def user_facing_error(error: BaseException | str, limit: int = 700) -> str:
    raw = str(error or "").replace("\r\n", "\n").strip()
    if not raw:
        return "未知错误"
    lowered = raw.lower()
    if (
        ("winerror 5" in lowered or "permission denied" in lowered or "拒绝访问" in raw)
        and "project.json" in lowered
    ):
        return "项目状态文件被 Windows 暂时占用，无法保存当前进度。已生成的图片仍会保留，请重新运行后继续补齐。"
    if "insufficient balance" in lowered or "error code: 402" in lowered:
        return "DeepSeek 账户余额不足，AI 总编与 AI 老师团暂时无法调用；已切换为本地规则检查。"
    if "rate limit" in lowered or "error code: 429" in lowered:
        return "DeepSeek 请求过于频繁或额度已用尽，请稍后重试；当前可继续使用本地规则检查。"
    if "target page, context or browser has been closed" in lowered:
        return "浏览器窗口已关闭或启动后意外退出，请确认没有手动关闭自动化窗口后重试。"
    if "executable doesn't exist" in lowered or "executable not found" in lowered:
        return "没有找到可用的 Chrome/Chromium 浏览器，请在配置页重新选择浏览器路径。"
    if "browser logs:" in lowered or "call log:" in lowered or "<launching>" in lowered:
        for marker in ("Browser logs:", "Call log:", "\n<launching>", "\n  - <launching>"):
            if marker in raw:
                raw = raw.split(marker, 1)[0].strip()
        if not raw:
            return "浏览器进程启动或关闭失败，底层调试日志已过滤，请重试。"
    lines: list[str] = []
    for line in raw.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith(("<launching>", "<launched>", "[pid=", "- [pid=", "--")):
            continue
        if "taskkill stderr:" in stripped or "temporary directories cleanup" in stripped or "gracefully close" in stripped:
            continue
        if stripped.count("�") >= 2:
            continue
        lines.append(stripped)
    message = " ".join(lines).strip()
    if not message:
        message = "浏览器进程返回了不可读的系统信息，已过滤乱码，请重试。"
    return message[: max(80, int(limit or 700))]


def sanitize_user_log_text(value: str) -> str:
    raw = str(value or "")
    if not raw:
        return ""
    lines = raw.replace("\r\n", "\n").splitlines()
    cleaned: list[str] = []
    skipping_browser_noise = False
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith(("Browser logs:", "Call log:", "<launching>", "<launched>", "- <launched>", "[pid=", "- [pid=", "features=")):
            skipping_browser_noise = True
            continue
        if "taskkill stderr:" in stripped or "temporary directories cleanup" in stripped or "gracefully close" in stripped:
            skipping_browser_noise = True
            continue
        is_app_line = stripped.startswith(("[job]", "[gate]", "[images]", "[covers]", "[audio]", "[subtitles]", "[video]", "[quality]", "[auto]", "[preflight]", "[director]", "[bgm]"))
        if skipping_browser_noise and not is_app_line:
            continue
        if is_app_line:
            skipping_browser_noise = False
        if "BrowserType." in stripped or "Target page, context or browser has been closed" in stripped:
            prefix, _, detail = stripped.partition("：")
            summary = user_facing_error(detail or stripped)
            cleaned.append(f"{prefix}：{summary}" if detail else summary)
            skipping_browser_noise = True
            continue
        if stripped.count("�") >= 2:
            continue
        cleaned.append(line.rstrip())
    return "\n".join(cleaned).strip()


def job_error_from_log(value: str) -> str:
    for raw_line in reversed(str(value or "").replace("\r\n", "\n").splitlines()):
        line = raw_line.strip()
        for marker in ("[job] 任务失败：", "[auto] 任务失败："):
            if line.startswith(marker):
                return user_facing_error(line[len(marker) :])
    return ""


def strip_image_prompt_workflow_rules(value: str) -> str:
    text = value or ""
    text = re.sub(
        r"每张图只服务当前(?:对应)?口播段落[，,；;。]?\s*"
        r"不把前一段的示例、名词或页面样式扩散到其它镜头[，,；;。]?",
        "",
        text,
    )
    text = re.sub(r"每张图只服务当前(?:对应)?口播段落[，,；;。]?", "", text)
    text = re.sub(r"不把前一段的示例、名词或页面样式扩散到其它镜头[，,；;。]?", "", text)
    return text


def truncate(value: str, limit: int = 220) -> str:
    value = clean_text(value)
    if len(value) <= limit:
        return value
    return value[: max(0, limit - 1)].rstrip() + "…"


def strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    match = re.match(r"^```(?:markdown|md|text)?\s*(.*?)\s*```$", text, re.DOTALL | re.IGNORECASE)
    if match:
        return match.group(1).strip()
    return text


def html_to_text(raw: str) -> str:
    text = HTML_TAG_RE.sub(" ", raw or "")
    text = html.unescape(text)
    return clean_text(text)


def extract_tokens(text: str) -> set[str]:
    tokens = {item.lower() for item in CHINESE_OR_WORD_RE.findall(text or "")}
    stop_words = {
        "为什么",
        "什么",
        "怎么",
        "如何",
        "关于",
        "以及",
        "今天",
        "最近",
        "最新",
        "topic",
        "brief",
        "video",
        "story",
        "content",
    }
    return {token for token in tokens if token not in stop_words}


def overlap_score(query_tokens: set[str], text: str) -> float:
    if not query_tokens:
        return 0.0
    haystack = clean_text(text).lower()
    matched = sum(1 for token in query_tokens if token in haystack)
    return matched / max(1, len(query_tokens))


def first_heading(content: str) -> str:
    for line in (content or "").splitlines():
        stripped = line.strip()
        if stripped.startswith("# "):
            heading = stripped[2:].strip()
            normalized = re.sub(r"[\s:：_-]+", "", heading).lower()
            if normalized in {
                "短标题",
                "标题",
                "视频标题",
                "封面标题",
                "请输入标题",
                "title",
                "shorttitle",
                "videotitle",
            }:
                continue
            return heading
    return ""


def extract_section(content: str, title: str, level: int = 2) -> str:
    hashes = "#" * level
    heading_breaks = "|".join(re.escape("#" * depth) for depth in range(1, level + 1))
    pattern = re.compile(
        rf"(?ms)^{re.escape(hashes)}[ \t]+{re.escape(title)}[^\r\n]*\r?\n(.*?)(?=^(?:{heading_breaks})[ \t]+|\Z)"
    )
    match = pattern.search(content or "")
    return match.group(1).strip() if match else ""


def extract_subsection(content: str, title: str) -> str:
    pattern = re.compile(
        rf"(?ms)^###[ \t]+{re.escape(title)}[^\r\n]*\r?\n(.*?)(?=^###[ \t]+|^##[ \t]+|\Z)"
    )
    match = pattern.search(content or "")
    return match.group(1).strip() if match else ""


def bullet_field_pattern(label: str) -> re.Pattern[str]:
    return re.compile(
        rf"(?m)^\s*[-*]\s*(?:\*\*)?\s*{re.escape(label)}\s*(?:\*\*)?\s*[：:]\s*(.+?)\s*$"
    )


def clean_bullet_value(value: str) -> str:
    cleaned = (value or "").strip()
    cleaned = re.sub(r"^\*\*\s*|\s*\*\*$", "", cleaned).strip()
    return clean_text(cleaned)


def extract_meta_field(content: str, label: str) -> str:
    meta = extract_section(content, "Meta", level=2)
    if not meta:
        return ""
    match = bullet_field_pattern(label).search(meta)
    return clean_bullet_value(match.group(1)) if match else ""


def extract_bullet_field(content: str, label: str) -> str:
    match = bullet_field_pattern(label).search(content or "")
    return clean_bullet_value(match.group(1)) if match else ""


def replace_section(content: str, title: str, body: str, level: int = 2) -> str:
    source = content or ""
    hashes = "#" * level
    heading_breaks = "|".join(re.escape("#" * depth) for depth in range(1, level + 1))
    pattern = re.compile(
        rf"(?ms)^{re.escape(hashes)}[ \t]+{re.escape(title)}[^\r\n]*\r?\n.*?(?=^(?:{heading_breaks})[ \t]+|\Z)"
    )
    replacement = f"{hashes} {title}\n\n{body.strip()}\n\n"
    if pattern.search(source):
        return pattern.sub(replacement, source, count=1)
    reference_match = re.search(r"(?m)^##[ \t]+参考资料[^\r\n]*\r?\n", source)
    if reference_match:
        head = source[: reference_match.start()].rstrip()
        tail = source[reference_match.start() :].lstrip()
        return f"{head}\n\n{replacement.rstrip()}\n\n{tail}"
    return f"{source.rstrip()}\n\n{replacement}".strip() + "\n"


def content_without_image_prompts(content: str) -> str:
    source = content or ""
    for title in ("图片提示词", "场景图提示词"):
        pattern = re.compile(rf"(?ms)^##[ \t]+{re.escape(title)}[^\r\n]*\r?\n.*?(?=^##[ \t]+|\Z)")
        source = pattern.sub("", source)
    return source.strip()


def content_for_editorial_quality(content: str) -> str:
    source = content_without_image_prompts(content)
    for title in ("参考资料", "资料来源"):
        pattern = re.compile(rf"(?ms)^##[ \t]+{re.escape(title)}[^\r\n]*\r?\n.*?(?=^##[ \t]+|\Z)")
        source = pattern.sub("", source)
    return source.strip()


