def clean_scene_spoken_text(text: str) -> str:
    """Keep spoken semantics while removing stage directions from scene context."""
    value = clean_text(str(text or ""))
    if not value:
        return ""
    value = strip_leading_stage_direction(value)
    value = re.sub(
        r"^[（(]([^）)]{1,120})[）)]\s*",
        lambda match: "" if _contains_any(match.group(1), SCENE_STAGE_DIRECTION_TERMS) else match.group(0),
        value,
    ).strip()
    if _contains_any(value[:90], SCENE_STAGE_DIRECTION_TERMS):
        spoken_markers = (
            "我让",
            "我本来",
            "你以为",
            "你花",
            "你买",
            "为什么",
            "真正",
            "先别",
            "你让",
            "你要",
            "所以",
            "其实",
            "但是",
            "最坑的是",
            "更隐蔽的是",
            "太天真了",
            "那我是不是",
            "AI最好的用法",
            "AI 最好的用法",
        )
        positions = [value.find(marker) for marker in spoken_markers if value.find(marker) >= 4]
        if positions:
            value = value[min(positions) :]
        else:
            stage_hits = sum(1 for term in SCENE_STAGE_DIRECTION_TERMS if term in value)
            has_spoken_signal = bool(re.search(r"\d", value) or _contains_any(value, SCENE_MEANINGFUL_SPEECH_TOKENS))
            if stage_hits >= 2 and not has_spoken_signal:
                return ""
    value = re.sub(r"(?<=[\u4e00-\u9fff])\s+(?=[\u4e00-\u9fff])", "", value)
    value = re.sub(r"(?<=\d)\s+(?=\d)", "", value)
    return clean_text(value).strip("，,。；;：: ")


def scene_audio_candidate_windows(group: list[dict[str, Any]], max_chars: int = 120) -> list[str]:
    pieces = [clean_scene_spoken_text(str(item.get("text", ""))) for item in group]
    pieces = [item for item in pieces if item and not looks_like_visual_direction(item)]
    candidates: list[str] = []
    for start in range(len(pieces)):
        combined = ""
        for end in range(start, min(len(pieces), start + 4)):
            combined = clean_text(f"{combined}{pieces[end]}")
            if len(combined) > max_chars:
                break
            if combined not in candidates:
                candidates.append(combined)
            if pieces[end].endswith(("。", "！", "？", "!", "?")) and len(combined) >= 12:
                break
    return candidates


def audio_anchor_completeness_score(text: str) -> int:
    value = clean_scene_spoken_text(text)
    if not value:
        return -20
    score = 3 if 18 <= len(value) <= 100 else 0
    if len(value) < 10 or len(value) > 125:
        score -= 4
    if value.endswith(("AI", "用 AI", "数据来", "关于", "的", "和", "与", "或", "但是", "因为", "所以", "然后", "如果", "而是", "比如")):
        score -= 6
    if "..." in value or "…" in value:
        score -= 3
    return score


def scene_audio_importance_score(text: str) -> int:
    value = clean_scene_spoken_text(text)
    if not value:
        return 0
    score = 18
    score += min(28, len(re.findall(r"\d+(?:\.\d+)?", value)) * 9)
    score += min(28, sum(5 for token in SCENE_MEANINGFUL_SPEECH_TOKENS if token in value))
    if _contains_any(value, ("但是", "结果", "反而", "真正", "最坑", "更隐蔽", "正确用法")):
        score += 12
    if re.search(r"[？?！!]", value):
        score += 5
    if _contains_any(value, SCENE_FILLER_SPEECH_TOKENS):
        score -= 18
    if _contains_any(value, ("评论区", "点赞", "关注", "转发")) and not re.search(r"\d", value):
        score -= 10
    return max(0, min(100, score))


def normalize_scene_fact_text(text: str) -> str:
    """Normalize common spoken numbers before comparing visual meaning."""
    value = clean_scene_spoken_text(text).lower()
    replacements = (
        ("四零零", "400"),
        ("九成三", "93%"),
        ("四成", "40%"),
        ("三天", "3天"),
    )
    for source, target in replacements:
        value = value.replace(source, target)
    return re.sub(r"[^a-z0-9%\u4e00-\u9fff]+", "", value)


def scene_anchor_fact_tokens(text: str) -> set[str]:
    value = clean_scene_spoken_text(text).lower()
    value = value.replace("四零零", "400").replace("九成三", "93%").replace("四成", "40%").replace("三天", "3天")
    return set(re.findall(r"\d+(?:\.\d+)?(?:\s*[×x]\s*\d+)?%?", value))


def scene_anchor_concept_keys(text: str) -> set[str]:
    value = normalize_scene_fact_text(text)
    keys: set[str] = set()
    closes_something = _contains_any(value, ("关掉", "关闭", "禁掉", "关干净", "远程关", "永久关闭"))
    if closes_something and _contains_any(value, ("客服", "电话", "400", "mac", "序列号")):
        keys.add("contact_resolution")
    if _contains_any(value, ("国家", "规定", "文件", "治理")) and _contains_any(value, ("广电", "监管", "规定", "文件")):
        keys.add("policy_evidence")
    if _contains_any(value, ("利润", "收入", "财报", "亏本")):
        keys.add("business_model")
    if _contains_any(value, ("优先", "选对", "全系无广告")) or ("品牌" in value and _contains_any(value, ("买", "选", "购买"))):
        keys.add("purchase_choice")
    if _contains_any(value, ("父母", "爸妈", "长辈")):
        keys.add("family_help")
    if "繁花" in value or ("电影" in value and _contains_any(value, ("时间", "等待", "省下", "看完"))):
        keys.add("time_cost")
    return keys


def scene_anchor_semantic_similarity(left: str, right: str) -> float:
    left_norm = normalize_scene_fact_text(left)
    right_norm = normalize_scene_fact_text(right)
    if not left_norm or not right_norm:
        return 0.0
    matcher = difflib.SequenceMatcher(None, left_norm, right_norm)
    ratio = matcher.ratio()
    longest = matcher.find_longest_match(0, len(left_norm), 0, len(right_norm)).size
    containment = longest / max(1, min(len(left_norm), len(right_norm)))
    left_units = _alignment_ngrams(left_norm)
    right_units = _alignment_ngrams(right_norm)
    union = left_units.union(right_units)
    jaccard = len(left_units.intersection(right_units)) / max(1, len(union))
    left_numbers = scene_anchor_fact_tokens(left)
    right_numbers = scene_anchor_fact_tokens(right)
    shared_numbers = left_numbers.intersection(right_numbers)
    number_bonus = 0.22 if shared_numbers else 0.0
    return min(1.0, max(ratio, containment * 0.9, jaccard + number_bonus))


def scene_anchors_are_duplicate(left: str, right: str) -> bool:
    left_norm = normalize_scene_fact_text(left)
    right_norm = normalize_scene_fact_text(right)
    if not left_norm or not right_norm:
        return False
    similarity = scene_anchor_semantic_similarity(left, right)
    if similarity >= 0.72:
        return True
    left_numbers = scene_anchor_fact_tokens(left)
    right_numbers = scene_anchor_fact_tokens(right)
    shared_numbers = left_numbers.intersection(right_numbers)
    shared_concepts = scene_anchor_concept_keys(left).intersection(scene_anchor_concept_keys(right))
    if shared_concepts.intersection({"contact_resolution", "policy_evidence", "time_cost"}):
        return True
    if shared_concepts and (similarity >= 0.08 or shared_numbers):
        return True
    if shared_numbers and similarity >= 0.20:
        return True
    shared_terms = {
        token
        for token in (
            "mac",
            "dns",
            "客服",
            "打",
            "关闭",
            "关掉",
            "开机广告",
            "广告屏",
            "繁花",
            "利润",
            "文件",
            "品牌",
            "父母",
            "长辈",
        )
        if token in left_norm and token in right_norm
    }
    return bool(shared_numbers and shared_terms and similarity >= 0.27)


def semantic_scene_beat_candidates(utterances: list[dict[str, Any]]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for index, item in enumerate(utterances):
        text = clean_scene_spoken_text(str(item.get("text", "")))
        if not text or looks_like_visual_direction(text):
            continue
        parts = [text]
        if index + 1 < len(utterances) and (len(text) < 8 or text.endswith(("就", "和", "与", "或", "的", "为", "是", "到", "了", "有线网卡"))):
            following = clean_scene_spoken_text(str(utterances[index + 1].get("text", "")))
            if following and not looks_like_visual_direction(following):
                parts.append(following)
        anchor = clean_scene_spoken_text("".join(parts))[:110]
        score = scene_audio_importance_score(anchor) + audio_anchor_completeness_score(anchor)
        if re.search(r"\d", normalize_scene_fact_text(anchor)):
            score += 12
        if _contains_any(anchor, ("怎么关", "第一步", "第二步", "第三步", "客服", "MAC", "利润", "文件", "优先", "父母", "长辈")):
            score += 9
        if _contains_any(anchor, ("评论区", "点赞", "关注", "转发", "打个样")):
            score -= 36
        if _contains_any(anchor, SCENE_FILLER_SPEECH_TOKENS):
            score -= 24
        candidates.append(
            {
                "utterance_index": index,
                "start_ms": int(item.get("start_ms", 0) or 0),
                "end_ms": int(item.get("end_ms", item.get("start_ms", 0)) or 0),
                "text": anchor,
                "score": max(0, min(120, score)),
            }
        )
    return candidates


def select_semantic_scene_beats(
    utterances: list[dict[str, Any]],
    requested_count: int,
    audio_duration_ms: int | None = None,
) -> list[dict[str, Any]]:
    requested = max(1, int(requested_count or 1))
    candidates = semantic_scene_beat_candidates(utterances)
    if not candidates:
        return []
    duration_ms = max(
        1,
        int(audio_duration_ms or 0),
        max((int(item.get("end_ms", 0) or 0) for item in utterances), default=1),
    )
    selected: list[dict[str, Any]] = []
    slot_ms = duration_ms / requested

    # A visual beat is both a semantic choice and a pacing boundary. Picking
    # the globally highest-scoring lines can cluster several beats together
    # and leave one still image on screen for 30+ seconds. Select the strongest
    # usable line near each temporal boundary, then use semantic novelty as a
    # preference inside that local window.
    for slot_index in range(requested):
        target_ms = slot_index * slot_ms
        lower_ms = 0 if slot_index == 0 else target_ms - slot_ms * 0.48
        upper_ms = duration_ms if slot_index == requested - 1 else target_ms + slot_ms * 0.58
        local = [
            item
            for item in candidates
            if item not in selected
            and lower_ms <= int(item.get("start_ms", 0) or 0) <= upper_ms
        ]
        if not local:
            local = [item for item in candidates if item not in selected]
        if not local:
            break

        novel = [
            item
            for item in local
            if not any(
                scene_anchors_are_duplicate(str(item.get("text", "")), str(chosen.get("text", "")))
                for chosen in selected
            )
        ]
        if not novel:
            novel = [
                item
                for item in candidates
                if item not in selected
                and not any(
                    scene_anchors_are_duplicate(str(item.get("text", "")), str(chosen.get("text", "")))
                    for chosen in selected
                )
            ]
        if not novel:
            break
        pool = novel

        def boundary_rank(item: dict[str, Any]) -> tuple[float, int, float]:
            start_ms = int(item.get("start_ms", 0) or 0)
            distance_penalty = abs(start_ms - target_ms) / max(1.0, slot_ms) * 34.0
            score = float(item.get("score", 0) or 0) - distance_penalty
            if slot_index == 0:
                score -= start_ms / max(1.0, slot_ms) * 18.0
            return (score, int(item.get("score", 0) or 0), -abs(start_ms - target_ms))

        selected.append(max(pool, key=boundary_rank))

    return sorted(selected, key=lambda item: int(item.get("utterance_index", 0) or 0))


def suggest_semantic_key_image_count(
    utterances: list[dict[str, Any]],
    requested_count: int,
    audio_duration_ms: int,
) -> dict[str, Any]:
    requested = max(1, int(requested_count or 1))
    candidates = semantic_scene_beat_candidates(utterances)
    selected = select_semantic_scene_beats(utterances, requested, audio_duration_ms)
    duration_floor = max(1, int(math.ceil(max(1, audio_duration_ms) / 32_000.0)))
    minimum, _maximum = scene_count_range_for_audio(audio_duration_ms)
    semantic_count = len(selected)
    # Semantic selection removes duplicate or filler visuals, but it must not
    # collapse a normal-length episode below the channel's watchable pacing
    # floor. Caption beats still carry the smaller information changes.
    final = min(requested, max(minimum, semantic_count or 1))
    return {
        "requested": requested,
        "final": max(1, final),
        "semantic_count": semantic_count,
        "duration_floor": duration_floor,
        "important_beats": selected,
        "candidate_beats": sorted(candidates, key=lambda item: int(item.get("score", 0) or 0), reverse=True)[:12],
    }


def scene_prompt_audio_anchor(prompt: str) -> str:
    text = clean_text(prompt)
    if not text:
        return ""
    anchor = extract_labeled_prompt_value(text, "口播原文", 120)
    if anchor:
        return anchor
    match = re.search(r"口播原文\s*[：:]\s*[「“\"']?(.{2,120}?)(?:[」”\"']|，(?:主体|动作|冲突|镜头)|。(?:主体|动作|冲突|镜头)|$)", text)
    return clean_text(match.group(1)) if match else summarize_scene_text(text, 120)


def scene_prompt_meaning_score(prompt: str) -> int:
    anchor = scene_prompt_audio_anchor(prompt)
    if not anchor:
        return 0
    score = 2
    score += min(8, len(re.findall(r"\d+(?:\.\d+)?(?:%|元|块|万|亿|年|家|款|个|倍)?", anchor)) * 4)
    score += min(8, sum(2 for token in SCENE_MEANINGFUL_SPEECH_TOKENS if token in anchor))
    if re.search(r"[？?！!]", anchor):
        score += 1
    if any(token in anchor for token in SCENE_FILLER_SPEECH_TOKENS):
        score -= 7
    if _contains_any(anchor, ("评论区", "点赞", "关注", "转发")) and not re.search(r"\d", anchor):
        score -= 3
    return score


def _alignment_ngrams(text: str, size: int = 2) -> set[str]:
    compact = re.sub(r"[^A-Za-z0-9\u4e00-\u9fff]+", "", clean_text(text)).lower()
    if not compact:
        return set()
    if len(compact) <= size:
        return {compact}
    return {compact[index : index + size] for index in range(len(compact) - size + 1)}


def scene_audio_alignment_score(prompt: str, speech: str) -> int:
    anchor = scene_prompt_audio_anchor(prompt)
    anchor_units = _alignment_ngrams(anchor)
    speech_units = _alignment_ngrams(speech)
    if not anchor_units or not speech_units:
        return 0
    overlap = len(anchor_units.intersection(speech_units))
    score = round(overlap / max(1, len(anchor_units)) * 100)
    anchor_numbers = set(re.findall(r"\d+(?:\.\d+)?", anchor))
    speech_numbers = set(re.findall(r"\d+(?:\.\d+)?", speech))
    if anchor_numbers and anchor_numbers.intersection(speech_numbers):
        score += 18
    return min(118, score)


def select_key_audio_anchor(group: list[dict[str, Any]], prompt: str) -> str:
    candidates = scene_audio_candidate_windows(group)
    if not candidates:
        return ""

    def rank(item: str) -> tuple[int, int, int, int]:
        alignment = scene_audio_alignment_score(prompt, item)
        meaning = scene_prompt_meaning_score(f"口播原文：{item}")
        has_fact = int(bool(re.search(r"\d", item) or any(token in item for token in SCENE_MEANINGFUL_SPEECH_TOKENS)))
        completeness = audio_anchor_completeness_score(item)
        length_preference = -abs(len(item) - 52)
        return (meaning + has_fact * 3 + completeness, int(alignment >= 35), alignment, length_preference)

    return clean_scene_spoken_text(max(candidates, key=rank))


def complete_asr_split_anchor(anchor: str, group: list[dict[str, Any]], max_chars: int = 120) -> str:
    """Join subtitle chunks when ASR timing splits a Chinese word in half."""
    current = clean_scene_spoken_text(anchor)
    if not current or not group:
        return current
    split_words = (
        "这波", "知识储备", "总参数", "激活参数", "响应速度", "上下文窗口",
        "价格战", "高难度", "全勤旗舰", "按需醒来", "复杂推理", "轻量款",
    )
    pieces = [clean_scene_spoken_text(str(item.get("text", ""))) for item in group]
    pieces = [item for item in pieces if item]
    for index, piece in enumerate(pieces[:-1]):
        if piece not in current and current not in piece:
            continue
        following = pieces[index + 1]
        crosses_boundary = any(
            any(
                piece.endswith(word[:cut]) and following.startswith(word[cut:])
                for cut in range(1, len(word))
            )
            for word in split_words
        )
        if not crosses_boundary:
            continue
        joined = clean_text(f"{current}{following}")
        cursor = index + 2
        # Add one neighbouring clause after the repaired word.  More would
        # swallow the next semantic beat merely because ASR omitted punctuation.
        if cursor < len(pieces) and len(joined) + len(pieces[cursor]) <= max_chars:
            joined = clean_text(f"{joined}{pieces[cursor]}")
        return clean_scene_spoken_text(joined)
    return current


def aligned_authored_audio_anchor(prompt: str, group_text: str) -> str:
    anchor = clean_scene_spoken_text(scene_prompt_audio_anchor(prompt))
    if not anchor or not group_text:
        return ""
    if anchor.rstrip().endswith(("—", "-", "：", ":")):
        return ""
    if any(
        token in anchor
        for token in (
            "口播原文只用于",
            "视觉钩子",
            "信息牌",
            "对应概念",
            "当前口播提炼",
            "不套用其它主题",
        )
    ):
        return ""
    if scene_prompt_meaning_score(f"口播原文：{anchor}") <= 2 and not re.search(r"\d", anchor):
        return ""
    score = scene_audio_alignment_score(f"口播原文：{anchor}", group_text)
    return anchor if score >= 35 and audio_anchor_completeness_score(anchor) >= 0 else ""


def actionable_audio_anchor(text: str) -> str:
    source = clean_scene_spoken_text(text)
    if not source:
        return ""
    priority_tokens = (
        "AI 最好的用法",
        "AI最好的用法",
        "帮你出草稿",
        "只出草稿",
        "列大纲",
        "关键的一段",
        "自己动手",
        "不要直接粘贴",
        "用自己的话",
        "认准",
        "优先选",
        "正确做法",
    )
    for token in priority_tokens:
        position = source.find(token)
        if position < 0:
            continue
        start = max(0, position - 18)
        excerpt = source[start : position + 88]
        return clean_scene_spoken_text(excerpt[:88])
    return ""


def align_scene_prompts_to_utterances(utterances: list[dict[str, Any]], scene_lines: list[str]) -> list[int]:
    if not utterances or not scene_lines:
        return []
    prompt_count = min(len(scene_lines), len(utterances))
    utterance_count = len(utterances)
    starts: list[int] = [0]
    previous = 0
    for prompt_index in range(1, prompt_count):
        remaining = prompt_count - prompt_index - 1
        lower = previous + 1
        upper = max(lower, utterance_count - remaining - 1)
        expected = round(prompt_index * (utterance_count - 1) / max(1, prompt_count - 1))
        best_index = max(lower, min(upper, expected))
        best_rank: tuple[float, float] = (-1.0, float("-inf"))
        for utterance_index in range(lower, upper + 1):
            window_text = " ".join(
                clean_text(str(item.get("text", "")))
                for item in utterances[utterance_index : min(utterance_count, utterance_index + 3)]
            )
            score = scene_audio_alignment_score(scene_lines[prompt_index], window_text)
            rank = (float(score), -abs(utterance_index - expected) * 0.35)
            if rank > best_rank:
                best_rank = rank
                best_index = utterance_index
        starts.append(best_index)
        previous = best_index
    return starts


def utterance_text_for_window(utterances: list[dict[str, Any]], start_ms: int, end_ms: int) -> str:
    parts: list[str] = []
    for item in utterances:
        item_start = int(item.get("start_ms", 0) or 0)
        item_end = int(item.get("end_ms", item_start) or item_start)
        if item_end <= start_ms or item_start >= end_ms:
            continue
        text = clean_text(str(item.get("text", "")))
        if text:
            parts.append(text)
    return " ".join(parts).strip()


def build_scene_timeline_for_scene_count(
    utterances: list[dict[str, Any]],
    scene_lines: list[str],
    scene_count: int,
    audio_duration_ms: int,
) -> dict[str, Any]:
    desired_count = max(1, int(scene_count or len(scene_lines) or 1))
    body_ms = max(
        desired_count * 900,
        int(audio_duration_ms or 0),
        max((int(item.get("end_ms", 0) or 0) for item in utterances), default=0),
    )
    selected_beats = select_semantic_scene_beats(utterances, desired_count, body_ms)
    if selected_beats:
        used_indices = {int(item.get("utterance_index", -1) or -1) for item in selected_beats}
        while len(selected_beats) < desired_count and len(used_indices) < len(utterances):
            target_ms = len(selected_beats) * body_ms / desired_count
            available = [
                (index, item)
                for index, item in enumerate(utterances)
                if index not in used_indices
                and clean_scene_spoken_text(str(item.get("text", "")))
                and not looks_like_visual_direction(str(item.get("text", "")))
            ]
            if not available:
                break
            utterance_index, utterance = min(
                available,
                key=lambda pair: abs(int(pair[1].get("start_ms", 0) or 0) - target_ms),
            )
            selected_beats.append(
                {
                    "utterance_index": utterance_index,
                    "start_ms": int(utterance.get("start_ms", 0) or 0),
                    "end_ms": int(utterance.get("end_ms", utterance.get("start_ms", 0)) or 0),
                    "text": clean_scene_spoken_text(str(utterance.get("text", ""))),
                    "score": scene_audio_importance_score(str(utterance.get("text", ""))),
                }
            )
            used_indices.add(utterance_index)
        selected_beats = sorted(
            selected_beats[:desired_count],
            key=lambda item: int(item.get("utterance_index", 0) or 0),
        )
    else:
        selected_beats = [
            {
                "utterance_index": round(index * max(0, len(utterances) - 1) / max(1, desired_count - 1)),
                "start_ms": round(index * body_ms / desired_count),
                "text": "",
                "score": 0,
            }
            for index in range(desired_count)
        ]
    prompts = normalize_scene_prompt_count(scene_lines, desired_count, "", "video")
    boundary_indices: list[int] = [0]
    if utterances:
        slot_ms = body_ms / desired_count
        for index in range(1, desired_count):
            target_ms = index * slot_ms
            lower_ms = target_ms - slot_ms * 0.40
            upper_ms = target_ms + slot_ms * 0.40
            remaining_boundaries = desired_count - index - 1
            lower_index = boundary_indices[-1] + 1
            upper_index = max(lower_index, len(utterances) - remaining_boundaries - 1)
            suggested_index = int(selected_beats[index].get("utterance_index", lower_index) or lower_index)
            suggested_index = max(lower_index, min(upper_index, suggested_index))
            suggested_start = int(utterances[suggested_index].get("start_ms", 0) or 0)
            if lower_ms <= suggested_start <= upper_ms:
                boundary_indices.append(suggested_index)
                continue
            local_boundaries = [
                candidate_index
                for candidate_index in range(lower_index, upper_index + 1)
                if lower_ms
                <= int(utterances[candidate_index].get("start_ms", 0) or 0)
                <= upper_ms
            ]
            candidates_for_boundary = local_boundaries or list(range(lower_index, upper_index + 1))
            boundary_indices.append(
                min(
                    candidates_for_boundary,
                    key=lambda candidate_index: abs(
                        int(utterances[candidate_index].get("start_ms", 0) or 0) - target_ms
                    ),
                )
            )
    scenes: list[dict[str, Any]] = []
    for index in range(desired_count):
        start_utterance_index = boundary_indices[index] if index < len(boundary_indices) else 0
        next_utterance_index = boundary_indices[index + 1] if index + 1 < len(boundary_indices) else len(utterances)
        if index == 0:
            body_start = 0
        elif 0 <= start_utterance_index < len(utterances):
            body_start = int(utterances[start_utterance_index].get("start_ms", 0) or 0)
        else:
            body_start = round(index * body_ms / desired_count)
        if 0 <= next_utterance_index < len(utterances):
            body_end = int(utterances[next_utterance_index].get("start_ms", body_ms) or body_ms)
        else:
            body_end = body_ms
        body_end = max(body_start + 1, body_end)
        group = utterances[start_utterance_index:next_utterance_index]
        group_text = clean_scene_spoken_text(
            " ".join(clean_text(str(item.get("text", ""))) for item in group if clean_text(str(item.get("text", ""))))
        )
        group_beats = [
            item
            for item in selected_beats
            if start_utterance_index
            <= int(item.get("utterance_index", -1) or -1)
            < next_utterance_index
        ]
        beat = max(group_beats, key=lambda item: int(item.get("score", 0) or 0)) if group_beats else {
            "text": select_key_audio_anchor(group, ""),
            "score": 0,
        }
        prompt = prompts[index] if index < len(prompts) else aligned_scene_prompt(scene_lines, index, desired_count, group_text)
        scene_start = TIMELINE_COVER_MS + int(body_start)
        scene_end = max(scene_start + 1, TIMELINE_COVER_MS + int(body_end))
        # The selected subtitle beat is authoritative. Cached prompts may help
        # with composition, but they must never move a scene back to an old fact.
        audio_anchor = clean_scene_spoken_text(str(beat.get("text", "")))
        if not audio_anchor:
            audio_anchor = select_key_audio_anchor(group, prompt) or clean_scene_spoken_text(scene_prompt_audio_anchor(prompt))
        else:
            audio_anchor = complete_asr_split_anchor(audio_anchor, group)
            expanded_anchor = select_key_audio_anchor(group, prompt)
            if (
                expanded_anchor
                and audio_anchor in expanded_anchor
                and len(audio_anchor) < len(expanded_anchor) <= 120
                and audio_anchor_completeness_score(expanded_anchor) >= audio_anchor_completeness_score(audio_anchor)
            ):
                # ASR frequently cuts at timing boundaries inside a phrase
                # (for example "这" + "波压价" or "知识储" + "备比").
                # Expand from adjacent subtitle entries without changing the
                # selected semantic beat so image prompts receive a full fact.
                audio_anchor = expanded_anchor
        authored_anchor = aligned_authored_audio_anchor(prompt, group_text)
        authored_limit = min(72, len(audio_anchor) + 18)
        if authored_anchor and len(authored_anchor) <= authored_limit and not re.search(r"[「」\"“”]{2,}", authored_anchor) and scene_anchor_semantic_similarity(authored_anchor, audio_anchor) >= 0.45:
            audio_anchor = authored_anchor
        importance = int(beat.get("score", 0) or scene_audio_importance_score(audio_anchor))
        scenes.append(
            {
                "index": index + 1,
                "start_ms": scene_start,
                "end_ms": scene_end,
                "prompt": prompt,
                "text": group_text or prompt,
                "audio_anchor": audio_anchor,
                "importance_score": importance,
                "key_image_reason": "全片唯一关键视觉节点",
                "alignment_score": scene_audio_alignment_score(prompt, group_text),
                "cut_reason": "semantic_key_beat",
                "semantic_anchor_hash": hashlib.sha256(normalize_scene_fact_text(audio_anchor).encode("utf-8")).hexdigest()[:12],
            }
        )

    minimum, maximum = scene_count_range_for_audio(body_ms)
    target = suggest_scene_count(body_ms, desired_count)["target"]
    return {
        "cover_duration_ms": TIMELINE_COVER_MS,
        "audio_duration_ms": max(TIMELINE_COVER_MS + body_ms + TIMELINE_OUTRO_MS, 9000),
        "outro_duration_ms": TIMELINE_OUTRO_MS,
        "candidate_scene_count": len(scene_lines),
        "scene_count_range": {"min": minimum, "max": maximum},
        "target_scene_count": target,
        "final_scene_count": len(scenes),
        "scenes": scenes,
        "repair": {
            "forced_scene_count": desired_count,
            "generated_at": storage.now_ts(),
            "source": "subtitles.srt global semantic key beats + current scene prompts",
            "selection_policy": "temporal_semantic_balance_v2",
        },
    }


def narrative_state_for_scene(index: int, total: int) -> str:
    if total <= 1:
        return "核心观点"
    position = (index - 1) / max(1, total - 1)
    if index == 1:
        return "前三秒钩子/痛点"
    if position < 0.25:
        return "背景铺垫"
    if position < 0.5:
        return "冲突或误区"
    if position < 0.75:
        return "机制拆解/证据"
    if index == total:
        return "结论回扣/互动"
    return "应用场景"


def infer_visual_type(prompt: str, text: str) -> str:
    source = f"{prompt}\n{text}"
    if any(token in source for token in ("时间轴", "过去", "现在", "未来", "年份")) or ("三段" in source and "阶段" in source):
        return "timeline"
    if any(token in source for token in ("对比", "vs", "VS", "左栏", "右栏", "三栏")):
        return "comparison"
    life_tokens = ("真实空间", "客厅", "沙发", "饭桌", "书桌", "家人", "长辈", "爸妈", "人物", "表情", "手部", "手机", "账单", "扣费短信")
    diagram_tokens = ("架构图", "流程图", "链路图", "机制图", "关系图", "系统图", "节点图", "因果链图")
    if any(token in source for token in life_tokens) and not any(token in source for token in diagram_tokens):
        return "life_scene"
    if any(token in source for token in ("架构图", "流程图", "链路图", "机制图", "关系图", "系统图", "因果链", "连接线", "节点")):
        return "mechanism_diagram"
    if any(token in source for token in ("数据", "增长", "比例", "市场", "趋势")):
        return "data_card"
    if any(token in source for token in ("客厅", "家庭", "场景", "人物", "手机", "房间")):
        return "life_scene"
    return "editorial_collage"


def scene_motion_for_type(visual_type: str, index: int) -> str:
    motions = {
        "timeline": "slow_pan_top_to_bottom",
        "comparison": "slow_pan_left_to_right",
        "mechanism_diagram": "gentle_push_in",
        "data_card": "micro_zoom_then_hold",
        "life_scene": "slow_push_in",
        "editorial_collage": "ken_burns_subtle",
    }
    if index == 1:
        return "quick_push_in"
    return motions.get(visual_type, "ken_burns_subtle")


def scene_material_hint(visual_type: str) -> str:
    hints = {
        "timeline": "AI 图，必要时叠加后期字幕解释节点",
        "comparison": "AI 图或后期分屏卡片",
        "mechanism_diagram": "AI 图优先，复杂结构可后期叠加图标",
        "data_card": "后期图表卡片优先，AI 图只做背景",
        "life_scene": "可混合真实素材或 AI 图",
        "editorial_collage": "AI 图",
    }
    return hints.get(visual_type, "AI 图")


def scene_transition_for_index(index: int, total: int, visual_type: str) -> str:
    if index == 1:
        return "hard_cut_from_cover"
    if index == total:
        return "soft_fade_to_end"
    if visual_type in {"timeline", "mechanism_diagram"}:
        return "match_cut_or_push"
    return "crossfade_8_frames"


def compact_prompt_speech_anchor(text: str, limit: int = 180) -> str:
    cleaned = clean_text(text)
    if not cleaned:
        return ""
    cleaned = re.sub(r"^【[^】]{1,12}】", "", cleaned).strip()
    cleaned = re.sub(r"\s+", " ", cleaned)
    if len(cleaned) <= limit:
        return cleaned
    pieces = re.split(r"(?<=[。！？!?])", cleaned)
    selected = ""
    for piece in pieces:
        piece = piece.strip()
        if not piece:
            continue
        if len(selected) + len(piece) > limit:
            break
        selected += piece
        if len(selected) >= 60:
            break
    if selected:
        return selected.strip()
    return cleaned[:limit].rstrip("，,。；;：: ") + "…"


def ensure_prompt_contains_speech_anchor(prompt: str, speech: str, *, purpose: str) -> str:
    text = normalize_image_prompt(prompt)
    if purpose == "cover" or not text:
        return text
    anchor = compact_prompt_speech_anchor(speech, 180)
    if not anchor:
        return text
    text = re.sub(
        r"^(?:本镜)?口播原文\s*[:：]?\s*「.*?」[。.]?\s*(?:口播原文只用于决定画面，不要把整句文字画进图里[。.]?|口播是画面内容和画面文字的主要语义来源.*?不必完整照抄口播[。.]?)?",
        "",
        text,
        count=1,
    ).strip(" 。")
    prefix = (
        f"本镜口播原文：「{anchor}」。"
        "口播是画面内容和画面文字的主要语义来源，AI 可以自行提炼、改写和组合其中的标题、数字、对比词、批注与说明关系，文字数量、字数和形式不设上限，不必完整照抄口播"
    )
    return compact_visual_image_prompt("。".join([prefix, text]), 900)


