def scene_specific_image_prompt(
    *,
    topic: str,
    speech_text: str,
    source_prompt: str,
    visual_scene: dict[str, Any],
    visual_world: str,
    narrative: str,
    visual_type: str,
    viewpoint: str,
    style_hint: str,
    scene_index: int = 1,
    total_scenes: int = 1,
) -> str:
    speech_quote = compact_prompt_speech_anchor(speech_text or clean_text(str(visual_scene.get("dialogue_anchor") or "")) or source_prompt, 180)
    speech_anchor = summarize_scene_text(speech_quote or speech_text or clean_text(str(visual_scene.get("dialogue_anchor") or "")) or source_prompt, 82)
    beat = summarize_scene_text(clean_text(str(visual_scene.get("beat") or "")) or source_prompt or speech_anchor, 92)
    blueprint = audio_bound_visual_blueprint(speech_quote or speech_anchor, topic)
    # The visual director has already translated the narration into a concrete
    # shot.  Keep that decision ahead of the generic semantic blueprint;
    # otherwise every topic collapses back to "a person using a device".
    subjects = [
        clean_visual_brief_fragment(item, 34)
        for item in (visual_scene.get("primary_subjects") if isinstance(visual_scene.get("primary_subjects"), list) else [])
        if clean_visual_brief_fragment(item, 34)
    ] or [
        clean_visual_brief_fragment(item, 42)
        for item in blueprint.get("subjects", [])
        if clean_visual_brief_fragment(item, 42)
    ]
    action = clean_visual_brief_fragment(visual_scene.get("action_peak"), 64) or clean_visual_brief_fragment(blueprint.get("action"), 64)
    tension = clean_visual_brief_fragment(visual_scene.get("tension"), 64) or clean_visual_brief_fragment(blueprint.get("tension"), 64)
    evidence = clean_visual_brief_fragment(blueprint.get("evidence"), 64)
    hooks = [
        clean_visual_brief_fragment(item, 12)
        for item in (visual_scene.get("attention_hooks") if isinstance(visual_scene.get("attention_hooks"), list) else [])
        if clean_visual_brief_fragment(item, 12)
    ]
    if not hooks:
        hooks = visual_callout_candidates(f"{speech_anchor} {source_prompt}", limit=4)
    if not subjects:
        subjects = [item for item in visual_decision_anchor_terms(f"{speech_anchor} {source_prompt}", {"attention_hooks": hooks}, limit=5) if item not in hooks][:3]
    if not action:
        action = summarize_scene_text(concrete_visual_hint_from_anchor(speech_anchor or source_prompt, source_prompt, "scene"), 54)
    if not tension:
        tension = infer_visual_tension(f"{speech_anchor} {source_prompt}", style_hint, visual_type, "scene")

    subject_text = "、".join(subjects[:3]) or "当前口播里的关键人物、手机屏幕或残留文件"
    world = clean_visual_brief_fragment(visual_world, 52)
    task_clause = f"画面任务：{beat}"
    if beat and speech_quote and token_overlap_score(beat, speech_quote, limit=40) >= 80:
        task_clause = ""
    parts = [
        f"主题：{topic}",
        f"口播原文：「{speech_quote or speech_anchor}」",
        task_clause,
        f"主主体：{subject_text}",
        f"动作：{action}",
        f"冲突/悬念：{summarize_scene_text(tension, 54)}",
        f"证据信息：{evidence}" if evidence else "",
        f"镜头视角：{viewpoint}",
        scene_variety_directive(scene_index, total_scenes, narrative, visual_type),
        scene_text_overlay_policy(narrative, visual_type, hooks),
    ]
    if world:
        parts.append(f"频道质感：{world}")
    if style_hint:
        parts.append(f"影像质感：{summarize_scene_text(style_hint, 42)}")
    parts.extend(extract_source_information_prompt_clauses(source_prompt))
    parts.extend(
        [
            "画面内容必须能追溯到当前口播的对象、动作、事实或关系",
            "人物、物件、文字、图表、批注和界面的使用方式均由当前口播、来源支撑信息与视觉概念共同决定",
        ]
    )
    return compact_visual_image_prompt("。".join(dedupe_clauses([item for item in parts if clean_text(item)])), 760).replace("...", "").replace("…", "")


def visual_director_scene_concept(visual_scene: dict[str, Any]) -> str:
    if not isinstance(visual_scene, dict) or not visual_scene:
        return ""
    subjects: list[str] = []
    for item in visual_scene.get("primary_subjects", []):
        raw = clean_text(str(item))
        if not raw or raw.endswith(("...", "…")):
            continue
        cleaned = clean_visual_brief_fragment(raw, 52)
        if cleaned:
            subjects.append(cleaned)
    parts = [
        f"核心画面：{clean_visual_brief_fragment(visual_scene.get('beat'), 88)}",
        f"证据主体：{'、'.join(subjects[:3])}" if subjects else "",
        f"正在发生：{clean_visual_brief_fragment(visual_scene.get('action_peak'), 64)}",
        f"冲突悬念：{clean_visual_brief_fragment(visual_scene.get('tension'), 72)}",
    ]
    return compact_visual_concept("；".join(item for item in parts if clean_text(item)), 280)


def rebind_scene_prompt_to_audio(
    topic: str,
    source_prompt: str,
    audio_anchor: str,
    speech_text: str,
    minimum_alignment: int = 24,
) -> tuple[str, int, bool]:
    final_speech = clean_scene_spoken_text(audio_anchor or speech_text)
    source = clean_text(source_prompt)
    if not final_speech or not source:
        return source, 0, False
    alignment = scene_audio_alignment_score(source, final_speech)
    if alignment >= minimum_alignment:
        return source, alignment, False
    rebound = audio_bound_semantic_scene_prompt(topic, final_speech, anchor=final_speech)
    return rebound or source, alignment, bool(rebound)


def build_scene_plan(
    project: dict[str, Any],
    content: str,
    timeline: dict[str, Any],
    scene_lines: list[str],
    visual_brief: dict[str, Any] | None = None,
    visual_director: dict[str, Any] | None = None,
) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or "video")
    episode_topic = clean_text(first_heading(content) or project.get("topic_name") or "本期主题")
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    scenes_raw = timeline.get("scenes") if isinstance(timeline, dict) else []
    scenes_raw = scenes_raw if isinstance(scenes_raw, list) else []
    summary = summarize_content(content, mode)
    total = len(scenes_raw)
    timeline_beats = [
        clean_text(str(item.get("prompt") or item.get("text") or ""))
        for item in scenes_raw
        if isinstance(item, dict)
    ]
    if visual_brief is None:
        visual_brief = get_or_create_visual_brief(project, template, content, scene_count=total or len(scene_lines), beats=timeline_beats or scene_lines)
    if visual_director is None:
        visual_director = get_or_create_visual_director(project, template, content, visual_brief)
    edit_direction = visual_director.get("edit_direction") if isinstance(visual_director.get("edit_direction"), dict) else {}
    sound_direction = visual_director.get("sound_direction") if isinstance(visual_director.get("sound_direction"), dict) else {}
    director_scenes = edit_direction.get("scenes") if isinstance(edit_direction.get("scenes"), list) else []
    scenes: list[dict[str, Any]] = []

    for idx, item in enumerate(scenes_raw, start=1):
        if not isinstance(item, dict):
            continue
        source_prompt = clean_text(str(item.get("prompt") or ""))
        speech_text = clean_scene_spoken_text(str(item.get("text") or ""))
        audio_anchor = clean_scene_spoken_text(str(item.get("audio_anchor") or ""))
        if not source_prompt and idx <= len(scene_lines):
            source_prompt = clean_text(scene_lines[idx - 1])
        source_prompt, prompt_audio_alignment, prompt_rebound = rebind_scene_prompt_to_audio(
            episode_topic,
            source_prompt,
            audio_anchor,
            speech_text,
        )
        visual_type = infer_visual_type(source_prompt, speech_text)
        director_seed = visual_director_scene_seed(visual_brief, idx)
        visual_anchor = composer_scene_prompt(source_prompt or speech_text or director_seed)
        visual_scene = visual_brief.get("scenes", [])[idx - 1] if idx - 1 < len(visual_brief.get("scenes", [])) else {}
        if not isinstance(visual_scene, dict):
            visual_scene = {}
        visual_dialogue = clean_text(str(visual_scene.get("dialogue_anchor") or ""))
        final_speech = audio_anchor or speech_text
        visual_audio_alignment = (
            scene_audio_alignment_score(f"口播原文：{visual_dialogue}", final_speech)
            if visual_dialogue and final_speech
            else 0
        )
        visual_rebound = bool(
            visual_dialogue
            and final_speech
            and visual_audio_alignment < 24
        )
        if visual_rebound:
            visual_scene = {}
        director_scene = director_scenes[idx - 1] if idx - 1 < len(director_scenes) and isinstance(director_scenes[idx - 1], dict) else {}
        image_prompt = scene_specific_image_prompt(
            topic=episode_topic,
            speech_text=audio_anchor or speech_text,
            source_prompt=source_prompt or visual_anchor or director_seed,
            visual_scene=visual_scene,
            visual_world=clean_text(str(visual_brief.get("visual_world") or "")),
            narrative=narrative_state_for_scene(idx, total),
            visual_type=visual_type,
            viewpoint=scene_viewpoint_hint(idx, total, visual_type),
            style_hint=content_scene_style_hint(classify_material_style(source_prompt or speech_text or visual_anchor, template, "scene"), template),
            scene_index=idx,
            total_scenes=total,
        )
        start_ms = int(item.get("start_ms", 0) or 0)
        end_ms = int(item.get("end_ms", start_ms) or start_ms)
        scenes.append(
            {
                "index": idx,
                "start_ms": start_ms,
                "end_ms": max(start_ms + 1, end_ms),
                "duration_ms": max(1, end_ms - start_ms),
                "source_prompt": source_prompt or speech_text or visual_anchor or director_seed,
                "narrative_state": narrative_state_for_scene(idx, total),
                "speech_text": speech_text,
                "speech_summary": summarize_scene_text(speech_text or source_prompt, 80),
                "audio_anchor": audio_anchor,
                "importance_score": int(item.get("importance_score", scene_audio_importance_score(f"{audio_anchor} {speech_text}")) or 0),
                "key_image_reason": clean_text(str(item.get("key_image_reason") or "")),
                "alignment_score": int(item.get("alignment_score", 0) or 0),
                "prompt_audio_alignment": prompt_audio_alignment,
                "prompt_rebound_to_audio": prompt_rebound,
                "visual_audio_alignment": visual_audio_alignment,
                "visual_rebound_to_audio": visual_rebound,
                "cut_reason": clean_text(str(item.get("cut_reason") or "")),
                "visual_type": visual_type,
                "material_style": classify_material_style(source_prompt or speech_text or visual_anchor, template, "scene"),
                "visual_anchor": visual_anchor,
                "visual_director": visual_scene,
                "image_prompt": image_prompt,
                "motion": clean_text(str(director_scene.get("motion") or "")) or scene_motion_for_type(visual_type, idx),
                "transition": clean_text(str(director_scene.get("transition") or "")) or scene_transition_for_index(idx, total, visual_type),
                "edit_direction": {
                    "pace": director_scene.get("pace"),
                    "target_hold_seconds": director_scene.get("target_hold_seconds"),
                    "cut_reason": director_scene.get("cut_reason"),
                    "subtitle_priority": director_scene.get("subtitle_priority"),
                },
                "sound_cue": {
                    "bgm_mood": sound_direction.get("bgm_mood"),
                    "energy": director_scene.get("pace"),
                    "note": "BGM 跟随本镜节奏，不盖过口播",
                },
                "material_hint": scene_material_hint(visual_type),
                "safe_text_policy": "画面文字和信息元素由当前口播与选定视觉概念决定；文字可以多也可以不使用，但事实必须准确且不能串入其它镜头。",
            }
        )

    return {
        "generated_at": storage.now_ts(),
        "topic": episode_topic,
        "title": summary.get("publish_title") or summary.get("video_title") or clean_text(project.get("topic_name") or ""),
        "scene_count": len(scenes),
        "timeline_source": "audio/scene_timeline.json",
        "visual_brief_source": "visual_brief.json",
        "visual_director_source": "visual_director.json",
        "visual_brief": {
            "topic_type": visual_brief.get("topic_type"),
            "topic_type_label": visual_brief.get("topic_type_label"),
            "visual_world": visual_brief.get("visual_world"),
            "forbidden": visual_brief.get("forbidden", []),
        },
        "edit_direction": {
            "overall_pace": edit_direction.get("overall_pace"),
            "transition_policy": edit_direction.get("transition_policy"),
            "opening_policy": edit_direction.get("opening_policy"),
        },
        "sound_direction": sound_direction,
        "cover_duration_ms": timeline.get("cover_duration_ms", TIMELINE_COVER_MS) if isinstance(timeline, dict) else TIMELINE_COVER_MS,
        "outro_duration_ms": timeline.get("outro_duration_ms", TIMELINE_OUTRO_MS) if isinstance(timeline, dict) else TIMELINE_OUTRO_MS,
        "workflow_notes": [
            "先由真实字幕里的语义节点筛选关键画面，纯过渡口播不单独增加图片。",
            "每镜保留音频段全文和关键口播，视觉形式由 AI 候选概念决定。",
            "图片文字和信息元素不预设数量或固定位置，生成后通过 OCR 核对关键事实。",
        ],
        "scenes": scenes,
    }


def write_scene_plan(project_id: int, project: dict[str, Any], content: str, timeline: dict[str, Any], scene_lines: list[str]) -> dict[str, Any]:
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    timeline_scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
    timeline_scenes = timeline_scenes if isinstance(timeline_scenes, list) else []
    timeline_beats = [
        clean_text(str(item.get("prompt") or item.get("text") or ""))
        for item in timeline_scenes
        if isinstance(item, dict)
    ]
    visual_brief = save_visual_brief(
        project_id,
        content,
        scene_count=len(timeline_beats) or len(scene_lines),
        beats=timeline_beats or scene_lines,
    )
    visual_director = get_or_create_visual_director(project, template, content, visual_brief)
    plan = build_scene_plan(project, content, timeline, scene_lines, visual_brief=visual_brief, visual_director=visual_director)
    storage.write_json(storage.project_file(project_id, "audio/scene_plan.json"), plan)
    manifest_prompts = [
        clean_text(str(item.get("image_prompt") or ""))
        for item in plan.get("scenes", [])
        if isinstance(item, dict) and clean_text(str(item.get("image_prompt") or ""))
    ]
    if manifest_prompts:
        with contextlib.suppress(Exception):
            manifest = save_visual_prompt_manifest(
                project_id,
                content,
                scene_lines_override=manifest_prompts,
            )
            sync_scene_prompt_records_from_manifest(
                project_id,
                manifest,
                [
                    clean_text(str(item.get("target") or ""))
                    for item in manifest.get("scenes", [])
                    if isinstance(item, dict)
                ],
            )
    return plan


def _spec_field(content: str, labels: list[str]) -> str:
    for label in labels:
        value = extract_meta_field(content, label) or extract_bullet_field(content, label)
        if value:
            return clean_text(value)
    return ""


def _video_spec_checks(spec: dict[str, Any]) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    basics = spec.get("basics") if isinstance(spec.get("basics"), dict) else {}
    scenes = spec.get("scenes") if isinstance(spec.get("scenes"), list) else []

    def add(level: str, where: str, issue: str, fix: str) -> None:
        checks.append({"level": level, "where": where, "issue": issue, "fix": fix})

    if not basics.get("audience"):
        add("warn", "受众", "没有识别到明确目标受众。", "在 brief 或 content.md 里补一句“目标受众：谁在什么场景看”。")
    if not basics.get("core_message"):
        add("warn", "核心信息", "没有识别到 12-20 字左右的核心记忆点。", "补一个“核心观点/核心信息”，后续封面和场景图都围绕它。")
    if not basics.get("hook"):
        add("risk", "开头钩子", "没有识别到明确钩子。", "补一句具体、反常识、有动作感的开头，不要只写泛泛结论。")
    if len(scenes) < 3 and basics.get("mode") != "article":
        add("risk", "分镜", "可用场景少于 3 个。", "先重建图片提示词或补充口播段落，再进入生图。")

    prompt_texts = [clean_text(str(item.get("image_prompt") or "")) for item in scenes if isinstance(item, dict)]
    normalized_heads = [re.sub(r"第\s*\d+\s*张|^\d+[.、]\s*", "", text[:90]) for text in prompt_texts]
    if len(normalized_heads) >= 3 and len(set(normalized_heads)) <= max(1, len(normalized_heads) // 2):
        add("warn", "场景差异", "多张场景图开头描述过于相似，可能又会生成同一类画面。", "逐镜绑定不同台词锚点、人物动作、空间或物件。")

    forbidden_residue = ("视频扣费", "纸样", "旧纸片", "复古档案", "牛皮纸", "手账")
    residue_hits = sorted({token for token in forbidden_residue if any(token in text for text in prompt_texts)})
    if residue_hits:
        add("warn", "提示词残留", f"发现疑似上期或固定风格残留：{', '.join(residue_hits)}。", "清理频道模板里的固定画面词，只保留频道气质。")
    return checks


def build_video_spec(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    content_text = content if content is not None else storage.get_content(project_id)
    if not clean_text(content_text):
        raise ValueError("当前项目还没有 content.md，无法生成编导规格。")

    summary = summarize_content(content_text, mode)
    topic = clean_text(project.get("topic_name") or summary.get("video_title") or first_heading(content_text) or "本期主题")
    platform = infer_platform_profile(project, template)
    style_source = "\n".join(
        filter(
            None,
            [
                topic,
                _spec_field(content_text, ["目标受众", "受众", "人群"]),
                _spec_field(content_text, ["核心观点", "核心信息", "核心知识点"]),
                _spec_field(content_text, ["钩子", "前3秒钩子", "前 3 秒钩子"]),
                content_text[:1600],
            ],
        )
    )
    style = classify_material_style(style_source, template, "scene")
    domain = classify_visual_prompt_domain(style_source, "scene")
    count_info = resolve_project_scene_count(project, content_text, mode)
    desired_count = clamp_scene_count(count_info.get("final", 0), 4 if mode == "article" else 6)
    beats = derive_content_scene_beats(content_text, mode, topic, style=style, source=style_source, desired_count=desired_count)
    dialogue_anchors = select_dialogue_scene_anchors(content_text, mode, max(len(beats), 1), limit=100)
    audience = _spec_field(content_text, ["目标受众", "目标人群", "受众", "人群"])
    if not audience and (
        "爸妈" in style_source
        or "爸、妈" in style_source
        or "爸爸妈妈" in style_source
        or "长辈" in style_source
        or "老人" in style_source
        or "中老年" in style_source
        or "爸妈" in clean_text(template.get("name") or template_key)
    ):
        audience = "45-70 岁中老年用户，以及会转发给父母的子女。"
    hook = _spec_field(content_text, ["钩子", "前3秒钩子", "前 3 秒钩子", "开头钩子"])
    if not hook and dialogue_anchors:
        hook = summarize_scene_text(dialogue_anchors[0], 110)
    core_message = _spec_field(content_text, ["核心观点", "核心信息", "核心知识点"])
    if not core_message:
        core_message = summarize_scene_text(summary.get("cover_title") or summary.get("publish_title") or topic, 40)
    scene_lines = build_content_scene_prompt_lines(project, template, content_text)
    scene_count = max(len(beats), len(scene_lines), 1)
    scenes: list[dict[str, Any]] = []
    for idx in range(1, scene_count + 1):
        beat = beats[min(idx - 1, len(beats) - 1)] if beats else f"{topic} 场景 {idx}"
        dialogue = dialogue_anchors[min(idx - 1, len(dialogue_anchors) - 1)] if dialogue_anchors else beat
        source_prompt = scene_lines[min(idx - 1, len(scene_lines) - 1)] if scene_lines else beat
        visual_type = infer_visual_type(source_prompt, dialogue)
        narrative = narrative_state_for_scene(idx, scene_count)
        scenes.append(
            {
                "index": idx,
                "narrative_state": narrative,
                "dialogue_anchor": dialogue,
                "scene_beat": beat,
                "information_load": summarize_scene_text(dialogue or beat, 70),
                "visual_type": visual_type,
                "material_style": classify_material_style(f"{source_prompt}\n{dialogue}", template, "scene"),
                "motion": scene_motion_for_type(visual_type, idx),
                "transition": scene_transition_for_index(idx, scene_count, visual_type),
                "text_policy": "是否使用文字及信息元素由当前口播决定；数字、对比、批注、图表和实体标签都可使用，但每项必须能回溯到本镜口播，界面长段正文和免责声明不直接入画。",
                "safe_area": "主体不压底部字幕区，手机屏幕和人物动作留在画面中上区域。",
                "image_prompt": source_prompt,
            }
        )

    covers = {
        "landscape": {
            "label": "横屏封面",
            "size": COVER_LANDSCAPE_SIZE,
            "prompt": build_content_cover_prompt(project, template, content_text, "landscape"),
        },
        "story": {
            "label": "图文封面",
            "size": COVER_STORY_SIZE,
            "prompt": build_content_cover_prompt(project, template, content_text, "story"),
        },
        "portrait": {
            "label": "竖屏封面",
            "size": COVER_PORTRAIT_SIZE,
            "prompt": build_content_cover_prompt(project, template, content_text, "portrait"),
        },
    }
    if mode == "article":
        covers = {"landscape": covers["landscape"]}

    spec: dict[str, Any] = {
        "schema": "short-video-studio.video-spec.v1",
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "template": {
            "key": template_key,
            "name": template.get("name") or template_key,
            "brand_name": template.get("brand_name") or template.get("name") or template_key,
            "mode": mode,
            "cover_style": template.get("cover_style") or "default",
        },
        "basics": {
            "topic": topic,
            "mode": mode,
            "platform": platform,
            "duration": summary.get("duration") or _spec_field(content_text, ["时长"]),
            "audience": audience,
            "core_message": core_message,
            "hook": hook,
            "publish_title": summary.get("publish_title") or "",
            "cover_title": summary.get("cover_title") or "",
            "cover_subtitle": summary.get("cover_subtitle") or "",
        },
        "visual_rules": {
            "style": style,
            "domain": domain,
            "channel_binding": channel_visual_style_hint(template, "scene"),
            "scene_text_policy": "场景图靠主体、动作、物件和空间关系形成信息锤点；文字与信息元素的数量、位置和形式由当前口播决定，核心事实必须准确，长段说明交给字幕。",
            "cover_text_policy": "只有封面主标题、副标题和频道角标可以清晰可读。",
        },
        "scene_count": len(scenes),
        "scene_count_policy": count_info,
        "scenes": scenes,
        "covers": covers,
        "workflow_notes": [
            "先把视频想清楚，再生成图片；图片提示词必须服务当前台词锚点。",
            "频道只提供统一气质，不能把某一期的具体物件、页面或流程写死到所有主题。",
            "每个镜头必须有信息载荷；没有信息载荷的镜头应删除或合并。",
        ],
    }
    spec["checks"] = _video_spec_checks(spec)
    return spec


def save_video_spec(project_id: int, content: str | None = None) -> dict[str, Any]:
    spec = build_video_spec(project_id, content)
    storage.write_json(storage.project_file(project_id, "video_spec.json"), spec)
    return spec


def load_fresh_video_spec(project_id: int) -> dict[str, Any]:
    spec_path = storage.project_file(project_id, "video_spec.json")
    content_path = storage.project_file(project_id, "content.md")
    if not spec_path.exists():
        return {}
    if content_path.exists() and spec_path.stat().st_mtime + 0.5 < content_path.stat().st_mtime:
        return {}
    payload = storage.read_json(spec_path, {})
    return payload if isinstance(payload, dict) else {}


def video_spec_scene_prompts(project_id: int) -> list[str]:
    payload = load_fresh_video_spec(project_id)
    scenes = payload.get("scenes") if isinstance(payload, dict) else None
    if not isinstance(scenes, list):
        return []
    prompts = [
        clean_text(str(item.get("image_prompt") or item.get("scene_beat") or item.get("dialogue_anchor") or ""))
        for item in scenes
        if isinstance(item, dict)
    ]
    return [prompt for prompt in prompts if prompt]


def video_spec_cover_prompt(project_id: int, kind: str) -> str:
    payload = load_fresh_video_spec(project_id)
    covers = payload.get("covers") if isinstance(payload, dict) else None
    if not isinstance(covers, dict):
        return ""
    cover = covers.get(kind)
    if not isinstance(cover, dict):
        cover = covers.get(str(normalize_cover_target(kind).get("kind") or kind)) if kind in COVER_IMAGE_TARGETS else None
    return clean_text(str(cover.get("prompt") or "")) if isinstance(cover, dict) else ""


def transcribe_audio_to_text(audio_path: Path) -> str:
    env = runtime_env()
    tmp_srt = storage.CONFIG_ROOT / f"brief-import-{storage.now_ms()}.srt"
    try:
        run_original_bridge(
            "asr",
            {
                "audio_path": str(audio_path),
                "srt_output": str(tmp_srt),
                "dialogue_lines": [],
            },
            env,
            timeout=300,
        )
        utterances = load_srt_entries(tmp_srt)
        text = utterances_to_plain_text(utterances)
        if text:
            return text
        if tmp_srt.exists():
            return clean_text(tmp_srt.read_text(encoding="utf-8", errors="ignore"))
        return ""
    finally:
        tmp_srt.unlink(missing_ok=True)


