def extract_labeled_prompt_value(text: str, label: str, limit: int = 92) -> str:
    cleaned = clean_text(text)
    if not cleaned:
        return ""
    start = -1
    marker_len = 0
    for marker in (f"{label}：", f"{label}:"):
        start = cleaned.find(marker)
        if start >= 0:
            marker_len = len(marker)
            break
    if start < 0:
        return ""
    tail = cleaned[start + marker_len :].strip(" ，。")
    stop_positions: list[int] = []
    for stop in PROMPT_FIELD_STOP_MARKERS:
        if stop == label:
            continue
        for prefix in (f"，{stop}", f"。{stop}", f"；{stop}"):
            pos = tail.find(prefix)
            if pos > 0:
                stop_positions.append(pos)
    if stop_positions:
        tail = tail[: min(stop_positions)]
    return compact_visual_anchor_text(tail.strip(" ，。；"), limit)


def explicit_visual_directives(raw_text: str, purpose: str) -> list[str]:
    labels = (
        ("封面先画", "封面主画面"),
        ("封面具体画面", "封面具体画面"),
        ("封面钩子锚点", "封面钩子锚点"),
        ("开头口播锚点", "封面钩子锚点"),
    ) if purpose == "cover" else (
        ("口播原文", "口播原文"),
        ("画面任务", "画面任务"),
        ("主主体", "主主体"),
        ("动作", "动作"),
        ("冲突/悬念", "冲突/悬念"),
        ("本镜头先画", "本镜头先画"),
        ("具体画面", "具体画面"),
        ("本期专属画面", "具体画面"),
        ("镜头变化", "镜头变化"),
        ("对应口播", "对应口播"),
    )
    directives: list[str] = []
    for label, prefix in labels:
        value = extract_labeled_prompt_value(raw_text, label, 110 if label in {"具体画面", "封面具体画面"} else 78)
        if value:
            if purpose != "cover":
                value = neutralize_scene_rendered_text_targets(value)
            directives.append(f"{prefix}：{value}")
    return dedupe_clauses(directives)


def extract_cover_title_hint(text: str) -> str:
    source = str(text or "")
    cleaned = clean_text(source)
    patterns = (
        r"(?:封面)?主标题\s*[：:]\s*[「“\"']?([^\r\n。；;]{2,80})",
        r"封面主标题必须原样清晰写成[「“](.+?)[」”]",
        r"主标题必须作为清晰可读中文大字出现[：:]\s*([^，。；]+)",
        r"围绕[「“](.+?)[」”]做短视频封面",
    )
    for pattern in patterns:
        match = re.search(pattern, source) or re.search(pattern, cleaned)
        if match:
            candidate = clean_text(match.group(1)).strip("「」“”\"' ：:")
            candidate = re.split(r"\s+(?:反转章|副标题|短副标题|频道角标)\s*[：:]", candidate, maxsplit=1)[0]
            if content_lines_use_english([candidate]):
                if len(candidate) <= 72:
                    return candidate
                return candidate[:73].rsplit(" ", 1)[0].rstrip(" ,.;:!?")
            return _compact_complete_text(candidate, 30)
    return ""


def extract_cover_subtitle_hint(text: str) -> str:
    source = str(text or "")
    patterns = (
        r"(?:反转章|短副标题|封面副标题|副标题)\s*[：:]\s*[「“\"']?([^\r\n。；;]{2,80})",
        r"封面短副标题必须原样清晰写成[「“](.+?)[」”]",
        r"副标题可作为较小清晰中文出现[：:]\s*([^，。；]+)",
    )
    for pattern in patterns:
        match = re.search(pattern, source)
        if match:
            candidate = clean_text(match.group(1)).strip("「」“”\"' ：:")
            if content_lines_use_english([candidate]):
                if len(candidate) <= 80:
                    return candidate
                return candidate[:81].rsplit(" ", 1)[0].rstrip(" ,.;:!?")
            return _compact_complete_text(candidate, 34)
    return ""


def neutralize_scene_rendered_text_targets(text: str) -> str:
    cleaned = clean_text(text)
    if not cleaned:
        return ""
    cleaned = re.sub(
        r"(?:[A-Za-z\u4e00-\u9fff]{2,12}[、/]){1,}[A-Za-z\u4e00-\u9fff]{2,12}(?=(?:三条|两条|几条|多条|不同|相关)?(?:无字)?(?:扣费|支付|授权|渠道|通道|入口))",
        "多个相关渠道",
        cleaned,
    )
    def quote_replacement(match: re.Match[str]) -> str:
        value = clean_text(match.group(1))
        if 1 <= len(value) <= 14 and not _contains_any(value, ("免责声明", "内容基于", "仅作", "水印", "Logo", "logo")):
            return f"短标签「{value}」"
        return "对应概念"

    cleaned = re.sub(r"[「“\"']([^」”\"']{1,30})[」”\"']", quote_replacement, cleaned)
    cleaned = re.sub(r"[A-Za-z0-9\u4e00-\u9fff]{1,16}会员", "某项服务", cleaned)
    cleaned = re.sub(r"(?:手机|屏幕|系统|扣费|付款|账单|服务|应用|App)?(?:短信|通知|弹窗|提示)", "无字提醒", cleaned)
    cleaned = re.sub(r"(?:手机|付款|扣费|消费|服务|应用|App)?账单", "无字账单卡片", cleaned)
    cleaned = cleaned.replace("无字账单卡片提醒", "无字账单卡片")
    cleaned = cleaned.replace("多个相关渠道通道", "多个相关渠道")
    if _contains_any(cleaned, ("短信", "通知", "账单", "页面", "按钮", "列表", "表格", "评论区", "标签", "标题", "弹窗", "卡片")):
        cleaned = f"{cleaned}；界面长段正文用图标、色块、短线和动作关系概括；与当前口播有关的数字、短结论和批注可由 AI 按信息层级清晰组织"
    return cleaned


def concrete_visual_hint_from_anchor(anchor_text: str, raw_text: str = "", purpose: str = "scene") -> str:
    anchor = clean_text(anchor_text)
    source = clean_text(f"{anchor} {raw_text}")
    if not anchor:
        return ""

    prefix = "封面具体画面" if purpose == "cover" else "具体画面"
    if _contains_any(source, ("自动续费", "扣费", "订阅", "会员", "免密支付", "自动扣款", "连续包月", "关闭服务", "取消订阅", "微信", "支付宝", "苹果支付")):
        if _contains_any(anchor, ("短信", "扣费", "续费", "想不起来", "几十块")) or re.search(r"(?:¥|￥)?\d+(?:\.\d+)?\s*(?:元|块|角|毛)", anchor):
            return f"{prefix}：手机上无字扣款通知或账单卡片在前景亮起，长辈/用户拿着手机停住，旁边家人凑近提醒，钱被悄悄扣走的瞬间清楚"
        if _contains_any(anchor, ("免费体验", "1块钱", "1元", "默认勾选", "到期自动续费", "试用")):
            return f"{prefix}：手机开通会员页面只露出无字勾选框和价格牌形图标，手指正要点击，旁边有一枚小警示符号"
        if _contains_any(anchor, ("App里", "取消订阅", "还在扣", "真正的开关", "水管总阀")):
            return f"{prefix}：手机里一个已关闭按钮在前景，但背景还有几条无字支付授权通道继续发光，误区一眼可见"
        if _contains_any(anchor, ("微信", "扣费服务", "服务", "三个点", "关闭服务")):
            return f"{prefix}：支付应用里的授权管理列表以无字卡片呈现，手指点向关闭入口，家人站在旁边确认，操作动作真实可见"
        if _contains_any(anchor, ("支付宝", "免密支付", "自动扣款", "支付设置")):
            return f"{prefix}：支付设置页面以无字列表呈现，手指停在关闭入口，桌面上有账单和老花镜做生活线索"
        if _contains_any(anchor, ("苹果", "头像", "订阅", "取消订阅")):
            return f"{prefix}：手机系统订阅设置页面以无字列表呈现，头像入口和订阅卡片用图形暗示，手指正在确认取消"
        if _contains_any(anchor, ("查一遍", "每个月", "省", "口袋", "清掉")):
            return f"{prefix}：餐桌或书桌上手机展示已关闭的无字扣费项目，旁边放着账单和零钱，人物表情从紧张变成放心"
        if _contains_any(anchor, ("评论区", "告诉我", "转发", "家里人", "下期见")):
            return f"{prefix}：用户把手机递给家人一起查看评论和转发动作，屏幕只露少量无字气泡，结尾互动感清楚"
        return f"{prefix}：以无字手机通知、订阅入口、账单卡片和家人提醒动作做主画面，把自动续费正在被发现或关闭的瞬间拍清楚"

    elder_terms = (
        "老人", "长辈", "中老年", "爸妈", "父母", "记性", "健忘", "忘事", "痴呆", "认知",
        "社区医院", "老年科", "画钟", "钥匙", "吃饭", "吃过饭", "吃了没",
        "早上", "下午", "散步", "打牌", "算账",
    )
    if _contains_any(source, elder_terms):
        if _contains_any(anchor, ("钥匙", "刚放", "东西转头", "名字", "提醒", "想起来")):
            return f"{prefix}：中老年人站在客厅茶几或玄关旁寻找刚放下的钥匙/手机，桌上有老花镜，家人停下动作关切看向他"
        if _contains_any(anchor, ("吃过饭", "吃了没", "早上", "下午", "性格突然", "暴躁", "多疑")):
            return f"{prefix}：饭桌或客厅里的真实家庭瞬间，一位长辈困惑地看着饭碗/墙上时钟，家人表情从担心到警觉"
        if _contains_any(anchor, ("出门", "走丢", "找不到", "回家", "不认识人")):
            return f"{prefix}：小区门口或街道路口，一位长辈拿着手机停住，背景有家人焦急寻找的动作，空间方向感清楚"
        if _contains_any(anchor, ("社区医院", "老年科", "认知测试", "画钟", "记忆力测试", "测试", "筛")):
            return f"{prefix}：社区医院诊室里，医生把简易认知测试纸推到桌前，长辈拿笔画钟，家人坐在旁边陪同"
        if _contains_any(anchor, ("聊天", "散步", "数字游戏", "打牌", "算账", "运转")):
            return f"{prefix}：家人和长辈在餐桌/公园长椅旁互动，打牌、算账或散步正在发生，画面温暖但动作明确"
        if _contains_any(anchor, ("评论区", "怎么判断", "类似情况", "更多人看到")):
            return f"{prefix}：子女和长辈坐在沙发边看手机评论，屏幕只露出少量无字气泡图标，人物正在讨论和回应"
        if _contains_any(anchor, ("害怕", "焦虑", "痴呆", "别急", "警惕", "信号", "留意")):
            return f"{prefix}：中年人握着手机查资料显得紧张，长辈在旁边停顿看向他，画面用一个小警示符号点出风险"
        return f"{prefix}：真实家庭或社区空间里，一位长辈、家人和关键生活物件同框，用表情和手部动作表现这句口播里的判断点"

    if _contains_any(source, ("智能手表", "智能手环", "血氧", "心率", "指夹式血氧仪", "PPG", "光电传感器")):
        if _contains_any(anchor, ("91%", "93%", "94%", "96%", "97%", "98%", "对比", "差距", "测了")):
            return f"{prefix}：同一只手在真实桌面同时佩戴智能手表和指夹式血氧仪，人物正在核对两种读数，设备与表情形成明确反差，数字只做辅助证据"
        if _contains_any(anchor, ("皮肤不是玻璃", "出汗", "纹身", "指甲油", "佩戴松", "干扰")):
            return f"{prefix}：微距拍摄手表背部传感器贴近真实手腕，汗珠、松动表带或纹身造成测量干扰，人物另一只手正在重新调整佩戴位置"
        if _contains_any(anchor, ("趋势", "晚上睡觉", "异常下降", "连续监测")):
            return f"{prefix}：卧室清晨的真实使用场景，手腕、床边设备和一条简洁趋势变化共同出现，人物正在回看整夜记录，不做报表拼贴"
        if _contains_any(anchor, ("说明书", "仅供参考", "诊断依据")):
            return f"{prefix}：人物把智能手表与展开的产品说明书放在同一桌面，手指指向关键免责声明位置，旁边的指夹式血氧仪成为真实对照物"
        return f"{prefix}：真实人物正在使用智能手表完成一次血氧测量，手腕、手指、设备贴合状态和即时反应清楚可见，必要时用指夹式血氧仪做现场对照"
    if _contains_any(source, ("路由器", "wifi", "WiFi", "PLC", "插座", "传感器", "网关", "主机", "智能家居", "设备")):
        return f"{prefix}：真实家居空间里把核心设备放大成主角，墙体/插座/手机控制界面形成清楚连接关系，光线突出技术冲突"
    if _contains_any(source, ("世界杯", "足球", "篮球", "比赛", "冠军", "球员", "比分", "奖杯")):
        return f"{prefix}：球场灯光下的关键动作瞬间，球员、奖杯或观众反应形成强对峙，胜负压力一眼能看懂"
    if _contains_any(source, ("实验", "细胞", "基因", "器官", "大脑", "医学", "药物", "分子")):
        return f"{prefix}：实验室或人体结构可视化场景，把核心机制落成一个正在观察/检测/变化的瞬间，不做平面讲义"
    if _contains_any(source, ("公司", "市场", "行业", "增长", "营收", "融资", "品牌", "销量")):
        return f"{prefix}：商业现场或城市空间里，一个产品、人物决策或体量对比压住画面，用光影和空间层次表现结果"
    if _contains_any(source, ("历史", "古代", "皇帝", "战争", "朝代", "帝国", "革命")):
        return f"{prefix}：把历史观点放进真实时代场景，人物、器物、建筑和权力关系同框，像电影剧照而不是旧纸资料"

    concrete_terms = [
        term
        for term in CONCRETE_VISUAL_TOKENS
        if term in source and term not in ("人物", "动作", "图标", "节点", "箭头")
    ][:4]
    if concrete_terms:
        return f"{prefix}：把{ '、'.join(concrete_terms) }放进同一真实空间，用一个正在发生的动作或状态变化承载观点"
    if str(prefix).startswith("封面"):
        return f"{prefix}：把封面标题里的主角、关键物件和核心冲突放到同一真实现场，先让观众一眼看懂本期主题"
    return f"{prefix}：把这句口播里的主角、动作、物件和结果放到同一真实现场，先让观众看到正在发生什么，再补少量辅助线索"


def image_layout_mode(raw_text: str, purpose: str) -> str:
    if purpose == "cover":
        return "text_led"
    speech = scene_prompt_audio_anchor(raw_text) or clean_text(raw_text)
    callouts = extract_scene_readable_callouts(speech)
    numeric_signal = bool(
        re.search(
            r"(?:\d+(?:\.\d+)?\s*(?:%|％|元|块|万|亿|秒|分钟|小时|天|年|倍|部|家|款|人|GB|MB|W|V|A))",
            speech,
            flags=re.IGNORECASE,
        )
    )
    conclusion_signal = _contains_any(
        speech,
        (
            "真相",
            "结论",
            "反转",
            "其实",
            "原来",
            "竟然",
            "别再",
            "不要再",
            "最关键",
            "真正的问题",
            "你以为",
            "为什么",
            "到底",
            "记住",
            "警惕",
        ),
    )
    return "text_led" if callouts or numeric_signal or conclusion_signal else "object_led"


def image_text_policy_clauses(raw_text: str, purpose: str) -> list[str]:
    if purpose == "cover":
        title = extract_cover_title_hint(raw_text)
        subtitle = extract_cover_subtitle_hint(raw_text)
        exact_text: list[str] = []
        if title:
            exact_text.append(f"封面主标题必须原样清晰写成「{title}」，不得省略、改写或缩成角落小字")
        if subtitle:
            exact_text.append(f"封面短副标题必须原样清晰写成「{subtitle}」，与主标题形成结论反转")
        return exact_text + [
            "采用文字主导的满幅封面：主标题是最大视觉块，文字与主体共同占满画面，不把标题缩在角落，也不留下大块无效空白",
            "画面只保留一到三个与主题直接相关的核心物体或人物局部，放大到能看清材质和冲突；删除装饰性小物、复杂背景和无关界面",
            "只有封面主标题、副标题和频道角标可以作为可读文字；主信息可配必要数字或短注，但不排成长段正文",
            "正文里的服务名、金额、按钮名、平台名和引号内容只作为语义锚点，不额外原样写进画面",
        ]
    readable_hint = scene_readable_callout_clause(raw_text)
    if image_layout_mode(raw_text, purpose) == "text_led":
        return [
            readable_hint,
            "本镜采用信息主导的满幅构图：由生图模型直接把当前口播需要的标题、完整结论、数字、对比、批注和关系文字画进图片；不设统一字数或数量上限，按语义层级自动换行和排版，文字必须完整、清晰、准确，不截断句子",
            "文字、主体、证据物件和关系线必须在同一次生成中成为一个整体；不追加统一标题板、黑条、灰色半透明卡片或后期模板字",
            "只保留一到三个能证明当前口播的核心物体或人物局部，主体与文字共同覆盖约85%的画面；删除无关人物、装饰小物、复杂背景、四宫格和密集卡片",
            "手机屏幕、账单、按钮、通知、评论区和表格里的长界面仍用图标、色块、短线或动作关系表达，不生成长段界面文字",
        ]
    return [
        readable_hint,
        "本镜采用物体主导的满幅构图：一个动作峰值加一到三个核心物体占满主要画面，不堆装饰道具，不使用空泛人物摆拍；没有关键数字或结论时不强行加大字",
        "手机屏幕、账单、按钮、通知、评论区和表格里的长界面仍用无字界面、模糊短线、图标、色块或动作关系表达",
    ]


def extract_scene_readable_callouts(text: str, limit: int = 4) -> list[str]:
    cleaned = clean_text(text)
    if not cleaned:
        return []
    cleaned = re.sub(r"\b\d+\s*[:：]\s*\d+\b", " ", cleaned)
    cleaned = re.sub(r"\b\d{3,4}\s*[x×]\s*\d{3,4}\b", " ", cleaned)
    cleaned = re.sub(r"第\s*\d+\s*张(?:场景图|正文配图|图片|图)?", " ", cleaned)
    cleaned = re.sub(r"(?:横屏|竖屏|横版|竖版)(?:封面|场景图|正文配图|头图)?", " ", cleaned)
    candidates: list[str] = []

    def add(value: str) -> None:
        value = clean_text(value).strip("「」“”\"'，。；:： ")
        if not value:
            return
        if re.fullmatch(r"\d{1,2}", value):
            return
        if any(term in value for term in IMAGE_PROMPT_META_POLLUTION_TERMS):
            return
        if len(value) > 14:
            return
        if _contains_any(value, ("免责声明", "内容基于", "仅作", "水印", "Logo", "logo")):
            return
        if value not in candidates:
            candidates.append(value)

    for match in re.finditer(r"[「“\"']([^」”\"']{1,14})[」”\"']", cleaned):
        add(match.group(1))
    patterns = (
        r"(?:TOP|Top|top)\s*\d+",
        r"\d+(?:\.\d+)?\s*%",
        r"(?<![A-Za-z])(?:¥|￥|\$)?\d+(?:\.\d+)?\s*(?:元|块|美元|亿|万|万人|人|个月|分钟|小时|天|年|倍|GB|MB)?",
        r"[一二两三四五六七八九十百千万]+(?:元|块|亿|万|万人|人|个月|分钟|小时|天|年|倍)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, cleaned):
            add(match.group(0))
    if "AI" in cleaned and _contains_any(cleaned, ("工作", "替代", "裁员", "饭碗", "岗位")):
        add("AI抢工作")
    keyword_groups = (
        ("先别慌", ("别慌", "别急", "先别")),
        ("真相", ("真相", "其实", "背后")),
        ("风险", ("风险", "危险", "陷阱", "扣费", "骗局")),
        ("省时间", ("效率", "省时间", "节省", "自动化")),
        ("谁在怕", ("谁在怕", "焦虑")),
    )
    for label, tokens in keyword_groups:
        if any(token in cleaned for token in tokens):
            add(label)
    return candidates[:limit]


def scene_readable_callout_clause(raw_text: str) -> str:
    callouts = extract_scene_readable_callouts(raw_text)
    if callouts:
        return (
            f"可读视觉钩子优先从当前口播提炼：{'、'.join(callouts)}；"
            "由 AI 按当前口播的信息层级决定使用哪些、如何组合和放置；允许使用完整结论和多层信息，不设固定字数，所有文字必须完整并与这一段音频完全呼应"
        )
    if re.search(r"\d", raw_text or "") or _contains_any(raw_text, ("数据", "增长", "比例", "排名", "成本", "销量", "市场", "趋势")):
        return "关键节点可加入大号数字、趋势箭头、对比光牌、批注和关系线；数量与层级由当前口播决定，数字必须准确"
    return "可按当前口播加入短结论、批注、图标和关系线，不限制固定数量或位置，不套用其它主题词"


