def scene_callout_rule_matches(source: str, rule_tokens: tuple[str, ...], labels: tuple[str, ...]) -> bool:
    text = clean_text(source)
    if not text:
        return False
    if labels and labels[0] == "3小时改稿":
        return _contains_any(text, ("AI", "人工智能")) and _contains_any(
            text,
            ("写作", "写稿", "改稿", "文案", "草稿", "大纲", "段落", "错别字", "废话", "复制粘贴"),
        )
    if labels and labels[0] == "AI代办":
        strong_ai_tokens = ("AI", "人工智能", "大模型", "智能体", "AIGC", "自动化", "机器人")
        replacement_tokens = ("抢工作", "替代岗位", "岗位变化", "裁员", "饭碗", "人机协作", "工作流自动化")
        return _contains_any(text, strong_ai_tokens) and _contains_any(text, replacement_tokens)
    return _contains_any(text, rule_tokens)


def foreign_scene_callout_hits(prompt: str, source: str) -> list[str]:
    text = clean_text(prompt)
    source_text = clean_text(source)
    hits: list[str] = []
    for rule_tokens, labels in SCENE_CALLOUT_DOMAIN_RULES:
        if scene_callout_rule_matches(source_text, rule_tokens, labels):
            continue
        for label in labels:
            if label in text and label not in hits:
                hits.append(label)
    return hits

