def infer_visual_topic_type(source: str, style: str, domain: str) -> str:
    text = clean_text(source).lower()
    if domain == "wearable_health" or _contains_any(text, ("智能手表", "智能手环", "血氧", "心率", "指夹式血氧仪", "ppg", "健康监测")):
        return "wearable_health"
    if domain == "smart_home":
        return "smart_home"
    if style == "elder_life":
        kind = classify_elder_life_topic_kind(source)
        if kind == "anti_fraud":
            return "elder_life_antifraud"
        if kind == "network_hotword":
            return "elder_life_hotword"
        if kind == "health":
            return "elder_life_health"
        if kind == "life_safety":
            return "life_safety"
        return "social_story"
    if domain == "product" or _contains_any(text, ("折叠屏", "手机", "汽车", "眼镜", "耳机", "充电器", "充电宝", "电视", "硬件产品")):
        return "ai_tech" if _contains_any(text, ("ai功能", "人工智能", "大模型", "智能体", "ai办公", "ai手机")) else "consumer_product"
    if style == "tech_cinematic" or _contains_any(text, ("ai", "人工智能", "大模型", "智能体", "自动化", "科技", "芯片", "机器人", "智能眼镜", "智能硬件")):
        return "ai_tech"
    if _contains_any(text, ("产品", "设备", "机器人", "硬件")):
        return "consumer_product"
    if domain == "mechanism" or style == "science_explainer" or _contains_any(text, ("原理", "机制", "为什么", "实验", "冷知识", "物理", "科学")):
        return "science_mechanism"
    if domain == "data" or _contains_any(text, ("财经", "股票", "基金", "价格", "销量", "市场", "增长", "趋势", "份额", "成本")):
        return "finance_data"
    if domain == "person_story":
        return "social_story"
    return "general_editorial"


def visual_topic_profile(topic_type: str) -> dict[str, Any]:
    return VISUAL_TOPIC_TYPE_PROFILES.get(topic_type, VISUAL_TOPIC_TYPE_PROFILES["general_editorial"])


def visual_callout_candidates(source: str, limit: int = 4) -> list[str]:
    text = clean_text(source)
    candidates: list[str] = []
    for quoted in re.findall(r"[「“\"']([^」”\"']{2,12})[」”\"']", text):
        candidates.append(quoted)
    for number in re.findall(r"\d+(?:\.\d+)?\s*(?:万|亿|元|美元|%|年|次|小时|分钟|副|倍)", text):
        candidates.append(number)
    keyword_rules = [
        (("反常识", "误区", "错了", "不一样", "终于", "真相"), "反常识"),
        (("价格", "成本", "便宜", "贵", "值不值"), "价格变化"),
        (("销量", "增长", "暴增", "市场", "趋势"), "数据变化"),
        (("风险", "骗局", "危险", "别急", "别慌"), "先别急"),
        (("效率", "省时间", "自动化", "工作流"), "省时间"),
        (("翻译", "导航", "会议", "录音", "识别"), "功能现场"),
    ]
    for keys, label in keyword_rules:
        if _contains_any(text, keys):
            candidates.append(label)
    return dedupe_clauses([summarize_scene_text(item, 8) for item in candidates if clean_text(item)])[:limit]


def visual_brief_scene_task(
    index: int,
    total: int,
    beat: str,
    dialogue_anchor: str,
    topic: str,
    style: str,
    domain: str,
    profile: dict[str, Any],
) -> dict[str, Any]:
    narrative = narrative_state_for_scene(index, total)
    source = "\n".join(item for item in (topic, beat, dialogue_anchor, narrative) if clean_text(item))
    visual_type = infer_visual_type(source, source)
    entities = choose_visual_entities(source, style, domain, limit=3)
    explicit_products = [
        token
        for token in (
            "折叠屏手机",
            "智能手表",
            "智能手环",
            "降噪耳机",
            "无线耳机",
            "无线充电器",
            "充电宝",
            "智能电视",
            "手机",
            "耳机",
            "手表",
            "电视",
        )
        if token in source
    ]
    if explicit_products:
        entities = dedupe_clauses([explicit_products[0], *entities])
    if not entities:
        entities = [str(item) for item in profile.get("subjects", [])[:3]]
    elif explicit_products and len(entities) < 2:
        entities = dedupe_clauses(
            [
                *entities,
                *[
                    str(item)
                    for item in profile.get("subjects", [])
                    if clean_text(str(item)) and str(item) != "产品本体"
                ],
            ]
        )[:3]
    actions = [str(item) for item in profile.get("actions", []) if clean_text(str(item))]
    # The channel owns the art direction, while the current narration owns
    # every subject and action.  Do not select a reusable topic recipe here:
    # it can leak a previous episode's objects into an unrelated scene.
    action = clean_text(concrete_visual_hint_from_anchor(dialogue_anchor or beat, source, "scene"))
    if not action:
        action = actions[(index - 1) % len(actions)] if actions else "正在发生的动作"
    callouts = visual_callout_candidates(source, limit=3) or [str(item) for item in profile.get("hooks", [])[:2]]
    tension = infer_visual_tension(source, style, visual_type, "scene") or str(profile.get("world") or "")
    return {
        "index": index,
        "narrative_state": narrative,
        "visual_type": visual_type,
        "beat": summarize_scene_text(beat, 86),
        "dialogue_anchor": summarize_scene_text(dialogue_anchor, 86),
        "primary_subjects": entities[:3],
        "action_peak": action,
        "attention_hooks": callouts[:3],
        "tension": summarize_scene_text(tension, 90),
    }


def build_visual_brief(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    scene_count: int = 0,
    beats: list[str] | None = None,
    dialogue_anchors: list[str] | None = None,
) -> dict[str, Any]:
    mode = clean_text(template.get("mode") or project.get("template_mode") or "video")
    visual_content = content_without_image_prompts(content)
    # Prefer the final editorial title over a long mining/query label.  Query
    # labels often contain categories and dates that consume prompt budget but
    # do not describe what the viewer should see.
    topic = clean_text(project.get("topic_name") or first_heading(visual_content or content) or "本期主题")
    summary = summarize_content(visual_content or content, mode)
    style_source = "\n".join(
        filter(
            None,
            [
                topic,
                summary.get("cover_title") or "",
                summary.get("cover_subtitle") or "",
                extract_bullet_field(visual_content, "核心观点"),
                extract_bullet_field(visual_content, "反常识点"),
                extract_bullet_field(visual_content, "人物或场景锚点"),
                extract_bullet_field(visual_content, "新比喻或新意象"),
                channel_image_style_prompt(template) or str(template.get("visual_strategy") or ""),
                visual_content[:1600],
            ],
        )
    )
    style = classify_material_style(style_source, template, "scene")
    domain = classify_visual_prompt_domain(style_source, "scene")
    topic_type = infer_visual_topic_type(style_source, style, domain)
    if style == "storyboard_comic" and re.search(
        r"(?:\bAI\b|人工智能|模型|参数|推理|Agent|DeepSeek|GPT|大语言)",
        style_source,
        flags=re.IGNORECASE,
    ):
        topic_type = "ai_tech"
    profile = dict(visual_topic_profile(topic_type))
    if style == "storyboard_comic":
        profile["world"] = (
            "暖米白纸张上的成熟科技编辑线稿卡通：当前主题对象由炭黑轮廓、手绘箭头、"
            "少量砖红/靛蓝/芥末黄平涂组成，像信息杂志跨页；不使用写实摄影、暗色控制台或泛用人物摆拍"
        )
    desired = scene_count or clamp_scene_count(resolve_project_scene_count(project, visual_content or content, mode).get("final", 0), 4 if mode == "article" else 6)
    scene_beats = beats or derive_content_scene_beats(visual_content or content, mode, topic, style=style, source=style_source, desired_count=desired)
    scene_beats = normalize_scene_prompt_count(scene_beats, desired, topic, mode)
    anchors = dialogue_anchors or select_dialogue_scene_anchors(visual_content or content, mode, max(len(scene_beats), 1), limit=88)
    scenes = [
        visual_brief_scene_task(
            idx,
            len(scene_beats),
            beat,
            anchors[min(idx - 1, len(anchors) - 1)] if anchors else beat,
            topic,
            style,
            domain,
            profile,
        )
        for idx, beat in enumerate(scene_beats, start=1)
    ]
    channel_negative = channel_image_negative_prompt(template)
    forbidden = dedupe_clauses(
        ([f"频道禁止元素：{compact_prompt_rule(channel_negative, 260)}"] if channel_negative else [])
        + [
            str(item)
            for item in profile.get("avoid", [])
            if clean_text(str(item))
        ]
        + [
            "不要把上一个主题的具体物件、场景和流程带入本期",
            "不要所有场景复用同一构图、同一背景或同一个主体姿势",
        ]
    )
    return {
        "generated_at": storage.now_ts(),
        "source_hash": visual_brief_source_hash(content),
        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
        "topic": topic,
        "channel": clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")),
        "mode": mode,
        "topic_type": topic_type,
        "topic_type_label": str(profile.get("label") or topic_type),
        "style": style,
        "domain": domain,
        "visual_world": str(profile.get("world") or ""),
        "subject_pool": [str(item) for item in profile.get("subjects", [])],
        "action_pool": [str(item) for item in profile.get("actions", [])],
        "attention_hooks": [str(item) for item in profile.get("hooks", [])],
        "channel_frame": compact_prompt_rule(channel_image_style_prompt(template) or str(template.get("visual_strategy") or ""), 220),
        "forbidden": forbidden[:6],
        "scene_count": len(scenes),
        "scenes": scenes,
    }


def visual_brief_source_hash(content: str) -> str:
    source = content_without_image_prompts(content or "")
    return hashlib.sha256(source.encode("utf-8", errors="ignore")).hexdigest()[:16]


def visual_brief_path(project_id: int) -> Path:
    return storage.project_file(project_id, "visual_brief.json")


def visual_director_path(project_id: int) -> Path:
    return storage.project_file(project_id, "visual_director.json")


def effective_visual_scene_count(project: dict[str, Any], fallback: int = 0) -> int:
    project_id = int(project.get("id") or 0)
    if project_id:
        timeline_path = storage.project_file(project_id, "audio/scene_timeline.json")
        content_path = storage.project_file(project_id, "content.md")
        timeline_fresh = timeline_path.exists() and (
            not content_path.exists() or timeline_path.stat().st_mtime + 0.5 >= content_path.stat().st_mtime
        )
        if timeline_fresh:
            timeline = storage.read_json(timeline_path, {})
            timeline_scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
            if isinstance(timeline_scenes, list) and timeline_scenes:
                return len(timeline_scenes)
        brief = storage.read_json(visual_brief_path(project_id), {})
        brief_scenes = brief.get("scenes") if isinstance(brief, dict) else []
        if isinstance(brief_scenes, list) and brief_scenes:
            return len(brief_scenes)
    return int(fallback or 0)


