def sound_signal_occurrences(source: str, token: str) -> int:
    if token.isascii() and re.fullmatch(r"[a-z0-9][a-z0-9_+.-]*", token):
        return len(re.findall(rf"(?<![a-z0-9]){re.escape(token)}(?![a-z0-9])", source))
    return source.count(token)


def sound_mood_decision(topic_type: str, style: str, domain: str, content: str) -> dict[str, Any]:
    weighted_sources = (
        (clean_text(topic_type).lower(), 2.4),
        (clean_text(domain).lower(), 2.0),
        (clean_text(style).lower(), 1.1),
        (clean_text(content)[:2400].lower(), 1.0),
    )
    scores: dict[str, float] = {key: 0.0 for key in SOUND_MOOD_PROFILES}
    evidence: dict[str, list[tuple[float, str]]] = {key: [] for key in SOUND_MOOD_PROFILES}
    for mood, signals in SOUND_MOOD_SIGNALS.items():
        for token, token_weight in signals:
            signal_score = 0.0
            for source, source_weight in weighted_sources:
                occurrences = min(2, sound_signal_occurrences(source, token))
                if occurrences:
                    signal_score += token_weight * source_weight * (1.0 + 0.2 * max(0, occurrences - 1))
            if signal_score:
                scores[mood] += signal_score
                evidence[mood].append((signal_score, token))
    ranked = sorted(scores.items(), key=lambda item: (-item[1], list(SOUND_MOOD_PROFILES).index(item[0])))
    mood, score = ranked[0] if ranked else ("story_soft", 0.0)
    if score <= 0:
        mood = "story_soft"
    matched = [token for _value, token in sorted(evidence.get(mood, []), reverse=True)[:4]]
    label = clean_text(str(SOUND_MOOD_PROFILES.get(mood, {}).get("label") or mood))
    reason = f"主题信号「{'、'.join(matched)}」更适合{label}" if matched else f"没有强题材信号，使用{label}为口播轻铺底"
    return {
        "mood": mood,
        "label": label,
        "score": round(float(score), 2),
        "matched_signals": matched,
        "reason": reason,
        "scores": {key: round(value, 2) for key, value in scores.items() if value > 0},
    }


def infer_sound_mood(topic_type: str, style: str, domain: str, content: str) -> str:
    return clean_text(str(sound_mood_decision(topic_type, style, domain, content).get("mood") or "story_soft"))


def scene_edit_pace(narrative_state: str, visual_type: str, dialogue_anchor: str) -> str:
    text = f"{narrative_state}\n{visual_type}\n{dialogue_anchor}"
    if "前三秒" in narrative_state:
        return "fast_hook"
    if "结论" in narrative_state or "互动" in narrative_state:
        return "hold_for_comment"
    if visual_type in {"mechanism_diagram", "data_card", "timeline"} or any(token in text for token in ("证据", "机制", "数据", "步骤")):
        return "slow_explain"
    if any(token in text for token in ("冲突", "误区", "反差", "真相", "但是", "结果")):
        return "medium_push"
    return "medium"


def scene_target_hold_seconds(pace: str, dialogue_anchor: str) -> float:
    chars = len(clean_text(dialogue_anchor))
    spoken_estimate = chars / 7.5 if chars else 6.0
    if pace == "fast_hook":
        return round(clamp_number(spoken_estimate, 3.0, 5.5), 1)
    if pace == "slow_explain":
        return round(clamp_number(spoken_estimate, 7.0, 13.0), 1)
    if pace == "hold_for_comment":
        return round(clamp_number(spoken_estimate, 5.0, 9.0), 1)
    if pace == "medium_push":
        return round(clamp_number(spoken_estimate, 5.0, 9.5), 1)
    return round(clamp_number(spoken_estimate, 5.5, 10.5), 1)


def director_motion_for_scene(visual_type: str, narrative_state: str, index: int) -> str:
    if index == 1 or "前三秒" in narrative_state:
        return "quick_push_in"
    if "结论" in narrative_state or "互动" in narrative_state:
        return "micro_zoom_then_hold"
    if visual_type == "timeline":
        return "slow_pan_left_to_right"
    if visual_type == "comparison":
        return "slow_pan_left_to_right"
    if visual_type == "mechanism_diagram":
        return "gentle_push_in"
    if visual_type == "data_card":
        return "micro_zoom_then_hold"
    if visual_type == "life_scene":
        return "slow_push_in"
    return "ken_burns_subtle"


def director_transition_for_scene(index: int, total: int, narrative_state: str, visual_type: str) -> str:
    if index == 1:
        return "hard_cut_from_cover"
    if index == total:
        return "soft_fade_to_end"
    if "机制" in narrative_state or visual_type in {"mechanism_diagram", "timeline", "data_card"}:
        return "hard_cut"
    return "hard_cut"


def build_edit_direction(visual_brief: dict[str, Any], content: str) -> dict[str, Any]:
    scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
    total = len(scenes)
    edit_scenes: list[dict[str, Any]] = []
    for idx, scene in enumerate(scenes, start=1):
        if not isinstance(scene, dict):
            continue
        narrative = clean_text(str(scene.get("narrative_state") or narrative_state_for_scene(idx, total)))
        visual_type = clean_text(str(scene.get("visual_type") or "editorial_collage"))
        dialogue_anchor = clean_text(str(scene.get("dialogue_anchor") or scene.get("beat") or ""))
        pace = scene_edit_pace(narrative, visual_type, dialogue_anchor)
        edit_scenes.append(
            {
                "index": idx,
                "narrative_state": narrative,
                "pace": pace,
                "target_hold_seconds": scene_target_hold_seconds(pace, dialogue_anchor),
                "motion": director_motion_for_scene(visual_type, narrative, idx),
                "transition": director_transition_for_scene(idx, total, narrative, visual_type),
                "cut_reason": "按口播信息转折切镜，避免平均 PPT 式停留",
                "subtitle_priority": "hook" if idx == 1 else ("interaction" if idx == total else "normal"),
            }
        )
    pace_values = [str(item.get("pace") or "") for item in edit_scenes]
    overall_pace = "fast_open_medium_body"
    if pace_values.count("slow_explain") >= max(2, len(pace_values) // 3):
        overall_pace = "explain_with_breath"
    if any(token in content for token in ("紧急", "爆", "崩了", "千万", "别急", "被骗")):
        overall_pace = "fast_warning"
    return {
        "overall_pace": overall_pace,
        "transition_policy": "少转场、硬切为主，只在结尾轻淡出；避免花哨转场抢口播",
        "opening_policy": "前三秒必须先给痛点、反差或结果，不要铺垫",
        "scene_count": len(edit_scenes),
        "scenes": edit_scenes,
    }


def build_sound_direction(visual_brief: dict[str, Any], content: str) -> dict[str, Any]:
    decision = sound_mood_decision(
        clean_text(str(visual_brief.get("topic_type") or "")),
        clean_text(str(visual_brief.get("style") or "")),
        clean_text(str(visual_brief.get("domain") or "")),
        content,
    )
    mood = clean_text(str(decision.get("mood") or "story_soft"))
    profile = SOUND_MOOD_PROFILES.get(mood, SOUND_MOOD_PROFILES["story_soft"])
    return {
        "bgm_policy_version": BGM_POLICY_VERSION,
        "bgm_mood": mood,
        "bgm_label": profile["label"],
        "bgm_reason": decision.get("reason"),
        "bgm_signals": decision.get("matched_signals", []),
        "bgm_confidence_score": decision.get("score", 0),
        "bgm_keywords": profile["keywords"],
        "bgm_volume": profile["volume"],
        "ducking": "口播优先；BGM 只做情绪底，不盖过人声",
        "energy_curve": profile["energy_curve"],
        "sound_effects": [
            "开头钩子可用极轻提示音",
            "关键反转处可用低频轻顿点",
            "不要在每次切图都加音效",
        ],
    }


def build_visual_director(project: dict[str, Any], template: dict[str, Any], content: str, visual_brief: dict[str, Any]) -> dict[str, Any]:
    edit_direction = build_edit_direction(visual_brief, content)
    sound_direction = build_sound_direction(visual_brief, content)
    return {
        "generated_at": storage.now_ts(),
        "source_hash": visual_brief_source_hash(content),
        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
        "topic": clean_text(str(project.get("topic_name") or visual_brief.get("topic") or first_heading(content) or "")),
        "channel": clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")),
        "mode": clean_text(str(template.get("mode") or project.get("template_mode") or "video")),
        "provider": clean_text(str(visual_brief.get("provider") or "rule-fallback")),
        "image_direction": {
            "topic_type": visual_brief.get("topic_type"),
            "topic_type_label": visual_brief.get("topic_type_label"),
            "visual_world": visual_brief.get("visual_world"),
            "subject_pool": visual_brief.get("subject_pool", []),
            "action_pool": visual_brief.get("action_pool", []),
            "attention_hooks": visual_brief.get("attention_hooks", []),
            "forbidden": visual_brief.get("forbidden", []),
        },
        "edit_direction": edit_direction,
        "sound_direction": sound_direction,
        "quality_targets": {
            "image_semantic_min": 68,
            "image_appeal_min": 70,
            "subtitle_coverage_min": 0.96,
            "avoid_prompt_meta": ["16:9", "4:3", "3:4", "第几张", "画幅要求", "视觉导演调试字段"],
        },
    }


def visual_director_is_current(director: dict[str, Any], content: str, scene_count: int = 0) -> bool:
    if not isinstance(director, dict) or not isinstance(director.get("edit_direction"), dict):
        return False
    if clean_text(str(director.get("prompt_policy_version") or "")) != IMAGE_PROMPT_POLICY_VERSION:
        return False
    if clean_text(str(director.get("source_hash") or "")) != visual_brief_source_hash(content):
        return False
    sound = director.get("sound_direction") if isinstance(director.get("sound_direction"), dict) else {}
    if clean_text(str(sound.get("bgm_policy_version") or "")) != BGM_POLICY_VERSION:
        return False
    if scene_count:
        edit = director.get("edit_direction") if isinstance(director.get("edit_direction"), dict) else {}
        if int(edit.get("scene_count") or 0) != scene_count:
            return False
        edit_scenes = edit.get("scenes") if isinstance(edit.get("scenes"), list) else []
        if len(edit_scenes) != scene_count:
            return False
    return True


def save_visual_director(
    project_id: int,
    content: str | None = None,
    *,
    visual_brief: dict[str, Any] | None = None,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    content_text = content if content is not None else storage.get_content(project_id)
    if visual_brief is None:
        existing_brief = storage.read_json(visual_brief_path(project_id), {})
        if visual_brief_is_current(existing_brief, project, content_text):
            visual_brief = existing_brief
        else:
            visual_brief = build_visual_brief(project, template, content_text)
    director = build_visual_director(project, template, content_text, visual_brief)
    storage.write_json(visual_director_path(project_id), director)
    return director


def get_or_create_visual_director(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    visual_brief: dict[str, Any],
) -> dict[str, Any]:
    project_id = int(project.get("id") or 0)
    if project_id:
        existing = storage.read_json(visual_director_path(project_id), {})
        if visual_director_is_current(existing, content, int(visual_brief.get("scene_count") or 0)):
            return existing
        return save_visual_director(project_id, content, visual_brief=visual_brief)
    return build_visual_director(project, template, content, visual_brief)


def visual_director_scene(project_id: int, index: int) -> dict[str, Any]:
    director = storage.read_json(visual_director_path(project_id), {})
    edit = director.get("edit_direction") if isinstance(director, dict) else {}
    scenes = edit.get("scenes") if isinstance(edit, dict) else []
    if not isinstance(scenes, list):
        return {}
    for scene in scenes:
        if isinstance(scene, dict) and int(scene.get("index") or 0) == index:
            return scene
    return scenes[index - 1] if 0 < index <= len(scenes) and isinstance(scenes[index - 1], dict) else {}


def director_bgm_volume(project_id: int, env: dict[str, str]) -> float:
    env_value = clean_text(env.get("BGM_VOLUME", ""))
    if env_value:
        with contextlib.suppress(Exception):
            return float(env_value)
    director = storage.read_json(visual_director_path(project_id), {})
    sound = director.get("sound_direction") if isinstance(director, dict) else {}
    with contextlib.suppress(Exception):
        return float(sound.get("bgm_volume"))
    return 0.18


def _text_list(value: Any, fallback: list[str] | None = None, limit: int = 6, item_limit: int = 80) -> list[str]:
    items: list[str] = []
    source = value if isinstance(value, list) else []
    for item in source:
        text = clean_text(str(item))
        if text:
            items.append(summarize_scene_text(text, item_limit))
    if not items and fallback:
        items = [summarize_scene_text(str(item), item_limit) for item in fallback if clean_text(str(item))]
    return dedupe_clauses(items)[:limit]


def _compact_visual_brief_for_prompt(brief: dict[str, Any]) -> dict[str, Any]:
    scenes = brief.get("scenes") if isinstance(brief.get("scenes"), list) else []
    return {
        "topic_type_label": brief.get("topic_type_label"),
        "visual_world": brief.get("visual_world"),
        "subject_pool": brief.get("subject_pool", [])[:5],
        "action_pool": brief.get("action_pool", [])[:5],
        "attention_hooks": brief.get("attention_hooks", [])[:5],
        "forbidden": brief.get("forbidden", [])[:5],
        "scenes": [
            {
                "index": item.get("index"),
                "narrative_state": item.get("narrative_state"),
                "beat": item.get("beat"),
                "dialogue_anchor": item.get("dialogue_anchor"),
                "primary_subjects": item.get("primary_subjects", [])[:3],
                "action_peak": item.get("action_peak"),
                "attention_hooks": item.get("attention_hooks", [])[:3],
            }
            for item in scenes[:12]
            if isinstance(item, dict)
        ],
    }


def channel_visual_memory(project_id: int, template_key: str, limit: int = 6) -> list[dict[str, Any]]:
    if not template_key:
        return []
    records: list[dict[str, Any]] = []
    try:
        projects = storage.list_projects()
    except OSError:
        return []
    for meta in projects:
        if len(records) >= limit:
            break
        if not isinstance(meta, dict):
            continue
        try:
            other_id = int(meta.get("id") or 0)
        except (ValueError, TypeError):
            continue
        if not other_id or other_id == project_id:
            continue
        if clean_text(str(meta.get("template") or "")) != template_key:
            continue
        brief = storage.read_json(visual_brief_path(other_id), {})
        if not isinstance(brief, dict) or not brief:
            continue
        scenes = brief.get("scenes") if isinstance(brief.get("scenes"), list) else []
        records.append(
            {
                "project_id": other_id,
                "topic": clean_text(str(meta.get("topic_name") or brief.get("topic") or "")),
                "status": clean_text(str(meta.get("last_job_status") or "")),
                "topic_type_label": clean_text(str(brief.get("topic_type_label") or "")),
                "visual_world": summarize_scene_text(str(brief.get("visual_world") or ""), 90),
                "subject_pool": _text_list(brief.get("subject_pool"), limit=4, item_limit=24),
                "attention_hooks": _text_list(brief.get("attention_hooks"), limit=4, item_limit=24),
                "forbidden": _text_list(brief.get("forbidden"), limit=4, item_limit=44),
                "scene_patterns": [
                    {
                        "state": scene.get("narrative_state"),
                        "subjects": scene.get("primary_subjects", [])[:3],
                        "action": scene.get("action_peak"),
                        "hooks": scene.get("attention_hooks", [])[:3],
                    }
                    for scene in scenes[:4]
                    if isinstance(scene, dict)
                ],
            }
        )
    return records


def compose_visual_director_messages(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    fallback: dict[str, Any],
    memory: list[dict[str, Any]],
) -> list[dict[str, str]]:
    visual_content = content_without_image_prompts(content or "")
    channel_payload = {
        "name": template.get("brand_name") or template.get("name") or project.get("template") or "",
        "target_audience": template.get("target_audience") or "",
        "voice": template.get("channel_voice") or "",
        "visual_strategy": template.get("visual_strategy") or "",
        "forbidden_rules": template.get("forbidden_rules") or "",
        "image_style_prompt": template.get("image_style_prompt") or "",
        "image_negative_prompt": template.get("image_negative_prompt") or "",
        "topic_mining_hint": template.get("topic_mining_hint") or "",
    }
    output_schema = {
        "topic_type": "short_snake_case",
        "topic_type_label": "中文主题视觉类型",
        "visual_world": "本期专属视觉世界，一句话，必须来自当前主题和正文",
        "subject_pool": ["本期可反复出现的真实主体/物件/空间"],
        "action_pool": ["本期可视化动作，不要泛泛写思考/讨论"],
        "attention_hooks": ["画面可用的短词/数字/冲突钩子，1-8字为主"],
        "forbidden": ["本期禁用的跑题元素，包含历史项目不可复制的元素"],
        "scenes": [
            {
                "index": 1,
                "narrative_state": "前三秒钩子/痛点",
                "visual_type": "life_scene/timeline/comparison/mechanism_diagram/data_card/editorial_collage",
                "beat": "本镜口播要点",
                "dialogue_anchor": "本镜对应口播锚点",
                "primary_subjects": ["本镜主主体1", "本镜主主体2"],
                "action_peak": "本镜能拍出来的瞬间动作",
                "attention_hooks": ["短词或数字"],
                "tension": "画面第一眼冲突/悬念",
            }
        ],
    }
    system = """
你是短视频工作流里的 AI 视觉导演，不是通用生图提示词模板。
你的任务是读取“频道定位 + 当前主题 + 当前 content.md 正文 + 历史视觉记忆”，输出一份本期专属 visual_brief JSON。

核心原则：
1. 频道只决定长期气质，当前主题和口播正文决定人物、空间、物件、动作和画面钩子。
2. 历史视觉记忆只能帮助你学习频道审美和避免重复，不允许复制上一期的具体场景、物件、流程和短词。
3. 只有口播里的新观点、数字、案例、转折或结论才单独切镜；纯过渡句沿用前一张图，不单独生成图片。每个重要镜头都要从对应口播中抽取不同的可视化证据，避免所有图都是同一个办公室、同一个人物、同一个屏幕光。
4. 是否使用文字、使用多少文字和信息元素，由当前口播的表达需要决定；数字、结论、批注、图表和关系线都可使用，但每项必须对应本镜口播且核心事实准确，不能复制无关长段正文。
5. 不要把历史项目、其它主题的固定流程、道具和画风套到无关主题；这条规则只用于避偏，不要写进最终图片提示词。
6. 只返回 JSON，不要 markdown，不要解释。
""".strip()
    user = {
        "current_project": {
            "id": project.get("id"),
            "topic": clean_text(str(project.get("topic_name") or first_heading(visual_content) or "")),
            "mode": clean_text(str(template.get("mode") or project.get("template_mode") or "video")),
        },
        "channel": channel_payload,
        "content_md_without_old_image_prompt": visual_content[:7000],
        "rule_fallback_scaffold": _compact_visual_brief_for_prompt(fallback),
        "channel_visual_memory_do_not_copy": memory,
        "required_scene_count": int(fallback.get("scene_count") or len(fallback.get("scenes") or [])),
        "output_schema": output_schema,
    }
    return [
        {"role": "system", "content": system},
        {"role": "user", "content": json.dumps(user, ensure_ascii=False, indent=2)},
    ]


def normalize_ai_visual_brief(
    payload: dict[str, Any],
    fallback: dict[str, Any],
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    model: str,
    memory_count: int,
) -> dict[str, Any]:
    fallback_scenes = fallback.get("scenes") if isinstance(fallback.get("scenes"), list) else []
    raw_scenes = payload.get("scenes") if isinstance(payload.get("scenes"), list) else []
    fallback_topic_type = clean_text(str(fallback.get("topic_type") or "general_editorial"))
    topic_guard_rejections: list[str] = []

    def guarded_items(value: Any, fallback_items: Any, *, limit: int, item_limit: int) -> list[str]:
        raw_items = _text_list(value, limit=limit, item_limit=item_limit)
        allowed: list[str] = []
        for item in raw_items:
            conflicts = visual_topic_conflict_hits(item, fallback_topic_type)
            if conflicts:
                topic_guard_rejections.append(f"{item} -> {','.join(conflicts)}")
                continue
            allowed.append(item)
        if allowed:
            return allowed[:limit]
        return _text_list(fallback_items, limit=limit, item_limit=item_limit)

    def guarded_text(value: Any, fallback_value: Any, limit: int) -> str:
        candidate = summarize_scene_text(str(value or ""), limit)
        conflicts = visual_topic_conflict_hits(candidate, fallback_topic_type)
        if conflicts:
            topic_guard_rejections.append(f"{candidate} -> {','.join(conflicts)}")
            return summarize_scene_text(str(fallback_value or ""), limit)
        return candidate or summarize_scene_text(str(fallback_value or ""), limit)

    normalized_scenes: list[dict[str, Any]] = []
    for idx, fallback_scene in enumerate(fallback_scenes, start=1):
        fallback_scene = fallback_scene if isinstance(fallback_scene, dict) else {}
        raw = raw_scenes[idx - 1] if idx - 1 < len(raw_scenes) and isinstance(raw_scenes[idx - 1], dict) else {}
        subjects = guarded_items(raw.get("primary_subjects"), fallback_scene.get("primary_subjects", []), limit=3, item_limit=24)
        hooks = _text_list(raw.get("attention_hooks"), fallback_scene.get("attention_hooks", []), limit=3, item_limit=12)
        normalized_scenes.append(
            {
                "index": idx,
                "narrative_state": clean_text(str(raw.get("narrative_state") or fallback_scene.get("narrative_state") or narrative_state_for_scene(idx, len(fallback_scenes)))),
                "visual_type": clean_text(str(raw.get("visual_type") or fallback_scene.get("visual_type") or "life_scene")),
                "beat": summarize_scene_text(str(raw.get("beat") or fallback_scene.get("beat") or ""), 92),
                "dialogue_anchor": summarize_scene_text(str(raw.get("dialogue_anchor") or fallback_scene.get("dialogue_anchor") or raw.get("beat") or fallback_scene.get("beat") or ""), 92),
                "primary_subjects": subjects,
                "action_peak": guarded_text(raw.get("action_peak"), fallback_scene.get("action_peak") or "一个正在发生的关键动作", 36),
                "attention_hooks": hooks,
                "tension": guarded_text(raw.get("tension"), fallback_scene.get("tension"), 90),
            }
        )

    subject_pool = guarded_items(payload.get("subject_pool"), fallback.get("subject_pool", []), limit=7, item_limit=26)
    action_pool = guarded_items(payload.get("action_pool"), fallback.get("action_pool", []), limit=7, item_limit=28)
    attention_hooks = _text_list(payload.get("attention_hooks"), fallback.get("attention_hooks", []), limit=7, item_limit=12)
    forbidden = dedupe_clauses(
        _text_list(payload.get("forbidden"), fallback.get("forbidden", []), limit=8, item_limit=50)
        + [
            "不要复制历史项目的具体场景、道具、短词和流程",
            "不要所有场景复用同一构图、同一背景或同一个主体姿势",
        ]
    )[:8]
    payload_topic_type = clean_text(str(payload.get("topic_type") or ""))
    topic_type = fallback_topic_type or payload_topic_type or "general_editorial"
    topic_label = clean_text(
        str(
            payload.get("topic_type_label")
            if not payload_topic_type or payload_topic_type == topic_type
            else fallback.get("topic_type_label")
        )
    ) or clean_text(str(fallback.get("topic_type_label") or topic_type))
    visual_world = guarded_text(payload.get("visual_world"), fallback.get("visual_world"), 120)
    return {
        **fallback,
        "generated_at": storage.now_ts(),
        "source_hash": visual_brief_source_hash(content),
        "provider": "deepseek-visual-director",
        "ai_model": model,
        "memory_count": memory_count,
        "topic_guard_rejections": dedupe_clauses(topic_guard_rejections)[:20],
        "topic": clean_text(str(project.get("topic_name") or fallback.get("topic") or "")),
        "channel": clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")),
        "topic_type": topic_type,
        "topic_type_label": topic_label,
        "visual_world": visual_world,
        "subject_pool": subject_pool,
        "action_pool": action_pool,
        "attention_hooks": attention_hooks,
        "forbidden": forbidden,
        "scene_count": len(normalized_scenes),
        "scenes": normalized_scenes,
    }


def generate_ai_visual_brief(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    fallback: dict[str, Any],
    memory: list[dict[str, Any]],
) -> dict[str, Any]:
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if not api_key:
        raise ContentGenerationError("DEEPSEEK_API_KEY 未配置，视觉导演使用规则兜底。")
    if OpenAI is None:
        raise ContentGenerationError("当前环境缺少 openai 依赖，视觉导演使用规则兜底。")
    base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
    model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
    thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
    reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
    client = OpenAI(api_key=api_key, base_url=base_url, timeout=30.0, max_retries=0)
    extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
    if thinking_type in {"enabled", "disabled"}:
        extra_body["thinking"] = {"type": thinking_type}
    try:
        response = client.chat.completions.create(
            model=model,
            messages=compose_visual_director_messages(project, template, content, fallback, memory),
            temperature=0.35,
            max_tokens=5000,
            extra_body=extra_body,
        )
    except APIConnectionError as exc:
        raise ContentGenerationError(f"连接 DeepSeek 视觉导演失败：{exc}") from exc
    except APIStatusError as exc:
        status_code = getattr(exc, "status_code", None)
        raise ContentGenerationError(f"调用 DeepSeek 视觉导演失败（HTTP {status_code or 'unknown'}）。") from exc
    except Exception as exc:
        raise ContentGenerationError(f"调用 DeepSeek 视觉导演失败：{exc}") from exc

    choice = response.choices[0] if getattr(response, "choices", None) else None
    raw = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
    payload = _safe_json_from_text(raw)
    if not payload:
        raise ContentGenerationError("DeepSeek 视觉导演没有返回可解析 JSON。")
    return normalize_ai_visual_brief(payload, fallback, project, template, content, model, len(memory))


def visual_brief_is_current(brief: dict[str, Any], project: dict[str, Any], content: str, scene_count: int = 0) -> bool:
    if not isinstance(brief, dict) or not brief.get("scenes"):
        return False
    if clean_text(str(brief.get("prompt_policy_version") or "")) != IMAGE_PROMPT_POLICY_VERSION:
        return False
    if clean_text(str(brief.get("source_hash") or "")) != visual_brief_source_hash(content):
        return False
    if scene_count and int(brief.get("scene_count") or 0) != scene_count:
        return False
    if scene_count:
        scenes = brief.get("scenes") if isinstance(brief.get("scenes"), list) else []
        if len(scenes) != scene_count:
            return False
    topic = clean_text(str(project.get("topic_name") or ""))
    return not topic or clean_text(str(brief.get("topic") or "")) == topic


def force_visual_brief_scene_count(brief: dict[str, Any], fallback: dict[str, Any], desired_count: int) -> dict[str, Any]:
    desired = max(0, int(desired_count or 0))
    if not desired:
        return brief
    scenes = brief.get("scenes") if isinstance(brief.get("scenes"), list) else []
    fallback_scenes = fallback.get("scenes") if isinstance(fallback.get("scenes"), list) else []
    normalized: list[dict[str, Any]] = []
    for index in range(desired):
        scene = scenes[index] if index < len(scenes) and isinstance(scenes[index], dict) else {}
        fallback_scene = fallback_scenes[index] if index < len(fallback_scenes) and isinstance(fallback_scenes[index], dict) else {}
        merged = {**fallback_scene, **scene}
        merged["index"] = index + 1
        if not clean_text(str(merged.get("narrative_state") or "")):
            merged["narrative_state"] = narrative_state_for_scene(index + 1, desired)
        normalized.append(merged)
    brief = dict(brief)
    brief["scene_count"] = len(normalized)
    brief["scenes"] = normalized
    return brief


def get_or_create_visual_brief(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    scene_count: int = 0,
    beats: list[str] | None = None,
    dialogue_anchors: list[str] | None = None,
    *,
    allow_ai: bool = False,
) -> dict[str, Any]:
    project_id = int(project.get("id") or 0)
    if project_id:
        existing = storage.read_json(visual_brief_path(project_id), {})
        if visual_brief_is_current(existing, project, content, scene_count):
            get_or_create_visual_director(project, template, content, existing)
            return existing
        if allow_ai:
            try:
                return save_visual_brief(project_id, content, scene_count=scene_count, beats=beats, dialogue_anchors=dialogue_anchors)
            except Exception:
                pass
    return build_visual_brief(project, template, content, scene_count=scene_count, beats=beats, dialogue_anchors=dialogue_anchors)

def save_visual_brief(
    project_id: int,
    content: str | None = None,
    scene_count: int = 0,
    beats: list[str] | None = None,
    dialogue_anchors: list[str] | None = None,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    content_text = content if content is not None else storage.get_content(project_id)
    fallback = build_visual_brief(project, template, content_text, scene_count=scene_count, beats=beats, dialogue_anchors=dialogue_anchors)
    memory = channel_visual_memory(project_id, template_key)
    try:
        brief = generate_ai_visual_brief(project, template, content_text, fallback, memory)
    except Exception as exc:
        brief = {
            **fallback,
            "provider": "rule-fallback",
            "memory_count": len(memory),
            "ai_error": clean_text(str(exc)),
        }
    brief = force_visual_brief_scene_count(brief, fallback, scene_count)
    director = save_visual_director(project_id, content_text, visual_brief=brief)
    brief["director_summary"] = {
        "visual_director_path": str(visual_director_path(project_id)),
        "overall_pace": director.get("edit_direction", {}).get("overall_pace") if isinstance(director.get("edit_direction"), dict) else "",
        "bgm_mood": director.get("sound_direction", {}).get("bgm_mood") if isinstance(director.get("sound_direction"), dict) else "",
        "bgm_label": director.get("sound_direction", {}).get("bgm_label") if isinstance(director.get("sound_direction"), dict) else "",
    }
    storage.write_json(visual_brief_path(project_id), brief)
    return brief


def filter_visual_hook_items(items: Iterable[Any], limit: int = 3) -> list[str]:
    hooks: list[str] = []
    for item in items:
        text = clean_visual_brief_fragment(str(item), 14).strip("「」“”\"'，。；:： ")
        if not text:
            continue
        if re.fullmatch(r"\d{1,2}", text):
            continue
        if any(term in text for term in IMAGE_PROMPT_META_POLLUTION_TERMS):
            continue
        if text not in hooks:
            hooks.append(text)
        if len(hooks) >= limit:
            break
    return hooks


def clean_visual_brief_fragment(value: Any, limit: int = 64) -> str:
    text = clean_text(str(value or ""))
    if not text:
        return ""
    text = text.replace("...", "").replace("…", "").strip("，,。；;:： ")
    for opener, closer in (("（", "）"), ("(", ")"), ("「", "」"), ("“", "”"), ("‘", "’"), ("'", "'"), ('"', '"')):
        if opener and text.count(opener) > text.count(closer):
            text = text.rsplit(opener, 1)[0].strip("，,。；;:： ")
    text = re.sub(r"[，,、]\s*$", "", text).strip("，,。；;:： ")
    if limit:
        text = truncate_visual_fragment(text, limit)
    return text


def truncate_visual_fragment(text: str, limit: int) -> str:
    source = clean_text(text)
    if not source or limit <= 0 or len(source) <= limit:
        return source
    window = source[:limit]
    for separator in ("。", "；", ";", "，", ",", "、"):
        cut = window.rfind(separator)
        if cut >= max(12, limit // 2):
            return window[:cut].strip("，,。；;:： ")
    cut = limit
    token_chars = re.compile(r"[A-Za-z0-9_.%℃°]")
    if cut < len(source) and token_chars.fullmatch(source[cut]) and token_chars.fullmatch(source[cut - 1]):
        while cut > 0 and token_chars.fullmatch(source[cut - 1]):
            cut -= 1
    if cut < max(12, limit // 2):
        cut = limit
    result = source[:cut].strip("，,。；;:： ")
    for opener, closer in (("（", "）"), ("(", ")"), ("「", "」"), ("“", "”"), ("‘", "’")):
        if result.count(opener) > result.count(closer):
            result = result.rsplit(opener, 1)[0].strip("，,。；;:： ")
    return result


def clean_visual_brief_list(items: Iterable[Any], limit: int = 44, count: int = 3) -> list[str]:
    cleaned: list[str] = []
    for item in items:
        value = clean_visual_brief_fragment(item, limit)
        if value and value not in cleaned:
            cleaned.append(value)
        if len(cleaned) >= count:
            break
    return cleaned


def visual_director_scene_clause(visual_brief: dict[str, Any], index: int) -> str:
    scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
    scene = scenes[index - 1] if 0 < index <= len(scenes) and isinstance(scenes[index - 1], dict) else {}
    subjects = "、".join(clean_visual_brief_list(scene.get("primary_subjects", []), 34, 3))
    hooks = "、".join(filter_visual_hook_items(scene.get("attention_hooks", []), 3))
    action = clean_visual_brief_fragment(scene.get("action_peak"), 44)
    parts = [
        f"主主体：{subjects or '本期核心主体'}",
        f"动作峰值：{action}" if action else "",
        f"画面短字：{hooks}" if hooks else "",
    ]
    return compact_prompt_rule("，".join(item for item in parts if clean_text(item)), 130)


def visual_director_cover_clause(visual_brief: dict[str, Any]) -> str:
    hooks = "、".join(filter_visual_hook_items(visual_brief.get("attention_hooks", []), 3))
    subjects = "、".join(clean_visual_brief_list(visual_brief.get("subject_pool", []), 34, 3))
    parts = [
        f"封面主主体：{subjects or '本期核心主体'}",
        f"第一眼短字：{hooks}" if hooks else "",
    ]
    return compact_prompt_rule("，".join(item for item in parts if clean_text(item)), 120)


def visual_director_scene_hint(visual_brief: dict[str, Any], index: int) -> str:
    scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
    scene = scenes[index - 1] if 0 < index <= len(scenes) and isinstance(scenes[index - 1], dict) else {}
    if not scene:
        return ""
    subjects = "、".join(clean_visual_brief_list(scene.get("primary_subjects", []), 34, 3))
    action = clean_visual_brief_fragment(scene.get("action_peak"), 48)
    tension = clean_visual_brief_fragment(scene.get("tension"), 48)
    hooks = "、".join(filter_visual_hook_items(scene.get("attention_hooks", []), 2))
    parts = [
        f"主体：{subjects}" if subjects else "",
        f"动作：{action}" if action else "",
        f"冲突：{tension}" if tension else "",
        f"短字：{hooks}" if hooks else "",
    ]
    return compact_prompt_rule("，".join(item for item in parts if clean_text(item)), 130)


def visual_director_scene_seed(visual_brief: dict[str, Any], index: int) -> str:
    scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
    scene = scenes[index - 1] if 0 < index <= len(scenes) and isinstance(scenes[index - 1], dict) else {}
    if not scene:
        return ""
    subjects = "、".join(clean_visual_brief_list(scene.get("primary_subjects", []), 34, 3))
    hooks = "、".join(filter_visual_hook_items(scene.get("attention_hooks", []), 3))
    parts = [
        clean_visual_brief_fragment(scene.get("beat"), 70),
        clean_visual_brief_fragment(scene.get("dialogue_anchor"), 70),
        f"主体={subjects}" if subjects else "",
        f"动作={clean_visual_brief_fragment(scene.get('action_peak'), 48)}" if clean_visual_brief_fragment(scene.get("action_peak"), 48) else "",
        f"冲突={clean_visual_brief_fragment(scene.get('tension'), 48)}" if clean_visual_brief_fragment(scene.get("tension"), 48) else "",
        f"短词/数字={hooks}" if hooks else "",
    ]
    return compact_prompt_rule("，".join(item for item in parts if clean_text(item)), 320)


def visual_director_cover_hint(visual_brief: dict[str, Any]) -> str:
    subjects = "、".join(clean_visual_brief_list(visual_brief.get("subject_pool", []), 34, 4))
    hooks = "、".join(filter_visual_hook_items(visual_brief.get("attention_hooks", []), 3))
    world = clean_visual_brief_fragment(visual_brief.get("visual_world"), 76)
    if not subjects and not hooks and not world:
        return ""
    parts = [
        f"封面主画面：{subjects}" if subjects else "",
        f"空间氛围：{world}" if world else "",
        f"短字钩子：{hooks}" if hooks else "",
    ]
    return compact_prompt_rule("，".join(item for item in parts if clean_text(item)), 130)


def image_target_scene_index(target: str, label: str = "") -> int:
    source = clean_text(f"{target} {label}")
    for pattern in (r"s[_-]?(\d{1,3})", r"场景\s*(\d{1,3})", r"scene[_-]?(\d{1,3})"):
        match = re.search(pattern, source, flags=re.IGNORECASE)
        if match:
            return max(0, int(match.group(1)))
    return 0


def _clean_visual_decision_item(value: Any, limit: int = 42) -> str:
    text = clean_text(str(value or ""))
    if not text:
        return ""
    text = re.sub(r"^(?:本期画面世界|画面要求|风格要求|限制|避免偏题|不要|禁止)\s*[:：]\s*", "", text)
    text = clean_generic_visual_clause(text) or text
    if any(term in text for term in IMAGE_PROMPT_META_POLLUTION_TERMS):
        return ""
    if text in IMAGE_ALIGNMENT_STOPWORDS:
        return ""
    return compact_visual_anchor_text(text, limit)


def _visual_decision_overlap(text: str, source: str) -> int:
    candidate = clean_text(text).lower()
    source_text = clean_text(source).lower()
    if not candidate or not source_text:
        return 0
    score = sum(2 for token in semantic_tokens(candidate, limit=10) if token and token in source_text)
    source_han = "".join(re.findall(r"[\u4e00-\u9fff]", source_text))
    fragments: set[str] = set()
    for run in re.findall(r"[\u4e00-\u9fff]{3,}", candidate):
        for width in (6, 5, 4, 3):
            if len(run) < width:
                continue
            fragments.update(run[index : index + width] for index in range(len(run) - width + 1))
    if source_han:
        score += min(4, sum(1 for fragment in fragments if fragment in source_han))
    return score


def visual_decision_pick(
    items: Any,
    source: str,
    *,
    limit: int = 3,
    item_limit: int = 42,
    require_overlap: bool = False,
) -> list[str]:
    raw_items = items if isinstance(items, list) else []
    source_text = clean_text(source).lower()
    scored: list[tuple[int, str]] = []
    for index, item in enumerate(raw_items):
        text = _clean_visual_decision_item(item, item_limit)
        if not text:
            continue
        overlap = _visual_decision_overlap(text, source_text)
        if require_overlap and not overlap:
            continue
        if overlap:
            score = 100 + overlap * 8 - index
        else:
            score = 40 - index
        scored.append((score, text))
    selected = [text for _score, text in sorted(scored, key=lambda pair: pair[0], reverse=True)]
    return dedupe_clauses(selected)[:limit]


def visual_decision_anchor_terms(source: str, visual_brief: dict[str, Any], *, limit: int = 8) -> list[str]:
    source_text = clean_text(source)
    candidates: list[str] = []
    candidates.extend(visual_callout_candidates(source_text, limit=6))
    candidates.extend(extract_scene_readable_callouts(source_text, limit=6))
    for token in semantic_tokens(source_text, limit=40):
        if len(token) < 2 or token in IMAGE_ALIGNMENT_STOPWORDS:
            continue
        if token in {"横向", "竖向", "封面", "场景图", "画面", "真实", "主体", "动作"}:
            continue
        candidates.append(token)
    for item in list(visual_brief.get("attention_hooks", []) or [])[:6]:
        cleaned = _clean_visual_decision_item(item, 12)
        if cleaned:
            candidates.append(cleaned)
    return dedupe_clauses(candidates)[:limit]


def visual_decision_layout(purpose: str, target: str, label: str) -> str:
    source = clean_text(f"{target} {label}")
    if purpose != "cover":
        return "横向电影分镜画面"
    if "portrait" in source or "竖" in source:
        return "竖向短视频封面画面"
    if "story" in source or "图文" in source:
        return "图文封面画面"
    return "横向视频封面画面"


def build_elastic_visual_decision(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    visual_brief: dict[str, Any],
    *,
    purpose: str,
    target: str,
    label: str,
    source_prompt: str,
    semantic_context: dict[str, Any],
) -> dict[str, Any]:
    topic = clean_text(str(project.get("topic_name") or visual_brief.get("topic") or first_heading(content) or ""))
    scene_index = image_target_scene_index(target, label)
    scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
    scene = scenes[scene_index - 1] if 0 < scene_index <= len(scenes) and isinstance(scenes[scene_index - 1], dict) else {}
    summary = summarize_content(content_without_image_prompts(content) or content, clean_text(str(template.get("mode") or project.get("template_mode") or "video")))
    speech = clean_text(str(semantic_context.get("speech") or ""))
    director_context = clean_text(str(semantic_context.get("visual_director") or ""))
    if purpose == "cover":
        dialogue_lines = parse_dialogue_lines(content_without_image_prompts(content) or content, clean_text(str(template.get("mode") or project.get("template_mode") or "video")))
        first_dialogue = strip_dialogue_speaker(dialogue_lines[0]) if dialogue_lines else ""
        cover_anchor_parts = []
        for value in (
            summary.get("publish_title") or summary.get("cover_subtitle") or topic,
            first_dialogue,
        ):
            cleaned_value = clean_text(str(value or ""))
            if not cleaned_value or "content.md" in cleaned_value.lower() or "brief.md" in cleaned_value.lower():
                continue
            cover_anchor_parts.append(cleaned_value)
        speech = summarize_scene_text("；".join(dedupe_clauses(cover_anchor_parts)), 58)
    source = "\n".join(
        item
        for item in (
            topic,
            speech,
            director_context,
            clean_text(str(scene.get("dialogue_anchor") or "")),
            clean_text(str(scene.get("beat") or "")),
            source_prompt,
            summary.get("cover_title") if purpose == "cover" else "",
            summary.get("cover_subtitle") if purpose == "cover" else "",
        )
        if clean_text(str(item))
    )
    authoritative_source = "\n".join(
        item
        for item in (
            topic,
            speech,
            clean_text(str(scene.get("dialogue_anchor") or "")),
            summary.get("cover_title") if purpose == "cover" else "",
            summary.get("cover_subtitle") if purpose == "cover" else "",
        )
        if clean_text(str(item))
    )
    if not authoritative_source:
        authoritative_source = source
    active_topic_type = clean_text(str(visual_brief.get("topic_type") or "general_editorial"))
    subjects = visual_decision_pick(
        scene.get("primary_subjects", []),
        authoritative_source,
        limit=3,
        require_overlap=True,
    )
    subjects = [item for item in subjects if not visual_topic_conflicts(item, active_topic_type)]
    if not subjects:
        subjects = visual_decision_pick(visual_brief.get("subject_pool", []), authoritative_source, limit=3)
        subjects = [item for item in subjects if not visual_topic_conflicts(item, active_topic_type)]
    actions = visual_decision_pick(
        [scene.get("action_peak")],
        authoritative_source,
        limit=1,
        item_limit=48,
        require_overlap=True,
    )
    fallback_actions = visual_decision_pick(visual_brief.get("action_pool", []), authoritative_source, limit=2, item_limit=48)
    actions = dedupe_clauses([*actions, *fallback_actions])[:2]
    actions = [item for item in actions if not visual_topic_conflicts(item, active_topic_type)]
    hooks = visual_decision_anchor_terms(authoritative_source, visual_brief, limit=6)
    world = _clean_visual_decision_item(visual_brief.get("visual_world"), 72)
    scene_tension = _clean_visual_decision_item(scene.get("tension"), 70)
    if scene_tension and (
        not _visual_decision_overlap(scene_tension, authoritative_source)
        or visual_topic_conflicts(scene_tension, active_topic_type)
    ):
        scene_tension = ""
    tension = scene_tension or _clean_visual_decision_item(
        infer_visual_tension(
            authoritative_source,
            clean_text(str(visual_brief.get("style") or "")),
            clean_text(str(scene.get("visual_type") or "")),
            purpose,
        ),
        70,
    )
    if purpose == "cover":
        if len(hooks) >= 2:
            tension = _clean_visual_decision_item(f"{hooks[0]}和{hooks[1]}形成反差，观众一眼看到{summarize_scene_text(topic, 24)}的疑问", 70)
        elif speech:
            tension = summarize_scene_text(speech, 70)
    if not tension:
        tension = summarize_scene_text(speech or source, 70)
    must_show = dedupe_clauses([*subjects, *hooks[:4]])[:7]
    return {
        "topic": topic,
        "purpose": purpose,
        "target": target,
        "label": label,
        "scene_index": scene_index,
        "topic_type": clean_text(str(visual_brief.get("topic_type_label") or visual_brief.get("topic_type") or "")),
        "layout": visual_decision_layout(purpose, target, label),
        "visual_world": world,
        "subjects": subjects,
        "action": actions[0] if actions else "",
        "secondary_action": actions[1] if len(actions) > 1 else "",
        "speech_anchor": summarize_scene_text(speech or clean_text(str(scene.get("dialogue_anchor") or "")), 76),
        "tension": tension,
        "must_show": must_show,
        "hook_words": hooks[:3],
        "channel_identity": clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")),
        "forbidden": dedupe_clauses([_clean_visual_decision_item(item, 34) for item in list(visual_brief.get("forbidden", []) or []) if clean_text(str(item))])[:5],
        "provider": clean_text(str(visual_brief.get("provider") or "rule-visual-decision")),
    }


def render_elastic_visual_prompt(decision: dict[str, Any]) -> str:
    purpose = clean_text(str(decision.get("purpose") or "scene"))
    layout = clean_text(str(decision.get("layout") or "短视频画面"))
    world = clean_text(str(decision.get("visual_world") or ""))
    subjects = [clean_text(str(item)) for item in decision.get("subjects", []) if clean_text(str(item))]
    must_show = [clean_text(str(item)) for item in decision.get("must_show", []) if clean_text(str(item))]
    hooks = [clean_text(str(item)) for item in decision.get("hook_words", []) if clean_text(str(item))]
    action = clean_text(str(decision.get("action") or ""))
    speech_anchor = clean_text(str(decision.get("speech_anchor") or ""))
    tension = clean_text(str(decision.get("tension") or ""))
    channel = clean_text(str(decision.get("channel_identity") or ""))

    subject_text = "、".join(subjects[:3]) or "本期核心人物和关键物件"
    parts = [layout]
    if world:
        parts.append(world)
    if action:
        parts.append(f"{subject_text}正在{action}")
    else:
        parts.append(f"{subject_text}处在同一个真实瞬间")
    if must_show:
        parts.append(f"关键可见物：{'、'.join(must_show[:6])}")
    if speech_anchor:
        parts.append(f"情节锚点：{speech_anchor}")
    if tension:
        parts.append(f"冲突悬念：{tension}")
    if hooks:
        if purpose == "cover":
            parts.append(f"画面短字只用：{'、'.join(hooks[:2])}")
        else:
            parts.append(f"可出现一个短数据或短标签：{'、'.join(hooks[:2])}")
    if purpose == "cover" and channel:
        parts.append(f"角落小号频道识别：{channel}")
    parts.append("真实摄影质感，人物表情和关键物件清楚，画面不含水印、二维码、品牌Logo和长段文字")
    return compact_visual_image_prompt("。".join(dedupe_clauses([item for item in parts if clean_text(item)])), 520 if purpose == "cover" else 460)


def elastic_visual_prompt_for_image(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    visual_brief: dict[str, Any],
    *,
    purpose: str,
    target: str,
    label: str,
    source_prompt: str,
    semantic_context: dict[str, Any],
) -> tuple[str, dict[str, Any]]:
    decision = build_elastic_visual_decision(
        project,
        template,
        content,
        visual_brief,
        purpose=purpose,
        target=target,
        label=label,
        source_prompt=source_prompt,
        semantic_context=semantic_context,
    )
    prompt = render_elastic_visual_prompt(decision)
    if not prompt:
        prompt = source_prompt
    return prompt, decision


