def extract_content_prompt_field(text: str, marker: str, limit: int = 140) -> str:
    source = normalize_image_prompt(text)
    start = source.find(f"{marker}：")
    sep_len = 1
    if start < 0:
        start = source.find(f"{marker}:")
    else:
        sep_len = 1
    if start < 0:
        return ""
    value_start = start + len(marker) + sep_len
    tail = source[value_start:]
    next_positions = []
    for next_marker in CONTENT_PROMPT_FIELD_MARKERS:
        if next_marker == marker:
            continue
        for prefix in (f"，{next_marker}：", f"，{next_marker}:", f"。{next_marker}：", f"。{next_marker}:"):
            pos = tail.find(prefix)
            if pos >= 0:
                next_positions.append(pos)
    end = min(next_positions) if next_positions else len(tail)
    value = tail[:end].strip(" ，,。；:：")
    return summarize_scene_text(value, limit)


def clean_distilled_prompt_field(value: str) -> str:
    cleaned = clean_text(value)
    if not cleaned:
        return ""
    cleaned = re.sub(r"^从本期专属主体里选一个压住画面[：:]?", "", cleaned).strip(" ，,。；:：")
    cleaned = cleaned.replace("...", "").replace("…", "")
    cleaned = re.sub(r"带[“\"「][^”\"」]{0,20}$", "", cleaned).strip(" ，,。；:：")
    if cleaned.count("“") > cleaned.count("”"):
        cleaned = cleaned.rsplit("“", 1)[0].strip(" ，,。；:：")
    if cleaned.count("（") > cleaned.count("）"):
        cleaned = cleaned.rsplit("（", 1)[0].strip(" ，,。；:：")
    return cleaned


def distill_content_authored_image_prompt(prompt: str, purpose: str) -> str:
    text = normalize_image_prompt(prompt)
    if not text:
        return ""
    is_cover = purpose == "cover"
    world = (
        extract_content_prompt_field(text, "频道质感", 90)
        or extract_content_prompt_field(text, "影像质感", 90)
        or extract_content_prompt_field(text, "本期画面世界", 90)
        or extract_content_prompt_field(text, "空间和氛围必须来自", 90)
    )
    if is_cover:
        cover_subject = clean_distilled_prompt_field(extract_content_prompt_field(text, "封面主主体", 150))
        cover_specific = clean_distilled_prompt_field(extract_content_prompt_field(text, "封面具体画面", 150))
        subject = cover_subject if "从本期专属主体" in extract_content_prompt_field(text, "封面具体画面", 150) else (cover_specific or cover_subject)
    else:
        subject = ""
    subject = (
        subject
        or extract_content_prompt_field(text, "主主体", 130)
        or extract_content_prompt_field(text, "本期专属画面", 110)
        or extract_content_prompt_field(text, "本镜头优先出现", 110)
    )
    subject = clean_distilled_prompt_field(subject)
    action = clean_distilled_prompt_field(
        extract_content_prompt_field(text, "动作", 100)
        or extract_content_prompt_field(text, "正在发生的动作", 100)
        or extract_content_prompt_field(text, "动作是", 100)
    )
    speech = (
        extract_content_prompt_field(text, "封面先画", 90)
        if is_cover
        else ""
    ) or extract_content_prompt_field(text, "口播原文", 180) or extract_content_prompt_field(text, "画面任务", 150) or extract_content_prompt_field(text, "对应口播原文", 180) or extract_content_prompt_field(text, "对应口播", 150) or extract_content_prompt_field(text, "画面先画", 150) or extract_content_prompt_field(text, "本镜头先画", 150)
    speech = clean_distilled_prompt_field(speech)
    conflict = clean_distilled_prompt_field(
        extract_content_prompt_field(text, "冲突/悬念", 110)
        or extract_content_prompt_field(text, "第一眼冲突", 110)
        or extract_content_prompt_field(text, "冲突悬念", 110)
    )
    hook = (
        extract_content_prompt_field(text, "封面第一眼短钩子", 42)
        or extract_content_prompt_field(text, "视觉钩子只用这些短词/数字之一", 42)
        if is_cover
        else ""
    ) or extract_content_prompt_field(text, "画面短字", 42) or extract_content_prompt_field(text, "短字", 42) or extract_content_prompt_field(text, "可读短标签", 42) or extract_content_prompt_field(text, "第一眼短钩子", 36)
    hook = clean_distilled_prompt_field(hook)
    camera = clean_distilled_prompt_field(extract_content_prompt_field(text, "镜头变化", 80))
    channel = clean_distilled_prompt_field(extract_content_prompt_field(text, "频道气质", 90))
    parts: list[str] = []
    if world:
        parts.append(world)
    if subject:
        parts.append(f"主画面：{subject}")
    if action:
        parts.append(f"正在发生：{action}")
    if speech and "口播原文" not in text and "对应口播原文" not in text:
        parts.append(f"{'封面钩子' if is_cover else '情节锚点'}：{speech}")
    if conflict:
        parts.append(f"冲突悬念：{conflict}")
    if hook:
        parts.append(f"画面短标签：{hook}")
    if camera:
        parts.append(camera)
    if channel:
        parts.append(channel)
    if not parts:
        return ""
    parts.append("真实摄影质感，主体清楚，屏幕和数据只做短标签或可视化光牌，画面留出字幕空间")
    return compact_visual_image_prompt("。".join(dedupe_clauses(parts)).replace("...", "").replace("…", ""), 760 if purpose == "scene" else 760)


def light_clean_content_image_prompt(prompt: str, purpose: str) -> str:
    text = normalize_image_prompt(strip_image_prompt_workflow_rules(prompt))
    if not text:
        return ""
    if purpose == "scene" and is_semantic_scene_generation_brief(text):
        return text
    distilled = distill_content_authored_image_prompt(text, purpose)
    if distilled:
        return distilled
    text = re.sub(r"避免偏题[:：].*?(?=，(?:本镜头先画|对应口播|本期专属画面|正在发生的动作|第一眼冲突|镜头变化|叙事阶段|频道气质)|。|$)", "", text)
    text = re.sub(r"不要引入本期专属画面未列出的题材流程、人物关系或道具[，。；;]?", "", text)
    text = re.sub(r"只允许少量短词/数字[:：]", "画面短标签：", text)
    text = re.sub(r"画面可.*?每张图都要有不同的主体动.*?(?=。|$)", "", text)
    text = re.sub(r"历史项目中的[^，。；;]*[，。；;]?", "", text)
    text = re.sub(r"\b\d+\s*[:：]\s*\d+\b", "", text)
    text = re.sub(r"\b\d{3,4}\s*[x×]\s*\d{3,4}\b", "", text)
    text = text.replace("...", "").replace("…", "")
    text = re.sub(r"第\s*\d+\s*张(?:场景图|正文配图|图片|图)?", "", text)
    text = re.sub(r"(?:请)?(?:直接)?生成(?:一张)?", "", text)
    text = re.sub(r"(?:画幅|尺寸|比例)\s*要求\s*[:：]?", "", text)
    text = re.sub(r"(?:场景图|封面图|图片提示词)\s*[:：]?", "", text)
    text = re.sub(r"\s+", " ", text).strip(" ，,。；:：")
    return compact_visual_image_prompt(text, 980 if purpose == "scene" else 860)


def source_first_image_prompt(original: str, elastic_prompt: str, purpose: str) -> str:
    original_is_authored = is_content_authored_image_prompt(original)
    source = light_clean_content_image_prompt(original, purpose)
    elastic = normalize_image_prompt(elastic_prompt)
    if not source:
        return elastic
    if original_is_authored:
        return source
    if not is_content_authored_image_prompt(source):
        source_score = int(prompt_visual_score(source, purpose).get("score", 0) or 0)
        elastic_score = int(prompt_visual_score(elastic, purpose).get("score", 0) or 0) if elastic else 0
        if elastic and elastic_score > source_score + 12:
            return elastic
    supplements: list[str] = []
    for clause in split_prompt_clauses(elastic):
        cleaned = clean_text(clause)
        if not cleaned:
            continue
        if any(marker in cleaned for marker in ("关键可见物", "情节锚点", "冲突悬念")):
            marker = cleaned.split("：", 1)[0].split(":", 1)[0]
            if marker and marker not in source:
                supplements.append(cleaned)
    merged = "。".join([source, *supplements[:2]])
    return compact_visual_image_prompt(merged, 980 if purpose == "scene" else 860)


def _contains_any(source: str, keywords: tuple[str, ...]) -> bool:
    return any(keyword in source for keyword in keywords)


