def read_generated_prompt(output_path: Path, fallback: str = "") -> str:
    prompt = storage.read_text(output_path.with_suffix(".md")).strip()
    purpose = "cover" if output_path.parent.name == "covers" or output_path.name.startswith("cover_") else "scene"
    return sanitize_prompt_for_image_model(prompt or fallback, purpose) or normalize_image_prompt(fallback)


def composer_scene_prompt(prompt: str) -> str:
    expanded = expand_scene_prompt_shorthand(prompt, {})
    clauses = split_dense_prompt_clauses(expanded)
    visual_clauses: list[str] = []
    for clause in clauses:
        rewritten = neutralize_materialized_style(abstract_textual_clause(clause, "scene"))
        if not rewritten:
            continue
        if any(token in rewritten for token in ("不出现", "不渲染", "不要", "不可读", "水印", "脚注", "字幕")):
            continue
        visual_clauses.append(rewritten)
    dialogue_hint = extract_prompt_dialogue_hint(expanded, 52)
    anchor_details = visual_anchor_details(expanded, "scene")
    if dialogue_hint and not anchor_details:
        anchor_details.append(f"本张场景的核心瞬间必须来自口播：{dialogue_hint}")
    if not visual_clauses:
        visual_clauses = ["知识短视频场景图，主体明确，结构关系清晰，画面有强对比和空间层次"]
    return compact_visual_image_prompt("；".join(dedupe_clauses(anchor_details + visual_clauses)[:5]), limit=260)


def composer_scene_prompts(project_id: int, scene_paths: list[Path], fallback_prompts: list[str]) -> list[str]:
    prompt_records = storage.read_json(storage.project_file(project_id, "scenes/scene_prompts.json"), [])
    by_filename: dict[str, str] = {}
    if isinstance(prompt_records, list):
        for item in prompt_records:
            if not isinstance(item, dict):
                continue
            filename = clean_text(str(item.get("filename", "")))
            prompt = clean_text(str(item.get("prompt") or item.get("source_prompt") or ""))
            if filename and prompt:
                by_filename[filename] = prompt
    prompts: list[str] = []
    for idx, path in enumerate(scene_paths):
        source = by_filename.get(path.name)
        if not source and idx < len(fallback_prompts):
            source = fallback_prompts[idx]
        prompts.append(composer_scene_prompt(source or ""))
    return prompts


def expand_scene_prompt_shorthand(prompt: str, template: dict[str, Any]) -> str:
    text = normalize_image_prompt(prompt)
    if not text:
        return text
    brand_marker = template_brand_marker(template)
    footer_marker = template_footer_marker(template)
    replacements = [
        (r"左上角品牌位\+小(?:标签|图章|邮戳)", brand_marker),
        (r"品牌位\+小(?:标签|图章|邮戳)", brand_marker),
        (r"左上角品牌位", brand_marker),
        (r"底部极小字免责文字", footer_marker),
        (r"底部小字免责文字", footer_marker),
        (r"底部免责小字", footer_marker),
        (r"底部免责文字", footer_marker),
    ]
    for pattern, replacement in replacements:
        if replacement:
            text = re.sub(pattern, replacement, text)
    return text


def apply_apiyi_prompt_conventions(prompt: str, size: str, purpose: str = "scene") -> str:
    clean_prompt = sanitize_prompt_for_image_model(prompt, purpose)
    if not clean_prompt:
        return clean_prompt
    if re.search(r"(\d+\s*[:：]\s*\d+)|(\d{3,4}\s*[x×]\s*\d{3,4})|方形|横版|竖版", clean_prompt):
        return clean_prompt
    hint = build_apiyi_size_hint(size)
    if not hint:
        return clean_prompt
    return f"{hint}，{clean_prompt}"


def normalize_image_prompt(prompt: str) -> str:
    text = strip_image_prompt_workflow_rules(prompt or "").strip()
    text = re.sub(r"\*\*(.*?)\*\*", r"\1", text)
    text = re.sub(r"`+", "", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


def _count_small_dark_components(region_gray: Any, threshold: float) -> int:
    if np is None:
        return 0
    dark = np.asarray(region_gray < threshold, dtype=bool)
    height, width = dark.shape
    visited = np.zeros((height, width), dtype=bool)
    components = 0
    for y in range(height):
        for x in range(width):
            if not dark[y, x] or visited[y, x]:
                continue
            stack = [(y, x)]
            visited[y, x] = True
            area = 0
            while stack:
                cy, cx = stack.pop()
                area += 1
                if area > 800:
                    break
                for ny in range(max(0, cy - 1), min(height, cy + 2)):
                    for nx in range(max(0, cx - 1), min(width, cx + 2)):
                        if not visited[ny, nx] and dark[ny, nx]:
                            visited[ny, nx] = True
                            stack.append((ny, nx))
            if 6 <= area <= 400:
                components += 1
    return components


_RAPID_OCR_ENGINE: Any = None


def extract_numeric_fact_tokens(text: str) -> list[str]:
    values: list[str] = []
    source = clean_text(text)
    for chinese_percent in re.findall(r"百分之([零一二两三四五六七八九十百千万]+)", source):
        value = chinese_integer_value(chinese_percent)
        if value is not None:
            values.append(f"{value}%")
    token_pattern = re.compile(
        r"(?:"
        r"\d+(?:\.\d+)?\s*(?:个)?\s*"
        r"(?:mAh|Ah|mWh|Wh|kWh|mW|kW|W|mV|V|mA|A|GHz|MHz|kHz|Hz|GB|TB|MB|KB|"
        r"毫安时|毫安|安时|安|毫瓦时|瓦时|千瓦时|毫瓦|千瓦|瓦|毫伏|伏|"
        r"摄氏度|℃|°C|秒|分钟|小时|天|周|月|季度|年|字|%|元|块|万|亿|次|倍|家|人|条|款|台)?"
        r"|[零一二两三四五六七八九十百千万几]+\s*(?:个)?\s*"
        r"(?:万毫安时|万毫安|毫安时|毫安|安时|安|毫瓦时|瓦时|千瓦时|毫瓦|千瓦|瓦|毫伏|伏|"
        r"摄氏度|秒|分钟|小时|天|周|月|季度|年|字|元|块|万|亿|次|倍|家|人|条|款|台)"
        r")",
        flags=re.IGNORECASE,
    )
    for match in token_pattern.finditer(source):
        value = clean_text(match.group(0))
        if not value or not re.search(r"\d|[零一二两三四五六七八九十百千万几]", value):
            continue
        following = source[match.end() : match.end() + 4]
        if value.endswith("块") and following.startswith(("表", "手表", "屏幕", "玻璃", "面板", "牌子")):
            continue
        if value not in values:
            values.append(value)
    return values


def chinese_integer_value(text: str) -> int | None:
    source = clean_text(text)
    if not source or not re.fullmatch(r"[零一二两三四五六七八九十百千万]+", source):
        return None
    digits = {"零": 0, "一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    if not any(char in source for char in "十百千万"):
        return int("".join(str(digits[char]) for char in source))
    total = 0
    section = 0
    number = 0
    for char in source:
        if char in digits:
            number = digits[char]
            continue
        unit = {"十": 10, "百": 100, "千": 1000, "万": 10000}[char]
        if unit == 10000:
            section = (section + number) * unit
            total += section
            section = 0
            number = 0
        else:
            section += (number or 1) * unit
            number = 0
    return total + section + number


def normalized_numeric_fact(token: str) -> str:
    source = re.sub(r"\s+|个", "", clean_text(token))
    percent_match = re.fullmatch(r"百分之([零一二两三四五六七八九十百千万]+)", source)
    if percent_match:
        value = chinese_integer_value(percent_match.group(1))
        return f"{value}%" if value is not None else source
    number_match = re.fullmatch(r"([零一二两三四五六七八九十百千万几]+)(秒|分钟|小时|天|年|字|元|块|万|亿|次|倍)?", source)
    if number_match:
        value = chinese_integer_value(number_match.group(1))
        if value is not None:
            return f"{value}{number_match.group(2) or ''}"
    unit_aliases = {
        "mah": "mAh",
        "ah": "Ah",
        "mwh": "mWh",
        "wh": "Wh",
        "kwh": "kWh",
        "mw": "mW",
        "kw": "kW",
        "w": "W",
        "mv": "mV",
        "v": "V",
        "ma": "mA",
        "a": "A",
        "ghz": "GHz",
        "mhz": "MHz",
        "khz": "kHz",
        "hz": "Hz",
        "gb": "GB",
        "tb": "TB",
        "mb": "MB",
        "kb": "KB",
    }
    technical_match = re.fullmatch(
        r"(.+?)(mAh|Ah|mWh|Wh|kWh|mW|kW|W|mV|V|mA|A|GHz|MHz|kHz|Hz|GB|TB|MB|KB)",
        source,
        flags=re.IGNORECASE,
    )
    if technical_match:
        unit = unit_aliases.get(technical_match.group(2).lower(), technical_match.group(2))
        return f"{technical_match.group(1)}{unit}"
    return source


def numeric_fact_equivalence_keys(token: str) -> set[str]:
    normalized = normalized_numeric_fact(token)
    keys = {normalized} if normalized else set()
    match = re.search(r"(\d+(?:\.\d+)?)(万|亿)?", normalized)
    if not match:
        return keys
    number = float(match.group(1))
    scale = {"万": 10_000, "亿": 100_000_000}.get(match.group(2) or "", 1)
    magnitude = number * scale
    magnitude_text = str(int(magnitude)) if magnitude.is_integer() else f"{magnitude:.8f}".rstrip("0").rstrip(".")
    keys.add(f"#value:{magnitude_text}")
    return keys


def numeric_fact_alignment(expected_facts: Iterable[str], detected_facts: Iterable[str]) -> dict[str, Any]:
    expected = sorted(
        {
            normalized_numeric_fact(str(item))
            for item in expected_facts
            if normalized_numeric_fact(str(item))
        }
    )
    detected = sorted(
        {
            normalized_numeric_fact(str(item))
            for item in detected_facts
            if normalized_numeric_fact(str(item))
        }
    )

    def matches(expected_item: str, detected_item: str) -> bool:
        if expected_item == detected_item:
            return True
        expected_cores = re.findall(r"\d+(?:\.\d+)?", expected_item)
        detected_cores = re.findall(r"\d+(?:\.\d+)?", detected_item)
        return any(
            expected_core == detected_core and len(re.sub(r"\D", "", expected_core)) >= 2
            for expected_core in expected_cores
            for detected_core in detected_cores
        )

    matched = [
        expected_item
        for expected_item in expected
        if any(matches(expected_item, detected_item) for detected_item in detected)
    ]
    missing = [item for item in expected if item not in matched]
    coverage = int(round((len(matched) / len(expected)) * 100)) if expected else 0
    return {
        "expected": expected,
        "detected": detected,
        "matched": matched,
        "missing": missing,
        "coverage_score": coverage,
    }


def image_audit_expected_numeric_facts(prompt: str) -> set[str]:
    source = clean_text(prompt)
    fact_lock_match = re.search(
        r"不可改错的数字事实\s*[:：]\s*(.+?)(?=\s+(?:创作边界|创作自由|文字策略|直接选择)\s*[:：]|$)",
        source,
    )
    explicit_fact_lock = clean_text(fact_lock_match.group(1)) if fact_lock_match else ""
    facts = {normalized_numeric_fact(item) for item in extract_numeric_fact_tokens(source)}
    if "1次" in facts and "1次" not in source and "一次" not in explicit_fact_lock:
        facts.discard("1次")
    return {item for item in facts if item}


def ocr_prompt_text_overlap_score(ocr_text: str, prompt: str) -> int:
    base_score = token_overlap_score(ocr_text, prompt, limit=80)
    candidate_han = "".join(re.findall(r"[\u4e00-\u9fff]", clean_text(ocr_text)))
    source_han = "".join(re.findall(r"[\u4e00-\u9fff]", clean_text(prompt)))
    if len(candidate_han) < 2 or len(source_han) < 2:
        return base_score
    candidate_bigrams = {
        candidate_han[index : index + 2]
        for index in range(len(candidate_han) - 1)
    }
    source_bigrams = {
        source_han[index : index + 2]
        for index in range(len(source_han) - 1)
    }
    hits = len(candidate_bigrams.intersection(source_bigrams))
    fragment_score = int(round((hits / max(1, min(len(candidate_bigrams), 10))) * 100))
    return max(base_score, min(100, fragment_score))


def normalized_visual_text(value: str) -> str:
    return re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", clean_text(value)).lower()


def visual_text_completeness_report(
    expected: str,
    ocr_text: str,
    ocr_lines: Sequence[str] | None = None,
) -> dict[str, Any]:
    normalized_expected = normalized_visual_text(expected)
    normalized_ocr = normalized_visual_text(ocr_text)
    if not normalized_expected:
        return {
            "expected": clean_text(expected),
            "normalized_expected": "",
            "matched_text": "",
            "ratio": 1.0,
            "coverage": 1.0,
            "score": 100,
            "missing_fragments": [],
            "passed": True,
        }

    candidates: list[str] = []
    for value in [*(ocr_lines or []), ocr_text]:
        normalized = normalized_visual_text(value)
        if normalized and normalized not in candidates:
            candidates.append(normalized)

    best = {
        "matched_text": "",
        "ratio": 0.0,
        "coverage": 0.0,
        "score": 0,
        "missing_fragments": [normalized_expected],
        "passed": False,
    }
    expected_length = len(normalized_expected)
    for candidate in candidates:
        if normalized_expected in candidate:
            return {
                "expected": clean_text(expected),
                "normalized_expected": normalized_expected,
                "matched_text": normalized_expected,
                "ratio": 1.0,
                "coverage": 1.0,
                "score": 100,
                "missing_fragments": [],
                "passed": True,
            }

        windows = [candidate]
        if len(candidate) > expected_length + 4:
            minimum = max(1, expected_length - 2)
            maximum = min(len(candidate), expected_length + 2)
            windows = []
            for window_length in range(minimum, maximum + 1):
                for start in range(0, len(candidate) - window_length + 1):
                    windows.append(candidate[start : start + window_length])
        for window in windows:
            matcher = difflib.SequenceMatcher(None, normalized_expected, window)
            ratio = float(matcher.ratio())
            matched_positions: set[int] = set()
            for block in matcher.get_matching_blocks():
                matched_positions.update(range(block.a, block.a + block.size))
            coverage = len(matched_positions) / max(1, expected_length)
            score = int(round((ratio * 0.45 + coverage * 0.55) * 100))
            missing_fragments: list[str] = []
            current: list[str] = []
            for index, character in enumerate(normalized_expected):
                if index in matched_positions:
                    if current:
                        missing_fragments.append("".join(current))
                        current = []
                    continue
                current.append(character)
            if current:
                missing_fragments.append("".join(current))
            passed = bool(ratio >= 0.88 and coverage >= 0.90)
            if score > int(best["score"]):
                best = {
                    "matched_text": window,
                    "ratio": round(ratio, 4),
                    "coverage": round(coverage, 4),
                    "score": score,
                    "missing_fragments": missing_fragments,
                    "passed": passed,
                }

    return {
        "expected": clean_text(expected),
        "normalized_expected": normalized_expected,
        **best,
    }


def required_scene_information_text(prompt: str) -> list[str]:
    source = normalize_image_prompt(prompt)
    candidates: list[str] = []
    patterns = (
        r"画面主信息\s*[:：][^「]{0,80}「([^」]{2,160})」",
        r"画面原生文字\s*[:：][^「]{0,80}「([^」]{2,160})」",
        r"必须落进成图的信息\s*[:：][^「]{0,80}「([^」]{2,160})」",
        r"(?:AI|模型)原生主标题\s*「([^」]{2,160})」",
        r"后期原生主标题\s*「([^」]{2,160})」",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source):
            value = clean_text(match.group(1)).strip("「」“”\"'，。；:： ")
            if value and value != "本镜核心结论" and value not in candidates:
                candidates.append(value)
    fact_match = re.search(
        r"(?:必须呈现的事实词|事实词原样呈现|模型原生事实文字|AI直接画入图片的文字|后期原生事实词)\s*[:：]?\s*「?(.+?)」?(?=(?:[。；]\s*|\n+)(?:信息构图模式|静音验收|来源边界|不可改错的数字事实|数字边界|创作边界)|$)",
        source,
    )
    if fact_match:
        for raw in re.split(r"[、，,；;]+", fact_match.group(1)):
            value = clean_text(raw).strip("「」“”\"'，。；:： ")
            value = re.sub(r"按当前口播关系.*$", "", value).strip()
            if len(value) >= 2 and value not in candidates:
                candidates.append(value)
    return candidates


def scene_exact_typography_payload(prompt: str) -> dict[str, Any]:
    required = required_scene_information_text(prompt)
    headline = clean_text(required[0]).strip("「」“”\"'，。；:：、（）()[]【】 ") if required else ""
    excluded_fragments = (
        "金额",
        "比例",
        "读数",
        "核心结论",
        "当前口播",
        "事实词",
        "信息牌",
        "按当前",
    )
    fact_chips: list[str] = []
    for raw in required[1:]:
        value = clean_scene_callout_item(raw)
        if (
            not value
            or value == headline
            or any(fragment in value for fragment in excluded_fragments)
            or value in fact_chips
        ):
            continue
        fact_chips.append(value)
    return {
        "headline": headline,
        "fact_chips": fact_chips,
        "all_text": [item for item in [headline, *fact_chips] if item],
    }


def image_exact_typography_payload(prompt: str, purpose: str) -> dict[str, Any]:
    if purpose == "cover":
        title = clean_text(extract_cover_title_hint(prompt))
        subtitle = clean_text(extract_cover_subtitle_hint(prompt))
        return {
            "headline": title,
            "subtitle": subtitle,
            "fact_chips": [],
            "all_text": [item for item in (title, subtitle) if item],
        }
    if purpose == "scene":
        return scene_exact_typography_payload(prompt)
    return {"headline": "", "subtitle": "", "fact_chips": [], "all_text": []}


def reserve_exact_typography_area(prompt: str, purpose: str, payload: dict[str, Any]) -> str:
    headline = clean_text(str(payload.get("headline") or ""))
    if purpose in {"scene", "cover"}:
        source = normalize_image_prompt(prompt)
        all_text = [
            clean_text(str(item))
            for item in payload.get("all_text", [])
            if clean_text(str(item))
        ]
        if purpose == "cover":
            native_clause = (
                f"AI原生封面文字：{'；'.join(all_text)}；由生图模型在同一次成图中直接完整写入，"
                "主标题必须是缩略图状态下仍清晰可读的最大视觉块，可自然换行，禁止省略、截断、乱码或改写；"
                "文字与主题主体共同构图，不预留空白标题框，不追加后期标题板"
            )
        else:
            native_clause = (
                f"AI原生画面文字：{'；'.join(all_text)}；由生图模型直接完整写入，可自然换行，不设统一字数上限，禁止截断和乱码"
                if all_text
                else "AI原生画面文字：根据当前完整口播自行提炼并直接写入图片，文字与主体共同构图，不追加后期标题板"
            )
        return normalize_image_prompt(f"{source}。{native_clause}")
    if purpose != "scene" and not headline:
        return normalize_image_prompt(prompt)
    source = normalize_image_prompt(prompt)
    text_render_terms = (
        (
            "封面主标题",
            "封面短副标题",
            "标题放在",
            "标题安全区",
            "文字主导",
            "可读文字",
            "主标题是最大视觉块",
            "文字与主体",
            "短字钩子",
            "画面短标签",
        )
        if purpose == "cover"
        else (
            "画面主信息",
            "必须落进成图的信息",
            "必须呈现的事实词",
            "事实词原样呈现",
            "后期文字元数据",
            "后期原生主标题",
            "后期原生事实词",
            "本镜只突出一个可读信息锚点",
            "是否使用文字及文字数量",
            "可参考的口播信息",
            "画面短标签",
        )
    )
    clauses = re.split(r"(?<=[。；;\n])", source)
    visual_only_clauses = [
        clause.strip()
        for clause in clauses
        if clause.strip() and not any(term in clause for term in text_render_terms)
    ]
    source = "".join(visual_only_clauses).strip()
    fact_count = len(payload.get("fact_chips") or [])
    role = "封面标题" if purpose == "cover" else "镜头主信息"
    reserve_height = "约画面高度的35%" if fact_count else "约画面高度的28%"
    directive = (
        f"构图协作（最高优先级）：{role}会由后期准确写入，但底图必须先生成与场景材质一致的信息承载面，"
        "例如屏幕、单据、墙面标记、刻度带或空间留白；不要生成错误文字、乱码；AI 底图不得生成任何可读中文、英文或数字、Logo、水印或孤立空白框。"
        f"承载面约占画面高度的{reserve_height.replace('约画面高度的', '')}，与主体动作、关键物件、关系箭头、"
        "图形证据和光影组成完整视觉动线，不做统一黑条或硬贴标签。"
    )
    # Keep the reservation marker intact until the one true outbound compiler runs.
    # Calling compact_visual_image_prompt here would recursively compile semantic
    # scene briefs and could drop the high-priority typography contract.
    return normalize_image_prompt("\n".join([source, directive]))


def scene_information_ocr_report(ocr_text: str, prompt: str) -> dict[str, Any]:
    required = required_scene_information_text(prompt)
    reports = {
        item: visual_text_completeness_report(item, ocr_text)
        for item in required
    }
    scores = {item: int(report.get("score", 0) or 0) for item, report in reports.items()}
    headline = required[0] if required else ""
    headline_score = int(scores.get(headline, 0) or 0)
    matched = [
        item
        for item, item_report in reports.items()
        if bool(item_report.get("passed"))
    ]
    return {
        "required": required,
        "headline": headline,
        "headline_score": headline_score,
        "headline_completeness": reports.get(headline, {}),
        "completeness": reports,
        "matched": matched,
        "missing": [item for item in required if item not in matched],
        "passed": not required or bool(reports.get(headline, {}).get("passed")),
    }


def foreign_scene_numeric_facts(text: str, context: dict[str, Any]) -> list[str]:
    # Prompt scaffolding is an instruction, not an episode fact.  Phrases such
    # as "观众1秒必须看懂" used to be misclassified as invented scene data and
    # could stop the whole full-auto pipeline before the image provider ran.
    text = (
        clean_text(text)
        .replace("观众1秒必须看懂", "观众必须立即看懂")
        .replace("一秒抓人", "立即抓人")
        .replace("1秒抓人", "立即抓人")
    )
    allowed_source = clean_text(
        f"{context.get('audio_anchor', '')} {context.get('speech', '')} {context.get('fact_source', '')}"
    )
    allowed = {normalized_numeric_fact(item) for item in extract_numeric_fact_tokens(allowed_source)}
    if context.get("fact_registry_enforced"):
        # The explicit audio anchor is always authoritative.  The broader
        # timeline speech can contain neighbouring facts, so the episode
        # registry still limits those numbers.
        allowed = {
            normalized_numeric_fact(str(item))
            for item in (context.get("allowed_numeric_facts") or [])
            if normalized_numeric_fact(str(item))
        }
        allowed.update(
            normalized_numeric_fact(item)
            for item in extract_numeric_fact_tokens(clean_text(str(context.get("audio_anchor") or "")))
            if normalized_numeric_fact(item)
        )
    candidate = {normalized_numeric_fact(item) for item in extract_numeric_fact_tokens(text)}
    if not candidate:
        return []
    allowed_keys = {key for item in allowed for key in numeric_fact_equivalence_keys(item)}
    foreign: list[str] = []
    for item in sorted(candidate):
        if re.fullmatch(r"[一二两三四五六七八九十百千万]+字", item):
            continue
        small_word_count = re.fullmatch(r"(\d+)字", item)
        if small_word_count and int(small_word_count.group(1)) <= 12:
            continue
        strong_fact = bool(re.search(r"秒|分钟|小时|年|字|%|元|万|亿|倍", item))
        numeric_cores = re.findall(r"\d+(?:\.\d+)?", item)
        if not strong_fact and not any(len(core.replace(".", "")) >= 3 for core in numeric_cores):
            continue
        if item in allowed:
            continue
        if numeric_fact_equivalence_keys(item).intersection(allowed_keys):
            continue
        foreign.append(item)
    return foreign


def repair_foreign_scene_numeric_facts(prompt: str, context: dict[str, Any]) -> tuple[str, list[str]]:
    """Generalize invented numbers while preserving the current-scene facts.

    A visual concept may be useful even when an AI director has borrowed a
    number from a neighbouring scene.  Throwing away the whole job is too
    expensive.  Replace only those foreign numeric facts with neutral wording,
    then let the semantic gate score the repaired prompt again.
    """
    text = (
        normalize_image_prompt(prompt)
        .replace("观众1秒必须看懂", "观众必须立即看懂")
        .replace("一秒抓人", "立即抓人")
        .replace("1秒抓人", "立即抓人")
    )
    foreign = foreign_scene_numeric_facts(text, context)
    if not foreign:
        return text, []

    repaired = text
    raw_numeric_tokens = extract_numeric_fact_tokens(text)
    for fact in sorted(foreign, key=len, reverse=True):
        replacement = "相关数值"
        if re.search(r"秒|分钟|小时", fact):
            replacement = "一段时间"
        elif "年" in fact:
            replacement = "长期"
        elif re.search(r"%|比例", fact):
            replacement = "相关比例"
        elif re.search(r"元|块|万|亿", fact):
            replacement = "相关金额"
        elif re.search(r"次|遍|轮", fact):
            replacement = "多次"
        elif re.search(r"字", fact):
            replacement = "一段内容"
        repaired = repaired.replace(fact, replacement)
        for raw_fact in raw_numeric_tokens:
            if normalized_numeric_fact(raw_fact) == fact:
                repaired = repaired.replace(raw_fact, replacement)
    return normalize_image_prompt(repaired), foreign


VISUAL_CONCEPT_CARRIERS: dict[str, tuple[str, ...]] = {
    "phone": ("手机", "移动屏幕", "竖屏"),
    "computer": ("电脑", "显示器", "笔记本屏幕", "双屏"),
    "whiteboard": ("白板", "写字板"),
    "face": ("人物面部", "正对镜头", "人物正脸", "侧脸特写"),
    "diagram": ("数据关系可视化", "信息图", "流程图", "关系图"),
}


VISUAL_CONCEPT_META_FAILURES = (
    "可能不符合",
    "可能不适合",
    "不推荐",
    "仅作备选",
    "仅供备选",
    "效果可能",
    "但可能",
    "无法确定",
)


def visual_concept_quality_issues(text: str) -> list[str]:
    source = clean_text(text)
    issues = [term for term in VISUAL_CONCEPT_META_FAILURES if term in source]
    if source.endswith(("...", "…")) or "..." in source:
        issues.append("概念被截断")
    if source and len(source) < 12:
        issues.append("概念过短")
    generic_pose = bool(re.search(r"摊手|双手摊开|摊开双手|耸肩", source))
    generic_symbol = bool(
        re.search(r"大问号|巨大问号|醒目问号|红叉|巨大红叉|盾牌|放大镜|悬浮芯片", source)
    )
    symbolic_gesture = bool(
        re.search(r"按下暂停|暂停手势|拒绝的手势|做出拒绝|手掌阻挡|手掌制止", source)
    )
    presenter_staging = bool(re.search(r"主播|人物|年轻人|男子|女子", source)) and bool(
        re.search(r"面对镜头|正对镜头|看向镜头|表情", source)
    )
    evidence_action = bool(
        re.search(
            r"拆开|测量|测试|记录|操作|按下|拔下|接入|切换|对照|验证|撕开|扫描|追踪|监听|取证|维修|实验",
            source,
        )
    )
    if generic_pose and (generic_symbol or presenter_staging) and not evidence_action:
        issues.append("通用人物摊手摆拍，缺少当前口播的证据动作")
    if generic_symbol and presenter_staging and not evidence_action:
        issues.append("用问号或红叉代替具体冲突证据")
    if symbolic_gesture or (generic_symbol and not evidence_action):
        issues.append("用抽象手势或符号代替具体冲突证据")
    return dedupe_clauses(issues)


def prompt_is_latin_dominant(text: str) -> bool:
    source = clean_text(text)
    latin = len(re.findall(r"[A-Za-z]", source))
    han = len(re.findall(r"[\u4e00-\u9fff]", source))
    return latin >= 40 and latin > han * 1.5


def generation_prompt_integrity_issues(text: str) -> list[str]:
    source = clean_text(text)
    issues: list[str] = []
    if not source:
        return ["提示词为空"]
    if "..." in source or "…" in source:
        issues.append("提示词被截断")
    for phrase in ("画面里有。", "画面有。", "核心画面：。", "主体是。", "动作是。"):
        if phrase in source:
            issues.append(f"空壳句：{phrase}")
    if re.search(r"\b(?:showi|showin|weari|displa|compari|backgroun|lighti|cinemati|realis)\s*。", source, flags=re.IGNORECASE):
        issues.append("英文单词被截断")
    for opener, closer in (("（", "）"), ("(", ")"), ("[", "]"), ("{", "}")):
        if source.count(opener) != source.count(closer):
            issues.append(f"括号不闭合：{opener}{closer}")
    return dedupe_clauses(issues)


def compact_visual_concept(text: str, limit: int = 260) -> str:
    source = clean_text(text).replace("...", "").replace("…", "").strip("，,。；;:： ")
    if not source:
        return ""
    clauses = [
        clean_text(item).strip("，,。；;:： ")
        for item in re.split(r"[。；;\n]+", source)
        if clean_text(item)
    ]
    clauses = [
        item
        for item in clauses
        if not any(marker in item for marker in VISUAL_CONCEPT_META_FAILURES)
    ]
    if not clauses:
        return ""
    selected: list[str] = []
    current_length = 0
    for clause in clauses:
        added = len(clause) + (1 if selected else 0)
        if selected and current_length + added > limit:
            continue
        if not selected and added > limit:
            clause = clean_visual_brief_fragment(clause, limit)
            added = len(clause)
        if clause:
            selected.append(clause)
            current_length += added
    return "；".join(selected).strip("，,。；;:： ")


