def visual_topic_conflict_hits(text: str, active_topic_type: str) -> list[str]:
    source = clean_text(text).lower()
    active = clean_text(active_topic_type).lower()
    if not source:
        return []
    conflicts: list[str] = []
    for topic_type, markers in VISUAL_TOPIC_EXCLUSIVE_MARKERS.items():
        if topic_type == active:
            continue
        if any(marker.lower() in source for marker in markers):
            conflicts.append(topic_type)
    return conflicts


def visual_topic_conflicts(text: str, active_topic_type: str) -> bool:
    return bool(visual_topic_conflict_hits(text, active_topic_type))


def visual_concept_carriers(text: str) -> set[str]:
    source = clean_text(text)
    return {
        carrier
        for carrier, terms in VISUAL_CONCEPT_CARRIERS.items()
        if any(term in source for term in terms)
    }


def run_local_image_ocr(path: Path) -> dict[str, Any]:
    global RapidOCR, _RAPID_OCR_ENGINE
    if not RAPID_OCR_AVAILABLE:
        return {"status": "unavailable", "engine": "rapidocr", "text": "", "lines": []}
    try:
        if RapidOCR is None:
            from rapidocr import RapidOCR as RapidOCRClass

            RapidOCR = RapidOCRClass
        if _RAPID_OCR_ENGINE is None:
            _RAPID_OCR_ENGINE = RapidOCR()
        result = _RAPID_OCR_ENGINE(str(path))
        texts = list(getattr(result, "txts", None) or [])
        scores = [float(item) for item in (getattr(result, "scores", None) or [])]
        if not texts and isinstance(result, tuple) and result:
            rows = result[0] if isinstance(result[0], list) else []
            for row in rows:
                if not isinstance(row, (list, tuple)) or len(row) < 2:
                    continue
                payload = row[1]
                if isinstance(payload, (list, tuple)) and payload:
                    texts.append(str(payload[0]))
                    scores.append(float(payload[1]) if len(payload) > 1 else 0.0)
        lines = [
            {"text": clean_text(str(text)), "score": round(scores[index], 4) if index < len(scores) else 0.0}
            for index, text in enumerate(texts)
            if clean_text(str(text))
        ]
        high_confidence = [item for item in lines if float(item.get("score", 0) or 0) >= 0.62]
        return {
            "status": "ok",
            "engine": "rapidocr",
            "text": " ".join(str(item.get("text") or "") for item in high_confidence),
            "lines": lines[:40],
            "line_count": len(lines),
        }
    except Exception as exc:
        return {"status": "failed", "engine": "rapidocr", "error": user_facing_error(exc), "text": "", "lines": []}


def image_perceptual_signature(image: Any) -> tuple[Any, Any]:
    if np is None:
        return None, None
    rgb = image.convert("RGB").resize((17, 16))
    gray = np.asarray(rgb.convert("L"), dtype=np.float32)
    dhash = gray[:, 1:] > gray[:, :-1]
    pixels = np.asarray(image.convert("RGB").resize((64, 64)), dtype=np.uint8)
    histogram = []
    for channel in range(3):
        counts, _edges = np.histogram(pixels[:, :, channel], bins=8, range=(0, 256))
        histogram.extend(counts.astype(np.float32).tolist())
    hist = np.asarray(histogram, dtype=np.float32)
    norm = float(np.linalg.norm(hist))
    return dhash, hist / norm if norm else hist


def scene_image_index_from_path(path: Path) -> int:
    """Resolve a scene index from official, candidate, or hidden temp names."""
    match = re.fullmatch(
        r"\.?s_(\d+)(?:_[a-z])?(?:\.(?:gen|regen)-\d+)?",
        path.stem,
        flags=re.IGNORECASE,
    )
    return int(match.group(1)) if match else 0


def scene_image_root(path: Path) -> Path | None:
    if path.parent.name == "scenes":
        return path.parent
    if path.parent.name == "candidates" and path.parent.parent.name == "scenes":
        return path.parent.parent
    return None


def image_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def project_scene_similarity(path: Path, image: Any) -> dict[str, Any]:
    """Compare a candidate with every accepted scene, including non-adjacent ones."""
    scene_root = scene_image_root(path)
    current_index = scene_image_index_from_path(path)
    if Image is None or np is None or scene_root is None or current_index <= 0:
        return {"checked": False, "scope": "project", "matches": []}

    current_hash, current_hist = image_perceptual_signature(image)
    if current_hash is None or current_hist is None:
        return {"checked": False, "scope": "project", "matches": []}

    candidate_paths: list[Path] = []
    for directory in (scene_root, scene_root / "candidates"):
        if not directory.exists():
            continue
        for candidate_path in directory.iterdir():
            if not candidate_path.is_file() or candidate_path.suffix.lower() not in RASTER_IMAGE_SUFFIXES:
                continue
            if candidate_path.name.startswith(".") or candidate_path.resolve(strict=False) == path.resolve(strict=False):
                continue
            if scene_image_index_from_path(candidate_path) <= 0:
                continue
            candidate_paths.append(candidate_path)

    source_sha = ""
    with contextlib.suppress(Exception):
        source_sha = image_file_sha256(path)
    matches: list[dict[str, Any]] = []
    for candidate_path in sorted(candidate_paths, key=lambda item: item.as_posix().lower()):
        try:
            candidate_sha = image_file_sha256(candidate_path)
            exact_duplicate = bool(source_sha and candidate_sha == source_sha)
            with Image.open(candidate_path) as candidate_image:
                candidate_hash, candidate_hist = image_perceptual_signature(candidate_image)
            hash_similarity = 1.0 - float(np.mean(current_hash != candidate_hash))
            hist_similarity = float(np.dot(current_hist, candidate_hist))
            combined = hash_similarity * 0.68 + hist_similarity * 0.32
            near_duplicate = bool(
                exact_duplicate
                or (hash_similarity >= 0.88 and hist_similarity >= 0.94 and combined >= 0.90)
            )
            matches.append(
                {
                    "filename": candidate_path.name,
                    "scene_index": scene_image_index_from_path(candidate_path),
                    "hash_similarity": round(hash_similarity, 4),
                    "histogram_similarity": round(hist_similarity, 4),
                    "combined": round(combined, 4),
                    "exact_duplicate": exact_duplicate,
                    "near_duplicate": near_duplicate,
                }
            )
        except (OSError, ValueError, TypeError):
            continue

    matches.sort(
        key=lambda item: (bool(item.get("exact_duplicate")), float(item.get("combined", 0) or 0)),
        reverse=True,
    )
    return {
        "checked": True,
        "scope": "project",
        "matches": matches,
        "exact_duplicate": any(item.get("exact_duplicate") for item in matches),
        "near_duplicate": any(item.get("near_duplicate") for item in matches),
    }


def scene_neighbor_similarity(path: Path, image: Any) -> dict[str, Any]:
    # Kept as the public compatibility name; the audit now covers the whole
    # project because repeated compositions are often several scenes apart.
    return project_scene_similarity(path, image)


def audit_generated_image(path: Path, size: str, purpose: str, prompt: str = "") -> dict[str, Any]:
    report: dict[str, Any] = {
        "ok": True,
        "severity": "ok",
        "reasons": [],
        "warnings": [],
        "size_hint": size,
        "purpose": purpose,
        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
    }
    if Image is None or np is None:
        report["skipped"] = "missing_image_audit_deps"
        return report
    if not path.exists():
        report["ok"] = False
        report["severity"] = "hard"
        report["reasons"] = ["missing_file"]
        return report

    try:
        with Image.open(path) as image:
            rgb = image.convert("RGB")
            width, height = rgb.size
            pixels = np.asarray(rgb, dtype=np.float32)
            audit_width = min(640, width)
            audit_height = max(1, int(height * (audit_width / max(1, width))))
            audit_gray = np.asarray(
                rgb.resize((audit_width, audit_height)).convert("L"),
                dtype=np.float32,
            )
    except Exception as exc:
        report["ok"] = False
        report["severity"] = "hard"
        report["reasons"] = [f"open_failed:{type(exc).__name__}"]
        return report

    gray = pixels.mean(axis=2)
    stddev = float(gray.std())
    report["width"] = int(width)
    report["height"] = int(height)
    report["stddev"] = round(stddev, 2)
    target_size = parse_image_size_hint(size)
    if target_size is not None:
        target_width, target_height = target_size
        report["target_width"] = int(target_width)
        report["target_height"] = int(target_height)
        if (width, height) != target_size:
            report["reasons"].append("dimension_mismatch")

    if stddev < IMAGE_AUDIT_MIN_STDDEV:
        report["reasons"].append("flat_low_variance")

    audit_rgb = np.asarray(rgb.resize((256, 144)), dtype=np.uint8)
    quantized = (audit_rgb // 32).reshape(-1, 3)
    _palette, palette_counts = np.unique(quantized, axis=0, return_counts=True)
    palette_probabilities = palette_counts.astype(np.float64) / max(1, int(palette_counts.sum()))
    color_entropy = float(
        -np.sum(palette_probabilities * np.log2(np.clip(palette_probabilities, 1e-12, 1.0)))
    )
    dominant_color_ratio = float(palette_counts.max() / max(1, int(palette_counts.sum())))
    audit_gray_small = audit_rgb.astype(np.float32).mean(axis=2)
    horizontal_edges = np.abs(np.diff(audit_gray_small, axis=1)) > 18.0
    vertical_edges = np.abs(np.diff(audit_gray_small, axis=0)) > 18.0
    edge_density = float((horizontal_edges.mean() + vertical_edges.mean()) / 2.0)
    report["color_entropy"] = round(color_entropy, 3)
    report["dominant_color_ratio"] = round(dominant_color_ratio, 4)
    report["edge_density"] = round(edge_density, 4)
    if purpose == "scene" and color_entropy < 2.2 and dominant_color_ratio > 0.66 and edge_density < 0.05:
        report["reasons"].append("flat_graphic_placeholder")

    patch_h = max(8, height // 14)
    patch_w = max(8, width // 14)
    corners = np.concatenate(
        [
            pixels[:patch_h, :patch_w].reshape(-1, 3),
            pixels[:patch_h, -patch_w:].reshape(-1, 3),
            pixels[-patch_h:, :patch_w].reshape(-1, 3),
            pixels[-patch_h:, -patch_w:].reshape(-1, 3),
        ],
        axis=0,
    )
    background = np.median(corners, axis=0)
    diff = np.abs(pixels - background).mean(axis=2)
    foreground = diff > 18.0
    foreground_ratio = float(foreground.mean())
    report["foreground_ratio"] = round(foreground_ratio, 4)
    if foreground_ratio < IMAGE_AUDIT_MIN_FOREGROUND_RATIO:
        report["reasons"].append("foreground_too_small")

    coords = np.argwhere(foreground)
    if coords.size:
        top, left = coords.min(axis=0)
        bottom, right = coords.max(axis=0)
        coverage_width = float((right - left + 1) / max(1, width))
        coverage_height = float((bottom - top + 1) / max(1, height))
        report["coverage_width"] = round(coverage_width, 4)
        report["coverage_height"] = round(coverage_height, 4)
        if coverage_width < IMAGE_AUDIT_MIN_COVERAGE_WIDTH:
            report["reasons"].append("coverage_too_narrow")
        if coverage_height < IMAGE_AUDIT_MIN_COVERAGE_HEIGHT:
            report["reasons"].append("coverage_too_short")
    else:
        report["reasons"].append("empty_foreground")

    if purpose in {"scene", "cover"}:
        top_left = gray[: max(32, int(height * 0.2)), : max(32, int(width * 0.32))]
        bottom_strip = gray[int(height * 0.84) :, :]
        audit_mean = float(audit_gray.mean())
        if audit_mean > 115:
            text_components = _count_small_dark_components(audit_gray, audit_mean - 24)
            component_density = text_components / max(1.0, (audit_width * audit_height) / 10_000.0)
            report["text_component_density"] = round(component_density, 2)
            report["text_elements_detected"] = bool(component_density >= IMAGE_AUDIT_TEXT_COMPONENT_DENSITY)
        if top_left.size:
            top_left_mean = float(top_left.mean())
            if top_left_mean > 135:
                top_left_components = _count_small_dark_components(top_left, top_left_mean - 25)
                report["top_left_components"] = int(top_left_components)
                report["top_left_text_elements_detected"] = bool(top_left_components >= 14)
        if bottom_strip.size:
            bottom_mean = float(bottom_strip.mean())
            if bottom_mean > 135:
                bottom_components = _count_small_dark_components(bottom_strip, bottom_mean - 22)
                report["bottom_components"] = int(bottom_components)
                report["bottom_text_elements_detected"] = bool(bottom_components >= 24)

    if purpose == "scene":
        similarity = scene_neighbor_similarity(path, rgb)
        report["neighbor_similarity"] = similarity
        report["project_similarity"] = similarity
        if similarity.get("exact_duplicate"):
            report["reasons"].append("exact_duplicate_scene")
        elif similarity.get("near_duplicate"):
            report["reasons"].append("near_duplicate_scene")

    ocr = run_local_image_ocr(path)
    report["ocr"] = ocr
    if purpose == "scene" and ocr.get("status") == "ok":
        information_ocr = scene_information_ocr_report(clean_text(str(ocr.get("text") or "")), prompt)
        report["ocr"]["information"] = information_ocr
        if information_ocr.get("required") and not information_ocr.get("passed"):
            report["reasons"].append("ocr_information_missing")
    if ocr.get("status") == "ok" and clean_text(str(ocr.get("text") or "")):
        ocr_text = clean_text(str(ocr.get("text") or ""))
        expected_facts = image_audit_expected_numeric_facts(prompt)
        detected_facts = {normalized_numeric_fact(item) for item in extract_numeric_fact_tokens(ocr_text)}
        report["ocr"]["expected_facts"] = sorted(expected_facts)
        report["ocr"]["detected_facts"] = sorted(detected_facts)
        contamination = ocr_prompt_contamination(ocr_text, prompt)
        text_overlap_score = ocr_prompt_text_overlap_score(ocr_text, prompt)
        fact_alignment = numeric_fact_alignment(expected_facts, detected_facts)
        fact_coverage_score = int(fact_alignment.get("coverage_score", 0) or 0)
        semantic_score = text_overlap_score
        if expected_facts:
            semantic_score = int(round(text_overlap_score * 0.35 + fact_coverage_score * 0.65))
        report["ocr"]["production_meta_hits"] = contamination
        report["ocr"]["text_overlap_score"] = text_overlap_score
        report["ocr"]["fact_coverage_score"] = fact_coverage_score
        report["ocr"]["matched_expected_facts"] = fact_alignment.get("matched", [])
        report["ocr"]["missing_expected_facts"] = fact_alignment.get("missing", [])
        report["ocr"]["semantic_score"] = semantic_score
        if contamination:
            report["reasons"].append("ocr_production_meta")
        if int(ocr.get("line_count", 0) or 0) >= 4 and semantic_score < 22:
            report["reasons"].append("ocr_semantic_mismatch")
        expected_digit_cores = {match.group(0) for item in expected_facts for match in re.finditer(r"\d+(?:\.\d+)?", item)}
        facts_overlap = bool(fact_alignment.get("matched"))
        unverified: set[str] = set()
        if expected_facts and detected_facts and not facts_overlap:
            report["reasons"].append("ocr_fact_mismatch")
        else:
            unverified = {
                item
                for item in detected_facts - expected_facts
                if re.search(r"秒|分钟|小时|天|年|字|%|元|块|万|亿|次|倍", item)
                or any(len(core) >= 3 and core not in expected_digit_cores for core in re.findall(r"\d+(?:\.\d+)?", item))
            }
        if expected_facts and unverified:
            report["warnings"].append("ocr_contains_unverified_numbers")

    if purpose == "cover":
        expected_cover_text = [
            item
            for item in (extract_cover_title_hint(prompt), extract_cover_subtitle_hint(prompt))
            if item
        ]
        if expected_cover_text:
            ocr_text = clean_text(str(ocr.get("text") or ""))
            ocr_lines = [clean_text(str(item.get("text") or "")) for item in ocr.get("lines", []) if isinstance(item, dict)]
            cover_completeness = {
                item: visual_text_completeness_report(item, ocr_text, ocr_lines)
                for item in expected_cover_text
            }
            matched_cover_text = [
                item
                for item in expected_cover_text
                if bool(cover_completeness.get(item, {}).get("passed"))
            ]
            missing_cover_text = [item for item in expected_cover_text if item not in matched_cover_text]
            report["ocr"]["expected_cover_text"] = expected_cover_text
            report["ocr"]["cover_text_completeness"] = cover_completeness
            report["ocr"]["matched_cover_text"] = matched_cover_text
            report["ocr"]["missing_cover_text"] = missing_cover_text
            if expected_cover_text and expected_cover_text[0] in missing_cover_text:
                report["reasons"].append("cover_title_missing")
            if len(expected_cover_text) > 1 and expected_cover_text[1] in missing_cover_text:
                report["reasons"].append("cover_subtitle_missing")

    hard_reasons = {
        "missing_file",
        "flat_low_variance",
        "foreground_too_small",
        "coverage_too_narrow",
        "coverage_too_short",
        "empty_foreground",
        "dimension_mismatch",
        "flat_graphic_placeholder",
        "exact_duplicate_scene",
        "near_duplicate_scene",
    }
    severity = "ok"
    if report["reasons"]:
        severity = "soft"
    if any(reason in hard_reasons for reason in report["reasons"]):
        severity = "hard"
    report["severity"] = severity
    report["ok"] = not report["reasons"]
    return report


