def image_audit_reason_label(reason: str) -> str:
    text = clean_text(str(reason or ""))
    return IMAGE_AUDIT_REASON_LABELS.get(text, text or "未知原因")


def build_ark_extra_body(env: dict[str, str], purpose: str) -> dict[str, Any]:
    extra: dict[str, Any] = {"watermark": False}
    key = "ARK_IMAGE_WEB_SEARCH_COVER" if purpose == "cover" else "ARK_IMAGE_WEB_SEARCH_SCENE"
    if env_flag(env.get(key)):
        extra["tools"] = [{"type": "web_search"}]
    return extra


def generate_ark_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    reference_images: list[Path] | None = None,
) -> Path:
    if OpenAI is None:
        raise RuntimeError("当前环境缺少 openai 依赖，无法调用火山方舟文生图。")
    api_key = (env.get("ARK_API_KEY", "") or "").strip()
    if not api_key:
        raise RuntimeError("ARK_API_KEY 未配置，无法生成场景图。")

    model = resolve_ark_image_model(env)
    client = OpenAI(api_key=api_key, base_url=ARK_BASE_URL, timeout=240.0)
    clean_prompt = normalize_image_prompt(prompt)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    extra_body = build_ark_extra_body(env, purpose)
    references = [path for path in list(reference_images or []) if path.exists()][:6]
    if references:
        extra_body["image"] = [_vision_image_data_url(path) for path in references]
        extra_body["sequential_image_generation"] = "disabled"
    response = client.images.generate(
        model=model,
        prompt=clean_prompt,
        size=size,
        response_format="b64_json",
        extra_body=extra_body,
    )
    image_data = base64.b64decode(response.data[0].b64_json)
    output_path.write_bytes(image_data)
    storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")
    return output_path


def _request_provider_json(
    method: str,
    url: str,
    headers: dict[str, str],
    payload: dict[str, Any] | None = None,
    timeout: float = 240.0,
) -> dict[str, Any]:
    data = None
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(url, data=data, method=method.upper())
    for key, value in headers.items():
        request.add_header(key, value)
    if payload is not None:
        request.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            text = response.read().decode("utf-8", errors="ignore")
            parsed = json.loads(text or "{}")
            if not isinstance(parsed, dict):
                raise RuntimeError("兼容接口返回的不是 JSON 对象。")
            return parsed
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="ignore")
        body_lower = body.lower()
        if "域名解析错误" in body or "鍩熷悕瑙ｆ瀽閿欒" in body or ("domain" in body_lower and "error" in body_lower):
            raise RuntimeError(
                "OpenAI 兼容网关返回“域名解析错误”：Base URL 已连通，但 NewAPI 后台渠道、分组或模型路由可能指向了不可解析的上游域名。请确认 token 分组有可用图片模型，模型 ID 不要填 newapi_channel_conn。"
            ) from exc
        detail = clean_text(body)[:400]
        raise RuntimeError(f"HTTP {exc.code}: {detail or '图片接口返回错误'}") from exc
    except urllib.error.URLError as exc:
        reason = getattr(exc, "reason", None) or exc
        raise RuntimeError(f"网络请求失败：{reason}") from exc
    except (TimeoutError, socket.timeout) as exc:
        raise RuntimeError(f"image request timed out after {timeout:.0f}s: {exc}") from exc
    except OSError as exc:
        if "timed out" in str(exc).lower():
            raise RuntimeError(f"image request timed out after {timeout:.0f}s: {exc}") from exc
        raise
    except json.JSONDecodeError as exc:
        raise RuntimeError("兼容接口返回了无法解析的 JSON。") from exc


def _download_provider_binary(url: str, timeout: float = 240.0) -> bytes:
    request = urllib.request.Request(
        url,
        method="GET",
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/137.0 Safari/537.36",
            "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read()
    except (TimeoutError, socket.timeout) as exc:
        raise RuntimeError(f"image download timed out after {timeout:.0f}s: {exc}") from exc
    except urllib.error.URLError as exc:
        reason = getattr(exc, "reason", None) or exc
        raise RuntimeError(f"image download failed: {reason}") from exc
    except OSError as exc:
        if "timed out" in str(exc).lower():
            raise RuntimeError(f"image download timed out after {timeout:.0f}s: {exc}") from exc
        raise RuntimeError(f"image download failed: {exc}") from exc


def _extract_provider_image_bytes(payload: dict[str, Any], timeout: float = 240.0) -> bytes:
    data = payload.get("data")
    if not isinstance(data, list) or not data or not isinstance(data[0], dict):
        raise RuntimeError("兼容出图接口未返回 data[0]。")
    item = data[0]
    encoded = item.get("b64_json") or item.get("b64")
    if isinstance(encoded, str) and encoded.strip():
        encoded_text = encoded.strip()
        if encoded_text.startswith("data:image") and "," in encoded_text:
            encoded_text = encoded_text.split(",", 1)[1]
        try:
            return base64.b64decode(encoded_text)
        except Exception as exc:
            raise RuntimeError("兼容出图接口返回的图片数据无法解码。") from exc
    image_url = item.get("url")
    if isinstance(image_url, str) and image_url.strip():
        return _download_provider_binary(image_url.strip(), timeout=timeout)
    raise RuntimeError("兼容出图接口未返回 b64_json 或 url。")


def chatgpt_handoff_dir(output_path: Path) -> Path:
    return output_path.parent / "_chatgpt_handoff"


CHATGPT_HANDOFF_PROVIDER_KEYS = {
    "chatgpt_handoff",
    "chatgpt_web_handoff",
    "chatgpt_desktop_handoff",
}


def resolve_chatgpt_handoff_target(env: dict[str, str], provider_key: str = "chatgpt_handoff") -> str:
    if provider_key == "chatgpt_web_handoff":
        return "web"
    if provider_key == "chatgpt_desktop_handoff":
        return "desktop"
    configured = clean_text(env.get("CHATGPT_IMAGE_OPEN_TARGET") or "web").lower() or "web"
    return configured if configured in {"web", "desktop", "both"} else "web"


def chatgpt_handoff_provider_record(provider_key: str, env: dict[str, str]) -> dict[str, str]:
    target = resolve_chatgpt_handoff_target(env, provider_key)
    if provider_key == "chatgpt_web_handoff" or target == "web":
        return {"key": provider_key, "label": "ChatGPT 网页接力", "model": "chatgpt-account"}
    if provider_key == "chatgpt_desktop_handoff" or target == "desktop":
        return {"key": provider_key, "label": "ChatGPT Classic 手动接力", "model": "chatgpt-account"}
    return {"key": provider_key, "label": "ChatGPT 网页 + Classic 接力（旧配置）", "model": "chatgpt-account"}


def balanced_scene_generation_brief(
    prompt: str,
    *,
    topic: str = "",
    speech: str = "",
    anchor: str = "",
    concept: str = "",
    source_information: dict[str, Any] | None = None,
) -> str:
    """Reduce accumulated prompt rules to facts plus an open creative brief."""
    source = normalize_image_prompt(prompt)
    spoken = clean_text(speech)
    if not spoken:
        spoken = scene_prompt_speech_anchor(source)
        if not spoken:
            quoted_speech = re.search(
                r"当前完整口播\s*[:：]?\s*(?:短标签\s*)?[「\"“]?([^。\n」\"”]+)[」\"”]?",
                source,
            )
            spoken = clean_text(quoted_speech.group(1)) if quoted_speech else extract_prompt_dialogue_hint_full(source)
    spoken = compact_prompt_speech_anchor(spoken, 360)
    focus = clean_text(anchor)
    if not focus:
        focus_match = re.search(r"当前口播重点\s*[:：]\s*([^。\n]+)", source)
        focus = clean_text(focus_match.group(1)) if focus_match else ""
    selected_concept = compact_visual_concept(concept, 280)
    if not selected_concept:
        concept_match = re.search(r"选定视觉概念\s*[:：]\s*([^\n]+)", source)
        selected_concept = compact_visual_concept(concept_match.group(1), 280) if concept_match else ""

    current_topic = clean_text(topic)
    if not current_topic:
        topic_match = re.search(
            r"(?:锁定本期主题|本期主题|主题情境|本镜主题情境|主题)\s*[:：]\s*(.*?)(?=[，,。；;\n]\s*(?:(?:本镜)?口播原文|当前完整口播|当前口播重点|画面任务|本镜任务|主体|主主体)\s*[:：]|$)",
            source,
        )
        current_topic = clean_text(topic_match.group(1)) if topic_match else ""

    def named_field(marker: str) -> str:
        label = clean_text(marker).rstrip(":：")
        if not label:
            return ""
        match = re.search(
            rf"(?:^|[，,。；;\n])\s*{re.escape(label)}\s*[:：]\s*"
            r"(.*?)(?=[，,。；;\n]\s*[^，,。；;\n:：]{1,24}\s*[:：]|$)",
            source,
        )
        return clean_text(match.group(1)) if match else ""

    def useful_clauses(prefixes: tuple[str, ...], limit: int) -> list[str]:
        values: list[str] = []
        for prefix in prefixes:
            value = named_field(prefix)
            if not value:
                continue
            if any(
                stale_rule in value
                for stale_rule in (
                    "最多保留",
                    "最多一个",
                    "2-8 字",
                    "2-8个字",
                    "上半区",
                    "不内嵌文字",
                    "冷蓝与暖金",
                    "字幕留白",
                )
            ):
                continue
            value = re.sub(r"[，,]\s*和$", "", value).strip()
            if value and value not in values:
                values.append(value)
            if len(values) >= limit:
                return values
        for clause in re.split(r"[。；\n]+", source):
            text = clean_text(clause)
            if not text or not any(text.startswith(prefix) for prefix in prefixes):
                continue
            if any(
                stale_rule in text
                for stale_rule in (
                    "最多保留",
                    "最多一个",
                    "2-8 字",
                    "2-8个字",
                    "上半区",
                    "不内嵌文字",
                    "冷蓝与暖金",
                    "字幕留白",
                )
            ):
                continue
            value = text.split("：", 1)[-1].strip() if "：" in text else text
            value = re.sub(r"[，,]\s*和$", "", value).strip()
            if value and value not in values:
                values.append(value)
            if len(values) >= limit:
                break
        return values

    goals = useful_clauses(("本镜任务：", "本镜信息任务：", "画面任务：", "冲突悬念：", "叙事任务：", "动作："), 3)
    evidence = useful_clauses(
        (
            "来源支撑信息：",
            "信息证据：",
            "口播事实支撑：",
            "可参考的场景证据：",
            "证据信息：",
            "主主体：",
            "可见主体：",
            "关键物件：",
            "本张换成",
        ),
        4,
    )
    visual_relations = useful_clauses(("可视化关系：", "信息结构：", "建议的信息结构："), 2)
    channel_style, channel_negative, episode_continuity = _channel_style_from_prompt(source)
    channel_strategy = _channel_strategy_from_prompt(source)
    channel_palette = _channel_palette_from_prompt(source)
    selected_concept = _normalize_concept_for_channel_style(selected_concept, channel_style)
    required_visual_copy = useful_clauses(
        ("画面主信息：", "必须呈现的事实词：", "信息构图模式：", "静音验收："),
        5,
    )
    source_payload = source_information if isinstance(source_information, dict) else {}
    source_evidence = [
        clean_text(str(item))
        for item in source_payload.get("supporting_evidence", [])
        if clean_text(str(item))
    ]
    for item in source_evidence:
        if item not in evidence:
            evidence.insert(0, item)
    if source_evidence:
        evidence = dedupe_clauses(source_evidence)[:4]
        if selected_concept:
            goals = ["把所选视觉概念与这组证据链合并成一个具体瞬间，让原因、过程和结果在同一画面内可辨认"]
    payload_relation = clean_text(str(source_payload.get("visual_relation") or ""))
    if payload_relation and payload_relation not in visual_relations:
        visual_relations.insert(0, payload_relation)
    payload_copy = source_payload.get("visual_copy") if isinstance(source_payload.get("visual_copy"), dict) else {}
    payload_headline = clean_text(str(payload_copy.get("headline") or ""))
    payload_fact_chips = [
        clean_text(str(item))
        for item in payload_copy.get("fact_chips", [])
        if clean_text(str(item))
    ]
    fact_source = clean_text(f"{focus} {spoken}") or source
    facts = []
    for token in extract_numeric_fact_tokens(fact_source):
        value = normalized_numeric_fact(token)
        if not value:
            continue
        if re.fullmatch(r"\d+(?:\.\d+)?", value) and len(re.sub(r"\D", "", value)) < 2:
            continue
        if value not in facts:
            facts.append(value)
    audience_plan = audience_visual_plan(
        topic=current_topic,
        narration=spoken or focus,
    )

    lines = []
    if current_topic:
        lines.append(f"本期主题：{current_topic}")
    if channel_style:
        lines.append(f"频道固定视觉签名：{channel_style}")
    if channel_strategy:
        lines.append(f"频道画面策略：{channel_strategy}")
    if episode_continuity:
        lines.append(f"同集视觉连续性：{episode_continuity}")
    if spoken:
        lines.append(f"当前完整口播：{spoken}")
    if focus and focus != spoken:
        lines.append(f"当前口播重点：{focus}")
    if selected_concept:
        lines.append(f"选定视觉概念：{selected_concept}")
    lines.append(
        "本镜任务："
        + ("；".join(goals) if goals else "把当前口播最重要的冲突、因果或反差，转成观众一眼能理解的短视频画面")
    )
    if evidence:
        lines.append(f"来源支撑信息：{'；'.join(evidence[:4])}")
    if visual_relations:
        lines.append(f"建议的信息结构：{'；'.join(visual_relations[:2])}")
    if required_visual_copy:
        lines.append(f"图片必须原生呈现的信息：{'；'.join(dedupe_clauses(required_visual_copy)[:5])}")
    if payload_headline:
        lines.append(
            f"画面原生文字：由模型直接把「{payload_headline}」完整写入图片，可自然换行，不得截断"
        )
    if payload_fact_chips:
        lines.append(f"必须呈现的事实词：{'、'.join(payload_fact_chips)}")
    if facts:
        lines.append(f"不可改错的数字事实：{'、'.join(facts)}")
    audience_block = audience_prompt_block(audience_plan)
    if audience_block:
        lines.append(audience_block)
    lines.extend(
        [
            "创作边界：只服务本期主题和当前口播；人物、对象和因果不得改错，不借用其它镜头或项目的信息；具体数字必须来自当前口播，不虚构示例数值。",
            "创作自由：画面风格、人物或物件、场景、构图、光线、色彩与材质由当前内容决定；把证据链物化为真实对象、动作峰值和状态变化，不套固定模板。",
            f"频道禁止元素：{channel_negative}" if channel_negative else "",
            "视觉取舍：不要用人物正对镜头摆拍；除非口播本身讲人物反应，否则不要用皱眉、摊手、盾牌、放大镜、红叉、问号、悬浮芯片或氛围背景代替具体证据。",
            "信息策略：关键证据、反转和结论镜头优先采用信息主导构图，让原因、过程和结果在底图中形成可辨认的物件关系。",
            "文字策略：由生图模型在同一次生成中完成准确标题、完整结论、数字、标签、批注和必要说明；文字内容与数量只由当前口播决定，不设统一字数上限，允许自然换行，禁止截断、乱码、Logo、水印和独立模板标题板。",
            "静音验收：观众只看成图，也能读完整主信息，并说出这一镜的具体冲突和哪组物件关系证明了它；否则重做。",
            "直接选择最适合这一段口播的视觉方案生成图片，不要复述规则。",
        ]
    )
    return "\n".join(lines)


def ai_teacher_scene_grounding_report(
    prompt: str,
    *,
    concept: str,
    semantic_context: dict[str, Any],
    active_topic_type: str,
) -> dict[str, Any]:
    """Validate hard facts without demanding boilerplate in a concrete AI brief."""
    candidate = normalize_image_prompt(prompt)
    combined = clean_text(f"{candidate} {concept}")
    integrity_issues = generation_prompt_integrity_issues(candidate)
    foreign_numbers = foreign_scene_numeric_facts(combined, semantic_context)
    semantic_source = clean_text(
        f"{semantic_context.get('topic', '')} {semantic_context.get('audio_anchor', '')} "
        f"{semantic_context.get('speech', '')} {semantic_context.get('visual_director', '')}"
    )
    foreign_callouts = foreign_scene_callout_hits(combined, semantic_source)
    topic_conflicts = visual_topic_conflict_hits(combined, active_topic_type)
    concept_issues = [
        issue
        for issue in visual_concept_quality_issues(concept or candidate)
        if issue != "概念过短" or len(candidate) < 48
    ]
    executable = len(candidate) >= 48 and bool(
        re.search(
            r"特写|近景|中景|全景|俯拍|视角|构图|主体|人物|一只手|手指|屏幕|桌面|厨房|办公室|街道|背景|光线|摄影|画面",
            candidate,
        )
    )
    accepted = bool(
        executable
        and not integrity_issues
        and not foreign_numbers
        and not foreign_callouts
        and not topic_conflicts
        and not concept_issues
    )
    penalty = (
        len(integrity_issues) * 24
        + len(foreign_numbers) * 28
        + len(foreign_callouts) * 24
        + len(topic_conflicts) * 30
        + len(concept_issues) * 18
        + (0 if executable else 35)
    )
    return {
        "accepted": accepted,
        "score": int(clamp_number(96 - penalty, 0, 100)),
        "executable": executable,
        "integrity_issues": integrity_issues,
        "foreign_numeric_facts": foreign_numbers,
        "foreign_callouts": foreign_callouts,
        "topic_conflicts": topic_conflicts,
        "concept_issues": concept_issues,
    }


def grounded_ai_teacher_scene_prompt(
    prompt: str,
    *,
    topic: str,
    semantic_context: dict[str, Any],
) -> str:
    """Make the teacher's concrete visual plan the center of the outbound brief."""
    focus = clean_scene_spoken_text(
        str(semantic_context.get("audio_anchor") or semantic_context.get("speech") or "")
    )
    return balanced_scene_generation_brief(
        "",
        topic=topic,
        speech=focus,
        anchor=focus,
        concept=normalize_image_prompt(prompt),
        source_information=semantic_context.get("source_information") if isinstance(semantic_context.get("source_information"), dict) else None,
    )


def audio_bound_semantic_scene_prompt(topic: str, speech: str, anchor: str = "") -> str:
    blueprint = audio_bound_visual_blueprint(clean_text(f"{anchor} {speech}"), topic)
    subjects = [clean_text(str(item)) for item in blueprint.get("subjects", []) if clean_text(str(item))]
    concept_parts = [
        f"核心证据：{'、'.join(subjects)}" if subjects else "",
        f"正在发生：{clean_text(str(blueprint.get('action') or ''))}",
        f"关键冲突：{clean_text(str(blueprint.get('tension') or ''))}",
        f"事实关系：{clean_text(str(blueprint.get('evidence') or ''))}",
    ]
    concept = compact_visual_concept("；".join(item for item in concept_parts if clean_text(item)), 280)
    return balanced_scene_generation_brief(
        "",
        topic=topic,
        speech=speech,
        anchor=anchor,
        concept=concept,
    )


def build_chatgpt_handoff_prompt(prompt: str, size: str, purpose: str) -> str:
    ratio_hint = build_apiyi_size_hint(size)
    purpose_hint = "短视频封面" if purpose == "cover" else "短视频画面"
    if purpose == "scene":
        # `scene_specific_image_prompt` is already a compact director contract.
        # Re-wrapping it as an open brief used to discard its concrete subject
        # and action, leaving only generic evidence language at the provider.
        has_directed_shot = ("主主体：" in prompt or "主体：" in prompt) and "动作：" in prompt
        semantic_prompt = (
            normalize_image_prompt(prompt)
            if is_semantic_scene_generation_brief(prompt) or has_directed_shot
            else balanced_scene_generation_brief(prompt)
        )
        clean_prompt = lightweight_scene_model_prompt(semantic_prompt, max_chars=680)
    else:
        clean_prompt = compile_outbound_image_prompt(
            sanitize_prompt_for_image_model(prompt, purpose),
            purpose,
            max_chars=560,
        )
        clean_prompt = re.sub(r"用小角标、专属色块或固定镜头气质体现个人IP识别[，,；;。]?", "", clean_prompt)
        clean_prompt = re.sub(r"频道名只做很小识别[，,；;。]?", "", clean_prompt)
    lines = [
        "请直接调用 ChatGPT 的“生成图片”功能，立即生成 1 张图片。",
        "只输出成图，不要整理或改写 Prompt。",
        f"用途：{purpose_hint}；画幅：{ratio_hint or '按任务尺寸'}。",
        clean_prompt,
        "主体与字幕区分开；事实准确；画面信息清楚。",
        "请现在直接生成图片，只返回图片，不要输出任何文字或新的 Prompt。",
    ]
    return "\n".join(lines).strip() + "\n"


