def _copy_text_to_windows_clipboard(text: str) -> bool:
    import ctypes
    from ctypes import wintypes

    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32
    handle_type = getattr(wintypes, "HGLOBAL", wintypes.HANDLE)

    user32.OpenClipboard.argtypes = [wintypes.HWND]
    user32.OpenClipboard.restype = wintypes.BOOL
    user32.EmptyClipboard.argtypes = []
    user32.EmptyClipboard.restype = wintypes.BOOL
    user32.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
    user32.SetClipboardData.restype = wintypes.HANDLE
    user32.CloseClipboard.argtypes = []
    user32.CloseClipboard.restype = wintypes.BOOL
    kernel32.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
    kernel32.GlobalAlloc.restype = handle_type
    kernel32.GlobalLock.argtypes = [handle_type]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalUnlock.argtypes = [handle_type]
    kernel32.GlobalUnlock.restype = wintypes.BOOL
    kernel32.GlobalFree.argtypes = [handle_type]
    kernel32.GlobalFree.restype = handle_type

    opened = False
    for _attempt in range(12):
        if user32.OpenClipboard(None):
            opened = True
            break
        time.sleep(0.05)
    if not opened:
        return False

    memory_handle = None
    transferred = False
    try:
        if not user32.EmptyClipboard():
            return False
        buffer = ctypes.create_unicode_buffer(str(text or ""))
        memory_handle = kernel32.GlobalAlloc(0x0002, ctypes.sizeof(buffer))
        if not memory_handle:
            return False
        pointer = kernel32.GlobalLock(memory_handle)
        if not pointer:
            return False
        try:
            ctypes.memmove(pointer, ctypes.addressof(buffer), ctypes.sizeof(buffer))
        finally:
            kernel32.GlobalUnlock(memory_handle)
        if not user32.SetClipboardData(13, memory_handle):
            return False
        transferred = True
        memory_handle = None
        return True
    finally:
        if memory_handle and not transferred:
            kernel32.GlobalFree(memory_handle)
        user32.CloseClipboard()


def copy_text_to_clipboard(text: str) -> bool:
    if os.name != "nt":
        return False
    try:
        if _copy_text_to_windows_clipboard(text):
            return True
    except Exception:
        pass
    try:
        payload = base64.b64encode(str(text or "").encode("utf-8")).decode("ascii")
        script = (
            f"$bytes=[Convert]::FromBase64String('{payload}');"
            "$value=[Text.Encoding]::UTF8.GetString($bytes);"
            "Set-Clipboard -Value $value"
        )
        encoded_command = base64.b64encode(script.encode("utf-16-le")).decode("ascii")
        completed = subprocess.run(
            ["powershell", "-NoProfile", "-EncodedCommand", encoded_command],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=8,
            **background_subprocess_kwargs(),
        )
        return completed.returncode == 0
    except Exception:
        return False


def open_chatgpt_handoff(
    page_path: Path,
    env: dict[str, str],
    prompt: str,
    open_target: str | None = None,
) -> bool:
    if not env_flag(env.get("CHATGPT_IMAGE_AUTO_OPEN", "true")):
        return False
    clipboard_copied = copy_text_to_clipboard(prompt)
    targets = {open_target or resolve_chatgpt_handoff_target(env)}
    if "both" in targets:
        targets = {"web", "desktop"}
    if "web" in targets:
        with contextlib.suppress(Exception):
            os.startfile(str(page_path))  # type: ignore[attr-defined]
    if "web" in targets:
        url = clean_text(env.get("CHATGPT_IMAGE_WEB_URL") or "https://chatgpt.com/") or "https://chatgpt.com/"
        with contextlib.suppress(Exception):
            os.startfile(url)  # type: ignore[attr-defined]
    if "desktop" in targets:
        desktop_path = clean_text(env.get("CHATGPT_IMAGE_DESKTOP_PATH") or "")
        if desktop_path and (desktop_path.startswith("chatgpt://") or desktop_path.startswith("ms-")):
            with contextlib.suppress(Exception):
                os.startfile(desktop_path)  # type: ignore[attr-defined]
        elif desktop_path and Path(desktop_path).exists():
            with contextlib.suppress(Exception):
                subprocess.Popen(
                    [desktop_path],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    **background_subprocess_kwargs(),
                )
        elif not desktop_path:
            with contextlib.suppress(Exception):
                os.startfile("chatgpt://")  # type: ignore[attr-defined]
    return clipboard_copied


def wait_for_external_image(output_path: Path, timeout_seconds: float, log: Callable[[str], None] | None = None) -> Path:
    deadline = time.monotonic() + timeout_seconds
    last_size = -1
    stable_since = 0.0
    while time.monotonic() < deadline:
        if output_path.exists() and output_path.stat().st_size > 4096:
            size = output_path.stat().st_size
            now = time.monotonic()
            if size == last_size:
                if not stable_since:
                    stable_since = now
                if now - stable_since >= 1.5:
                    return output_path
            else:
                last_size = size
                stable_since = now
        time.sleep(2.0)
    handoff = chatgpt_handoff_dir(output_path) / f"{output_path.stem}.html"
    raise RuntimeError(
        "ChatGPT 接力等待超时：请在 ChatGPT 生成图片后，把 PNG 保存到 "
        f"{output_path}，然后重试当前图片或重新运行图片步骤。接力页：{handoff}"
    )


def cleanup_chatgpt_handoff_artifacts(output_path: Path, log: Callable[[str], None] | None = None) -> None:
    handoff_dir = chatgpt_handoff_dir(output_path)
    stem = output_path.stem
    removed: list[str] = []
    for path in (
        handoff_dir / f"{stem}.html",
        handoff_dir / f"{stem}.prompt.txt",
        handoff_dir / f"{stem}.handoff.json",
    ):
        try:
            path.unlink()
            removed.append(path.name)
        except FileNotFoundError:
            continue
        except Exception:
            continue
    with contextlib.suppress(Exception):
        if handoff_dir.exists() and not any(handoff_dir.iterdir()):
            handoff_dir.rmdir()
    if log and removed:
        log(f"[images] 已清理 ChatGPT 接力提示词文件：{', '.join(removed)}")


def generate_chatgpt_handoff_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    provider_key: str = "chatgpt_handoff",
) -> Path:
    clean_prompt = build_chatgpt_handoff_prompt(prompt, size, purpose)
    open_target = resolve_chatgpt_handoff_target(env, provider_key)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    backup_paths: list[tuple[Path, Path]] = []
    backup_stamp = storage.now_ms()
    for current_path in (output_path, output_path.with_suffix(".md"), output_path.with_suffix(".audit.json")):
        if not current_path.exists():
            continue
        backup_path = current_path.with_name(f".{current_path.name}.handoff-backup-{backup_stamp}")
        current_path.replace(backup_path)
        backup_paths.append((current_path, backup_path))
    try:
        storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")
        page_path = write_chatgpt_handoff_page(clean_prompt, output_path, size, purpose, env, open_target=open_target)
        clipboard_copied = open_chatgpt_handoff(page_path, env, clean_prompt, open_target=open_target)
        if log:
            target_label = "ChatGPT Classic" if open_target == "desktop" else "ChatGPT 网页"
            log(f"[images] {target_label} 接力文件已生成：{page_path}")
            if clipboard_copied:
                log(f"[images] 生图提示词已复制并自动存档；请手动粘贴发送，生成后保存到：{output_path}")
            else:
                prompt_path = chatgpt_handoff_dir(output_path) / f"{output_path.stem}.prompt.txt"
                log(f"[images] 剪贴板写入失败，请从 {prompt_path} 复制提示词，生成后保存到：{output_path}")
        result = wait_for_external_image(output_path, chatgpt_image_wait_seconds(env), log=log)
        cleanup_chatgpt_handoff_artifacts(output_path, log=log)
        for _current_path, backup_path in backup_paths:
            backup_path.unlink(missing_ok=True)
        return result
    except Exception:
        for current_path, backup_path in backup_paths:
            if backup_path.exists():
                current_path.unlink(missing_ok=True)
                backup_path.replace(current_path)
        cleanup_chatgpt_handoff_artifacts(output_path, log=log)
        raise


def default_chatgpt_browser_profile_dir() -> Path:
    return storage.CONFIG_ROOT / "chatgpt-browser-profile"


