class ChatgptLoginRequiredError(RuntimeError):
    pass


class ChatgptAccessChallengeError(RuntimeError):
    pass


class ChatgptGenerationCancelledError(RuntimeError):
    pass


def chatgpt_image_account_count(env: dict[str, str]) -> int:
    if chatgpt_account_provider(env) == "ant_browser":
        try:
            return max(1, len(ant_browser.discover_accounts(env)))
        except Exception:
            return max(1, len(ant_browser.parse_launch_codes(env.get("ANT_BROWSER_LAUNCH_CODES") or "")))
    try:
        return max(1, min(int(clean_text(env.get("CHATGPT_IMAGE_ACCOUNT_COUNT") or "1")), 12))
    except ValueError:
        return 1


def chatgpt_image_cdp_base_port(env: dict[str, str]) -> int:
    try:
        return max(1024, min(int(clean_text(env.get("CHATGPT_IMAGE_CDP_BASE_PORT") or "9222")), 65000))
    except ValueError:
        return 9222


def chatgpt_account_provider(env: dict[str, str]) -> str:
    provider = clean_text(env.get("CHATGPT_ACCOUNT_PROVIDER") or "local").lower()
    return "local" if provider == "local" else "ant_browser"


def chatgpt_image_accounts(env: dict[str, str]) -> list[dict[str, Any]]:
    if chatgpt_account_provider(env) == "ant_browser":
        accounts = ant_browser.discover_accounts(env)
        if not accounts:
            raise RuntimeError("Ant Browser 中还没有带快捷打开码的实例。")
        return accounts
    count = chatgpt_image_account_count(env)
    base_port = chatgpt_image_cdp_base_port(env)
    base_profile = chatgpt_browser_user_data_dir(env)
    raw_labels = [clean_text(item) for item in clean_text(env.get("CHATGPT_IMAGE_ACCOUNT_LABELS") or "").split(",")]
    accounts: list[dict[str, Any]] = []
    for index in range(count):
        profile_dir = base_profile if index == 0 else base_profile.with_name(f"{base_profile.name}-account-{index + 1:02d}")
        account_id = f"account-{index + 1:02d}"
        accounts.append(
            {
                "id": account_id,
                "index": index + 1,
                "label": raw_labels[index] if index < len(raw_labels) and raw_labels[index] else f"ChatGPT 账号 {index + 1}",
                "port": base_port + index,
                "cdp_url": f"http://127.0.0.1:{base_port + index}",
                "profile_dir": profile_dir,
            }
        )
    return accounts


def chatgpt_cdp_metadata(account: dict[str, Any], timeout: float = 1.5) -> dict[str, Any]:
    if not clean_text(str(account.get("cdp_url") or "")):
        return {}
    endpoint = f"{account['cdp_url']}/json/version"
    try:
        with urllib.request.urlopen(endpoint, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def chatgpt_access_challenge_reason(title: str = "", url: str = "", body_text: str = "") -> str:
    normalized_title = clean_text(title).lower()
    normalized_url = clean_text(url).lower()
    normalized_body = clean_text(body_text).lower()
    if any(token in normalized_url for token in ("challenges.cloudflare.com", "/cdn-cgi/challenge")):
        return "Cloudflare 安全验证页"
    challenge_tokens = (
        "请稍候",
        "just a moment",
        "verify you are human",
        "正在验证",
        "安全验证",
        "checking your browser",
        "cloudflare",
        "check your inbox",
        "verify your email",
        "检查你的收件箱",
        "验证你的邮箱",
    )
    if any(token in normalized_title for token in challenge_tokens):
        return clean_text(title) or "ChatGPT 安全验证页"
    if any(token in normalized_body for token in challenge_tokens):
        return "ChatGPT 安全验证页"
    return ""


def chatgpt_cdp_page_status(account: dict[str, Any], timeout: float = 0.4) -> dict[str, str]:
    endpoint = f"{account['cdp_url']}/json/list"
    try:
        with urllib.request.urlopen(endpoint, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
    except Exception:
        return {"state": "closed", "title": "", "url": ""}
    pages = [item for item in payload if isinstance(item, dict) and item.get("type") == "page"] if isinstance(payload, list) else []
    for item in pages:
        title = clean_text(str(item.get("title") or ""))
        target_url = clean_text(str(item.get("url") or ""))
        if chatgpt_access_challenge_reason(title, target_url):
            return {"state": "challenge", "title": title, "url": target_url}
    chatgpt_page = next((item for item in pages if "chatgpt.com" in str(item.get("url") or "").lower()), None)
    if chatgpt_page:
        return {
            "state": "chatgpt",
            "title": clean_text(str(chatgpt_page.get("title") or "")),
            "url": clean_text(str(chatgpt_page.get("url") or "")),
        }
    if pages:
        return {
            "state": "other",
            "title": clean_text(str(pages[0].get("title") or "")),
            "url": clean_text(str(pages[0].get("url") or "")),
        }
    return {"state": "empty", "title": "", "url": ""}


def _wait_for_chatgpt_cdp_shutdown(account: dict[str, Any], timeout_seconds: float) -> bool:
    deadline = time.monotonic() + max(0.5, float(timeout_seconds or 0))
    while time.monotonic() < deadline:
        if not chatgpt_cdp_metadata(account, timeout=0.2):
            return True
        time.sleep(0.25)
    return not bool(chatgpt_cdp_metadata(account, timeout=0.2))


def _terminate_managed_chatgpt_process(account: dict[str, Any]) -> bool:
    account_id = clean_text(str(account.get("id") or ""))
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        process = _CHATGPT_CDP_PROCESSES.pop(account_id, None)
    if process is None:
        return False
    try:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5.0)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=3.0)
        return True
    except Exception:
        return False


def _wait_for_managed_chatgpt_process_exit(
    account: dict[str, Any],
    timeout_seconds: float = 8.0,
) -> bool:
    account_id = clean_text(str(account.get("id") or ""))
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        process = _CHATGPT_CDP_PROCESSES.get(account_id)
    if process is None:
        return True
    try:
        process.wait(timeout=max(0.5, float(timeout_seconds or 0)))
    except subprocess.TimeoutExpired:
        return False
    except Exception:
        with contextlib.suppress(Exception):
            if process.poll() is None:
                return False
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        if _CHATGPT_CDP_PROCESSES.get(account_id) is process:
            _CHATGPT_CDP_PROCESSES.pop(account_id, None)
    return True


def _request_chatgpt_browser_shutdown(browser: Any) -> None:
    """Close the external Chromium process, not only the Playwright connection."""
    session: Any = None
    try:
        session = browser.new_browser_cdp_session()
        session.send("Browser.close")
        return
    except Exception:
        with contextlib.suppress(Exception):
            browser.close()
    finally:
        if session is not None:
            with contextlib.suppress(Exception):
                session.detach()


def close_connected_chatgpt_browser(
    browser: Any,
    account: dict[str, Any],
    *,
    timeout_seconds: float = 10.0,
    log: Callable[[str], None] | None = None,
    image_saved: bool = True,
) -> bool:
    if account.get("provider") == "ant_browser":
        stopped = False
        try:
            env = runtime_env()
            ant_browser.client_from_env(env, timeout=max(3.0, timeout_seconds)).stop(str(account.get("code") or ""))
            stopped = True
        except Exception as exc:
            if log:
                log(f"[images] Ant Browser 实例 {account.get('code') or account.get('label')} 回收异常：{user_facing_error(exc)}")
        with contextlib.suppress(Exception):
            browser.close()
        if log and stopped:
            log(f"[images] {account['label']} 已由 Ant Browser 停止，登录资料仍由 Ant Browser 保管")
        return stopped
    with contextlib.suppress(Exception):
        _request_chatgpt_browser_shutdown(browser)
    closed = _wait_for_chatgpt_cdp_shutdown(account, timeout_seconds)
    if not closed:
        _terminate_managed_chatgpt_process(account)
        closed = _wait_for_chatgpt_cdp_shutdown(account, 6.0)
    else:
        # The CDP endpoint disappears before Chrome finishes persisting its
        # clean-exit state. Give the managed process time to leave normally;
        # terminating it here makes the next launch offer to restore pages.
        gracefully_exited = _wait_for_managed_chatgpt_process_exit(
            account,
            timeout_seconds=max(6.0, min(float(timeout_seconds or 0), 15.0)),
        )
        if not gracefully_exited:
            _terminate_managed_chatgpt_process(account)
    if log:
        if closed:
            result_label = "本张图片已保存" if image_saved else "本次生图已结束"
            log(f"[images] {account['label']} {result_label}，Chrome 已确认关闭")
        else:
            result_label = "图片已保存" if image_saved else "生图失败"
            log(f"[images] {account['label']} {result_label}，但 Chrome 未能自动退出；请在账号管理中关闭该窗口")
    return closed


def close_chatgpt_cdp_browser(account: dict[str, Any], timeout_seconds: float = 8.0) -> bool:
    if account.get("provider") == "ant_browser":
        try:
            ant_browser.client_from_env(runtime_env(), timeout=max(3.0, timeout_seconds)).stop(
                str(account.get("code") or "")
            )
            account["cdp_url"] = ""
            account["port"] = 0
            return True
        except Exception:
            return False
    if not chatgpt_cdp_metadata(account, timeout=0.2):
        if not _wait_for_managed_chatgpt_process_exit(account, timeout_seconds=3.0):
            _terminate_managed_chatgpt_process(account)
        return True
    browser: Any = None
    try:
        from playwright.sync_api import sync_playwright

        with sync_playwright() as playwright:
            browser = playwright.chromium.connect_over_cdp(account["cdp_url"], timeout=5000)
            return close_connected_chatgpt_browser(
                browser,
                account,
                timeout_seconds=timeout_seconds,
            )
    except Exception:
        _terminate_managed_chatgpt_process(account)
        return _wait_for_chatgpt_cdp_shutdown(account, 3.0)


def chatgpt_profile_has_saved_session(profile_dir: Path) -> bool:
    profile_dir = Path(profile_dir)
    cookie_files = (
        profile_dir / "Default" / "Network" / "Cookies",
        profile_dir / "Default" / "Cookies",
    )
    auth_cookie_names = (
        "__Secure-next-auth.session-token",
        "oai-client-auth-session",
        "oai-client-auth-info",
        "_puid",
    )
    placeholders = ",".join("?" for _item in auth_cookie_names)
    for cookie_file in cookie_files:
        if not cookie_file.is_file() or cookie_file.stat().st_size <= 4096:
            continue
        connection: sqlite3.Connection | None = None
        try:
            connection = sqlite3.connect(
                f"file:{cookie_file.resolve().as_posix()}?mode=ro",
                uri=True,
                timeout=0.2,
            )
            row = connection.execute(
                f"""
                SELECT 1
                FROM cookies
                WHERE (host_key LIKE '%chatgpt.com' OR host_key LIKE '%openai.com')
                  AND name IN ({placeholders})
                LIMIT 1
                """,
                auth_cookie_names,
            ).fetchone()
            if row:
                return True
        except (OSError, sqlite3.Error):
            continue
        finally:
            if connection is not None:
                connection.close()
    return False


def ensure_chatgpt_cdp_browser(
    account: dict[str, Any],
    env: dict[str, str],
    *,
    url: str | None = None,
    log: Callable[[str], None] | None = None,
    headless: bool | None = None,
    abort_event: threading.Event | None = None,
) -> dict[str, Any]:
    if abort_event is not None and abort_event.is_set():
        raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。")
    if account.get("provider") == "ant_browser":
        client = ant_browser.client_from_env(env, timeout=130.0)
        code = clean_text(str(account.get("code") or ""))
        if not code:
            raise RuntimeError("Ant Browser 实例缺少快捷打开码。")
        if log:
            log(f"[images] 正在通过 Ant Browser 启动实例 {code}（{account['label']}）")
        session = client.start_session(
            code,
            start_url=clean_text(url or env.get("CHATGPT_IMAGE_WEB_URL") or "https://chatgpt.com/"),
            timeout_ms=120000,
        )
        direct_url = clean_text(str(session.get("directDebugUrl") or session.get("cdpUrl") or ""))
        if not direct_url:
            raise RuntimeError(f"Ant Browser 实例 {code} 未返回 CDP 地址。")
        account["cdp_url"] = direct_url.rstrip("/")
        account["port"] = int(session.get("debugPort") or session.get("cdpPort") or 0)
        account["profile_id"] = clean_text(str(session.get("profileId") or account.get("profile_id") or ""))
        metadata = chatgpt_cdp_metadata(account, timeout=5.0)
        if not metadata:
            raise RuntimeError(f"Ant Browser 实例 {code} 的 CDP 连接还未就绪。")
        return metadata
    metadata = chatgpt_cdp_metadata(account)
    if metadata:
        return metadata
    browser_path = resolve_chatgpt_browser_path(env)
    if not browser_path:
        raise RuntimeError("没有找到可用于 ChatGPT 端口连接的 Chrome/Edge。")
    profile_dir = storage.ensure_dir(Path(account["profile_dir"]))
    target_url = clean_text(url or env.get("CHATGPT_IMAGE_WEB_URL") or "https://chatgpt.com/") or "https://chatgpt.com/"
    background_mode = env_flag(env.get("CHATGPT_IMAGE_HEADLESS")) if headless is None else bool(headless)
    true_headless = background_mode and env_flag(env.get("CHATGPT_IMAGE_TRUE_HEADLESS"))
    args = [
        browser_path,
        f"--remote-debugging-address=127.0.0.1",
        f"--remote-debugging-port={account['port']}",
        f"--user-data-dir={profile_dir}",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-session-crashed-bubble",
        "--hide-crash-restore-bubble",
        "--disable-background-mode",
        "--window-size=1480,1120",
    ]
    if true_headless:
        args.extend(["--headless=new", "--disable-gpu", "--hide-scrollbars"])
    elif background_mode:
        args.extend(
            [
                "--start-minimized",
                "--window-position=-32000,-32000",
                "--disable-background-timer-throttling",
                "--disable-renderer-backgrounding",
                "--disable-backgrounding-occluded-windows",
            ]
        )
    else:
        args.extend(["--new-window", "--window-position=80,80"])
    args.append(target_url)
    process = subprocess.Popen(
        args,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        **background_subprocess_kwargs(),
    )
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        previous = _CHATGPT_CDP_PROCESSES.get(account["id"])
        if previous is None or previous.poll() is not None:
            _CHATGPT_CDP_PROCESSES[account["id"]] = process
    if log:
        mode_label = "真无头浏览器" if true_headless else "后台端口浏览器" if background_mode else "可见登录浏览器"
        log(f"[images] 正在启动 {account['label']} 的{mode_label}，端口 {account['port']}")
    deadline = time.monotonic() + 25.0
    while time.monotonic() < deadline:
        if abort_event is not None and abort_event.is_set():
            _terminate_managed_chatgpt_process(account)
            raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。")
        metadata = chatgpt_cdp_metadata(account)
        if metadata:
            return metadata
        time.sleep(0.5)
    raise RuntimeError(
        f"{account['label']} 的浏览器端口 {account['port']} 未能启动。"
        "请关闭占用该账号资料夹的旧 Chrome 窗口后重试。"
    )


def acquire_chatgpt_image_account(env: dict[str, str]) -> tuple[dict[str, Any], threading.Lock]:
    global _CHATGPT_ACCOUNT_POOL_CURSOR
    accounts = chatgpt_image_accounts(env)
    deadline = time.monotonic() + 30.0
    while time.monotonic() < deadline:
        now = storage.now_ts()
        with _CHATGPT_ACCOUNT_POOL_LOCK:
            start = _CHATGPT_ACCOUNT_POOL_CURSOR % len(accounts)
            ordered = accounts[start:] + accounts[:start]
            for account in ordered:
                health = _CHATGPT_ACCOUNT_HEALTH.get(account["id"], {})
                if len(accounts) > 1 and float(health.get("cooldown_until", 0) or 0) > now:
                    continue
                use_lock = _CHATGPT_ACCOUNT_USE_LOCKS.setdefault(account["id"], threading.Lock())
                if use_lock.acquire(blocking=False):
                    abort_event = threading.Event()
                    _CHATGPT_ACCOUNT_LEASES[account["id"]] = {
                        "lock": use_lock,
                        "abort_event": abort_event,
                        "started_at": now,
                        "owner_thread": threading.current_thread(),
                    }
                    _CHATGPT_ACCOUNT_POOL_CURSOR = (int(account["index"]) % len(accounts))
                    health["last_selected_at"] = now
                    _CHATGPT_ACCOUNT_HEALTH[account["id"]] = health
                    return account, use_lock
        time.sleep(0.5)
    raise RuntimeError("所有 ChatGPT 生图账号都在使用或冷却中，请稍后自动续跑。")


def chatgpt_account_abort_event(account: dict[str, Any], account_lock: threading.Lock) -> threading.Event:
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        lease = _CHATGPT_ACCOUNT_LEASES.get(account["id"]) or {}
        if lease.get("lock") is account_lock and isinstance(lease.get("abort_event"), threading.Event):
            return lease["abort_event"]
        abort_event = threading.Event()
        _CHATGPT_ACCOUNT_LEASES[account["id"]] = {
            "lock": account_lock,
            "abort_event": abort_event,
            "started_at": storage.now_ts(),
            "owner_thread": threading.current_thread(),
        }
        return abort_event


def release_chatgpt_image_account(account: dict[str, Any], account_lock: threading.Lock) -> None:
    with contextlib.suppress(RuntimeError):
        account_lock.release()
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        lease = _CHATGPT_ACCOUNT_LEASES.get(account["id"])
        if lease and lease.get("lock") is account_lock:
            _CHATGPT_ACCOUNT_LEASES.pop(account["id"], None)


def abort_active_chatgpt_image_generations(
    env: dict[str, str],
    *,
    timeout_seconds: float = 12.0,
) -> dict[str, Any]:
    """Stop active browser work and wait for worker threads to return their account leases."""
    targets: list[tuple[dict[str, Any], threading.Lock]] = []
    accounts_by_id = {account["id"]: account for account in chatgpt_image_accounts(env)}
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        for account_id, lease in list(_CHATGPT_ACCOUNT_LEASES.items()):
            account = accounts_by_id.get(account_id)
            use_lock = lease.get("lock")
            abort_event = lease.get("abort_event")
            if account is None or use_lock is None or not hasattr(use_lock, "locked"):
                continue
            if not use_lock.locked():
                _CHATGPT_ACCOUNT_LEASES.pop(account_id, None)
                continue
            if isinstance(abort_event, threading.Event):
                abort_event.set()
            lease["abort_requested_at"] = storage.now_ts()
            targets.append((account, use_lock))
    for account, _use_lock in targets:
        with contextlib.suppress(Exception):
            close_chatgpt_cdp_browser(account, timeout_seconds=min(6.0, timeout_seconds))
    deadline = time.monotonic() + max(0.0, timeout_seconds)
    while targets and time.monotonic() < deadline:
        if all(not use_lock.locked() for _account, use_lock in targets):
            break
        time.sleep(0.1)
    released = [account["id"] for account, use_lock in targets if not use_lock.locked()]
    pending = [account["id"] for account, use_lock in targets if use_lock.locked()]
    return {"requested": len(targets), "released": released, "pending": pending}


def record_chatgpt_account_result(account: dict[str, Any], *, error: str = "", env: dict[str, str] | None = None) -> None:
    now = storage.now_ts()
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        health = _CHATGPT_ACCOUNT_HEALTH.setdefault(account["id"], {})
        if not error:
            health.update({"failures": 0, "cooldown_until": 0, "last_success_at": now, "last_error": ""})
            return
        failures = int(health.get("failures", 0) or 0) + 1
        source = clean_text(error)
        configured = env or {}
        try:
            default_cooldown = int(float(clean_text(configured.get("CHATGPT_IMAGE_ACCOUNT_COOLDOWN_SECONDS") or "180")))
        except ValueError:
            default_cooldown = 180
        cooldown = 900 if any(token in source for token in ("额度", "上限", "登录", "套餐")) else max(60, default_cooldown)
        health.update(
            {
                "failures": failures,
                "cooldown_until": now + cooldown,
                "last_failure_at": now,
                "last_error": source[:300],
            }
        )


def _reconcile_stale_chatgpt_account_lease(
    account: dict[str, Any],
    *,
    browser_connected: bool,
    now: float | None = None,
    grace_seconds: float = 8.0,
    orphan_timeout_seconds: float = 1200.0,
) -> bool:
    """Release an aborted account lease after its browser has already gone away.

    Browser shutdown and the image worker run on different threads. If the
    worker is interrupted while unwinding, the CDP process can be gone while
    the per-account lock remains held forever. Status polling reconciles that
    impossible state after a short cleanup grace period.
    """
    if browser_connected:
        return False
    current_time = storage.now_ts() if now is None else float(now)
    account_id = clean_text(str(account.get("id") or ""))
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        use_lock = _CHATGPT_ACCOUNT_USE_LOCKS.get(account_id)
        lease = _CHATGPT_ACCOUNT_LEASES.get(account_id)
        if not use_lock or not lease or not use_lock.locked():
            if lease and (not use_lock or not use_lock.locked()):
                _CHATGPT_ACCOUNT_LEASES.pop(account_id, None)
            return False
        abort_event = lease.get("abort_event")
        abort_requested = isinstance(abort_event, threading.Event) and abort_event.is_set()
        owner_thread = lease.get("owner_thread")
        owner_gone = isinstance(owner_thread, threading.Thread) and not owner_thread.is_alive()
        started_at = float(lease.get("started_at") or current_time)
        lease_age = max(0.0, current_time - started_at)
        legacy_orphan = owner_thread is None and lease_age >= max(60.0, float(orphan_timeout_seconds or 0))
        if abort_requested:
            requested_at = float(lease.get("abort_requested_at") or started_at)
            if current_time - requested_at < max(1.0, float(grace_seconds or 0)):
                return False
        elif not owner_gone and not legacy_orphan:
            return False
        with contextlib.suppress(RuntimeError):
            use_lock.release()
        if _CHATGPT_ACCOUNT_LEASES.get(account_id) is lease:
            _CHATGPT_ACCOUNT_LEASES.pop(account_id, None)
        process = _CHATGPT_CDP_PROCESSES.get(account_id)
        if process is not None and process.poll() is not None:
            _CHATGPT_CDP_PROCESSES.pop(account_id, None)
        return not use_lock.locked()


def chatgpt_account_pool_status(env: dict[str, str]) -> dict[str, Any]:
    now = storage.now_ts()
    accounts: list[dict[str, Any]] = []
    provider = chatgpt_account_provider(env)
    connection_error = ""
    try:
        source_accounts = chatgpt_image_accounts(env)
    except Exception as exc:
        source_accounts = []
        connection_error = user_facing_error(exc)
    for account in source_accounts:
        metadata = chatgpt_cdp_metadata(account, timeout=0.2)
        _reconcile_stale_chatgpt_account_lease(
            account,
            browser_connected=bool(metadata),
            now=now,
        )
        page_status = chatgpt_cdp_page_status(account, timeout=0.2) if metadata else {"state": "closed", "title": "", "url": ""}
        with _CHATGPT_ACCOUNT_POOL_LOCK:
            health = dict(_CHATGPT_ACCOUNT_HEALTH.get(account["id"], {}))
            use_lock = _CHATGPT_ACCOUNT_USE_LOCKS.get(account["id"])
            lease = dict(_CHATGPT_ACCOUNT_LEASES.get(account["id"], {}))
        cooldown_until = float(health.get("cooldown_until", 0) or 0)
        accounts.append(
            {
                "id": account["id"],
                "index": account["index"],
                "label": account["label"],
                "port": account["port"],
                "profile_dir": str(account.get("profile_dir") or ""),
                "provider": account.get("provider") or "local",
                "code": account.get("code") or "",
                "profile_id": account.get("profile_id") or "",
                "found": account.get("found", True),
                "connected": bool(metadata),
                "saved_session": bool(account.get("found"))
                if account.get("provider") == "ant_browser"
                else chatgpt_profile_has_saved_session(Path(account["profile_dir"])),
                "browser": clean_text(str(metadata.get("Browser") or "")),
                "page_state": page_status["state"],
                "page_title": page_status["title"],
                "busy": bool(use_lock and use_lock.locked()),
                "stopping": bool(
                    use_lock
                    and use_lock.locked()
                    and isinstance(lease.get("abort_event"), threading.Event)
                    and lease["abort_event"].is_set()
                ),
                "cooling_down": cooldown_until > now,
                "cooldown_remaining": max(0, int(cooldown_until - now)),
                "last_success_at": health.get("last_success_at"),
                "last_error": health.get("last_error", ""),
            }
        )
    return {
        "count": len(accounts),
        "strategy": "round_robin",
        "provider": provider,
        "api_url": clean_text(env.get("ANT_BROWSER_API_URL") or "http://127.0.0.1:19876"),
        "configured_codes": ant_browser.parse_launch_codes(env.get("ANT_BROWSER_LAUNCH_CODES") or ""),
        "connection_error": connection_error,
        "base_port": chatgpt_image_cdp_base_port(env) if provider == "local" else 0,
        "accounts": accounts,
    }


def test_ant_browser_connection(env: dict[str, str]) -> dict[str, Any]:
    client = ant_browser.client_from_env(env, timeout=5.0)
    client.health()
    profiles = client.list_profiles()
    codes = [clean_text(str(item.get("launchCode") or "")) for item in profiles]
    codes = [code for code in codes if code]
    return {
        "ok": True,
        "api_url": client.base_url,
        "profile_count": len(profiles),
        "code_count": len(codes),
        "codes": codes,
        "message": f"已连接 Ant Browser，共发现 {len(profiles)} 个实例、{len(codes)} 个快捷打开码。",
    }


def resolve_chatgpt_browser_path(env: dict[str, str]) -> str | None:
    configured = clean_text(env.get("CHATGPT_IMAGE_BROWSER_PATH") or "")
    if configured and Path(configured).exists():
        return configured
    candidates = [
        Path("C:/Program Files/Google/Chrome/Application/chrome.exe"),
        Path("C:/Program Files (x86)/Google/Chrome/Application/chrome.exe"),
        Path("C:/Program Files/Microsoft/Edge/Application/msedge.exe"),
        Path("C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe"),
    ]
    for candidate in candidates:
        if candidate.exists():
            return str(candidate)
    return None


def chatgpt_browser_user_data_dir(env: dict[str, str]) -> Path:
    configured = clean_text(env.get("CHATGPT_IMAGE_USER_DATA_DIR") or "")
    if configured:
        return Path(configured)
    return default_chatgpt_browser_profile_dir()


def open_chatgpt_login_window(
    env: dict[str, str],
    url: str | None = None,
    account_id: str | None = None,
) -> dict[str, Any]:
    login_url = clean_text(url or env.get("CHATGPT_IMAGE_WEB_URL") or "https://chatgpt.com/") or "https://chatgpt.com/"
    accounts = chatgpt_image_accounts(env)
    requested_account_id = clean_text(account_id or "")
    account = next((item for item in accounts if item["id"] == requested_account_id), None) if requested_account_id else accounts[0]
    if account is None:
        raise RuntimeError(f"没有找到 ChatGPT 生图账号：{requested_account_id}")
    with _CHATGPT_ACCOUNT_POOL_LOCK:
        use_lock = _CHATGPT_ACCOUNT_USE_LOCKS.get(account["id"])
    if use_lock and use_lock.locked():
        raise RuntimeError(f"{account['label']} 正在生图，请等待当前图片结束后再打开登录窗口。")
    if account.get("provider") == "ant_browser":
        ensure_chatgpt_cdp_browser(account, env, url=login_url, headless=False)
        return {
            "ok": True,
            "url": login_url,
            "browser_path": "Ant Browser",
            "profile_dir": "",
            "account_id": account["id"],
            "account_label": account["label"],
            "code": account.get("code") or "",
            "port": account["port"],
            "launch_mode": "ant-browser-code",
        }
    if chatgpt_cdp_metadata(account, timeout=0.2) and not close_chatgpt_cdp_browser(account):
        raise RuntimeError(f"{account['label']} 的后台浏览器仍在运行，请关闭旧窗口后再打开登录页。")
    ensure_chatgpt_cdp_browser(account, env, url=login_url, headless=False)
    return {
        "ok": True,
        "url": login_url,
        "browser_path": resolve_chatgpt_browser_path(env) or "",
        "profile_dir": str(account["profile_dir"]),
        "account_id": account["id"],
        "account_label": account["label"],
        "port": account["port"],
        "launch_mode": "cdp-port",
    }


def clear_chatgpt_login_state(env: dict[str, str]) -> dict[str, Any]:
    if chatgpt_account_provider(env) == "ant_browser":
        return {
            "ok": True,
            "existed": False,
            "removed_files": 0,
            "profile_dir": "",
            "message": "账号资料由 Ant Browser 管理，本工具没有保存登录资料。",
        }
    configured_dir = clean_text(env.get("CHATGPT_IMAGE_USER_DATA_DIR") or "")
    profile_dir = chatgpt_browser_user_data_dir(env)
    default_dir = default_chatgpt_browser_profile_dir()
    resolved_profile = profile_dir.resolve()
    resolved_default = default_dir.resolve()
    resolved_config = storage.CONFIG_ROOT.resolve()

    if configured_dir and not (resolved_profile == resolved_default or resolved_config in resolved_profile.parents):
        raise RuntimeError(
            "当前配置了自定义 ChatGPT 自动化登录资料夹。为避免误删你的真实浏览器数据，"
            f"请手动清理这个目录，或先把 CHATGPT_IMAGE_USER_DATA_DIR 留空：{profile_dir}"
        )

    existed = profile_dir.exists()
    removed_files = 0
    if existed:
        for _root, _dirs, files in os.walk(profile_dir):
            removed_files += len(files)

        def onerror(func: Callable[..., Any], path: str, _exc_info: Any) -> None:
            try:
                os.chmod(path, 0o700)
                func(path)
            except Exception as exc:
                raise RuntimeError(f"无法清理 ChatGPT 登录资料夹，请先关闭弹出的 ChatGPT/Chrome 窗口后再试：{path}") from exc

        try:
            shutil.rmtree(profile_dir, onerror=onerror)
        except RuntimeError:
            raise
        except Exception as exc:
            raise RuntimeError(f"无法清理 ChatGPT 登录资料夹，请先关闭弹出的 ChatGPT/Chrome 窗口后再试：{profile_dir}") from exc

    storage.ensure_dir(profile_dir)
    return {
        "ok": True,
        "existed": existed,
        "removed_files": removed_files,
        "profile_dir": str(profile_dir),
        "message": "ChatGPT 自动化登录状态已清空。下次生图会重新打开登录页。",
    }


def clear_chatgpt_account_login_state(env: dict[str, str], account_id: str) -> dict[str, Any]:
    if chatgpt_account_provider(env) == "ant_browser":
        raise RuntimeError("该实例由 Ant Browser 管理，请在 Ant Browser 中调整实例列表或快捷打开码。")
    requested_account_id = clean_text(account_id)
    accounts = chatgpt_image_accounts(env)
    account = next((item for item in accounts if item["id"] == requested_account_id), None)
    if account is None:
        raise RuntimeError(f"没有找到 ChatGPT 生图账号：{requested_account_id}")
    account_position = accounts.index(account)

    resolved_default = default_chatgpt_browser_profile_dir().resolve()
    resolved_config = storage.CONFIG_ROOT.resolve()
    affected_accounts = accounts[account_position:]
    for affected in affected_accounts:
        profile_dir = Path(affected["profile_dir"])
        resolved_profile = profile_dir.resolve()
        if not (resolved_profile == resolved_default or resolved_config in resolved_profile.parents):
            raise RuntimeError(
                "当前账号使用了工具数据目录之外的自定义浏览器资料夹。为避免误删真实浏览器数据，"
                f"请手动清理该目录：{profile_dir}"
            )
        if chatgpt_cdp_metadata(affected, timeout=0.2):
            raise RuntimeError(
                f"请先关闭 {affected['label']} 的 ChatGPT/Chrome 窗口，再删除账号。"
            )
        with _CHATGPT_ACCOUNT_POOL_LOCK:
            use_lock = _CHATGPT_ACCOUNT_USE_LOCKS.get(affected["id"])
            if use_lock and use_lock.locked():
                raise RuntimeError(f"{affected['label']} 正在执行生图任务，暂时不能删除账号。")

    if len(accounts) == 1:
        profile_dir = Path(account["profile_dir"])
        existed = profile_dir.exists()
        if existed:
            shutil.rmtree(profile_dir)
        storage.ensure_dir(profile_dir)
        return {
            "ok": True,
            "account_id": account["id"],
            "account_label": account["label"],
            "count": 1,
            "message": "生图至少需要保留一个账号槽位，已清空该账号的登录资料。",
        }

    staging_root = Path(tempfile.mkdtemp(prefix=".chatgpt-account-delete-", dir=storage.CONFIG_ROOT))
    staged_profiles: dict[int, Path] = {}
    try:
        for index in range(account_position, len(accounts)):
            source = Path(accounts[index]["profile_dir"])
            staged = staging_root / f"profile-{index + 1:02d}"
            if source.exists():
                shutil.move(str(source), str(staged))
                staged_profiles[index] = staged

        for index in range(account_position + 1, len(accounts)):
            staged = staged_profiles.get(index)
            if staged and staged.exists():
                destination = Path(accounts[index - 1]["profile_dir"])
                shutil.move(str(staged), str(destination))

        new_count = len(accounts) - 1
        env_patch = {"CHATGPT_IMAGE_ACCOUNT_COUNT": str(new_count)}
        raw_labels = clean_text(env.get("CHATGPT_IMAGE_ACCOUNT_LABELS") or "")
        if raw_labels:
            labels = [clean_text(item) for item in raw_labels.split(",")]
            if account_position < len(labels):
                labels.pop(account_position)
            env_patch["CHATGPT_IMAGE_ACCOUNT_LABELS"] = ",".join(labels)
        storage.save_env_patch(env_patch)
    except Exception as exc:
        for index in range(len(accounts) - 1, account_position, -1):
            shifted = Path(accounts[index - 1]["profile_dir"])
            original = Path(accounts[index]["profile_dir"])
            if shifted.exists() and not original.exists():
                with contextlib.suppress(Exception):
                    shutil.move(str(shifted), str(original))
        target_staged = staged_profiles.get(account_position)
        target_original = Path(account["profile_dir"])
        if target_staged and target_staged.exists() and not target_original.exists():
            with contextlib.suppress(Exception):
                shutil.move(str(target_staged), str(target_original))
        raise RuntimeError(f"删除 {account['label']} 失败，账号资料已尽量恢复：{exc}") from exc
    finally:
        with contextlib.suppress(Exception):
            shutil.rmtree(staging_root)

    with _CHATGPT_ACCOUNT_POOL_LOCK:
        _CHATGPT_ACCOUNT_HEALTH.clear()
        _CHATGPT_ACCOUNT_USE_LOCKS.clear()
        _CHATGPT_ACCOUNT_LEASES.clear()
    return {
        "ok": True,
        "account_id": account["id"],
        "account_label": account["label"],
        "count": new_count,
        "message": f"{account['label']} 已删除，后续账号已前移；当前共 {new_count} 个轮询账号。",
    }


def _surface_chatgpt_login(
    page: Any,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    account_id: str | None = None,
) -> None:
    try:
        current_url = clean_text(str(page.url or ""))
    except Exception:
        current_url = ""
    if env_flag(env.get("CHATGPT_IMAGE_HEADLESS")):
        with contextlib.suppress(Exception):
            browser = page.context.browser
            if browser is not None:
                browser.close()
        requested_account = next(
            (
                item
                for item in chatgpt_image_accounts(env)
                if item["id"] == clean_text(account_id or "")
            ),
            None,
        )
        if requested_account is not None:
            deadline = time.monotonic() + 8.0
            while chatgpt_cdp_metadata(requested_account, timeout=0.2) and time.monotonic() < deadline:
                time.sleep(0.25)
        try:
            opened = open_chatgpt_login_window(
                env,
                url=current_url or None,
                account_id=account_id,
            )
        except Exception as exc:
            if log:
                log(f"[images] 自动打开 ChatGPT 登录页失败：{exc}")
            raise ChatgptLoginRequiredError(
                "ChatGPT 账号登录已失效，自动打开登录窗口失败，请在账号管理中重新登录。"
            ) from exc
        if log:
            log(f"[images] 已自动打开可见的 ChatGPT 登录页：{opened.get('url')}")
            log(f"[images] 请完成 {opened.get('account_label') or '当前账号'} 登录；其他账号会继续轮询生图")
        raise ChatgptLoginRequiredError(
            f"{opened.get('account_label') or 'ChatGPT 账号'} 需要重新登录，已打开对应的可见登录窗口。"
        )
    with contextlib.suppress(Exception):
        page.bring_to_front()
    if log:
        log("[images] 已切到 ChatGPT 浏览器窗口，请先完成重新登录后再重试。")


def _write_image_bytes_as_png(data: bytes, output_path: Path) -> None:
    output_path.parent.mkdir(parents=True, exist_ok=True)
    if Image is not None:
        try:
            image = Image.open(io.BytesIO(data))
            image.save(output_path, format="PNG")
            return
        except Exception:
            pass
    output_path.write_bytes(data)


def _large_chatgpt_images_script() -> str:
    return """
() => {
  const main = document.querySelector("main") || document.querySelector('[role="main"]');
  const turns = Array.from(document.querySelectorAll(
    '[data-testid^="conversation-turn"], [data-message-author-role], [data-turn]'
  ));
  return Array.from(document.images)
  .map((img, index) => {
    const src = img.currentSrc || img.src || "";
    const turn = img.closest('[data-testid^="conversation-turn"], [data-message-author-role], [data-turn], article');
    const explicitRole = turn?.getAttribute("data-message-author-role")
      || turn?.getAttribute("data-turn")
      || turn?.querySelector('[data-message-author-role]')?.getAttribute("data-message-author-role")
      || turn?.querySelector('[data-turn]')?.getAttribute("data-turn")
      || "";
    const turnIndex = turn
      ? turns.findIndex((item) => item === turn || item.contains(turn) || turn.contains(item))
      : -1;
    const generatedImage = Boolean(
      img.closest('[id^="image-"], [class*="imagegen-image"]')
      || /backend-api\/estuary\/content/i.test(src)
      || /(?:已生成图片|generated image)/i.test(img.alt || "")
    );
    return {
      index,
      key: `${src}|${img.naturalWidth || img.width || 0}x${img.naturalHeight || img.height || 0}`,
      src,
      width: img.naturalWidth || img.width || 0,
      height: img.naturalHeight || img.height || 0,
      complete: Boolean(img.complete),
      alt: img.alt || "",
      in_main: main ? main.contains(img) : !img.closest("nav, aside"),
      assistant: explicitRole.toLowerCase() === "assistant",
      generated: generatedImage,
      turn_index: turnIndex
    };
  })
  .filter((item) => item.complete && item.src && item.width >= 256 && item.height >= 256)
}
"""


def chatgpt_image_snapshot_keys(images: Any) -> set[str]:
    if not isinstance(images, list):
        return set()
    return {
        clean_text(str(item.get("key") or f"{item.get('src', '')}|{item.get('width', 0)}x{item.get('height', 0)}"))
        for item in images
        if isinstance(item, dict) and clean_text(str(item.get("src") or ""))
    }


def _chatgpt_login_required(page: Any) -> bool:
    try:
        current_url = clean_text(str(page.url or "")).lower()
    except (AttributeError, RuntimeError):
        current_url = ""
    if any(token in current_url for token in ("/auth", "/login", "signin", "session", "verify")):
        return True
    selectors = [
        "button:has-text('登录')",
        "button:has-text('Log in')",
        "button:has-text('Sign in')",
        "a:has-text('登录')",
        "a:has-text('Log in')",
        "a:has-text('Sign in')",
        "button:has-text('Continue with Google')",
        "button:has-text('Continue with Microsoft')",
    ]
    for selector in selectors:
        try:
            locator = page.locator(selector).first
            if locator.count() and locator.is_visible(timeout=400):
                return True
        except (AttributeError, RuntimeError):
            continue
    try:
        body_text = clean_text(page.locator("body").inner_text(timeout=1200)).lower()
    except (AttributeError, RuntimeError):
        body_text = ""
    login_tokens = (
        "log in",
        "sign in",
        "continue with google",
        "continue with microsoft",
        "继续使用 google",
        "继续使用 microsoft",
        "登录",
        "注册",
    )
    return "chatgpt" in body_text and any(token in body_text for token in login_tokens)


def _raise_chatgpt_login_required(page: Any) -> None:
    try:
        current_url = clean_text(str(page.url or ""))
    except (AttributeError, RuntimeError):
        current_url = ""
    suffix = f" 当前页面：{current_url}" if current_url else ""
    raise ChatgptLoginRequiredError(
        "ChatGPT 登录状态已失效，请先重新登录 ChatGPT 后再重试生图。"
        " 请在账号管理中点击‘登录此账号’完成登录。"
        + suffix
    )


def _chatgpt_access_challenge(page: Any) -> str:
    try:
        current_url = clean_text(str(page.url or ""))
    except (AttributeError, RuntimeError):
        current_url = ""
    try:
        title = clean_text(str(page.title() or ""))
    except (AttributeError, RuntimeError):
        title = ""
    try:
        body_text = clean_text(str(page.locator("body").inner_text(timeout=1200) or ""))[:3000]
    except (AttributeError, RuntimeError):
        body_text = ""
    return chatgpt_access_challenge_reason(title, current_url, body_text)


def _raise_chatgpt_access_challenge(page: Any) -> None:
    reason = _chatgpt_access_challenge(page)
    if not reason:
        return
    raise ChatgptAccessChallengeError(
        f"当前账号进入了 {reason}，后台任务已停止等待并将自动轮换账号。"
        "请稍后在账号管理中打开该账号，手动完成一次验证。"
    )


def _wait_for_visible_chatgpt_challenge(
    page: Any,
    timeout_seconds: float = 180.0,
    log: Callable[[str], None] | None = None,
) -> None:
    reason = _chatgpt_access_challenge(page)
    if not reason:
        return
    with contextlib.suppress(Exception):
        page.bring_to_front()
    if log:
        log(f"[images] 当前账号进入 {reason}，已保留可见 Chrome 窗口；完成页面验证后任务会自动继续")
    deadline = time.monotonic() + max(30.0, timeout_seconds)
    next_progress_at = 0.0
    while time.monotonic() < deadline:
        reason = _chatgpt_access_challenge(page)
        if not reason:
            if log:
                log("[images] ChatGPT 页面验证已完成，继续输入提示词")
            return
        if log and time.monotonic() >= next_progress_at:
            remaining = max(0, int(deadline - time.monotonic()))
            log(f"[images] 等待可见 Chrome 完成验证，剩余约 {remaining}s")
            next_progress_at = time.monotonic() + 15.0
        page.wait_for_timeout(1500)
    raise ChatgptAccessChallengeError(
        "可见 Chrome 的 ChatGPT 安全验证等待超时；窗口已保留，请完成验证后继续任务。"
    )


def _fetch_image_b64_script() -> str:
    return """
async (src) => {
  const response = await fetch(src);
  const blob = await response.blob();
  const buffer = await blob.arrayBuffer();
  const bytes = new Uint8Array(buffer);
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return { b64: btoa(binary), type: blob.type || "" };
}
"""


def _find_chatgpt_composer(page: Any, timeout_seconds: float = 180.0) -> tuple[Any, str]:
    selectors = [
        "textarea#prompt-textarea",
        "#prompt-textarea",
        "textarea",
        "div.ProseMirror",
        "[contenteditable='true']",
    ]
    deadline = time.monotonic() + timeout_seconds
    last_error = ""
    while time.monotonic() < deadline:
        _raise_chatgpt_access_challenge(page)
        if _chatgpt_login_required(page):
            _raise_chatgpt_login_required(page)
        for selector in selectors:
            locator = page.locator(selector).last
            try:
                if locator.count() and locator.is_visible(timeout=800):
                    return locator, selector
            except Exception as exc:
                last_error = str(exc)
        page.wait_for_timeout(1200)
    _raise_chatgpt_access_challenge(page)
    if _chatgpt_login_required(page):
        _raise_chatgpt_login_required(page)
    raise RuntimeError(
        "ChatGPT 网页自动化没有找到输入框。请在弹出的 Chrome 里登录 ChatGPT，确认能正常发送消息后重试。"
        + (f" 最近错误：{last_error}" if last_error else "")
    )


def _fill_chatgpt_composer(
    page: Any,
    prompt: str,
    env: dict[str, str] | None = None,
    log: Callable[[str], None] | None = None,
    timeout_seconds: float = 180.0,
    account_id: str | None = None,
) -> None:
    deadline = time.monotonic() + max(30.0, timeout_seconds)
    last_error = ""
    login_hint_logged = False
    waiting_hint_logged = False
    next_progress_at = 0.0
    while time.monotonic() < deadline:
        try:
            composer, selector = _find_chatgpt_composer(page, timeout_seconds=12.0)
            if selector.startswith("textarea"):
                composer.evaluate(
                    """
(el, text) => {
  el.scrollIntoView({ block: "center", inline: "nearest" });
  el.focus();
  const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value")?.set;
  if (setter) setter.call(el, text);
  else el.value = text;
  el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: text }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
}
""",
                    prompt,
                )
            else:
                composer.evaluate(
                    """
(el, text) => {
  el.scrollIntoView({ block: "center", inline: "nearest" });
  el.focus();
  document.execCommand("selectAll", false, null);
  document.execCommand("insertText", false, text);
  el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: text }));
}
""",
                    prompt,
                )
            return
        except (ChatgptAccessChallengeError, ChatgptLoginRequiredError):
            raise
        except Exception as exc:
            last_error = str(exc)
            _raise_chatgpt_access_challenge(page)
            if _chatgpt_login_required(page):
                _raise_chatgpt_login_required(page)
            if log and not waiting_hint_logged:
                log("[images] ChatGPT 输入框暂时不可编辑，正在轮询等待页面加载完成")
                waiting_hint_logged = True
            if log and time.monotonic() >= next_progress_at:
                remaining = max(0, int(deadline - time.monotonic()))
                log(f"[images] ChatGPT 页面等待中，剩余约 {remaining}s")
                next_progress_at = time.monotonic() + 20.0
            page.wait_for_timeout(1800)
    _raise_chatgpt_access_challenge(page)
    if _chatgpt_login_required(page):
        _raise_chatgpt_login_required(page)
    raise RuntimeError(
        "ChatGPT 输入框长时间不可编辑，请确认已登录且页面完全加载后重试。"
        + (f" 最近错误：{last_error}" if last_error else "")
    )


def _attach_chatgpt_reference_images(
    page: Any,
    reference_images: list[Path],
    log: Callable[[str], None] | None = None,
) -> None:
    paths = [path.resolve() for path in reference_images if path.exists() and path.suffix.lower() in RASTER_IMAGE_SUFFIXES][:6]
    if not paths:
        return
    candidates = page.locator("input[type='file']")
    chosen = None
    with contextlib.suppress(Exception):
        for index in range(int(candidates.count())):
            candidate = candidates.nth(index)
            accept = clean_text(str(candidate.get_attribute("accept") or "")).lower()
            if not accept or "image" in accept or any(ext in accept for ext in (".png", ".jpg", ".jpeg", ".webp")):
                chosen = candidate
                break
    if chosen is None:
        for selector in (
            "button[data-testid='composer-plus-btn']",
            "button[aria-label*='添加']",
            "button[aria-label*='Add']",
        ):
            with contextlib.suppress(Exception):
                button = page.locator(selector).last
                if button.count() and button.is_visible(timeout=500) and button.is_enabled(timeout=500):
                    button.click(timeout=3000)
                    page.wait_for_timeout(400)
                    break
        candidates = page.locator("input[type='file']")
        with contextlib.suppress(Exception):
            if candidates.count():
                chosen = candidates.last
    if chosen is None:
        raise RuntimeError("ChatGPT 商品图生图没有找到参考图上传入口，本张已停止，避免退回文生图生成错误商品。")
    chosen.set_input_files([str(path) for path in paths], timeout=30000)
    page.wait_for_timeout(1800)
    if log:
        log(f"[images] 已上传 {len(paths)} 张商品参考图，本张按图生图保持商品外观")


def _click_chatgpt_send(page: Any) -> None:
    selectors = [
        "button[data-testid='send-button']",
        "button[aria-label*='Send']",
        "button[aria-label*='发送']",
        "button:has-text('发送')",
        "button:has-text('Send')",
    ]
    for _ in range(30):
        for selector in selectors:
            button = page.locator(selector).last
            try:
                if button.count() and button.is_visible(timeout=500) and button.is_enabled(timeout=500):
                    button.click(timeout=5000)
                    return
            except Exception:
                continue
        page.wait_for_timeout(500)
    page.keyboard.press("Enter")


def _chatgpt_generation_page_state(page: Any) -> dict[str, Any]:
    body_text = ""
    with contextlib.suppress(Exception):
        body_text = str(page.locator("body").inner_text(timeout=2500) or "")
    recent_text = re.sub(r"\s+", " ", body_text[-12000:]).strip()
    lowered = recent_text.lower()

    active = any(
        marker in lowered
        for marker in (
            "正在生成图片",
            "图片生成中",
            "creating image",
            "generating image",
            "creating images",
        )
    )
    if not active:
        for selector in (
            "button[data-testid='stop-button']",
            "button[aria-label*='Stop']",
            "button[aria-label*='停止']",
            "button:has-text('停止生成')",
        ):
            with contextlib.suppress(Exception):
                locator = page.locator(selector).last
                if locator.count() and locator.is_visible(timeout=300):
                    active = True
                    break

    send_ready = False
    for selector in (
        "button[data-testid='send-button']",
        "button[aria-label*='Send']",
        "button[aria-label*='发送']",
    ):
        with contextlib.suppress(Exception):
            locator = page.locator(selector).last
            if locator.count() and locator.is_visible(timeout=300) and locator.is_enabled(timeout=300):
                send_ready = True
                break

    error = ""
    error_markers = (
        ("you've reached your image generation limit", "ChatGPT 图片生成额度已用完"),
        ("you have reached your image generation limit", "ChatGPT 图片生成额度已用完"),
        ("已达到图片生成上限", "ChatGPT 图片生成额度已用完"),
        ("we experienced an error when generating images", "ChatGPT 图片生成服务返回错误"),
        ("we experienced an error while generating images", "ChatGPT 图片生成服务返回错误"),
        ("there was an error generating your image", "ChatGPT 图片生成服务返回错误"),
        ("something went wrong while generating", "ChatGPT 生成图片时出错"),
        ("生成图片时出错", "ChatGPT 生成图片时出错"),
        ("image generation failed", "ChatGPT 图片生成失败"),
        ("failed to generate image", "ChatGPT 图片生成失败"),
        ("too many requests", "ChatGPT 当前请求过多"),
        ("rate limit", "ChatGPT 当前请求频率受限"),
        ("please try again later", "ChatGPT 暂时不可用，请稍后重试"),
        ("请稍后重试", "ChatGPT 暂时不可用，请稍后重试"),
        ("log in to continue", "ChatGPT 账号登录已失效"),
        ("please log in", "ChatGPT 账号登录已失效"),
        ("登录以继续", "ChatGPT 账号登录已失效"),
        ("network error", "ChatGPT 页面网络连接异常"),
        ("网络错误", "ChatGPT 页面网络连接异常"),
    )
    for marker, message in error_markers:
        if marker in lowered:
            error = message
            break

    signature = hashlib.sha256(recent_text.encode("utf-8", errors="ignore")).hexdigest()[:16] if recent_text else ""
    return {
        "active": active,
        "send_ready": send_ready,
        "error": error,
        "signature": signature,
    }


def chatgpt_image_wait_failure(
    page_state: dict[str, Any],
    *,
    elapsed_seconds: float,
    silent_seconds: float,
    ready_seconds: float,
    stall_seconds: float,
    active_limit_seconds: float | None = None,
) -> str:
    explicit_error = clean_text(str(page_state.get("error") or ""))
    if explicit_error:
        return f"{explicit_error}，本张已停止等待。"
    if page_state.get("active"):
        if active_limit_seconds and elapsed_seconds >= active_limit_seconds:
            return (
                f"ChatGPT 连续生成 {int(active_limit_seconds)} 秒仍没有返回图片，当前账号已判定为本张停滞。"
                "系统将冷却该账号并自动轮换下一个账号。"
            )
        if silent_seconds >= stall_seconds:
            return (
                f"ChatGPT 虽仍显示生成中，但页面连续 {int(stall_seconds)} 秒没有任何变化，本张已判定为停滞并停止等待。"
                "请在弹出的窗口确认账号状态后再续跑。"
            )
        return ""
    # When the composer is ready again, ChatGPT has finished handling the
    # request. If no assistant image appeared, waiting for the full image
    # timeout only hides quota/mode failures behind a misleading spinner.
    if elapsed_seconds >= 60.0 and ready_seconds >= min(90.0, stall_seconds):
        return (
            "ChatGPT 回复已经结束，但没有出现新图片，可能只回复了文字或没有进入“生成图片”模式。"
            "本张已自动停止，避免继续空等。"
        )
    if silent_seconds >= stall_seconds:
        return (
            f"ChatGPT 页面连续 {int(stall_seconds)} 秒没有生图进展，本张已自动停止。"
            "请查看弹出的窗口是否出现登录失效、套餐限制或文字回复后再续跑。"
        )
    return ""


def _save_latest_chatgpt_image(
    page: Any,
    before_indexes: set[Any],
    output_path: Path,
    timeout_seconds: float,
    stall_seconds: float = 240.0,
    active_limit_seconds: float | None = None,
    log: Callable[[str], None] | None = None,
    abort_event: threading.Event | None = None,
) -> Path:
    started_at = time.monotonic()
    deadline = started_at + timeout_seconds
    candidate: dict[str, Any] | None = None
    next_progress_at = 0.0
    last_error = ""
    last_signature = ""
    last_signal_at = started_at
    ready_since = 0.0
    was_active = False
    while time.monotonic() < deadline:
        if abort_event is not None and abort_event.is_set():
            raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。")
        try:
            images = page.evaluate(_large_chatgpt_images_script())
        except Exception as exc:
            if abort_event is not None and abort_event.is_set():
                raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。") from exc
            last_error = str(exc)
            raise RuntimeError(
                "ChatGPT 浏览器连接中断：请确认弹出的 Chrome 窗口没有被关闭，账号没有跳到重新登录页。"
                + (f" 最近错误：{last_error}" if last_error else "")
            ) from exc
        if isinstance(images, list):
            before_uses_fingerprints = bool(before_indexes) and all(isinstance(item, str) for item in before_indexes)
            new_images = [
                item
                for item in images
                if isinstance(item, dict)
                and bool(item.get("in_main", True))
                and (
                    clean_text(
                        str(
                            item.get("key")
                            or f"{item.get('src', '')}|{item.get('width', 0)}x{item.get('height', 0)}"
                        )
                    )
                    not in before_indexes
                    if before_uses_fingerprints
                    else int(item.get("index", -1)) not in before_indexes
                )
            ]
            if new_images:
                assistant_images = [item for item in new_images if item.get("assistant")]
                generated_images = [item for item in new_images if item.get("generated")]
                eligible = assistant_images or generated_images
                if eligible:
                    # `data-turn="assistant"` is the current ChatGPT marker,
                    # while older layouts used `data-message-author-role`.
                    # The imagegen marker is a guarded fallback for the next DOM
                    # change; stable src fingerprints still exclude old images.
                    candidate = max(
                        eligible,
                        key=lambda item: (int(item.get("turn_index", -1) or -1), int(item.get("index", -1) or -1)),
                    )
                    break
        now = time.monotonic()
        page_state = _chatgpt_generation_page_state(page)
        signature = clean_text(str(page_state.get("signature") or ""))
        if signature and signature != last_signature:
            last_signature = signature
            last_signal_at = now
        is_active = bool(page_state.get("active"))
        if is_active != was_active:
            last_signal_at = now
            was_active = is_active
        if is_active:
            ready_since = 0.0
        elif page_state.get("send_ready"):
            ready_since = ready_since or now
        else:
            ready_since = 0.0
        elapsed = max(0.0, now - started_at)
        silent_for = max(0.0, now - last_signal_at)
        ready_for = max(0.0, now - ready_since) if ready_since else 0.0
        failure = chatgpt_image_wait_failure(
            page_state,
            elapsed_seconds=elapsed,
            silent_seconds=silent_for,
            ready_seconds=ready_for,
            stall_seconds=stall_seconds,
            active_limit_seconds=active_limit_seconds,
        )
        if failure:
            raise RuntimeError(failure)
        if log and time.monotonic() >= next_progress_at:
            elapsed_int = max(0, int(elapsed))
            if page_state.get("active"):
                message = f"ChatGPT 正在生成图片，已等待 {elapsed_int} 秒；页面生成状态正常"
            elif page_state.get("send_ready"):
                message = f"ChatGPT 已回到可输入状态但尚未检测到图片，已等待 {elapsed_int} 秒；正在确认是否只回复了文字"
            else:
                message = f"ChatGPT 尚未返回图片，已等待 {elapsed_int} 秒；最近页面变化在 {int(silent_for)} 秒前"
            log(f"[images] {message}")
            next_progress_at = time.monotonic() + 10.0
        page.wait_for_timeout(2500)
    if not candidate:
        raise RuntimeError("ChatGPT 已发送提示词，但没有检测到新生成图片。请确认账号具备生图能力后重试。")

    src = str(candidate.get("src") or "")
    index = int(candidate.get("index", -1))
    if src:
        try:
            payload = page.evaluate(_fetch_image_b64_script(), src)
            if isinstance(payload, dict) and payload.get("b64"):
                _write_image_bytes_as_png(base64.b64decode(str(payload["b64"])), output_path)
                return output_path
        except Exception:
            pass

    if index >= 0:
        image_locator = page.locator("img").nth(index)
        image_locator.screenshot(path=str(output_path), timeout=30000)
        return output_path
    raise RuntimeError("检测到 ChatGPT 图片，但无法下载或截图保存。")


def _goto_chatgpt_with_retry(
    page: Any,
    url: str,
    *,
    log: Callable[[str], None] | None = None,
    attempts: int = 4,
) -> Any:
    last_error: Exception | None = None
    current_page = page
    for attempt in range(1, max(1, attempts) + 1):
        try:
            if current_page.is_closed():
                current_page = current_page.context.new_page()
            current_page.goto(url, wait_until="domcontentloaded", timeout=60000)
            return current_page
        except Exception as exc:
            last_error = exc
            if attempt >= attempts:
                break
            delay = min(10, attempt * 2)
            if log:
                log(
                    f"[images] ChatGPT 页面连接中断，{delay} 秒后自动重连 "
                    f"({attempt + 1}/{attempts})：{user_facing_error(exc)}"
                )
            with contextlib.suppress(Exception):
                if current_page.is_closed():
                    current_page = current_page.context.new_page()
                else:
                    current_page.goto("about:blank", wait_until="commit", timeout=5000)
            time.sleep(delay)
    raise RuntimeError(f"ChatGPT 页面连续 {attempts} 次连接失败：{user_facing_error(last_error or 'unknown error')}")


def _reuse_chatgpt_automation_page(
    context: Any,
    chatgpt_url: str,
    log: Callable[[str], None] | None = None,
) -> Any:
    """Reuse Chrome's launch tab instead of opening a second ChatGPT tab."""
    try:
        pages = [page for page in list(context.pages or []) if page.is_closed() is not True]
    except (AttributeError, RuntimeError):
        pages = []
    if not pages:
        return context.new_page()

    expected_host = urllib.parse.urlsplit(chatgpt_url).netloc.lower() or "chatgpt.com"

    def page_url(page: Any) -> str:
        with contextlib.suppress(Exception):
            return clean_text(str(page.url or ""))
        return ""

    target = next(
        (
            page
            for page in pages
            if expected_host in urllib.parse.urlsplit(page_url(page)).netloc.lower()
            or "chatgpt.com" in urllib.parse.urlsplit(page_url(page)).netloc.lower()
        ),
        None,
    )
    if target is None:
        target = next(
            (page for page in pages if page_url(page).lower() in {"", "about:blank", "chrome://newtab/"}),
            pages[0],
        )

    closed_duplicates = 0
    for extra in pages:
        if extra is target:
            continue
        extra_url = page_url(extra).lower()
        extra_host = urllib.parse.urlsplit(extra_url).netloc.lower()
        if extra_url in {"", "about:blank", "chrome://newtab/"} or "chatgpt.com" in extra_host:
            with contextlib.suppress(Exception):
                extra.close()
                closed_duplicates += 1
    if log:
        if closed_duplicates:
            log(f"[images] 已复用现有 ChatGPT 标签并关闭 {closed_duplicates} 个重复标签")
        else:
            log("[images] 已复用 Chrome 启动时的 ChatGPT 标签，不再新开第二个标签")
    return target


def _open_fresh_chatgpt_image_chat(page: Any, chatgpt_url: str, log: Callable[[str], None] | None = None) -> Any:
    parsed = urllib.parse.urlsplit(chatgpt_url)
    base_url = urllib.parse.urlunsplit((parsed.scheme or "https", parsed.netloc or "chatgpt.com", "/", "", ""))
    page = _goto_chatgpt_with_retry(page, base_url, log=log)
    page.wait_for_timeout(1800)
    current_path = urllib.parse.urlsplit(clean_text(str(page.url or ""))).path
    if current_path.startswith("/c/"):
        new_chat_pattern = re.compile(r"新聊天|新对话|New chat", re.IGNORECASE)
        candidates = [
            page.locator("a[data-testid='create-new-chat-button']"),
            page.get_by_role("link", name=new_chat_pattern),
            page.get_by_role("button", name=new_chat_pattern),
            page.locator("a[href='/']").first,
        ]
        clicked = False
        for candidate in candidates:
            try:
                if candidate.count() and candidate.is_visible(timeout=500):
                    candidate.click(timeout=4000)
                    clicked = True
                    break
            except Exception:
                continue
        if not clicked:
            page = _goto_chatgpt_with_retry(page, base_url, log=log)
        page.wait_for_timeout(1500)
    if urllib.parse.urlsplit(clean_text(str(page.url or ""))).path.startswith("/c/"):
        raise RuntimeError("ChatGPT 没有切换到独立新对话，已停止生图，避免上一镜内容污染当前图片。")
    if log:
        log("[images] 已进入独立新对话，本镜不会继承上一张图片的内容")
    return page


def chatgpt_delete_after_save_enabled(env: dict[str, str]) -> bool:
    value = clean_text(env.get("CHATGPT_IMAGE_DELETE_AFTER_SAVE") or "")
    return True if not value else env_flag(value)


def _click_chatgpt_text_action(page: Any, labels: list[str], timeout_ms: int = 2500) -> str:
    pattern = re.compile("|".join(re.escape(label) for label in labels), re.IGNORECASE)
    locators = []
    for role in ("menuitem", "button"):
        locators.append(page.get_by_role(role, name=pattern).last)
    for label in labels:
        locators.extend(
            [
                page.locator(f"button:has-text('{label}')").last,
                page.locator(f"[role='menuitem']:has-text('{label}')").last,
                page.locator(f"text={label}").last,
            ]
        )
    for locator in locators:
        try:
            if locator.count() and locator.is_visible(timeout=400):
                text = clean_text(locator.inner_text(timeout=600))
                locator.click(timeout=timeout_ms)
                return text or labels[0]
        except Exception:
            continue
    raise RuntimeError(f"没有找到可点击的按钮：{'/'.join(labels)}")


def _open_chatgpt_current_conversation_menu(page: Any) -> str:
    result = page.evaluate(
        """
() => {
  const isVisible = (el) => {
    if (!el) return false;
    const rect = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none";
  };
  const buttonText = (button) => [
    button.innerText || "",
    button.getAttribute("aria-label") || "",
    button.getAttribute("title") || "",
    button.dataset?.testid || ""
  ].join(" ").trim();
  const clickMenuButtonNear = (root) => {
    let node = root;
    for (let depth = 0; node && depth < 8; depth += 1, node = node.parentElement) {
      const buttons = Array.from(node.querySelectorAll("button")).filter((button) => {
        if (!isVisible(button) || button.disabled) return false;
        const text = buttonText(button).toLowerCase();
        return text.includes("more")
          || text.includes("options")
          || text.includes("menu")
          || text.includes("conversation")
          || text.includes("更多")
          || text.includes("选项")
          || text.includes("操作")
          || text.includes("菜单")
          || text.includes("对话");
      });
      const allButtons = Array.from(node.querySelectorAll("button")).filter((button) => isVisible(button) && !button.disabled);
      const target = buttons[buttons.length - 1] || allButtons[allButtons.length - 1];
      if (target) {
        target.scrollIntoView({ block: "center", inline: "nearest" });
        target.click();
        return { ok: true, text: buttonText(target) };
      }
    }
    return { ok: false, reason: "nearby menu button not found" };
  };
  const pathMatch = location.pathname.match(/\\/c\\/([^/?#]+)/);
  const currentId = pathMatch ? pathMatch[1] : "";
  const candidates = [];
  if (currentId && window.CSS && CSS.escape) {
    candidates.push(...document.querySelectorAll(`a[href*="/c/${CSS.escape(currentId)}"]`));
  }
  candidates.push(...document.querySelectorAll('nav a[aria-current="page"][href*="/c/"], aside a[aria-current="page"][href*="/c/"]'));
  for (const selected of document.querySelectorAll('nav [aria-selected="true"], aside [aria-selected="true"], nav [data-active="true"], aside [data-active="true"]')) {
    candidates.push(...selected.querySelectorAll('a[href*="/c/"]'));
  }
  for (const link of candidates) {
    if (!isVisible(link)) continue;
    const clicked = clickMenuButtonNear(link);
    if (clicked.ok) return clicked;
  }
  return { ok: false, reason: currentId ? `conversation ${currentId} not found in sidebar` : "current chat has no /c/ id yet" };
}
"""
    )
    if isinstance(result, dict) and result.get("ok"):
        return clean_text(str(result.get("text") or ""))
    reason = ""
    if isinstance(result, dict):
        reason = clean_text(str(result.get("reason") or ""))
    raise RuntimeError(reason or "没有打开当前会话菜单")


def _confirm_chatgpt_conversation_delete(page: Any) -> bool:
    pattern = re.compile("删除|Delete", re.IGNORECASE)
    containers = [
        page.get_by_role("dialog").last,
        page.get_by_role("alertdialog").last,
        page.locator("[role='dialog']").last,
        page.locator("[role='alertdialog']").last,
    ]
    for container in containers:
        try:
            if not container.count() or not container.is_visible(timeout=500):
                continue
            actions = [
                container.get_by_role("button", name=pattern).last,
                container.locator("button:has-text('删除')").last,
                container.locator("button:has-text('Delete')").last,
            ]
            for action in actions:
                try:
                    if action.count() and action.is_visible(timeout=400) and action.is_enabled(timeout=400):
                        action.click(timeout=3000)
                        return True
                except (AttributeError, RuntimeError):
                    continue
        except (AttributeError, RuntimeError):
            continue
    return False


def cleanup_chatgpt_conversation_after_save(page: Any, env: dict[str, str], log: Callable[[str], None] | None = None) -> None:
    if not chatgpt_delete_after_save_enabled(env):
        return
    try:
        page.wait_for_timeout(800)
        _open_chatgpt_current_conversation_menu(page)
        page.wait_for_timeout(500)
        _click_chatgpt_text_action(page, ["删除", "Delete"])
        page.wait_for_timeout(700)
        if not _confirm_chatgpt_conversation_delete(page):
            with contextlib.suppress(Exception):
                page.keyboard.press("Enter")
        page.wait_for_timeout(1200)
        if log:
            log("[images] 已删除本次 ChatGPT 生图会话，避免左侧历史列表堆积")
    except Exception as exc:
        if log:
            log(f"[images] ChatGPT 会话自动删除未完成：{exc}；图片已保存，不影响后续流程")


def close_chatgpt_browser_context(context: Any, log: Callable[[str], None] | None = None) -> None:
    closed = False
    try:
        for page in list(getattr(context, "pages", []) or []):
            with contextlib.suppress(Exception):
                page.close()
                closed = True
    except (AttributeError, RuntimeError):
        pass
    try:
        context.close()
        closed = True
    except Exception as exc:
        if log:
            log(f"[images] ChatGPT 浏览器关闭时返回了非致命错误：{user_facing_error(exc)}")
    if log and closed:
        log("[images] 已关闭本次 ChatGPT 生图窗口")


def _activate_chatgpt_image_mode(page: Any, log: Callable[[str], None] | None = None) -> bool:
    image_mode_pattern = re.compile(r"^(?:生成图片|创建图片|Create image|Create images)$", re.IGNORECASE)

    def click_visible(locator: Any) -> bool:
        try:
            count = min(int(locator.count()), 6)
        except (AttributeError, RuntimeError):
            return False
        for index in range(count):
            try:
                item = locator.nth(index)
                if item.is_visible(timeout=500) and item.is_enabled(timeout=500):
                    item.click(timeout=4000)
                    page.wait_for_timeout(600)
                    return True
            except (AttributeError, RuntimeError):
                continue
        return False

    direct_candidates = [
        page.get_by_role("button", name=image_mode_pattern),
        page.locator("button").filter(has_text=image_mode_pattern),
        page.locator("[role='button']").filter(has_text=image_mode_pattern),
    ]
    for candidate in direct_candidates:
        if click_visible(candidate):
            if log:
                log("[images] 已先选择 ChatGPT「生成图片」模式，再输入提示词")
            return True

    plus_candidates = [
        page.locator("button[data-testid='composer-plus-btn']"),
        page.locator("button[aria-label*='添加']"),
        page.locator("button[aria-label*='Add']"),
    ]
    for plus in plus_candidates:
        if not click_visible(plus):
            continue
        menu_candidates = [
            page.get_by_role("menuitem", name=image_mode_pattern),
            page.get_by_role("button", name=image_mode_pattern),
        ]
        for candidate in menu_candidates:
            if click_visible(candidate):
                if log:
                    log("[images] 已从工具菜单选择 ChatGPT「生成图片」模式，再输入提示词")
                return True

    if log:
        log("[images] 当前页面没有找到“生成图片”按钮，将使用强制生图指令继续")
    return False


def _generate_chatgpt_web_auto_image_for_account(
    playwright: Any,
    account: dict[str, Any],
    clean_prompt: str,
    output_path: Path,
    chatgpt_url: str,
    timeout_seconds: float,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    reference_images: list[Path] | None = None,
    abort_event: threading.Event | None = None,
) -> Path:
    page: Any = None
    browser: Any = None
    completed = False
    browser_cleanup_done = False
    try:
        if abort_event is not None and abort_event.is_set():
            raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。")
        ensure_chatgpt_cdp_browser(account, env, url=chatgpt_url, log=log, abort_event=abort_event)
        if log:
            if account.get("provider") == "ant_browser":
                log(
                    f"[images] Ant Browser 轮询 -> {account['label']}，"
                    f"快捷码 {account.get('code')}，CDP {account.get('cdp_url')}"
                )
            else:
                log(
                    f"[images] 账号轮询 -> {account['label']}，"
                    f"复用本地端口 {account['port']}，profile={account['profile_dir']}"
                )
            if account.get("provider") == "ant_browser":
                log("[images] 登录资料、指纹与代理均由 Ant Browser 实例保管，本工具仅接管当前生图页面")
            elif env_flag(env.get("CHATGPT_IMAGE_HEADLESS")):
                log("[images] 生图 Chrome 通过本地 CDP 端口在后台运行，不会自动弹出登录窗口")
            elif env_flag(env.get("CHATGPT_IMAGE_CLOSE_BROWSER_AFTER_SAVE", "true")):
                log("[images] 使用可见 Chrome 生图；图片保存后会自动关闭浏览器")
            else:
                log("[images] 浏览器会话保持常驻；本张只新建独立标签页，不再重复启动 Chrome")
        browser = playwright.chromium.connect_over_cdp(account["cdp_url"], timeout=60000)
        if abort_event is not None and abort_event.is_set():
            raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。")
        if not browser.contexts:
            raise RuntimeError(f"{account['label']} 的浏览器端口没有可用上下文。")
        context = browser.contexts[0]
        page = _reuse_chatgpt_automation_page(context, chatgpt_url, log=log)
        page = _open_fresh_chatgpt_image_chat(page, chatgpt_url, log=log)
        if env_flag(env.get("CHATGPT_IMAGE_HEADLESS")):
            _raise_chatgpt_access_challenge(page)
        else:
            _wait_for_visible_chatgpt_challenge(page, timeout_seconds=min(timeout_seconds, 300.0), log=log)
        _activate_chatgpt_image_mode(page, log=log)
        _attach_chatgpt_reference_images(page, list(reference_images or []), log=log)
        before_images = page.evaluate(_large_chatgpt_images_script())
        before_indexes = chatgpt_image_snapshot_keys(before_images)
        _fill_chatgpt_composer(
            page,
            clean_prompt,
            env=env,
            log=log,
            timeout_seconds=min(chatgpt_image_wait_seconds(env), 300.0),
            account_id=account["id"],
        )
        _click_chatgpt_send(page)
        if log:
            log("[images] ChatGPT 提示词已发送，正在等待生成图片")
        result = _save_latest_chatgpt_image(
            page,
            before_indexes,
            output_path,
            timeout_seconds,
            stall_seconds=chatgpt_image_stall_seconds(env),
            active_limit_seconds=chatgpt_image_active_limit_seconds(env),
            log=log,
            abort_event=abort_event,
        )
        if log:
            log(f"[images] ChatGPT 网页自动化已保存 {output_path.name}")
        cleanup_chatgpt_conversation_after_save(page, env, log=log)
        if browser is not None and env_flag(env.get("CHATGPT_IMAGE_CLOSE_BROWSER_AFTER_SAVE", "true")):
            close_connected_chatgpt_browser(browser, account, log=log)
            browser = None
            browser_cleanup_done = True
        completed = True
        return result
    except ChatgptAccessChallengeError:
        # A browser started in legacy true-headless mode will keep returning the
        # challenge page. Close it so the next run restarts in background CDP mode.
        if browser is not None and env_flag(env.get("CHATGPT_IMAGE_HEADLESS")):
            close_connected_chatgpt_browser(browser, account, timeout_seconds=8.0, log=log)
            browser = None
            browser_cleanup_done = True
        raise
    finally:
        if page is not None:
            with contextlib.suppress(Exception):
                page.close()
        if not completed and not browser_cleanup_done:
            if browser is not None:
                with contextlib.suppress(Exception):
                    close_connected_chatgpt_browser(
                        browser,
                        account,
                        timeout_seconds=8.0,
                        log=log,
                        image_saved=False,
                    )
            else:
                # The browser may have started successfully even when the CDP
                # connection or page setup failed. Close it by account port so
                # the next retry starts from a clean process.
                with contextlib.suppress(Exception):
                    closed = close_chatgpt_cdp_browser(account, timeout_seconds=8.0)
                    if log and closed:
                        log(f"[images] {account['label']} 本次生图已结束，Chrome 已确认关闭")


def _run_chatgpt_web_auto_image_account_pool(
    playwright_factory: Callable[[], Any],
    clean_prompt: str,
    output_path: Path,
    chatgpt_url: str,
    timeout_seconds: float,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    reference_images: list[Path] | None = None,
) -> Path:
    try:
        attempt_limit = max(1, len(chatgpt_image_accounts(env)))
    except Exception as exc:
        raise RuntimeError(user_facing_error(exc)) from exc
    account_errors: list[str] = []

    with playwright_factory() as playwright:
        for attempt_index in range(attempt_limit):
            try:
                account, account_lock = acquire_chatgpt_image_account(env)
            except Exception as exc:
                account_errors.append(user_facing_error(exc))
                break
            abort_event = chatgpt_account_abort_event(account, account_lock)
            try:
                result = _generate_chatgpt_web_auto_image_for_account(
                    playwright,
                    account,
                    clean_prompt,
                    output_path,
                    chatgpt_url,
                    timeout_seconds,
                    env,
                    log=log,
                    reference_images=reference_images,
                    abort_event=abort_event,
                )
                record_chatgpt_account_result(account, env=env)
                return result
            except Exception as exc:
                if abort_event.is_set() or isinstance(exc, ChatgptGenerationCancelledError):
                    raise ChatgptGenerationCancelledError("ChatGPT 生图任务已取消。") from exc
                if isinstance(exc, ChatgptAccessChallengeError) and env_flag(env.get("CHATGPT_IMAGE_HEADLESS")):
                    visible_env = dict(env)
                    visible_env["CHATGPT_IMAGE_HEADLESS"] = "false"
                    if log:
                        log(f"[images] {account['label']} 后台页面触发验证，正在自动改用有界面的 Chrome 重试")
                    try:
                        result = _generate_chatgpt_web_auto_image_for_account(
                            playwright,
                            account,
                            clean_prompt,
                            output_path,
                            chatgpt_url,
                            timeout_seconds,
                            visible_env,
                            log=log,
                            reference_images=reference_images,
                            abort_event=abort_event,
                        )
                        record_chatgpt_account_result(account, env=env)
                        return result
                    except Exception as visible_exc:
                        exc = visible_exc
                account_error = user_facing_error(exc)
                record_chatgpt_account_result(account, error=account_error, env=env)
                account_errors.append(f"{account['label']}：{account_error}")
                if log:
                    remaining = attempt_limit - attempt_index - 1
                    if remaining > 0:
                        log(f"[images] {account['label']} 本张失败并进入冷却，自动切换下一账号：{account_error}")
                    else:
                        log(f"[images] {account['label']} 本张失败并进入冷却：{account_error}")
            finally:
                release_chatgpt_image_account(account, account_lock)

    details = "；".join(account_errors[-attempt_limit:])
    raise RuntimeError(
        "所有 ChatGPT 生图账号均不可用，本张图片未生成。"
        "程序已停止空等；请在账号管理中处理显示为“需要验证”或“需登录”的账号后继续。"
        + (f" 详情：{details}" if details else "")
    )


def generate_chatgpt_web_auto_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    reference_images: list[Path] | None = None,
) -> Path:
    try:
        from playwright.sync_api import sync_playwright
    except Exception as exc:
        raise RuntimeError("ChatGPT 网页自动化需要 playwright，请先运行 pip install playwright。") from exc

    clean_prompt = build_chatgpt_handoff_prompt(prompt, size, purpose)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")
    chatgpt_url = clean_text(env.get("CHATGPT_IMAGE_WEB_URL") or "https://chatgpt.com/") or "https://chatgpt.com/"
    return _run_chatgpt_web_auto_image_account_pool(
        sync_playwright,
        clean_prompt,
        output_path,
        chatgpt_url,
        chatgpt_image_wait_seconds(env),
        env,
        log=log,
        reference_images=reference_images,
    )


def default_imageai_playground_profile_dir() -> Path:
    return storage.CONFIG_ROOT / "imageai-playground-profile"


def imageai_playground_user_data_dir(env: dict[str, str]) -> Path:
    configured = clean_text(env.get("IMAGEAI_PLAYGROUND_USER_DATA_DIR") or "")
    if configured:
        return Path(configured)
    return default_imageai_playground_profile_dir()


def build_imageai_playground_prompt(prompt: str, size: str, purpose: str) -> str:
    del size
    return sanitize_prompt_for_image_model(prompt, purpose)


def imageai_playground_launch_url(env: dict[str, str]) -> str:
    app_url = clean_text(env.get("IMAGEAI_PLAYGROUND_URL") or "https://imageai.centos.hk/") or "https://imageai.centos.hk/"
    parsed = urllib.parse.urlsplit(app_url)
    if parsed.netloc:
        scheme = parsed.scheme or "https"
        netloc = parsed.netloc
        path = parsed.path or "/"
    else:
        scheme = "https"
        netloc = parsed.path.rstrip("/")
        path = "/"
    query = dict(urllib.parse.parse_qsl(parsed.query, keep_blank_values=True))
    if not env_flag(env.get("IMAGEAI_PLAYGROUND_USE_SAVED_SETTINGS", "true")):
        api_key = (env.get("THIRD_PARTY_IMAGE_API_KEY", "") or "").strip()
        base_url = normalize_openai_compatible_base_url(env.get("THIRD_PARTY_IMAGE_BASE_URL", "") or "https://ai.centos.hk/v1")
        if not api_key:
            raise RuntimeError("GPT Image Playground 配置注入模式需要先填写 THIRD_PARTY_IMAGE_API_KEY。")
        if not base_url:
            raise RuntimeError("GPT Image Playground 配置注入模式需要先填写 THIRD_PARTY_IMAGE_BASE_URL。")
        query.update({"apiUrl": base_url, "apiKey": api_key, "apiMode": "images"})
    return urllib.parse.urlunsplit((scheme, netloc, path, urllib.parse.urlencode(query), parsed.fragment))


def _fill_imageai_playground_prompt(page: Any, prompt: str, timeout_seconds: float = 120.0) -> None:
    selectors = [
        "textarea[placeholder*='描述']",
        "textarea[placeholder*='提示']",
        "textarea",
        "input[placeholder*='描述']",
        "input[placeholder*='提示']",
    ]
    deadline = time.monotonic() + timeout_seconds
    last_error = ""
    while time.monotonic() < deadline:
        for selector in selectors:
            locator = page.locator(selector).last
            try:
                if locator.count() and locator.is_visible(timeout=600) and locator.is_enabled(timeout=600):
                    locator.evaluate(
                        """
(el, text) => {
  el.scrollIntoView({ block: "center", inline: "nearest" });
  el.focus();
  const proto = el.tagName === "TEXTAREA" ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
  const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
  if (setter) setter.call(el, text);
  else el.value = text;
  el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: text }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
}
""",
                        prompt,
                    )
                    return
            except Exception as exc:
                last_error = str(exc)
        page.wait_for_timeout(1000)
    raise RuntimeError("GPT Image Playground 没有找到可编辑的提示词输入框。" + (f" 最近错误：{last_error}" if last_error else ""))


def _click_imageai_playground_generate(page: Any) -> None:
    result = page.evaluate(
        """
() => {
  const isVisible = (el) => {
    if (!el) return false;
    const rect = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none";
  };
  const textOf = (el) => [
    el.innerText || "",
    el.getAttribute("aria-label") || "",
    el.getAttribute("title") || "",
    el.getAttribute("data-testid") || ""
  ].join(" ").trim();
  const prompt = Array.from(document.querySelectorAll("textarea, input")).reverse().find((el) => {
    if (!isVisible(el) || el.disabled) return false;
    const ph = el.getAttribute("placeholder") || "";
    return ph.includes("描述") || ph.includes("提示") || (el.value && el.value.length > 20);
  });
  if (!prompt) return { ok: false, reason: "prompt input not found" };
  let node = prompt;
  for (let depth = 0; node && depth < 8; depth += 1, node = node.parentElement) {
    const buttons = Array.from(node.querySelectorAll("button")).filter((button) => isVisible(button) && !button.disabled);
    if (!buttons.length) continue;
    const preferred = buttons.find((button) => /生成|发送|提交|generate|send|submit/i.test(textOf(button))) || buttons[buttons.length - 1];
    preferred.scrollIntoView({ block: "center", inline: "nearest" });
    preferred.click();
    return { ok: true, text: textOf(preferred) };
  }
  return { ok: false, reason: "generate button not found near prompt input" };
}
"""
    )
    if isinstance(result, dict) and result.get("ok"):
        return
    reason = clean_text(str(result.get("reason") if isinstance(result, dict) else result))
    raise RuntimeError(f"GPT Image Playground 没有找到生成按钮：{reason or 'unknown'}")


def _save_latest_imageai_playground_image(
    page: Any,
    before_indexes: set[int],
    output_path: Path,
    timeout_seconds: float,
    log: Callable[[str], None] | None = None,
) -> Path:
    deadline = time.monotonic() + timeout_seconds
    candidate: dict[str, Any] | None = None
    next_progress_at = 0.0
    last_error_text = ""
    while time.monotonic() < deadline:
        try:
            images = page.evaluate(_large_chatgpt_images_script())
        except Exception as exc:
            raise RuntimeError(f"GPT Image Playground 浏览器连接中断：{exc}") from exc
        if isinstance(images, list):
            new_images = [
                item
                for item in images
                if isinstance(item, dict) and int(item.get("index", -1)) not in before_indexes
            ]
            if new_images:
                candidate = new_images[-1]
                break
            if images:
                candidate = images[-1]
        if log and time.monotonic() >= next_progress_at:
            remaining = max(0, int(deadline - time.monotonic()))
            log(f"[images] GPT Image Playground 图片生成等待中，剩余约 {remaining}s")
            next_progress_at = time.monotonic() + 20.0
        with contextlib.suppress(Exception):
            body_text = clean_text(page.locator("body").inner_text(timeout=800))
            error_markers = ("失败", "错误", "error", "invalid", "unauthorized", "forbidden", "余额", "quota", "429")
            if any(marker in body_text.lower() for marker in error_markers):
                last_error_text = body_text[-500:]
        page.wait_for_timeout(2500)
    if not candidate:
        suffix = f" 页面提示：{last_error_text}" if last_error_text else ""
        raise RuntimeError("GPT Image Playground 已点击生成，但没有检测到生成图片。" + suffix)

    src = str(candidate.get("src") or "")
    index = int(candidate.get("index", -1))
    if src:
        try:
            payload = page.evaluate(_fetch_image_b64_script(), src)
            if isinstance(payload, dict) and payload.get("b64"):
                _write_image_bytes_as_png(base64.b64decode(str(payload["b64"])), output_path)
                return output_path
        except Exception:
            pass
    if index >= 0:
        page.locator("img").nth(index).screenshot(path=str(output_path), timeout=30000)
        return output_path
    raise RuntimeError("检测到 GPT Image Playground 图片，但无法下载或截图保存。")


def cleanup_imageai_playground_history(page: Any, env: dict[str, str], log: Callable[[str], None] | None = None) -> None:
    if not env_flag(env.get("IMAGEAI_PLAYGROUND_DELETE_AFTER_SAVE", "true")):
        return
    try:
        page.evaluate(
            """
async () => {
  const deleteDb = (name) => new Promise((resolve) => {
    const request = indexedDB.deleteDatabase(name);
    request.onsuccess = () => resolve(true);
    request.onerror = () => resolve(false);
    request.onblocked = () => resolve(false);
  });
  const names = ["gpt-image-playground"];
  if (indexedDB.databases) {
    try {
      const databases = await indexedDB.databases();
      for (const db of databases || []) {
        if (db && db.name && db.name.includes("gpt-image-playground")) names.push(db.name);
      }
    } catch (_) {}
  }
  for (const name of Array.from(new Set(names))) {
    await deleteDb(name);
  }
}
"""
        )
        if log:
            log("[images] 已清理 GPT Image Playground 本地任务/图片历史，保留网站设置")
    except Exception as exc:
        if log:
            log(f"[images] GPT Image Playground 历史清理未完成：{exc}；图片已保存，不影响后续流程")


def generate_imageai_playground_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    reference_images: list[Path] | None = None,
) -> Path:
    try:
        from playwright.sync_api import sync_playwright
    except Exception as exc:
        raise RuntimeError("GPT Image Playground 网页自动化需要 playwright，请先运行 pip install playwright。") from exc

    clean_prompt = build_imageai_playground_prompt(prompt, size, purpose)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")

    browser_path = resolve_chatgpt_browser_path(env)
    profile_dir = storage.ensure_dir(imageai_playground_user_data_dir(env))
    launch_url = imageai_playground_launch_url(env)
    timeout_seconds = imageai_playground_wait_seconds(env)
    if log:
        log(f"[images] GPT Image Playground 打开浏览器 profile={profile_dir}")
        if env_flag(env.get("IMAGEAI_PLAYGROUND_USE_SAVED_SETTINGS", "true")):
            log("[images] 使用 imageai.centos.hk 网站已保存的密钥和模型配置；本次只输入提示词并抓回图片")
        else:
            log("[images] 已自动注入第三方 Base URL/API Key 到 imageai.centos.hk，生成完成后会抓回项目目录")

    with sync_playwright() as playwright:
        launch_kwargs: dict[str, Any] = {
            "headless": env_flag(env.get("IMAGEAI_PLAYGROUND_HEADLESS")),
            "accept_downloads": True,
            "viewport": {"width": 1440, "height": 1100},
            "locale": "zh-CN",
            "args": ["--disable-blink-features=AutomationControlled"],
        }
        if browser_path:
            launch_kwargs["executable_path"] = browser_path
        context = playwright.chromium.launch_persistent_context(str(profile_dir), **launch_kwargs)
        try:
            page = context.pages[0] if context.pages else context.new_page()
            page.goto(launch_url, wait_until="domcontentloaded", timeout=60000)
            page.wait_for_timeout(2500)
            before_images = page.evaluate(_large_chatgpt_images_script())
            before_indexes = {
                int(item.get("index", -1))
                for item in before_images
                if isinstance(item, dict) and int(item.get("index", -1)) >= 0
            } if isinstance(before_images, list) else set()
            references = [path.resolve() for path in list(reference_images or []) if path.exists()][:6]
            if references:
                file_inputs = page.locator("input[type='file']")
                if not file_inputs.count():
                    raise RuntimeError(
                        "GPT Image Playground 当前页面没有商品参考图上传入口。"
                        "请改用火山方舟 Seedream 或 ChatGPT 网页自动化后重试。"
                    )
                file_inputs.last.set_input_files([str(path) for path in references], timeout=30000)
                page.wait_for_timeout(1200)
                if log:
                    log(f"[images] GPT Image Playground 已上传 {len(references)} 张商品参考图")
            _fill_imageai_playground_prompt(page, clean_prompt, timeout_seconds=min(timeout_seconds, 240.0))
            _click_imageai_playground_generate(page)
            if log:
                log("[images] GPT Image Playground 提示词已提交，正在等待图片")
            result = _save_latest_imageai_playground_image(page, before_indexes, output_path, timeout_seconds, log=log)
            if log:
                log(f"[images] GPT Image Playground 已保存 {output_path.name}")
            cleanup_imageai_playground_history(page, env, log=log)
            return result
        finally:
            with contextlib.suppress(Exception):
                context.close()
            if log:
                log("[images] 已关闭本次 GPT Image Playground 窗口")


def prepare_chatgpt_handoff_request(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    template: dict[str, Any] | None = None,
    provider_key: str = "chatgpt_handoff",
) -> dict[str, Any]:
    prepared_prompt = normalize_image_prompt(prompt)
    handoff_prompt = build_chatgpt_handoff_prompt(prepared_prompt, size, purpose)
    open_target = resolve_chatgpt_handoff_target(env, provider_key)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    storage.write_text(output_path.with_suffix(".md"), prepared_prompt + "\n")
    page_path = write_chatgpt_handoff_page(handoff_prompt, output_path, size, purpose, env, open_target=open_target)
    clipboard_copied = open_chatgpt_handoff(page_path, env, handoff_prompt, open_target=open_target)
    return {
        "needs_handoff": True,
        "page_path": str(page_path),
        "output_path": str(output_path.resolve()),
        "prompt": prepared_prompt,
        "open_target": open_target,
        "clipboard_copied": clipboard_copied,
        "prompt_path": str(chatgpt_handoff_dir(output_path) / f"{output_path.stem}.prompt.txt"),
    }


def apiyi_image_available(env: dict[str, str]) -> bool:
    api_key = (env.get("APIYI_API_KEY", "") or "").strip()
    base_url = normalize_openai_compatible_base_url(env.get("APIYI_BASE_URL", "") or "")
    return bool(api_key and base_url)


def third_party_image_available(env: dict[str, str]) -> bool:
    api_key = (env.get("THIRD_PARTY_IMAGE_API_KEY", "") or "").strip()
    base_url = normalize_openai_compatible_base_url(env.get("THIRD_PARTY_IMAGE_BASE_URL", "") or "")
    return bool(api_key and base_url)


def imageai_playground_available(env: dict[str, str]) -> bool:
    if env_flag(env.get("IMAGEAI_PLAYGROUND_USE_SAVED_SETTINGS", "true")):
        return bool(clean_text(env.get("IMAGEAI_PLAYGROUND_URL") or "https://imageai.centos.hk/"))
    return third_party_image_available(env)


def resolve_image_provider(env: dict[str, str]) -> dict[str, str]:
    preference = clean_text(env.get("IMAGE_PROVIDER") or "auto").lower() or "auto"
    prefer_apiyi = env_flag(env.get("APIYI_IMAGE_REPLACE_ARK"))
    has_apiyi = apiyi_image_available(env)
    has_third_party = third_party_image_available(env)
    has_imageai_playground = imageai_playground_available(env)
    has_ark = bool((env.get("ARK_API_KEY", "") or "").strip())
    has_agnes = bool((env.get("AGNES_API_KEY", "") or "").strip())

    if preference in {"chatgpt_web_auto", "chatgpt-auto", "chatgpt_auto", "chatgpt_browser"}:
        return {"key": "chatgpt_web_auto", "label": "ChatGPT 网页自动化", "model": "chatgpt-account"}
    if preference in {"chatgpt_web_handoff", "chatgpt-web-handoff", "chatgpt_web_manual"}:
        return chatgpt_handoff_provider_record("chatgpt_web_handoff", env)
    if preference in {"chatgpt_desktop_handoff", "chatgpt-desktop-handoff", "chatgpt_classic", "chatgpt-classic"}:
        return chatgpt_handoff_provider_record("chatgpt_desktop_handoff", env)
    if preference in {"chatgpt", "chatgpt_handoff", "chatgpt-web", "chatgpt_web"}:
        return chatgpt_handoff_provider_record("chatgpt_handoff", env)
    if preference in {"imageai_playground", "imageai", "gpt_image_playground", "gpt-image-playground", "playground_web"}:
        if not has_imageai_playground:
            raise RuntimeError("已选择 GPT Image Playground 网页出图，但入口地址为空；若关闭了网站已保存配置，还需要填写第三方 API Key/Base URL。")
        return {"key": "imageai_playground", "label": "GPT Image Playground 网页", "model": resolve_third_party_image_model(env)}
    if preference in {"newapi", "new_api", "new-api"}:
        if not has_third_party:
            raise RuntimeError("已选择 NewAPI 出图，但 THIRD_PARTY_IMAGE_API_KEY 或 THIRD_PARTY_IMAGE_BASE_URL 还没填完整。")
        return {"key": "third_party", "label": "NewAPI / OpenAI Image", "model": resolve_third_party_image_model(env)}
    if preference in {"third_party", "third-party", "custom_openai", "custom-openai", "openai_custom", "openai-custom"}:
        if not has_third_party:
            raise RuntimeError("已选择第三方 OpenAI 兼容出图，但 THIRD_PARTY_IMAGE_API_KEY 或 THIRD_PARTY_IMAGE_BASE_URL 还没填完整。")
        return {"key": "third_party", "label": "第三方 OpenAI 兼容文生图", "model": resolve_third_party_image_model(env)}
    if preference in {"apiyi"}:
        if not has_apiyi:
            raise RuntimeError("已选择 OpenAI 兼容/API易出图，但 APIYI_API_KEY 或 APIYI_BASE_URL 还没填完整。")
        return {"key": "apiyi", "label": "API易 / OpenAI 兼容文生图", "model": resolve_apiyi_image_model(env)}
    if preference in {"openai_compatible", "openai-compatible"}:
        if has_third_party:
            return {"key": "third_party", "label": "第三方 OpenAI 兼容文生图", "model": resolve_third_party_image_model(env)}
        if has_apiyi:
            return {"key": "apiyi", "label": "API易 / OpenAI 兼容文生图", "model": resolve_apiyi_image_model(env)}
        raise RuntimeError("已选择 OpenAI 兼容出图，但第三方/APIYI 配置都不完整。")
    if preference in {"ark", "seedream", "doubao"}:
        if not has_ark:
            raise RuntimeError("已选择火山方舟出图，但 ARK_API_KEY 还没填写。")
        return {"key": "ark", "label": "火山方舟 Seedream", "model": resolve_ark_image_model(env)}
    if preference in {"agnes", "agnes_image", "agnes-image"}:
        if not has_agnes:
            raise RuntimeError("已选择 Agnes 图片 API，但 AGNES_API_KEY 还没填写。")
        return {
            "key": "agnes",
            "label": "Agnes Image 2.1 Flash",
            "model": clean_text(env.get("AGNES_IMAGE_MODEL") or capsule_providers.DEFAULT_AGNES_IMAGE_MODEL),
        }

    if prefer_apiyi:
        if not has_apiyi:
            raise RuntimeError("已开启 OpenAI 兼容出图，但 APIYI_API_KEY 或 APIYI_BASE_URL 还没填完整。")
        return {"key": "apiyi", "label": "API易 / OpenAI 兼容文生图", "model": resolve_apiyi_image_model(env)}
    if has_ark:
        return {"key": "ark", "label": "火山方舟 Seedream", "model": resolve_ark_image_model(env)}
    if has_agnes:
        return {
            "key": "agnes",
            "label": "Agnes Image 2.1 Flash",
            "model": clean_text(env.get("AGNES_IMAGE_MODEL") or capsule_providers.DEFAULT_AGNES_IMAGE_MODEL),
        }
    if has_third_party:
        return {"key": "third_party", "label": "第三方 OpenAI 兼容文生图", "model": resolve_third_party_image_model(env)}
    if has_apiyi:
        return {"key": "apiyi", "label": "API易 / OpenAI 兼容文生图", "model": resolve_apiyi_image_model(env)}
    raise RuntimeError("未配置可用的文生图服务。请先配置方舟密钥，或填写 OpenAI 兼容文生图配置。")


def resolve_image_provider_queue(env: dict[str, str]) -> list[dict[str, str]]:
    """Return image providers in failover order.

    auto_no_apiyi intentionally skips third-party/OpenAI-compatible accounts so
    image generation never waits on those services. Explicit IMAGE_PROVIDER
    values are strict and do not silently fall back to another provider.
    """
    preference = clean_text(env.get("IMAGE_PROVIDER") or "auto").lower() or "auto"
    has_ark = bool((env.get("ARK_API_KEY", "") or "").strip())
    has_agnes = bool((env.get("AGNES_API_KEY", "") or "").strip())
    has_apiyi = apiyi_image_available(env)
    has_third_party = third_party_image_available(env)
    has_imageai_playground = imageai_playground_available(env)
    allow_chatgpt_auto = not env.get("CHATGPT_IMAGE_AUTO_OPEN") or env_flag(env.get("CHATGPT_IMAGE_AUTO_OPEN"))

    def record(key: str) -> dict[str, str]:
        if key == "ark":
            return {"key": "ark", "label": "火山方舟 Seedream", "model": resolve_ark_image_model(env)}
        if key == "agnes":
            return {
                "key": "agnes",
                "label": "Agnes Image 2.1 Flash",
                "model": clean_text(env.get("AGNES_IMAGE_MODEL") or capsule_providers.DEFAULT_AGNES_IMAGE_MODEL),
            }
        if key == "apiyi":
            return {"key": "apiyi", "label": "API易 / OpenAI 兼容文生图", "model": resolve_apiyi_image_model(env)}
        if key == "third_party":
            return {"key": "third_party", "label": "第三方 OpenAI 兼容文生图", "model": resolve_third_party_image_model(env)}
        if key == "newapi":
            return {"key": "third_party", "label": "NewAPI / OpenAI Image", "model": resolve_third_party_image_model(env)}
        if key == "imageai_playground":
            return {"key": "imageai_playground", "label": "GPT Image Playground 网页", "model": resolve_third_party_image_model(env)}
        if key == "chatgpt_web_auto":
            return {"key": "chatgpt_web_auto", "label": "ChatGPT 网页自动化", "model": "chatgpt-account"}
        if key in CHATGPT_HANDOFF_PROVIDER_KEYS:
            return chatgpt_handoff_provider_record(key, env)
        raise RuntimeError(f"未知图片生成供应商：{key}")

    if preference in {"auto_no_apiyi", "no_apiyi", "auto_without_apiyi", "skip_apiyi"}:
        providers: list[dict[str, str]] = []
        if has_ark:
            providers.append(record("ark"))
        if allow_chatgpt_auto:
            providers.append(record("chatgpt_web_auto"))
        if providers:
            return providers
        raise RuntimeError("未配置可用的非第三方图片生成渠道。")

    if preference in {"ark", "seedream", "doubao"}:
        if not has_ark:
            raise RuntimeError("已选择火山方舟出图，但 ARK_API_KEY 还没填写。")
        return [record("ark")]
    if preference in {"agnes", "agnes_image", "agnes-image"}:
        if not has_agnes:
            raise RuntimeError("已选择 Agnes 图片 API，但 AGNES_API_KEY 还没填写。")
        return [record("agnes")]

    if preference in {"chatgpt_web_auto", "chatgpt-auto", "chatgpt_auto", "chatgpt_browser"}:
        return [record("chatgpt_web_auto")]
    if preference in {"chatgpt_web_handoff", "chatgpt-web-handoff", "chatgpt_web_manual"}:
        return [record("chatgpt_web_handoff")]
    if preference in {"chatgpt_desktop_handoff", "chatgpt-desktop-handoff", "chatgpt_classic", "chatgpt-classic"}:
        return [record("chatgpt_desktop_handoff")]
    if preference in {"chatgpt", "chatgpt_handoff", "chatgpt-web", "chatgpt_web"}:
        return [record("chatgpt_handoff")]
    if preference in {"imageai_playground", "imageai", "gpt_image_playground", "gpt-image-playground", "playground_web"}:
        if not has_imageai_playground:
            raise RuntimeError("已选择 GPT Image Playground 网页出图，但入口地址为空；若关闭了网站已保存配置，还需要填写第三方 API Key/Base URL。")
        return [record("imageai_playground")]
    if preference in {"newapi", "new_api", "new-api"}:
        if not has_third_party:
            raise RuntimeError("已选择 NewAPI 出图，但第三方配置不完整。")
        return [record("newapi")]
    if preference in {"third_party", "third-party", "custom_openai", "custom-openai", "openai_custom", "openai-custom"}:
        if not has_third_party:
            raise RuntimeError("已选择第三方 OpenAI 兼容出图，但第三方配置不完整。")
        return [record("third_party")]
    if preference in {"apiyi"}:
        if not has_apiyi:
            raise RuntimeError("已选择 APIYI，但 APIYI 配置不完整。")
        return [record("apiyi")]
    if preference in {"openai_compatible", "openai-compatible"}:
        if has_third_party:
            return [record("third_party")]
        if has_apiyi:
            return [record("apiyi")]
        raise RuntimeError("已选择 OpenAI 兼容出图，但第三方/APIYI 配置都不完整。")

    return [resolve_image_provider(env)]


def describe_image_provider_queue(env: dict[str, str]) -> str:
    providers = resolve_image_provider_queue(env)
    preference = clean_text(env.get("IMAGE_PROVIDER") or "auto").lower() or "auto"
    labels = " -> ".join(
        f"{provider['label']}({provider.get('model') or 'default'})"
        for provider in providers
    )
    if preference in {"auto", "auto_no_apiyi", "no_apiyi", "auto_without_apiyi", "skip_apiyi"}:
        return f"自动选择队列：{labels}"
    return f"已锁定图片入口：{labels}；失败将直接报错，不自动切换"


def openai_compatible_image_config(env: dict[str, str], provider_key: str) -> dict[str, Any]:
    if provider_key == "third_party":
        return {
            "key": "third_party",
            "label": "第三方 OpenAI 兼容文生图",
            "api_key": (env.get("THIRD_PARTY_IMAGE_API_KEY", "") or "").strip(),
            "base_url": normalize_openai_compatible_base_url(env.get("THIRD_PARTY_IMAGE_BASE_URL", "") or ""),
            "model": resolve_third_party_image_model(env),
            "timeout": third_party_image_timeout(env),
            "retries": third_party_image_retries(env),
        }
    return {
        "key": "apiyi",
        "label": "API易 / OpenAI 兼容文生图",
        "api_key": (env.get("APIYI_API_KEY", "") or "").strip(),
        "base_url": normalize_openai_compatible_base_url(env.get("APIYI_BASE_URL", "") or ""),
        "model": resolve_apiyi_image_model(env),
        "timeout": apiyi_image_timeout(env),
        "retries": apiyi_image_retries(env),
    }


def generate_openai_compatible_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    provider_key: str = "apiyi",
    provider_label: str | None = None,
    reference_images: list[Path] | None = None,
) -> Path:
    config = openai_compatible_image_config(env, provider_key)
    api_key = str(config["api_key"])
    base_url = str(config["base_url"])
    label = provider_label or str(config["label"])
    if not api_key:
        raise RuntimeError(f"{label} API Key 未配置，无法调用 OpenAI 兼容文生图。")
    if not base_url:
        raise RuntimeError(f"{label} Base URL 未配置，无法调用 OpenAI 兼容文生图。")

    model = str(config["model"])
    if is_openai_compatible_connection_stub(model):
        raise RuntimeError(
            f"{label} 图片模型 ID 不能填写 {model}；它是 NewAPI 连接对象类型，不是图片模型。请改成 gpt-image-1、dall-e-3、gpt-image-2-all 或你的 NewAPI 图片模型别名。"
        )
    request_size = normalize_openai_compatible_image_size(size, model)
    clean_prompt = apply_apiyi_prompt_conventions(prompt, size, purpose)
    references = [path for path in list(reference_images or []) if path.exists()][:6]
    if references:
        if OpenAI is None:
            raise RuntimeError(f"{label} 图生图需要 openai 依赖。")
        client = OpenAI(api_key=api_key, base_url=base_url, timeout=float(config["timeout"]), max_retries=0)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with contextlib.ExitStack() as stack:
            image_files = [stack.enter_context(path.open("rb")) for path in references]
            try:
                response = client.images.edit(
                    model=model,
                    image=image_files,
                    prompt=clean_prompt,
                    n=1,
                    size=request_size,
                    response_format="b64_json",
                    input_fidelity="high",
                )
            except Exception as exc:
                raise RuntimeError(
                    f"{label} 当前模型未完成商品参考图编辑：{user_facing_error(exc)}。"
                    "请改用火山方舟 Seedream 或 ChatGPT 网页自动化后重试。"
                ) from exc
        item = response.data[0] if getattr(response, "data", None) else None
        b64_json = clean_text(str(getattr(item, "b64_json", "") or "")) if item else ""
        image_url = clean_text(str(getattr(item, "url", "") or "")) if item else ""
        if b64_json:
            output_path.write_bytes(base64.b64decode(b64_json))
        elif image_url:
            output_path.write_bytes(_download_provider_binary(image_url, timeout=float(config["timeout"])))
        else:
            raise RuntimeError(f"{label} 图生图响应里没有图片数据。")
        storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")
        if log:
            log(f"[images] {label} 已使用 {len(references)} 张商品参考图完成图生图")
        return output_path
    payload: dict[str, Any] = {
        "model": model,
        "prompt": clean_prompt,
        "n": 1,
        "size": request_size,
        "response_format": "b64_json",
    }
    headers = {"Authorization": f"Bearer {api_key}", "Accept": "application/json"}
    output_path.parent.mkdir(parents=True, exist_ok=True)
    last_exc: RuntimeError | None = None
    request_timeout = float(config["timeout"])
    max_retries = int(config["retries"])
    endpoint = f"{base_url}/images/generations"
    for attempt in range(1, max_retries + 1):
        payload["response_format"] = "b64_json"
        try:
            started = time.monotonic()
            if log:
                log(
                    f"[images] {label} POST {endpoint} model={model} "
                    f"size={request_size} response_format=b64_json attempt={attempt}/{max_retries} timeout={request_timeout:.0f}s"
                )
            try:
                response = _request_provider_json(
                    "POST",
                    endpoint,
                    headers,
                    payload=payload,
                    timeout=request_timeout,
                )
            except RuntimeError as exc:
                message = str(exc).lower()
                if "response_format" in message or "b64_json" in message:
                    payload["response_format"] = "url"
                    if log:
                        log(f"[images] {label} b64_json response_format not accepted; retrying same attempt with url")
                    response = _request_provider_json(
                        "POST",
                        endpoint,
                        headers,
                        payload=payload,
                        timeout=request_timeout,
                    )
                else:
                    raise
            if log:
                log(f"[images] {label} response received in {time.monotonic() - started:.1f}s; downloading/decoding image")
            image_data = _extract_provider_image_bytes(response, timeout=request_timeout)
            output_path.write_bytes(image_data)
            storage.write_text(output_path.with_suffix(".md"), clean_prompt + "\n")
            if log:
                log(f"[images] {label} saved {output_path.name} ({len(image_data) / 1048576.0:.1f} MB)")
            return output_path
        except RuntimeError as exc:
            last_exc = exc
            if log:
                elapsed = time.monotonic() - started if "started" in locals() else 0.0
                log(f"[images] {label} attempt {attempt}/{max_retries} failed after {elapsed:.1f}s: {exc}")
            if attempt >= max_retries:
                break
            delay = min(6, attempt * 2)
            if log:
                log(f"[images] {label} retrying in {delay}s")
            time.sleep(delay)
    if last_exc is not None:
        raise last_exc
    raise RuntimeError("OpenAI 兼容文生图调用失败。")


def image_prompt_generation_attempt_limit(provider_key: str, output_name: str) -> int:
    normalized_name = clean_text(output_name).lower()
    if re.search(r"s_\d+_[a-z](?:\.gen-\d+)?\.png$", normalized_name):
        return 1
    if clean_text(provider_key).lower() in {"chatgpt_web_auto", "imageai_playground"}:
        # Browser image generation is slow and costly. Once it returns a usable
        # image, semantic/typography audit findings stay as review warnings;
        # they must not trigger another browser generation of the same slot.
        # Explicit single-image redraw remains available from the UI.
        return 1
    return IMAGE_PROMPT_REWRITE_ATTEMPTS


SCENE_SELECTED_CONCEPT_RE = re.compile(
    r"选定视觉概念\s*[:：]\s*(.*?)"
    r"(?=\s+(?:本镜任务|画面任务|可参考的场景证据|不可改错的数字事实|数字边界|创作边界)\s*[:：]|$)",
    flags=re.IGNORECASE,
)


def selected_visual_concept_from_prompt(prompt: str) -> str:
    match = SCENE_SELECTED_CONCEPT_RE.search(normalize_image_prompt(prompt))
    return compact_visual_concept(match.group(1), 280) if match else ""


def repair_generic_scene_visual_concept(prompt: str) -> tuple[str, list[str]]:
    source = normalize_image_prompt(prompt)
    concept = selected_visual_concept_from_prompt(source)
    issues = visual_concept_quality_issues(concept)
    generic_issues = [
        issue
        for issue in issues
        if issue in {
            "通用人物摊手摆拍，缺少当前口播的证据动作",
            "用问号或红叉代替具体冲突证据",
            "用抽象手势或符号代替具体冲突证据",
        }
    ]
    if not generic_issues:
        return source, []
    evidence_following_markers = (
        "选定视觉概念：",
        "本镜任务：",
        "建议的信息结构：",
        "必须落进成图的信息：",
        "不可改错的数字事实：",
        "数字事实：",
        "数字事实（仅校准物件与因果，不画成字符）：",
        "数字边界：",
        "排版：",
        "创作边界：",
        "创作自由：",
        "视觉取舍：",
        "信息策略：",
        "文字策略：",
        "静音验收：",
        "排版分工（最高优先级）：",
    )
    evidence = ""
    for evidence_marker in ("来源支撑信息：", "信息证据："):
        evidence = _semantic_brief_value(source, evidence_marker, evidence_following_markers)
        if evidence:
            break
    evidence = _compact_complete_text(evidence, 132)
    if evidence:
        replacement = (
            "选定视觉概念：证据驱动画面，用下方信息证据里的具体对象、动作与结果组成同一现场；"
            "必须看见原因、过程和结果的物件关系，不用抽象手势、红叉、问号、盾牌或放大镜代替证据"
        )
    else:
        replacement = (
            "选定视觉概念：视觉方案重选，从当前完整口播里选择可见的测试动作、实物证据、"
            "因果关系或结果反差作为主画面；"
            "人物只能参与真实动作，不能正对镜头摊手摆拍，也不能让抽象手势或符号代替具体内容"
        )
    repaired = SCENE_SELECTED_CONCEPT_RE.sub(replacement, source, count=1)
    return normalize_image_prompt(repaired), generic_issues


def project_scene_visual_memory_clause(output_path: Path, limit: int = 5) -> str:
    """Build dynamic anti-repetition context from this project's accepted shots."""
    scene_root = scene_image_root(output_path)
    current_index = scene_image_index_from_path(output_path)
    if scene_root is None or current_index <= 0:
        return ""

    memories: list[tuple[int, str]] = []
    for image_path in scene_root.iterdir() if scene_root.exists() else []:
        if not image_path.is_file() or image_path.suffix.lower() not in RASTER_IMAGE_SUFFIXES:
            continue
        if image_path.name.startswith("."):
            continue
        scene_index = scene_image_index_from_path(image_path)
        if scene_index <= 0 or scene_index == current_index:
            continue
        prompt = read_generated_prompt(image_path, "")
        concept = compact_visual_concept(selected_visual_concept_from_prompt(prompt), 110)
        if not concept:
            continue
        memories.append((scene_index, concept))
    if not memories:
        return ""

    nearest = sorted(memories, key=lambda item: (abs(item[0] - current_index), item[0]))[: max(1, limit)]
    nearest.sort(key=lambda item: item[0])
    used = "；".join(f"镜头{index}：{concept}" for index, concept in nearest)
    return (
        f"项目内已用视觉记忆（只用于避重，不是画面文字）：{used}。"
        "保持当前口播事实和必要主体不变，但本镜不能复刻这些镜头的主体摆位、人物姿势、景别、信息版式或证据组合；"
        "请根据当前口播另选更有冲突的动作、证据视角和空间关系，差异必须一眼可见，不能只换颜色或背景。"
    )


def product_reference_images_for_output(output_path: Path) -> list[Path]:
    try:
        relative = output_path.resolve(strict=False).relative_to(storage.PROJECTS_ROOT.resolve())
        project_id = int(relative.parts[0]) if relative.parts else 0
    except (ValueError, OSError, IndexError):
        return []
    if project_id <= 0:
        return []
    references: list[Path] = []
    settings = storage.get_project_settings(project_id)
    if clean_text(str(settings.get("content_type") or "")) == "product":
        for filename in list(settings.get("product_asset_files") or [])[:6]:
            path = storage.project_file(project_id, f"uploads/products/{storage.safe_name(str(filename))}")
            if path.exists() and path.is_file() and path.suffix.lower() in RASTER_IMAGE_SUFFIXES:
                references.append(path)
    for item in list_project_sources(project_id):
        if clean_text(str(item.get("type") or "")).lower() != "image" or not bool(item.get("must_use")):
            continue
        relative_path = clean_text(str(item.get("relative_path") or ""))
        if not relative_path:
            continue
        path = storage.project_file(project_id, relative_path)
        if (
            path.exists()
            and path.is_file()
            and path.suffix.lower() in RASTER_IMAGE_SUFFIXES
            and path not in references
        ):
            references.append(path)
    return references[:6]


def generate_configured_image(
    prompt: str,
    output_path: Path,
    size: str,
    purpose: str,
    env: dict[str, str],
    log: Callable[[str], None] | None = None,
    template: dict[str, Any] | None = None,
) -> Path:
    providers = resolve_image_provider_queue(env)
    reference_images = product_reference_images_for_output(output_path)
    template_stub = dict(template or {})
    template_stub.update(
        {
            "brand_name": template_stub.get("brand_name", ""),
            "cover_footnote_line_1": template_stub.get("cover_footnote_line_1", ""),
            "cover_footnote_line_2": template_stub.get("cover_footnote_line_2", ""),
        }
    )
    last_error: Exception | None = None

    for provider_index, provider in enumerate(providers, start=1):
        audit_report: dict[str, Any] | None = None
        last_path: Path | None = None
        output_name = output_path.name.lower()
        competition_candidate = bool(re.search(r"s_\d+_[a-z](?:\.gen-\d+)?\.png$", output_name))
        max_prompt_attempts = image_prompt_generation_attempt_limit(provider["key"], output_name)
        if log:
            mode_note = "严格模式" if len(providers) == 1 else f"自动队列 {provider_index}/{len(providers)}"
            log(f"[images] provider -> {provider['label']} model={provider.get('model') or 'default'} mode={mode_note}")
            if reference_images:
                log(f"[images] 商品模式已绑定 {len(reference_images)} 张真实参考图，本张禁止退回纯文生图")
        try:
            for attempt in range(1, max_prompt_attempts + 1):
                integrity_source_prompt = prompt
                direct_prompt = ""
                if purpose == "scene":
                    balanced_prompt = (
                        normalize_image_prompt(prompt)
                        if is_semantic_scene_generation_brief(prompt)
                        else balanced_scene_generation_brief(prompt)
                    )
                    if "本期主题：" in balanced_prompt and "当前完整口播：" in balanced_prompt:
                        direct_prompt = balanced_prompt
                        integrity_source_prompt = balanced_prompt
                if not direct_prompt and image_prompt_has_topic_anchor(prompt):
                    direct_prompt = sanitize_prompt_for_image_model(prompt, purpose) or normalize_image_prompt(prompt)
                if direct_prompt:
                    prepared_prompt = direct_prompt
                    generic_concept_issues: list[str] = []
                    if purpose == "scene":
                        prepared_prompt, generic_concept_issues = repair_generic_scene_visual_concept(prepared_prompt)
                    repair_clauses: list[str] = []
                    reasons = audit_report.get("reasons", []) if audit_report else []
                    if attempt > 1 and reasons:
                        if any("text" in str(reason) for reason in reasons):
                            repair_clauses.append("重绘修正版：底图清除全部可读文字、数字、乱码、水印和页脚，只保留无字场景、物件、动作和关系证据")
                        if any("empty" in str(reason) or "foreground" in str(reason) or "coverage" in str(reason) for reason in reasons):
                            repair_clauses.append("重绘修正版：把主题相关人物、设备或关键物件放大到前景，减少空白")
                        if any("flat" in str(reason) for reason in reasons):
                            repair_clauses.append("重绘修正版：增强人物表情、设备细节、前景遮挡和高对比光影")
                        if any("duplicate_scene" in str(reason) for reason in reasons):
                            duplicate_match = next(
                                (
                                    item
                                    for item in (audit_report.get("project_similarity", {}).get("matches", []) if audit_report else [])
                                    if item.get("near_duplicate")
                                ),
                                {},
                            )
                            duplicate_name = clean_text(str(duplicate_match.get("filename") or "已有镜头"))
                            repair_clauses.append(
                                f"概念级重绘：上一版与 {duplicate_name} 重复；保留当前口播事实，"
                                "彻底更换主动作、证据载体、镜头景别、主体摆位和信息层级，不能只换颜色、人物或背景"
                            )
                        if any("ocr_fact_mismatch" in str(reason) for reason in reasons):
                            repair_clauses.append("事实修正版：重新核对当前口播中的数量和因果关系，用无字物件状态与图形关系表达，不在底图写数字")
                        if any(str(reason) in {"ocr_production_meta", "ocr_semantic_mismatch"} for reason in reasons):
                            repair_clauses.append("语义修正版：清除全部生产过程文字和其它可读字符；只保留服务当前主题的无字场景、物件、动作、状态和图形关系")
                        if any(str(reason) == "ocr_information_missing" for reason in reasons):
                            repair_clauses.append(
                                "原生文字修正版：上一版漏字或文字不完整；重新生成整张图片，"
                                "让当前口播的主结论、关键数字和必要说明在画面内完整可读，允许自动换行，禁止截断、乱码和模板标题板"
                            )
                        scene_speech = scene_prompt_speech_anchor(integrity_source_prompt)
                        topic_match = re.search(
                            r"(?:本期主题|主题)\s*[:：]\s*([^\n。；]{2,80})",
                            normalize_image_prompt(integrity_source_prompt),
                        )
                        audience_plan = audience_visual_plan(
                            topic=clean_text(topic_match.group(1) if topic_match else ""),
                            narration=scene_speech or integrity_source_prompt,
                            index=max(1, scene_image_index_from_path(output_path)),
                        )
                        audience_issues = audience_visual_failure_reasons(
                            audience_plan,
                            visual_concept=prepared_prompt,
                            audit_reasons=[str(item) for item in reasons],
                        )
                        repair_clauses.extend(audience_visual_repair_actions(audience_plan, audience_issues))
                    if repair_clauses:
                        prepared_prompt = compact_visual_image_prompt("。".join([prepared_prompt, *repair_clauses]), 760 if purpose == "cover" else 720)
                    review_score = prompt_visual_score(prepared_prompt, purpose)
                    prompt_review = {
                        "before": review_score,
                        "after": review_score,
                        "rewritten": bool(generic_concept_issues),
                        "topic_locked": True,
                        "generic_concept_repaired": generic_concept_issues,
                    }
                else:
                    prepared_prompt = optimize_visual_generation_prompt(
                        prompt,
                        template_stub,
                        purpose,
                        attempt=attempt,
                        audit_reasons=audit_report.get("reasons", []) if audit_report else None,
                    )
                    prepared_prompt, prompt_review = rewrite_prompt_by_visual_director(prepared_prompt, purpose)
                if purpose == "scene":
                    diversity_clause = project_scene_visual_memory_clause(output_path)
                    if diversity_clause:
                        prepared_prompt = "\n".join([prepared_prompt, diversity_clause])
                typography_payload = image_exact_typography_payload(prepared_prompt, purpose)
                audit_reference_prompt = prepared_prompt
                if purpose != "scene" and typography_payload.get("headline"):
                    prepared_prompt = reserve_exact_typography_area(prepared_prompt, purpose, typography_payload)
                integrity_source_prompt = repair_legacy_mojibake(integrity_source_prompt)
                prepared_prompt = repair_legacy_mojibake(prepared_prompt)
                pre_compact_length = len(normalize_image_prompt(prepared_prompt))
                prepared_prompt = (
                    lightweight_scene_model_prompt(prepared_prompt, max_chars=680)
                    if purpose == "scene"
                    else compile_outbound_image_prompt(
                        prepared_prompt,
                        purpose,
                        max_chars=560,
                    )
                )
                outbound_review = prompt_visual_score(prepared_prompt, purpose)
                prompt_review["after"] = outbound_review
                prompt_integrity = semantic_scene_brief_integrity(integrity_source_prompt, prepared_prompt) if purpose == "scene" else {"required": False, "ok": True, "missing": []}
                if not prompt_integrity.get("ok"):
                    missing = "、".join(str(item) for item in prompt_integrity.get("missing", []))
                    raise RuntimeError(f"实际生图提示词在发送前丢失了{missing}，已停止生成，避免使用残缺提示词。")
                display_name = output_path.name
                if display_name.startswith(".") and ".gen-" in display_name:
                    display_name = display_name[1:].split(".gen-", 1)[0] + output_path.suffix
                if log:
                    if prompt_review.get("generic_concept_repaired"):
                        log(
                            "[images] 已淘汰通用人物摆拍概念，发送前改为按当前口播重新选择测试动作、证据和结果反差"
                        )
                    if prompt_review.get("reverted_negative_rewrite"):
                        before = prompt_review.get("before", {})
                        rejected = (prompt_review.get("rejected_rewrite") or {}).get("score", {})
                        after = prompt_review.get("after", {})
                        log(
                            f"[images] 视觉导演改写降分已回退：原 {before.get('score', 0)} 分，"
                            f"改写 {rejected.get('score', 0)} 分，继续使用 {after.get('score', before.get('score', 0))} 分原提示词"
                        )
                    elif prompt_review.get("rewritten"):
                        before = prompt_review.get("before", {})
                        after = prompt_review.get("after", {})
                        log(
                            f"[images] 视觉导演已重写提示词：{before.get('score', 0)} -> {after.get('score', 0)} 分，"
                            f"长度 {before.get('length', 0)} -> {after.get('length', 0)}"
                        )
                    else:
                        score = prompt_review.get("after", {}).get("score", prompt_review.get("before", {}).get("score", 0))
                        length = prompt_review.get("after", {}).get("length", prompt_review.get("before", {}).get("length", 0))
                        log(f"[images] 视觉导演提示词评分：{score} 分，长度 {length}")
                    if prompt_integrity.get("required"):
                        log("[images] 实际提示词完整性通过：主题、口播锚点与事实数字已保留")
                    if pre_compact_length != len(prepared_prompt):
                        log(
                            f"[images] 发送前语义压缩：{pre_compact_length} -> {len(prepared_prompt)} 字，"
                            "已移除重复规则并保留当前镜头事实"
                        )
                    log(
                        f"[images] 使用 {provider['label']} 生成 {display_name}"
                        f"（model={provider.get('model') or 'default'}，attempt={attempt}/{max_prompt_attempts}）"
                    )
                try:
                    if provider["key"] == "chatgpt_web_auto":
                        last_path = generate_chatgpt_web_auto_image(
                            prepared_prompt,
                            output_path,
                            size,
                            purpose,
                            env,
                            log=log,
                            reference_images=reference_images,
                        )
                    elif provider["key"] == "imageai_playground":
                        last_path = generate_imageai_playground_image(
                            prepared_prompt,
                            output_path,
                            size,
                            purpose,
                            env,
                            log=log,
                            reference_images=reference_images,
                        )
                    elif provider["key"] in CHATGPT_HANDOFF_PROVIDER_KEYS:
                        if reference_images:
                            raise RuntimeError(
                                "当前 ChatGPT 手动接力入口不能自动附带商品参考图。"
                                "请切换到 ChatGPT 网页自动化或火山方舟 Seedream。"
                            )
                        last_path = generate_chatgpt_handoff_image(
                            prepared_prompt,
                            output_path,
                            size,
                            purpose,
                            env,
                            log=log,
                            provider_key=provider["key"],
                        )
                    elif provider["key"] in {"apiyi", "third_party"}:
                        last_path = generate_openai_compatible_image(
                            prepared_prompt,
                            output_path,
                            size,
                            purpose,
                            env,
                            log=log,
                            provider_key=provider["key"],
                            provider_label=provider["label"],
                            reference_images=reference_images,
                        )
                    elif provider["key"] == "agnes":
                        if reference_images:
                            raise RuntimeError("Agnes 图片 API 当前只处理文生图；商品参考图请使用 Seedream。")
                        size_match = re.search(r"(\d+)\s*[x×]\s*(\d+)", str(size), re.IGNORECASE)
                        if size_match:
                            requested_width = int(size_match.group(1))
                            requested_height = int(size_match.group(2))
                            ratio = "9:16" if requested_height > requested_width else "1:1" if requested_height == requested_width else "16:9"
                        else:
                            ratio = "16:9"
                        capsule_providers.generate_agnes_image(
                            prompt=prepared_prompt,
                            output_path=output_path,
                            api_key=clean_text(env.get("AGNES_API_KEY")),
                            model=clean_text(env.get("AGNES_IMAGE_MODEL") or capsule_providers.DEFAULT_AGNES_IMAGE_MODEL),
                            base_url=clean_text(env.get("AGNES_BASE_URL") or capsule_providers.DEFAULT_AGNES_BASE_URL),
                            ratio=ratio,
                            size="1K",
                            timeout=configured_timeout_seconds(env, "THIRD_PARTY_IMAGE_TIMEOUT_SECONDS", 1200, 120, 3600),
                        )
                        last_path = output_path
                    else:
                        last_path = generate_ark_image(
                            prepared_prompt,
                            output_path,
                            size,
                            purpose,
                            env,
                            reference_images=reference_images,
                        )
                except Exception as generation_exc:
                    error_text = clean_text(str(generation_exc))
                    retry_cancelled = any(
                        marker in error_text
                        for marker in ("生图任务已取消", "任务已取消", "用户取消")
                    )
                    if (
                        attempt > 1
                        and not retry_cancelled
                        and last_path is not None
                        and last_path.exists()
                        and audit_report
                    ):
                        preserved_audit = dict(audit_report)
                        preserved_audit["original_severity"] = preserved_audit.get("severity", "")
                        preserved_audit["ok"] = True
                        preserved_audit["severity"] = "soft"
                        preserved_audit["retry_interrupted"] = True
                        preserved_audit["retry_error"] = user_facing_error(generation_exc)
                        warnings = list(preserved_audit.get("warnings") or [])
                        warnings.append("修正版生图未完成，已保留上一张成图供人工复核。")
                        preserved_audit["warnings"] = warnings
                        previous_prompt = clean_text(str(preserved_audit.get("prompt") or prompt))
                        storage.write_text(output_path.with_suffix(".md"), previous_prompt + "\n")
                        storage.write_json(output_path.with_suffix(".audit.json"), preserved_audit)
                        if log:
                            log(
                                f"[images] 第 {attempt} 次修正版未完成；"
                                "已保留上一张成图并标记待人工复核，任务继续"
                            )
                        return last_path
                    raise

                normalize_generated_image_size(last_path, size, log=log, label=display_name)
                if purpose == "scene":
                    # A scene may be regenerated over an older deterministic
                    # typography result.  Remove its legacy sidecars so no
                    # downstream step can mistake the new AI-native image for
                    # an image that still needs a second title layer.
                    scene_information_overlay_path(last_path).unlink(missing_ok=True)
                    scene_information_overlay_asset_path(last_path).unlink(missing_ok=True)
                    scene_information_source_path(last_path).unlink(missing_ok=True)
                if purpose == "cover":
                    # Covers now use the same single-pass contract as scene
                    # images: the image model draws title and subject together.
                    # Delete sidecars from the retired deterministic overlay so
                    # downstream code never treats an old overlay as current.
                    cover_typography_source_path(last_path).unlink(missing_ok=True)
                    last_path.with_suffix(".typography.json").unlink(missing_ok=True)

                audit_report = audit_generated_image(last_path, size, purpose, audit_reference_prompt)
                if purpose == "scene":
                    scene_speech = scene_prompt_speech_anchor(integrity_source_prompt)
                    topic_match = re.search(
                        r"(?:本期主题|主题)\s*[:：]\s*([^\n。；]{2,80})",
                        normalize_image_prompt(integrity_source_prompt),
                    )
                    audience_plan = audience_visual_plan(
                        topic=clean_text(topic_match.group(1) if topic_match else ""),
                        narration=scene_speech or integrity_source_prompt,
                        index=max(1, scene_image_index_from_path(output_path)),
                    )
                    audience_issues = audience_visual_failure_reasons(
                        audience_plan,
                        visual_concept=prepared_prompt,
                        audit_reasons=[str(item) for item in audit_report.get("reasons", [])],
                    )
                    audit_report["audience_visual"] = audience_plan
                    audit_report["audience_issues"] = audience_issues
                    audit_report["audience_repair_actions"] = audience_visual_repair_actions(
                        audience_plan,
                        audience_issues,
                    )
                    semantic_blockers = {
                        "metric_subject_missing",
                        "fake_comparison",
                        "generic_emotion_substitute",
                        "irrelevant_symbolic_object",
                        "speech_visual_mismatch",
                        "visual_proof_missing",
                    }
                    for issue in audience_issues:
                        if issue in semantic_blockers and issue not in audit_report["reasons"]:
                            audit_report["reasons"].append(issue)
                    if any(issue in semantic_blockers for issue in audience_issues):
                        audit_report["severity"] = "soft"
                        audit_report["ok"] = False
                audit_report["attempt"] = attempt
                audit_report["provider"] = provider["key"]
                audit_report["provider_label"] = provider["label"]
                audit_report["prompt"] = prepared_prompt
                audit_report["reference_images"] = [path.name for path in reference_images]
                audit_report["reference_image_count"] = len(reference_images)
                audit_report["prompt_review"] = prompt_review
                audit_report["prompt_integrity"] = prompt_integrity
                audit_report["exact_typography"] = typography_payload
                storage.write_text(output_path.with_suffix(".md"), prepared_prompt + "\n")
                storage.write_json(output_path.with_suffix(".audit.json"), audit_report)

                if audit_report.get("ok"):
                    if log:
                        log(f"[images] {display_name} 第 {attempt} 次生成通过图片自检")
                    return last_path
                audit_reasons = [
                    image_audit_reason_label(str(reason))
                    for reason in audit_report.get("reasons", [])
                    if clean_text(str(reason))
                ]
                if log:
                    reason_text = "、".join(audit_reasons) or "未达到当前图片质量标准"
                    if competition_candidate:
                        log(
                            f"[images] {display_name} 候选自检提示：{reason_text}；"
                            "本候选不重复重绘，交给 A/B 方案评分选择"
                        )
                    elif attempt < max_prompt_attempts:
                        log(
                            f"[images] {display_name} 第 {attempt} 次生成未通过自检：{reason_text}；"
                            f"正在修正提示词并重绘（下一次 {attempt + 1}/{max_prompt_attempts}）"
                        )
                    else:
                        log(f"[images] {display_name} 第 {attempt} 次生成仍未通过自检：{reason_text}")
                if attempt >= max_prompt_attempts:
                    break

            if last_path is None:
                raise RuntimeError("图片生成失败，未得到任何输出。")
            if audit_report and audit_report.get("severity") == "hard" and (
                not competition_candidate or "exact_duplicate_scene" in audit_report.get("reasons", [])
            ):
                reasons = ", ".join(audit_report.get("reasons", []))
                raise RuntimeError(f"图片生成后自检未通过：{reasons}")
            return last_path
        except Exception as exc:
            last_error = exc
            error_message = user_facing_error(exc)
            if output_path.name.startswith("."):
                _cleanup_generated_tmp(output_path)
            if log:
                if provider_index < len(providers):
                    log(f"[images] {provider['label']} 失败：{error_message}；当前是自动队列，切换到下一个图片入口")
                else:
                    log(f"[images] {provider['label']} 失败：{error_message}；已选择严格图片入口，不自动切换")
            if provider_index < len(providers):
                continue
            raise

    if last_error is not None:
        raise last_error
    raise RuntimeError("未配置可用的图片生成渠道。")


def find_scene_image_paths(project_id: int) -> list[Path]:
    status = storage.scene_status(project_id)
    existing = status.get("existing")
    if isinstance(existing, list) and existing:
        paths: list[Path] = []
        for item in existing:
            if not isinstance(item, dict):
                continue
            absolute_path = clean_text(str(item.get("absolute_path") or ""))
            if not absolute_path:
                continue
            path = Path(absolute_path)
            if path.exists() and path.suffix.lower() in RASTER_IMAGE_SUFFIXES:
                paths.append(path)
        if paths:
            return paths
    scene_dir = storage.project_file(project_id, "scenes")
    paths: list[Path] = []
    if not scene_dir.exists():
        return paths
    expected = int(status.get("expected_count", 0) or 0)
    for path in sorted(scene_dir.iterdir()):
        if not path.is_file():
            continue
        if not re.fullmatch(r"s_\d+", path.stem):
            continue
        if path.suffix.lower() not in RASTER_IMAGE_SUFFIXES:
            continue
        if expected > 0:
            match = re.search(r"(\d+)", path.stem)
            if match and int(match.group(1)) > expected:
                continue
        paths.append(path)
    return paths


def find_cover_path(project_id: int) -> Path | None:
    cover_dir = storage.project_file(project_id, "covers")
    for name in (
        "cover_landscape.png",
        "cover_landscape.jpg",
        "cover_landscape.jpeg",
        "cover_story.png",
        "cover_story.jpg",
        "cover_story.jpeg",
    ):
        candidate = cover_dir / name
        if candidate.exists():
            return candidate
    scene_paths = find_scene_image_paths(project_id)
    return scene_paths[0] if scene_paths else None


BGM_FILENAMES = ("bgm.mp3", "bgm.wav", "bgm.m4a", "bgm.aac")
BGM_FEATURE_ENABLED = False
AUTO_BGM_SOURCES = {"procedural_local", "freesound", "jamendo", "loudly"}
ONLINE_BGM_SOURCES = {"freesound", "jamendo", "loudly"}


def auto_bgm_provider_changed(source: str, online_provider: str, online_catalog_ready: bool) -> bool:
    """Only invalidate an automatic track when the selected catalog can replace it.

    A local procedural track is the intentional fallback while an online provider is
    not configured. Treating that fallback as stale creates an endless resume loop.
    Tracks from a different online catalog still need replacing, even before the new
    provider is configured, so the UI can accurately report the provider migration.
    """
    source_key = clean_text(source).lower()
    provider_key = clean_text(online_provider).lower()
    if source_key not in AUTO_BGM_SOURCES or provider_key not in ONLINE_BGM_SOURCES:
        return False
    if source_key == provider_key:
        return False
    return source_key in ONLINE_BGM_SOURCES or bool(online_catalog_ready)


def online_bgm_provider_ready(env: dict[str, str], provider: str) -> bool:
    provider_key = clean_text(provider).lower()
    if provider_key == "loudly":
        return bool(clean_text(env.get("LOUDLY_API_KEY", "")))
    if provider_key == "jamendo":
        return bool(clean_text(env.get("JAMENDO_CLIENT_ID", "")))
    if provider_key == "freesound":
        return bool(clean_text(env.get("FREESOUND_API_KEY", "")))
    return False


def resolve_online_bgm_provider(env: dict[str, str], preferred: str) -> tuple[str, bool]:
    """Use the preferred catalog when ready, otherwise use another configured one."""
    preferred_key = clean_text(preferred).lower() or "loudly"
    candidates = [preferred_key, "loudly", "jamendo", "freesound"]
    for provider in dedupe_clauses(candidates):
        if provider in ONLINE_BGM_SOURCES and online_bgm_provider_ready(env, provider):
            return provider, True
    return preferred_key, False


def find_project_bgm_path(project_id: int) -> Path | None:
    for filename in BGM_FILENAMES:
        project_candidate = storage.project_file(project_id, filename)
        if project_candidate.exists():
            return project_candidate
    return None


def find_template_bgm_path(template_key: str | None = None) -> Path | None:
    if not template_key:
        return None
    for filename in BGM_FILENAMES:
        template_candidate = storage.TEMPLATES_ROOT / template_key / filename
        if template_candidate.exists():
            return template_candidate
    return None


def find_bgm_path(project_id: int, template_key: str | None = None) -> Path | None:
    if not BGM_FEATURE_ENABLED:
        return None
    project_path = find_project_bgm_path(project_id)
    if project_path:
        return project_path
    template_path = find_template_bgm_path(template_key)
    if template_path:
        return template_path
    return None


