def project_bgm_meta_path(project_id: int) -> Path:
    return storage.project_file(project_id, "bgm_meta.json")


def recent_channel_bgm_metas(project_id: int, limit: int = 20) -> list[dict[str, Any]]:
    """Return BGM metadata in recency order for this project and its channel."""
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    ordered: list[dict[str, Any]] = []

    def append_meta(meta: dict[str, Any]) -> None:
        if isinstance(meta, dict) and meta:
            ordered.append(meta)

    append_meta(storage.read_json(project_bgm_meta_path(project_id), {}))
    history_dir = storage.project_file(project_id, "bgm_history")
    if history_dir.exists():
        history_meta = sorted(
            history_dir.glob("bgm_meta-*.json"),
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        for path in history_meta:
            append_meta(storage.read_json(path, {}))
            if len(ordered) >= max(1, int(limit or 20)):
                return ordered[: max(1, int(limit or 20))]

    for item in storage.list_projects():
        other_id = int(item.get("id") or 0)
        if not other_id or other_id == int(project_id):
            continue
        if template_key and clean_text(str(item.get("template") or "")) != template_key:
            continue
        append_meta(storage.read_json(project_bgm_meta_path(other_id), {}))
        if len(ordered) >= max(1, int(limit or 20)):
            break
    return ordered[: max(1, int(limit or 20))]


def bgm_arrangement_id_from_meta(meta: dict[str, Any]) -> str:
    selector = meta.get("selector") if isinstance(meta, dict) and isinstance(meta.get("selector"), dict) else {}
    track = meta.get("track") if isinstance(meta, dict) and isinstance(meta.get("track"), dict) else {}
    return clean_text(str(selector.get("arrangement_id") or track.get("arrangement_id") or ""))


def recent_bgm_arrangement_ids(project_id: int, mood: str, limit: int = 12) -> list[str]:
    ordered: list[str] = []
    desired_mood = clean_text(mood)
    for meta in recent_channel_bgm_metas(project_id, limit=max(limit * 2, 20)):
        selector = meta.get("selector") if isinstance(meta.get("selector"), dict) else {}
        meta_mood = clean_text(str(meta.get("mood") or selector.get("mood") or ""))
        if desired_mood and meta_mood and meta_mood != desired_mood:
            continue
        arrangement_id = bgm_arrangement_id_from_meta(meta)
        if arrangement_id and arrangement_id not in ordered:
            ordered.append(arrangement_id)
        if len(ordered) >= max(1, int(limit or 12)):
            break
    return ordered


def choose_bgm_arrangement(project_id: int, mood: str) -> dict[str, Any]:
    arrangement_ids = list(BGM_MOOD_ARRANGEMENTS.get(mood) or BGM_MOOD_ARRANGEMENTS["story_soft"])
    project = storage.get_project(project_id)
    topic = clean_text(str(project.get("topic_name") or ""))
    seed = int(hashlib.sha256(f"{project_id}:{topic}:{mood}".encode("utf-8", errors="ignore")).hexdigest()[:8], 16)
    offset = seed % max(1, len(arrangement_ids))
    rotated = arrangement_ids[offset:] + arrangement_ids[:offset]
    recent = recent_bgm_arrangement_ids(project_id, mood, limit=max(1, len(arrangement_ids)))
    selected_id = next((item for item in rotated if item not in recent), "")
    if not selected_id:
        recency = {item: recent.index(item) for item in recent}
        selected_id = max(rotated, key=lambda item: recency.get(item, len(recent) + 1))
    selected = BGM_ARRANGEMENT_LIBRARY.get(selected_id, BGM_ARRANGEMENT_LIBRARY["minimal_pulse"])
    return {
        "arrangement_id": selected_id,
        "arrangement_label": selected.get("label", selected_id),
        "arrangement_query_terms": selected.get("query_terms", ""),
        "arrangement_tags": list(selected.get("tags", [])),
        "arrangement_instrumentation": list(selected.get("instrumentation", [])),
        "arrangement_catalog_query": BGM_ARRANGEMENT_CATALOG_QUERIES.get(selected_id, "documentary music"),
        "recent_arrangements": recent[:4],
    }


def project_bgm_settings_path(project_id: int) -> Path:
    return storage.project_file(project_id, "bgm_settings.json")


def project_bgm_mix_preview_path(project_id: int) -> Path:
    return storage.project_file(project_id, "audio/bgm_mix_preview.mp3")


def project_bgm_mix_preview_meta_path(project_id: int) -> Path:
    return storage.project_file(project_id, "audio/bgm_mix_preview.json")


def project_bgm_settings(project_id: int) -> dict[str, Any]:
    payload = storage.read_json(project_bgm_settings_path(project_id), {})
    payload = payload if isinstance(payload, dict) else {}
    volume_value = payload.get("volume")
    try:
        volume = max(0.0, min(float(volume_value), 0.35)) if volume_value is not None else None
    except (TypeError, ValueError):
        volume = None
    return {
        "volume": volume,
        "track_locked": bool(payload.get("track_locked", False)),
        "updated_at": float(payload.get("updated_at", 0) or 0),
    }


def update_project_bgm_settings(
    project_id: int,
    *,
    volume: float | None = None,
    track_locked: bool | None = None,
) -> dict[str, Any]:
    current = project_bgm_settings(project_id)
    if volume is not None:
        current["volume"] = round(max(0.0, min(float(volume), 0.35)), 3)
    if track_locked is not None:
        current["track_locked"] = bool(track_locked)
    current["updated_at"] = storage.now_ts()
    storage.write_json(project_bgm_settings_path(project_id), current)
    project_bgm_mix_preview_path(project_id).unlink(missing_ok=True)
    project_bgm_mix_preview_meta_path(project_id).unlink(missing_ok=True)
    return current


