def project_visual_master_path(project_id: int) -> Path:
    return storage.project_file(project_id, "cache/video/visual-master.mp4")


def project_visual_master_meta_path(project_id: int) -> Path:
    return storage.project_file(project_id, "cache/video/visual-master.json")


def migrate_legacy_visual_master_cache(project_id: int) -> list[str]:
    """Move internal visual-master artifacts out of the public release folder."""
    pairs = (
        (
            storage.project_file(project_id, "releases/visual-master.mp4"),
            project_visual_master_path(project_id),
        ),
        (
            storage.project_file(project_id, "releases/visual_master.json"),
            project_visual_master_meta_path(project_id),
        ),
    )
    migrated: list[str] = []
    for legacy_path, cache_path in pairs:
        if not legacy_path.exists():
            continue
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        if cache_path.exists():
            legacy_path.unlink(missing_ok=True)
        else:
            legacy_path.replace(cache_path)
        migrated.append(legacy_path.name)
    return migrated


def bgm_theme_decision_for_project(project_id: int, content: str = "") -> dict[str, Any]:
    content_text = content or storage.get_content(project_id)
    director = storage.read_json(visual_director_path(project_id), {})
    sound = director.get("sound_direction") if isinstance(director, dict) else {}
    mood = clean_text(str(sound.get("bgm_mood") or "")) if isinstance(sound, dict) else ""
    sound_policy = clean_text(str(sound.get("bgm_policy_version") or "")) if isinstance(sound, dict) else ""
    if mood in PROCEDURAL_BGM_PROFILES and sound_policy == BGM_POLICY_VERSION and visual_director_is_current(director, content_text):
        profile = SOUND_MOOD_PROFILES.get(mood, SOUND_MOOD_PROFILES["story_soft"])
        return {
            "mood": mood,
            "label": profile.get("label", mood),
            "reason": clean_text(str(sound.get("bgm_reason") or "")) or "沿用当前文案的声音导演判断",
            "matched_signals": _text_list(sound.get("bgm_signals"), [], limit=6, item_limit=20),
            "score": float(sound.get("bgm_confidence_score", 0) or 0),
        }
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    return sound_mood_decision(
        clean_text(str(template.get("tavily_topic") or "")),
        clean_text(str(template.get("cover_style") or template.get("style") or "")),
        clean_text(str(template.get("brand_name") or template.get("name") or "")),
        f"{clean_text(str(project.get('topic_name') or ''))}\n{content_text}",
    )


def bgm_mood_for_project(project_id: int, content: str = "") -> str:
    return clean_text(str(bgm_theme_decision_for_project(project_id, content).get("mood") or "story_soft"))


def bgm_context_for_project(project_id: int, content: str = "") -> dict[str, Any]:
    content_text = content or storage.get_content(project_id)
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    semantic_hash = clean_text(str(content_semantic_fingerprints(project, template, content_text).get("bgm_semantic_hash") or ""))
    decision = bgm_theme_decision_for_project(project_id, content_text)
    payload = {
        "policy_version": BGM_POLICY_VERSION,
        "project_id": int(project_id),
        "topic": clean_text(str(project.get("topic_name") or "")),
        "template": clean_text(str(project.get("template") or "")),
        "content_hash": semantic_hash,
    }
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8", errors="ignore")
    return {
        **payload,
        "context_hash": hashlib.sha256(encoded).hexdigest()[:20],
        "desired_mood": decision.get("mood"),
        "desired_label": decision.get("label"),
        "reason": decision.get("reason"),
        "matched_signals": decision.get("matched_signals", []),
    }


def bgm_selection_fingerprint(context: dict[str, Any], brief: dict[str, Any]) -> str:
    payload = {
        "context_hash": context.get("context_hash"),
        "mood": brief.get("mood"),
        "query": brief.get("query"),
        "tags": brief.get("tags", []),
        "bpm": brief.get("bpm", []),
        "provider": brief.get("provider"),
    }
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8", errors="ignore")
    return hashlib.sha256(encoded).hexdigest()[:20]


def normalize_bgm_brief(payload: dict[str, Any], fallback: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        payload = {}
    fallback_mood = clean_text(str(fallback.get("mood") or "story_soft"))
    proposed_mood = clean_text(str(payload.get("mood") or ""))
    mood_locked = bool(fallback.get("mood_locked"))
    mood = proposed_mood or fallback_mood
    if mood not in BGM_SEARCH_PROFILES:
        mood = fallback_mood
    rejected_mood = proposed_mood if mood_locked and proposed_mood and proposed_mood != fallback_mood else ""
    if rejected_mood:
        mood = fallback_mood
    selection_payload = fallback if rejected_mood else payload
    fallback_query = clean_text(str(fallback.get("query") or "documentary instrumental music"))
    arrangement_id = clean_text(str(fallback.get("arrangement_id") or ""))
    arrangement_label = clean_text(str(fallback.get("arrangement_label") or ""))
    arrangement_query_terms = clean_text(str(fallback.get("arrangement_query_terms") or ""))
    arrangement_catalog_query = clean_text(str(fallback.get("arrangement_catalog_query") or ""))
    arrangement_tags = _text_list(fallback.get("arrangement_tags"), [], limit=6, item_limit=24)
    arrangement_instrumentation = _text_list(
        fallback.get("arrangement_instrumentation"),
        [],
        limit=5,
        item_limit=32,
    )
    query = clean_text(str(selection_payload.get("query") or fallback_query))
    query = re.sub(r"(?i)\b(douyin|tiktok|kuaishou|抖音|快手|热门神曲|爆款歌曲|版权歌)\b", " ", query)
    if bgm_candidate_is_non_music_noise({"name": query}):
        query = fallback_query
    if arrangement_query_terms and arrangement_query_terms.casefold() not in query.casefold():
        query = f"{query} {arrangement_query_terms}"
    query = clean_text(query)[:110] or "documentary instrumental music"
    tags = _text_list(
        [*arrangement_tags, *_text_list(selection_payload.get("tags"), fallback.get("tags", []), limit=8, item_limit=24)],
        [],
        limit=8,
        item_limit=24,
    )
    tags = [item for item in tags if not bgm_candidate_is_non_music_noise({"name": item})]
    avoid = _text_list(
        [
            *_text_list(payload.get("avoid"), ["popular copyrighted songs", "vocal lead", "lyrics"], limit=8, item_limit=36),
            "sound effects",
            "field recordings",
            "fan or machine noise",
            "hiss static buzzing",
        ],
        [],
        limit=12,
        item_limit=36,
    )
    bpm = selection_payload.get("bpm") if isinstance(selection_payload.get("bpm"), list) else fallback.get("bpm", [60, 100])
    bpm_values: list[int] = []
    for value in bpm[:2] if isinstance(bpm, list) else []:
        with contextlib.suppress(TypeError, ValueError):
            bpm_values.append(max(45, min(150, int(float(value)))))
    if len(bpm_values) < 2:
        fallback_bpm = fallback.get("bpm", [60, 100]) if isinstance(fallback.get("bpm"), list) else [60, 100]
        bpm_values = [int(fallback_bpm[0]), int(fallback_bpm[-1])]
    bpm_values = sorted(bpm_values[:2])
    profile = SOUND_MOOD_PROFILES.get(mood, SOUND_MOOD_PROFILES["story_soft"])
    instrumentation = _text_list(
        [
            *arrangement_instrumentation,
            *_text_list(
                selection_payload.get("instrumentation"),
                fallback.get("instrumentation", profile.get("keywords", [])),
                limit=6,
                item_limit=32,
            ),
        ],
        [],
        limit=6,
        item_limit=32,
    )
    instrumentation = [
        item
        for item in instrumentation
        if not bgm_candidate_is_non_music_noise({"name": item})
    ]
    reason = clean_text(str(selection_payload.get("reason") or fallback.get("reason") or ""))
    if bgm_candidate_is_non_music_noise({"name": reason}):
        reason = clean_text(str(fallback.get("reason") or "用纯音乐承接本期情绪，不复刻口播中描述的问题声音。"))
    return {
        "mood": mood,
        "label": SOUND_MOOD_PROFILES.get(mood, {}).get("label", mood),
        "query": query,
        "tags": tags,
        "avoid": avoid,
        "bpm": bpm_values,
        "volume": float(profile.get("volume", 0.16) or 0.16),
        "reason": reason,
        "instrumentation": instrumentation,
        "arrangement_id": arrangement_id,
        "arrangement_label": arrangement_label,
        "arrangement_query_terms": arrangement_query_terms,
        "arrangement_catalog_query": arrangement_catalog_query,
        "arrangement_tags": arrangement_tags,
        "arrangement_instrumentation": arrangement_instrumentation,
        "recent_arrangements": _text_list(fallback.get("recent_arrangements"), [], limit=4, item_limit=32),
        "mood_locked": mood_locked,
        "confidence_score": float(fallback.get("confidence_score", 0) or 0),
        "rejected_mood": rejected_mood,
        "provider": clean_text(str(payload.get("provider") or "rule-bgm-selector")),
    }


def rule_bgm_brief(project_id: int, content: str = "") -> dict[str, Any]:
    decision = bgm_theme_decision_for_project(project_id, content)
    mood = clean_text(str(decision.get("mood") or "story_soft"))
    profile = BGM_SEARCH_PROFILES.get(mood, BGM_SEARCH_PROFILES["story_soft"])
    sound_profile = SOUND_MOOD_PROFILES.get(mood, SOUND_MOOD_PROFILES["story_soft"])
    arrangement = choose_bgm_arrangement(project_id, mood)
    confidence = float(decision.get("score", 0) or 0)
    mood_locked = bool(mood != "story_soft" and confidence >= 18.0)
    return normalize_bgm_brief(
        {"provider": "rule-bgm-selector", "reason": decision.get("reason")},
        {
            "mood": mood,
            "mood_locked": mood_locked,
            "confidence_score": confidence,
            "reason": decision.get("reason"),
            "instrumentation": [
                *arrangement.get("arrangement_instrumentation", []),
                *sound_profile.get("keywords", []),
            ],
            **arrangement,
            **profile,
        },
    )


def compose_bgm_selector_messages(project: dict[str, Any], template: dict[str, Any], content: str, fallback: dict[str, Any]) -> list[dict[str, str]]:
    director = storage.read_json(visual_director_path(int(project.get("id") or 0)), {})
    allowed_moods = "|".join(SOUND_MOOD_PROFILES)
    system = f"""
你是短视频 BGM 选曲导演。你只负责给免版权/可授权音乐库的搜索词，不允许推荐抖音热歌、影视配乐、歌手歌曲或任何可能侵权的曲名。
根据本期主题、完整口播的情绪走向和频道气质，输出 JSON。主题与本期口播优先于频道固定风格：
{{"mood":"{allowed_moods}","query":"英文搜索词","tags":["英文标签"],"avoid":["避开的音乐类型"],"bpm":[最低BPM,最高BPM],"instrumentation":["建议乐器或声音材质"],"reason":"一句中文选曲理由"}}
BGM 必须给口播留空间，少人声或无人声，适合中文短视频铺底。
BGM 用音乐的旋律、节奏和配器承接情绪，不能把口播正在批评或描述的噪声、故障声、环境声直接复刻成配乐；禁止把嘶声、底噪、静电、嗡鸣、风扇、机器环境采样或普通音效写进 query、tags 和 instrumentation。
不要因为出现“风险”“科技”等一个泛词就定型；结合主冲突、证据方式、结论情绪综合判断。
如果 fallback.mood_locked 为 true，说明主题信号置信度很高，不得更换 mood；你仍可优化同类型里的乐器、能量和搜索词。
fallback.arrangement_id 是系统为本期从频道近期未使用方案中选择的配器方向。必须保留这个方向的核心乐器和节奏材质，不要重新改回频道上一期的配器。
参考最近 20 期重复监控：如果同一情绪或曲目已经过密，而当前主题有同样合适的其它声音方案，优先换乐器、节奏密度和搜索词；不能为了求新使用与主题不符的音乐。
""".strip()
    repetition: dict[str, Any] = {}
    with contextlib.suppress(Exception):
        repetition = channel_repetition_report(int(project.get("id", 0) or 0), max_projects=20)
    user = {
        "project": {"topic": project.get("topic_name"), "template": project.get("template")},
        "channel": {
            "name": template.get("brand_name") or template.get("name") or project.get("template") or "",
            "target_audience": template.get("target_audience") or "",
            "voice": template.get("channel_voice") or "",
            "style": template.get("visual_strategy") or template.get("cover_style") or "",
            "forbidden": template.get("forbidden_rules") or "",
        },
        "visual_director_sound": director.get("sound_direction") if isinstance(director, dict) else {},
        "recent_20_episode_repetition": {
            key: value
            for key, value in (repetition.get("dimensions") or {}).items()
            if key in {"bgm_mood", "bgm_track"} and isinstance(value, dict)
        },
        "fallback": fallback,
        "content_excerpt": content_without_image_prompts(content)[:2500],
    }
    return [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(user, ensure_ascii=False)}]


def ai_bgm_brief(project_id: int, content: str = "") -> dict[str, Any]:
    fallback = rule_bgm_brief(project_id, content)
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if not api_key or OpenAI is None:
        return fallback
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
    model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
    try:
        client = OpenAI(api_key=api_key, base_url=base_url, timeout=45.0)
        response = client.chat.completions.create(
            model=model,
            messages=compose_bgm_selector_messages(project, template, content or storage.get_content(project_id), fallback),
            temperature=0.25,
            max_tokens=800,
        )
        choice = response.choices[0] if getattr(response, "choices", None) else None
        raw = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
        payload = _safe_json_from_text(raw)
        if payload:
            payload["provider"] = f"deepseek-bgm-selector:{model}"
            return normalize_bgm_brief(payload, fallback)
    except (ValueError, KeyError, json.JSONDecodeError):
        return fallback
    return fallback


def bgm_meta_with_context(base: dict[str, Any], context: dict[str, Any], brief: dict[str, Any]) -> dict[str, Any]:
    return {
        **base,
        "policy_version": BGM_POLICY_VERSION,
        "selection_policy_version": BGM_SELECTION_POLICY_VERSION,
        "context_hash": context.get("context_hash"),
        "content_hash": context.get("content_hash"),
        "topic": context.get("topic"),
        "template": context.get("template"),
        "selection_fingerprint": bgm_selection_fingerprint(context, brief),
        "selector": brief,
        "mood": brief.get("mood"),
        "label": brief.get("label"),
        "reason": brief.get("reason") or context.get("reason"),
        "bpm": brief.get("bpm", []),
        "volume": brief.get("volume"),
    }


def bgm_meta_matches_context(meta: dict[str, Any], context: dict[str, Any]) -> bool:
    if not isinstance(meta, dict):
        return False
    return (
        clean_text(str(meta.get("policy_version") or "")) == BGM_POLICY_VERSION
        and clean_text(str(meta.get("selection_policy_version") or "")) == BGM_SELECTION_POLICY_VERSION
        and clean_text(str(meta.get("context_hash") or "")) == clean_text(str(context.get("context_hash") or ""))
    )


def project_bgm_status(project_id: int) -> dict[str, Any]:
    if not BGM_FEATURE_ENABLED:
        return {
            "mode": "off",
            "status": "disabled",
            "current": True,
            "needs_rematch": False,
            "manual_locked": False,
            "track_locked": False,
            "path": "",
            "source": "off",
            "label": "已移除",
            "reason": "系统已取消背景音乐，成片只保留口播音轨。",
            "volume": 0.0,
        }
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    content = storage.get_content(project_id)
    env = runtime_env()
    mode = clean_text(env.get("BGM_AUTO_MODE", "auto")).lower() or "auto"
    configured_online_provider = clean_text(env.get("BGM_ONLINE_PROVIDER", "loudly")).lower() or "loudly"
    online_provider, online_catalog_ready = resolve_online_bgm_provider(env, configured_online_provider)
    context = bgm_context_for_project(project_id, content)
    desired = rule_bgm_brief(project_id, content)
    meta = storage.read_json(project_bgm_meta_path(project_id), {})
    meta = meta if isinstance(meta, dict) else {}
    settings = project_bgm_settings(project_id)
    configured_volume = settings.get("volume")
    effective_volume = (
        float(configured_volume)
        if configured_volume is not None
        else director_bgm_volume(project_id, env)
    )
    track_locked = bool(settings.get("track_locked", False))
    project_path = find_project_bgm_path(project_id)
    template_path = find_template_bgm_path(template_key)

    base = {
        "mode": mode,
        "policy_version": BGM_POLICY_VERSION,
        "selection_policy_version": BGM_SELECTION_POLICY_VERSION,
        "context_hash": context.get("context_hash"),
        "desired_mood": desired.get("mood"),
        "desired_label": desired.get("label"),
        "desired_bpm": desired.get("bpm", []),
        "desired_reason": desired.get("reason") or context.get("reason"),
        "matched_signals": context.get("matched_signals", []),
        "volume": effective_volume,
        "track_locked": track_locked,
        "online_provider": online_provider,
        "configured_online_provider": configured_online_provider,
        "online_catalog_ready": online_catalog_ready,
    }
    if mode in {"off", "false", "0", "none", "disable", "disabled"}:
        return {
            **base,
            "status": "disabled",
            "current": True,
            "needs_rematch": False,
            "manual_locked": False,
            "path": "",
            "source": "off",
            "label": "已关闭",
            "reason": "配置中已关闭自动背景音乐",
        }

    if project_path and project_path.exists():
        source = clean_text(str(meta.get("source") or "project_manual"))
        auto_managed = source in AUTO_BGM_SOURCES
        manual_locked = not auto_managed or track_locked
        track = meta.get("track") if isinstance(meta.get("track"), dict) else {}
        non_music_noise = bool(
            auto_managed
            and source == "freesound"
            and (
                bgm_candidate_is_non_music_noise(track)
                or bgm_candidate_music_quality(track) <= 0
            )
        )
        provider_changed = auto_bgm_provider_changed(source, online_provider, online_catalog_ready)
        try:
            online_retry_after = float(meta.get("online_retry_after", 0) or 0)
        except (TypeError, ValueError):
            online_retry_after = 0.0
        online_retry_cooldown = bool(
            source == "procedural_local"
            and clean_text(str(meta.get("fallback_reason") or ""))
            and online_retry_after > storage.now_ts()
        )
        if online_retry_cooldown:
            provider_changed = False
        provider_pending = bool(
            auto_managed
            and source == "procedural_local"
            and online_provider in ONLINE_BGM_SOURCES
            and (not online_catalog_ready or online_retry_cooldown)
        )
        current = manual_locked or (
            bgm_meta_matches_context(meta, context)
            and not provider_changed
            and not non_music_noise
        )
        selector = meta.get("selector") if isinstance(meta.get("selector"), dict) else {}
        if auto_managed and not current:
            change_report = storage.read_json(storage.project_file(project_id, "content_change.json"), {})
            invalidation = change_report.get("invalidate") if isinstance(change_report, dict) and isinstance(change_report.get("invalidate"), dict) else {}
            existing_mood = clean_text(str(meta.get("mood") or selector.get("mood") or ""))
            desired_mood = clean_text(str(desired.get("mood") or context.get("desired_mood") or ""))
            policy_current = (
                clean_text(str(meta.get("policy_version") or "")) == BGM_POLICY_VERSION
                and clean_text(str(meta.get("selection_policy_version") or "")) == BGM_SELECTION_POLICY_VERSION
            )
            if (
                policy_current
                and not provider_changed
                and not invalidation.get("bgm")
                and not non_music_noise
                and existing_mood
                and existing_mood == desired_mood
            ):
                migrated_brief = {**desired, **selector, "mood": existing_mood}
                meta = bgm_meta_with_context(meta, context, migrated_brief)
                storage.write_json(project_bgm_meta_path(project_id), meta)
                selector = meta.get("selector") if isinstance(meta.get("selector"), dict) else selector
                current = True
        return {
            **base,
            "status": "current" if current else "stale",
            "current": current,
            "needs_rematch": not current,
            "manual_locked": manual_locked,
            "path": project_path.as_posix(),
            "source": source,
            "mood": clean_text(str(meta.get("mood") or selector.get("mood") or "")),
            "label": clean_text(str(meta.get("label") or selector.get("label") or ("人工音乐" if manual_locked else "待重新匹配"))),
            "bpm": meta.get("bpm") or selector.get("bpm") or [],
            "reason": (
                clean_text(str(meta.get("reason") or selector.get("reason") or "项目目录中的音乐由人工锁定"))
                if current
                else (
                    "当前自动素材是环境噪声或音效，不是可用的背景音乐，需要重新匹配。"
                    if non_music_noise
                    else clean_text(str(desired.get("reason") or context.get("reason") or "主题或文案已变化，需要重新匹配"))
                )
            ),
            "provider": clean_text(str(selector.get("provider") or "")),
            "track": track,
            "non_music_noise": non_music_noise,
            "audio_vocal_audit": meta.get("audio_vocal_audit") if isinstance(meta.get("audio_vocal_audit"), dict) else {},
            "rotation_reason": clean_text(str(meta.get("rotation_reason") or "")),
            "fallback_reason": clean_text(str(meta.get("fallback_reason") or "")),
            "provider_changed": provider_changed,
            "provider_pending": provider_pending,
            "online_retry_after": online_retry_after,
            "online_retry_cooldown": online_retry_cooldown,
            "local_variant": int(meta.get("local_variant", 0) or 0),
            "arrangement_id": clean_text(str(selector.get("arrangement_id") or desired.get("arrangement_id") or "")),
            "arrangement_label": clean_text(str(selector.get("arrangement_label") or desired.get("arrangement_label") or "")),
            "updated_at": float(meta.get("generated_at", 0) or project_path.stat().st_mtime),
        }

    if mode in {"template", "channel", "fixed"}:
        if template_path and template_path.exists():
            return {
                **base,
                "status": "current",
                "current": True,
                "needs_rematch": False,
                "manual_locked": True,
                "path": template_path.as_posix(),
                "source": "template_fixed",
                "label": "频道固定曲",
                "reason": "当前配置选择始终使用频道目录中的固定 BGM",
                "updated_at": template_path.stat().st_mtime,
            }
        return {
            **base,
            "status": "missing",
            "current": False,
            "needs_rematch": False,
            "manual_locked": True,
            "path": "",
            "source": "template_missing",
            "label": "频道固定曲缺失",
            "reason": "频道固定模式下没有找到 bgm.mp3 / bgm.wav",
        }

    return {
        **base,
        "status": "pending",
        "current": False,
        "needs_rematch": True,
        "manual_locked": False,
        "path": "",
        "source": "theme_auto",
        "mood": desired.get("mood"),
        "label": desired.get("label"),
        "bpm": desired.get("bpm", []),
        "reason": desired.get("reason") or context.get("reason"),
        "rotation_reason": "尚未选曲，将避开当前曲和频道近期曲目",
        "provider": desired.get("provider"),
        "arrangement_id": desired.get("arrangement_id"),
        "arrangement_label": desired.get("arrangement_label"),
    }


def archive_existing_project_bgm(project_id: int) -> list[str]:
    history_dir = storage.project_file(project_id, "bgm_history")
    storage.ensure_dir(history_dir)
    stamp = storage.now_ms()
    archived: list[str] = []
    for filename in BGM_FILENAMES:
        source = storage.project_file(project_id, filename)
        if not source.exists():
            continue
        target = history_dir / f"{source.stem}-{stamp}{source.suffix.lower()}"
        shutil.copy2(source, target)
        archived.append(target.as_posix())
    meta_path = project_bgm_meta_path(project_id)
    if meta_path.exists():
        target = history_dir / f"bgm_meta-{stamp}.json"
        shutil.copy2(meta_path, target)
        archived.append(target.as_posix())
    history_groups: dict[str, list[Path]] = {}
    for path in history_dir.glob("bgm*-*.*"):
        match = re.search(r"-(\d+)\.[^.]+$", path.name)
        if match:
            history_groups.setdefault(match.group(1), []).append(path)
    for old_stamp in sorted(history_groups, key=int, reverse=True)[8:]:
        for path in history_groups[old_stamp]:
            path.unlink(missing_ok=True)
    return archived


def allowed_bgm_license(text: str) -> bool:
    lowered = clean_text(text).lower()
    if not lowered:
        return False
    if any(token in lowered for token in ("noncommercial", "sampling+", "sampling plus", "by-nc", "nc")):
        return False
    return (
        "creative commons 0" in lowered
        or "cc0" in lowered
        or "creativecommons.org/publicdomain/zero/" in lowered
    )


def bgm_track_id_from_meta(meta: dict[str, Any], provider: str) -> str:
    if not isinstance(meta, dict) or clean_text(str(meta.get("source") or "")).lower() != clean_text(provider).lower():
        return ""
    track = meta.get("track") if isinstance(meta.get("track"), dict) else {}
    return clean_text(str(track.get("id") or ""))


def bgm_track_family_signature(item: dict[str, Any]) -> str:
    """Group numbered variants and near-identical catalog tracks into one family."""
    name = clean_text(str(item.get("name") or item.get("title") or "")).casefold()
    username = clean_text(str(item.get("username") or item.get("artist_name") or "")).casefold()
    name = re.sub(r"\.(mp3|wav|m4a|aac|flac)\b", " ", name)
    name = re.sub(r"\s*[\(\[].*?[\)\]]", " ", name)
    name = re.sub(r"\b(?:loop|version|ver|variant|take|mix|master|edit|track|part)\b", " ", name)
    name = re.sub(r"\b(?:no\.?\s*)?\d+\b", " ", name)
    name = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", " ", name)
    normalized = " ".join(token for token in name.split() if len(token) > 1)
    if not normalized:
        normalized = clean_text(str(item.get("id") or "")).casefold()
    source = f"{username}:{normalized}" if username else normalized
    return hashlib.sha256(source.encode("utf-8", errors="ignore")).hexdigest()[:16] if source else ""


def bgm_track_family_from_meta(meta: dict[str, Any], provider: str) -> str:
    if not isinstance(meta, dict) or clean_text(str(meta.get("source") or "")).lower() != clean_text(provider).lower():
        return ""
    track = meta.get("track") if isinstance(meta.get("track"), dict) else {}
    return bgm_track_family_signature(track) or clean_text(str(track.get("family_signature") or ""))


def recent_bgm_track_ids(project_id: int, provider: str, limit: int = 20) -> set[str]:
    """Return the current, archived, and recent channel track IDs for rotation."""
    ordered: list[str] = []
    try:
        recent_metas = recent_channel_bgm_metas(project_id, limit=max(20, limit * 2))
    except (FileNotFoundError, OSError):
        recent_metas = []
    for meta in recent_metas:
        track_id = bgm_track_id_from_meta(meta, provider)
        if track_id and track_id not in ordered:
            ordered.append(track_id)
        if len(ordered) >= max(1, int(limit or 20)):
            break
    return set(ordered)


def recent_bgm_track_families(project_id: int, provider: str, limit: int = 20) -> set[str]:
    ordered: list[str] = []
    try:
        recent_metas = recent_channel_bgm_metas(project_id, limit=max(20, limit * 2))
    except (FileNotFoundError, OSError):
        recent_metas = []
    for meta in recent_metas:
        signature = bgm_track_family_from_meta(meta, provider)
        if signature and signature not in ordered:
            ordered.append(signature)
        if len(ordered) >= max(1, int(limit or 20)):
            break
    return set(ordered)


def prioritize_fresh_bgm_candidates(ranked: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Prefer any acceptable fresh track over replaying a recent channel track."""
    fresh = [item for item in ranked if float(item.get("recent_repeat_penalty", 0) or 0) <= 0]
    repeated = [item for item in ranked if float(item.get("recent_repeat_penalty", 0) or 0) > 0]
    return [*fresh, *repeated] if fresh else ranked


def recent_freesound_track_ids(project_id: int, limit: int = 20) -> set[str]:
    return recent_bgm_track_ids(project_id, "freesound", limit)


def rank_freesound_bgm_candidates(
    results: list[dict[str, Any]],
    brief: dict[str, Any],
    recent_track_ids: set[str] | None = None,
    recent_family_signatures: set[str] | None = None,
) -> list[dict[str, Any]]:
    recent = {clean_text(str(item)) for item in (recent_track_ids or set()) if clean_text(str(item))}
    recent_families = {
        clean_text(str(item))
        for item in (recent_family_signatures or set())
        if clean_text(str(item))
    }
    desired_tokens = {
        token.lower()
        for token in re.findall(r"[A-Za-z0-9_-]{3,}", " ".join([
            clean_text(str(brief.get("query") or "")),
            " ".join(str(item) for item in brief.get("tags", []) if clean_text(str(item))),
        ]))
        if token.lower() not in {"music", "background", "short", "video", "sound", "audio"}
    }
    avoid_phrases = [
        clean_text(str(item)).casefold()
        for item in brief.get("avoid", [])
        if clean_text(str(item))
    ]
    mood_negative_tokens = {
        "business_pulse": {"creepy", "dark", "eerie", "haunt", "horror", "ominous"},
        "practical_upbeat": {"creepy", "dark", "eerie", "haunt", "horror", "ominous", "sad"},
        "warm_warning": {"aggressive", "creepy", "horror", "ominous", "trailer"},
        "science_curiosity": {"aggressive", "creepy", "horror", "ominous"},
        "story_soft": {"aggressive", "horror", "trailer"},
    }.get(clean_text(str(brief.get("mood") or "")), set())
    eligible: list[dict[str, Any]] = []
    for item in results:
        if not isinstance(item, dict) or not allowed_bgm_license(str(item.get("license") or "")):
            continue
        music_quality = bgm_candidate_music_quality(item)
        if bgm_candidate_has_vocals(item) or bgm_candidate_is_non_music_noise(item) or music_quality <= 0:
            continue
        previews = item.get("previews") if isinstance(item.get("previews"), dict) else {}
        preview_url = clean_text(str(previews.get("preview-hq-mp3") or previews.get("preview-lq-mp3") or ""))
        if not preview_url:
            continue
        eligible.append({**item, "preview_url": preview_url, "music_quality": music_quality})
    if not eligible:
        return []

    max_search_score = max(float(item.get("score", 0) or 0) for item in eligible) or 1.0
    max_download_log = max(math.log1p(max(0, int(item.get("num_downloads", 0) or 0))) for item in eligible) or 1.0
    ranked: list[dict[str, Any]] = []
    for item in eligible:
        haystack = " ".join([
            clean_text(str(item.get("name") or "")),
            " ".join(str(tag) for tag in item.get("tags", []) if clean_text(str(tag))),
        ]).lower()
        overlap = len([token for token in desired_tokens if token in haystack]) / max(1, len(desired_tokens))
        relevance = max(0.0, float(item.get("score", 0) or 0)) / max_search_score
        popularity = math.log1p(max(0, int(item.get("num_downloads", 0) or 0))) / max_download_log
        rating = max(0.0, min(1.0, float(item.get("avg_rating", 0) or 0) / 5.0))
        rating_confidence = min(1.0, math.log1p(max(0, int(item.get("num_ratings", 0) or 0))) / math.log(21))
        try:
            query_priority = max(0, int(item.get("query_priority", 2) or 0))
        except (TypeError, ValueError):
            query_priority = 2
        query_priority_score = max(0.2, 1.0 - query_priority * 0.18)
        avoid_hits = 0
        for phrase in avoid_phrases:
            phrase_tokens = set(re.findall(r"[a-z0-9]+", phrase))
            if phrase_tokens and phrase_tokens <= set(re.findall(r"[a-z0-9]+", haystack)):
                avoid_hits += 1
        avoid_penalty = min(0.42, avoid_hits * 0.18)
        mood_mismatch_penalty = 0.34 if mood_negative_tokens & set(re.findall(r"[a-z0-9]+", haystack)) else 0.0
        off_theme_penalty = 0.22 if overlap <= 0 and query_priority >= 2 else 0.0
        track_id = clean_text(str(item.get("id") or ""))
        family_signature = bgm_track_family_signature(item)
        track_repeat_penalty = 0.58 if track_id and track_id in recent else 0.0
        family_repeat_penalty = 0.36 if family_signature and family_signature in recent_families else 0.0
        repeat_penalty = track_repeat_penalty + family_repeat_penalty
        music_quality = float(item.get("music_quality", 0.55) or 0.55)
        selection_score = (
            relevance * 0.20
            + overlap * 0.28
            + popularity * 0.12
            + rating * rating_confidence * 0.05
            + music_quality * 0.20
            + query_priority_score * 0.15
            - repeat_penalty
            - avoid_penalty
            - mood_mismatch_penalty
            - off_theme_penalty
        )
        ranked.append(
            {
                **item,
                "selection_score": round(selection_score, 4),
                "theme_overlap": round(overlap, 4),
                "popularity_score": round(popularity, 4),
                "recent_repeat_penalty": repeat_penalty,
                "track_repeat_penalty": track_repeat_penalty,
                "family_repeat_penalty": family_repeat_penalty,
                "family_signature": family_signature,
                "query_priority_score": round(query_priority_score, 4),
                "avoid_penalty": round(avoid_penalty, 4),
                "mood_mismatch_penalty": round(mood_mismatch_penalty, 4),
                "off_theme_penalty": round(off_theme_penalty, 4),
            }
        )
    ordered = sorted(ranked, key=lambda item: float(item.get("selection_score", 0) or 0), reverse=True)
    return prioritize_fresh_bgm_candidates(ordered)


def bgm_candidate_has_vocals(item: dict[str, Any]) -> bool:
    """Reject catalog tracks whose metadata indicates speech, singing, or vocals."""
    haystack = " ".join(
        [
            clean_text(str(item.get("name") or "")),
            " ".join(str(tag) for tag in item.get("tags", []) if clean_text(str(tag))),
        ]
    ).casefold()
    tokens = set(re.findall(r"[a-z0-9]+", haystack))
    vocal_tokens = {
        "acapella",
        "breath",
        "breathing",
        "chant",
        "child",
        "choir",
        "conversation",
        "crowd",
        "dialogue",
        "female",
        "girl",
        "human",
        "interview",
        "lyrics",
        "male",
        "moan",
        "narration",
        "podcast",
        "rap",
        "scream",
        "screaming",
        "singing",
        "song",
        "speech",
        "spoken",
        "talk",
        "talking",
        "voice",
        "voiceover",
        "vocal",
        "vocals",
        "whisper",
        "whispering",
        "woman",
    }
    if tokens & vocal_tokens:
        return True
    return any(marker in haystack for marker in ("人声", "女声", "男声", "对白", "旁白", "演唱", "歌词"))


def bgm_candidate_music_quality(item: dict[str, Any]) -> float:
    """Reject short SFX and score complete, usable instrumental beds."""
    name = clean_text(str(item.get("name") or item.get("title") or "")).casefold()
    tags = " ".join(str(tag) for tag in item.get("tags", []) if clean_text(str(tag))).casefold()
    haystack = f"{name} {tags}"
    try:
        duration = float(item.get("duration", 0) or 0)
    except (TypeError, ValueError):
        duration = 0.0

    title_reject_markers = (
        " sfx",
        "sound effect",
        "audio logo",
        "background room tone",
        "cinematic impact",
        "atmospheric element",
        "field recording",
        "interior sound",
        "muffled music",
        "transition fx",
        "trailer hit",
        "climax intro",
        "street music",
        "stinger",
    )
    padded_name = f" {name}"
    if any(marker in padded_name for marker in title_reject_markers):
        return 0.0
    if duration and duration < 45.0:
        return 0.0

    strong_music_tokens = {
        "instrumental",
        "music",
        "soundtrack",
        "underscore",
        "composition",
        "orchestral",
        "piano",
        "guitar",
        "marimba",
        "melody",
    }
    supporting_music_tokens = {
        "beat",
        "cinematic",
        "documentary",
        "electronic",
        "lofi",
        "pulse",
        "rhythm",
        "score",
        "strings",
        "synth",
        "synthesizer",
        "loop",
    }
    tokens = set(re.findall(r"[a-z0-9]+", haystack))
    if {"field", "recording"} <= tokens and "instrumental" not in tokens:
        return 0.0
    if tokens & {"footstep", "footsteps", "roomtone"}:
        return 0.0
    strong_count = len(tokens & strong_music_tokens)
    support_count = len(tokens & supporting_music_tokens)
    if duration <= 0:
        return 0.72 if strong_count else 0.55
    if strong_count:
        duration_bonus = min(0.12, max(0.0, duration - 60.0) / 600.0)
        return min(1.0, 0.78 + min(0.10, strong_count * 0.04) + duration_bonus)
    if support_count >= 3 and duration >= 60.0:
        return 0.66
    if support_count >= 2 and duration >= 60.0:
        return 0.58
    return 0.0


def bgm_candidate_is_non_music_noise(item: dict[str, Any]) -> bool:
    """Reject ambience and sound effects that a catalog search mislabeled as BGM."""
    haystack = " ".join(
        [
            clean_text(str(item.get("name") or item.get("title") or "")),
            " ".join(str(tag) for tag in item.get("tags", []) if clean_text(str(tag))),
        ]
    ).casefold()
    tokens = set(re.findall(r"[a-z0-9]+", haystack))
    music_tokens = {
        "beat",
        "cinematic",
        "composition",
        "electronic",
        "instrumental",
        "loop",
        "melody",
        "music",
        "musical",
        "orchestral",
        "piano",
        "rhythm",
        "score",
        "soundtrack",
        "synth",
        "synthesizer",
        "underscore",
    }
    noise_tokens = {
        "airconditioner",
        "ambiance",
        "ambience",
        "appliance",
        "buzz",
        "buzzing",
        "engine",
        "factory",
        "fan",
        "fans",
        "fieldrecording",
        "hum",
        "humming",
        "machine",
        "machinery",
        "mechanical",
        "noise",
        "roomtone",
        "static",
        "ventilation",
    }
    phrase_markers = (
        "air conditioner",
        "background noise",
        "brown noise",
        "field recording",
        "pink noise",
        "room tone",
        "sound effect",
        "white noise",
        "底噪",
        "白噪",
        "嗡鸣",
        "嘶声",
        "风扇噪声",
        "机器噪声",
        "环境采样",
    )
    has_music_evidence = bool(tokens & music_tokens)
    has_noise_evidence = bool(tokens & noise_tokens) or any(marker in haystack for marker in phrase_markers)
    return has_noise_evidence and not has_music_evidence


def freesound_query_candidates(brief: dict[str, Any]) -> list[str]:
    full_query = clean_text(str(brief.get("query") or "documentary background music"))
    tags = [
        token.lower()
        for token in re.findall(
            r"[A-Za-z0-9_-]{3,}",
            " ".join(str(item) for item in brief.get("tags", []) if clean_text(str(item))),
        )
        if token.lower() not in {"music", "background", "short", "video", "sound", "audio"}
    ]
    mood_queries = {
        "privacy_investigation": "investigation music",
        "tech_suspense": "suspense music",
        "urgent_warning": "tension music",
        "warm_warning": "piano music",
        "business_pulse": "corporate music",
        "science_curiosity": "documentary music",
        "practical_upbeat": "corporate music",
        "story_soft": "emotional music",
    }
    arrangement_tags = _text_list(brief.get("arrangement_tags"), tags, limit=4, item_limit=24)
    arrangement_query = clean_text(str(brief.get("arrangement_catalog_query") or ""))
    if not arrangement_query and arrangement_tags:
        arrangement_query = f"{arrangement_tags[0]} music"
    raw_candidates = [
        full_query,
        mood_queries.get(clean_text(str(brief.get("mood") or "")), "documentary music"),
        arrangement_query,
        "documentary music",
        "instrumental music",
    ]
    candidates: list[str] = []
    for item in raw_candidates:
        query = clean_text(item)
        if query and query.lower() not in {existing.lower() for existing in candidates}:
            candidates.append(query)
    return candidates


def bgm_asr_vocal_evidence(utterances: list[dict[str, Any]]) -> dict[str, Any]:
    """Turn raw ASR output into conservative, explainable vocal evidence."""
    ignored = {"music", "background music", "instrumental", "纯音乐", "音乐"}
    meaningful: list[dict[str, Any]] = []
    for item in utterances:
        if not isinstance(item, dict):
            continue
        text = clean_text(str(item.get("text") or "")).strip("♪♫♬♩[]()（） ")
        compact = re.sub(r"[^A-Za-z0-9\u4e00-\u9fff]+", "", text)
        if not compact or text.casefold() in ignored:
            continue
        chinese_count = len(re.findall(r"[\u4e00-\u9fff]", text))
        latin_words = re.findall(r"[A-Za-z0-9]+", text)
        if chinese_count < 2 and len(latin_words) < 2 and len(compact) < 4:
            continue
        try:
            start_ms = max(0, int(item.get("start_ms", 0) or 0))
            end_ms = max(start_ms, int(item.get("end_ms", start_ms) or start_ms))
        except (TypeError, ValueError):
            start_ms = 0
            end_ms = 0
        meaningful.append({"text": text, "start_ms": start_ms, "end_ms": end_ms})

    transcript = clean_text(" ".join(item["text"] for item in meaningful))
    symbol_count = len(re.findall(r"[A-Za-z0-9\u4e00-\u9fff]", transcript))
    speech_ms = sum(max(0, item["end_ms"] - item["start_ms"]) for item in meaningful)
    has_vocals = bool(meaningful and (symbol_count >= 6 or speech_ms >= 900))
    return {
        "has_vocals": has_vocals,
        "utterance_count": len(meaningful),
        "speech_ms": speech_ms,
        "recognized_symbol_count": symbol_count,
        "transcript_excerpt": transcript[:120],
    }


def audit_bgm_audio_for_vocals(audio_path: Path, env: dict[str, str] | None = None) -> dict[str, Any]:
    """Inspect downloaded music with ASR and report whether speech is audible."""
    resolved_env = dict(env or runtime_env())
    mode = clean_text(str(resolved_env.get("BGM_VOCAL_AUDIT", "auto") or "auto")).lower()
    if mode in {"off", "false", "0", "disabled", "none"}:
        return {
            "status": "skipped",
            "checked": False,
            "has_vocals": False,
            "reason": "实际人声检测已关闭。",
        }
    has_credentials = bool(
        (resolved_env.get("VOLC_ASR_APP_KEY") and resolved_env.get("VOLC_ASR_ACCESS_KEY"))
        or (resolved_env.get("VOLC_TTS_APP_KEY") and resolved_env.get("VOLC_TTS_ACCESS_KEY"))
    )
    if not has_credentials:
        return {
            "status": "unavailable",
            "checked": False,
            "has_vocals": False,
            "reason": "未配置可用的 ASR 密钥，仅完成曲库标签过滤。",
        }

    audit_srt = audio_path.with_name(f".{audio_path.stem}.vocal-audit-{storage.now_ms()}.srt")
    try:
        result = run_original_bridge(
            "asr",
            {
                "audio_path": str(audio_path),
                "srt_output": str(audit_srt),
                "dialogue_lines": [],
            },
            resolved_env,
            configured_timeout_seconds(
                resolved_env,
                "BGM_VOCAL_AUDIT_TIMEOUT_SECONDS",
                240,
                60,
                900,
            ),
        )
        utterances = result.get("utterances", []) if isinstance(result, dict) else []
        evidence = bgm_asr_vocal_evidence(utterances if isinstance(utterances, list) else [])
        rejected = bool(evidence.get("has_vocals"))
        return {
            "status": "rejected" if rejected else "passed",
            "checked": True,
            **evidence,
            "reason": (
                "识别到可辨对白或唱词，已淘汰这首候选。"
                if rejected
                else "实际音频未识别到可辨人声。"
            ),
        }
    except Exception as exc:
        return {
            "status": "inconclusive",
            "checked": False,
            "has_vocals": False,
            "reason": f"实际人声检测未完成：{user_facing_error(exc, 160)}",
        }
    finally:
        audit_srt.unlink(missing_ok=True)


def freesound_search_bgm(
    project_id: int,
    brief: dict[str, Any],
    api_key: str,
    target_duration: float,
    status_callback: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    queries = freesound_query_candidates(brief)
    if not queries:
        raise RuntimeError("BGM 搜索词为空。")
    results_by_id: dict[str, dict[str, Any]] = {}
    used_queries: list[str] = []
    for query_index, query in enumerate(queries):
        params = {
            "query": query,
            "filter": 'duration:[45 TO 600] license:"Creative Commons 0"',
            "sort": "score",
            "page_size": "50",
            "fields": "id,name,url,username,license,duration,tags,previews,score,avg_rating,num_ratings,num_downloads",
        }
        url = "https://freesound.org/apiv2/search/text/?" + urllib.parse.urlencode(params)
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "short-video-studio/1.0", "Authorization": f"Token {api_key}"},
        )
        with urllib.request.urlopen(request, timeout=30) as response:
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
        used_queries.append(query)
        rows = payload.get("results") if isinstance(payload, dict) else []
        for item in rows if isinstance(rows, list) else []:
            if not isinstance(item, dict):
                continue
            item_id = clean_text(str(item.get("id") or ""))
            if item_id:
                existing = results_by_id.get(item_id, {})
                matched_queries = list(existing.get("matched_queries", [])) if isinstance(existing, dict) else []
                if query not in matched_queries:
                    matched_queries.append(query)
                results_by_id[item_id] = {
                    **existing,
                    **item,
                    "query_priority": min(int(existing.get("query_priority", query_index) or 0), query_index)
                    if existing
                    else query_index,
                    "matched_queries": matched_queries,
                }
    results = list(results_by_id.values())
    recent_track_ids = recent_freesound_track_ids(project_id)
    recent_family_signatures = recent_bgm_track_families(project_id, "freesound")
    ranked = rank_freesound_bgm_candidates(
        results,
        brief,
        recent_track_ids,
        recent_family_signatures,
    )
    if not ranked:
        raise RuntimeError(f"Freesound 没有找到 CC0 且带可下载预览的 BGM；已尝试：{' / '.join(used_queries)}。")

    temp_path = storage.project_file(project_id, "bgm.freesound-preview.mp3")
    target_path = storage.project_file(project_id, "bgm.mp3")
    storage.ensure_dir(temp_path.parent)
    env = runtime_env()
    try:
        max_candidates = int(float(env.get("BGM_VOCAL_AUDIT_MAX_CANDIDATES", 5) or 5))
    except (TypeError, ValueError):
        max_candidates = 5
    max_candidates = max(1, min(max_candidates, 10))
    selected: dict[str, Any] | None = None
    selected_audit: dict[str, Any] = {}
    rejected_candidates: list[dict[str, Any]] = []
    for candidate_index, candidate in enumerate(ranked[:max_candidates], start=1):
        candidate_id = clean_text(str(candidate.get("id") or ""))
        try:
            if status_callback:
                status_callback(
                    f"[bgm] 正在试听候选 {candidate_index}/{min(len(ranked), max_candidates)}："
                    f"{clean_text(str(candidate.get('name') or candidate_id or '未命名曲目'))}"
                )
            audio_request = urllib.request.Request(candidate["preview_url"], headers={"User-Agent": "short-video-studio/1.0"})
            with urllib.request.urlopen(audio_request, timeout=60) as response:
                data = response.read(30 * 1024 * 1024)
            if not data:
                raise RuntimeError("预览音频下载为空")
            temp_path.write_bytes(data)
            if safe_probe_duration(temp_path) <= 0:
                raise RuntimeError("下载结果不是可用音频")
            audit = audit_bgm_audio_for_vocals(temp_path, env)
            if audit.get("has_vocals"):
                if status_callback:
                    status_callback(f"[bgm] 候选 {candidate_index} 检测到可辨人声，已自动换下一首")
                rejected_candidates.append(
                    {
                        "id": candidate_id,
                        "name": clean_text(str(candidate.get("name") or "")),
                        "reason": clean_text(str(audit.get("reason") or "检测到人声")),
                    }
                )
                continue
            selected = candidate
            selected_audit = audit
            shutil.copyfile(temp_path, target_path)
            break
        except Exception as exc:
            rejected_candidates.append(
                {
                    "id": candidate_id,
                    "name": clean_text(str(candidate.get("name") or "")),
                    "reason": user_facing_error(exc, 160),
                }
            )
    temp_path.unlink(missing_ok=True)
    if not selected or not target_path.exists():
        raise RuntimeError(
            f"Freesound 前 {min(len(ranked), max_candidates)} 首候选均未通过下载或人声检查，请换一个主题音乐来源。"
        )
    return {
        "path": target_path,
        "audio_vocal_audit": selected_audit,
        "track": {
            "id": selected.get("id"),
            "name": selected.get("name"),
            "url": selected.get("url"),
            "username": selected.get("username"),
            "license": selected.get("license"),
            "duration": selected.get("duration"),
            "tags": selected.get("tags", []),
            "num_downloads": selected.get("num_downloads", 0),
            "avg_rating": selected.get("avg_rating", 0),
            "num_ratings": selected.get("num_ratings", 0),
            "selection_score": selected.get("selection_score", 0),
            "theme_overlap": selected.get("theme_overlap", 0),
            "popularity_score": selected.get("popularity_score", 0),
            "music_quality": selected.get("music_quality", 0),
            "family_signature": selected.get("family_signature", ""),
            "matched_queries": selected.get("matched_queries", []),
            "avoid_penalty": selected.get("avoid_penalty", 0),
            "mood_mismatch_penalty": selected.get("mood_mismatch_penalty", 0),
            "arrangement_id": brief.get("arrangement_id", ""),
            "arrangement_label": brief.get("arrangement_label", ""),
            "search_queries": used_queries,
            "audio_vocal_audit": selected_audit,
            "rejected_candidate_count": len(rejected_candidates),
            "rejected_candidates": rejected_candidates,
            "rotation_reason": (
                "已避开当前曲、同系列曲和频道近期配器"
                if (
                    (recent_track_ids and clean_text(str(selected.get("id") or "")) not in recent_track_ids)
                    or (
                        recent_family_signatures
                        and clean_text(str(selected.get("family_signature") or "")) not in recent_family_signatures
                    )
                )
                else "曲库内暂无新的合格曲目，沿用最匹配候选"
            ),
        },
    }


