def loudly_tag_names(item: dict[str, Any], *fields: str) -> list[str]:
    names: list[str] = []
    for field in fields:
        rows = item.get(field) if isinstance(item.get(field), list) else []
        for row in rows:
            value = row.get("name") if isinstance(row, dict) else row
            normalized = clean_text(str(value or ""))
            if normalized:
                names.append(normalized)
    return list(dict.fromkeys(names))


def recent_loudly_track_ids(project_id: int, limit: int = 20) -> set[str]:
    return recent_bgm_track_ids(project_id, "loudly", limit)


def rank_loudly_bgm_candidates(
    results: list[dict[str, Any]],
    brief: dict[str, Any],
    recent_track_ids: set[str] | None = None,
    target_duration: float = 0.0,
) -> list[dict[str, Any]]:
    recent = {clean_text(str(item)) for item in (recent_track_ids or set()) if clean_text(str(item))}
    mood = clean_text(str(brief.get("mood") or "story_soft"))
    profile = LOUDLY_THEME_PROFILES.get(mood, LOUDLY_THEME_PROFILES["story_soft"])
    desired_moods = {value.casefold() for value in profile["moods"]}
    desired_genres = {value.casefold() for value in profile["genres"]}
    bpm_range = brief.get("bpm") if isinstance(brief.get("bpm"), list) else []
    try:
        bpm_low = float(bpm_range[0]) if bpm_range else 60.0
        bpm_high = float(bpm_range[-1]) if bpm_range else 120.0
    except (TypeError, ValueError):
        bpm_low, bpm_high = 60.0, 120.0
    target = max(75.0, min(float(target_duration or 150.0), 420.0))
    ranked: list[dict[str, Any]] = []
    for item in results:
        if not isinstance(item, dict) or bool(item.get("has_vocal")):
            continue
        audio_url = clean_text(str(item.get("music_file_path") or ""))
        if not audio_url:
            continue
        try:
            raw_duration = float(item.get("duration", 0) or 0)
        except (TypeError, ValueError):
            raw_duration = 0.0
        duration = raw_duration / 1000.0 if raw_duration > 10000 else raw_duration
        if duration < 60.0 or duration > 900.0:
            continue
        moods = loudly_tag_names(item, "moods")
        genres = loudly_tag_names(item, "genres", "secondary_genres")
        energies = loudly_tag_names(item, "energies")
        mood_overlap = len(desired_moods & {value.casefold() for value in moods}) / max(1, len(desired_moods))
        genre_overlap = len(desired_genres & {value.casefold() for value in genres}) / max(1, len(desired_genres))
        duration_fit = min(1.0, duration / target) if duration < target else max(0.72, 1.0 - (duration - target) / 1200.0)
        try:
            bpm = float(item.get("tempo_bpm", 0) or 0)
        except (TypeError, ValueError):
            bpm = 0.0
        if bpm <= 0:
            bpm_fit = 0.55
        elif bpm_low <= bpm <= bpm_high:
            bpm_fit = 1.0
        else:
            bpm_fit = max(0.0, 1.0 - min(abs(bpm - bpm_low), abs(bpm - bpm_high)) / 60.0)
        track_id = clean_text(str(item.get("id") or ""))
        repeat_penalty = 0.85 if track_id and track_id in recent else 0.0
        selection_score = mood_overlap * 0.34 + genre_overlap * 0.26 + duration_fit * 0.22 + bpm_fit * 0.18 - repeat_penalty
        ranked.append(
            {
                **item,
                "duration_sec": duration,
                "catalog_moods": moods,
                "catalog_genres": genres,
                "catalog_energies": energies,
                "selection_score": round(selection_score, 4),
                "mood_score": round(mood_overlap, 4),
                "genre_score": round(genre_overlap, 4),
                "duration_fit": round(duration_fit, 4),
                "bpm_fit": round(bpm_fit, 4),
                "recent_repeat_penalty": repeat_penalty,
            }
        )
    ordered = sorted(ranked, key=lambda item: float(item.get("selection_score", 0) or 0), reverse=True)
    return prioritize_fresh_bgm_candidates(ordered)


def loudly_match_tag(preferred: list[str], available: list[str]) -> str:
    lookup = {clean_text(value).casefold(): clean_text(value) for value in available if clean_text(value)}
    for value in preferred:
        if value.casefold() in lookup:
            return lookup[value.casefold()]
    for value in preferred:
        tokens = set(re.findall(r"[a-z0-9]+", value.casefold()))
        for key, original in lookup.items():
            if tokens and tokens & set(re.findall(r"[a-z0-9]+", key)):
                return original
    return ""


def loudly_search_bgm(project_id: int, brief: dict[str, Any], api_key: str, target_duration: float) -> dict[str, Any]:
    headers = {"User-Agent": "short-video-studio/1.0", "Accept": "application/json", "API-KEY": api_key}
    tags_request = urllib.request.Request("https://soundtracks.loudly.com/api/songs/tags", headers=headers)
    with urllib.request.urlopen(tags_request, timeout=30) as response:
        tags_payload = json.loads(response.read().decode("utf-8", errors="replace"))
    available_moods = tags_payload.get("mood") if isinstance(tags_payload, dict) and isinstance(tags_payload.get("mood"), list) else []
    available_genres = tags_payload.get("genre") if isinstance(tags_payload, dict) and isinstance(tags_payload.get("genre"), list) else []
    mood_key = clean_text(str(brief.get("mood") or "story_soft"))
    profile = LOUDLY_THEME_PROFILES.get(mood_key, LOUDLY_THEME_PROFILES["story_soft"])
    selected_mood = loudly_match_tag(profile["moods"], [str(item) for item in available_moods])
    selected_genre = loudly_match_tag(profile["genres"], [str(item) for item in available_genres])

    query_candidates = [
        {"mood": selected_mood, "genre": selected_genre},
        {"mood": selected_mood},
        {"genre": selected_genre},
        {},
    ]
    results_by_id: dict[str, dict[str, Any]] = {}
    used_queries: list[dict[str, str]] = []
    for query in query_candidates:
        normalized_query = {key: value for key, value in query.items() if clean_text(str(value))}
        if normalized_query in used_queries:
            continue
        params = {**normalized_query, "limit": "100", "page": "1"}
        url = "https://soundtracks.loudly.com/api/songs?" + urllib.parse.urlencode(params)
        request = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(request, timeout=35) as response:
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
        used_queries.append(normalized_query)
        rows = payload.get("items") if isinstance(payload, dict) and isinstance(payload.get("items"), list) else []
        for item in rows:
            if not isinstance(item, dict):
                continue
            track_id = clean_text(str(item.get("id") or ""))
            if track_id:
                results_by_id[track_id] = item
        if len(results_by_id) >= 20:
            break

    recent_track_ids = recent_loudly_track_ids(project_id)
    ranked = rank_loudly_bgm_candidates(
        list(results_by_id.values()), brief, recent_track_ids, target_duration
    )
    selected = ranked[0] if ranked else None
    if not selected:
        raise RuntimeError("Loudly 没有找到可下载、无人声且与当前主题匹配的完整配乐。")

    temp_path = storage.project_file(project_id, "bgm.loudly.mp3")
    target_path = storage.project_file(project_id, "bgm.mp3")
    audio_request = urllib.request.Request(clean_text(str(selected.get("music_file_path") or "")), headers=headers)
    with urllib.request.urlopen(audio_request, timeout=90) as response:
        data = response.read(60 * 1024 * 1024)
    if not data:
        raise RuntimeError("Loudly 音乐下载为空。")
    storage.ensure_dir(temp_path.parent)
    temp_path.write_bytes(data)
    shutil.copyfile(temp_path, target_path)
    if safe_probe_duration(target_path) <= 0:
        raise RuntimeError("Loudly 下载的文件不是可用音频。")
    return {
        "path": target_path,
        "track": {
            "provider": "loudly",
            "id": selected.get("id"),
            "name": selected.get("title"),
            "url": selected.get("music_file_path"),
            "license": "Loudly API commercial license",
            "duration": selected.get("duration_sec"),
            "bpm": selected.get("tempo_bpm"),
            "moods": selected.get("catalog_moods", []),
            "genres": selected.get("catalog_genres", []),
            "energies": selected.get("catalog_energies", []),
            "selection_score": selected.get("selection_score", 0),
            "mood_score": selected.get("mood_score", 0),
            "genre_score": selected.get("genre_score", 0),
            "duration_fit": selected.get("duration_fit", 0),
            "bpm_fit": selected.get("bpm_fit", 0),
            "search_queries": used_queries,
            "rotation_reason": "已避开当前曲和频道近期曲目" if recent_track_ids and clean_text(str(selected.get("id") or "")) not in recent_track_ids else "曲库内暂无新的合格曲目，沿用最匹配候选",
        },
    }


def allowed_jamendo_license(license_url: str) -> bool:
    """Allow commercial reuse without non-commercial, no-derivatives, or share-alike terms."""
    lowered = clean_text(license_url).lower().rstrip("/") + "/"
    if not lowered or any(marker in lowered for marker in ("-nc", "-nd", "by-sa")):
        return False
    return "/licenses/by/" in lowered or "/publicdomain/zero/" in lowered


def jamendo_track_tags(item: dict[str, Any]) -> list[str]:
    musicinfo = item.get("musicinfo") if isinstance(item.get("musicinfo"), dict) else {}
    grouped = musicinfo.get("tags") if isinstance(musicinfo.get("tags"), dict) else {}
    values: list[str] = []
    for group in ("genres", "instruments", "vartags"):
        rows = grouped.get(group) if isinstance(grouped.get(group), list) else []
        values.extend(clean_text(str(value)).lower() for value in rows if clean_text(str(value)))
    return list(dict.fromkeys(values))


def jamendo_popularity_value(item: dict[str, Any]) -> float:
    stats = item.get("stats") if isinstance(item.get("stats"), dict) else {}
    total = 0.0
    for key, weight in {
        "listened": 1.0,
        "listens": 1.0,
        "downloaded": 5.0,
        "downloads": 5.0,
        "favorited": 12.0,
        "favorites": 12.0,
        "likes": 8.0,
        "playlisted": 10.0,
    }.items():
        try:
            total += max(0.0, float(stats.get(key, 0) or 0)) * weight
        except (TypeError, ValueError):
            continue
    return total


def recent_jamendo_track_ids(project_id: int, limit: int = 20) -> set[str]:
    return recent_bgm_track_ids(project_id, "jamendo", limit)


def rank_jamendo_bgm_candidates(
    results: list[dict[str, Any]],
    brief: dict[str, Any],
    recent_track_ids: set[str] | None = None,
    target_duration: float = 0.0,
) -> list[dict[str, Any]]:
    recent = {clean_text(str(item)) for item in (recent_track_ids or set()) if clean_text(str(item))}
    desired_tokens = {
        token.lower()
        for token in re.findall(
            r"[A-Za-z0-9_-]{3,}",
            " ".join(
                [
                    clean_text(str(brief.get("query") or "")),
                    " ".join(str(item) for item in brief.get("tags", []) if clean_text(str(item))),
                ]
            ),
        )
        if token.lower() not in {"music", "background", "short", "video", "sound", "audio", "documentary"}
    }
    eligible: list[dict[str, Any]] = []
    for item in results:
        if not isinstance(item, dict):
            continue
        musicinfo = item.get("musicinfo") if isinstance(item.get("musicinfo"), dict) else {}
        if clean_text(str(musicinfo.get("vocalinstrumental") or "")).lower() != "instrumental":
            continue
        if not bool(item.get("audiodownload_allowed")) or not clean_text(str(item.get("audiodownload") or "")):
            continue
        if not allowed_jamendo_license(str(item.get("license_ccurl") or "")):
            continue
        try:
            duration = float(item.get("duration", 0) or 0)
        except (TypeError, ValueError):
            duration = 0.0
        if duration < 75.0 or duration > 600.0:
            continue
        tags = jamendo_track_tags(item)
        haystack = " ".join(
            [clean_text(str(item.get("name") or "")), clean_text(str(item.get("album_name") or "")), " ".join(tags)]
        ).lower()
        if any(
            marker in haystack
            for marker in ("sound effect", "soundeffect", "field recording", "white noise", "podcast", "a cappella")
        ):
            continue
        eligible.append({**item, "catalog_tags": tags, "catalog_popularity": jamendo_popularity_value(item)})
    if not eligible:
        return []

    max_popularity_log = max(math.log1p(float(item.get("catalog_popularity", 0) or 0)) for item in eligible) or 1.0
    target = max(75.0, min(float(target_duration or 150.0), 300.0))
    ranked: list[dict[str, Any]] = []
    for item in eligible:
        haystack = " ".join(
            [
                clean_text(str(item.get("name") or "")),
                clean_text(str(item.get("album_name") or "")),
                " ".join(item.get("catalog_tags", [])),
            ]
        ).lower()
        overlap = len([token for token in desired_tokens if token in haystack]) / max(1, len(desired_tokens))
        catalog_rank = max(1, int(item.get("_catalog_rank", 1) or 1))
        relevance = 1.0 / (1.0 + (catalog_rank - 1) * 0.08)
        popularity = math.log1p(float(item.get("catalog_popularity", 0) or 0)) / max_popularity_log
        duration = float(item.get("duration", 0) or 0)
        duration_fit = min(1.0, duration / target) if duration < target else max(0.72, 1.0 - (duration - target) / 1200.0)
        content_id_bonus = 0.05 if bool(item.get("content_id_free")) else 0.0
        track_id = clean_text(str(item.get("id") or ""))
        repeat_penalty = 0.75 if track_id and track_id in recent else 0.0
        selection_score = relevance * 0.30 + overlap * 0.28 + popularity * 0.27 + duration_fit * 0.15 + content_id_bonus - repeat_penalty
        ranked.append(
            {
                **item,
                "selection_score": round(selection_score, 4),
                "theme_overlap": round(overlap, 4),
                "popularity_score": round(popularity, 4),
                "duration_fit": round(duration_fit, 4),
                "recent_repeat_penalty": repeat_penalty,
            }
        )
    ordered = sorted(ranked, key=lambda item: float(item.get("selection_score", 0) or 0), reverse=True)
    return prioritize_fresh_bgm_candidates(ordered)


def jamendo_query_candidates(brief: dict[str, Any]) -> list[str]:
    mood_tags = {
        "privacy_investigation": "soundtrack electronic suspense minimal",
        "urgent_warning": "soundtrack cinematic tension dramatic",
        "tech_suspense": "electronic cinematic suspense ambient",
        "warm_warning": "piano acoustic calm emotional",
        "business_pulse": "corporate electronic upbeat groove",
        "science_curiosity": "electronic ambient curious soundtrack",
        "practical_upbeat": "corporate upbeat acoustic positive",
        "story_soft": "cinematic piano emotional calm",
    }
    brief_tags = [
        token.lower()
        for token in re.findall(
            r"[A-Za-z0-9_-]{3,}",
            " ".join(str(item) for item in brief.get("tags", []) if clean_text(str(item))),
        )
        if token.lower() not in {"music", "background", "short", "video", "sound", "audio", "documentary"}
    ]
    raw = [
        " ".join(brief_tags[:4]),
        mood_tags.get(clean_text(str(brief.get("mood") or "")), "cinematic ambient instrumental"),
        "soundtrack instrumental",
    ]
    candidates: list[str] = []
    for value in raw:
        normalized = clean_text(value)
        if normalized and normalized.lower() not in {item.lower() for item in candidates}:
            candidates.append(normalized)
    return candidates


def jamendo_search_bgm(project_id: int, brief: dict[str, Any], client_id: str, target_duration: float) -> dict[str, Any]:
    results_by_id: dict[str, dict[str, Any]] = {}
    used_queries: list[str] = []
    catalog_rank = 0
    for query in jamendo_query_candidates(brief):
        params = {
            "client_id": client_id,
            "format": "json",
            "limit": "100",
            "fuzzytags": query,
            "vocalinstrumental": "instrumental",
            "durationbetween": "75_600",
            "include": "musicinfo stats",
            "audioformat": "mp32",
            "audiodlformat": "mp32",
            "groupby": "artist_id",
            "boost": "popularity_total",
            "ccnc": "false",
            "ccnd": "false",
            "ccsa": "false",
        }
        url = "https://api.jamendo.com/v3.0/tracks/?" + urllib.parse.urlencode(params)
        request = urllib.request.Request(url, headers={"User-Agent": "short-video-studio/1.0"})
        with urllib.request.urlopen(request, timeout=35) as response:
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
        headers = payload.get("headers") if isinstance(payload, dict) and isinstance(payload.get("headers"), dict) else {}
        if int(headers.get("code", 0) or 0) != 0:
            raise RuntimeError(clean_text(str(headers.get("error_message") or "Jamendo API request failed")))
        used_queries.append(query)
        rows = payload.get("results") if isinstance(payload, dict) else []
        for item in rows if isinstance(rows, list) else []:
            if not isinstance(item, dict):
                continue
            track_id = clean_text(str(item.get("id") or ""))
            if not track_id or track_id in results_by_id:
                continue
            catalog_rank += 1
            results_by_id[track_id] = {**item, "_catalog_rank": catalog_rank}
        if len(results_by_id) >= 40:
            break
    recent_track_ids = recent_jamendo_track_ids(project_id)
    ranked = rank_jamendo_bgm_candidates(
        list(results_by_id.values()), brief, recent_track_ids, target_duration
    )
    selected = ranked[0] if ranked else None
    if not selected:
        raise RuntimeError(f"Jamendo 没有找到可商用、可下载且无人声的完整配乐；已尝试：{' / '.join(used_queries)}。")

    temp_path = storage.project_file(project_id, "bgm.jamendo.mp3")
    target_path = storage.project_file(project_id, "bgm.mp3")
    audio_request = urllib.request.Request(
        clean_text(str(selected.get("audiodownload") or "")), headers={"User-Agent": "short-video-studio/1.0"}
    )
    with urllib.request.urlopen(audio_request, timeout=90) as response:
        data = response.read(50 * 1024 * 1024)
    if not data:
        raise RuntimeError("Jamendo 音乐下载为空。")
    storage.ensure_dir(temp_path.parent)
    temp_path.write_bytes(data)
    shutil.copyfile(temp_path, target_path)
    if safe_probe_duration(target_path) <= 0:
        raise RuntimeError("Jamendo 下载的文件不是可用音频。")
    return {
        "path": target_path,
        "track": {
            "provider": "jamendo",
            "id": selected.get("id"),
            "name": selected.get("name"),
            "artist_id": selected.get("artist_id"),
            "artist_name": selected.get("artist_name"),
            "album_name": selected.get("album_name"),
            "url": selected.get("shareurl") or selected.get("shorturl"),
            "image": selected.get("image") or selected.get("album_image"),
            "license": selected.get("license_ccurl"),
            "attribution": f"{clean_text(str(selected.get('name') or ''))} - {clean_text(str(selected.get('artist_name') or ''))}",
            "duration": selected.get("duration"),
            "tags": selected.get("catalog_tags", []),
            "content_id_free": bool(selected.get("content_id_free")),
            "selection_score": selected.get("selection_score", 0),
            "theme_overlap": selected.get("theme_overlap", 0),
            "popularity_score": selected.get("popularity_score", 0),
            "duration_fit": selected.get("duration_fit", 0),
            "search_queries": used_queries,
            "rotation_reason": "已避开当前曲和频道近期曲目" if recent_track_ids and clean_text(str(selected.get("id") or "")) not in recent_track_ids else "曲库内暂无新的合格曲目，沿用最匹配候选",
        },
    }


def recent_procedural_bgm_variants(project_id: int, mood: str, limit: int = 12) -> list[int]:
    variants: list[int] = []
    for meta in recent_channel_bgm_metas(project_id, limit=max(20, limit * 2)):
        if clean_text(str(meta.get("source") or "")) != "procedural_local":
            continue
        selector = meta.get("selector") if isinstance(meta.get("selector"), dict) else {}
        if clean_text(str(meta.get("mood") or selector.get("mood") or "")) != clean_text(mood):
            continue
        try:
            variant = int(meta.get("local_variant"))
        except (TypeError, ValueError):
            continue
        if variant not in variants:
            variants.append(variant)
        if len(variants) >= max(1, int(limit or 12)):
            break
    return variants


def choose_local_bgm_variant(project_id: int, mood: str, pool_size: int = 16) -> int:
    project = storage.get_project(project_id)
    topic = clean_text(str(project.get("topic_name") or ""))
    size = max(4, int(pool_size or 16))
    seed = int(hashlib.sha256(f"{project_id}:{topic}:{mood}:local-bgm".encode("utf-8", errors="ignore")).hexdigest()[:8], 16)
    start = seed % size
    candidates = list(range(start, size)) + list(range(0, start))
    recent = recent_procedural_bgm_variants(project_id, mood, limit=size)
    fresh = next((variant for variant in candidates if variant not in recent), None)
    if fresh is not None:
        return fresh
    recency = {variant: recent.index(variant) for variant in recent}
    return max(candidates, key=lambda variant: recency.get(variant, len(recent) + 1))


def write_procedural_bgm_wav(project_id: int, target: Path, *, mood: str, duration: float, variant: int = 0) -> None:
    profile = PROCEDURAL_BGM_PROFILES.get(mood, PROCEDURAL_BGM_PROFILES["story_soft"])
    sample_rate = 44100
    seconds = max(32.0, min(float(duration or 72.0), 120.0))
    variant_index = max(0, int(variant or 0))
    seed_text = f"{project_id}:{mood}:{storage.get_project(project_id).get('topic_name', '')}:{variant_index}"
    seed = int(hashlib.sha256(seed_text.encode("utf-8", errors="ignore")).hexdigest()[:8], 16)
    phase_offset = (seed % 6283) / 1000.0
    bpm_offsets = (-7.0, -3.0, 0.0, 4.0, 8.0, 2.0)
    bpm = max(54.0, min(118.0, float(profile.get("bpm") or 80) + bpm_offsets[variant_index % len(bpm_offsets)]))
    beat = 60.0 / bpm
    source_chords = profile.get("notes") if isinstance(profile.get("notes"), list) else PROCEDURAL_BGM_PROFILES["story_soft"]["notes"]
    chord_offset = (variant_index + seed) % len(source_chords)
    chords = list(source_chords[chord_offset:]) + list(source_chords[:chord_offset])
    if variant_index % 3 == 1:
        chords = list(reversed(chords))
    pulse_divisions = (1.0, 0.5, 0.75, 0.5)
    pulse_interval = max(beat * pulse_divisions[variant_index % len(pulse_divisions)], 0.1)
    arp_enabled = variant_index % 4 in {1, 2}
    harmonic_mix = (0.10, 0.16, 0.07, 0.13)[variant_index % 4]
    target.parent.mkdir(parents=True, exist_ok=True)

    with wave.open(str(target), "wb") as wav:
        wav.setnchannels(1)
        wav.setsampwidth(2)
        wav.setframerate(sample_rate)
        total_samples = int(seconds * sample_rate)
        chunk = bytearray()
        for index in range(total_samples):
            t = index / sample_rate
            bar = int(t / max(beat * 4, 0.1))
            chord = chords[bar % len(chords)]
            envelope = 0.62 + 0.22 * math.sin(2 * math.pi * t / max(seconds * 0.85, 1.0) + phase_offset)
            pad = 0.0
            for note_index, freq in enumerate(chord):
                detune = 1.0 + ((seed >> (note_index * 3)) & 7) * 0.0007
                pad += math.sin(2 * math.pi * float(freq) * detune * t + phase_offset * (note_index + 1)) * (0.42 / len(chord))
                pad += math.sin(2 * math.pi * float(freq) * 0.5 * t + phase_offset) * (0.22 / len(chord))
                pad += math.sin(2 * math.pi * float(freq) * 2.0 * t + phase_offset * 0.5) * (harmonic_mix / len(chord))
            pad *= float(profile.get("pad") or 0.2) * envelope

            beat_pos = t % pulse_interval
            pulse = 0.0
            if beat_pos < min(0.09, pulse_interval * 0.24):
                pulse_octave = 1.0 if variant_index % 3 == 0 else 2.0
                pulse = math.sin(2 * math.pi * float(chord[0]) * pulse_octave * t) * math.exp(-beat_pos * 28.0) * float(profile.get("pulse") or 0.08)
            arpeggio = 0.0
            if arp_enabled:
                arp_interval = max(beat / 2.0, 0.12)
                arp_pos = t % arp_interval
                if arp_pos < min(0.12, arp_interval * 0.42):
                    arp_step = int(t / arp_interval) % len(chord)
                    arp_freq = float(chord[arp_step]) * (2.0 if variant_index % 2 else 1.0)
                    arpeggio = math.sin(2 * math.pi * arp_freq * t + phase_offset) * math.exp(-arp_pos * 15.0) * 0.035
            half_pos = t % max(beat / 2, 0.1)
            spark = 0.0
            if half_pos < 0.018 and variant_index % 3 != 2:
                spark_frequency = (1250.0, 1800.0, 2300.0)[variant_index % 3]
                spark = math.sin(2 * math.pi * spark_frequency * t + phase_offset) * math.exp(-half_pos * 80.0) * float(profile.get("spark") or 0.01)
            lfo = 0.88 + 0.12 * math.sin(2 * math.pi * t / 11.0 + phase_offset)
            sample = max(-0.92, min(0.92, (pad + pulse + arpeggio + spark) * lfo))
            chunk.extend(struct.pack("<h", int(sample * 32767)))
            if len(chunk) >= sample_rate * 2:
                wav.writeframes(bytes(chunk))
                chunk.clear()
        if chunk:
            wav.writeframes(bytes(chunk))


def convert_audio_to_mp3(source: Path, target: Path) -> bool:
    try:
        subprocess.run(
            [
                str(ffmpeg_binary()),
                "-y",
                "-i",
                str(source),
                "-codec:a",
                "libmp3lame",
                "-b:a",
                "128k",
                str(target),
            ],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=True,
            timeout=300,
            **background_subprocess_kwargs(),
        )
        return target.exists() and target.stat().st_size > 1000
    except subprocess.SubprocessError:
        return False


def download_bgm_to_project(project_id: int, url: str) -> Path:
    suffix = Path(urllib.parse.urlparse(url).path).suffix.lower()
    if suffix not in {".mp3", ".wav", ".m4a", ".aac"}:
        suffix = ".mp3"
    temp_path = storage.project_file(project_id, f"bgm.download{suffix}")
    target_path = storage.project_file(project_id, "bgm.mp3")
    with urllib.request.urlopen(url, timeout=45) as response:
        data = response.read(20 * 1024 * 1024)
    if not data:
        raise RuntimeError("BGM 下载为空。")
    storage.ensure_dir(temp_path.parent)
    temp_path.write_bytes(data)
    if suffix == ".mp3":
        shutil.copyfile(temp_path, target_path)
    elif not convert_audio_to_mp3(temp_path, target_path):
        shutil.copyfile(temp_path, storage.project_file(project_id, f"bgm{suffix}"))
        target_path = storage.project_file(project_id, f"bgm{suffix}")
    if safe_probe_duration(target_path) <= 0:
        raise RuntimeError("下载的 BGM 不是可用音频。")
    return target_path


def ensure_project_bgm(
    project_id: int,
    template_key: str | None = None,
    *,
    audio_duration: float = 0.0,
    force_rematch: bool = False,
    status_callback: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    env = runtime_env()
    mode = clean_text(env.get("BGM_AUTO_MODE", "auto")).lower() or "auto"
    status_before = project_bgm_status(project_id)
    if status_before.get("status") == "disabled":
        return status_before
    if mode in {"template", "channel", "fixed"}:
        return status_before
    if status_before.get("current") and not force_rematch:
        return {**status_before, "status": "exists", "reused": True}

    content = storage.get_content(project_id)
    bgm_brief = ai_bgm_brief(project_id, content)
    context = bgm_context_for_project(project_id, content)
    archived: list[str] = []
    if force_rematch and find_project_bgm_path(project_id):
        archived = archive_existing_project_bgm(project_id)
    download_url = clean_text(env.get("BGM_DOWNLOAD_URL", ""))
    if download_url and mode in {"auto", "download"}:
        try:
            path = download_bgm_to_project(project_id, download_url)
            meta = bgm_meta_with_context(
                {
                    "generated_at": storage.now_ts(),
                    "status": "downloaded",
                    "source": "BGM_DOWNLOAD_URL",
                    "url": download_url,
                    "path": path.as_posix(),
                    "duration_sec": round(safe_probe_duration(path), 3),
                    "note": "使用配置中的固定授权下载地址；该来源视为人工指定。",
                    "archived": archived,
                },
                context,
                bgm_brief,
            )
            storage.write_json(project_bgm_meta_path(project_id), meta)
            return {**meta, "path": path.as_posix(), "source": "download_url", "manual_locked": True}
        except Exception as exc:
            if mode == "download":
                raise RuntimeError(f"BGM 下载失败：{exc}") from exc

    configured_online_provider = clean_text(env.get("BGM_ONLINE_PROVIDER", "loudly")).lower() or "loudly"
    online_provider, _online_catalog_ready = resolve_online_bgm_provider(env, configured_online_provider)
    loudly_api_key = clean_text(env.get("LOUDLY_API_KEY", ""))
    jamendo_client_id = clean_text(env.get("JAMENDO_CLIENT_ID", ""))
    freesound_key = clean_text(env.get("FREESOUND_API_KEY", ""))
    online_fallback_reason = ""
    if mode in {"auto", "online"} and online_provider == "loudly" and loudly_api_key:
        try:
            online = loudly_search_bgm(project_id, bgm_brief, loudly_api_key, audio_duration)
            path = online["path"]
            if status_callback:
                status_callback("[bgm] 曲库匹配完成，正在检查实际音频是否含可辨人声")
            audit = audit_bgm_audio_for_vocals(path, env)
            if audit.get("has_vocals"):
                path.unlink(missing_ok=True)
                raise RuntimeError("Loudly 候选实际音频含可辨人声，已拒绝采用")
            online["audio_vocal_audit"] = audit
            meta = bgm_meta_with_context(
                {
                    "generated_at": storage.now_ts(),
                    "status": "downloaded",
                    "source": "loudly",
                    "track": online.get("track", {}),
                    "audio_vocal_audit": online.get("audio_vocal_audit", {}),
                    "path": path.as_posix(),
                    "duration_sec": round(safe_probe_duration(path), 3),
                    "note": "Loudly 完整纯音乐；按主题、情绪、类型、BPM、时长与近期去重自动选曲。",
                    "rotation_reason": clean_text(str(online.get("track", {}).get("rotation_reason") or "")),
                    "archived": archived,
                },
                context,
                bgm_brief,
            )
            storage.write_json(project_bgm_meta_path(project_id), meta)
            return {**meta, "path": path.as_posix(), "source": "loudly", "track": online.get("track", {})}
        except Exception as exc:
            if mode == "online":
                raise RuntimeError(f"Loudly 在线 BGM 匹配失败：{exc}") from exc
            online_fallback_reason = f"Loudly 在线匹配失败，已回退本地主题音乐：{user_facing_error(exc, 220)}"
    if mode in {"auto", "online"} and online_provider == "jamendo" and jamendo_client_id:
        try:
            online = jamendo_search_bgm(project_id, bgm_brief, jamendo_client_id, audio_duration)
            path = online["path"]
            if status_callback:
                status_callback("[bgm] 曲库匹配完成，正在检查实际音频是否含可辨人声")
            audit = audit_bgm_audio_for_vocals(path, env)
            if audit.get("has_vocals"):
                path.unlink(missing_ok=True)
                raise RuntimeError("Jamendo 候选实际音频含可辨人声，已拒绝采用")
            online["audio_vocal_audit"] = audit
            meta = bgm_meta_with_context(
                {
                    "generated_at": storage.now_ts(),
                    "status": "downloaded",
                    "source": "jamendo",
                    "track": online.get("track", {}),
                    "audio_vocal_audit": online.get("audio_vocal_audit", {}),
                    "path": path.as_posix(),
                    "duration_sec": round(safe_probe_duration(path), 3),
                    "note": "Jamendo 完整纯音乐；作者、曲目页面与授权地址已记录在 track 元数据中。",
                    "rotation_reason": clean_text(str(online.get("track", {}).get("rotation_reason") or "")),
                    "archived": archived,
                },
                context,
                bgm_brief,
            )
            storage.write_json(project_bgm_meta_path(project_id), meta)
            return {**meta, "path": path.as_posix(), "source": "jamendo", "track": online.get("track", {})}
        except Exception as exc:
            if mode == "online":
                raise RuntimeError(f"Jamendo 在线 BGM 匹配失败：{exc}") from exc
            online_fallback_reason = f"Jamendo 在线匹配失败，已回退本地主题音乐：{user_facing_error(exc, 220)}"
    if mode in {"auto", "online"} and online_provider == "freesound" and freesound_key:
        try:
            online = freesound_search_bgm(
                project_id,
                bgm_brief,
                freesound_key,
                audio_duration,
                status_callback=status_callback,
            )
            path = online["path"]
            meta = bgm_meta_with_context(
                {
                    "generated_at": storage.now_ts(),
                    "status": "downloaded",
                    "source": "freesound",
                    "track": online.get("track", {}),
                    "audio_vocal_audit": online.get("audio_vocal_audit", {}),
                    "path": path.as_posix(),
                    "duration_sec": round(safe_probe_duration(path), 3),
                    "note": "在线搜索可授权 BGM 后下载到本地；请按 track.license 遵守署名要求。",
                    "rotation_reason": clean_text(str(online.get("track", {}).get("rotation_reason") or "")),
                    "archived": archived,
                },
                context,
                bgm_brief,
            )
            storage.write_json(project_bgm_meta_path(project_id), meta)
            return {
                **meta,
                "path": path.as_posix(),
                "source": "freesound",
                "track": online.get("track", {}),
            }
        except Exception as exc:
            if mode == "online":
                raise RuntimeError(f"在线 BGM 搜索失败：{exc}") from exc
            online_fallback_reason = f"Freesound 在线匹配失败，已回退本地主题音乐：{user_facing_error(exc, 220)}"

    if mode not in {"auto", "generate", "local", "online"}:
        return {"status": "skipped", "path": "", "source": mode}

    mood = clean_text(str(bgm_brief.get("mood") or bgm_mood_for_project(project_id, content)))
    wav_path = storage.project_file(project_id, "bgm.wav")
    mp3_path = storage.project_file(project_id, "bgm.mp3")
    generated_duration = max(48.0, min(float(audio_duration or 72.0), 72.0))
    local_variant = choose_local_bgm_variant(project_id, mood)
    write_procedural_bgm_wav(project_id, wav_path, mood=mood, duration=generated_duration, variant=local_variant)
    path = mp3_path if convert_audio_to_mp3(wav_path, mp3_path) else wav_path
    if mode in {"auto", "online"} and online_provider == "loudly" and not loudly_api_key:
        online_fallback_reason = "Loudly API Key 未配置，本期使用本地主题音乐；配置后会优先选择完整纯音乐。"
    elif mode in {"auto", "online"} and online_provider == "jamendo" and not jamendo_client_id:
        online_fallback_reason = "Jamendo Client ID 未配置，本期使用本地主题音乐；配置后会优先选择完整纯音乐。"
    elif mode in {"auto", "online"} and online_provider == "freesound" and not freesound_key:
        online_fallback_reason = "Freesound API Key 未配置，本期使用主题匹配的本地无版权备用音乐；配置后会优先从在线曲库按贴合度和热度选曲。"
    try:
        online_retry_cooldown_seconds = int(float(env.get("BGM_ONLINE_RETRY_COOLDOWN_SECONDS", 21600) or 21600))
    except (TypeError, ValueError):
        online_retry_cooldown_seconds = 21600
    online_retry_cooldown_seconds = max(900, min(online_retry_cooldown_seconds, 86400))
    meta = bgm_meta_with_context(
        {
            "generated_at": storage.now_ts(),
            "status": "generated",
            "source": "procedural_local",
            "path": path.as_posix(),
            "duration_sec": round(safe_probe_duration(path), 3),
            "note": online_fallback_reason or "本地自动生成的无版权铺底音乐，按本期主题与口播情绪分型，默认低音量循环混入。",
            "fallback_reason": online_fallback_reason,
            "online_retry_after": (
                storage.now_ts() + online_retry_cooldown_seconds
                if online_fallback_reason
                else 0
            ),
            "local_variant": local_variant,
            "rotation_reason": (
                f"已避开频道近期配器，生成「{bgm_brief.get('arrangement_label') or '主题音乐'}」变体"
            ),
            "archived": archived,
        },
        context,
        bgm_brief,
    )
    storage.write_json(project_bgm_meta_path(project_id), meta)
    return {**meta, "path": path.as_posix(), "source": "procedural_local", "mood": mood, "label": meta["label"]}


def ffmpeg_binary() -> Path:
    candidate = workspace_root() / "_analysis" / "awesome_app_install" / "ffmpeg" / "bin" / "ffmpeg.exe"
    if candidate.exists():
        return candidate
    return Path("ffmpeg")


def strip_generated_video_audio(path: Path) -> bool:
    """Remove model-generated audio so only the project's narration reaches the final mix."""
    if not path.exists() or path.stat().st_size <= 0:
        return False
    silent_path = path.with_name(f".{path.stem}.silent{path.suffix}")
    silent_path.unlink(missing_ok=True)
    completed = subprocess.run(
        [
            str(ffmpeg_binary()),
            "-y",
            "-i",
            str(path),
            "-map",
            "0:v:0",
            "-c:v",
            "copy",
            "-an",
            "-movflags",
            "+faststart",
            str(silent_path),
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        **background_subprocess_kwargs(),
    )
    if completed.returncode != 0 or not silent_path.exists() or silent_path.stat().st_size <= 0:
        silent_path.unlink(missing_ok=True)
        detail = clean_text(completed.stderr)[-600:]
        raise RuntimeError(f"无法移除动态图模型自带音轨：{detail}")
    silent_path.replace(path)
    return True


def burn_motion_information_overlay(video_path: Path, overlay_path: Path) -> bool:
    """Keep key information stable across every model-generated video frame."""
    if not video_path.exists() or not overlay_path.exists():
        return False
    rendered_path = video_path.with_name(f".{video_path.stem}.information{video_path.suffix}")
    rendered_path.unlink(missing_ok=True)
    duration = max(0.1, safe_probe_duration(video_path))
    probe = subprocess.run(
        [
            str(ffprobe_binary()),
            "-v",
            "error",
            "-select_streams",
            "v:0",
            "-show_entries",
            "stream=width,height",
            "-of",
            "csv=s=x:p=0",
            str(video_path),
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        **background_subprocess_kwargs(),
    )
    dimension_match = re.search(r"(\d+)x(\d+)", clean_text(probe.stdout))
    if not dimension_match:
        raise RuntimeError("无法读取动态镜头尺寸，不能安全写入主信息图层")
    video_width, video_height = dimension_match.groups()
    completed = subprocess.run(
        [
            str(ffmpeg_binary()),
            "-y",
            "-i",
            str(video_path),
            "-stream_loop",
            "-1",
            "-framerate",
            "30",
            "-i",
            str(overlay_path),
            "-filter_complex",
            f"[1:v]scale={video_width}:{video_height},format=rgba,"
            "fade=t=in:st=0.12:d=0.32:alpha=1[info];"
            "[0:v][info]overlay=0:0:eof_action=repeat:shortest=1:format=auto,format=yuv420p[v]",
            "-map",
            "[v]",
            "-an",
            "-c:v",
            "libx264",
            "-preset",
            "veryfast",
            "-crf",
            "18",
            "-t",
            f"{duration:.3f}",
            "-movflags",
            "+faststart",
            str(rendered_path),
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        **background_subprocess_kwargs(),
    )
    if completed.returncode != 0 or not rendered_path.exists() or rendered_path.stat().st_size <= 0:
        rendered_path.unlink(missing_ok=True)
        detail = clean_text(completed.stderr)[-700:]
        raise RuntimeError(f"无法把镜头主信息写入动态视频：{detail}")
    rendered_path.replace(video_path)
    return True


def ffprobe_binary() -> Path:
    candidate = workspace_root() / "_analysis" / "awesome_app_install" / "ffmpeg" / "bin" / "ffprobe.exe"
    if candidate.exists():
        return candidate
    return Path("ffprobe")


def probe_media_duration(media_path: Path) -> float:
    result = subprocess.run(
        [
            str(ffprobe_binary()),
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            str(media_path),
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        check=True,
        timeout=60,
        **background_subprocess_kwargs(),
    )
    try:
        return float((result.stdout or "0").strip() or "0")
    except ValueError:
        return 0.0


def probe_audio_duration(audio_path: Path) -> float:
    return probe_media_duration(audio_path)


def mp3_id3_header_offsets(data: bytes) -> list[int]:
    """Locate complete ID3 headers used by each MP3 round returned by Doubao."""
    offsets: list[int] = []
    cursor = 0
    while True:
        index = data.find(b"ID3", cursor)
        if index < 0:
            break
        if index + 10 <= len(data) and data[index + 3] in {2, 3, 4}:
            offsets.append(index)
        cursor = index + 3
    return offsets


TTS_ROUND_REPAIR_FILTER = (
    "highpass=f=65,"
    "deesser=i=0.30:m=0.55:f=0.42,"
    "equalizer=f=4100:t=q:w=0.7:g=-6.5,"
    "equalizer=f=6100:t=q:w=0.8:g=-8.5,"
    "lowpass=f=7600,"
    "alimiter=limit=0.97"
)


def pcm16_voice_quality(pcm: bytes, sample_rate: int = 24000) -> dict[str, Any]:
    """Detect vocoder-like high-frequency corruption in mono PCM speech."""
    usable = len(pcm) - (len(pcm) % 2)
    samples = array.array("h")
    samples.frombytes(pcm[:usable])
    if sys.byteorder != "little":
        samples.byteswap()
    window = max(2000, sample_rate // 2)
    hop = max(1000, window // 2)
    ratios: list[float] = []
    for start in range(0, max(0, len(samples) - window + 1), hop):
        end = start + window
        total_sq = 0
        diff_sq = 0
        previous = int(samples[start])
        for index in range(start, end):
            current = int(samples[index])
            total_sq += current * current
            if index > start:
                delta = current - previous
                diff_sq += delta * delta
            previous = current
        if total_sq <= 0:
            continue
        rms = math.sqrt(total_sq / window) / 32768.0
        if 20.0 * math.log10(max(rms, 1e-12)) < -38.0:
            continue
        ratios.append(math.sqrt(diff_sq / total_sq))
    if not ratios:
        return {
            "active_windows": 0,
            "median_derivative_ratio": 0.0,
            "p90_derivative_ratio": 0.0,
            "bad_window_ratio": 0.0,
            "suspicious": False,
        }
    ordered = sorted(ratios)
    median = ordered[len(ordered) // 2]
    p90 = ordered[min(len(ordered) - 1, math.ceil(len(ordered) * 0.9) - 1)]
    bad_ratio = sum(1 for value in ratios if value > 0.60) / len(ratios)
    suspicious = median > 0.55 or (bad_ratio >= 0.35 and p90 > 0.80)
    return {
        "active_windows": len(ratios),
        "median_derivative_ratio": round(median, 4),
        "p90_derivative_ratio": round(p90, 4),
        "bad_window_ratio": round(bad_ratio, 4),
        "suspicious": suspicious,
    }


def repair_tts_pcm_round(pcm: bytes, sample_rate: int = 24000) -> bytes:
    result = subprocess.run(
        [
            str(ffmpeg_binary()),
            "-hide_banner",
            "-loglevel",
            "error",
            "-f",
            "s16le",
            "-ar",
            str(sample_rate),
            "-ac",
            "1",
            "-i",
            "pipe:0",
            "-af",
            TTS_ROUND_REPAIR_FILTER,
            "-f",
            "s16le",
            "pipe:1",
        ],
        input=pcm,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=180,
        **background_subprocess_kwargs(),
    )
    if result.returncode != 0 or not result.stdout:
        detail = clean_text(result.stderr.decode("utf-8", errors="replace"))
        raise RuntimeError(f"异常配音分段自动降噪失败：{detail[:180]}")
    return result.stdout


def pcm16_edge_silence_ms(
    pcm: bytes,
    edge: str,
    sample_rate: int = 24000,
    threshold_db: float = -40.0,
) -> int:
    """Measure contiguous quiet audio at the start or end of mono PCM."""
    usable = len(pcm) - (len(pcm) % 2)
    if usable <= 0:
        return 0
    samples = array.array("h")
    samples.frombytes(pcm[:usable])
    if sys.byteorder != "little":
        samples.byteswap()
    frame_samples = max(1, round(sample_rate * 0.01))
    amplitude_limit = 32768.0 * math.pow(10.0, threshold_db / 20.0)
    starts = range(0, len(samples), frame_samples)
    if edge == "end":
        starts = range(max(0, len(samples) - frame_samples), -1, -frame_samples)
    quiet_samples = 0
    for start in starts:
        end = min(len(samples), start + frame_samples)
        if end <= start:
            continue
        rms = math.sqrt(sum(int(value) * int(value) for value in samples[start:end]) / (end - start))
        if rms > amplitude_limit:
            break
        quiet_samples += end - start
    return round(quiet_samples * 1000 / sample_rate)


def tts_boundary_pause_ms(current: dict[str, Any], following: dict[str, Any]) -> int:
    """Choose a natural minimum pause without forcing one fixed cadence."""
    text = clean_text(str(current.get("text") or ""))
    current_speaker = clean_text(str(current.get("speaker") or ""))
    following_speaker = clean_text(str(following.get("speaker") or ""))
    if current_speaker and following_speaker and current_speaker.casefold() != following_speaker.casefold():
        return 520
    if re.search(r"[！？!?]\s*[”’\"']?$", text):
        return 440
    if re.search(r"[。.]\s*[”’\"']?$", text):
        return 360
    if re.search(r"[；;]\s*[”’\"']?$", text):
        return 300
    if re.search(r"[，,、：:]\s*[”’\"']?$", text):
        return 220
    return 260


def pcm_silence(duration_ms: int, sample_rate: int = 24000) -> bytes:
    samples = max(0, round(sample_rate * max(0, duration_ms) / 1000.0))
    return b"\x00\x00" * samples


def normalize_tts_audio_asset(
    audio_path: Path,
    dialogue: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Decode every podcast round separately and encode one valid, clean MP3.

    Doubao returns one complete MP3 stream per podcast round. The original
    runtime concatenates those byte streams, leaving an ID3 header between
    utterances. Decoding the malformed aggregate produces a header error and
    an audible hiss/click at every boundary.
    """
    if not audio_path.exists() or audio_path.stat().st_size <= 0:
        raise RuntimeError("豆包配音输出为空，无法整理音频分段。")
    source = audio_path.read_bytes()
    offsets = mp3_id3_header_offsets(source)
    source_hash = hashlib.sha256(source).hexdigest()[:16]
    source_duration = probe_audio_duration(audio_path)
    decoded_source_duration = source_duration
    round_quality: list[dict[str, Any]] = []
    repaired_rounds: list[int] = []
    boundary_pacing: list[dict[str, Any]] = []
    inserted_pause_ms = 0
    with tempfile.TemporaryDirectory(prefix="short-video-tts-") as temp_dir_text:
        temp_dir = Path(temp_dir_text)
        input_args: list[str]
        decode_strategy = "single_stream"
        round_count = max(1, len(offsets))
        if len(offsets) > 1:
            starts = offsets
            chunks: list[Path] = []
            for index, start in enumerate(starts):
                end = starts[index + 1] if index + 1 < len(starts) else len(source)
                payload = source[start:end]
                if len(payload) < 512:
                    continue
                chunk_path = temp_dir / f"round-{index + 1:03d}.mp3"
                chunk_path.write_bytes(payload)
                chunks.append(chunk_path)
            if len(chunks) < 2:
                raise RuntimeError("豆包配音包含多个音频分段，但无法完整拆分。")
            # Each Doubao round is a complete MP3 and may use different stream
            # parameters. The concat demuxer assumes identical streams and can
            # turn mismatched rounds into loud high-frequency noise. Decode and
            # resample every round independently before joining raw PCM bytes.
            decoded_rounds: list[bytes] = []
            for index, chunk_path in enumerate(chunks, start=1):
                decoded = subprocess.run(
                    [
                        str(ffmpeg_binary()),
                        "-hide_banner",
                        "-loglevel",
                        "error",
                        "-i",
                        str(chunk_path),
                        "-vn",
                        "-ar",
                        "24000",
                        "-ac",
                        "1",
                        "-f",
                        "s16le",
                        "pipe:1",
                    ],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=120,
                    **background_subprocess_kwargs(),
                )
                if decoded.returncode != 0 or not decoded.stdout:
                    detail = clean_text(decoded.stderr.decode("utf-8", errors="replace"))
                    raise RuntimeError(f"豆包配音第 {index} 段解码失败：{detail[:180]}")
                pcm_payload = decoded.stdout
                quality = pcm16_voice_quality(pcm_payload)
                quality["round"] = index
                quality["repaired"] = False
                if quality.get("suspicious"):
                    repaired = repair_tts_pcm_round(pcm_payload)
                    repaired_quality = pcm16_voice_quality(repaired)
                    repaired_quality["round"] = index
                    repaired_quality["repaired"] = True
                    repaired_quality["before"] = quality
                    pcm_payload = repaired
                    quality = repaired_quality
                    repaired_rounds.append(index)
                round_quality.append(quality)
                decoded_rounds.append(pcm_payload)

            raw_pcm_bytes = sum(len(item) for item in decoded_rounds)
            dialogue_items = [item for item in (dialogue or []) if isinstance(item, dict)]
            pacing_enabled = len(dialogue_items) == len(decoded_rounds)
            pcm_path = temp_dir / "rounds.s16le"
            with pcm_path.open("wb") as pcm_output:
                for index, pcm_payload in enumerate(decoded_rounds):
                    pcm_output.write(pcm_payload)
                    if not pacing_enabled or index + 1 >= len(decoded_rounds):
                        continue
                    trailing_ms = pcm16_edge_silence_ms(pcm_payload, "end")
                    leading_ms = pcm16_edge_silence_ms(decoded_rounds[index + 1], "start")
                    target_ms = tts_boundary_pause_ms(dialogue_items[index], dialogue_items[index + 1])
                    added_ms = max(0, target_ms - trailing_ms - leading_ms)
                    if added_ms:
                        pcm_output.write(pcm_silence(added_ms))
                        inserted_pause_ms += added_ms
                    boundary_pacing.append(
                        {
                            "after_round": index + 1,
                            "target_ms": target_ms,
                            "existing_ms": trailing_ms + leading_ms,
                            "inserted_ms": added_ms,
                        }
                    )
            input_args = ["-f", "s16le", "-ar", "24000", "-ac", "1", "-i", str(pcm_path)]
            decode_strategy = "per_round_pcm"
            decoded_source_duration = raw_pcm_bytes / (24000 * 2)
            round_count = len(chunks)
        else:
            input_args = ["-i", str(audio_path)]

        normalized_path = temp_dir / "podcast.normalized.mp3"
        filters = (
            "highpass=f=65,"
            "deesser=i=0.30:m=0.50:f=0.50,"
            "equalizer=f=7200:t=q:w=1.1:g=-2.5,"
            "lowpass=f=9700,"
            "alimiter=limit=0.97"
        )
        result = subprocess.run(
            [
                str(ffmpeg_binary()),
                "-y",
                "-hide_banner",
                "-loglevel",
                "warning",
                *input_args,
                "-vn",
                "-af",
                filters,
                "-ar",
                "24000",
                "-ac",
                "1",
                "-codec:a",
                "libmp3lame",
                "-b:a",
                "128k",
                "-write_xing",
                "1",
                str(normalized_path),
            ],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=900,
            **background_subprocess_kwargs(),
        )
        if result.returncode != 0 or not normalized_path.exists() or normalized_path.stat().st_size < 1000:
            detail = clean_text(result.stderr or result.stdout or "FFmpeg 未生成规范音频")
            raise RuntimeError(f"配音分段整理失败：{detail[:240]}")
        normalized_duration = probe_audio_duration(normalized_path)
        expected_normalized_duration = decoded_source_duration + inserted_pause_ms / 1000.0
        if expected_normalized_duration > 0 and not (
            expected_normalized_duration * 0.94 <= normalized_duration <= expected_normalized_duration * 1.06
        ):
            raise RuntimeError(
                f"配音分段整理后时长异常：{expected_normalized_duration:.2f}s -> {normalized_duration:.2f}s"
            )
        normalized_data = normalized_path.read_bytes()
        normalized_headers = mp3_id3_header_offsets(normalized_data)
        if len(normalized_headers) > 1:
            raise RuntimeError("配音整理结果仍包含多个 MP3 头，已拒绝覆盖原音频。")
        final_decoded = subprocess.run(
            [
                str(ffmpeg_binary()),
                "-hide_banner",
                "-loglevel",
                "error",
                "-i",
                str(normalized_path),
                "-vn",
                "-ar",
                "24000",
                "-ac",
                "1",
                "-f",
                "s16le",
                "pipe:1",
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=180,
            **background_subprocess_kwargs(),
        )
        if final_decoded.returncode != 0 or not final_decoded.stdout:
            raise RuntimeError("配音质检无法解码最终音轨，已拒绝覆盖旧音频。")
        final_quality = pcm16_voice_quality(final_decoded.stdout)
        if final_quality.get("suspicious"):
            raise RuntimeError(
                "配音仍存在大段高频嘶声，自动降噪后未达标，已拒绝进入字幕和成片。"
            )
        shutil.copyfile(normalized_path, audio_path)

    metadata = {
        "version": TTS_AUDIO_PROCESSING_VERSION,
        "processed_at": storage.now_ts(),
        "source_hash": source_hash,
        "output_hash": hashlib.sha256(audio_path.read_bytes()).hexdigest()[:16],
        "round_count": round_count,
        "source_duration": round(source_duration, 3),
        "decoded_source_duration": round(decoded_source_duration, 3),
        "inserted_pause_seconds": round(inserted_pause_ms / 1000.0, 3),
        "boundary_pacing": boundary_pacing,
        "output_duration": round(probe_audio_duration(audio_path), 3),
        "id3_headers_before": len(offsets),
        "id3_headers_after": len(mp3_id3_header_offsets(audio_path.read_bytes())),
        "decode_strategy": decode_strategy,
        "filter": filters,
        "round_quality": round_quality,
        "repaired_rounds": repaired_rounds,
        "final_quality": final_quality,
    }
    storage.write_json(audio_path.with_name("podcast_processing.json"), metadata)
    return metadata


def probe_stream_start_time(media_path: Path, stream_selector: str) -> float:
    result = subprocess.run(
        [
            str(ffprobe_binary()),
            "-v",
            "error",
            "-select_streams",
            stream_selector,
            "-show_entries",
            "stream=start_time",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            str(media_path),
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        check=True,
        timeout=60,
        **background_subprocess_kwargs(),
    )
    try:
        return float((result.stdout or "0").strip() or "0")
    except ValueError:
        return 0.0


def normalize_media_timeline(output_path: Path) -> None:
    video_start = probe_stream_start_time(output_path, "v:0")
    audio_start = probe_stream_start_time(output_path, "a:0")
    if abs(video_start) < 0.05 and abs(audio_start) < 0.05:
        return

    with tempfile.TemporaryDirectory(prefix="svs-retime-") as temp_dir_name:
        temp_output = Path(temp_dir_name) / output_path.name
        cmd = [
            str(ffmpeg_binary()),
            "-y",
            "-i",
            str(output_path),
            "-vf",
            "setpts=PTS-STARTPTS",
            "-af",
            "asetpts=PTS-STARTPTS",
            "-c:v",
            "libx264",
            "-preset",
            "veryfast",
            "-c:a",
            "aac",
            "-b:a",
            "192k",
            "-pix_fmt",
            "yuv420p",
            "-movflags",
            "+faststart",
            str(temp_output),
        ]
        subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=True,
            timeout=3600,
            **background_subprocess_kwargs(),
        )
        temp_output.replace(output_path)


def write_shifted_srt(source_path: Path, target_path: Path, offset_ms: int) -> Path:
    entries = load_srt_entries(source_path)
    if not entries or offset_ms == 0:
        return source_path
    shifted: list[dict[str, Any]] = []
    for entry in entries:
        start_ms = max(0, int(entry.get("start_ms", 0) or 0) + offset_ms)
        end_ms = max(start_ms + 1, int(entry.get("end_ms", 0) or 0) + offset_ms)
        shifted.append(
            {
                "start_ms": start_ms,
                "end_ms": end_ms,
                "text": clean_text(str(entry.get("text", ""))),
            }
        )
    write_srt_entries(target_path, shifted)
    return target_path


def subtitle_end_duration(subtitle_path: Path | None) -> float | None:
    if not subtitle_path or not subtitle_path.exists():
        return None
    entries = load_srt_entries(subtitle_path)
    if not entries:
        return None
    end_ms = max(int(item.get("end_ms", 0) or 0) for item in entries)
    if end_ms <= 0:
        return None
    return end_ms / 1000.0


def load_timeline_durations(project_id: int, scene_count: int) -> tuple[float, list[float], float] | None:
    timeline_path = storage.project_file(project_id, "audio/scene_timeline.json")
    if not timeline_path.exists():
        return None
    data = storage.read_json(timeline_path, {})
    if not isinstance(data, dict):
        return None
    scenes = data.get("scenes")
    if not isinstance(scenes, list) or len(scenes) != scene_count or not scenes:
        return None
    try:
        audio_ms = int(data.get("audio_duration_ms", 0) or 0)
        cover_ms = int(data.get("cover_duration_ms", scenes[0].get("start_ms", 0)) or 0)
        last_end_ms = int(scenes[-1].get("end_ms", 0) or 0)
        scene_durations = []
        previous_end = cover_ms
        for scene in scenes:
            start_ms = int(scene.get("start_ms", 0) or 0)
            end_ms = int(scene.get("end_ms", 0) or 0)
            if end_ms <= start_ms or start_ms < previous_end:
                return None
            scene_durations.append((end_ms - start_ms) / 1000.0)
            previous_end = end_ms
        outro_ms = max(0, int(data.get("outro_duration_ms", 0) or 0))
        if outro_ms == 0 and audio_ms > last_end_ms:
            outro_ms = audio_ms - last_end_ms
        return cover_ms / 1000.0, scene_durations, outro_ms / 1000.0
    except (ValueError, TypeError, KeyError):
        return None


def expected_video_duration(
    project_id: int,
    scene_count: int,
    audio_path: Path,
    subtitle_path: Path | None,
) -> float:
    candidates: list[float] = []
    audio_duration = probe_audio_duration(audio_path)
    if audio_duration > 0:
        candidates.append(audio_duration)

    subtitle_duration = subtitle_end_duration(subtitle_path)
    if subtitle_duration is not None and subtitle_duration > 0:
        candidates.append(subtitle_duration + SUBTITLE_END_PADDING_SECONDS)

    timing = load_timeline_durations(project_id, scene_count)
    if timing:
        cover_duration, scene_durations, outro_duration = timing
        candidates.append(cover_duration + sum(scene_durations) + outro_duration)

    return max(candidates, default=0.0)


def video_duration_tolerance_seconds(expected_duration: float) -> float:
    if expected_duration <= 0:
        return ORIGINAL_VIDEO_DURATION_TOLERANCE_SECONDS
    return max(2.5, min(8.0, max(expected_duration * 0.015, ORIGINAL_VIDEO_DURATION_TOLERANCE_SECONDS)))


def ensure_video_duration_matches(output_path: Path, expected_duration: float) -> float:
    if expected_duration <= 0:
        return probe_media_duration(output_path)
    actual_duration = probe_media_duration(output_path)
    tolerance = video_duration_tolerance_seconds(expected_duration)
    delta = actual_duration - expected_duration
    if actual_duration <= 0:
        raise RuntimeError(f"无法读取成片时长：{output_path}")
    if abs(delta) > tolerance:
        direction = "过长" if delta > 0 else "过短"
        raise RuntimeError(
            f"原版 composer 输出时长{direction}：预期约 {expected_duration:.1f}s，实际 {actual_duration:.1f}s，偏差 {delta:+.1f}s"
        )
    return actual_duration


def ffmpeg_concat_quote(path: Path) -> str:
    return path.resolve().as_posix().replace("'", r"'\''")


def ffmpeg_subtitle_path(path: Path) -> str:
    return path.resolve().as_posix().replace(":", r"\:").replace("'", r"\'")


def write_concat_list(path: Path, entries: list[tuple[Path, float]]) -> None:
    lines = ["ffconcat version 1.0"]
    for image_path, duration in entries:
        lines.append(f"file '{ffmpeg_concat_quote(image_path)}'")
        lines.append(f"duration {max(0.04, duration):.3f}")
    if entries:
        lines.append(f"file '{ffmpeg_concat_quote(entries[-1][0])}'")
    storage.write_text(path, "\n".join(lines) + "\n")


def load_scene_plan_entries(project_id: int) -> list[dict[str, Any]]:
    plan_path = storage.project_file(project_id, "audio/scene_plan.json")
    if not plan_path.exists():
        return []
    data = storage.read_json(plan_path, {})
    scenes = data.get("scenes") if isinstance(data, dict) else []
    if not isinstance(scenes, list):
        return []
    return [item for item in scenes if isinstance(item, dict)]


MOTION_CLIP_MANIFEST_VERSION = "capsule-motion-clips-v3-native-scene-text"


def project_motion_clip_manifest_path(project_id: int) -> Path:
    return storage.project_file(project_id, "video_clips/manifest.json")


def project_motion_director_plan_path(project_id: int) -> Path:
    return storage.project_file(project_id, "video_clips/director_plan.json")


def _motion_clip_scene_score(scene: dict[str, Any], index: int) -> float:
    try:
        score = float(scene.get("importance_score", scene.get("importance", 0)) or 0)
    except (TypeError, ValueError):
        score = 0.0
    text = clean_text(
        " ".join(
            str(scene.get(key) or "")
            for key in ("narrative_role", "beat_type", "speech_text", "audio_anchor", "motion")
        )
    ).lower()
    if index == 1:
        score += 40
    if any(token in text for token in ("hook", "开头", "钩子", "证据", "实测", "反转", "结论", "冲突")):
        score += 24
    if re.search(r"\d", text):
        score += 8
    return score


def select_motion_clip_scene_indexes(
    project_id: int,
    *,
    mode: str,
    count: int,
    scene_count: int,
) -> list[int]:
    if scene_count <= 0 or mode in {"off", "none", "disabled"}:
        return []
    if mode == "opening_only":
        return [1]
    if mode == "all":
        return list(range(1, scene_count + 1))
    plan = load_scene_plan_entries(project_id)
    ranked = sorted(
        range(1, scene_count + 1),
        key=lambda index: (
            _motion_clip_scene_score(plan[index - 1] if index - 1 < len(plan) else {}, index),
            -index,
        ),
        reverse=True,
    )
    selected = ranked[: max(1, min(int(count), scene_count))]
    return sorted(selected)


def build_motion_clip_director_plan(
    project_id: int,
    index: int,
    scene: dict[str, Any],
    *,
    duration: int = 5,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    topic = clean_text(project.get("topic_name"))
    return motion_director.build_motion_plan(
        topic=topic,
        index=index,
        scene=scene,
        duration=duration,
    )


def build_motion_clip_prompt(
    project_id: int,
    index: int,
    scene: dict[str, Any],
    *,
    duration: int = 5,
) -> str:
    plan = build_motion_clip_director_plan(
        project_id,
        index,
        scene,
        duration=duration,
    )
    return compact_visual_image_prompt(clean_text(plan.get("prompt")), 760)


def prepare_motion_information_keyframe(
    project_id: int,
    index: int,
    scene: dict[str, Any],
    source_path: Path,
) -> tuple[Path, dict[str, Any]]:
    """Reuse the AI-native scene image as the motion keyframe.

    Scene typography is generated together with the image.  Motion rendering
    must preserve that frame rather than adding a second deterministic title
    layer that competes with the original composition.
    """
    speech = clean_scene_spoken_text(
        str(
            scene.get("audio_anchor")
            or scene.get("speech_text")
            or scene.get("speech_summary")
            or scene_prompt_speech_anchor(str(scene.get("source_prompt") or scene.get("image_prompt") or ""))
            or ""
        )
    )
    contrast = re.search(
        r"总参数\s*(?P<total>\d+(?:\.\d+)?\s*[A-Za-z]*)[^。！？]{0,32}?(?:只醒|只激活|激活)\s*(?P<active>\d+(?:\.\d+)?\s*[A-Za-z]*)",
        speech,
        flags=re.IGNORECASE,
    )
    if contrast:
        total = re.sub(r"\s+", "", contrast.group("total"))
        active = re.sub(r"\s+", "", contrast.group("active"))
        headline = f"{total} → {active}"
        chips = [f"总参数 {total}", f"实际激活 {active}"]
        display_mode = "numeric_contrast"
    else:
        headline = scene_information_headline(speech) if speech else ""
        chips = scene_information_fact_chips(speech, headline=headline, limit=2) if speech else []
        display_mode = "headline"
    if headline == "本镜核心结论":
        headline = ""
    return source_path, {
        "applied": False,
        "mode": "ai_native",
        "headline": headline,
        "fact_chips": chips,
        "display_mode": display_mode,
        "reason": "scene_text_already_in_image",
    }


def generate_project_motion_clips(
    project_id: int,
    *,
    log: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    env = runtime_env()
    provider = clean_text(env.get("VIDEO_PROVIDER") or "off").lower()
    mode = clean_text(env.get("VIDEO_MOTION_MODE") or "key_scenes").lower()
    if provider in {"", "off", "none", "disabled"} or mode in {"off", "none", "disabled"}:
        payload = {
            "version": MOTION_CLIP_MANIFEST_VERSION,
            "status": "disabled",
            "provider": "off",
            "clips": [],
            "updated_at": storage.now_ts(),
        }
        storage.write_json(project_motion_clip_manifest_path(project_id), payload)
        return payload
    agnes_api_key = clean_text(env.get("AGNES_API_KEY") or env.get("AGNES_TOKEN"))
    ark_api_key = clean_text(env.get("ARK_API_KEY"))
    if provider == "auto":
        provider = "agnes" if agnes_api_key else ("seedance" if ark_api_key else "auto")
    if provider == "auto":
        payload = {
            "version": MOTION_CLIP_MANIFEST_VERSION,
            "status": "skipped",
            "provider": "auto",
            "reason": "未配置 Agnes 或 Seedance 视频 API，保留静态图轻运动",
            "clips": [],
            "updated_at": storage.now_ts(),
        }
        storage.write_json(project_motion_clip_manifest_path(project_id), payload)
        return payload
    if provider not in {"auto", "agnes", "agnes_video", "seedance", "ark"}:
        raise RuntimeError(f"动态镜头供应商 {provider} 暂未接入生产链路")
    if provider in {"agnes", "agnes_video"} and not agnes_api_key:
        raise RuntimeError("已启用 Agnes 动态镜头，但 AGNES_API_KEY 为空")
    if provider in {"seedance", "ark"} and not ark_api_key:
        raise RuntimeError("已启用 Seedance 动态镜头，但火山方舟 API Key 为空")

    scene_paths = find_scene_image_paths(project_id)
    if not scene_paths:
        raise RuntimeError("还没有场景图，动态镜头步骤需要先完成图片生成")
    try:
        requested_count = int(env.get("VIDEO_CLIP_COUNT") or 2)
    except (TypeError, ValueError):
        requested_count = 2
    try:
        duration = max(4, min(int(float(env.get("VIDEO_CLIP_DURATION_SECONDS") or 5)), 15))
    except (TypeError, ValueError):
        duration = 5
    resolution = clean_text(env.get("VIDEO_CLIP_RESOLUTION") or "720p").lower()
    if resolution not in {"480p", "720p", "1080p", "4k"}:
        resolution = "720p"
    timeout = configured_timeout_seconds(env, "VIDEO_CLIP_TIMEOUT_SECONDS", 1200, 300, 3600)
    use_agnes = provider in {"agnes", "agnes_video"}
    model = clean_text(
        env.get("AGNES_VIDEO_MODEL") or capsule_providers.DEFAULT_AGNES_VIDEO_MODEL
        if use_agnes
        else env.get("ARK_VIDEO_MODEL") or capsule_providers.DEFAULT_SEEDANCE_MODEL
    )
    base_url = clean_text(
        env.get("AGNES_BASE_URL") or capsule_providers.DEFAULT_AGNES_BASE_URL
        if use_agnes
        else env.get("ARK_BASE_URL") or capsule_providers.DEFAULT_ARK_BASE_URL
    )
    selected = select_motion_clip_scene_indexes(
        project_id,
        mode=mode,
        count=requested_count,
        scene_count=len(scene_paths),
    )
    scenes = load_scene_plan_entries(project_id)
    director_plans = {
        index: build_motion_clip_director_plan(
            project_id,
            index,
            scenes[index - 1] if index - 1 < len(scenes) else {},
            duration=duration,
        )
        for index in selected
    }
    storage.write_json(
        project_motion_director_plan_path(project_id),
        {
            "version": motion_director.MOTION_DIRECTOR_VERSION,
            "topic": clean_text(storage.get_project(project_id).get("topic_name")),
            "selected_scene_indexes": selected,
            "plans": [director_plans[index] for index in selected],
            "updated_at": storage.now_ts(),
        },
    )
    old_manifest = storage.read_json(project_motion_clip_manifest_path(project_id), {})
    old_clips = {
        int(item.get("scene_index", 0) or 0): item
        for item in (old_manifest.get("clips", []) if isinstance(old_manifest, dict) else [])
        if isinstance(item, dict)
    }
    records: list[dict[str, Any]] = []
    generated = 0
    reused = 0

    def save_motion_checkpoint(*, status: str, current_scene_index: int = 0, error: str = "") -> None:
        """Persist every completed clip so later failures resume from that clip."""
        storage.write_json(
            project_motion_clip_manifest_path(project_id),
            {
                "version": MOTION_CLIP_MANIFEST_VERSION,
                "director_version": motion_director.MOTION_DIRECTOR_VERSION,
                "status": status,
                "provider": "agnes" if use_agnes else "seedance",
                "model": model,
                "mode": mode,
                "selected_scene_indexes": selected,
                "current_scene_index": current_scene_index,
                "generated_count": generated,
                "reused_count": reused,
                "clips": sorted(records, key=lambda item: int(item.get("scene_index", 0) or 0)),
                "error": clean_text(error),
                "updated_at": storage.now_ts(),
            },
        )

    for position, index in enumerate(selected, start=1):
        image_path = scene_paths[index - 1]
        scene = scenes[index - 1] if index - 1 < len(scenes) else {}
        director_plan = director_plans[index]
        prompt = compact_visual_image_prompt(clean_text(director_plan.get("prompt")), 760)
        motion_image_path, information_typography = prepare_motion_information_keyframe(
            project_id,
            index,
            scene,
            image_path,
        )
        if information_typography.get("applied") and log:
            log(
                "[motion_clips] 已把当前口播主信息写入关键帧："
                f"{clean_text(str(information_typography.get('headline') or ''))}"
            )
        output_path = storage.project_file(project_id, f"video_clips/s_{index:02d}.mp4")
        fingerprint_payload = {
            "version": MOTION_CLIP_MANIFEST_VERSION,
            "director_version": motion_director.MOTION_DIRECTOR_VERSION,
            "provider": "agnes" if use_agnes else "seedance",
            "model": model,
            "source_hash": production_file_hash(image_path),
            "information_typography": {
                "headline": clean_text(str(information_typography.get("headline") or "")),
                "fact_chips": list(information_typography.get("fact_chips") or []),
            },
            "prompt": prompt,
            "duration": duration,
            "resolution": resolution,
        }
        fingerprint = hashlib.sha256(
            json.dumps(fingerprint_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        ).hexdigest()
        old = old_clips.get(index, {})
        if (
            not old
            and output_path.exists()
            and output_path.stat().st_size > 0
            and output_path.stat().st_mtime >= image_path.stat().st_mtime
            and safe_probe_duration(output_path) > 0
        ):
            recovered_duration = safe_probe_duration(output_path)
            recovered = {
                "scene_index": index,
                "filename": output_path.name,
                "relative_path": f"video_clips/{output_path.name}",
                "source_image": f"scenes/{image_path.name}",
                "fingerprint": fingerprint,
                "provider": "agnes" if use_agnes else "seedance",
                "model": model,
                "task_id": "",
                "duration_seconds": recovered_duration,
                "prompt": prompt,
                "director_plan": director_plan,
                "reused": True,
                "recovered_from_disk": True,
                "generated_at": output_path.stat().st_mtime,
            }
            reused += 1
            records.append(recovered)
            save_motion_checkpoint(status="generating", current_scene_index=index)
            if log:
                log(f"[motion_clips] 已从磁盘接回 {position}/{len(selected)}：s_{index:02d}.mp4，跳过重复生成")
            continue
        if (
            output_path.exists()
            and output_path.stat().st_size > 0
            and clean_text(old.get("fingerprint")) == fingerprint
            and safe_probe_duration(output_path) > 0
        ):
            reused += 1
            records.append({**old, "reused": True})
            if log:
                log(f"[motion_clips] 复用 {position}/{len(selected)}：s_{index:02d}.mp4")
            continue
        if log:
            log(f"[motion_clips] 开始 {position}/{len(selected)}：场景 {index} 图生视频")
        progress_callback = (
            (lambda message, scene_index=index: log(f"[motion_clips] 场景 {scene_index}：{message}"))
            if log
            else None
        )
        if log:
            log(f"[motion_clips] 场景 {index} 本次视频提示词：{prompt}")
            log("[motion_clips] 视频模型通过 API 在后台运行；进度、提示词和已完成片段会持续写入当前任务")
        save_motion_checkpoint(status="generating", current_scene_index=index)
        if use_agnes:
            result = capsule_providers.generate_agnes_i2v(
                prompt=prompt,
                image_path=motion_image_path,
                output_path=output_path,
                api_key=agnes_api_key,
                model=model,
                base_url=base_url,
                width=1152,
                height=648,
                num_frames=121,
                frame_rate=24,
                negative_prompt="镜头抖动，主体变形，改写或删除已有文字，新增文字，乱码，额外物体，画面闪烁，构图漂移",
                timeout=timeout,
                progress=progress_callback,
            )
        else:
            result = capsule_providers.generate_seedance_i2v(
                prompt=prompt,
                image_path=motion_image_path,
                output_path=output_path,
                api_key=ark_api_key,
                model=model,
                base_url=base_url,
                ratio="16:9",
                resolution=resolution,
                duration=duration,
                timeout=timeout,
                progress=progress_callback,
            )
        overlay_asset_value = clean_text(str(information_typography.get("overlay_asset_path") or ""))
        overlay_asset_path = Path(overlay_asset_value) if overlay_asset_value else None
        if overlay_asset_path is not None and overlay_asset_path.is_file():
            burn_motion_information_overlay(output_path, overlay_asset_path)
            if log:
                log("[motion_clips] 主信息图层已贯穿全部视频帧，文字不会被模型擦除或改写")
        strip_generated_video_audio(output_path)
        if log:
            log("[motion_clips] 已移除模型自带音轨，动态镜头只保留画面")
        clip_duration = safe_probe_duration(output_path)
        if clip_duration <= 0:
            output_path.unlink(missing_ok=True)
            raise RuntimeError(f"场景 {index} 的动态镜头文件无有效视频流")
        generated += 1
        records.append(
            {
                "scene_index": index,
                "filename": output_path.name,
                "relative_path": f"video_clips/{output_path.name}",
                "source_image": f"scenes/{image_path.name}",
                "fingerprint": fingerprint,
                "provider": result.get("provider", "volcengine_seedance"),
                "model": result.get("model", model),
                "task_id": result.get("task_id", ""),
                "duration_seconds": clip_duration,
                "prompt": prompt,
                "director_plan": director_plan,
                "reused": False,
                "generated_at": storage.now_ts(),
            }
        )
        save_motion_checkpoint(status="generating", current_scene_index=index)
        if log:
            log(f"[motion_clips] 完成场景 {index}：{clip_duration:.1f} 秒")
    payload = {
        "version": MOTION_CLIP_MANIFEST_VERSION,
        "director_version": motion_director.MOTION_DIRECTOR_VERSION,
        "status": "ready",
        "provider": "agnes" if use_agnes else "seedance",
        "model": model,
        "mode": mode,
        "selected_scene_indexes": selected,
        "generated_count": generated,
        "reused_count": reused,
        "clips": sorted(records, key=lambda item: int(item.get("scene_index", 0) or 0)),
        "updated_at": storage.now_ts(),
    }
    storage.write_json(project_motion_clip_manifest_path(project_id), payload)
    return payload


def current_motion_clip_paths(project_id: int) -> dict[int, Path]:
    manifest = storage.read_json(project_motion_clip_manifest_path(project_id), {})
    if not isinstance(manifest, dict) or manifest.get("status") != "ready":
        return {}
    result: dict[int, Path] = {}
    for item in manifest.get("clips", []):
        if not isinstance(item, dict):
            continue
        index = int(item.get("scene_index", 0) or 0)
        relative = clean_text(item.get("relative_path"))
        path = storage.project_file(project_id, relative) if relative else storage.project_file(project_id, f"video_clips/s_{index:02d}.mp4")
        if index > 0 and path.exists() and safe_probe_duration(path) > 0:
            result[index] = path
    return result




