def compact_style_hint_for_prompt(hint: str, fallback: str) -> str:
    text = clean_text(hint).replace("...", "").replace("…", "").strip("，,。；;:： ")
    if not text:
        return fallback
    for sep in ("；", ";", "。"):
        if sep in text:
            text = text.split(sep, 1)[0].strip("，,。；;:： ")
            break
    return clean_visual_brief_fragment(text, 48) or fallback


def channel_image_style_prompt(template: dict[str, Any] | None) -> str:
    """Return only the explicit channel-level image signature.

    The broader visual_strategy field remains editorial guidance. Keeping these
    separate prevents a channel identity from fixing the subjects or story of
    every episode.
    """
    return clean_text(str((template or {}).get("image_style_prompt") or ""))


def channel_image_strategy_prompt(template: dict[str, Any] | None) -> str:
    """Compile the editable channel visual strategy into a short enforceable rule."""
    strategy = clean_text(str((template or {}).get("visual_strategy") or ""))
    if not strategy:
        return ""
    clauses = [
        clean_text(item).strip("，,。；; ")
        for item in re.split(r"[。；;\n]+", strategy)
        if clean_text(item)
    ]
    priority_terms = ("口播", "信息", "主体", "画面", "数字", "证据", "对比", "字幕")
    ordered = sorted(
        enumerate(clauses),
        key=lambda pair: (
            -sum(1 for term in priority_terms if term in pair[1]),
            pair[0],
        ),
    )
    selected = [value for _, value in ordered[:3]]
    return _compact_complete_text("；".join(selected), 180)


def channel_image_negative_prompt(template: dict[str, Any] | None) -> str:
    return clean_text(str((template or {}).get("image_negative_prompt") or ""))


def channel_visual_palette_prompt(template: dict[str, Any] | None) -> str:
    palette = (template or {}).get("visual_palette")
    if isinstance(palette, dict):
        background = clean_text(str(palette.get("background") or ""))
        ink = clean_text(str(palette.get("ink") or ""))
        accents = "、".join(clean_text(str(item)) for item in palette.get("accents", []) if clean_text(str(item)))
        rule = clean_text(str(palette.get("rule") or ""))
        return "；".join(item for item in (background, ink, accents, rule) if item)
    return clean_text(str(palette or ""))


def channel_visual_contract(template: dict[str, Any] | None, purpose: str) -> str:
    """Short, final visual constraints that survive prompt compaction."""
    style = channel_image_style_prompt(template)
    material = (
        "固定为纸张线稿卡通：暖米白纸张、炭黑手绘线；砖红/靛蓝/芥末黄只做重点；禁止写实摄影、3D渲染、暗色控制台和霓虹"
        if "纸张" in style or "线稿" in style
        else "材质约束：保持频道既定材质、线条和颜色，不混入其它频道的主色或画风"
    )
    information = (
        "画面任务：一个主结论、两到四个当前口播事实、一个因果箭头；主体与信息共同占满画面，底部留字幕区"
        if purpose == "scene"
        else "信息结构：1个短主标题、1个支撑事实、1个冲突主体；标题与主体共同占满画面"
    )
    return f"{material}；{information}"


def normalize_prompt_for_channel_material(prompt: str, template: dict[str, Any] | None) -> str:
    """Recast stale scene recipes when a channel changes its visual material."""
    text = clean_text(prompt)
    style = channel_image_style_prompt(template)
    if "纸张" not in style and "线稿" not in style:
        return text
    replacements = {
        "哑光深蓝小矩形芯片格": "炭黑线稿小矩形参数格",
        "深蓝小矩形芯片格": "炭黑线稿小矩形参数格",
        "信号橙": "砖红与芥末黄平涂",
        "橙色模块": "被标记的参数格",
        "橙色激活节点": "砖红激活标记",
        "青色数据流": "手绘靛蓝箭头",
        "扁平数据线": "手绘靛蓝箭头",
        "成熟2D科技编辑卡通世界": "暖米白纸张线稿科技编辑卡通世界",
        "高质感2D科技编辑卡通": "成熟纸张线稿科技编辑卡通",
        "二维平面感和哑光材质": "暖米白纸纤维、炭黑线稿和轻微印刷网点",
    }
    for source, target in replacements.items():
        text = text.replace(source, target)
    return text


def channel_image_policy_signature(template: dict[str, Any] | None) -> str:
    payload = {
        "style": channel_image_style_prompt(template),
        "strategy": channel_image_strategy_prompt(template),
        "negative": channel_image_negative_prompt(template),
        "palette": channel_visual_palette_prompt(template),
        "forbidden_rules": clean_text(str((template or {}).get("forbidden_rules") or "")),
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()[:16]


def apply_channel_image_policy(prompt: str, template: dict[str, Any] | None, purpose: str) -> str:
    """Append channel policy after generic prompt cleanup so it cannot be lost."""
    prompt = normalize_prompt_for_channel_material(prompt, template)
    # The image model follows the first compact instructions much more
    # reliably than a long policy appended after the story.  Keep the channel
    # contract explicit but small, then reserve the remaining context for this
    # exact narration and its visual evidence.
    style = compact_prompt_rule(channel_image_style_prompt(template), 96)
    strategy = compact_prompt_rule(channel_image_strategy_prompt(template), 64)
    negative = compact_prompt_rule(channel_image_negative_prompt(template), 72)
    palette = compact_prompt_rule(channel_visual_palette_prompt(template), 96)
    contract = compact_prompt_rule(channel_visual_contract(template, purpose), 126)
    policies: list[str] = []
    if style and "频道固定画面风格：" not in prompt and "频道固定视觉签名" not in prompt:
        policies.append(
            f"频道固定视觉签名：{style}"
        )
    if strategy and "频道画面策略：" not in prompt:
        policies.append(f"频道画面策略：{strategy}")
    if palette and "频道固定色彩系统：" not in prompt:
        policies.append(f"频道固定色彩系统：{palette}")
    if negative and "频道禁止元素：" not in prompt:
        policies.append(f"频道禁止元素：{negative}")
    if contract and "频道视觉合同：" not in prompt:
        policies.append(f"频道视觉合同：{contract}")
    if not policies:
        return prompt

    policy_text = "。".join(policies)
    total_limit = 760 if purpose == "cover" else 700
    base_limit = max(250, total_limit - len(policy_text) - 2)
    base = compact_visual_image_prompt(prompt, base_limit).strip("。")
    return f"{policy_text}。本镜内容：{base}".strip("。")


def episode_visual_continuity_prompt(
    project_id: int,
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
) -> str:
    settings = storage.get_project_settings(project_id)
    anchor = clean_text(str(settings.get("auto_topic_prompt") or ""))
    if not anchor:
        topic = clean_text(str(project.get("topic_name") or first_heading(content) or ""))
        latin_entities = re.findall(r"\b[A-Za-z][A-Za-z0-9._-]{2,}(?:\s+[A-Za-z0-9._-]+)?\b", clean_text(f"{topic} {content}"))
        anchor = clean_text(latin_entities[0]) if latin_entities else topic
    anchor = compact_prompt_rule(anchor, 48) or "本期核心对象"
    style = channel_image_style_prompt(template)
    if _is_editorial_cartoon_style(style):
        palette = channel_visual_palette_prompt(template) or "同一频道主题色"
        return (
            f"同集连续：以「{anchor}」作贯穿线稿母题；保持同一纸张颗粒、炭黑线条和频道色彩（{compact_prompt_rule(palette, 78)}），"
            "只变本镜事实、动作和因果箭头。"
        )
    return (
        f"同集视觉连续性：以「{anchor}」为贯穿对象，保持同一主体设计、色彩系统和材质语言；"
        "每镜只改变口播对应的动作、证据关系和景别"
    )


