def active_source_references(project_id: int, references: list[dict[str, Any]] | None = None) -> list[dict[str, Any]]:
    source_references = storage.get_references(project_id) if references is None and project_id else (references or [])
    result: list[dict[str, Any]] = []
    for item in source_references:
        if not isinstance(item, dict):
            continue
        source_name = clean_text(str(item.get("source") or ""))
        source_url = clean_text(str(item.get("url") or ""))
        if source_name in {"历史稿", "历史内容"}:
            continue
        if re.search(r"[/\\]data[/\\]projects[/\\]\d+[/\\]content\.md$", source_url, flags=re.IGNORECASE):
            continue
        text = " ".join(
            clean_text(str(item.get(field) or ""))
            for field in ("title", "summary", "snippet", "content")
        )
        if text:
            result.append(item)
    return result


def source_information_signature(project_id: int, references: list[dict[str, Any]] | None = None) -> str:
    payload = [
        {
            "title": clean_text(str(item.get("title") or "")),
            "url": clean_text(str(item.get("url") or "")),
            "source": clean_text(str(item.get("source") or "")),
            "summary": clean_text(str(item.get("summary") or "")),
            "snippet": clean_text(str(item.get("snippet") or "")),
        }
        for item in active_source_references(project_id, references)
    ]
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8", errors="ignore")
    return hashlib.sha256(encoded).hexdigest()[:16]


def clean_source_information_text(value: str) -> str:
    text = html.unescape(str(value or ""))
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", " ", text)
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"https?://\S+", " ", text)
    text = re.sub(r"^[#>*\-\s]+", "", text)
    text = re.sub(r"\s+", " ", text)
    return clean_text(text).strip(" -—|，。；:：")


def split_source_information_clauses(value: str) -> list[str]:
    text = clean_source_information_text(value)
    if not text:
        return []
    raw_parts = re.split(r"[。！？!?；;\n]+|(?<!\d)\.(?!\d)", text)
    clauses: list[str] = []
    for raw in raw_parts:
        candidate = clean_source_information_text(raw)
        if len(candidate) > 150:
            subparts = re.split(r"[,，]\s*", candidate)
        else:
            subparts = [candidate]
        for subpart in subparts:
            clause = clean_source_information_text(subpart)
            if len(clause) < 10 or len(clause) > 170:
                continue
            if _contains_any(clause.lower(), SOURCE_INFORMATION_NOISE_TERMS):
                continue
            if clause not in clauses:
                clauses.append(clause)
    return clauses


def source_information_match_score(candidate: str, target: str) -> int:
    left = clean_text(candidate).lower()
    right = clean_text(target).lower()
    if not left or not right:
        return 0
    left_tokens = set(semantic_tokens(left, limit=80))
    right_tokens = set(semantic_tokens(right, limit=80))
    token_hits = len(left_tokens.intersection(right_tokens))

    def cjk_ngrams(text: str) -> set[str]:
        grams: set[str] = set()
        for chunk in re.findall(r"[\u4e00-\u9fff]{3,}", text):
            for width in (2, 3):
                grams.update(chunk[index : index + width] for index in range(max(0, len(chunk) - width + 1)))
        return grams

    left_grams = cjk_ngrams(left)
    right_grams = cjk_ngrams(right)
    gram_hits = len(left_grams.intersection(right_grams))
    gram_base = max(1, min(len(left_grams), len(right_grams), 36))
    numeric_bonus = 0
    left_facts = {
        normalized_numeric_fact(item)
        for item in extract_numeric_fact_tokens(left)
        if normalized_numeric_fact(item)
    }
    right_facts = {
        normalized_numeric_fact(item)
        for item in extract_numeric_fact_tokens(right)
        if normalized_numeric_fact(item)
    }
    shared_facts = left_facts.intersection(right_facts)
    strong_shared_facts = {
        fact
        for fact in shared_facts
        if len(re.sub(r"\D", "", fact)) >= 2
        or bool(re.search(r"%|元|块|万|亿|小时|分钟|秒|年|月|天|次|倍|gb|mb", fact, flags=re.IGNORECASE))
    }
    if strong_shared_facts:
        numeric_bonus = 18
    synonym_bonus = sum(
        22
        for group in SOURCE_INFORMATION_SYNONYM_GROUPS
        if any(term in left for term in group) and any(term in right for term in group)
    )
    score = token_hits * 14 + int(round((gram_hits / gram_base) * 70)) + numeric_bonus + synonym_bonus
    return int(clamp_number(score, 0, 100))


def source_information_mode(value: str) -> str:
    text = clean_text(value)
    if extract_numeric_fact_tokens(text) or re.search(r"\d+(?:\.\d+)?\s*(?:%|元|块|万|亿|小时|分钟|秒|次|倍|GB|MB)", text, flags=re.IGNORECASE):
        return "data"
    if _contains_any(text, ("相比", "对比", "而是", "却", "反而", "高于", "低于", "只有", "前后", "差距")):
        return "comparison"
    if _contains_any(text, ("因为", "导致", "所以", "意味着", "原因", "来自", "结果", "从而")):
        return "cause_effect"
    if _contains_any(text, ("第一", "第二", "第三", "步骤", "先", "再", "最后", "方法")):
        return "steps"
    if _contains_any(text, ("原理", "协议", "算法", "机制", "通过", "工作台", "系统", "芯片", "流程")):
        return "mechanism"
    if _contains_any(text, ("风险", "损坏", "后悔", "维修", "脆弱", "故障", "陷阱", "警惕")):
        return "risk"
    return "evidence"


def scene_information_headline(speech: str) -> str:
    text = clean_scene_spoken_text(speech).strip("「」“”\"'，。；:： ")
    if not text:
        return "本镜核心结论"
    compact = re.sub(r"\s+", "", text)
    patterns: tuple[tuple[str, Callable[[re.Match[str]], str]], ...] = (
        (
            r"总参数(?P<total>\d+(?:\.\d+)?\s*[A-Za-z]*)[^。！？]{0,24}?(?:只醒|只激活|激活)(?P<active>\d+(?:\.\d+)?\s*[A-Za-z]*)",
            lambda match: f"{match.group('total')}总参数，只醒{match.group('active')}",
        ),
        (
            r"(?:屏幕里)?疯狂塞功能",
            lambda _match: "功能越塞越多",
        ),
        (
            r"买车前别只看(?P<object>芯片型号|参数|配置|品牌)",
            lambda match: f"买车别只看{match.group('object')}",
        ),
        (
            r"只用来(?P<items>[^。！？]{2,24})",
            lambda match: f"只剩{match.group('items')}",
        ),
        (
            r"(?P<object>[^，。！？]{0,8}(?:倒车影像|屏幕|车机|手机|手表|耳机|电视))(?P<state>黑屏|卡顿|掉帧|失效|死机|发热|变慢)",
            lambda match: f"{match.group('object')}{match.group('state')}",
        ),
        (
            r"(?P<object>[A-Za-z0-9\u4e00-\u9fff]{2,10})(?:这颗|这个|这台)?被(?P<state>吹上天|夸大|高估)",
            lambda match: (
                f"{match.group('object').removesuffix('这颗').removesuffix('这个').removesuffix('这台')}"
                f"被{match.group('state')}"
            ),
        ),
        (
            r"新车[^。！？]{0,16}(?:好几年前|旧芯片|老芯片)",
            lambda _match: "新车配旧芯",
        ),
        (
            r"(?P<period>一个月|每月|每个月)[^。！？]{0,12}(?P<action>重启[^，。！？]{0,6})",
            lambda match: f"{match.group('period')}{match.group('action')}",
        ),
        (
            r"(?P<action>切换[^，。！？]{0,10}(?:掉帧|卡顿))",
            lambda match: match.group("action"),
        ),
    )
    for pattern, formatter in patterns:
        match = re.search(pattern, compact, flags=re.IGNORECASE)
        if match:
            headline = clean_text(formatter(match)).strip("，。；:： ")
            if headline:
                return headline

    clauses = [
        clean_text(item).strip("「」“”\"'，。；:： ")
        for item in re.split(r"[。！？；;]+|(?<=，)", text)
        if clean_text(item).strip("「」“”\"'，。；:： ")
    ]
    scored: list[tuple[int, str]] = []
    for clause in clauses:
        cleaned = re.sub(r"^(?:你以为|其实|结果|所以|但是|然后|为什么|先别急|我发现)", "", clause).strip("，。；:： ")
        if len(cleaned) < 4:
            continue
        score = 0
        if extract_numeric_fact_tokens(cleaned):
            score += 5
        if _contains_any(cleaned, ("黑屏", "掉帧", "卡顿", "变慢", "只用", "结果", "反而", "风险", "后悔", "真相", "失效", "省下", "多花")):
            score += 6
        if 5 <= len(cleaned) <= 18:
            score += 4
        score += min(4, len(semantic_tokens(cleaned, limit=8)))
        scored.append((score, cleaned))
    candidate = max(scored, default=(0, text), key=lambda item: (item[0], -len(item[1])))[1]
    candidate = re.sub(r"^(?:你以为|其实|结果|所以|但是|然后|为什么|先别急|我发现)", "", candidate).strip("，。；:： ")
    return candidate


def scene_information_fact_chips(speech: str, headline: str = "", limit: int = 6) -> list[str]:
    text = clean_scene_spoken_text(speech).strip("「」“”\"'，。；:： ")
    chips: list[str] = []
    for raw in re.findall(
        r"\d+(?:\.\d+)?\s*(?:%|％|B|M|K|GB|MB|TB|秒|分钟|小时|天|倍|元|块|万|亿)",
        text,
        flags=re.IGNORECASE,
    ):
        value = re.sub(r"\s+", "", clean_text(raw))
        if value and value not in headline and value not in chips:
            chips.append(value)
        if len(chips) >= limit:
            return chips[:limit]
    list_source = ""
    if "：" in text or ":" in text:
        list_source = re.split(r"[：:]", text, maxsplit=1)[-1]
    if list_source:
        for raw in re.split(r"[、，,；;…]+", list_source):
            value = clean_text(raw).strip("「」“”\"'，。；:： ")
            value = re.sub(r"^(?:还有|以及|包括|例如|比如)", "", value).strip()
            if (
                2 <= len(value) <= 10
                and not value.endswith(("是什么", "为什么", "怎么办"))
                and value not in headline
                and value not in chips
            ):
                chips.append(value)
            if len(chips) >= limit:
                return chips[:limit]
    for item in extract_scene_readable_callouts(text, limit=max(8, limit * 2)):
        value = clean_text(item).strip("「」“”\"'，。；:： ")
        if value and value not in chips and value not in headline:
            chips.append(value)
    relation_phrases = (
        ("黑屏", "黑屏"),
        ("掉帧", "掉帧"),
        ("降频", "降频"),
        ("自启动", "自启动"),
        ("重启", "重启"),
        ("折痕", "折痕"),
        ("维修", "维修"),
        ("不可逆", "不可逆"),
        ("塑料薄膜", "塑料内屏"),
        ("适配", "软件适配"),
        ("只用来导航", "导航"),
        ("听歌", "听歌"),
        ("调空调", "空调"),
        ("3D地图", "3D地图"),
        ("动态壁纸", "动态壁纸"),
        ("应用商店", "应用商店"),
        ("点外卖", "点外卖"),
        ("看视频", "看视频"),
        ("KTV", "KTV"),
        ("系统更新策略", "更新策略"),
        ("芯片型号", "芯片型号"),
    )
    for token, label in relation_phrases:
        if token in text and label not in headline and label not in chips:
            chips.append(label)
        if len(chips) >= limit:
            break
    return chips[:limit]


def source_information_candidates(
    project_id: int,
    *,
    topic: str,
    content: str,
    references: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    episode_target = clean_text(
        " ".join(
            filter(
                None,
                [
                    topic,
                    extract_bullet_field(content, "核心观点"),
                    extract_bullet_field(content, "反常识点"),
                    extract_bullet_field(content, "钩子"),
                    content[:2200],
                ],
            )
        )
    )
    candidates: list[dict[str, Any]] = []
    for source_index, item in enumerate(active_source_references(project_id, references), start=1):
        title = clean_source_information_text(str(item.get("title") or "")) or f"资料 {source_index}"
        source_name = clean_text(str(item.get("source") or "资料来源"))
        source_text = "。".join(
            clean_text(str(item.get(field) or ""))
            for field in ("title", "summary", "snippet", "content")
            if clean_text(str(item.get(field) or ""))
        )
        reference_relevance = source_information_match_score(f"{title} {source_text[:600]}", episode_target)
        if reference_relevance < 12:
            continue
        for clause in split_source_information_clauses(source_text):
            comparable_clause = re.sub(r"\s+", "", clause).lower()
            comparable_title = re.sub(r"\s+", "", title).lower()
            if comparable_clause == comparable_title or (
                len(comparable_clause) >= 18
                and (comparable_title.startswith(comparable_clause) or comparable_clause.startswith(comparable_title))
            ):
                continue
            if clause.endswith(("…", "...")) or _contains_any(clause, ("来自北京", "打开各家品牌官网")):
                continue
            episode_relevance = max(reference_relevance, source_information_match_score(clause, episode_target))
            if episode_relevance < 16:
                continue
            candidates.append(
                {
                    "text": clause,
                    "mode": source_information_mode(clause),
                    "source_title": title,
                    "source_name": source_name,
                    "source_url": clean_text(str(item.get("url") or "")),
                    "episode_relevance": episode_relevance,
                }
            )
    candidates.sort(key=lambda item: (-int(item.get("episode_relevance") or 0), len(str(item.get("text") or ""))))
    return candidates[:64]


def script_context_evidence_candidates(content: str, speech: str, *, limit: int = 3) -> list[dict[str, Any]]:
    """Use nearby final-script lines when external source snippets do not cover this scene."""
    section = extract_section(content, "口播脚本", level=2) or extract_section(content, "对话脚本", level=2)
    spoken = clean_scene_spoken_text(speech)
    if not section or not spoken:
        return []

    clauses: list[str] = []
    for raw_line in section.splitlines():
        line = re.sub(r"^\s*(?:[-*]\s*)?(?:【[^】]{1,12}】\s*)+", "", raw_line).strip()
        if not line:
            continue
        for clause in split_source_information_clauses(line):
            cleaned = clean_scene_spoken_text(clause)
            if cleaned and cleaned not in clauses:
                clauses.append(cleaned)
    if not clauses:
        return []

    best_index = max(
        range(len(clauses)),
        key=lambda index: (
            source_information_match_score(clauses[index], spoken),
            difflib.SequenceMatcher(None, clauses[index], spoken).ratio(),
        ),
    )
    result: list[dict[str, Any]] = []
    for index in range(best_index, min(len(clauses), best_index + max(4, limit + 2))):
        clause = clauses[index]
        similarity = difflib.SequenceMatcher(None, clause, spoken).ratio()
        if clause in spoken or similarity >= 0.82:
            continue
        score = max(28, source_information_match_score(clause, spoken))
        result.append(
            {
                "text": clause,
                "mode": source_information_mode(clause),
                "source_title": "当前最终口播",
                "source_name": "口播上下文",
                "source_url": "",
                "episode_relevance": score,
                "scene_relevance": score,
                "grounding": "script_context",
            }
        )
        if len(result) >= max(1, int(limit or 1)):
            break
    return result


def source_information_has_scene_subject_overlap(clause: str, target: str) -> bool:
    """Reject source snippets that only share a date or a generic word.

    The previous scorer could match an unrelated police report to a software
    vulnerability scene merely because both mentioned “2026”.  Chinese bigrams
    preserve domain subjects without requiring an external tokenizer.
    """

    generic = {
        "数据",
        "记录",
        "发现",
        "结果",
        "问题",
        "情况",
        "时间",
        "今年",
        "去年",
        "通过",
        "使用",
        "用户",
        "相关",
        "已经",
        "超过",
        "接近",
        "美国",
        "国家",
    }

    def informative_terms(value: str) -> set[str]:
        text = clean_text(value).lower()
        terms = {
            token
            for token in re.findall(r"[a-z][a-z0-9_.+-]{2,}", text)
            if token not in {"http", "https", "www", "com"}
        }
        for run in re.findall(r"[\u4e00-\u9fff]{2,}", text):
            terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
            if 2 <= len(run) <= 8:
                terms.add(run)
        return {term for term in terms if term not in generic and not re.fullmatch(r"\d+", term)}

    clause_terms = informative_terms(clause)
    target_terms = informative_terms(target)
    return bool(clause_terms.intersection(target_terms))


def scene_source_information_payload(
    project_id: int,
    *,
    topic: str,
    speech: str,
    content: str,
    candidates: list[dict[str, Any]] | None = None,
    limit: int = 3,
) -> dict[str, Any]:
    spoken = clean_scene_spoken_text(speech) or clean_text(speech)
    primary_message = summarize_scene_text((spoken or topic).strip("「」“”\"'，。；:： "), 72)
    source_candidates = candidates if isinstance(candidates, list) else source_information_candidates(
        project_id,
        topic=topic,
        content=content,
    )
    target = clean_text(f"{topic} {spoken}")
    ranked: list[tuple[int, dict[str, Any]]] = []
    for item in source_candidates:
        clause = clean_text(str(item.get("text") or ""))
        source_subject_text = clean_text(
            f"{item.get('source_title', '')} {item.get('source_name', '')} {clause}"
        )
        if spoken and not source_information_has_scene_subject_overlap(source_subject_text, target):
            continue
        scene_relevance = source_information_match_score(clause, spoken or target)
        if scene_relevance < (18 if spoken else 22):
            continue
        total_score = int(round(scene_relevance * 0.78 + int(item.get("episode_relevance") or 0) * 0.22))
        ranked.append((total_score, item))
    ranked.sort(key=lambda pair: (-pair[0], len(str(pair[1].get("text") or ""))))

    selected: list[dict[str, Any]] = []
    for score, item in ranked:
        clause = clean_text(str(item.get("text") or ""))
        if any(difflib.SequenceMatcher(None, clause, str(existing.get("text") or "")).ratio() >= 0.78 for existing in selected):
            continue
        selected.append({**item, "scene_relevance": score})
        if len(selected) >= max(1, int(limit or 1)):
            break
    grounding = "references" if selected else "speech"
    if not selected:
        selected = script_context_evidence_candidates(content, spoken, limit=limit)
        if selected:
            grounding = "script_context"

    mode_counts = Counter(clean_text(str(item.get("mode") or "evidence")) for item in selected)
    information_mode = mode_counts.most_common(1)[0][0] if mode_counts else source_information_mode(spoken)

    def audio_safe_evidence(value: str) -> str:
        clause = clean_text(value)
        pattern = re.compile(
            r"(?P<amount>\d+(?:\.\d+)?|[一二两三四五六七八九十百千万半]+)\s*"
            r"(?P<unit>%|％|毫米|厘米|小时|分钟|秒|年|个月|月|天|元|块|万元|亿元|倍|次|GB|MB)",
            flags=re.IGNORECASE,
        )

        def replace(match: re.Match[str]) -> str:
            raw = clean_text(match.group(0))
            if raw and raw in spoken:
                return raw
            unit = clean_text(match.group("unit")).lower()
            if unit in {"毫米", "厘米"}:
                return "一点"
            if unit in {"小时", "分钟", "秒"}:
                return "一些时间"
            if unit in {"年", "个月", "月", "天"}:
                return "一段时间"
            if unit in {"元", "块", "万元", "亿元"}:
                return "一笔费用"
            if unit in {"%", "％"}:
                return "明显比例"
            return "一些"

        clause = pattern.sub(replace, clause)
        return re.sub(r"(一些|一段时间|一点){2,}", r"\1", clause)

    supporting_evidence = [
        summarize_scene_text(
            (
                clean_text(str(item.get("text") or ""))
                if clean_text(str(item.get("grounding") or "")) == "script_context"
                else audio_safe_evidence(str(item.get("text") or ""))
            ),
            96,
        )
        for item in selected
        if clean_text(str(item.get("text") or ""))
    ]
    source_labels = dedupe_clauses(
        [
            clean_text(str(item.get("source_title") or item.get("source_name") or "资料来源"))
            for item in selected
            if clean_text(str(item.get("source_title") or item.get("source_name") or ""))
        ]
    )
    headline = scene_information_headline(spoken or primary_message)
    fact_chips = scene_information_fact_chips(spoken or primary_message, headline=headline)
    required_text = dedupe_clauses([headline, *fact_chips])
    return {
        "policy_version": SOURCE_INFORMATION_POLICY_VERSION,
        "primary_message": primary_message,
        "information_mode": information_mode,
        "visual_relation": SOURCE_INFORMATION_RELATIONS.get(information_mode, SOURCE_INFORMATION_RELATIONS["evidence"]),
        "supporting_evidence": supporting_evidence,
        "source_labels": source_labels,
        "source_trace": [
            {
                "title": clean_text(str(item.get("source_title") or "")),
                "source": clean_text(str(item.get("source_name") or "")),
                "url": clean_text(str(item.get("source_url") or "")),
                "excerpt": clean_text(str(item.get("text") or "")),
                "relevance": int(item.get("scene_relevance") or 0),
            }
            for item in selected
        ],
        "visual_copy": {
            "headline": headline,
            "fact_chips": fact_chips,
            "required_text": required_text,
            "silent_viewing_question": "观众静音看图，能立刻说出这一镜的结论、对象和证据",
        },
        "grounding": grounding,
    }


def scene_prompt_speech_anchor(prompt: str) -> str:
    source = normalize_image_prompt(prompt)
    quoted = re.search(r"口播原文\s*[:：]\s*「([^」]+)」", source)
    if quoted:
        return clean_scene_spoken_text(quoted.group(1))
    match = re.search(
        r"口播原文\s*[:：]\s*[「“\"]?(.*?)[」”\"]?(?=[，,。；;]\s*(?:画面任务|本镜任务|本镜信息任务|主体|主主体|动作|冲突|冲突/悬念|镜头视角|影像质感|频道质感)\s*[:：]|$)",
        source,
    )
    if match:
        return clean_scene_spoken_text(match.group(1))
    return clean_scene_spoken_text(
        extract_prompt_dialogue_hint_full(source)
        or extract_prompt_dialogue_hint(source, 180)
    )


def source_information_prompt_clauses(payload: dict[str, Any]) -> list[str]:
    if not isinstance(payload, dict):
        return []
    primary = clean_text(str(payload.get("primary_message") or ""))
    relation = clean_text(str(payload.get("visual_relation") or ""))
    evidence = [
        clean_text(str(item))
        for item in payload.get("supporting_evidence", [])
        if clean_text(str(item))
    ]
    visual_copy = payload.get("visual_copy") if isinstance(payload.get("visual_copy"), dict) else {}
    headline = clean_text(str(visual_copy.get("headline") or ""))
    fact_chips = [
        clean_text(str(item))
        for item in visual_copy.get("fact_chips", [])
        if clean_text(str(item))
    ]
    clauses: list[str] = []
    if primary:
        clauses.append(f"本镜信息任务：以「{primary}」为主信息，把对象、动作、证据和结果组织成一眼可读的画面")
    if evidence:
        clauses.append(f"来源支撑信息：{'；'.join(evidence[:3])}")
    else:
        clauses.append(f"口播事实支撑：{primary}")
    if relation:
        clauses.append(f"可视化关系：{relation}")
    if headline:
        clauses.append(
            f"画面原生文字：由生图模型直接把「{headline}」完整、清晰地写进图片并与主体物件融合；"
            "允许按构图自然换行，不得截断或由程序另盖标题"
        )
    if fact_chips:
        clauses.append(
            f"必须呈现的事实词：{'、'.join(fact_chips)}；由生图模型按当前口播关系原生组织成数据、对比、步骤或证据批注"
        )
    clauses.append(
        "信息构图模式：文字、关键物件与关系证据一次生成并共同构成画面；"
        "主结论负责第一眼抓人，完整说明与事实词组成后续阅读层，文字字数和数量不设统一上限，"
        "避免空场景、单独产品照、只有情绪人物或大面积无信息背景"
    )
    clauses.append("静音验收：观众只看图片也能立刻说出这一镜的结论、对象和证据；只有物体、人物或氛围而没有结论的画面视为未完成")
    clauses.append("来源边界：主结论必须直接呼应当前口播；来源信息只做支撑，不引入无关主题，不把资料全文或长链接画进图片")
    return clauses


def extract_source_information_prompt_clauses(prompt: str) -> list[str]:
    prefixes = (
        "本镜信息任务：",
        "来源支撑信息：",
        "口播事实支撑：",
        "可视化关系：",
        "画面主信息：",
        "画面原生文字：",
        "必须呈现的事实词：",
        "信息构图模式：",
        "静音验收：",
        "来源边界：",
    )
    clauses: list[str] = []
    for raw in re.split(r"[。\n]+", normalize_image_prompt(prompt)):
        clause = clean_text(raw)
        if clause and any(clause.startswith(prefix) for prefix in prefixes) and clause not in clauses:
            clauses.append(clause)
    return clauses[:9]


def expand_scene_speech_anchor(content: str, mode: str, anchor: str, max_chars: int = 132) -> str:
    """Recover a short continuation line that belongs to the selected narration.

    Script writers often put a benchmark or conclusion on the next speaker line.
    Treating that line as a separate scene drops the relationship that makes the
    image meaningful, for example “4.5万个漏洞 / 接近去年全年总和”.
    """

    source = clean_text(anchor)
    if not source:
        return ""
    dialogue = [
        clean_text(strip_dialogue_speaker(item))
        for item in parse_dialogue_lines(content_without_image_prompts(content) or content, mode)
        if clean_text(strip_dialogue_speaker(item))
    ]
    if not dialogue:
        return source[:max_chars]
    best_index = max(
        range(len(dialogue)),
        key=lambda idx: token_overlap_score(source, dialogue[idx], limit=80),
    )
    if token_overlap_score(source, dialogue[best_index], limit=80) < 35:
        return source[:max_chars]
    base = dialogue[best_index]
    continuation = re.compile(
        r"^(?:接近|逼近|相当于|达到|超过|这意味着|也就是说|换句话说|其中|而且|结果|但|却|甚至|因此)"
    )
    previous_link = re.compile(r"^(?:接近|逼近|相当于|达到|超过|这意味着|也就是说|其中|结果)")
    parts = [base]
    if previous_link.search(base) and best_index > 0:
        candidate = dialogue[best_index - 1]
        if len(candidate) <= 92:
            parts.insert(0, candidate)
    if best_index + 1 < len(dialogue):
        candidate = dialogue[best_index + 1]
        if continuation.search(candidate) and len(candidate) <= 52:
            parts.append(candidate)
    return clean_text("。".join(item.strip("。！？； ") for item in parts if item))[:max_chars]


def build_content_scene_prompt_lines(project: dict[str, Any], template: dict[str, Any], content: str) -> list[str]:
    mode = clean_text(template.get("mode") or project.get("template_mode") or "video")
    visual_content = content_without_image_prompts(content)
    topic = clean_text(first_heading(visual_content or content) or project.get("topic_name") or "本期主题")
    style_source = "\n".join(
        filter(
            None,
            [
                topic,
                extract_bullet_field(visual_content, "核心观点"),
                extract_bullet_field(visual_content, "反常识点"),
                extract_bullet_field(visual_content, "人物或场景锚点"),
                extract_bullet_field(visual_content, "新比喻或新意象"),
                product_facts_prompt_block(project),
                visual_content[:1600],
            ],
        )
    )
    style = classify_material_style(style_source, template, "scene")
    domain = classify_visual_prompt_domain(style_source, "scene")
    scene_count_info = resolve_project_scene_count(project, visual_content or content, mode)
    desired_count = clamp_scene_count(scene_count_info.get("final", 0), 4 if mode == "article" else 6)
    desired_count = effective_visual_scene_count(project, desired_count) or desired_count
    # Once audio has produced a fresh scene plan, it is the authoritative
    # source for image prompts.  Re-deriving anchors from the article here used
    # to shift later scenes forward (and duplicate early narration), breaking
    # the relationship between voice, subtitle and picture.
    project_id = int(project.get("id") or 0)
    if project_id:
        planned_prompts = timeline_scene_prompts(project_id)
        if planned_prompts:
            return normalize_scene_prompt_count(
                planned_prompts,
                desired_count,
                topic,
                mode,
            )
    beats = derive_content_scene_beats(visual_content or content, mode, topic, style=style, source=style_source, desired_count=desired_count)
    total = len(beats)
    dialogue_anchors = select_dialogue_scene_anchors(visual_content or content, mode, max(total, 1), limit=78)
    visual_brief = get_or_create_visual_brief(
        project,
        template,
        visual_content or content,
        scene_count=total,
        beats=beats,
        dialogue_anchors=dialogue_anchors,
    )
    lines: list[str] = []
    for idx, beat in enumerate(beats, start=1):
        visual_type = infer_visual_type(beat, beat)
        narrative = narrative_state_for_scene(idx, total)
        focus = refine_scene_focus_text(beat, visual_content or content, style, domain, visual_type, narrative)
        dialogue_anchor = dialogue_anchors[min(idx - 1, len(dialogue_anchors) - 1)] if dialogue_anchors else beat
        dialogue_anchor = expand_scene_speech_anchor(visual_content or content, mode, dialogue_anchor)
        channel_hints = channel_visual_binding_hints(template, f"{topic}\n{beat}\n{dialogue_anchor}")
        if channel_hints:
            subject_hints = [
                *channel_hints,
                *generic_scene_grounding_hints(narrative, visual_type),
            ]
        else:
            subject_hints = scene_subject_priority_hints(
                style,
                domain,
                visual_type,
                narrative,
                f"{topic}\n{beat}\n{dialogue_anchor}\n{visual_content[:900]}",
            )
        subject_rules = dedupe_clauses(
            [compact_prompt_rule(item, 58) for item in subject_hints if clean_text(item)]
        )[:2]
        director_hint = visual_director_scene_hint(visual_brief, idx)
        concrete_hint = director_hint or concrete_visual_hint_from_anchor(
            focus or dialogue_anchor,
            f"{topic}\n{beat}\n{dialogue_anchor}\n{visual_content[:600]}",
            "scene",
        )
        task_clause = f"画面任务：{focus}" if focus else ""
        if focus and dialogue_anchor and token_overlap_score(focus, dialogue_anchor, limit=40) >= 80:
            task_clause = ""
        clauses = [
            f"主题：{topic}",
            f"口播原文：{dialogue_anchor}",
            product_visual_prompt_block(project, purpose="scene", index=idx, total=total),
            task_clause,
            concrete_hint,
            f"镜头视角：{scene_viewpoint_hint(idx, total, visual_type)}",
            scene_variety_directive(idx, total, narrative, visual_type),
            f"影像质感：{compact_prompt_rule(content_scene_style_hint(style, template), 42)}",
            project_visual_text_language_rule(project, "scene"),
        ]
        line = compact_prompt_rule(
            "，".join(dedupe_clauses([item for item in clauses if clean_text(item)])),
            520 if project_is_product_mode(project) else 300,
        )
        line = line.replace("...", "").replace("…", "").strip("，,。") + "。"
        lines.append(line)
    return lines


def build_content_cover_prompt(project: dict[str, Any], template: dict[str, Any], content: str, kind: str) -> str:
    mode = clean_text(template.get("mode") or project.get("template_mode") or "video")
    visual_content = content_without_image_prompts(content)
    topic = clean_text(first_heading(visual_content or content) or project.get("topic_name") or "本期主题")
    summary = summarize_content(visual_content or content, mode)
    cover_title = clean_text(summary.get("cover_title") or first_heading(content) or topic)
    cover_short_title = compact_cover_title_for_prompt(cover_title, topic)
    subtitle = clean_text(summary.get("cover_subtitle") or extract_bullet_field(visual_content, "封面副标题"))
    brand = clean_text(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")
    style_source = "\n".join(
        filter(
            None,
            [
                topic,
                cover_title,
                subtitle,
                extract_bullet_field(visual_content, "钩子"),
                extract_bullet_field(visual_content, "核心观点"),
                extract_bullet_field(visual_content, "反常识点"),
                product_facts_prompt_block(project),
            ],
        )
    )
    style = classify_material_style(style_source, template, "cover")
    domain = classify_visual_prompt_domain(style_source, "cover")
    visual_brief = get_or_create_visual_brief(
        project,
        template,
        visual_content or content,
        scene_count=effective_visual_scene_count(
            project,
            int(resolve_project_scene_count(project, visual_content or content, mode).get("final", 0) or 0),
        ),
    )
    cover_anchor = clean_text(
        extract_bullet_field(visual_content, "核心观点")
        or extract_bullet_field(visual_content, "反常识点")
        or extract_bullet_field(visual_content, "钩子")
        or cover_title
        or topic
    )
    channel_hints = channel_visual_binding_hints(template, f"{topic}\n{cover_title}\n{subtitle}\n{cover_anchor}")
    if channel_hints:
        subject_hints = [
            *channel_hints,
            *generic_cover_grounding_hints(),
        ]
    else:
        subject_hints = cover_subject_priority_hints(style, domain, f"{topic}\n{cover_title}\n{subtitle}\n{content[:900]}")
    focus_candidates = [
        subtitle,
        extract_bullet_field(visual_content, "核心观点"),
        extract_bullet_field(visual_content, "反常识点"),
        extract_bullet_field(visual_content, "人物或场景锚点"),
        extract_bullet_field(visual_content, "新比喻或新意象"),
        extract_bullet_field(visual_content, "前3秒视觉钩子"),
        extract_bullet_field(visual_content, "钩子"),
    ]
    if style == "elder_life" and classify_elder_life_topic_kind(style_source) == "network_hotword":
        focus_candidates = [
            item
            for item in focus_candidates
            if clean_text(item) and not is_elder_life_offtopic_antifraud_text(item)
        ]
    focus_candidates.extend(derive_content_scene_beats(visual_content or content, mode, topic, style=style, source=style_source)[:3])
    focuses = dedupe_clauses([compact_cover_focus_text(item, style, domain, 50) for item in focus_candidates if clean_text(item)])
    director_cover_hint = visual_director_cover_hint(visual_brief)
    concrete_hint = director_cover_hint or concrete_visual_hint_from_anchor(
        (focuses[0] if focuses else "") or cover_anchor or cover_title or topic,
        f"{topic}\n{cover_title}\n{subtitle}\n{cover_anchor}\n{visual_content[:600]}",
        "cover",
    )
    subject_rules = dedupe_clauses(
        [compact_prompt_rule(item, 58) for item in subject_hints if clean_text(item)]
    )[:2]

    clauses = [
        f"主题：{topic}",
        f"封面任务：{focuses[0]}" if focuses else f"封面任务：{cover_title or topic}",
        product_visual_prompt_block(project, purpose="cover"),
        visual_director_cover_clause(visual_brief),
        concrete_hint,
        f"封面版式：{cover_variant_layout_hint(kind)}",
        f"影像质感：{compact_prompt_rule(content_cover_style_hint(style, template), 52)}",
        "主体突出，明暗与色彩对比清楚，第一眼有冲突或悬念",
    ]
    clauses.extend(subject_rules)
    if cover_anchor:
        clauses.append(f"封面钩子锚点：{cover_anchor}")
    if len(focuses) > 1:
        clauses.append(f"再用{focuses[1]}补出冲突、结果或空间关系")
    if len(focuses) > 2:
        clauses.append(f"可再带出{focuses[2]}作为辅助线索")
    if brand:
        clauses.append(f"角落小识别：{brand}")
    clauses.append("文字只放封面短字和一个小识别，其它信息用主体动作、表情、屏幕光或数据光牌表现")
    clauses.append(project_visual_text_language_rule(project, "cover"))
    clauses.append("画面留出标题区，信息集中，不能像通用素材图")
    base_prompt = compact_prompt_rule("，".join(dedupe_clauses([item for item in clauses if item])), 700)
    return ensure_cover_text_directives(
        base_prompt,
        cover_short_title or cover_title or topic,
        subtitle,
        project_output_language(project),
    )


def visual_prompt_manifest_path(project_id: int) -> Path:
    return storage.project_file(project_id, "visual_prompt_manifest.json")


def visual_timeline_signature(project_id: int) -> str:
    timeline_path = storage.project_file(project_id, "audio/scene_timeline.json")
    if not timeline_path.exists():
        return ""
    timeline = storage.read_json(timeline_path, {})
    scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
    if not isinstance(scenes, list) or not scenes:
        return ""
    fingerprint = [
        {
            "index": int(item.get("index") or index),
        }
        for index, item in enumerate(scenes, start=1)
        if isinstance(item, dict)
    ]
    payload = {
        "scene_count": len(fingerprint),
        "scenes": fingerprint,
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()[:16]


def visual_prompt_manifest_identity(project: dict[str, Any], content: str) -> dict[str, str]:
    project_id = int(project.get("id") or 0)
    topic = clean_text(str(project.get("topic_name") or first_heading(content) or ""))
    topic_hash = hashlib.sha256(topic.encode("utf-8", errors="ignore")).hexdigest()[:12] if topic else ""
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    semantic = content_semantic_fingerprints(project, template, content)
    visual_content_hash = semantic_text_hash(
        {
            "topic": semantic.get("topic_hash"),
            "opening": semantic.get("opening_hash"),
            "core": semantic.get("core_hash"),
            "cover": semantic.get("cover_hash"),
        }
    )
    return {
        "channel_id": clean_text(str(project.get("template") or "")),
        "episode_id": str(project_id),
        "topic": topic,
        "topic_hash": topic_hash,
        "content_hash": visual_content_hash,
        "channel_image_policy_hash": channel_image_policy_signature(template),
        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
        "source_information_policy_version": SOURCE_INFORMATION_POLICY_VERSION,
        "reference_information_hash": source_information_signature(project_id) if project_id else "",
        "timeline_signature": visual_timeline_signature(project_id) if project_id else "",
    }


def visual_prompt_manifest_is_current(
    manifest: dict[str, Any],
    project: dict[str, Any],
    content: str,
) -> bool:
    if not isinstance(manifest, dict):
        return False
    if int(manifest.get("manifest_version") or 0) != VISUAL_PROMPT_MANIFEST_VERSION:
        return False
    identity = visual_prompt_manifest_identity(project, content)
    for key in (
        "channel_id",
        "episode_id",
        "topic",
        "topic_hash",
        "content_hash",
        "channel_image_policy_hash",
        "prompt_policy_version",
        "source_information_policy_version",
        "reference_information_hash",
        "timeline_signature",
    ):
        if clean_text(str(manifest.get(key) or "")) != clean_text(str(identity.get(key) or "")):
            return False
    scenes = manifest.get("scenes") if isinstance(manifest.get("scenes"), list) else []
    if not scenes or int(manifest.get("scene_count") or 0) != len(scenes):
        return False
    for index, item in enumerate(scenes, start=1):
        if not isinstance(item, dict) or not clean_text(str(item.get("prompt") or "")):
            return False
        lineage = item.get("lineage") if isinstance(item.get("lineage"), dict) else {}
        if clean_text(str(lineage.get("scene_id") or "")) != f"scene-{index:02d}":
            return False
        for key in (
            "channel_id",
            "episode_id",
            "content_hash",
            "topic_hash",
            "channel_image_policy_hash",
            "prompt_policy_version",
            "source_information_policy_version",
            "reference_information_hash",
        ):
            if clean_text(str(lineage.get(key) or "")) != clean_text(str(identity.get(key) or "")):
                return False
    return True


def load_visual_prompt_manifest(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    content_text = content if content is not None else storage.get_content(project_id)
    manifest = storage.read_json(visual_prompt_manifest_path(project_id), {})
    if visual_prompt_manifest_is_current(manifest, project, content_text):
        return manifest
    return {}


def visual_prompt_manifest_scene_prompts(project_id: int, content: str | None = None) -> list[str]:
    manifest = load_visual_prompt_manifest(project_id, content)
    scenes = manifest.get("scenes") if isinstance(manifest.get("scenes"), list) else []
    return [
        clean_text(str(item.get("prompt") or ""))
        for item in scenes
        if isinstance(item, dict) and clean_text(str(item.get("prompt") or ""))
    ]


def visual_prompt_manifest_cover_prompt(project_id: int, kind: str, content: str | None = None) -> str:
    manifest = load_visual_prompt_manifest(project_id, content)
    covers = manifest.get("covers") if isinstance(manifest.get("covers"), dict) else {}
    normalized_kind = clean_text(kind).lower()
    item = covers.get(normalized_kind) if isinstance(covers, dict) else None
    return clean_text(str(item.get("prompt") or "")) if isinstance(item, dict) else ""


def build_visual_prompt_manifest(
    project_id: int,
    content: str | None = None,
    *,
    scene_lines_override: list[str] | None = None,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    content_text = content if content is not None else storage.get_content(project_id)
    editorial_content = content_without_image_prompts(content_text) or content_text
    visual_topic = clean_text(first_heading(editorial_content) or project.get("topic_name") or "本期主题")
    fact_registry = build_episode_fact_registry(project_id, editorial_content)
    verified_numeric_facts = {
        clean_text(str(item))
        for item in (fact_registry.get("verified_facts") or [])
        if clean_text(str(item))
    }
    identity = visual_prompt_manifest_identity(project, editorial_content)
    source_candidates = source_information_candidates(
        project_id,
        topic=visual_topic,
        content=editorial_content,
    )
    repetition: dict[str, Any] = {}
    with contextlib.suppress(Exception):
        repetition = channel_repetition_report(project_id, max_projects=20)
    pose_avoidance = channel_repeat_visual_directive(repetition, "character_pose")
    cover_avoidance = channel_repeat_visual_directive(repetition, "cover_composition")
    scene_lines = [normalize_image_prompt(item) for item in (scene_lines_override or []) if normalize_image_prompt(item)]
    if not scene_lines:
        scene_lines = build_content_scene_prompt_lines(project, template, editorial_content)
    episode_continuity = episode_visual_continuity_prompt(project_id, project, template, editorial_content)

    scenes: list[dict[str, Any]] = []
    for index, prompt in enumerate(scene_lines, start=1):
        scene_speech = scene_prompt_speech_anchor(prompt) or clean_text(prompt)
        scene_speech = expand_scene_speech_anchor(editorial_content, mode, scene_speech)
        audience_plan = audience_visual_plan(
            topic=visual_topic,
            narration=scene_speech,
            index=index,
        )
        audience_issues = audience_visual_failure_reasons(
            audience_plan,
            visual_concept=prompt,
        )
        repair_actions = audience_visual_repair_actions(audience_plan, audience_issues)
        source_information = scene_source_information_payload(
            project_id,
            topic=visual_topic,
            speech=scene_speech,
            content=editorial_content,
            candidates=source_candidates,
        )
        if clean_text(str(audience_plan.get("mode") or "")) in {
            "single_metric",
            "benchmark_metric",
            "true_comparison",
        }:
            primary_metric = (
                audience_plan.get("primary_metric")
                if isinstance(audience_plan.get("primary_metric"), dict)
                else {}
            )
            metric_text = clean_text(
                f"{primary_metric.get('value', '')}{primary_metric.get('label', '')}"
            )
            fact_chips = dedupe_clauses(
                [
                    clean_text(str(audience_plan.get("context_label") or "")),
                    metric_text,
                    clean_text(str(audience_plan.get("relation_label") or "")),
                ]
            )
            source_information["visual_copy"] = {
                "headline": clean_text(str(audience_plan.get("kicker") or "")),
                "fact_chips": fact_chips[:3],
                "required_text": dedupe_clauses(
                    [
                        clean_text(str(audience_plan.get("kicker") or "")),
                        *fact_chips[:3],
                    ]
                ),
                "silent_viewing_question": clean_text(str(audience_plan.get("audience_question") or "")),
            }
        tension_match = re.search(
            r"(?:冲突/悬念|冲突悬念|冲突)\s*[:：]\s*(.*?)(?=(?:短字|镜头视角|影像质感|证据信息|来源支撑信息)\s*[:：]|$)",
            prompt,
        )
        one_second_takeaway = clean_text(tension_match.group(1)) if tension_match else clean_text(
            str(audience_plan.get("audience_takeaway") or scene_speech)
        )
        prompt = compact_visual_image_prompt(
            "。".join(
                dedupe_clauses(
                    [
                        f"本期主题：{visual_topic}",
                        f"当前完整口播：{scene_speech}",
                        f"观众1秒必须看懂：{one_second_takeaway}",
                        prompt,
                        *source_information_prompt_clauses(source_information),
                        audience_prompt_block(audience_plan),
                    ]
                )
            ),
            1200,
        )
        prompt = apply_channel_image_policy(prompt, template, "scene")
        if episode_continuity and "同集视觉连续性：" not in prompt:
            prompt = f"{prompt}。{episode_continuity}".strip("。")
        if pose_avoidance:
            prompt = compact_visual_image_prompt(f"{prompt}。{pose_avoidance}", 1200)
        # Do not let continuity/source annotations turn a generation request
        # back into a page-long brief.  The retained front section contains the
        # channel contract, current narration, visual concept and core facts.
        prompt = compact_visual_image_prompt(prompt, 740)
        prompt_hash = hashlib.sha256(prompt.encode("utf-8", errors="ignore")).hexdigest()[:16]
        prompt_numeric_facts = sorted(
            {
                clean_text(str(claim.get("normalized") or ""))
                for claim in strong_numeric_claims_in_line(prompt)
                if clean_text(str(claim.get("normalized") or "")) in verified_numeric_facts
            }
        )
        lineage = {
            **identity,
            "scene_id": f"scene-{index:02d}",
            "prompt_hash": prompt_hash,
        }
        scenes.append(
            {
                "index": index,
                "scene_id": f"scene-{index:02d}",
                "target": f"s_{index:02d}.png",
                "prompt": prompt,
                "prompt_hash": prompt_hash,
                "quality_score": 0,
                "quality_score_version": IMAGE_PROMPT_SCORE_VERSION,
                "quality_state": "unscored",
                "verified_numeric_facts": prompt_numeric_facts,
                "source_information": source_information,
                "audience_visual": audience_plan,
                "audience_preflight": {
                    "passed": not audience_issues,
                    "issues": audience_issues,
                    "repair_actions": repair_actions,
                },
                "generation_decision": {
                    "image_required": bool(audience_plan.get("image_required")),
                    "priority": int(audience_plan.get("image_priority", 0) or 0),
                    "role": clean_text(str(audience_plan.get("visual_role") or "")),
                    "asset_strategy": clean_text(str(audience_plan.get("asset_strategy") or "")),
                },
                "prompt_history": [],
                "lineage": lineage,
            }
        )

    cover_kinds = ("landscape",) if mode == "article" else ("landscape", "story", "portrait")
    covers: dict[str, dict[str, Any]] = {}
    for kind in cover_kinds:
        prompt = normalize_image_prompt(build_content_cover_prompt(project, template, editorial_content, kind))
        if cover_avoidance:
            prompt = compact_visual_image_prompt(f"{prompt}。{cover_avoidance}", 1200)
        prompt_hash = hashlib.sha256(prompt.encode("utf-8", errors="ignore")).hexdigest()[:16]
        prompt_numeric_facts = sorted(
            {
                clean_text(str(claim.get("normalized") or ""))
                for claim in strong_numeric_claims_in_line(prompt)
                if clean_text(str(claim.get("normalized") or "")) in verified_numeric_facts
            }
        )
        covers[kind] = {
            "kind": kind,
            "target": f"cover_{kind}.png",
            "prompt": prompt,
            "prompt_hash": prompt_hash,
            "quality_score": 0,
            "quality_score_version": IMAGE_PROMPT_SCORE_VERSION,
            "quality_state": "unscored",
            "verified_numeric_facts": prompt_numeric_facts,
            "prompt_history": [],
            "lineage": {
                **identity,
                "scene_id": f"cover-{kind}",
                "prompt_hash": prompt_hash,
            },
        }

    return {
        "manifest_version": VISUAL_PROMPT_MANIFEST_VERSION,
        "generated_at": storage.now_ts(),
        **identity,
        "mode": mode,
        "fact_registry_version": FACT_REGISTRY_VERSION,
        "fact_registry_hash": clean_text(str(fact_registry.get("fact_hash") or "")),
        "verified_numeric_facts": sorted(verified_numeric_facts),
        "source_information_policy_version": SOURCE_INFORMATION_POLICY_VERSION,
        "audience_visual_policy_version": AUDIENCE_VISUAL_POLICY_VERSION,
        "reference_information_hash": clean_text(str(identity.get("reference_information_hash") or "")),
        "source_information_candidate_count": len(source_candidates),
        "scene_count": len(scenes),
        "scenes": scenes,
        "covers": covers,
        "legacy_content_prompt_section_ignored": bool(parse_scene_prompts(content_text, mode)),
    }


def save_visual_prompt_manifest(
    project_id: int,
    content: str | None = None,
    *,
    scene_lines_override: list[str] | None = None,
    force: bool = False,
    preserve_covers: bool = False,
) -> dict[str, Any]:
    content_text = content if content is not None else storage.get_content(project_id)
    previous = storage.read_json(visual_prompt_manifest_path(project_id), {})
    if not force and scene_lines_override is None:
        existing = load_visual_prompt_manifest(project_id, content_text)
        if existing:
            return existing
    manifest = build_visual_prompt_manifest(
        project_id,
        content_text,
        scene_lines_override=scene_lines_override,
    )
    if preserve_covers and isinstance(previous, dict) and isinstance(previous.get("covers"), dict):
        manifest["covers"] = previous["covers"]
    storage.write_json(visual_prompt_manifest_path(project_id), manifest)
    return manifest


def sync_scene_prompt_records_from_manifest(
    project_id: int,
    manifest: dict[str, Any],
    targets: Iterable[str],
) -> None:
    target_set = {clean_text(str(item)) for item in targets if clean_text(str(item))}
    if not target_set:
        return
    records_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    records = storage.read_json(records_path, [])
    if not isinstance(records, list):
        records = []
    records_by_filename = {
        clean_text(str(item.get("filename") or "")): item
        for item in records
        if isinstance(item, dict) and clean_text(str(item.get("filename") or ""))
    }
    scenes = manifest.get("scenes") if isinstance(manifest.get("scenes"), list) else []
    changed = False
    for item in scenes:
        if not isinstance(item, dict):
            continue
        target = clean_text(str(item.get("target") or ""))
        prompt = normalize_image_prompt(str(item.get("prompt") or ""))
        if target not in target_set or not prompt:
            continue
        matches = re.findall(r"(\d+)", target)
        index = int(matches[0]) if matches else len(records) + 1
        record = records_by_filename.get(target)
        if record is None:
            record = {"filename": target, "label": f"场景 {index}"}
            records.append(record)
            records_by_filename[target] = record
        lineage = item.get("lineage") if isinstance(item.get("lineage"), dict) else {}
        record.update(
            {
                "prompt": prompt,
                "source_prompt": prompt,
                "content_hash": clean_text(str(lineage.get("content_hash") or manifest.get("content_hash") or "")),
                "topic_hash": clean_text(str(lineage.get("topic_hash") or manifest.get("topic_hash") or "")),
                "channel_id": clean_text(str(lineage.get("channel_id") or manifest.get("channel_id") or "")),
                "episode_id": clean_text(str(lineage.get("episode_id") or manifest.get("episode_id") or project_id)),
                "manifest_version": clean_text(str(manifest.get("manifest_version") or VISUAL_PROMPT_MANIFEST_VERSION)),
                "prompt_policy_version": clean_text(str(manifest.get("prompt_policy_version") or IMAGE_PROMPT_POLICY_VERSION)),
                "audience_visual": item.get("audience_visual") if isinstance(item.get("audience_visual"), dict) else {},
                "audience_preflight": item.get("audience_preflight") if isinstance(item.get("audience_preflight"), dict) else {},
                "generation_decision": item.get("generation_decision") if isinstance(item.get("generation_decision"), dict) else {},
                "updated_at": storage.now_ts(),
            }
        )
        record.pop("information_overlay", None)
        record.pop("information_anchor", None)
        record.pop("manual_image_accepted", None)
        record.pop("manual_image_accepted_at", None)
        changed = True
    if target_set:
        filtered_records = [
            record
            for record in records
            if not (
                isinstance(record, dict)
                and re.fullmatch(r"s_\d+\.png", clean_text(str(record.get("filename") or "")))
                and clean_text(str(record.get("filename") or "")) not in target_set
            )
        ]
        if len(filtered_records) != len(records):
            records = filtered_records
            changed = True
    if changed:
        storage.write_json(records_path, sorted(records, key=scene_record_index))


def update_visual_prompt_manifest_prompts(
    project_id: int,
    purpose: str,
    final_prompts: dict[str, str],
    content: str | None = None,
    *,
    prompt_scores: dict[str, int] | None = None,
    source: str = "prompt-preflight",
    force: bool = False,
) -> dict[str, Any]:
    content_text = content if content is not None else storage.get_content(project_id)
    manifest = load_visual_prompt_manifest(project_id, content_text)
    if not manifest:
        manifest = save_visual_prompt_manifest(project_id, content_text)

    normalized_purpose = clean_text(purpose).lower()
    changed = False
    accepted_targets: list[str] = []
    preserved_targets: list[str] = []
    score_map = prompt_scores if isinstance(prompt_scores, dict) else {}

    def update_item(item: dict[str, Any]) -> None:
        nonlocal changed
        target = clean_text(str(item.get("target") or ""))
        prompt = normalize_image_prompt(str(final_prompts.get(target) or ""))
        if not prompt:
            return
        new_score = int(score_map.get(target, 0) or 0)
        current_prompt = normalize_image_prompt(str(item.get("prompt") or ""))
        current_score = int(item.get("quality_score", 0) or 0)
        current_score_version = clean_text(str(item.get("quality_score_version") or ""))
        prompt_hash = hashlib.sha256(prompt.encode("utf-8", errors="ignore")).hexdigest()[:16]
        candidate = {
            "prompt": prompt,
            "prompt_hash": prompt_hash,
            "quality_score": new_score,
            "quality_score_version": IMAGE_PROMPT_SCORE_VERSION,
            "source": source,
            "generated_at": storage.now_ts(),
        }
        if (
            not force
            and current_prompt
            and current_prompt != prompt
            and current_score > 0
            and current_score_version == IMAGE_PROMPT_SCORE_VERSION
            and new_score > 0
            and new_score < current_score
        ):
            item["last_rejected_candidate"] = candidate
            item["best_version_locked"] = True
            preserved_targets.append(target)
            changed = True
            return
        if current_prompt and current_prompt != prompt:
            history = item.get("prompt_history") if isinstance(item.get("prompt_history"), list) else []
            history.append(
                {
                    "prompt": current_prompt,
                    "prompt_hash": clean_text(str(item.get("prompt_hash") or "")),
                    "quality_score": current_score,
                    "quality_score_version": current_score_version,
                    "source": clean_text(str(item.get("quality_source") or "previous")),
                    "archived_at": storage.now_ts(),
                }
            )
            item["prompt_history"] = history[-3:]
        if current_prompt != prompt:
            item["prompt"] = prompt
            item["prompt_hash"] = prompt_hash
            lineage = item.get("lineage") if isinstance(item.get("lineage"), dict) else {}
            lineage["prompt_hash"] = prompt_hash
            item["lineage"] = lineage
            changed = True
        if new_score > 0 and (
            force
            or current_score_version != IMAGE_PROMPT_SCORE_VERSION
            or new_score >= current_score
            or current_prompt == prompt
        ):
            item["quality_score"] = new_score
            item["quality_score_version"] = IMAGE_PROMPT_SCORE_VERSION
            item["quality_state"] = "scored"
            item["quality_source"] = source
            item["quality_updated_at"] = storage.now_ts()
            item["best_version_locked"] = False
            item.pop("last_rejected_candidate", None)
            changed = True
        accepted_targets.append(target)

    if normalized_purpose == "scene":
        items = manifest.get("scenes") if isinstance(manifest.get("scenes"), list) else []
        for item in items:
            if not isinstance(item, dict):
                continue
            update_item(item)
    elif normalized_purpose == "cover":
        covers = manifest.get("covers") if isinstance(manifest.get("covers"), dict) else {}
        for item in covers.values():
            if not isinstance(item, dict):
                continue
            update_item(item)
    if changed:
        manifest["updated_at"] = storage.now_ts()
        manifest["last_prompt_update"] = {
            "purpose": normalized_purpose,
            "source": source,
            "accepted_targets": dedupe_clauses(accepted_targets),
            "preserved_targets": dedupe_clauses(preserved_targets),
            "best_version_lock_applied": bool(preserved_targets),
        }
        storage.write_json(visual_prompt_manifest_path(project_id), manifest)
    if normalized_purpose == "scene":
        sync_scene_prompt_records_from_manifest(
            project_id,
            manifest,
            [*accepted_targets, *preserved_targets],
        )
    return manifest


def resolved_scene_prompt_plan(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
) -> list[str]:
    project_id = int(project.get("id") or 0)
    if project_id:
        manifest_prompts = visual_prompt_manifest_scene_prompts(project_id, content)
        if manifest_prompts:
            return manifest_prompts
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    legacy_prompts = parse_scene_prompts(content, mode)
    if legacy_prompts:
        return legacy_prompts
    return build_content_scene_prompt_lines(project, template, content)


def build_dynamic_image_prompt_section(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    scene_lines_override: list[str] | None = None,
) -> str:
    mode = clean_text(template.get("mode") or project.get("template_mode") or "video")
    scene_lines = scene_lines_override or build_content_scene_prompt_lines(project, template, content)
    duration = extract_meta_field(content, "时长") or summarize_content(content, mode).get("duration", "")
    if mode == "article":
        section_lines = [
            "### 横屏封面图（头图）",
            build_content_cover_prompt(project, template, content, "landscape"),
            "",
            f"### 场景图（正文配图，共 {len(scene_lines)} 张）",
        ]
        section_lines.extend(f"{idx}. {line}" for idx, line in enumerate(scene_lines, start=1))
        return "\n".join(section_lines).strip()

    count_line = f"### 场景图（按目标时长 {duration or '3-10分钟'}，共{len(scene_lines)}张）"
    section_lines = [
        "### 横屏封面图",
        build_content_cover_prompt(project, template, content, "landscape"),
        "",
        "### 竖屏封面图",
        build_content_cover_prompt(project, template, content, "portrait"),
        "",
        count_line,
        "",
    ]
    section_lines.extend(f"{idx}. {line}" for idx, line in enumerate(scene_lines, start=1))
    return "\n".join(section_lines).strip()


def refresh_content_image_prompts(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
    scene_lines_override: list[str] | None = None,
) -> str:
    del project, template, scene_lines_override
    return (content_without_image_prompts(content) or content).rstrip() + "\n"


def summarize_content(content: str, mode: str) -> dict[str, Any]:
    title = first_heading(content)
    meta_publish_title = extract_meta_field(content, "发布标题")
    cover_title = extract_meta_field(content, "封面主标题") or meta_publish_title or title or ""
    cover_subtitle = extract_meta_field(content, "封面副标题")
    publish_title = extract_meta_field(content, "推荐发布标题") or meta_publish_title or title
    duration = extract_meta_field(content, "时长")
    scene_prompts = parse_scene_prompts(content, mode)
    highlights = parse_highlights(content)
    dialogue_lines = parse_dialogue_lines(content, mode)

    if not duration:
        if mode == "article":
            duration = "图文"
        elif len(dialogue_lines) >= 36:
            duration = "9-10分钟"
        elif len(dialogue_lines) >= 26:
            duration = "7-8分钟"
        elif len(dialogue_lines) >= 18:
            duration = "5-6分钟"
        else:
            duration = "3-4分钟"

    score_text = extract_meta_field(content, "选题评分")
    score_match = re.search(r"=\s*([0-5](?:\.\d)?)|([0-5](?:\.\d)?)\s*分", score_text)
    topic_score = score_match.group(1) or score_match.group(2) if score_match else ""
    if not topic_score:
        heuristic = min(5.0, 3.4 + min(len(scene_prompts), 12) * 0.1)
        topic_score = f"{heuristic:.1f}"

    body_len = len(re.sub(r"\s+", "", content or ""))
    return {
        "video_title": title,
        "cover_title": cover_title or fallback_cover_title(title or publish_title),
        "cover_subtitle": cover_subtitle,
        "publish_title": publish_title,
        "duration": duration,
        "dialogue_count": len(dialogue_lines),
        "scene_count": len(scene_prompts),
        "body_len": body_len,
        "highlight_count": len(highlights),
        "topic_score": topic_score,
        "mode": mode,
    }


def topic_score_report(project: dict[str, Any], brief: str) -> dict[str, Any]:
    topic = clean_text(project["topic_name"])
    excerpt = clean_text(brief or topic)
    familiarity = 1.0 if len(topic) <= 18 else 0.7
    contrast = 0.9 if "为什么" in topic or "怎么" in topic or "真相" in topic else 0.7
    story = 0.9 if len(excerpt) >= 18 else 0.6
    reality = 0.8 if any(word in excerpt for word in ["用户", "生活", "今天", "现实", "场景"]) else 0.6
    visual = 0.9 if any(word in excerpt for word in ["对比", "案例", "画面", "人物", "场景"]) else 0.7
    total = round(familiarity + contrast + story + reality + visual, 1)
    return {
        "topic": topic,
        "brief_excerpt": excerpt[:120],
        "total_score": total,
        "scorecard": [
            {"name": "熟悉度", "score": familiarity, "reason": "主题是否能让普通观众一眼明白在讲什么。"},
            {"name": "反常识", "score": contrast, "reason": "是否存在明显的认知反转或隐藏机制。"},
            {"name": "故事性", "score": story, "reason": "是否能拆成起因、经过、结果的一条线。"},
            {"name": "现实连接", "score": reality, "reason": "结尾能不能自然回到今天的生活场景。"},
            {"name": "可视化", "score": visual, "reason": "能否拆成多张有明确信息点的场景图。"},
        ],
        "verdict": "分数达标时适合进入脚本生成；分数偏低时应先换角度或缩短篇幅。",
    }


def viral_doctor_report(project: dict[str, Any], content: str) -> dict[str, Any]:
    scene_count = len(parse_scene_prompts(content, project.get("template_mode", "video")))
    has_hook = any(token in content for token in ["你以为", "你知道吗", "但你猜", "为什么"])
    overall = round(min(5.0, 3.0 + scene_count * 0.15 + (0.4 if has_hook else 0.0)), 1)
    return {
        "overall_score": overall,
        "top_issues": [
            {
                "where": "开头钩子",
                "issue": "如果第一句不够反常识，用户滑走会非常快。",
                "fix": "把结论后置半句，先抛反常识问题或具体细节。",
            },
            {
                "where": "中段转折",
                "issue": "如果全程都在解释，没有案例和转折，信息会显得很平。",
                "fix": "在中段加入一个更具体的例子，或者旧做法 vs 新理解的对比。",
            },
        ],
        "performance_read": "当前稿子已经具备成片结构，但是否像爆款，还取决于开头和中段的抓力。",
        "verdict": "可以直接生产；想更像原软件的成稿风格，优先强化钩子、字幕金句和场景图对应关系。",
    }


def viral_doctor_report(project: dict[str, Any], content: str) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or "video")
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    scene_count = len(resolved_scene_prompt_plan(project, template, content))
    engagement = content_engagement_report(content, mode)
    return {
        "overall_score": engagement["overall_score"],
        "opening_score": engagement["opening_score"],
        "retention_score": engagement["retention_score"],
        "interaction_score": engagement["interaction_score"],
        "scene_count": scene_count,
        "top_issues": engagement["issues"][:3]
        or [
            {
                "where": "整体表达",
                "issue": "结构完整，但金句、推进和互动还可以继续抬高。",
                "fix": "继续收紧首句、关键转折句和结尾评论钩子。",
            }
        ],
        "performance_read": engagement["performance_read"],
        "verdict": engagement["verdict"],
    }


def title_cover_ab_report(project: dict[str, Any], content: str, count: int = 6) -> dict[str, Any]:
    summary = summarize_content(content, project.get("template_mode", "video"))
    base_title = summary.get("publish_title") or project["topic_name"]
    base_cover = summary.get("cover_title") or fallback_cover_title(project["topic_name"])
    subtitle = summary.get("cover_subtitle") or fallback_cover_subtitle(project["topic_name"])
    hook_types = ["反常识", "疑问句", "结果先行", "误区纠正", "数字冲击", "现实连接"]
    variants = []
    for idx in range(count):
        variants.append(
            {
                "video_title": f"{base_title}（方案 {idx + 1}）",
                "cover_title": f"{base_cover}",
                "cover_subtitle": subtitle,
                "hook_type": hook_types[idx % len(hook_types)],
                "risk": "低",
                "why": "保留熟悉对象，同时在句式上做差异化测试，更接近原软件的标题 A/B 工作流。",
            }
        )
    return {
        "recommended_index": 0,
        "variants": variants,
        "verdict": "默认先用第 1 套，再根据平台反馈替换钩子句式。",
    }


def infer_platform_profile(project: dict[str, Any], template: dict[str, Any]) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    template_name = clean_text(template.get("name") or template.get("key") or project.get("template") or "")
    if mode == "article":
        return {
            "platform": "图文平台",
            "format": "图文卡片/长图文",
            "voice": "密度高、标题明确、每屏一个观点",
            "success_signals": ["首屏标题有冲突", "每页只讲一个点", "评论区有表达空间"],
        }
    if "双人" in template_name:
        return {
            "platform": "抖音/视频号",
            "format": "双人对谈式横屏短视频",
            "voice": "一问一答、追问拆解、生活吐槽带出技术或观点",
            "success_signals": ["前三秒反常识", "两人轮替节奏清楚", "每 20-40 秒有一个新信息点"],
        }
    return {
        "platform": "抖音/视频号",
        "format": "单人口播横屏短视频",
        "voice": "朋友式讲故事、反常识开场、案例推动",
        "success_signals": ["开头问题尖锐", "中段有转折", "结尾能落到现实用途"],
    }


def classify_title_strategy(text: str) -> str:
    title = clean_text(text)
    if re.search(r"\d", title):
        return "数字冲击"
    if any(token in title for token in ("为什么", "怎么", "吗", "？", "?")):
        return "疑问钩子"
    if any(token in title for token in ("不是", "真相", "误区", "反而", "其实", "藏在")):
        return "反常识"
    if any(token in title for token in ("你家", "普通人", "别再", "总是", "痛点", "废了")):
        return "痛点共鸣"
    if any(token in title for token in ("最好", "最强", "第一", "必看")):
        return "强判断"
    return "结果先行"


def content_strategy_report(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str = "general",
    references: list[dict[str, Any]] | None = None,
    content: str = "",
) -> dict[str, Any]:
    topic = clean_text(project.get("topic_name") or "")
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    source = clean_text("\n".join([topic, brief, content]))
    summary = summarize_content(content, mode) if content else {}
    score = topic_score_report(project, brief)
    title = clean_text(summary.get("publish_title") or summary.get("video_title") or topic)
    platform = infer_platform_profile(project, template)
    refs = references or []
    ref_titles = [clean_text(str(item.get("title") or "")) for item in refs[:5] if isinstance(item, dict)]

    contradiction = "旧理解和真实机制之间的反差"
    if any(token in source for token in ("断网", "掉线", "废铁", "失效")):
        contradiction = "用户以为是网络问题，真正关键可能在底层连接方式"
    elif any(token in source for token in ("便宜", "贵", "成本", "价格")):
        contradiction = "表面看是价格问题，背后其实是价值和风险判断"
    elif any(token in source for token in ("AI", "模型", "自动化")):
        contradiction = "大家只看工具热闹，真正差异在流程和验证能力"

    emotion_curve = ["好奇", "共鸣", "意外", "理解", "想试/想评论"]
    if mode == "article":
        emotion_curve = ["被标题钩住", "发现误区", "逐页拆解", "得到结论", "愿意收藏"]

    return {
        "generated_at": storage.now_ts(),
        "topic": topic,
        "template": clean_text(template.get("name") or template.get("key") or project.get("template") or ""),
        "platform_profile": platform,
        "tavily_topic": tavily_topic or "general",
        "reference_count": len(refs),
        "reference_titles": ref_titles,
        "topic_score": score,
        "insights": {
            "core_viewpoint": clean_text(extract_meta_field(content, "核心观点")) if content else f"{topic}最值得讲的不是表面结论，而是背后的因果机制",
            "counter_intuition": contradiction,
            "audience_pain": "观众已经遇到过类似场景，但不知道真正原因是什么",
            "knowledge_payload": "把概念拆成起因、机制、证据、应用四段",
            "story_engine": "痛点开场 -> 旧理解失效 -> 新机制解释 -> 现实场景回扣",
            "persuasion_strategy": "先共情，再反转，再用具体画面降低理解成本",
            "title_strategy": classify_title_strategy(title),
            "opening_hook": clean_text(extract_meta_field(content, "钩子")) if content else f"你以为「{topic}」只是普通问题？真正关键藏在另一层。",
            "golden_three_seconds": clean_text(extract_meta_field(content, "前3秒视觉钩子")) if content else "先给一个强痛点画面，再抛反常识问题。",
            "emotion_curve": emotion_curve,
            "interaction_hook": clean_text(extract_meta_field(content, "互动钩子")) or "你遇到过类似情况吗？评论区聊聊。",
        },
        "output_contract": {
            "content_md": "标题、Meta、脚本/正文、重点字幕、参考资料",
            "visual_prompt_manifest": "频道、本期、场景和内容哈希绑定的独立图片提示词清单",
            "content_audit": "平台适配、AI味、事实风险、标题策略、前三秒钩子",
            "scene_plan": "每镜的叙事状态、视觉锚点、生图提示词、运动和转场建议",
        },
    }


def content_audit_report(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    content: str,
    references: list[dict[str, Any]] | None = None,
    *,
    source_content: str | None = None,
) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    summary = summarize_content(content, mode)
    dialogue_lines = parse_dialogue_lines(content, mode)
    scene_prompts = resolved_scene_prompt_plan(project, template, content)
    summary["scene_count"] = len(scene_prompts)
    highlights = parse_highlights(content)
    title = clean_text(summary.get("publish_title") or summary.get("video_title") or project.get("topic_name") or "")
    plain = clean_text(content_for_editorial_quality(content))
    issues: list[dict[str, str]] = []

    def add_issue(level: str, where: str, issue: str, fix: str) -> None:
        issues.append({"level": level, "where": where, "issue": issue, "fix": fix})

    hook_text = "\n".join(dialogue_lines[:3]) if dialogue_lines else plain[:160]
    semantic_hook_signals = opening_semantic_hook_signals(hook_text)
    if not (
        any(token in hook_text for token in ("你", "为什么", "怎么", "以为", "知道", "断网", "废", "真相", "其实"))
        or any(semantic_hook_signals.values())
    ):
        add_issue("warn", "前三秒钩子", "开头缺少直接问题、痛点或反常识信号。", "第一句改成观众能立刻代入的问题或具体痛点。")
    if mode != "article" and len(dialogue_lines) < 8:
        add_issue("warn", "脚本长度", "对话/口播句数偏少，成片可能显得薄。", "补足起因、机制、例子、回扣四段。")
    scene_count_info = resolve_project_scene_count(
        project,
        content,
        mode,
        candidate_count=len(scene_prompts),
    )
    authoritative_scene_count = effective_visual_scene_count(project, 0)
    if authoritative_scene_count > 0:
        minimum_scene_count = authoritative_scene_count
        target_scene_count = authoritative_scene_count
        maximum_scene_count = authoritative_scene_count
    else:
        minimum_scene_count = 4 if mode == "article" else int(scene_count_info.get("minimum", 6) or 6)
        target_scene_count = int(scene_count_info.get("target", minimum_scene_count) or minimum_scene_count)
        maximum_scene_count = int(scene_count_info.get("maximum", target_scene_count) or target_scene_count)
    if len(scene_prompts) < minimum_scene_count:
        add_issue(
            "warn",
            "场景图",
            f"当前只有 {len(scene_prompts)} 个场景，画面变化不够支撑短视频节奏。",
            f"按脚本/音频长度补到约 {target_scene_count} 个明确镜头（建议范围 {minimum_scene_count}-{maximum_scene_count}）。",
        )
    if not highlights and mode != "article":
        add_issue("warn", "重点字幕", "没有重点字幕，后续高亮字幕缺少依据。", "抽 4-8 条短句作为金句/转折句。")
    if len(references or []) == 0:
        add_issue("info", "事实依据", "当前没有参考资料记录，事实型选题可追溯性偏弱。", "补联网资料或历史稿引用，保留 references.json。")

    ai_smell_tokens = ["首先", "其次", "最后", "综上", "总而言之", "在当今社会", "值得注意的是", "不可忽视"]
    ai_smell_hits = [token for token in ai_smell_tokens if token in plain]
    if len(ai_smell_hits) >= 2:
        add_issue("warn", "表达风格", f"存在较明显 AI 公文感词汇：{', '.join(ai_smell_hits[:4])}。", "改成更口语的追问、吐槽、具体细节和短句。")

    bad_phrase_hits = script_bad_phrase_hits("\n".join(dialogue_lines) or plain)
    if bad_phrase_hits:
        add_issue(
            "risk",
            "口播套话/播客腔",
            f"存在弱开头或播客式收尾：{', '.join(bad_phrase_hits[:6])}。",
            "删除“今天我们来聊聊”“本期播客”“感谢收听”等表达，开头直接给冲突，结尾用具体互动问题。",
        )
    duplicate_interactions = duplicate_terminal_interaction_indexes(dialogue_lines)
    if duplicate_interactions:
        add_issue(
            "risk",
            "结尾互动重复",
            f"结尾出现 {len(duplicate_interactions) + 1} 个评论动作，口播会连续重复互动要求。",
            "保留一个最自然、最具体的评论动作，删除其余同义收尾。",
        )
    semantic_duplicates = [
        pair
        for pair in semantic_duplicate_dialogue_pairs(dialogue_lines)
        if not pair.get("interaction_duplicate")
    ]
    if semantic_duplicates:
        examples = "；".join(
            f"第 {int(pair['left_index']) + 1}/{int(pair['right_index']) + 1} 句"
            for pair in semantic_duplicates[:3]
        )
        add_issue(
            "warn",
            "口播语义重复",
            f"相邻段落存在近义复述：{examples}。",
            "保留信息增量更大的一句；若是刻意递进，请补充新的事实、例子或结论。",
        )

    numeric_consistency = numeric_source_consistency_report(
        int(project.get("id", 0) or 0),
        source_content if source_content is not None else content,
        brief=brief,
        references=references or [],
    )
    unsupported_facts = numeric_consistency.get("unsupported_facts") if isinstance(numeric_consistency.get("unsupported_facts"), list) else []
    if unsupported_facts:
        preview = "、".join(
            f"{item.get('section') or '口播'}第 {item.get('line_index')} 行的 {item.get('fact')}"
            for item in unsupported_facts[:5]
            if isinstance(item, dict)
        )
        add_issue(
            "risk",
            "数字事实依据",
            f"发现未被当前 brief 或参考资料支持的精确数字：{preview}。",
            "先补入可靠来源并重新生成，或把无法核验的精确数字改成不夸大的定性表达；禁止让 AI 猜一个替代数字。",
        )

    risky_tokens = [
        "保证",
        "稳赚",
        "百分百",
        "100%",
        "治疗",
        "治愈",
        "最权威",
        "绝对",
        "一定",
        "必然",
        "肯定",
        "唯一",
        "内幕消息",
        "吓进医院",
    ]
    risk_hits = [token for token in risky_tokens if token in plain]
    if risk_hits:
        add_issue("risk", "平台风险", f"疑似绝对化或高风险词：{', '.join(risk_hits)}。", "改成来源限定、概率表达或经验判断。")

    title_strategy = classify_title_strategy(title)
    viral = viral_doctor_report(project, content)
    ab = title_cover_ab_report(project, content, 6)
    score = 100
    score -= sum(18 for item in issues if item["level"] == "risk")
    score -= sum(9 for item in issues if item["level"] == "warn")
    score -= sum(3 for item in issues if item["level"] == "info")
    score = max(0, min(100, score))
    if score >= 86:
        verdict = "可以直接进入生产。"
    elif score >= 70:
        verdict = "可以生产，但建议先修开头、标题或场景图。"
    else:
        verdict = "建议先重写关键段落再进入生产。"

    return {
        "generated_at": storage.now_ts(),
        "score": score,
        "verdict": verdict,
        "rewrite_recommended": score < 70 or any(item["level"] == "risk" for item in issues),
        "summary": summary,
        "platform_profile": infer_platform_profile(project, template),
        "title_strategy": title_strategy,
        "metrics": {
            "dialogue_count": len(dialogue_lines),
            "scene_prompt_count": len(scene_prompts),
            "highlight_count": len(highlights),
            "reference_count": len(references or []),
            "body_len": summary.get("body_len", len(plain)),
            "unsupported_numeric_fact_count": len(unsupported_facts),
        },
        "numeric_consistency": numeric_consistency,
        "issues": issues,
        "viral_doctor": viral,
        "title_cover_ab": ab,
    }


def build_content_artifacts(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str,
    references: list[dict[str, Any]],
    content: str,
) -> dict[str, Any]:
    strategy = content_strategy_report(project, template, brief, tavily_topic, references, content)
    audit = content_audit_report(project, template, brief, content, references)
    return {"strategy": strategy, "audit": audit}


def unwrap_ddg_url(url: str) -> str:
    parsed = urllib.parse.urlparse(url or "")
    if "duckduckgo.com" in parsed.netloc and parsed.path.startswith("/l/"):
        query = urllib.parse.parse_qs(parsed.query)
        target = query.get("uddg", [""])[0]
        if target:
            return urllib.parse.unquote(target)
    return url


def local_article_references(project: dict[str, Any], template: dict[str, Any], brief: str) -> list[dict[str, Any]]:
    query_tokens = extract_tokens(f"{project['topic_name']} {brief}")
    refs: list[dict[str, Any]] = []
    for meta in storage.list_projects():
        if meta["id"] == project["id"]:
            continue
        if meta.get("template") != project.get("template"):
            continue
        content = storage.get_content(meta["id"])
        if not clean_text(content):
            continue
        score = overlap_score(query_tokens, f"{meta.get('topic_name', '')}\n{content[:4000]}")
        if score <= 0:
            continue
        summary = storage.get_summary(meta["id"])
        refs.append(
            {
                "index": 0,
                "title": summary.get("publish_title") or summary.get("video_title") or meta["topic_name"],
                "url": storage.project_file(meta["id"], "content.md").as_posix(),
                "source": "历史稿",
                "query": project["topic_name"],
                "snippet": truncate(content),
                "score": round(score, 3),
                "has_content": True,
            }
        )
    refs.sort(key=lambda item: item.get("score", 0.0), reverse=True)
    return refs[:3]


NEWS_FRESHNESS_POLICY_VERSION = "current-events-v1"
CURRENT_NEWS_MAX_AGE_DAYS = 31


def parse_reference_datetime(value: Any) -> datetime | None:
    text = clean_text(str(value or ""))
    if not text:
        return None
    normalized = text.replace("Z", "+00:00")
    with contextlib.suppress(ValueError):
        parsed = datetime.fromisoformat(normalized)
        return parsed.replace(tzinfo=parsed.tzinfo or timezone.utc).astimezone(timezone.utc)
    with contextlib.suppress(TypeError, ValueError, OverflowError):
        parsed = parsedate_to_datetime(text)
        return parsed.replace(tzinfo=parsed.tzinfo or timezone.utc).astimezone(timezone.utc)
    for pattern in ("%Y-%m-%d", "%Y/%m/%d", "%b %d, %Y", "%B %d, %Y"):
        with contextlib.suppress(ValueError):
            return datetime.strptime(text, pattern).replace(tzinfo=timezone.utc)
    return None


def reference_freshness(reference: dict[str, Any], now: datetime | None = None) -> dict[str, Any]:
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    published_raw = clean_text(
        str(
            reference.get("published_date")
            or reference.get("published_at")
            or reference.get("date")
            or ""
        )
    )
    published = parse_reference_datetime(published_raw)
    age_days: int | None = None
    if published is not None:
        age_days = max(0, int((current - published).total_seconds() // 86400))

    source_text = clean_text(
        f"{reference.get('title', '')} {reference.get('snippet', '')}"
    )
    years = sorted({int(value) for value in re.findall(r"(?<!\d)(20\d{2})(?!\d)", source_text)})
    old_event_years = [year for year in years if year <= current.year - 2]
    recent_years = [year for year in years if year >= current.year - 1]
    resurfaced_old_event = bool(old_event_years and not recent_years)

    if age_days is None:
        status = "unknown"
    elif age_days <= 7:
        status = "live"
    elif age_days <= CURRENT_NEWS_MAX_AGE_DAYS:
        status = "recent"
    else:
        status = "stale"
    if resurfaced_old_event:
        status = "historical"
    return {
        "policy_version": NEWS_FRESHNESS_POLICY_VERSION,
        "published_date": published_raw,
        "age_days": age_days,
        "status": status,
        "event_years": years,
        "resurfaced_old_event": resurfaced_old_event,
    }


def prioritize_current_news_references(
    references: list[dict[str, Any]],
    *,
    max_age_days: int = CURRENT_NEWS_MAX_AGE_DAYS,
    allow_unknown: bool = False,
) -> list[dict[str, Any]]:
    ranked: list[dict[str, Any]] = []
    for item in references:
        freshness = reference_freshness(item)
        age_days = freshness.get("age_days")
        if freshness.get("resurfaced_old_event"):
            continue
        if age_days is None and not allow_unknown:
            continue
        if age_days is not None and int(age_days) > max_age_days:
            continue
        entry = dict(item)
        entry["freshness"] = freshness
        entry["freshness_status"] = freshness.get("status")
        entry["age_days"] = age_days
        entry["published_date"] = freshness.get("published_date") or clean_text(str(item.get("published_date") or ""))
        ranked.append(entry)
    ranked.sort(
        key=lambda item: (
            int(item.get("age_days")) if item.get("age_days") is not None else 99999,
            -float(item.get("score") or 0.0),
        )
    )
    return ranked


def search_tavily(
    query: str,
    tavily_topic: str,
    limit: int,
    *,
    time_range: str = "",
) -> list[dict[str, Any]]:
    env = runtime_env()
    api_key = clean_text(env.get("TAVILY_API_KEY", ""))
    if not api_key:
        return []
    resolved_topic = clean_text(tavily_topic or env.get("TAVILY_TOPIC", "general") or "general")
    payload = {
        "api_key": api_key,
        "query": query,
        "topic": resolved_topic,
        "search_depth": "basic",
        "max_results": max(1, min(limit, 10)),
        "include_raw_content": False,
    }
    resolved_time_range = clean_text(time_range).lower()
    if resolved_time_range in {"day", "week", "month", "year", "d", "w", "m", "y"}:
        payload["time_range"] = resolved_time_range
    request = urllib.request.Request(
        "https://api.tavily.com/search",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=25) as response:
            body = json.loads(response.read().decode("utf-8"))
    except (urllib.error.URLError, json.JSONDecodeError, OSError):
        return []

    refs = []
    for index, item in enumerate(body.get("results", []), start=1):
        snippet = item.get("content") or item.get("snippet") or ""
        refs.append(
            {
                "index": index - 1,
                "title": clean_text(item.get("title") or f"检索结果 {index}"),
                "url": clean_text(item.get("url") or ""),
                "source": "Tavily",
                "query": query,
                "snippet": truncate(snippet),
                "score": round(float(item.get("score") or 0.0), 3),
                "has_content": bool(clean_text(snippet)),
                "published_date": clean_text(
                    str(item.get("published_date") or item.get("published_at") or item.get("date") or "")
                ),
            }
        )
    return refs


def search_google_news_rss(query: str, limit: int = 8) -> list[dict[str, Any]]:
    params = urllib.parse.urlencode(
        {
            "q": clean_text(query),
            "hl": "zh-CN",
            "gl": "CN",
            "ceid": "CN:zh-Hans",
        }
    )
    request = urllib.request.Request(
        f"https://news.google.com/rss/search?{params}",
        headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"},
    )
    try:
        with urllib.request.urlopen(request, timeout=12) as response:
            root = ET.fromstring(response.read())
    except (urllib.error.URLError, ET.ParseError, OSError):
        return []
    results: list[dict[str, Any]] = []
    for index, item in enumerate(root.findall("./channel/item"), start=1):
        title = clean_text(item.findtext("title") or "")
        url = clean_text(item.findtext("link") or "")
        published_date = clean_text(item.findtext("pubDate") or "")
        source_node = item.find("source")
        publisher = clean_text(source_node.text if source_node is not None and source_node.text else "")
        if not title or not url:
            continue
        results.append(
            {
                "index": index - 1,
                "title": title,
                "url": url,
                "source": publisher or "Google News",
                "query": query,
                "snippet": title,
                "score": round(max(0.1, 1.0 - (index - 1) * 0.06), 3),
                "has_content": True,
                "published_date": published_date,
            }
        )
        if len(results) >= max(1, min(limit, 20)):
            break
    return results


def search_current_news(query: str, limit: int = 8) -> list[dict[str, Any]]:
    rss_results = search_google_news_rss(query, limit)
    weekly = prioritize_current_news_references(
        search_tavily(query, "news", limit, time_range="week"),
        max_age_days=7,
    )
    rss_weekly = prioritize_current_news_references(
        rss_results,
        max_age_days=7,
    )
    recent = dedupe_references([*weekly, *rss_weekly])
    if len(recent) >= min(3, max(1, limit)):
        return recent[:limit]
    monthly = prioritize_current_news_references(
        search_tavily(query, "news", limit, time_range="month"),
        max_age_days=CURRENT_NEWS_MAX_AGE_DAYS,
    )
    rss_monthly = prioritize_current_news_references(
        rss_results,
        max_age_days=CURRENT_NEWS_MAX_AGE_DAYS,
    )
    return dedupe_references([*recent, *monthly, *rss_monthly])[:limit]


def query_requests_current_news(query: str, tavily_topic: str = "") -> bool:
    source = clean_text(f"{query} {tavily_topic}").lower()
    return clean_text(tavily_topic).lower() == "news" or _contains_any(
        source,
        (
            "最新",
            "刚刚",
            "今日",
            "今天",
            "本周",
            "近期",
            "实况",
            "进展",
            "发布会",
            "官宣",
            "上线",
            "突发",
            "热搜",
            "热点",
            "新闻",
        ),
    )


def search_duckduckgo(query: str, limit: int) -> list[dict[str, Any]]:
    params = urllib.parse.urlencode({"q": query})
    request = urllib.request.Request(
        f"https://duckduckgo.com/html/?{params}",
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36"
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=25) as response:
            raw_html = response.read().decode("utf-8", "ignore")
    except (urllib.error.URLError, OSError):
        return []

    refs = []
    for index, match in enumerate(DDG_RESULT_RE.finditer(raw_html), start=1):
        href, title_html, block = match.groups()
        snippet_match = DDG_SNIPPET_RE.search(block)
        snippet_html = ""
        if snippet_match:
            snippet_html = snippet_match.group(1) or snippet_match.group(2) or ""
        refs.append(
            {
                "index": index - 1,
                "title": html_to_text(title_html) or f"DuckDuckGo 结果 {index}",
                "url": unwrap_ddg_url(href),
                "source": "DuckDuckGo",
                "query": query,
                "snippet": truncate(html_to_text(snippet_html)),
                "score": round(max(0.0, 1.0 - index * 0.08), 3),
                "has_content": bool(clean_text(snippet_html)),
            }
        )
        if len(refs) >= limit:
            break
    return refs


def dedupe_references(references: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[str] = set()
    deduped: list[dict[str, Any]] = []
    for item in references:
        key = clean_text(item.get("url") or "") or clean_text(item.get("title") or "")
        if not key or key in seen:
            continue
        seen.add(key)
        entry = dict(item)
        entry["index"] = len(deduped)
        deduped.append(entry)
    return deduped


PROJECT_SOURCE_VERSION = "production-sources-v1"


def list_project_sources(project_id: int) -> list[dict[str, Any]]:
    payload = storage.read_json(storage.project_file(project_id, "source_materials.json"), {})
    items = (payload.get("items") or []) if isinstance(payload, dict) else []
    return [dict(item) for item in items if isinstance(item, dict)]


def save_project_sources(project_id: int, items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    for index, raw in enumerate(items):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        item["id"] = clean_text(str(item.get("id") or "")) or hashlib.sha1(
            f"{project_id}:{index}:{item.get('url', '')}:{item.get('title', '')}".encode("utf-8")
        ).hexdigest()[:12]
        item["type"] = clean_text(str(item.get("type") or "url")).lower() or "url"
        item["title"] = clean_text(str(item.get("title") or item.get("url") or "未命名资料"))
        item["url"] = clean_text(str(item.get("url") or ""))
        item["snippet"] = clean_text(str(item.get("snippet") or item.get("note") or ""))
        item["source"] = clean_text(str(item.get("source") or "用户资料"))
        item["must_use"] = bool(item.get("must_use", True))
        item["adopted"] = bool(item.get("adopted", True))
        normalized.append(item)
    storage.write_json(
        storage.project_file(project_id, "source_materials.json"),
        {
            "version": PROJECT_SOURCE_VERSION,
            "updated_at": time.time(),
            "items": normalized,
        },
    )
    return normalized


def add_project_source(project_id: int, payload: dict[str, Any]) -> dict[str, Any]:
    items = list_project_sources(project_id)
    source_type = clean_text(str(payload.get("type") or "url")).lower() or "url"
    url = clean_text(str(payload.get("url") or ""))
    title = clean_text(str(payload.get("title") or ""))
    note = clean_text(str(payload.get("note") or payload.get("snippet") or ""))
    if not title:
        title = urllib.parse.urlparse(url).netloc if url else truncate(note, 40)
    source_id = hashlib.sha1(
        f"{project_id}:{source_type}:{url}:{title}:{time.time_ns()}".encode("utf-8")
    ).hexdigest()[:12]
    item = {
        "id": source_id,
        "type": source_type,
        "title": title or "未命名资料",
        "url": url,
        "snippet": note,
        "source": clean_text(str(payload.get("source") or "用户资料")),
        "must_use": bool(payload.get("must_use", True)),
        "adopted": True,
        "created_at": time.time(),
    }
    items.append(item)
    save_project_sources(project_id, items)
    return item


def delete_project_source(project_id: int, source_id: str) -> dict[str, Any]:
    items = list_project_sources(project_id)
    removed = next((item for item in items if clean_text(str(item.get("id") or "")) == source_id), None)
    remaining = [item for item in items if clean_text(str(item.get("id") or "")) != source_id]
    save_project_sources(project_id, remaining)
    if removed and clean_text(str(removed.get("type") or "")) == "image":
        relative_path = clean_text(str(removed.get("relative_path") or ""))
        if relative_path:
            path = storage.project_file(project_id, relative_path)
            with contextlib.suppress(OSError):
                path.unlink()
    return {"ok": True, "removed": removed, "items": remaining}


def project_source_references(project_id: int) -> list[dict[str, Any]]:
    references: list[dict[str, Any]] = []
    for item in list_project_sources(project_id):
        if not bool(item.get("adopted", True)):
            continue
        source_type = clean_text(str(item.get("type") or "url")).lower()
        if source_type == "image" and not clean_text(str(item.get("snippet") or "")):
            continue
        references.append(
            {
                "index": 0,
                "title": clean_text(str(item.get("title") or "用户资料")),
                "url": clean_text(str(item.get("url") or item.get("relative_path") or "")),
                "source": clean_text(str(item.get("source") or "用户资料")),
                "query": "用户指定资料",
                "snippet": clean_text(str(item.get("snippet") or "")),
                "score": 1.0 if bool(item.get("must_use")) else 0.85,
                "has_content": bool(clean_text(str(item.get("snippet") or ""))),
                "must_use": bool(item.get("must_use")),
                "source_material_id": clean_text(str(item.get("id") or "")),
            }
        )
    return references


def search_project_sources(
    project_id: int,
    query: str,
    *,
    current_news: bool = False,
    limit: int = 8,
) -> dict[str, Any]:
    cleaned_query = clean_text(query)
    if not cleaned_query:
        raise ValueError("请输入检索关键词")
    count = max(2, min(int(limit or 8), 12))
    ddg_query = (
        f"{datetime.now().year} {datetime.now().month}月 {cleaned_query}"
        if current_news
        else cleaned_query
    )
    with ThreadPoolExecutor(max_workers=2, thread_name_prefix="source-search") as executor:
        tavily_future = (
            executor.submit(search_current_news, cleaned_query, count)
            if current_news
            else executor.submit(search_tavily, cleaned_query, "general", count)
        )
        ddg_future = executor.submit(search_duckduckgo, ddg_query, count)
        tavily_results = tavily_future.result()
        ddg_results = ddg_future.result()
    merged = dedupe_references([*tavily_results, *ddg_results])[:count]
    candidates: list[dict[str, Any]] = []
    adopted_urls = {
        clean_text(str(item.get("url") or ""))
        for item in list_project_sources(project_id)
        if clean_text(str(item.get("url") or ""))
    }
    for item in merged:
        candidate = dict(item)
        candidate["id"] = hashlib.sha1(
            f"{candidate.get('url', '')}:{candidate.get('title', '')}".encode("utf-8")
        ).hexdigest()[:12]
        candidate["adopted"] = clean_text(str(candidate.get("url") or "")) in adopted_urls
        candidates.append(candidate)
    result = {
        "version": PROJECT_SOURCE_VERSION,
        "query": cleaned_query,
        "current_news": bool(current_news),
        "providers": {
            "Tavily": len(tavily_results),
            "DuckDuckGo": len(ddg_results),
        },
        "results": candidates,
        "searched_at": time.time(),
    }
    storage.write_json(storage.project_file(project_id, "research_candidates.json"), result)
    return result


def get_project_source_candidates(project_id: int) -> dict[str, Any]:
    return storage.read_json(
        storage.project_file(project_id, "research_candidates.json"),
        {"version": PROJECT_SOURCE_VERSION, "query": "", "results": []},
    )


def adopt_project_source_candidate(project_id: int, candidate_id: str) -> dict[str, Any]:
    payload = get_project_source_candidates(project_id)
    results = payload.get("results") if isinstance(payload, dict) else []
    candidate = next(
        (
            dict(item)
            for item in results
            if isinstance(item, dict) and clean_text(str(item.get("id") or "")) == candidate_id
        ),
        None,
    )
    if candidate is None:
        raise ValueError("检索结果已经更新，请重新搜索")
    item = add_project_source(
        project_id,
        {
            "type": "url",
            "title": candidate.get("title"),
            "url": candidate.get("url"),
            "note": candidate.get("snippet"),
            "source": candidate.get("source"),
            "must_use": True,
        },
    )
    for raw in results:
        if isinstance(raw, dict) and clean_text(str(raw.get("id") or "")) == candidate_id:
            raw["adopted"] = True
    storage.write_json(storage.project_file(project_id, "research_candidates.json"), payload)
    return {"ok": True, "item": item, "candidates": payload}


def read_reference_preview(project_id: int, index: int) -> dict[str, Any]:
    references = storage.get_references(project_id)
    if index < 0 or index >= len(references):
        raise IndexError(index)

    reference = dict(references[index])
    url = clean_text(reference.get("url") or "")
    snippet = clean_text(reference.get("snippet") or "")
    content = ""
    content_type = "snippet"
    resolved_path = ""

    if url:
        candidate = Path(url)
        if candidate.exists() and candidate.is_file():
            resolved_path = str(candidate.resolve())
            content = candidate.read_text(encoding="utf-8", errors="ignore")
            content_type = "markdown" if candidate.suffix.lower() in {".md", ".markdown"} else "text"
        elif url.startswith(("http://", "https://")):
            request = urllib.request.Request(
                url,
                headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36"
                },
            )
            try:
                with urllib.request.urlopen(request, timeout=15) as response:
                    payload = response.read().decode("utf-8", "ignore")
                    content = html_to_text(payload)
                    content_type = "html"
            except (urllib.error.URLError, OSError):
                content = ""

    if not content:
        title = clean_text(reference.get("title") or "未命名参考")
        lines = [f"# {title}", ""]
        if url:
            lines.append(f"链接: {url}")
        if reference.get("source"):
            lines.append(f"来源: {reference['source']}")
        if snippet:
            lines.extend(["", "摘要", snippet])
        content = "\n".join(lines).strip()

    return {
        "index": index,
        "reference": reference,
        "content": content,
        "content_type": content_type,
        "resolved_path": resolved_path,
    }


_TOPIC_REFERENCE_ALIASES: dict[str, tuple[str, ...]] = {
    "具身智能": ("embodied ai", "embodied intelligence", "physical ai"),
    "生成式人工智能": ("generative ai", "genai"),
    "人工智能": ("artificial intelligence", " ai "),
}


def locked_topic_terms(topic: str) -> list[str]:
    """Extract the subject terms that a reference must actually discuss."""
    source = repair_legacy_mojibake(clean_text(topic))
    source = re.sub(r"https?://\S+", " ", source, flags=re.I)
    source = re.split(r"\s+--+", source, maxsplit=1)[0]
    source = re.sub(r"[（(][^）)]{0,80}[）)]", " ", source)
    source = re.sub(r"(?:人民网|新华网|央视网|中新网|澎湃新闻|人民日报)$", "", source)
    source = clean_text(source).strip("-—|/·：:，,。！？!? ")
    clauses = [
        clean_text(item).strip("-—|/·：:，,。！？!? ")
        for item in re.split(r"[，,：:；;！？!?|/]", source)
    ]
    terms: list[str] = []
    if 2 <= len(source) <= 28:
        terms.append(source)
    for clause in clauses:
        if 2 <= len(clause) <= 20:
            terms.append(clause)
        for token in re.findall(r"[A-Za-z][A-Za-z0-9+.-]{1,24}|[\u4e00-\u9fff]{2,12}", clause):
            if len(token) >= 2:
                terms.append(token)
    for key, aliases in _TOPIC_REFERENCE_ALIASES.items():
        if key in source:
            terms.extend(aliases)
    return list(dict.fromkeys(term.lower() for term in terms if clean_text(term)))


def reference_topic_score(reference: dict[str, Any], topic: str) -> int:
    title = repair_legacy_mojibake(clean_text(str(reference.get("title") or ""))).lower()
    snippet = repair_legacy_mojibake(clean_text(str(reference.get("snippet") or ""))).lower()
    terms = locked_topic_terms(topic)
    if not title and not snippet:
        return 0
    score = 0
    for index, term in enumerate(terms):
        if not term:
            continue
        weight = 7 if index == 0 else 4
        if term in title:
            score = max(score, weight)
        elif term in snippet:
            score = max(score, 2 if index == 0 else 1)
    return score


def brief_reference_candidates(brief: str, topic: str) -> list[dict[str, Any]]:
    """Promote the locked candidate's cited sources from brief.md into evidence."""
    references: list[dict[str, Any]] = []
    for raw_line in repair_legacy_mojibake(brief).splitlines():
        line = clean_text(raw_line)
        url_match = re.search(r"https?://\S+", line, flags=re.I)
        if not line.startswith("-") or not url_match:
            continue
        url = url_match.group(0).rstrip(".,;，。；")
        description = line[1:url_match.start()].strip()
        description = re.sub(r"^\[[^\]]+\]\s*", "", description)
        title, separator, snippet = description.partition("：")
        if not separator:
            title, separator, snippet = description.partition(": ")
        title = clean_text(title) or clean_text(topic)
        snippet = clean_text(snippet)
        references.append(
            {
                "title": title,
                "url": url,
                "source": urllib.parse.urlparse(url).netloc or "brief",
                "query": clean_text(topic),
                "snippet": snippet,
                "score": 1.0,
                "has_content": bool(snippet),
                "must_use": True,
                "locked_topic_source": True,
            }
        )
    return dedupe_references(references)


def sanitize_locked_topic_brief(brief: str, topic: str) -> str:
    """Remove parallel-news reference lines before a locked brief reaches the writer."""
    kept: list[str] = []
    for raw_line in repair_legacy_mojibake(brief).splitlines():
        line = clean_text(raw_line)
        if line.startswith("-") and re.search(r"https?://\S+", line, flags=re.I):
            candidate = brief_reference_candidates(raw_line, topic)
            if candidate and reference_topic_score(candidate[0], topic) < 4:
                continue
        kept.append(raw_line)
    return "\n".join(kept).strip()


def filter_references_for_locked_topic(
    references: list[dict[str, Any]],
    topic: str,
    *,
    limit: int,
) -> list[dict[str, Any]]:
    ranked: list[tuple[int, int, dict[str, Any]]] = []
    for index, raw in enumerate(references):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        topic_score = reference_topic_score(item, topic)
        extracted_locked_source = bool(item.get("locked_topic_source"))
        required = bool(item.get("must_use")) and not extracted_locked_source
        if extracted_locked_source and topic_score >= 4:
            required = True
        if not required and topic_score < 2:
            continue
        item["topic_score"] = topic_score
        ranked.append((100 if required else topic_score, -index, item))
    ranked.sort(key=lambda row: (row[0], row[1]), reverse=True)
    return dedupe_references([row[2] for row in ranked])[: max(1, limit)]


def build_reference_context(project: dict[str, Any], template: dict[str, Any], brief: str, tavily_topic: str) -> dict[str, Any]:
    env = runtime_env()
    max_refs = max(3, min(int(env.get("TAVILY_MAX_REFERENCES", "20") or 20), 20))
    topic = clean_text(project["topic_name"])
    compact_brief = truncate(brief, 200)
    query = topic if not compact_brief else f"{topic} {compact_brief}"

    local_refs = local_article_references(project, template, brief)
    project_id = int(project.get("id") or 0)
    manual_refs = project_source_references(project_id) if project_id else []
    brief_refs = [
        item
        for item in brief_reference_candidates(brief, topic)
        if reference_topic_score(item, topic) >= 4
    ]
    project_settings = storage.get_project_settings(project_id) if project_id else {}
    current_news_mode = bool(project_settings.get("current_news_mode")) or query_requests_current_news(query, tavily_topic)
    web_refs = (
        search_current_news(query, max_refs)
        if current_news_mode
        else search_tavily(query, tavily_topic, max_refs)
    )
    if not web_refs:
        dated_query = f"{datetime.now().year} {datetime.now().month}月 {query}" if current_news_mode else query
        web_refs = search_duckduckgo(dated_query, min(max_refs, 8))
        if current_news_mode:
            web_refs = [
                {
                    **item,
                    "freshness": reference_freshness(item),
                    "freshness_status": "unknown",
                }
                for item in web_refs
            ]

    manual_refs = filter_references_for_locked_topic(manual_refs, topic, limit=max_refs)
    local_refs = filter_references_for_locked_topic(local_refs, topic, limit=2)
    web_candidates = brief_refs if brief_refs else web_refs
    web_refs = filter_references_for_locked_topic(web_candidates, topic, limit=max_refs)
    refs = dedupe_references(manual_refs + web_refs + local_refs)[:max_refs]
    return {
        "query": query,
        "manual_refs": manual_refs,
        "brief_refs": brief_refs,
        "model_brief": sanitize_locked_topic_brief(brief, topic),
        "local_refs": local_refs,
        "web_refs": web_refs,
        "references": refs,
        "current_news_mode": current_news_mode,
        "freshness_policy_version": NEWS_FRESHNESS_POLICY_VERSION,
    }


def format_reference_block(title: str, refs: list[dict[str, Any]]) -> str:
    if not refs:
        return f"{title}\n- 无"
    lines = [title]
    for item in refs:
        snippet = item.get("snippet") or ""
        freshness = item.get("freshness") if isinstance(item.get("freshness"), dict) else reference_freshness(item)
        published_date = clean_text(str(freshness.get("published_date") or item.get("published_date") or ""))
        freshness_status = clean_text(str(freshness.get("status") or item.get("freshness_status") or "unknown"))
        date_line = f"  发布日期: {published_date or '未知'}（{freshness_status}）\n"
        lines.append(
            f"- 标题: {item.get('title') or '未命名'}\n"
            f"  来源: {item.get('source') or '未知'}\n"
            f"{date_line}"
            f"  链接: {item.get('url') or '无'}\n"
            f"  摘要: {snippet or '无'}"
        )
    return "\n".join(lines)


def message_content_to_text(content: Any) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict):
                parts.append(str(item.get("text") or item.get("content") or ""))
            else:
                parts.append(str(getattr(item, "text", "") or getattr(item, "content", "") or ""))
        return "\n".join(part for part in parts if part).strip()
    return str(content or "").strip()


def compose_deepseek_messages(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str,
    context: dict[str, Any],
) -> list[dict[str, str]]:
    brief_for_model = str(context.get("model_brief") or brief)
    template_prompt = str(template.get("prompt") or "").strip()
    mode = clean_text(template.get("mode") or project.get("template_mode") or "video")
    voice_mode = clean_text(template.get("voice_mode") or "")
    template_identity = {
        "key": template.get("key") or project.get("template") or "",
        "name": template.get("name") or template.get("key") or "",
        "brand_name": template.get("brand_name") or template.get("name") or "",
        "mode": mode,
        "voice_mode": voice_mode,
        "target_audience": template.get("target_audience") or "",
        "channel_voice": template.get("channel_voice") or "",
        "visual_strategy": template.get("visual_strategy") or "",
        "forbidden_rules": template.get("forbidden_rules") or "",
        "interaction_goal": template.get("interaction_goal") or "",
        "topic_mining_hint": template.get("topic_mining_hint") or "",
        "cover_style": template.get("cover_style") or "",
        "release_tags": template.get("release_tags") or "",
    }
    channel_profile = channel_profile_text(template)
    learning = channel_learning_prompt_block(project, template)
    product_rules = build_product_content_rules(project)
    research_plan = (
        storage.read_json(
            storage.project_file(int(project.get("id", 0) or 0), "research_plan.json"),
            {},
        )
        if project.get("id")
        else {}
    )
    research_routes = research_plan.get("routes") if isinstance(research_plan, dict) else []
    research_routes = research_routes if isinstance(research_routes, list) else []
    research_guidance = (
        "本期多源研究路由：\n"
        + "\n".join(
            f"- {clean_text(str(item.get('label') or item.get('provider') or '来源'))}: "
            f"{clean_text(str(item.get('reason') or '用于交叉验证'))}"
            for item in research_routes
            if isinstance(item, dict)
        )
        + "\n这些来源负责发现和交叉验证；写入口播与图片的每个数字仍必须绑定 references.json 中的具体来源。"
        if research_routes
        else ""
    )
    system_rules = """
你现在要为短片工坊生成最终可落地的 content.md。

优先级：
1. 当前频道模板 prompt.md 是最高优先级。频道的人设、语气、角色关系、栏目结构、封面气质、镜头语言、禁忌和发布习惯，都必须服从频道模板；单期时长始终按本期信息量自适应。
2. 当前主题和 brief 只提供本期素材，不得覆盖频道模板风格。不同频道必须生成不同口吻和不同视觉气质。
3. 下方通用要求只用于保证短片工坊生产链路能解析，不允许把所有频道改写成同一种“通用知识科普/爆款反常识”风格。

硬性要求：
1. 只输出最终的 Markdown 成品，不要解释，不要前言，不要致谢。
2. 第一行必须直接从 # 或 ## 标题开始。
3. 如果给了历史稿参考，只能借鉴风格、视角和连续创作语气，不能照搬旧稿。
4. 如果给了联网资料，涉及最新事实、时间、金额、排名、参数时优先以联网资料为准；先核对发布日期和事件发生时间。近期文章回顾旧事件不能写成刚发生；不确定就保守表述。
5. 你的输出必须严格遵守当前模板 prompt 约定的章节、角色标签和图片提示词。时长按本期有效信息量自适应，以讲清核心结论所需的最短完整表达为准；不得为凑时长重复内容，也不得为压时长删掉必要证据。
6. 如果频道模板没有明确章节，按原版兼容结构输出：## Meta、## 原始材料简述、视频频道输出 ## 对话脚本 或 ## 口播脚本、## 重点字幕、## 图片提示词、## 参考资料；图文频道输出 ## 正文、## 图片提示词、## 参考资料。
7. 视频频道的图片提示词必须包含 ### 横屏封面图、### 竖屏封面图、### 场景图；场景图用 1. 2. 3. 编号，数量要匹配有效信息点和语音节奏，通常 90 秒约 4-6 张、2 分钟约 6-8 张、3-4 分钟约 7-9 张、5-6 分钟约 10-14 张。只有新事实、新数字、新案例、新后果、新方法或新结论才新建场景图；“先别急”“你想想”“换个角度”等纯过渡口播沿用上一张图，不得单独配图。比例和像素尺寸由程序控制，不要写进提示词正文。
8. 封面提示词要和频道个人 IP 强关联，允许直接生成项目指定语言下清晰可读的主标题、短副标题和频道名/作者角标；场景图里的文字与信息元素由对应口播决定，可包含数字、短结论、批注、图表和关系线，不限定数量、字数或固定位置，但不能偏离本期事实或把每张图套成同一种封面海报。
9. 每张场景图必须根据对应脚本段落和本期素材重新设计，不要复制同一种纸面手账、档案卡、旧纸、胶带、拼贴背景；除非频道模板或题材明确要求。
10. 生成文案前必须内部使用 Viral Writer 的爆款写作框架：核心观点、副观点、说服策略、情绪触发、金句、情感曲线、情感层次、论证多样性、视角切换、语言风格、互动钩子。只把结论落实到正文，不要把分析 Meta 输出到 content.md。
11. 视频口播必须像对一个具体观众说话：第一句控制在 10-32 个汉字，前三秒直接给具体损失、结果、反差或危险，不能用“今天我们来聊聊”“本期节目”“大家好”开场。
12. 中段每 20-30 秒必须新增一次追看理由：新数字、新案例、更狠后果、误区反转或尖锐追问；不能连续解释超过 3 段。结尾只保留一个低门槛评论动作，不能同时堆叠点赞、收藏、关注、转发等多个要求。
13. `## 口播脚本`、`## 对话脚本`、`## 视频脚本` 内只能写实际要朗读的台词。单人用 `【主播】`，双人只用模板角色；`【画面】`、`【画面切换】`、`【镜头】`、`【场景】`、构图、动作、界面说明和生图提示词只能出现在 `## 图片提示词`，绝不能混入口播区。
14. 输出前逐行做“朗读测试”：去掉角色标签后，这一行必须能被真人直接念出口。凡是描述画面里写了什么、物件摆在哪里、镜头怎么拍、标题放哪里、需要生成什么图片的句子，一律移到 `## 图片提示词`，不得伪装成 `【主播】` 台词。
15. 四类内容必须各归各位：口播只进脚本章节；画面要求只进图片提示词；封面主副标题只进 Meta；推荐发布标题和发布信息只进 Meta。禁止把任一类内容复制到另一类章节。
16. 即使材料存在缺口，也必须利用已核实资料缩小结论、调整标题和叙事范围，交付一份可直接朗读的完整成稿。严禁输出编辑说明、素材缺口清单、补料任务单或“先补齐再写”的占位稿。
17. 如果参考来源是早报、日报、榜单、资讯合集，先根据“当前主题”锁定唯一叙事主线。摘要中其它并列新闻只是噪声，不得写进脚本，不得用一句“其实是同一件事”强行连接无共同因果的事件。
18. 只能使用参考资料中明确写出的事实。只有文章标题而没有正文或摘要证据时，不得推测实验过程、技术指标、人物行为、时间、数字或结论；可以不写，不能自行补全。
""".strip()

    user_parts = [
        f"当前频道配置：{json.dumps(template_identity, ensure_ascii=False)}",
        f"频道中枢：\n{channel_profile or '未填写结构化频道中枢，请严格以 prompt.md 为准。'}",
        learning,
        research_guidance,
        product_facts_prompt_block(project),
        f"当前日期：{datetime.now().astimezone().strftime('%Y-%m-%d')}",
        (
            "新闻时效要求：本期按最新实况处理。核心事件至少需要两条近30天来源相互印证；"
            "优先近7天来源；发布日期未知或只讲多年前事件的资料只能作为背景，不能作为最新进展。"
            if context.get("current_news_mode")
            else "新闻时效要求：如果稿件声称“最新、刚刚、近日”，必须能从参考资料发布日期中得到支持。"
        ),
        f"当前主题：{clean_text(project['topic_name'])}",
        f"联网话题：{tavily_topic or 'general'}",
        "",
        "原始 brief：",
        brief_for_model.strip() or "无",
        "",
        format_reference_block("历史稿参考：", context.get("local_refs", [])),
        "",
        format_reference_block("公开资料参考：", context.get("web_refs", [])),
        "",
        "请严格基于上面的模板规则与材料，一次性写出完整 content.md。写之前先内部完成 Viral Writer 11 个洞见维度的构思，但不要把构思过程输出出来。",
    ]

    return [
        {
            "role": "system",
            "content": "\n\n".join(
                item
                for item in (
                    template_prompt,
                    system_rules,
                    product_rules,
                    build_output_language_rules(project),
                )
                if item
            ),
        },
        {"role": "user", "content": "\n".join(user_parts).strip()},
    ]


def render_fallback_story_content(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    refs: list[dict[str, Any]],
    speaker_mode: str,
) -> str:
    topic = clean_text(project["topic_name"])
    cover_title = fallback_cover_title(topic)
    publish_title = fallback_publish_title(topic)
    cover_subtitle = fallback_cover_subtitle(topic)
    scene_lines = generic_scene_lines(topic, "video")
    duration = "5-6分钟" if len(brief) > 60 else "3-4分钟"

    reference_summary = "；".join(item["title"] for item in refs[:3]) or f"{topic}的公开资料"
    if speaker_mode == "dual":
        dialogue = [
            f"【女】你以为「{topic}」只是表面这个问题？其实真正有意思的，是它背后的那套逻辑。",
            f"【男】对，而且这事最容易被忽略的地方，不是答案本身，而是它为什么会变成今天这个样子。",
            f"【女】那我们就别绕了，先说最关键的起点，到底是哪一步让它开始变味的。",
            f"【男】通常要先把背景讲清楚。只看结果，大家会觉得这是常识；把过程摊开，才发现里面全是转折。",
            f"【女】也就是说，观众真正想听的，不是定义，而是这件事怎么一步步走到这里。",
            f"【男】没错。所以我们会先拆误区，再拿例子，最后再回到今天的人为什么还会被这个问题困住。",
            f"【女】那中间最容易讲错的地方是什么？",
            f"【男】最容易错的是把它讲成概念清单。真正有效的讲法，是让人看到一条完整的因果线。",
            f"【女】所以你最后想让观众记住的，不是术语，而是那个一听就懂的判断。",
            f"【男】对。你下次再遇到「{topic}」，至少知道先看哪个关键点，而不是被表面信息带着跑。",
        ]
    else:
        dialogue = [
            f"【主播】你以为「{topic}」只是个普通话题？真正难的，从来不是定义，而是它背后的那条因果线。",
            f"【主播】很多人一上来就急着下结论，但这事最值得听的，恰恰是它怎么一步步演变成今天这样。",
            f"【主播】如果只背概念，你会觉得它很抽象。可一旦把背景、转折和结果摊开，它就像一个很完整的故事。",
            f"【主播】先说起点。每个类似问题之所以会反复出现，往往都不是因为答案没人知道，而是大家盯错了地方。",
            f"【主播】接着看中段。真正拉开差距的，通常不是表面动作，而是那个被忽略的关键变量。",
            f"【主播】再往下拆，你就会发现，很多我们以为的常识，其实只是讲了半截的旧理解。",
            f"【主播】这时候最有效的办法，不是继续堆术语，而是拿一个具体例子，把它讲成看得见的画面。",
            f"【主播】最后回到今天。下次你再碰到「{topic}」，至少知道先看哪里，而不是被表面信息牵着走。",
        ]

    highlight_lines = [
        f"{topic}真正难的，从来不是表面定义",
        "把背景、转折、结果讲成一条线，内容才会成立",
        "别只背概念，先找那个真正影响结果的变量",
        "回到现实场景，观众才会觉得这期内容有用",
    ]

    scene_prompt_lines = [
        f"宽画幅横向构图，画面必须只对应这段口播「{line}」；文字、数字、批注和关系元素由口播信息量决定，核心事实准确，底部不要脚注、免责声明或无关长段正文。"
        for idx, line in enumerate(scene_lines)
    ]

    refs_block = "\n".join(f"- [{item['title']}]({item['url']}) - {item['snippet']}" for item in refs) or "- 无"

    return (
        f"# {cover_title}\n\n"
        f"## Meta\n"
        f"- 封面副标题: {cover_subtitle}\n"
        f"- 核心观点: {topic}真正值得讲的，是背后那条因果线\n"
        f"- 时长: {duration}\n"
        f"- 推荐发布标题: {publish_title}\n"
        f"- 钩子: 你以为「{topic}」只是个普通问题？真正有意思的是它背后的那套逻辑。\n"
        f"- 互动钩子: 你自己最容易在哪一步想当然？评论区留一句。\n"
        f"- 免责声明:\n\n"
        f"## 原始材料简述\n"
        f"- 主体: {topic}\n"
        f"- 核心知识点: 把这个主题讲成能听懂、能记住、能落地的一条线\n"
        f"- 反常识点: 大家通常只看表面，不看真正的关键变量\n"
        f"- 本期差异化抓手: {reference_summary}\n"
        f"- 联系现实的角度: 下次再次遇到这个主题时，用户知道先看哪里\n\n"
        f"## 对话脚本\n\n"
        + "\n\n".join(dialogue)
        + "\n\n## 重点字幕\n"
        + "\n".join(f"{idx + 1}. {line}" for idx, line in enumerate(highlight_lines))
        + "\n\n## 图片提示词\n\n"
        + "### 横屏封面图\n"
        + f"围绕「{topic}」制作横向封面，主标题「{cover_title}」要清晰可读，副标题「{cover_subtitle}」可小字出现，频道名保持固定角标，文字短而醒目。\n\n"
        + "### 竖屏封面图\n"
        + f"围绕「{topic}」制作竖向封面，主标题「{cover_title}」要清晰可读，副标题「{cover_subtitle}」可小字出现，频道名保持固定角标，文字短而醒目。\n\n"
        + "### 场景图\n"
        + "\n".join(f"{idx + 1}. {line}" for idx, line in enumerate(scene_prompt_lines))
        + "\n\n## 参考资料\n"
        + refs_block
        + "\n"
    )


def render_fallback_article_content(project: dict[str, Any], template: dict[str, Any], brief: str, refs: list[dict[str, Any]]) -> str:
    topic = clean_text(project["topic_name"])
    title = fallback_cover_title(topic)
    subtitle = fallback_cover_subtitle(topic)
    publish_title = f"{topic}，这件事为什么总被大家讲偏？"
    points = [
        f"先把「{topic}」的核心问题点明，让读者知道这篇文章到底要解决什么。",
        f"拆掉围绕「{topic}」最常见的一个误区，制造继续往下读的动力。",
        f"解释「{topic}」真正的关键机制，让抽象概念落成看得见的因果链。",
        f"拿一个现实案例说明「{topic}」为什么值得今天的人重新理解。",
    ]
    image_prompts = [
        f"宽画幅横向构图，画面必须只对应这段口播「{line}」。可按口播组织数字、短结论、批注和关系线，不限制固定数量或位置，不生成无关长段正文。"
        for idx, line in enumerate(points, start=1)
    ]
    refs_block = "\n".join(f"- [{item['title']}]({item['url']}) - {item['snippet']}" for item in refs) or "- 无"
    return (
        f"# {title}\n\n"
        f"## Meta\n"
        f"- 封面副标题: {subtitle}\n"
        f"- 核心观点: {topic}真正值得看的，是那条容易被忽略的逻辑链\n"
        f"- 推荐发布标题: {publish_title}\n"
        f"- 钩子: 你有没有发现，很多人聊「{topic}」时，真正重要的那一步反而最少被提到？\n"
        f"- 互动钩子: 你平时最容易在哪一步被带偏，评论区聊聊。\n"
        f"- 免责声明:\n\n"
        f"## 正文\n\n"
        f"很多人一提到「{topic}」，往往会直接跳到结论。但真正决定读者能不能看进去的，不是结论，而是你有没有把那条最关键的逻辑链讲清楚。\n\n"
        f"### 先把问题点明\n\n"
        f"{points[0]}\n\n"
        f"[配图1]\n\n"
        f"### 为什么总会讲偏\n\n"
        f"{points[1]}\n\n"
        f"- 表面信息通常最容易传播\n"
        f"- 真正关键的转折往往被省掉\n"
        f"- 一旦省掉因果，内容就会变成概念堆砌\n\n"
        f"[配图2]\n\n"
        f"### 真正该看的关键点\n\n"
        f"{points[2]}\n\n"
        f"[配图3]\n\n"
        f"### 回到现实场景\n\n"
        f"{points[3]}\n\n"
        f"[配图4]\n\n"
        f"### 写在最后\n\n"
        f"所以这篇内容真正想留下来的，不是一个孤立答案，而是你下次再碰到「{topic}」时，知道先看哪里。你平时最容易在哪一步被带偏，评论区聊聊。\n\n"
        f"## 图片提示词\n\n"
        f"### 横屏封面图（头图）\n"
        f"宽画幅头图，商业杂志头图风，主视觉围绕「{topic}」，主标题「{title}」和副标题「{subtitle}」清晰可读，文字短而醒目，保留后期叠字安全区。\n\n"
        f"### 场景图（正文配图，按正文配图数 4-8 张）\n"
        + "\n".join(f"{idx + 1}. {prompt}" for idx, prompt in enumerate(image_prompts))
        + "\n\n## 参考资料\n"
        + refs_block
        + "\n"
    )


def fallback_opening_source_fragment(brief: str, *, require_number: bool = False) -> str:
    for raw in re.split(r"[\n。！？!?]", str(brief or "")):
        fragment = clean_text(raw).strip("-*# ；;：:")
        if not 8 <= len(fragment) <= 42:
            continue
        if require_number and not re.search(r"\d", fragment):
            continue
        if any(token in fragment for token in ("请生成", "输出格式", "图片提示词", "字数", "章节", "Markdown", "自动挖题", "brief")):
            continue
        return fragment
    return ""


def fallback_opening_line(topic: str, family: str, brief: str = "") -> str:
    evidence = fallback_opening_source_fragment(brief, require_number=True)
    firsthand = fallback_opening_source_fragment(brief)
    if family == "evidence_number" and evidence:
        return evidence.rstrip("。！？!?") + "。"
    if family == "personal_evidence" and firsthand:
        return firsthand.rstrip("。！？!?") + "。"
    if family == "scene_action":
        if firsthand:
            return firsthand.rstrip("。！？!?") + "。"
        return f"「{topic}」一进入真实使用场景，宣传里没说的那一面就露出来了。"
    if family == "consequence":
        return f"「{topic}」真正让人付代价的，往往不是出问题那一刻，而是发现得太晚。"
    if family == "identity_conflict":
        return f"同样是「{topic}」，有人买到的是方便，有人接住的却是一串麻烦。"
    if family == "belief_collision":
        return f"关于「{topic}」，流传最广的判断，恰好漏掉了决定结果的一步。"
    if family == "open_loop":
        return f"「{topic}」真正改变结果的，是哪个一直没人注意的动作？"
    return f"先说结果：「{topic}」不能只看表面那一层。"


def build_fallback_dialogue_lines(
    topic: str,
    speaker_mode: str,
    project: dict[str, Any] | None = None,
    template: dict[str, Any] | None = None,
    brief: str = "",
) -> list[str]:
    plan = channel_opening_diversity_plan(project or {}, template or {}, brief=brief) if project and template else {}
    opening = fallback_opening_line(topic, clean_text(str(plan.get("selected_family") or "scene_action")), brief)
    if speaker_mode == "dual":
        return [
            f"【女】{opening}",
            f"【男】对，这种题最容易写成解释文，但观众真正想听的，是它到底卡在哪儿，为什么会一步步变成现在这样。",
            f"【女】别上来背概念，先说那个最容易让人误判的瞬间，行吗？",
            f"【男】行。很多时候表面现象看着已经很明显了，可真正决定结果的，往往是后面那个被忽略的小动作。",
            f"【女】这就有意思了，表面看是一个问题，真正关键其实藏在另一层？",
            f"【男】没错。所以中间一定得拆两步：第一步讲大家原来怎么想，第二步讲为什么这种想法会把人带偏。",
            f"【女】那别空讲，你举个具体点的例子，不然观众听到这儿还是会觉得抽象。",
            f"【男】最有效的讲法，就是把它放进一个真实场景里。你一看到人物、动作、结果，马上就知道问题到底出在哪儿。",
            f"【女】所以这期真正要记住的，不是一个大词，而是那个“原来我一直忽略这里”的瞬间。",
            f"【男】对。下次你再碰到「{topic}」，先别急着顺着表面往下想，先找那个真正决定结果的点。",
            f"【女】你平时最容易在哪一步想当然？",
            f"【男】把你第一反应留在评论区，我们就知道下一期该先拆哪种误区了。",
        ]
    return [
        f"【主播】{opening}",
        f"【主播】很多稿子一上来就在解释名词，可短视频观众不等这个，他们更想知道：这事到底为什么会卡住我？",
        f"【主播】先抓那个最容易误判的瞬间。你一旦看懂这一步，后面很多问题都顺了。",
        f"【主播】表面看，大家以为问题就在眼前；但真正关键，通常藏在后面那个不起眼的动作里。",
        f"【主播】这也是为什么同一个题，有人越听越明白，有人却越听越空，因为前者在讲过程，后者只在讲结论。",
        f"【主播】那过程怎么讲才不空？最简单，就是把它塞进一个真实场景里：谁在做、怎么做、结果怎样，一下就清楚了。",
        f"【主播】你会发现，很多旧理解不是完全错，而是只讲了半截。真正把人留住的，是后面那半截反转。",
        f"【主播】别只记一个词，记住那个决定结果的小细节。下次再碰到「{topic}」，先看那里。",
        f"【主播】你自己最容易在哪一步想当然？评论区留一句，我按这个顺序继续拆。",
    ]


def render_fallback_story_content_v2(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    refs: list[dict[str, Any]],
    speaker_mode: str,
) -> str:
    topic = clean_text(project["topic_name"])
    cover_title = fallback_cover_title(topic)
    publish_title = fallback_publish_title(topic)
    cover_subtitle = fallback_cover_subtitle(topic)
    scene_lines = generic_scene_lines(topic, "video")
    duration = "5-6分钟" if len(clean_text(brief)) > 160 else "3-4分钟"
    dialogue = build_fallback_dialogue_lines(topic, speaker_mode, project, template, brief)
    reference_summary = "；".join(item.get("title") or "" for item in refs[:3] if isinstance(item, dict) and clean_text(item.get("title") or "")) or f"{topic} 的公开资料"
    highlight_lines = [
        f"别急着聊「{topic}」的结论，最关键的是第一步。",
        "表面看是一个问题，真正关键往往藏在另一层。",
        "别只背概念，要把它放进真实场景里看。",
        "下次再碰到类似情况，先找那个决定结果的小细节。",
    ]
    scene_prompt_lines = [
        f"宽画幅横向构图，画面必须只对应这段口播「{line}」。保留字幕空间，文字与信息元素由口播需要决定，核心事实准确，不要无关长段正文。"
        for idx, line in enumerate(scene_lines)
    ]
    refs_block = "\n".join(
        f"- [{item.get('title') or '参考资料'}]({item.get('url') or ''}) - {item.get('snippet') or ''}"
        for item in refs
        if isinstance(item, dict)
    ) or "- 暂无参考资料"
    hook = dialogue[0].replace("【女】", "").replace("【男】", "").replace("【主播】", "").strip()
    interaction_hook = "你自己最容易在哪一步想当然？评论区留一句。"
    return (
        f"# {cover_title}\n\n"
        f"## Meta\n"
        f"- 封面副标题: {cover_subtitle}\n"
        f"- 核心观点: 真正能把「{topic}」讲明白的，不是表面结论，而是那条因果链。\n"
        f"- 时长: {duration}\n"
        f"- 推荐发布标题: {publish_title}\n"
        f"- 钩子: {hook}\n"
        f"- 互动钩子: {interaction_hook}\n"
        f"- 免责声明:\n\n"
        f"## 原始材料简述\n"
        f"- 主体: {topic}\n"
        f"- 核心知识点: 不是只讲是什么，而是讲清为什么、怎么一步步发生。\n"
        f"- 反常识点: 大家以为问题在表面，真正关键却在更后面的细节。\n"
        f"- 本期差异化抓手: {reference_summary}\n"
        f"- 联系现实的角度: 下次再碰到类似情况，观众知道先看哪一步。\n\n"
        f"## 对话脚本\n\n"
        + "\n\n".join(dialogue)
        + "\n\n## 重点字幕\n"
        + "\n".join(f"{idx + 1}. {line}" for idx, line in enumerate(highlight_lines))
        + "\n\n## 图片提示词\n"
        + "### 横屏封面图\n"
        + f"围绕「{topic}」制作横向封面，主标题「{cover_title}」清晰可读，副标题「{cover_subtitle}」可小字出现，保留频道角标位置，整体抓眼但不堆字。\n\n"
        + "### 竖屏封面图\n"
        + f"围绕「{topic}」制作竖向封面，主标题「{cover_title}」清晰可读，副标题「{cover_subtitle}」可小字出现，画面留出后期标题区。\n\n"
        + "### 场景图\n"
        + "\n".join(f"{idx + 1}. {line}" for idx, line in enumerate(scene_prompt_lines))
        + "\n\n## 参考资料\n"
        + refs_block
        + "\n"
    )


def render_fallback_article_content_v2(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    refs: list[dict[str, Any]],
) -> str:
    topic = clean_text(project["topic_name"])
    title = fallback_cover_title(topic)
    subtitle = fallback_cover_subtitle(topic)
    publish_title = f"{topic}，很多人从第一步就看偏了"
    opening_plan = channel_opening_diversity_plan(project, template, brief=brief)
    opening = fallback_opening_line(topic, clean_text(str(opening_plan.get("selected_family") or "scene_action")), brief)
    points = [
        f"先把「{topic}」最容易让人误判的那个瞬间点出来，让读者一上来就知道这篇内容为什么值得继续看。",
        f"拆掉围绕「{topic}」最常见的一层旧理解，把“你以为”和“其实”拉开。",
        f"用具体场景把真正的机制讲出来，不讲空概念，只讲看得见的动作和结果。",
        f"最后把它拉回现实，让读者知道下次遇到类似情况该先看哪里。",
    ]
    image_prompts = [
        f"宽画幅横向构图，画面必须只对应这段口播「{line}」。可按口播自由组织数字、结论、批注和图形关系，不设固定数量，不生成无关长段正文。"
        for idx, line in enumerate(points, start=1)
    ]
    refs_block = "\n".join(
        f"- [{item.get('title') or '参考资料'}]({item.get('url') or ''}) - {item.get('snippet') or ''}"
        for item in refs
        if isinstance(item, dict)
    ) or "- 暂无参考资料"
    return (
        f"# {title}\n\n"
        f"## Meta\n"
        f"- 封面副标题: {subtitle}\n"
        f"- 核心观点: 真正值得讲的不是表面定义，而是观众最容易漏掉的那个关键动作。\n"
        f"- 推荐发布标题: {publish_title}\n"
        f"- 钩子: {opening}\n"
        f"- 互动钩子: 你最容易在哪一步看偏，评论区聊聊。\n"
        f"- 免责声明:\n\n"
        f"## 正文\n\n"
        f"{opening}\n\n"
        f"### 先说最容易讲偏的地方\n\n"
        f"{points[0]}\n\n"
        f"[配图1]\n\n"
        f"### 为什么大家总会在这里看偏\n\n"
        f"{points[1]}\n\n"
        f"[配图2]\n\n"
        f"### 真正要看的是哪一步\n\n"
        f"{points[2]}\n\n"
        f"[配图3]\n\n"
        f"### 回到今天，怎么用上这件事\n\n"
        f"{points[3]}\n\n"
        f"[配图4]\n\n"
        f"### 写在最后\n\n"
        f"所以这篇内容真正想留下来的，不是一个孤零零的结论，而是你下次再碰到「{topic}」时，知道先看哪里。你自己最容易在哪一步想当然？评论区聊聊。\n\n"
        f"## 图片提示词\n"
        f"### 横屏封面图（头图）\n"
        f"宽画幅头图，围绕「{topic}」，主标题「{title}」和副标题「{subtitle}」清晰可读，首屏抓人，保留后期文字安全区。\n"
        f"### 场景图（正文配图）\n"
        + "\n".join(f"{idx + 1}. {prompt}" for idx, prompt in enumerate(image_prompts))
        + "\n\n## 参考资料\n"
        + refs_block
        + "\n"
    )


def render_fallback_content_english(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    refs: list[dict[str, Any]],
) -> str:
    """Produce parser-compatible English content when the remote writer is unavailable."""

    topic = clean_text(str(project.get("topic_name") or "This story"))
    mode = clean_text(str(template.get("mode") or "video"))
    voice_mode = clean_text(str(template.get("voice_mode") or "single"))
    settings = project_product_settings(project)
    product_mode = project_is_product_mode(project)
    product_name = clean_text(str(settings.get("product_name") or topic))
    subject = product_name if product_mode else topic
    cover_title = subject.rstrip("?!.,:; ") or "The Detail Everyone Missed"
    cover_subtitle = (
        "What it changes in real use"
        if product_mode
        else "The detail that changes the whole story"
    )
    source_titles = [
        clean_text(str(item.get("title") or ""))
        for item in refs[:3]
        if isinstance(item, dict) and clean_text(str(item.get("title") or ""))
    ]
    source_summary = "; ".join(source_titles) or "the supplied brief and verified project sources"
    references = "\n".join(
        f"- [{clean_text(str(item.get('title') or 'Source'))}]({clean_text(str(item.get('url') or ''))})"
        + (f" - {clean_text(str(item.get('snippet') or ''))}" if clean_text(str(item.get("snippet") or "")) else "")
        for item in refs
        if isinstance(item, dict)
    ) or "- No external source was available; this draft uses only the supplied brief."

    if product_mode:
        target = clean_text(str(settings.get("product_target_customer") or "people comparing similar products"))
        scenarios = clean_text(str(settings.get("product_usage_scenarios") or "daily use"))
        selling_points = dedupe_clauses(
            re.split(r"[\n；;。]+", clean_text(str(settings.get("product_selling_points") or "")))
        )[:4]
        evidence = clean_text(str(settings.get("product_evidence") or ""))
        lead_point = selling_points[0] if selling_points else "whether it solves the problem it claims to solve"
        spoken = [
            f"If you're one of {target}, ignore the feature list for a moment.",
            f"Put {product_name} into {scenarios}. The first thing to test is {lead_point}.",
        ]
        spoken.extend(
            f"Then test this claim in a real action: {point}. Look for the result, not the adjective."
            for point in selling_points[1:]
        )
        if evidence:
            spoken.append(f"Here is the evidence we can verify: {evidence}. Anything beyond that is not a promise.")
        spoken.extend(
            [
                f"That makes {product_name} a better fit for {target}, but only if it matches the way you actually use it.",
                "Which real-world test would you want to see before buying it?",
            ]
        )
        core_view = f"{product_name} is worth considering only when its verified claims survive a real use case."
    else:
        spoken = [
            f"The most important part of {topic} is not the headline. It is the detail that changes what the headline means.",
            "Start with the visible result, then trace the action that produced it.",
            "That is where the common explanation usually breaks: it describes what happened, but skips why it happened.",
            "Now compare the claim with the strongest available evidence.",
            f"For this story, the useful source trail is {source_summary}.",
            "One new fact should change the question, not merely repeat the previous sentence.",
            "The real test is whether the explanation still works in an ordinary, concrete situation.",
            f"So when {topic} appears again, look for the deciding action before accepting the easy conclusion.",
            "Which detail would change your mind first?",
        ]
        core_view = f"The useful story in {topic} is the causal detail that turns a headline into an explanation."

    if mode == "article":
        article_points = spoken[:4]
        image_prompts = [
            f"Wide editorial image for this paragraph: {line} Show one concrete subject, one action, and visible evidence. "
            "Use only correctly spelled English when readable text is necessary."
            for line in article_points
        ]
        return (
            f"# {cover_title}\n\n"
            "## Meta\n"
            f"- 封面副标题: {cover_subtitle}\n"
            f"- 核心观点: {core_view}\n"
            f"- 推荐发布标题: {cover_title}\n"
            f"- 钩子: {spoken[0]}\n"
            f"- 互动钩子: {spoken[-1]}\n\n"
            "## 正文\n\n"
            + "\n\n".join(
                f"### {heading}\n\n{paragraph}\n\n[配图{index}]"
                for index, (heading, paragraph) in enumerate(
                    zip(
                        ("Start with the result", "Find the missing cause", "Test the evidence", "Bring it back to real life"),
                        article_points,
                    ),
                    start=1,
                )
            )
            + "\n\n## 图片提示词\n"
            + f"### 横屏封面图（头图）\nWide editorial cover for {topic}. Exact English headline: “{cover_title}”. "
            f"Exact English subtitle: “{cover_subtitle}”. Strong subject, clear conflict, readable title area.\n"
            + "### 场景图（正文配图）\n"
            + "\n".join(f"{index}. {item}" for index, item in enumerate(image_prompts, start=1))
            + "\n\n## 参考资料\n"
            + references
            + "\n"
        )

    if voice_mode == "dual":
        labels = ("【女】", "【男】")
        script_lines = [f"{labels[index % 2]}{line}" for index, line in enumerate(spoken)]
        script_heading = "## 对话脚本"
    else:
        script_lines = [f"【主播】{line}" for line in spoken]
        script_heading = "## 口播脚本"
    highlights = [
        spoken[0],
        spoken[min(2, len(spoken) - 1)],
        spoken[-2],
    ]
    scene_prompts = [
        f"Wide short-video scene tied only to this narration: “{line}” Show a specific subject, action, consequence, "
        "and source-supported information. Any readable text must be concise, complete, and correctly spelled English."
        for line in spoken[: min(6, len(spoken))]
    ]
    return (
        f"# {cover_title}\n\n"
        "## Meta\n"
        f"- 封面副标题: {cover_subtitle}\n"
        f"- 核心观点: {core_view}\n"
        "- 时长: 按本期信息量自适应，以实际配音为准\n"
        f"- 推荐发布标题: {cover_title}\n"
        f"- 钩子: {spoken[0]}\n"
        f"- 互动钩子: {spoken[-1]}\n\n"
        "## 原始材料简述\n"
        f"- 主体: {subject}\n"
        f"- 核心知识点: {core_view}\n"
        f"- 本期差异化抓手: {source_summary}\n\n"
        f"{script_heading}\n\n"
        + "\n\n".join(script_lines)
        + "\n\n## 重点字幕\n"
        + "\n".join(f"{index}. {line}" for index, line in enumerate(highlights, start=1))
        + "\n\n## 图片提示词\n"
        + f"### 横屏封面图\nWide short-video cover. Exact English headline: “{cover_title}”. "
        f"Exact English subtitle: “{cover_subtitle}”. One dominant subject, one clear conflict, no filler text.\n\n"
        + "### 场景图\n"
        + "\n".join(f"{index}. {item}" for index, item in enumerate(scene_prompts, start=1))
        + "\n\n## 参考资料\n"
        + references
        + "\n"
    )


def render_fallback_content(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str,
    context: dict[str, Any],
) -> str:
    refs = context.get("references", [])
    web_refs = [
        item
        for item in refs
        if isinstance(item, dict) and clean_text(str(item.get("url") or "")).startswith(("http://", "https://"))
    ]
    refs = web_refs or refs
    mode = template.get("mode", "video")
    voice_mode = template.get("voice_mode", "")
    if project_uses_english(project):
        return render_fallback_content_english(project, template, brief, refs)
    if project_is_product_mode(project):
        settings = project_product_settings(project)
        product_name = clean_text(str(settings.get("product_name") or project.get("topic_name") or "这件商品"))
        target = clean_text(str(settings.get("product_target_customer") or "正在比较同类商品的人"))
        scenarios = clean_text(str(settings.get("product_usage_scenarios") or "日常使用场景"))
        points = dedupe_clauses(
            re.split(r"[\n；;。]+", clean_text(str(settings.get("product_selling_points") or "")))
        )[:4]
        evidence = clean_text(str(settings.get("product_evidence") or ""))
        offer = clean_text(str(settings.get("product_offer") or ""))
        point_text = points[0] if points else "是否真正解决你的使用麻烦"
        action = f"先核对{offer}再决定" if offer else "先对照自己的使用场景再决定"
        dialogue = [
            f"【主播】如果你是{target}，先别看一长串参数，先看它能不能解决这个具体麻烦。",
            f"【主播】把{product_name}放进{scenarios}，第一件要验证的就是：{point_text}。",
        ]
        for point in points[1:]:
            dialogue.append(f"【主播】再看一个会影响体验的细节：{point}。别听形容词，直接看使用动作和结果。")
        if evidence:
            dialogue.append(f"【主播】这里能确认的证据是：{evidence}。超出这部分的信息，不拿来替它做保证。")
        dialogue.extend(
            [
                f"【主播】所以它更适合{target}，但你仍然要把自己的{scenarios}放在前面判断。",
                f"【主播】准备入手前，{action}。你最想先看它哪一项真实测试？",
            ]
        )
        refs_block = "\n".join(
            f"- [{item.get('title') or '参考资料'}]({item.get('url') or ''})"
            for item in refs
            if isinstance(item, dict)
        ) or "- 暂无外部参考，内容只使用商品事实表与 brief"
        return (
            f"# {project.get('topic_name') or product_name}\n\n"
            "## Meta\n"
            f"- 封面副标题: {point_text}\n"
            f"- 核心观点: {product_name}值不值得选，要看它在真实使用场景里能否兑现已确认卖点\n"
            f"- 推荐发布标题: {project.get('topic_name') or product_name}\n"
            f"- 钩子: {dialogue[0].replace('【主播】', '')}\n"
            f"- 互动钩子: 你最想先看它哪一项真实测试？\n\n"
            "## 口播脚本\n\n"
            + "\n\n".join(dialogue)
            + "\n\n## 重点字幕\n"
            + "\n".join(f"{index + 1}. {item}" for index, item in enumerate(([point_text] + points[1:3])[:4]))
            + "\n\n## 参考资料\n"
            + refs_block
            + "\n"
        )
    if mode == "article":
        return render_fallback_article_content_v2(project, template, brief, refs)
    if voice_mode == "single":
        return render_fallback_story_content_v2(project, template, brief, refs, speaker_mode="single")
    return render_fallback_story_content_v2(project, template, brief, refs, speaker_mode="dual")


HOLLOW_SCRIPT_PHRASES = (
    "这种题最容易写成解释文",
    "真正决定结果的点",
    "真正决定结果的，往往是",
    "被忽略的小动作",
    "表面看是一个问题",
    "真正关键其实藏在另一层",
    "第一步讲大家原来怎么想",
    "把它放进一个真实场景里",
    "最有效的讲法",
    "下次你再碰到",
    "先找那个真正决定结果",
)


def hollow_script_report(content: str, mode: str = "video") -> dict[str, Any]:
    """Detect editorial scaffolding accidentally shipped as final narration."""
    script = "\n".join(parse_dialogue_lines(content, mode))
    hits = [phrase for phrase in HOLLOW_SCRIPT_PHRASES if phrase in script]
    channel_leak = bool(re.search(r"(?:【[^】]+】\s*)?频道\s*[：:]", script))
    source_title_leak = bool(
        re.search(r"--\s*(?:经济|科技|新闻|社会|财经)", script, flags=re.I)
        or re.search(r"(?:人民网|新华网|央视网|中新网)[」”\"]", script)
    )
    hollow = len(hits) >= 3 or (len(hits) >= 2 and (channel_leak or source_title_leak))
    return {
        "hollow": hollow,
        "hits": hits,
        "channel_leak": channel_leak,
        "source_title_leak": source_title_leak,
    }


def request_deepseek_chat_completion(
    *,
    api_key: str,
    base_url: str,
    model: str,
    messages: list[dict[str, Any]],
    temperature: float,
    max_tokens: int,
    extra_body: dict[str, Any] | None = None,
    timeout: float = 300.0,
) -> tuple[str, str]:
    """Call the OpenAI-compatible endpoint without importing the SDK runtime."""
    endpoint = base_url.rstrip("/")
    if not endpoint.endswith("/chat/completions"):
        endpoint += "/chat/completions"
    payload: dict[str, Any] = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    payload.update(extra_body or {})
    response = _request_provider_json(
        "POST",
        endpoint,
        {
            "Authorization": f"Bearer {api_key}",
            "Accept": "application/json",
        },
        payload,
        timeout=timeout,
    )
    choices = response.get("choices")
    if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
        raise ContentGenerationError("DeepSeek 没有返回可用结果。")
    choice = choices[0]
    message = choice.get("message") if isinstance(choice.get("message"), dict) else {}
    content = repair_legacy_mojibake(
        message_content_to_text(message.get("content") if isinstance(message, dict) else "")
    )
    return content, clean_text(str(choice.get("finish_reason") or ""))


def render_deepseek_content(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str,
    context: dict[str, Any],
) -> str:
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    if not api_key:
        raise ContentGenerationError("DeepSeek API Key 未配置，文案未生成；已阻止使用空壳兜底稿。")

    base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
    model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
    thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
    reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
    messages = compose_deepseek_messages(project, template, brief, tavily_topic, context)
    if messages:
        messages[0]["content"] = "\n\n".join(
            item
            for item in (
                str(messages[0].get("content") or "").strip(),
                build_common_content_system_rules(),
                build_viral_content_rules(project, template),
                build_product_content_rules(project),
                build_output_language_rules(project),
            )
            if item
        )
    request_timeout = configured_timeout_seconds(env, "AI_TEXT_TIMEOUT_SECONDS", 300, 60, 900)

    extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
    if thinking_type in {"enabled", "disabled"}:
        extra_body["thinking"] = {"type": thinking_type}

    def compact_recovery_content() -> str:
        references = context.get("references") if isinstance(context, dict) else []
        references = references if isinstance(references, list) else []
        evidence_lines: list[str] = []
        resolved_topic = clean_text(str(project.get("topic_name") or ""))
        topic_prefix = resolved_topic.replace("...", "").replace("…", "").strip()
        for item in references:
            if not isinstance(item, dict):
                continue
            title = clean_text(str(item.get("title") or ""))
            snippet = clean_text(str(item.get("snippet") or ""))
            url = clean_text(str(item.get("url") or ""))
            if not url.startswith(("http://", "https://")):
                continue
            if topic_prefix and title.startswith(topic_prefix) and len(title) > len(resolved_topic):
                resolved_topic = title
            evidence_lines.append(f"- {title}\n  摘要：{snippet[:650]}\n  来源：{url}")
            if len(evidence_lines) >= 6:
                break
        voice_mode = clean_text(str(template.get("voice_mode") or "single"))
        script_heading = "对话脚本" if voice_mode == "dual" else "口播脚本"
        return_messages = [
            {
                "role": "system",
                "content": (
                    "你是短视频频道主编。只交付可直接生产的完整 content.md，不写分析过程、编辑说明、资料缺口或补料清单。"
                    "资料不足时缩小结论并删除缺少证据的主张，仍然围绕已核实信息完成一篇稿子。"
                    "全文控制在900至1600个中文字，台词自然、具体、可朗读。"
                    "开头直接给反差或结果，中段每2至4句出现新证据、追问或转折，结尾只留一个具体互动问题。"
                    "若来源是早报、日报、榜单或资讯合集，只写与主题标题直接相关的一条因果主线，删除摘要中其它并列新闻。"
                ),
            },
            {
                "role": "user",
                "content": (
                    f"频道：{clean_text(str(template.get('name') or project.get('template') or ''))}\n"
                    f"频道口吻：{clean_text(str(template.get('tone') or template.get('voice') or '犀利但客观，像懂技术的朋友聊天'))}\n"
                    f"主题：{resolved_topic}\n"
                    f"已核实资料：\n{chr(10).join(evidence_lines) or '只使用主题中可确认的信息，不补写精确数字。'}\n\n"
                    "固定输出结构：# 短标题；## Meta；## 原始材料简述；"
                    f"## {script_heading}；## 重点字幕；## 图片提示词；## 参考资料。"
                    "脚本必须是本期新闻成稿，不得出现‘自动挖题’‘素材不足’‘背后逻辑’等占位表达。"
                    "图片提示词生成4至6张，每张绑定对应口播中的一个事实、数字、人物动作或因果关系。"
                ),
            },
        ]
        retry_text, _finish_reason = request_deepseek_chat_completion(
            api_key=api_key,
            base_url=base_url,
            model=model,
            messages=return_messages,
            temperature=0.55,
            max_tokens=7000,
            extra_body=extra_body,
            timeout=request_timeout,
        )
        retry_text = strip_code_fences(retry_text)
        return re.sub(r"(?is)^<think>.*?</think>\s*", "", retry_text).strip()

    try:
        raw_content, finish_reason = request_deepseek_chat_completion(
            api_key=api_key,
            base_url=base_url,
            model=model,
            messages=messages,
            temperature=0.7,
            max_tokens=12000,
            extra_body=extra_body,
            timeout=request_timeout,
        )
    except Exception as exc:
        raise ContentGenerationError(f"调用 DeepSeek 失败：{exc}") from exc

    if finish_reason == "length":
        content = compact_recovery_content()
    else:
        content = strip_code_fences(raw_content)
        content = re.sub(r"(?is)^<think>.*?</think>\s*", "", content).strip()
    if not content.startswith("#"):
        raise ContentGenerationError("DeepSeek 已响应，但返回内容不是完整的 content.md，请重试。")
    engagement = content_engagement_report(content, mode)
    if engagement.get("needs_rewrite"):
        try:
            rewritten, _finish_reason = request_deepseek_chat_completion(
                api_key=api_key,
                base_url=base_url,
                model=model,
                messages=compose_deepseek_rewrite_messages(project, template, content, engagement),
                temperature=0.65,
                max_tokens=12000,
                extra_body=extra_body,
                timeout=request_timeout,
            )
            rewritten = strip_code_fences(rewritten)
            rewritten = re.sub(r"(?is)^<think>.*?</think>\s*", "", rewritten).strip()
            if rewritten.startswith("#"):
                content = rewritten
        except Exception:
            pass
    def has_complete_production_structure(candidate: str) -> bool:
        if mode == "article":
            return all(
                clean_text(extract_section(candidate, title, level=2))
                for title in ("正文", "图片提示词", "参考资料")
            )
        script_ready = any(
            clean_text(extract_section(candidate, title, level=2))
            for title in ("口播脚本", "对话脚本", "视频脚本", "脚本")
        )
        support_ready = all(
            clean_text(extract_section(candidate, title, level=2))
            for title in ("Meta", "重点字幕", "图片提示词", "参考资料")
        )
        return script_ready and support_ready

    if not has_complete_production_structure(content):
        recovered = compact_recovery_content()
        if not has_complete_production_structure(recovered):
            raise ContentGenerationError("DeepSeek 返回的文案结构不完整，已阻止空壳兜底稿进入生产。")
        content = recovered
    hollow = hollow_script_report(content, mode)
    if hollow.get("hollow"):
        raise ContentGenerationError(
            "DeepSeek 返回了通用占位稿，缺少本期事实与案例，已阻止保存。"
        )
    content = compact_content_meta(content)
    return content + ("\n" if not content.endswith("\n") else "")


def render_original_content(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    tavily_topic: str,
) -> dict[str, Any]:
    env = runtime_env()
    if not clean_text(env.get("DEEPSEEK_API_KEY", "")):
        raise ContentGenerationError("原版脚本生成需要先配置 DeepSeek API Key。")

    template_key = clean_text(
        template.get("key")
        or template.get("name")
        or project.get("template")
        or ""
    )
    if not template_key:
        raise ContentGenerationError("当前项目缺少模板信息，无法调用原版脚本链路。")

    prompt_path = storage.TEMPLATES_ROOT / template_key / "prompt.md"
    result = run_original_bridge(
        "content",
        {
            "project_id": int(project["id"]),
            "topic_name": clean_text(project["topic_name"]),
            "brief": brief,
            "template_key": template_key,
            "tavily_topic": tavily_topic,
            "prompt_path": str(prompt_path) if prompt_path.exists() else "",
        },
        env,
        timeout=1800,
    )
    content = strip_code_fences(str(result.get("content") or "")).strip()
    if not content.startswith("#"):
        raise ContentGenerationError("原版脚本链路已返回，但 content.md 结构不完整。")

    references = result.get("references", [])
    if not isinstance(references, list):
        references = []
    normalized_references: list[dict[str, Any]] = []
    for item in references:
        if not isinstance(item, dict):
            continue
        title = clean_text(str(item.get("title") or ""))
        url = clean_text(str(item.get("url") or ""))
        snippet = clean_text(str(item.get("snippet") or ""))
        source = clean_text(str(item.get("source") or ""))
        if not (title or url or snippet):
            continue
        normalized_references.append(
            {
                "title": title or url or "Reference",
                "url": url,
                "snippet": snippet,
                "source": source,
            }
        )

    topic = clean_text(str(project.get("topic_name") or ""))
    locked_references = [
        item
        for item in brief_reference_candidates(brief, topic)
        if reference_topic_score(item, topic) >= 4
    ]
    if locked_references:
        normalized_references = locked_references
    else:
        normalized_references = filter_references_for_locked_topic(
            normalized_references,
            topic,
            limit=8,
        )

    hollow = hollow_script_report(content, clean_text(str(template.get("mode") or "video")))
    if hollow.get("hollow"):
        raise ContentGenerationError("备用链路返回了通用占位稿，已阻止保存。")

    stages = result.get("stages", [])
    if not isinstance(stages, list):
        stages = []
    return {
        "content": content + ("\n" if not content.endswith("\n") else ""),
        "references": normalized_references,
        "stages": [clean_text(str(item)) for item in stages if clean_text(str(item))],
        "provider": "original",
    }


def scene_prompt(project_id: int, filename: str) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    prompt_cache_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    content_path = storage.project_file(project_id, "content.md")
    prompt_cache_fresh = prompt_cache_path.exists() and (
        not content_path.exists() or prompt_cache_path.stat().st_mtime >= content_path.stat().st_mtime
    )
    if prompt_cache_fresh:
        context_hashes = project_image_context_hashes(project_id)
        scene_records = storage.read_json(prompt_cache_path, [])
        for record in scene_records:
            if not isinstance(record, dict):
                continue
            if record.get("filename") == filename:
                if clean_text(str(record.get("content_hash") or "")) != context_hashes.get("content_hash", ""):
                    continue
                if clean_text(str(record.get("topic_hash") or "")) != context_hashes.get("topic_hash", ""):
                    continue
                source_prompt = clean_text(str(record.get("prompt") or record.get("source_prompt") or record.get("label") or ""))
                prompt_source = composer_scene_prompt(source_prompt) or source_prompt
                prompt = optimize_visual_generation_prompt(prompt_source, template, "scene") if source_prompt else ""
                return {"filename": filename, "prompt": prompt}

    summary = storage.get_summary(project_id)
    content = storage.get_content(project_id)
    mode = project.get("template_mode", "video")
    prompts = parse_scene_prompts(content, mode) or generic_scene_lines(project["topic_name"], mode)
    scene_index_matches = re.findall(r"(\d+)", filename)
    scene_index = int(scene_index_matches[0]) if scene_index_matches else 1
    prompt_text = prompts[scene_index - 1] if 0 < scene_index <= len(prompts) else f"围绕「{summary.get('video_title') or project['topic_name']}」生成配图"
    prompt_text = composer_scene_prompt(prompt_text) or prompt_text
    prompt_text = optimize_visual_generation_prompt(prompt_text, template, "scene")
    return {"filename": filename, "prompt": prompt_text}


def _image_review_path(project_id: int) -> Path:
    return storage.project_file(project_id, "image_review.json")


def _scene_output_paths(project_id: int) -> list[Path]:
    return [storage.project_file(project_id, f"scenes/{item['filename']}") for item in storage.scene_status(project_id).get("existing", [])]


def _cover_output_paths(project_id: int) -> list[Path]:
    return [
        storage.project_file(project_id, "covers/cover_landscape.png"),
        storage.project_file(project_id, "covers/cover_story.png"),
        storage.project_file(project_id, "covers/cover_portrait.png"),
    ]


def project_cover_enabled(project_id: int) -> bool:
    """Whether automatic production should generate and require covers."""
    return storage.get_project_settings(project_id).get("cover_enabled", True) is not False


def _asset_fingerprint(paths: list[Path]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for path in paths:
        if not path.exists():
            continue
        stat = path.stat()
        records.append(
            {
                "path": path.as_posix(),
                "size": stat.st_size,
                "mtime_ns": stat.st_mtime_ns,
            }
        )
    return records


def pending_scene_prompt_redraw_indexes(scene_status_payload: dict[str, Any]) -> list[int]:
    existing = scene_status_payload.get("existing") if isinstance(scene_status_payload, dict) else []
    if not isinstance(existing, list):
        return []
    expected = int(scene_status_payload.get("expected_count", 0) or 0)
    indexes: set[int] = set()
    for item in existing:
        if not isinstance(item, dict) or not item.get("prompt_pending_redraw"):
            continue
        try:
            index = int(item.get("index", 0) or 0)
        except (TypeError, ValueError):
            continue
        if index > 0 and (expected <= 0 or index <= expected):
            indexes.add(index)
    return sorted(indexes)


def image_review_status(project_id: int) -> dict[str, Any]:
    raw = storage.read_json(_image_review_path(project_id), {})
    if not isinstance(raw, dict):
        raw = {}
    scene_status_payload = storage.scene_status(project_id)
    pending_redraw_indexes = pending_scene_prompt_redraw_indexes(scene_status_payload)
    candidate_groups = scene_status_payload.get("candidate_groups") if isinstance(scene_status_payload.get("candidate_groups"), list) else []
    pending_candidate_indexes = sorted(
        {
            int(item.get("scene_index", 0) or 0)
            for item in candidate_groups
            if isinstance(item, dict) and item.get("selection_pending") and int(item.get("scene_index", 0) or 0) > 0
        }
    )
    scene_ready = bool(
        scene_status_payload.get("complete")
        and int(scene_status_payload.get("expected_count", 0) or 0) > 0
        and int(scene_status_payload.get("generated_count", 0) or 0) >= int(scene_status_payload.get("expected_count", 0) or 0)
        and not pending_redraw_indexes
    )
    cover_enabled = project_cover_enabled(project_id)
    cover_paths = _cover_output_paths(project_id)
    cover_generated = sum(1 for path in cover_paths if path.exists())
    covers_ready = not cover_enabled or cover_generated == len(cover_paths)
    cover_candidate = cover_candidate_status(project_id)
    cover_candidate_pending = bool(cover_enabled and cover_candidate.get("pending"))
    fingerprint = {
        "scenes": _asset_fingerprint(_scene_output_paths(project_id)),
        "covers": _asset_fingerprint(cover_paths) if cover_enabled else [],
    }
    required = bool(raw.get("required", False))
    stored_fingerprint = raw.get("fingerprint")
    confirmed = (
        bool(raw.get("confirmed"))
        and stored_fingerprint == fingerprint
        and not pending_redraw_indexes
        and not pending_candidate_indexes
        and not cover_candidate_pending
    )
    ready_to_confirm = scene_ready and covers_ready and not pending_candidate_indexes and not cover_candidate_pending
    can_generate_video = bool(
        not pending_candidate_indexes
        and not cover_candidate_pending
        and (
            # Full-auto mode consumes the current complete image set. Prompt
            # policy upgrades remain visible as recommendations, but they do
            # not turn video composition back into an image-generation step.
            not required
            or (confirmed and not pending_redraw_indexes)
        )
    )
    return {
        "required": required,
        "confirmed": confirmed,
        "can_generate_video": can_generate_video,
        "ready_to_confirm": ready_to_confirm,
        "scene_ready": scene_ready,
        "covers_ready": covers_ready,
        "scene_expected": scene_status_payload.get("expected_count", 0),
        "scene_generated": scene_status_payload.get("generated_count", 0),
        "scene_pending_redraw": len(pending_redraw_indexes),
        "scene_pending_redraw_indexes": pending_redraw_indexes,
        "scene_candidate_pending": len(pending_candidate_indexes),
        "scene_candidate_pending_indexes": pending_candidate_indexes,
        "cover_candidate_pending": int(cover_candidate_pending),
        "cover_candidate": cover_candidate,
        "cover_enabled": cover_enabled,
        "cover_expected": len(cover_paths) if cover_enabled else 0,
        "cover_generated": cover_generated,
        "updated_at": raw.get("updated_at"),
        "confirmed_at": raw.get("confirmed_at") if confirmed else None,
        "dirty_reason": "" if confirmed else str(raw.get("dirty_reason") or ""),
    }


def save_image_review_status(project_id: int, *, required: bool | None = None, confirmed: bool | None = None) -> dict[str, Any]:
    raw = storage.read_json(_image_review_path(project_id), {})
    if not isinstance(raw, dict):
        raw = {}
    current_required = bool(raw.get("required", False))
    if required is not None:
        raw["required"] = bool(required)
    elif "required" not in raw:
        raw["required"] = current_required

    if confirmed is not None:
        if confirmed:
            status = image_review_status(project_id)
            if not status.get("ready_to_confirm"):
                if status.get("scene_candidate_pending") or status.get("cover_candidate_pending"):
                    raise ValueError("封面或首镜仍有 A/B 方案待选择，请先采用其中一个方案。")
                raise ValueError(
                    "场景图还没有全部生成，请先补齐图片。"
                    if status.get("cover_enabled") is False
                    else "场景图和封面图还没有全部生成，请先补齐图片。"
                )
            raw["confirmed"] = True
            raw["confirmed_at"] = storage.now_ts()
            raw["dirty_reason"] = ""
            raw["fingerprint"] = {
                "scenes": _asset_fingerprint(_scene_output_paths(project_id)),
                "covers": _asset_fingerprint(_cover_output_paths(project_id)) if project_cover_enabled(project_id) else [],
            }
        else:
            raw["confirmed"] = False
            raw["confirmed_at"] = None
            raw["fingerprint"] = None
            raw["dirty_reason"] = raw.get("dirty_reason") or "图片等待重新确认"

    raw["updated_at"] = storage.now_ts()
    storage.write_json(_image_review_path(project_id), raw)
    return image_review_status(project_id)


def mark_image_review_dirty(project_id: int, reason: str) -> dict[str, Any]:
    raw = storage.read_json(_image_review_path(project_id), {})
    if not isinstance(raw, dict):
        raw = {}
    raw["required"] = bool(raw.get("required", False))
    raw["confirmed"] = False
    raw["confirmed_at"] = None
    raw["fingerprint"] = None
    # Automatic review has no human confirmation gate. Keeping a stale dirty
    # reason here makes an already-adopted image look like a missing candidate.
    raw["dirty_reason"] = reason if raw["required"] else ""
    raw["updated_at"] = storage.now_ts()
    storage.write_json(_image_review_path(project_id), raw)
    return image_review_status(project_id)


def reuse_current_images_for_content(project_id: int) -> dict[str, Any]:
    content_path = storage.project_file(project_id, "content.md")
    if not content_path.exists():
        raise RuntimeError("当前项目还没有 content.md，无法确认复用旧图。")
    scene_paths = [path for path in find_scene_image_paths(project_id) if path.exists()]
    cover_paths = [path for path in _cover_output_paths(project_id) if path.exists()]
    image_paths = scene_paths + cover_paths
    if not image_paths:
        raise RuntimeError("当前项目没有可复用的场景图或封面图。")
    target_mtime = max(time.time(), content_path.stat().st_mtime + 2.0)
    touched: list[str] = []
    for index, path in enumerate(image_paths):
        stamp = target_mtime + index * 0.001
        os.utime(path, (stamp, stamp))
        touched.append(path.as_posix())

    review_status = image_review_status(project_id)
    if review_status.get("ready_to_confirm"):
        review_status = save_image_review_status(project_id, required=review_status.get("required"), confirmed=True)
    else:
        mark_image_review_dirty(project_id, "已复用部分旧图，但图片或封面还未齐，需要补齐后确认")
        review_status = image_review_status(project_id)

    result = {
        "touched": touched,
        "scene_count": len(scene_paths),
        "cover_count": len(cover_paths),
        "review": review_status,
        "reuse_confirmed": bool(review_status.get("can_generate_video")),
        "skip_prompt_preflight": True,
        "saved_at": storage.now_ts(),
        "message": "已将当前旧图标记为适配最新版 content.md，可继续总检或成片。",
    }
    storage.save_report(project_id, "image_reuse", result)
    return result


def assert_images_confirmed_for_video(project_id: int) -> None:
    status = image_review_status(project_id)
    if status.get("can_generate_video"):
        return
    raise RuntimeError("当前项目开启了图片确认关卡。请先确认场景图和封面图，再开始成片合成。")


