def image_prompt_generic_hits(text: str) -> list[str]:
    source = clean_text(text)
    hits = [phrase for phrase in IMAGE_PROMPT_GENERIC_PHRASES if phrase in source]
    if source.count("画面") >= 5:
        hits.append("画面重复过多")
    if source.count("本期") >= 2:
        hits.append("本期泛称过多")
    return dedupe_clauses(hits)


def image_prompt_has_topic_anchor(text: str) -> bool:
    source = clean_text(text)
    if is_semantic_scene_generation_brief(text):
        return True
    return any(
        marker in source
        for marker in (
            "锁定本期主题",
            "必须直接出现或清楚指向",
            "人物动作和冲突都围绕这些信息展开",
            "本镜口播原文",
        )
    )


def clean_generic_visual_clause(clause: str) -> str:
    cleaned = clean_text(clause)
    if not cleaned:
        return ""
    cleaned = re.sub(r"本期画面世界\s*[:：]\s*", "", cleaned)
    cleaned = re.sub(r"用反差、风险、误区或悬念制造第一眼吸引力", "", cleaned)
    cleaned = re.sub(r"把当前口播的结果压成一个正在发生的视觉瞬间", "", cleaned)
    cleaned = re.sub(r"画面不是通用素材图", "", cleaned)
    cleaned = re.sub(r"空间留白充足，信息量集中", "", cleaned)
    cleaned = re.sub(r"画面干净有冲击力", "", cleaned)
    cleaned = re.sub(r"只有封面大标题、一个小角标和主体冲突瞬间", "", cleaned)
    cleaned = re.sub(r"画面只服务这一句话", "", cleaned)
    for phrase in IMAGE_PROMPT_GENERIC_PHRASES:
        if phrase in cleaned:
            cleaned = cleaned.replace(phrase, "")
    cleaned = re.sub(r"[，,；;：:、\s]+$", "", cleaned)
    cleaned = re.sub(r"^[，,；;：:、\s]+", "", cleaned)
    cleaned = re.sub(r"(?:，\s*){2,}", "，", cleaned)
    cleaned = re.sub(r"(?:。\s*){2,}", "。", cleaned)
    return cleaned.strip(" ，,。；;：:")


def strip_generic_visual_filler(prompt: str, *, topic: str = "", source: str = "", purpose: str = "scene") -> str:
    text = normalize_image_prompt(prompt)
    if not text:
        return text
    clauses = split_prompt_clauses(text)
    if len(clauses) <= 2:
        return text

    topic_text = clean_text(topic)
    source_text = clean_text(source)
    specific_source = f"{topic_text} {source_text}"
    for phrase in IMAGE_PROMPT_GENERIC_PHRASES:
        specific_source = specific_source.replace(phrase, " ")
    specific_source = specific_source.replace("画面", " ").replace("本期", " ")
    specific_tokens = [
        token
        for token in semantic_tokens(specific_source, limit=80)
        if len(token) >= 2 and token not in IMAGE_ALIGNMENT_STOPWORDS
    ]
    specific_numbers = set(re.findall(r"\d+(?:\.\d+)?%?", specific_source))

    kept: list[str] = []
    removed = 0
    for clause in clauses:
        clause_text = clean_text(clause)
        hits = image_prompt_generic_hits(clause_text)
        if not hits:
            kept.append(clause)
            continue
        cleaned_clause = clean_generic_visual_clause(clause_text)
        lowered = clause_text.lower()
        has_specific_token = any(token and token in lowered for token in specific_tokens)
        has_specific_number = any(number and number in clause_text for number in specific_numbers)
        has_anchor = image_prompt_has_topic_anchor(clause_text)
        if not cleaned_clause and not has_anchor:
            removed += 1
            continue
        if cleaned_clause and cleaned_clause != clause_text and (has_anchor or has_specific_token or has_specific_number):
            kept.append(cleaned_clause)
            removed += 1
            continue
        if has_anchor or has_specific_token or has_specific_number:
            kept.append(clause)
        else:
            removed += 1

    if not removed or len(kept) < 2:
        return text
    return compact_visual_image_prompt("。".join(dedupe_clauses(kept)), 620 if purpose == "cover" else 520)


def image_prompt_topic_anchor_clause(topic: str, source: str, purpose: str) -> str:
    topic_text = clean_text(topic)
    source_text = clean_text(source)
    if not topic_text:
        return ""
    key_terms: list[str] = []
    visual_candidates = (
        "智能手表",
        "血氧",
        "血氧读数",
        "指夹式血氧仪",
        "专业血氧仪",
        "PPG",
        "传感器",
        "手机屏幕",
        "数据光牌",
        "老人",
        "家人",
        "客厅",
        "手机",
        "手机屏幕",
        "应用",
        "删除App",
        "移除App",
        "缓存",
        "残留文件",
        "残留文件夹",
        "账号数据",
        "存储空间",
        "存储设置",
        "红色存储条",
        "其他文件",
        "文件夹",
        "数据光牌",
        "设置",
    )
    for token in visual_candidates:
        if token in source_text or token in topic_text:
            key_terms.append(token)
    key_terms.extend(
        re.findall(
            r"\d+(?:\.\d+)?(?:%|万|亿|元|美元|分钟|小时|年|次|倍|分|部|个|点)",
            source_text,
        )[:4]
    )
    key_terms = dedupe_clauses([item for item in key_terms if clean_text(item)])[:8]
    if not key_terms:
        if purpose == "cover":
            return f"封面主题情境：{summarize_scene_text(topic_text, 34)}，画面聚焦封面标题、核心冲突、真实人物、关键物件和第一眼钩子"
        return f"主题情境：{summarize_scene_text(topic_text, 34)}，画面聚焦当前口播里的真实人物、动作、关键物件和冲突瞬间"
    label = "封面主题情境" if purpose == "cover" else "本镜主题情境"
    if purpose == "cover":
        return f"{label}：{summarize_scene_text(topic_text, 34)}，可见主体优先来自封面标题和主题钩子里的{'、'.join(key_terms[:5])}，人物动作和冲突由标题钩子触发"
    return f"{label}：{summarize_scene_text(topic_text, 34)}，可见主体优先来自当前口播里的{'、'.join(key_terms[:5])}，人物动作和冲突由这句口播触发"


def ensure_prompt_keeps_topic_anchor(prompt: str, *, topic: str, source: str, purpose: str) -> str:
    text = normalize_image_prompt(prompt)
    topic_text = clean_text(topic)
    if not text or not topic_text:
        return text
    topic_score = token_overlap_score(text, topic_text, limit=24)
    generic_hits = image_prompt_generic_hits(text)
    if topic_score >= 45 and len(generic_hits) < 3:
        return text
    anchor = image_prompt_topic_anchor_clause(topic_text, source or text, purpose)
    if not anchor:
        return text
    anchored = compact_visual_image_prompt("。".join([anchor, text]), 620 if purpose == "cover" else 520)
    return strip_generic_visual_filler(anchored, topic=topic_text, source=source or text, purpose=purpose)


def clamp_number(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def image_prompt_context_map(project_id: int, content: str = "", mode: str = "video") -> dict[str, str]:
    root = storage.project_dir(project_id)
    prompts: dict[str, str] = {}
    prompt_cache_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    content_path = storage.project_file(project_id, "content.md")
    prompt_cache_fresh = prompt_cache_path.exists() and (
        not content_path.exists() or prompt_cache_path.stat().st_mtime >= content_path.stat().st_mtime
    )
    scene_records = storage.read_json(prompt_cache_path, []) if prompt_cache_fresh else []
    if not isinstance(scene_records, list):
        scene_records = []
    scene_prompts = [
        clean_text(str(record.get("prompt") or record.get("source_prompt") or ""))
        for record in scene_records
        if isinstance(record, dict)
    ]
    if not scene_prompts and content:
        scene_prompts = visual_prompt_manifest_scene_prompts(project_id, content) or parse_scene_prompts(content, mode)
    for index, prompt in enumerate(scene_prompts, start=1):
        prompts[f"scenes/s_{index:02d}.png"] = prompt

    # Quality checks must score the prompt that actually produced each asset,
    # not a newer plan/cache that may differ from the generated image.
    for path in find_scene_image_paths(project_id):
        relative = str(path.relative_to(root)).replace("\\", "/")
        actual_prompt = ""
        audit_path = path.with_suffix(".audit.json")
        if audit_path.exists():
            audit = storage.read_json(audit_path, {})
            if isinstance(audit, dict):
                actual_prompt = clean_text(str(audit.get("prompt") or ""))
        md_path = path.with_suffix(".md")
        if not actual_prompt and md_path.exists():
            with contextlib.suppress(Exception):
                actual_prompt = clean_text(storage.read_text(md_path))
        if actual_prompt:
            prompts[relative] = actual_prompt

    for path in _cover_output_paths(project_id):
        relative = str(path.relative_to(root)).replace("\\", "/")
        actual_prompt = ""
        audit_path = path.with_suffix(".audit.json")
        if audit_path.exists():
            audit = storage.read_json(audit_path, {})
            if isinstance(audit, dict):
                actual_prompt = clean_text(str(audit.get("prompt") or ""))
        md_path = path.with_suffix(".md")
        if not actual_prompt and md_path.exists():
            with contextlib.suppress(Exception):
                actual_prompt = clean_text(storage.read_text(md_path))
        if actual_prompt:
            prompts[relative] = actual_prompt
    return prompts


def score_term_presence(text: str, terms: tuple[str, ...], weight: float) -> float:
    if not text:
        return 0.0
    hits = sum(1 for term in terms if term and term in text)
    return min(weight, hits * (weight / 2.0))


def semantic_tokens(text: str, limit: int = 80) -> list[str]:
    cleaned = clean_text(text)
    tokens = re.findall(r"[A-Za-z]{2,}|[0-9]+(?:\.[0-9]+)?(?:万|亿|%|美元|元|小时|分钟|年|次)?|[\u4e00-\u9fff]{2,14}", cleaned)
    result: list[str] = []
    for token in tokens:
        token = clean_text(token)
        if not token or token in IMAGE_ALIGNMENT_STOPWORDS:
            continue
        if len(token) == 2 and token in {"横向", "竖向", "清楚", "短视", "画幅"}:
            continue
        result.append(token.lower())
        if len(result) >= limit:
            break
    return dedupe_clauses(result)


def token_overlap_score(prompt: str, target: str, *, limit: int = 80) -> int:
    target_tokens = semantic_tokens(target, limit=limit)
    if not target_tokens:
        return 70
    prompt_text = clean_text(prompt).lower()
    hits = sum(1 for token in target_tokens if token and token in prompt_text)
    return int(round(clamp_number((hits / max(1, min(len(target_tokens), 12))) * 100, 0, 100)))


def normalize_scene_semantic_context(context: dict[str, Any]) -> dict[str, Any]:
    """Keep a rebuilt scene attached to its explicit audio anchor."""
    normalized = dict(context or {})
    anchor = clean_scene_spoken_text(str(normalized.get("audio_anchor") or ""))
    speech = clean_scene_spoken_text(str(normalized.get("speech") or ""))
    anchor_key = re.sub(r"[^\u4e00-\u9fffA-Za-z0-9]+", "", anchor).lower()
    speech_key = re.sub(r"[^\u4e00-\u9fffA-Za-z0-9]+", "", speech).lower()
    if anchor:
        if speech and speech_key != anchor_key:
            normalized["timeline_speech"] = speech
        normalized["speech"] = anchor
        normalized["speech_rebound_to_audio_anchor"] = bool(anchor_key not in speech_key)
    else:
        normalized["speech"] = speech
    normalized["audio_anchor"] = anchor
    return normalized


def image_semantic_context_map(project_id: int, content: str = "", mode: str = "video") -> dict[str, dict[str, Any]]:
    project = storage.get_project(project_id)
    topic = clean_text(str(project.get("topic_name") or first_heading(content) or ""))
    summary = summarize_content(content, mode) if content else {}
    fact_registry = build_episode_fact_registry(project_id, content) if clean_text(content) else {}
    verified_fact_set = {
        clean_text(str(item))
        for item in (fact_registry.get("verified_facts") or [])
        if clean_text(str(item))
    }

    def verified_facts_for_text(value: str) -> list[str]:
        present_keys = {
            key
            for token in extract_numeric_fact_tokens(value)
            for key in numeric_fact_equivalence_keys(token)
        }
        return sorted(
            fact
            for fact in verified_fact_set
            if numeric_fact_equivalence_keys(fact).intersection(present_keys)
        )

    result: dict[str, dict[str, Any]] = {}
    scene_plan = storage.read_json(storage.project_file(project_id, "audio/scene_plan.json"), {})
    scenes = scene_plan.get("scenes") if isinstance(scene_plan, dict) else []
    if isinstance(scenes, list):
        for scene in scenes:
            if not isinstance(scene, dict):
                continue
            index = int(scene.get("index") or 0)
            if not index:
                continue
            director = scene.get("visual_director") if isinstance(scene.get("visual_director"), dict) else {}
            speech_text = clean_scene_spoken_text(
                str(
                    scene.get("speech_text")
                    or scene.get("speech_summary")
                    or scene.get("audio_anchor")
                    or director.get("dialogue_anchor")
                    or scene.get("source_prompt")
                    or ""
                )
            )
            result[f"scenes/s_{index:02d}.png"] = normalize_scene_semantic_context({
                "topic": topic,
                "speech": speech_text,
                "audio_anchor": clean_scene_spoken_text(
                    str(scene.get("audio_anchor") or director.get("dialogue_anchor") or scene.get("speech_summary") or "")
                ),
                "visual_director": " ".join(
                    [
                        str(director.get("beat") or ""),
                        str(director.get("dialogue_anchor") or ""),
                        " ".join(str(item) for item in director.get("primary_subjects", []) if clean_text(str(item))),
                        str(director.get("action_peak") or ""),
                        str(director.get("tension") or ""),
                        " ".join(str(item) for item in director.get("attention_hooks", []) if clean_text(str(item))),
                    ]
                ),
            })
    prompt_manifest = load_visual_prompt_manifest(project_id, content) if content else {}
    manifest_scenes = prompt_manifest.get("scenes") if isinstance(prompt_manifest.get("scenes"), list) else []
    content_scene_prompts = [
        clean_text(str(item.get("prompt") or ""))
        for item in manifest_scenes
        if isinstance(item, dict) and clean_text(str(item.get("prompt") or ""))
    ]
    if not content_scene_prompts and content:
        content_scene_prompts = parse_scene_prompts(content, mode)
    for index, scene_prompt_text in enumerate(content_scene_prompts, start=1):
        rel = f"scenes/s_{index:02d}.png"
        prompt_text = clean_text(scene_prompt_text)
        if not prompt_text:
            continue
        context = result.setdefault(rel, {"topic": topic, "speech": "", "visual_director": ""})
        dialogue_hint = extract_prompt_dialogue_hint_full(prompt_text) or extract_prompt_dialogue_hint(prompt_text, 100)
        if dialogue_hint and not clean_text(str(context.get("speech") or "")):
            context["speech"] = clean_text(dialogue_hint)
        context["visual_director"] = clean_text(f"{context.get('visual_director', '')} {prompt_text}")
        manifest_scene = manifest_scenes[index - 1] if index <= len(manifest_scenes) and isinstance(manifest_scenes[index - 1], dict) else {}
        source_information = manifest_scene.get("source_information") if isinstance(manifest_scene.get("source_information"), dict) else {}
        if source_information:
            context["source_information"] = source_information
            context["source_information_text"] = " ".join(
                [
                    clean_text(str(source_information.get("primary_message") or "")),
                    *[
                        clean_text(str(item))
                        for item in source_information.get("supporting_evidence", [])
                        if clean_text(str(item))
                    ],
                ]
            )
        result[rel] = normalize_scene_semantic_context(context)
    if content:
        source_candidates = source_information_candidates(project_id, topic=topic, content=content)
        for context in result.values():
            current_information = (
                context.get("source_information")
                if isinstance(context.get("source_information"), dict)
                else {}
            )
            current_evidence = current_information.get("supporting_evidence")
            if isinstance(current_evidence, list) and any(clean_text(str(item)) for item in current_evidence):
                continue
            rebuilt_information = scene_source_information_payload(
                project_id,
                topic=topic,
                speech=clean_text(str(context.get("audio_anchor") or context.get("speech") or "")),
                content=content,
                candidates=source_candidates,
            )
            context["source_information"] = rebuilt_information
            context["source_information_text"] = " ".join(
                [
                    clean_text(str(rebuilt_information.get("primary_message") or "")),
                    *[
                        clean_text(str(item))
                        for item in rebuilt_information.get("supporting_evidence", [])
                        if clean_text(str(item))
                    ],
                ]
            )
    if fact_registry.get("version") == FACT_REGISTRY_VERSION:
        for context in result.values():
            scene_source = clean_text(
                f"{context.get('audio_anchor', '')} {context.get('speech', '')}"
            )
            allowed_facts = verified_facts_for_text(scene_source)
            context["fact_registry_enforced"] = True
            context["allowed_numeric_facts"] = allowed_facts
            context["fact_source"] = " ".join(allowed_facts)
    cover_speech = " ".join(
        clean_text(str(item))
        for item in (
            summary.get("cover_title"),
            summary.get("cover_subtitle"),
            summary.get("publish_title"),
            extract_bullet_field(content, "钩子"),
            extract_bullet_field(content, "核心观点"),
        )
        if clean_text(str(item))
    )
    # A cover is allowed to repeat numbers that are literally part of the
    # selected topic/title (dates, model numbers, prices, etc.). Previously the
    # scene-only fact registry rejected those title numbers and stopped the
    # pipeline after every scene image had already been generated.
    cover_allowed_facts = {
        *verified_fact_set,
        *[
            normalized_numeric_fact(item)
            for item in extract_numeric_fact_tokens(f"{topic} {cover_speech}")
            if normalized_numeric_fact(item)
        ],
    }
    cover_context = {
        "topic": topic,
        "speech": cover_speech,
        "fact_source": " ".join(sorted(cover_allowed_facts)),
        "fact_registry_enforced": fact_registry.get("version") == FACT_REGISTRY_VERSION,
        "allowed_numeric_facts": sorted(cover_allowed_facts),
        "visual_director": clean_text(str((scene_plan.get("visual_brief") if isinstance(scene_plan, dict) else {}) or "")),
    }
    for path in _cover_output_paths(project_id):
        rel = str(path.relative_to(storage.project_dir(project_id))).replace("\\", "/")
        result[rel] = cover_context
    return result


def image_semantic_score(prompt: str, context: dict[str, Any], *, is_cover: bool = False) -> dict[str, Any]:
    text = clean_text(prompt)
    topic = clean_text(str(context.get("topic") or ""))
    speech = clean_text(str(context.get("speech") or ""))
    audio_anchor = clean_text(str(context.get("audio_anchor") or ""))
    director = clean_text(str(context.get("visual_director") or ""))
    topic_score = token_overlap_score(text, topic, limit=24) if topic else 70
    if is_cover and topic:
        topic_score = max(topic_score, int(clamp_number(_visual_decision_overlap(text, topic) * 30, 0, 100)))
    speech_score = token_overlap_score(text, speech, limit=60) if speech else 55
    cover_key_score = 0
    if is_cover and speech:
        cover_key_score = int(clamp_number(_visual_decision_overlap(text, speech) * 9, 0, 100))
        speech_score = max(speech_score, cover_key_score)
    anchor_score = token_overlap_score(text, audio_anchor, limit=32) if audio_anchor else speech_score
    director_score = token_overlap_score(text, director, limit=60) if director else 55
    if is_cover and director:
        director_score = max(director_score, int(clamp_number(_visual_decision_overlap(text, director) * 12, 0, 100)))
    attraction = 45
    attraction += int(score_term_presence(text, IMAGE_APPEAL_SUBJECT_TERMS, 16))
    attraction += int(score_term_presence(text, IMAGE_APPEAL_ACTION_TERMS, 16))
    attraction += int(score_term_presence(text, IMAGE_APPEAL_CONFLICT_TERMS, 18))
    attraction += int(score_term_presence(text, IMAGE_APPEAL_TEXT_TERMS, 8 if is_cover else 5))
    attraction_score = int(clamp_number(attraction, 0, 100))
    meta_hits = [term for term in IMAGE_PROMPT_META_POLLUTION_TERMS if term in text]
    semantic_source = "\n".join(item for item in (topic, audio_anchor, speech, director) if item)
    foreign_callouts = foreign_scene_callout_hits(text, semantic_source) if not is_cover else []
    foreign_numeric = foreign_scene_numeric_facts(text, context)
    text_safety = max(0, 100 - len(meta_hits) * 18 - len(foreign_callouts) * 28 - len(foreign_numeric) * 24)
    if is_cover:
        overall = int(
            round(
                topic_score * 0.22
                + speech_score * 0.28
                + director_score * 0.1
                + attraction_score * 0.25
                + text_safety * 0.15
            )
        )
    else:
        overall = int(
            round(
                topic_score * 0.18
                + anchor_score * 0.28
                + speech_score * 0.18
                + director_score * 0.08
                + attraction_score * 0.18
                + text_safety * 0.1
            )
        )
    if foreign_callouts:
        overall = max(0, overall - min(45, len(foreign_callouts) * 18))
    if foreign_numeric:
        overall = max(0, overall - min(45, len(foreign_numeric) * 18))
    reasons: list[str] = []
    suggestions: list[str] = []
    if topic_score < 45:
        reasons.append("主题关键词贴合偏弱。")
        suggestions.append("把本期主题里的核心名词放进主主体或画面冲突。")
    if speech_score < 45:
        reasons.append("与本段口播贴合偏弱。")
        suggestions.append("用本段口播里的物件、动作、数字或人物关系重写这一张。")
    if audio_anchor and anchor_score < 45:
        reasons.append("没有准确承接当前关键口播。")
        suggestions.append("先围绕 audio_anchor 的核心对象、动作和事实重新选择视觉概念。")
    if attraction_score < 65:
        reasons.append("第一眼吸引力不足，缺少明确主体、动作或冲突。")
        suggestions.append("加入表情、动作峰值、强对比、关键物件或短数字钩子。")
    if meta_hits:
        reasons.append(f"提示词含生产说明：{', '.join(meta_hits[:4])}。")
        suggestions.append("清除画幅比例、编号、场景图等元信息，只保留画面内容。")
    if foreign_callouts:
        reasons.append(f"提示词混入跨题材短词：{', '.join(foreign_callouts[:4])}。")
        suggestions.append("删除不在当前主题、口播或视觉导演计划中的短词，再重新生成这张图。")
    if foreign_numeric:
        reasons.append(f"提示词新增了当前语义来源中没有的数字：{', '.join(foreign_numeric[:4])}。")
        suggestions.append("只保留标题、口播或已核实资料里的数字，不自行计算或补写新数字。")
    return {
        "overall": overall,
        "topic": topic_score,
        "speech": speech_score,
        "cover_key": cover_key_score,
        "audio_anchor": anchor_score,
        "visual_director": director_score,
        "attraction": attraction_score,
        "text_safety": text_safety,
        "meta_hits": meta_hits[:8],
        "foreign_callouts": foreign_callouts[:8],
        "foreign_numeric_facts": foreign_numeric[:8],
        "reasons": reasons[:5],
        "suggestions": list(dict.fromkeys(suggestions))[:5],
    }


def image_appeal_score(item: dict[str, Any], prompt: str = "", *, is_cover: bool = False, semantic_context: dict[str, Any] | None = None) -> dict[str, Any]:
    score = 45.0
    reasons: list[str] = []
    suggestions: list[str] = []

    if not item.get("ok"):
        return {
            "score": 0,
            "grade": "不可用",
            "reasons": ["图片不可用或无法读取。"],
            "suggestions": ["先重新生成这张图片。"],
        }

    mean_luma = float(item.get("mean_luma", 0) or 0)
    contrast = float(item.get("contrast", 0) or 0)
    edge_score = float(item.get("edge_score", 0) or 0)
    width = int(item.get("width", 0) or 0)
    height = int(item.get("height", 0) or 0)

    if 52 <= mean_luma <= 205:
        score += 10
    elif mean_luma < 32:
        score -= 18
        reasons.append("整体偏暗，首帧容易被划走。")
        suggestions.append("提高主体亮度，加入明确光源或更干净的前景。")
    elif mean_luma > 230:
        score -= 10
        reasons.append("整体过亮，层次和主体可能被冲淡。")
        suggestions.append("降低背景亮度，用阴影或色块把主体托出来。")

    if contrast >= 36:
        score += 15
    elif contrast >= 24:
        score += 8
    else:
        score -= 14
        reasons.append("对比度偏低，画面可能显得太素。")
        suggestions.append("增强明暗反差、前后景分离或加入醒目的色彩冲突。")

    if edge_score >= 8:
        score += 12
    elif edge_score >= 5:
        score += 6
    else:
        score -= 10
        reasons.append("细节密度偏低，主体抓眼度不足。")
        suggestions.append("换成近景人物、清晰物件动作或更具体的场景。")

    if width >= 1280 and height >= 720:
        score += 6
    else:
        score -= 8
        reasons.append("分辨率偏低，不适合做短视频主图。")
        suggestions.append("按当前任务要求的场景图或封面尺寸重绘。")

    prompt_score = 0.0
    prompt_score += score_term_presence(prompt, IMAGE_APPEAL_SUBJECT_TERMS, 8)
    prompt_score += score_term_presence(prompt, IMAGE_APPEAL_ACTION_TERMS, 7)
    prompt_score += score_term_presence(prompt, IMAGE_APPEAL_CONFLICT_TERMS, 10)
    prompt_score += score_term_presence(prompt, IMAGE_APPEAL_SCENE_TERMS, 6)
    prompt_score += score_term_presence(prompt, IMAGE_APPEAL_TEXT_TERMS, 4 if is_cover else 2)
    if prompt:
        score += prompt_score
    else:
        score -= 8
        reasons.append("没有找到对应提示词，无法确认画面是否绑定口播。")
        suggestions.append("重新生成提示词，让图片绑定频道、主题和本段口播。")

    if is_cover:
        title_terms = ("标题", "主标题", "副标题", "钩子", "封面", "角标", "频道", "作者", "短标签")
        if any(term in prompt for term in title_terms):
            score += 6
        else:
            score -= 8
            reasons.append("封面缺少点击理由或个人 IP 标识。")
            suggestions.append("封面提示词加入主标题、短标签、频道角标和一个强主体。")
    else:
        if any(term in prompt for term in ("口播", "阶段", "画面重点", "对应")):
            score += 5
        else:
            score -= 5
            reasons.append("场景图提示词与口播绑定不够明显。")
            suggestions.append("把本段最关键的一句口播改成画面动作或人物关系。")

    if not reasons and score < 78:
        reasons.append("画面基础指标可用，但还缺少更强的第一眼冲击。")
        suggestions.append("增加人物表情、动作冲突或具体物件，让画面一眼能读懂。")

    semantic = image_semantic_score(prompt, semantic_context or {}, is_cover=is_cover) if prompt else {
        "overall": 0,
        "topic": 0,
        "speech": 0,
        "visual_director": 0,
        "attraction": 0,
        "text_safety": 0,
        "meta_hits": [],
        "reasons": ["没有提示词，无法做主题/口播贴合评分。"],
        "suggestions": ["重新生成提示词和图片记录。"],
    }
    semantic_overall = int(semantic.get("overall", 0) or 0)
    if semantic_overall >= 82:
        score += 8
    elif semantic_overall >= 68:
        score += 2
    elif semantic_overall < 50:
        score -= 18
    else:
        score -= 8
    for reason in semantic.get("reasons", [])[:3]:
        if reason not in reasons:
            reasons.append(str(reason))
    for suggestion in semantic.get("suggestions", [])[:3]:
        if suggestion not in suggestions:
            suggestions.append(str(suggestion))

    final_score = int(round(clamp_number(score, 0, 100)))
    if final_score >= 85:
        grade = "强"
    elif final_score >= 70:
        grade = "可用"
    elif final_score >= 55:
        grade = "偏弱"
    else:
        grade = "需重绘"
    return {
        "score": final_score,
        "grade": grade,
        "prompt_signal_score": round(prompt_score, 1),
        "semantic": semantic,
        "reasons": reasons[:4],
        "suggestions": list(dict.fromkeys(suggestions))[:4],
    }


def image_asset_metrics(path: Path, project_id: int) -> dict[str, Any]:
    record: dict[str, Any] = {
        "file": str(path.relative_to(storage.project_dir(project_id))),
        "exists": path.exists(),
        "ok": False,
        "issues": [],
    }
    if not path.exists():
        record["issues"].append("文件不存在")
        return record
    try:
        stat = path.stat()
        record["size"] = stat.st_size
        if Image is None or ImageStat is None:
            record["ok"] = stat.st_size > 0
            record["issues"].append("当前环境缺少 Pillow，无法做图像视觉指标")
            return record
        with Image.open(path) as image:
            rgb = image.convert("RGB")
            gray = rgb.convert("L")
            stat_luma = ImageStat.Stat(gray)
            mean_luma = round(float(stat_luma.mean[0]), 2)
            std_luma = round(float(stat_luma.stddev[0]), 2)
            extrema = gray.getextrema()
            width, height = rgb.size
            aspect = round(width / max(1, height), 4)
            edge_score = 0.0
            with contextlib.suppress(Exception):
                if ImageFilter is not None:
                    edges = gray.resize((240, max(1, round(240 * height / max(1, width))))).filter(ImageFilter.FIND_EDGES)
                    edge_score = round(float(ImageStat.Stat(edges).mean[0]), 2)
            record.update(
                {
                    "ok": True,
                    "width": width,
                    "height": height,
                    "aspect_ratio": aspect,
                    "mean_luma": mean_luma,
                    "contrast": std_luma,
                    "min_luma": int(extrema[0]),
                    "max_luma": int(extrema[1]),
                    "edge_score": edge_score,
                    "hash": image_average_hash(path),
                }
            )
            if mean_luma < 8:
                record["issues"].append("疑似黑图或极暗")
            elif mean_luma < 32:
                record["issues"].append("整体偏暗，短视频首帧吸引力可能不足")
            if std_luma < 18:
                record["issues"].append("画面对比度偏低，可能显得太素")
            if edge_score and edge_score < 4:
                record["issues"].append("边缘/细节偏少，主体可能不够抓眼")
    except Exception as exc:
        record["issues"].append(str(exc))
    return record


def visual_image_quality_report(project_id: int, content: str = "", mode: str = "video") -> dict[str, Any]:
    scene_paths = find_scene_image_paths(project_id)
    cover_paths = [path for path in _cover_output_paths(project_id) if path.exists()]
    assets = [image_asset_metrics(path, project_id) for path in [*scene_paths, *cover_paths]]
    prompt_map = image_prompt_context_map(project_id, content, mode)
    semantic_map = image_semantic_context_map(project_id, content, mode)
    issues: list[dict[str, Any]] = []
    for item in assets:
        file = str(item.get("file") or "").replace("\\", "/")
        prompt = prompt_map.get(file, "")
        semantic_context = semantic_map.get(file, {})
        appeal = image_appeal_score(
            item,
            prompt,
            is_cover=file.startswith("covers/"),
            semantic_context=semantic_context,
        )
        item["appeal"] = appeal
        semantic = appeal.get("semantic") if isinstance(appeal.get("semantic"), dict) else {}
        semantic_overall = int(semantic.get("overall", 0) or 0)
        foreign_callouts = semantic.get("foreign_callouts", []) if isinstance(semantic.get("foreign_callouts"), list) else []
        if foreign_callouts:
            issues.append(
                quality_issue(
                    "risk",
                    file,
                    f"图片提示词混入跨题材短词：{', '.join(str(item) for item in foreign_callouts[:4])}。",
                    "清除旧项目/错误领域短词，并按当前完整口播重新生成这张图。",
                )
            )
        elif semantic_overall and semantic_overall < 65:
            semantic_reasons = "; ".join(str(text) for text in semantic.get("reasons", [])[:2])
            semantic_fix = "；".join(str(text) for text in semantic.get("suggestions", [])[:2]) or "按本段口播重写提示词后单张重绘。"
            issues.append(
                quality_issue(
                    "warn",
                    file,
                    f"图片与主题/口播贴合偏弱：{semantic_overall} 分，{semantic_reasons}",
                    semantic_fix,
                )
            )
        meta_hits = semantic.get("meta_hits", []) if isinstance(semantic.get("meta_hits"), list) else []
        if meta_hits:
            issues.append(
                quality_issue(
                    "warn",
                    file,
                    f"图片提示词含生产元信息：{', '.join(str(term) for term in meta_hits[:4])}。",
                    "重绘前先刷新提示词，清除画幅比例、编号和生产说明。",
                )
            )
        if int(appeal.get("score", 0) or 0) < 60:
            fix = "；".join(str(text) for text in appeal.get("suggestions", [])[:2]) or "单张重绘，强化主体、动作和冲突。"
            issues.append(
                quality_issue(
                    "warn",
                    file,
                    f"图片吸引力偏弱：{appeal.get('score')} 分，{'; '.join(str(x) for x in appeal.get('reasons', [])[:2])}",
                    fix,
                )
            )
    for item in assets:
        file = str(item.get("file") or "")
        for issue in item.get("issues", [])[:3]:
            level = "risk" if "黑图" in str(issue) or "不存在" in str(issue) else "warn"
            issues.append(quality_issue(level, file, str(issue), "单张重绘或换一版更强主体的提示词。"))

    duplicate_pairs: list[dict[str, Any]] = []
    scene_assets = [item for item in assets if str(item.get("file", "")).startswith("scenes/") and item.get("hash")]
    for left_index, left in enumerate(scene_assets):
        for right in scene_assets[left_index + 1 :]:
            similarity = hash_similarity(str(left.get("hash", "")), str(right.get("hash", "")))
            if similarity >= 0.91:
                duplicate_pairs.append({"left": left.get("file"), "right": right.get("file"), "similarity": similarity})
    if duplicate_pairs:
        issues.append(
            quality_issue(
                "warn",
                "场景图重复",
                f"检测到 {len(duplicate_pairs)} 组视觉相似度较高的场景图。",
                "建议重绘相邻重复图，让每段口播对应不同动作、物件或镜头距离。",
            )
        )

    scene_lumas = [float(item.get("mean_luma", 0) or 0) for item in scene_assets if item.get("ok")]
    appeal_scores = [int(item.get("appeal", {}).get("score", 0) or 0) for item in assets if item.get("ok")]
    semantic_scores = [
        int(item.get("appeal", {}).get("semantic", {}).get("overall", 0) or 0)
        for item in assets
        if item.get("ok") and isinstance(item.get("appeal", {}).get("semantic"), dict)
    ]
    low_semantic_assets = [
        {
            "file": item.get("file"),
            "semantic_score": item.get("appeal", {}).get("semantic", {}).get("overall"),
            "topic": item.get("appeal", {}).get("semantic", {}).get("topic"),
            "speech": item.get("appeal", {}).get("semantic", {}).get("speech"),
            "visual_director": item.get("appeal", {}).get("semantic", {}).get("visual_director"),
            "reasons": item.get("appeal", {}).get("semantic", {}).get("reasons", []),
            "suggestions": item.get("appeal", {}).get("semantic", {}).get("suggestions", []),
        }
        for item in assets
        if int(item.get("appeal", {}).get("semantic", {}).get("overall", 0) or 0) < 65
    ]
    low_appeal_assets = [
        {
            "file": item.get("file"),
            "score": item.get("appeal", {}).get("score"),
            "grade": item.get("appeal", {}).get("grade"),
            "reasons": item.get("appeal", {}).get("reasons", []),
            "suggestions": item.get("appeal", {}).get("suggestions", []),
        }
        for item in assets
        if int(item.get("appeal", {}).get("score", 0) or 0) < 60
    ]
    if scene_lumas and max(scene_lumas) - min(scene_lumas) < 18:
        issues.append(quality_issue("info", "画面节奏", "场景图明暗变化较小，整条视频可能显得节奏单一。", "可让部分段落使用更强光影、近景或动作冲突。"))
    if appeal_scores and sum(appeal_scores) / len(appeal_scores) < 68:
        issues.append(quality_issue("warn", "图片吸引力", "本组图片平均吸引力偏弱，视频可能看起来平。", "优先重绘低分图片，把每张图改成强主体、明确动作、具体冲突。"))
    if semantic_scores and sum(semantic_scores) / len(semantic_scores) < 70:
        issues.append(quality_issue("warn", "图片语义贴合", "本组图片与主题/口播的平均贴合偏弱。", "按“频道气质 -> 本期主题 -> 对应口播句”重建图片提示词，再批量重绘。"))

    score = quality_score_from_issues(issues)
    return {
        "score": score,
        "verdict": quality_verdict(score),
        "assets": [
            {key: value for key, value in item.items() if key != "hash"}
            for item in assets
        ],
        "duplicate_pairs": duplicate_pairs[:20],
        "metrics": {
            "asset_count": len(assets),
            "scene_count": len(scene_paths),
            "cover_count": len(cover_paths),
            "duplicate_pair_count": len(duplicate_pairs),
            "avg_scene_luma": round(sum(scene_lumas) / len(scene_lumas), 2) if scene_lumas else 0,
            "avg_appeal_score": round(sum(appeal_scores) / len(appeal_scores), 1) if appeal_scores else 0,
            "low_appeal_count": len(low_appeal_assets),
            "avg_semantic_score": round(sum(semantic_scores) / len(semantic_scores), 1) if semantic_scores else 0,
            "low_semantic_count": len(low_semantic_assets),
        },
        "low_appeal_assets": low_appeal_assets[:12],
        "low_semantic_assets": low_semantic_assets[:12],
        "issues": issues,
    }


def content_quality_report(
    project: dict[str, Any],
    template: dict[str, Any],
    brief: str,
    content: str,
    references: list[dict[str, Any]],
    *,
    source_content: str | None = None,
) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    audit = content_audit_report(
        project,
        template,
        brief,
        content,
        references,
        source_content=source_content,
    )
    engagement = content_engagement_report(content, mode)
    issues: list[dict[str, Any]] = [dict(item) for item in audit.get("issues", []) if isinstance(item, dict)]
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else summarize_content(content, mode)
    dialogue_lines = parse_dialogue_lines(content, mode)
    opening = clean_text(dialogue_lines[0] if dialogue_lines else content[:120])
    opening_novelty: dict[str, Any] = {}
    project_id = int(project.get("id", 0) or 0)
    if project_id:
        with contextlib.suppress(Exception):
            opening_novelty = opening_novelty_report(project_id, content)

    if engagement.get("opening_score", 0) < CONTENT_OPENING_MIN_SCORE:
        issues.append(quality_issue("warn", "开头吸引力", "前三秒钩子偏弱，观众可能不知道为什么要继续看。", "第一句改成具体痛点、反常识问题或结果先行。"))
    if engagement.get("retention_score", 0) < CONTENT_RETENTION_MIN_SCORE:
        issues.append(quality_issue("warn", "中段留存", "中段推进偏平，缺少持续的信息差或转折。", "每 20-40 秒安排一个新问题、反转或具体案例。"))
    if engagement.get("interaction_score", 0) < CONTENT_INTERACTION_MIN_SCORE:
        issues.append(quality_issue("warn", "结尾互动", "结尾互动钩子不够明确或动作太多。", "只保留一个低门槛评论动作，例如“装了扣1，没装扣2”。"))
    if opening and any(opening.startswith(token) for token in WEAK_OPENING_TOKENS):
        issues.append(quality_issue("warn", "开头句式", "开头仍有常见口播套话。", "删掉寒暄，直接从冲突、场景或问题开始。"))
    if opening_novelty.get("repetitive"):
        closest = (opening_novelty.get("closest_matches") or [{}])[0]
        match_text = f"，与项目 #{closest.get('project_id')} 的开场相似度 {float(closest.get('similarity', 0) or 0):.0%}" if closest.get("project_id") else ""
        issues.append(
            quality_issue(
                "warn",
                "频道开场重复",
                f"第一句仍在复用近期的“{opening_novelty.get('surface') or opening_novelty.get('family_label') or '相同结构'}”{match_text}。",
                "保留事实，只把切入口改为本期独有的动作、证据、后果或对象；不要只替换主题名。",
            )
        )
    bad_phrase_hits = script_bad_phrase_hits("\n".join(dialogue_lines) or content)
    if bad_phrase_hits:
        issues.append(
            quality_issue(
                "risk",
                "口播套话/播客腔",
                f"存在弱开头或播客式收尾：{', '.join(bad_phrase_hits[:6])}。",
                "先做节奏增强或总编优化，删除“今天我们来聊聊”“本期播客”“感谢收听”等表达。",
            )
        )

    score = min(int(audit.get("score", 100) or 100), quality_score_from_issues(issues))
    return {
        "score": score,
        "verdict": quality_verdict(score),
        "rewrite_recommended": score < CONTENT_GATE_MIN_SCORE or bool(engagement.get("needs_rewrite")) or any(str(item.get("level")) == "risk" for item in issues),
        "summary": summary,
        "engagement": {
            "overall_score": engagement.get("overall_score"),
            "opening_score": engagement.get("opening_score"),
            "retention_score": engagement.get("retention_score"),
            "interaction_score": engagement.get("interaction_score"),
            "opening_novelty_score": opening_novelty.get("score", 100),
            "opening_family": opening_novelty.get("family", ""),
        },
        "opening_novelty": opening_novelty,
        "metrics": audit.get("metrics", {}),
        "issues": issues,
    }


NEGATIVE_STYLE_CLAUSE_TOKENS = ("不要", "避免", "禁用", "禁止", "不使用", "不做", "不能", "别", "无")


def prompt_has_positive_style_token(prompt: str, token: str) -> bool:
    text = clean_text(prompt)
    if not text or token not in text:
        return False
    clauses = re.split(r"[，,。；;：:\n]", text)
    for clause in clauses:
        clause = clean_text(clause)
        if token not in clause:
            continue
        if any(negative in clause for negative in NEGATIVE_STYLE_CLAUSE_TOKENS):
            continue
        return True
    return False


def image_director_report(project_id: int, project: dict[str, Any], template: dict[str, Any], content: str) -> dict[str, Any]:
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    scene_status_payload = storage.scene_status(project_id)
    prompt_cache_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    content_path = storage.project_file(project_id, "content.md")
    prompt_cache_fresh = prompt_cache_path.exists() and (
        not content_path.exists() or prompt_cache_path.stat().st_mtime >= content_path.stat().st_mtime
    )
    scene_records = storage.read_json(prompt_cache_path, []) if prompt_cache_fresh else []
    if not isinstance(scene_records, list):
        scene_records = []
    scene_prompts = [
        clean_text(str(record.get("prompt") or record.get("source_prompt") or ""))
        for record in scene_records
        if isinstance(record, dict)
    ]
    if not scene_prompts:
        scene_prompts = visual_prompt_manifest_scene_prompts(project_id, content) or parse_scene_prompts(content, mode)
    if len(scene_prompts) < 2:
        derived_prompts = current_scene_prompts(
            project_id,
            content,
            mode,
            str(project.get("topic_name") or ""),
            prefer_timeline=False,
        )
        if len(derived_prompts) > len(scene_prompts):
            scene_prompts = derived_prompts
    scene_paths = find_scene_image_paths(project_id)
    cover_enabled = project_cover_enabled(project_id)
    cover_paths = _cover_output_paths(project_id)
    cover_generated = sum(1 for path in cover_paths if path.exists())
    expected = int(scene_status_payload.get("expected_count", 0) or len(scene_prompts) or 0)
    generated = int(scene_status_payload.get("generated_count", 0) or len(scene_paths))
    issues: list[dict[str, Any]] = []

    if expected <= 0:
        issues.append(quality_issue("warn", "图片计划", "没有识别到场景图计划。", "先生成或修正 content.md 里的图片提示词。"))
    elif generated < expected:
        issues.append(quality_issue("risk", "场景图数量", f"场景图缺失：已生成 {generated}/{expected}。", "补齐缺失场景图后再合成视频。"))
    if cover_enabled and cover_generated < len(cover_paths):
        issues.append(quality_issue("warn", "封面图", f"封面未完整生成：已生成 {cover_generated}/{len(cover_paths)}。", "补齐横屏、图文、竖屏封面，方便不同平台发布。"))

    similarity = prompt_similarity_score(scene_prompts)
    repeated_style_tokens = ["纸质拼贴", "档案拼贴", "手账风", "复古拼贴", "卡片拼贴", "便签拼贴"]
    repeated_style_hits = {
        token: sum(1 for prompt in scene_prompts if prompt_has_positive_style_token(prompt, token))
        for token in repeated_style_tokens
    }
    repeated_style = [
        token for token, count in repeated_style_hits.items()
        if scene_prompts and count / max(1, len(scene_prompts)) >= 0.72 and count >= 3
    ]
    if similarity >= 0.78:
        issues.append(quality_issue("warn", "场景差异度", "多张场景图提示词过于相似，画面容易显得重复。", "让每张图绑定不同口播句、人物动作和场景关系。"))
    if repeated_style:
        issues.append(quality_issue("warn", "固定画风", f"提示词高频重复同一类画风：{', '.join(repeated_style[:4])}。", "把画风从频道统一感改为主题驱动，避免每期都像同一套纸面。"))

    anchor_bound = sum(1 for prompt in scene_prompts if any(token in prompt for token in ("口播", "画面重点", "这张图必须对应", "阶段")))
    if scene_prompts and anchor_bound / max(1, len(scene_prompts)) < 0.75:
        issues.append(quality_issue("warn", "口播绑定", "部分场景图没有明确绑定对应口播。", "按“频道 -> 主题 -> 当前口播句”重写每张图提示词。"))

    brand = clean_text(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or "")
    cover_prompt_text = "\n".join(storage.read_text(path.with_suffix(".md")) for path in cover_paths if path.with_suffix(".md").exists())
    if brand and cover_prompt_text and brand not in cover_prompt_text:
        issues.append(quality_issue("info", "个人 IP", "封面提示词没有明显带频道名/作者名。", "封面固定加入频道名、作者名或专属角标，增强个人 IP 识别。"))

    audit_records: list[dict[str, Any]] = []
    for path in [*scene_paths, *[item for item in cover_paths if cover_enabled and item.exists()]]:
        audit = read_image_audit(path)
        if audit:
            audit_records.append({"file": str(path.relative_to(storage.project_dir(project_id))), **audit})
            severity = str(audit.get("severity") or "")
            if severity == "hard":
                issues.append(quality_issue("risk", path.name, f"图片自检硬失败：{', '.join(str(x) for x in audit.get('reasons', []))}", "重绘这张图片。"))
            elif severity == "soft":
                issues.append(quality_issue("info", path.name, f"图片自检提示：{', '.join(str(x) for x in audit.get('reasons', []))}", "必要时重绘或换提示词。"))

    visual_report = visual_image_quality_report(project_id, content, mode)
    for issue in visual_report.get("issues", []):
        if isinstance(issue, dict):
            issues.append(dict(issue))
    layer_report = image_prompt_layer_report(project_id, content)
    for issue in layer_report.get("issues", []):
        if isinstance(issue, dict):
            issues.append(dict(issue))

    issues, ignored_issues, image_override = split_ignored_image_quality_issues(project_id, issues)
    score = quality_score_from_issues(issues)
    return {
        "score": score,
        "verdict": quality_verdict(score),
        "metrics": {
            "scene_expected": expected,
            "scene_generated": generated,
            "cover_enabled": cover_enabled,
            "cover_expected": len(cover_paths) if cover_enabled else 0,
            "cover_generated": cover_generated,
            "scene_prompt_count": len(scene_prompts),
            "prompt_similarity_max": similarity,
            "anchor_bound_count": anchor_bound,
            "prompt_cache_fresh": prompt_cache_fresh,
            "visual_score": visual_report.get("score"),
            "visual_asset_count": visual_report.get("metrics", {}).get("asset_count"),
            "visual_duplicate_pair_count": visual_report.get("metrics", {}).get("duplicate_pair_count"),
            "avg_image_appeal_score": visual_report.get("metrics", {}).get("avg_appeal_score"),
            "low_image_appeal_count": visual_report.get("metrics", {}).get("low_appeal_count"),
            "avg_image_semantic_score": visual_report.get("metrics", {}).get("avg_semantic_score"),
            "low_image_semantic_count": visual_report.get("metrics", {}).get("low_semantic_count"),
            "image_prompt_layer_score": layer_report.get("metrics", {}).get("avg_layer_score"),
            "weak_image_prompt_count": layer_report.get("metrics", {}).get("weak_prompt_count"),
            "image_quality_override_active": bool(image_override.get("active")),
            "ignored_image_soft_issue_count": len(ignored_issues),
        },
        "issues": issues,
        "ignored_issues": ignored_issues[:20],
        "image_quality_override": image_override,
        "image_audits": audit_records[:20],
        "visual": visual_report,
        "prompt_layers": layer_report,
    }


def visual_director_quality_report(project_id: int, content: str = "") -> dict[str, Any]:
    director_path = visual_director_path(project_id)
    director = storage.read_json(director_path, {})
    issues: list[dict[str, Any]] = []
    if not isinstance(director, dict) or not director:
        issues.append(quality_issue("risk", "视觉导演", "还没有生成 visual_director.json。", "点击“视觉导演”或重新生成字幕/场景计划。"))
        return {
            "score": quality_score_from_issues(issues),
            "verdict": quality_verdict(quality_score_from_issues(issues)),
            "path": str(director_path),
            "issues": issues,
            "metrics": {},
        }
    if clean_text(str(director.get("source_hash") or "")) != visual_brief_source_hash(content or storage.get_content(project_id)):
        issues.append(quality_issue("warn", "视觉导演", "visual_director.json 不是基于当前 content.md 生成。", "刷新视觉导演，避免图片、节奏和音乐仍对应旧稿。"))
    image_direction = director.get("image_direction") if isinstance(director.get("image_direction"), dict) else {}
    edit_direction = director.get("edit_direction") if isinstance(director.get("edit_direction"), dict) else {}
    sound_direction = director.get("sound_direction") if isinstance(director.get("sound_direction"), dict) else {}
    edit_scenes = edit_direction.get("scenes") if isinstance(edit_direction.get("scenes"), list) else []
    scene_plan = storage.read_json(storage.project_file(project_id, "audio/scene_plan.json"), {})
    plan_scenes = scene_plan.get("scenes") if isinstance(scene_plan, dict) else []
    plan_count = len(plan_scenes) if isinstance(plan_scenes, list) else 0
    if not image_direction.get("visual_world"):
        issues.append(quality_issue("warn", "画面导演", "缺少本期视觉世界。", "刷新视觉导演，让画面世界来自频道、主题和口播。"))
    if not edit_scenes:
        issues.append(quality_issue("warn", "剪辑导演", "缺少逐镜节奏计划。", "刷新视觉导演，生成每镜 pace、motion、transition。"))
    elif plan_count and len(edit_scenes) != plan_count:
        issues.append(quality_issue("warn", "剪辑导演", f"导演镜头 {len(edit_scenes)} 个，scene_plan {plan_count} 个。", "重新写出 scene_plan，让导演节奏和字幕时间轴一致。"))
    if not sound_direction.get("bgm_mood"):
        issues.append(quality_issue("info", "声音导演", "缺少 BGM 情绪建议。", "刷新视觉导演，生成 bgm_mood、音量和能量曲线。"))
    transitions = [clean_text(str(item.get("transition") or "")) for item in edit_scenes if isinstance(item, dict)]
    fancy_count = sum(1 for item in transitions if item and item not in {"hard_cut", "hard_cut_from_cover", "soft_fade_to_end"})
    if fancy_count > max(1, len(transitions) // 3):
        issues.append(quality_issue("info", "转场", "转场建议偏多，可能抢口播。", "短视频口播优先硬切或轻淡出，少用花哨转场。"))
    score = quality_score_from_issues(issues)
    return {
        "score": score,
        "verdict": quality_verdict(score),
        "path": str(director_path),
        "metrics": {
            "scene_count": len(edit_scenes),
            "scene_plan_count": plan_count,
            "overall_pace": edit_direction.get("overall_pace"),
            "transition_policy": edit_direction.get("transition_policy"),
            "bgm_mood": sound_direction.get("bgm_mood"),
            "bgm_label": sound_direction.get("bgm_label"),
            "bgm_volume": sound_direction.get("bgm_volume"),
        },
        "director": {
            "image_direction": image_direction,
            "edit_direction": {
                key: value for key, value in edit_direction.items() if key != "scenes"
            },
            "sound_direction": sound_direction,
        },
        "issues": issues,
    }


AI_SUPERVISOR_ROLES = (
    ("topic_teacher", "爆款选题老师", "判断选题钩子、反差、受众痛点和传播价值"),
    ("script_teacher", "脚本结构老师", "判断开头钩子、中段留存、转折密度和结尾互动"),
    ("visual_teacher", "视觉导演老师", "判断图片提示词是否跟频道、主题、口播逐镜对齐"),
    ("edit_teacher", "剪辑节奏老师", "判断场景张数、时轴、节奏、字幕和 BGM 是否服务口播"),
    ("ops_teacher", "平台运营老师", "判断标题、封面卖点、标签和评论区引导"),
    ("fact_teacher", "事实合规老师", "判断资料来源、事实风险、夸张表述和安全边界"),
)


def _supervisor_grade(score: int) -> str:
    if score >= 85:
        return "优秀，可进入生产"
    if score >= 72:
        return "可用，建议小修"
    if score >= 60:
        return "有风险，建议返工"
    return "阻止，先重做"


def _supervisor_record(key: str, name: str, score: int, findings: list[str], suggestions: list[str]) -> dict[str, Any]:
    score = int(clamp_number(score, 0, 100))
    return {
        "key": key,
        "name": name,
        "score": score,
        "grade": _supervisor_grade(score),
        "blocking": score < 60,
        "findings": dedupe_clauses([item for item in findings if clean_text(item)])[:5],
        "suggestions": dedupe_clauses([item for item in suggestions if clean_text(item)])[:5],
    }


def local_ai_supervisor_report(project_id: int, content: str) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template = storage.get_template(clean_text(project.get("template") or ""))
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    brief = storage.get_brief(project_id)
    summary = summarize_content(content, mode)
    engagement = content_engagement_report(content, mode)
    image_layers = image_prompt_layer_report(project_id, content)
    director = visual_director_quality_report(project_id, content)
    video = video_quality_report(project_id)
    references = storage.get_references(project_id)
    topic_title = clean_text(str(project.get("topic_name") or summary.get("video_title") or first_heading(content) or ""))
    scene_status = storage.scene_status(project_id)

    teachers: list[dict[str, Any]] = []
    hook = clean_text(str(summary.get("hook") or ""))
    topic_score = 66
    topic_findings: list[str] = []
    topic_suggestions: list[str] = []
    if any(token in topic_title + hook + brief for token in ("为什么", "竟然", "真相", "别", "千万", "反而", "不是", "套路")):
        topic_score += 14
        topic_findings.append("选题具备反差或问题钩子。")
    else:
        topic_score -= 10
        topic_suggestions.append("标题和前三句需要更强的反常识、结果或损失感。")
    if len(topic_title) <= 28:
        topic_score += 6
    else:
        topic_suggestions.append("标题偏长，发布标题建议压缩到 16-26 字。")
    teachers.append(_supervisor_record("topic_teacher", "爆款选题老师", topic_score, topic_findings, topic_suggestions))

    raw_script_score = float(engagement.get("overall_score", 3.25) or 3.25)
    script_score = int(round(raw_script_score * 20)) if raw_script_score <= 5 else int(round(raw_script_score))
    script_score = int(clamp_number(script_score, 0, 100))
    script_findings = [f"开头 {engagement.get('opening_score', 0)}，留存 {engagement.get('retention_score', 0)}，互动 {engagement.get('interaction_score', 0)}。"]
    script_suggestions = [str(item) for item in engagement.get("suggestions", []) if clean_text(str(item))]
    if script_score < 75:
        script_suggestions.append("前三句先给结果/损失/反差，中段每 20-35 秒补一个追问或反转。")
    teachers.append(_supervisor_record("script_teacher", "脚本结构老师", script_score, script_findings, script_suggestions))

    layer_metrics = image_layers.get("metrics", {}) if isinstance(image_layers, dict) else {}
    visual_score = int(layer_metrics.get("avg_layer_score", 65) or 65)
    visual_findings = [f"图片提示词平均分层 {visual_score}，弱提示词 {layer_metrics.get('weak_prompt_count', 0)} 条。"]
    visual_suggestions = []
    if visual_score < 78:
        visual_suggestions.append("每张图先绑定本镜口播，再写主体、动作、冲突、短字，删掉画幅比例和生产说明。")
    director_score = int(director.get("score", 70) or 70)
    visual_score = int(round((visual_score + director_score) / 2))
    teachers.append(_supervisor_record("visual_teacher", "视觉导演老师", visual_score, visual_findings, visual_suggestions))

    video_metrics = video.get("metrics", {}) if isinstance(video, dict) else {}
    edit_score = int(video.get("score", 70) or 70)
    edit_findings = [
        f"场景计划 {scene_status.get('expected_count', 0)}，已生成 {scene_status.get('generated_count', 0)}，字幕覆盖 {round(float(video_metrics.get('subtitle_coverage', 0) or 0) * 100)}%。"
    ]
    edit_suggestions = []
    if scene_status.get("expected_source") == "audio_timeline":
        edit_suggestions.append("当前按真实音频时轴锁定张数，后续补图和合成应跟随该计划。")
    if edit_score < 75:
        edit_suggestions.append("先修字幕覆盖、时轴段数或缺失场景图，再合成成片。")
    teachers.append(_supervisor_record("edit_teacher", "剪辑节奏老师", edit_score, edit_findings, edit_suggestions))

    ops_score = 68
    ops_findings = []
    ops_suggestions = []
    if summary.get("publish_title"):
        ops_score += 8
        ops_findings.append("已有发布标题。")
    else:
        ops_suggestions.append("补 3-6 个发布标题变体，封面标题控制在 5-10 字。")
    if template.get("release_tags"):
        ops_score += 6
    else:
        ops_suggestions.append("频道模板建议配置固定标签和互动句。")
    if summary.get("interaction"):
        ops_score += 8
    else:
        ops_suggestions.append("结尾需要明确评论问题或收藏理由。")
    teachers.append(_supervisor_record("ops_teacher", "平台运营老师", ops_score, ops_findings, ops_suggestions))

    fact_score = 70
    fact_findings = []
    fact_suggestions = []
    if len(references) >= 3:
        fact_score += 12
        fact_findings.append(f"已有 {len(references)} 条参考资料。")
    else:
        fact_score -= 12
        fact_suggestions.append("资料不足时应停止强结论，补官方/百科/新闻/论文来源后再生成。")
    if any(token in content for token in ("绝对", "百分百", "一定", "全网", "唯一")):
        fact_score -= 8
        fact_suggestions.append("删掉绝对化表达，避免事实和平台合规风险。")
    teachers.append(_supervisor_record("fact_teacher", "事实合规老师", fact_score, fact_findings, fact_suggestions))

    overall = int(round(sum(int(item.get("score", 0) or 0) for item in teachers) / max(1, len(teachers))))
    return {
        "provider": "local-supervisor-rules",
        "ai_model": "",
        "score": overall,
        "overall_score": overall,
        "verdict": _supervisor_grade(overall),
        "teachers": teachers,
        "next_actions": dedupe_clauses(
            suggestion
            for teacher in teachers
            for suggestion in teacher.get("suggestions", [])
        )[:8],
        "context": {
            "topic": topic_title,
            "template": project.get("template"),
            "scene_count": scene_status.get("expected_count", 0),
            "scene_count_source": scene_status.get("expected_source", ""),
        },
    }


def compose_ai_supervisor_messages(project: dict[str, Any], template: dict[str, Any], content: str, local_report: dict[str, Any]) -> list[dict[str, str]]:
    visual_content = content_without_image_prompts(content)
    schema = {
        "overall_score": 0,
        "verdict": "一句总评",
        "teachers": [
            {
                "key": "topic_teacher/script_teacher/visual_teacher/edit_teacher/ops_teacher/fact_teacher",
                "name": "老师名",
                "score": 0,
                "grade": "优秀/可用/风险/阻止",
                "blocking": False,
                "findings": ["具体问题或优点"],
                "suggestions": ["可执行修改建议"],
            }
        ],
        "next_actions": ["按优先级排列的下一步"],
    }
    system = """
你是短视频内容工厂的 AI 第三视角评审团，由多个专业老师组成。
你不是重写文案的人，而是监督者：必须指出哪里会影响播放、点击、完播、事实安全和生产稳定性。
老师角色固定为：爆款选题老师、脚本结构老师、视觉导演老师、剪辑节奏老师、平台运营老师、事实合规老师。
每个老师都要给 0-100 分、明确是否阻止进入下一步，并给短而具体的修改建议。
只返回 JSON，不要 markdown，不要解释。
""".strip()
    user = {
        "project": {
            "id": project.get("id"),
            "topic": project.get("topic_name"),
            "template": project.get("template"),
        },
        "channel": {
            "name": template.get("brand_name") or template.get("name") or template.get("key"),
            "audience": template.get("target_audience"),
            "voice": template.get("channel_voice"),
            "visual_strategy": template.get("visual_strategy"),
            "forbidden_rules": template.get("forbidden_rules"),
            "image_style_prompt": template.get("image_style_prompt"),
            "image_negative_prompt": template.get("image_negative_prompt"),
        },
        "content_md_without_image_prompt": visual_content[:9000],
        "local_rule_report_for_reference": local_report,
        "required_roles": [
            {"key": key, "name": name, "job": job}
            for key, name, job in AI_SUPERVISOR_ROLES
        ],
        "output_schema": schema,
    }
    return [
        {"role": "system", "content": system},
        {"role": "user", "content": json.dumps(user, ensure_ascii=False, indent=2)},
    ]


def normalize_ai_supervisor_payload(payload: dict[str, Any], fallback: dict[str, Any], model: str) -> dict[str, Any]:
    fallback_by_key = {
        str(item.get("key") or ""): item
        for item in fallback.get("teachers", [])
        if isinstance(item, dict)
    }
    raw_teachers = payload.get("teachers") if isinstance(payload.get("teachers"), list) else []
    normalized: list[dict[str, Any]] = []
    for key, name, _job in AI_SUPERVISOR_ROLES:
        raw = next((item for item in raw_teachers if isinstance(item, dict) and item.get("key") == key), {})
        fallback_item = fallback_by_key.get(key, {})
        score = int(clamp_number(float(raw.get("score", fallback_item.get("score", 65)) or 65), 0, 100))
        normalized.append(
            {
                "key": key,
                "name": clean_text(str(raw.get("name") or name)),
                "score": score,
                "grade": clean_text(str(raw.get("grade") or _supervisor_grade(score))),
                "blocking": bool(raw.get("blocking", score < 60)),
                "findings": _text_list(raw.get("findings"), fallback_item.get("findings", []), limit=5, item_limit=90),
                "suggestions": _text_list(raw.get("suggestions"), fallback_item.get("suggestions", []), limit=5, item_limit=90),
            }
        )
    overall = int(clamp_number(float(payload.get("overall_score", 0) or 0), 0, 100))
    if overall <= 0:
        overall = int(round(sum(item["score"] for item in normalized) / max(1, len(normalized))))
    return {
        **fallback,
        "provider": "deepseek-ai-supervisors",
        "ai_model": model,
        "score": overall,
        "overall_score": overall,
        "verdict": clean_text(str(payload.get("verdict") or _supervisor_grade(overall))),
        "teachers": normalized,
        "next_actions": _text_list(payload.get("next_actions"), fallback.get("next_actions", []), limit=8, item_limit=100),
    }


def ai_supervisor_report(project_id: int, content: str | None = None, *, prefer_ai: bool = True) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    content_text = content if content is not None else storage.get_content(project_id)
    fallback = local_ai_supervisor_report(project_id, content_text)
    if not prefer_ai:
        return fallback
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if not api_key:
        fallback["ai_error"] = "DEEPSEEK_API_KEY 未配置，当前使用本地规则老师团。"
        return fallback
    if OpenAI is None:
        fallback["ai_error"] = "当前环境缺少 openai 依赖，无法调用 AI 老师团。"
        return fallback
    base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
    model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
    thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
    reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
    client = OpenAI(api_key=api_key, base_url=base_url, timeout=90.0)
    extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
    if thinking_type in {"enabled", "disabled"}:
        extra_body["thinking"] = {"type": thinking_type}
    try:
        response = client.chat.completions.create(
            model=model,
            messages=compose_ai_supervisor_messages(project, template, content_text, fallback),
            temperature=0.25,
            max_tokens=4500,
            extra_body=extra_body,
        )
        choice = response.choices[0] if getattr(response, "choices", None) else None
        raw = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
        payload = _safe_json_from_text(raw)
        if not payload:
            raise ContentGenerationError("AI 老师团没有返回可解析 JSON。")
        return normalize_ai_supervisor_payload(payload, fallback, model)
    except Exception as exc:
        fallback["provider"] = "deepseek-ai-supervisors-failed"
        fallback["ai_model"] = model
        fallback["ai_error"] = str(exc)
        return fallback


def image_prompt_layer_entry(prompt: str, *, kind: str, topic: str, brand: str) -> dict[str, Any]:
    text = normalize_image_prompt(prompt)
    meta_hits = [term for term in IMAGE_PROMPT_META_POLLUTION_TERMS if term in text]
    generic_hits = image_prompt_generic_hits(text)
    density = scene_visual_density_report(text) if kind == "scene" else {"layer_count": 5, "issues": [], "layers": {}, "score": 100}
    topic_tokens = [
        part
        for part in re.findall(r"[\u4e00-\u9fffA-Za-z0-9%]{2,}", clean_text(topic))[:8]
        if part not in IMAGE_ALIGNMENT_STOPWORDS
    ]
    if kind == "cover":
        script_anchor_ok = any(
            token in text
            for token in (
                "封面先画",
                "封面主画面",
                "封面具体画面",
                "封面钩子",
                "主标题",
                "副标题",
                "核心观点",
                "反常识",
                "主题钩子",
                "冲突悬念",
                "第一眼",
                "主题情境",
            )
        )
    else:
        script_anchor_ok = any(
            token in text
            for token in ("口播原文", "画面任务", "口播", "对应", "开头这句", "画面重点", "阶段", "情节锚点", "冲突悬念", "关键可见物", "可见物")
        )
    speech_anchor = scene_prompt_speech_anchor(text) if kind == "scene" else ""
    audience_plan = (
        audience_visual_plan(topic=topic, narration=speech_anchor or text)
        if kind == "scene"
        else {}
    )
    primary_metric = (
        audience_plan.get("primary_metric")
        if isinstance(audience_plan.get("primary_metric"), dict)
        else {}
    )
    metric_label = clean_text(str(primary_metric.get("label") or ""))
    audience_clarity_ok = (
        kind != "scene"
        or (
            any(marker in text for marker in ("观众1秒必须看懂", "静音验收", "证据画面"))
            and (not metric_label or metric_label in text)
        )
    )
    generic_substitute = bool(
        re.search(r"抱头|摊手|耸肩|皱眉|巨大红叉|大问号|悬浮芯片|纸张堆叠成山|文件堆成山", text)
    ) and not bool(re.search(r"真实记录|原生工作界面|检测结果|实物证据|取证|实测", text))
    layer_checks = {
        "channel": bool(brand and brand in text) or any(token in text for token in ("频道", "系列感", "角标", "视觉基调", "专属色块")),
        "topic": bool(topic and any(part and part in text for part in topic_tokens)),
        "script_anchor": script_anchor_ok,
        "subject_action": any(token in text for token in IMAGE_APPEAL_SUBJECT_TERMS) and any(token in text for token in IMAGE_APPEAL_ACTION_TERMS),
        "evidence_relation": any(
            token in text
            for token in ("证据", "记录", "检测", "结果", "对照", "因果", "前后", "来源", "原生工作界面", "实测")
        ),
        "audience_clarity": audience_clarity_ok and not generic_substitute,
        "text_rules": any(token in text for token in IMAGE_APPEAL_TEXT_TERMS) or any(token in text for token in ("中文", "可读", "标题", "字幕空间", "留白")),
        "visual_density": kind != "scene" or int(density.get("layer_count", 0) or 0) >= 4,
        "safety": any(token in text for token in ("画面干净", "纯视觉叙事", "信息量集中", "字幕留白", "字幕安全区", "空间留白", "背景克制"))
        or not any(token in text for token in ("水印", "二维码", "免责声明", "脚注", "乱码", "长段")),
        "meta_clean": not meta_hits and len(generic_hits) < 2,
    }
    weights = {
        "channel": 10 if kind == "cover" else 4,
        "topic": 12 if kind == "cover" else 10,
        "script_anchor": 14 if kind == "scene" else 10,
        "subject_action": 14,
        "evidence_relation": 18 if kind == "scene" else 10,
        "audience_clarity": 18 if kind == "scene" else 10,
        "text_rules": 8,
        "visual_density": 6 if kind == "scene" else 8,
        "safety": 4,
        "meta_clean": 4,
    }
    score = sum(weights[key] for key, ok in layer_checks.items() if ok)
    missing = [key for key, ok in layer_checks.items() if not ok]
    suggestions = []
    if "channel" in missing:
        suggestions.append("补频道气质/固定角标/个人 IP 识别，不要只写本期画面。")
    if "topic" in missing:
        suggestions.append("补本期主题关键词或核心观点，让画面不是通用素材图。")
    if "script_anchor" in missing:
        suggestions.append("补封面主题钩子、主标题或核心冲突。" if kind == "cover" else "补对应口播句或阶段，保证每张图绑定当前文案。")
    if "subject_action" in missing:
        suggestions.append("补一个明确主体和正在发生的动作。")
    if "evidence_relation" in missing:
        suggestions.append("补真实对象、动作、记录或检测结果，说明哪条证据支撑当前口播。")
    if "audience_clarity" in missing:
        suggestions.append("先写清观众1秒必须看懂的对象、事实和证据，并清除通用焦虑人物或无关象征物。")
    if "visual_density" in missing:
        suggestions.append("补前景动作、证据道具、背景环境、短字冲突和光影结构，避免画面太素。")
    if "text_rules" in missing:
        suggestions.append("说明文字只允许短标题/短标签，并保留字幕空间。")
    if "safety" in missing:
        suggestions.append("补画面干净、纯视觉叙事、字幕留白等正向约束，不把规则词喂给图片模型。")
    if "meta_clean" in missing:
        dirty = dedupe_clauses([*meta_hits[:4], *generic_hits[:4]])
        suggestions.append(f"删掉生产元信息或模板化泛词：{', '.join(dirty)}，这些词容易让模型跑偏。")
    return {
        "score": int(round(clamp_number(score, 0, 100))),
        "layers": layer_checks,
        "missing_layers": missing,
        "meta_hits": meta_hits[:8],
        "generic_hits": generic_hits[:8],
        "density": density,
        "suggestions": suggestions[:4],
    }


def image_prompt_layer_report(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    content_text = content if content is not None else storage.get_content(project_id)
    topic = clean_text(str(first_heading(content_text) or project.get("topic_name") or ""))
    brand = clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or template_key))
    scene_prompts = resolved_scene_prompt_plan(project, template, content_text)

    entries: list[dict[str, Any]] = []
    cover_prompts = [
        ("cover_landscape", "横屏封面", build_content_cover_prompt(project, template, content_text, "landscape")),
        ("cover_portrait", "竖屏封面", build_content_cover_prompt(project, template, content_text, "portrait")),
    ]
    if mode == "article":
        cover_prompts = [("cover_landscape", "横屏封面", build_content_cover_prompt(project, template, content_text, "landscape"))]
    for target, label, prompt in cover_prompts:
        layer = image_prompt_layer_entry(prompt, kind="cover", topic=topic, brand=brand)
        entries.append({"kind": "cover", "target": target, "label": label, "prompt": prompt, **layer})
    for index, prompt in enumerate(scene_prompts, start=1):
        layer = image_prompt_layer_entry(prompt, kind="scene", topic=topic, brand=brand)
        entries.append({"kind": "scene", "target": f"s_{index:02d}.png", "label": f"场景 {index}", "prompt": prompt, **layer})

    issues: list[dict[str, Any]] = []
    for item in entries:
        if int(item.get("score", 0) or 0) < 72:
            issues.append(
                quality_issue(
                    "warn",
                    str(item.get("label") or item.get("target") or ""),
                    f"图片提示词分层不足：{item.get('score')} 分，缺少 {', '.join(item.get('missing_layers', [])[:4])}。",
                    "；".join(str(text) for text in item.get("suggestions", [])[:2]) or "重建图片提示词。",
                )
            )
    repeated_style_tokens = ["纸质拼贴", "档案拼贴", "手账风", "复古拼贴", "卡片拼贴", "便签拼贴"]
    repeated = [
        token
        for token in repeated_style_tokens
        if scene_prompts and sum(1 for prompt in scene_prompts if prompt_has_positive_style_token(prompt, token)) / max(1, len(scene_prompts)) >= 0.72
    ]
    if repeated:
        issues.append(
            quality_issue(
                "warn",
                "画风同质化",
                f"场景图提示词过度重复同一类画风：{', '.join(repeated[:4])}。",
                "让频道只决定气质，主题和当前口播决定主体、动作、空间和冲突。",
            )
        )

    scores = [int(item.get("score", 0) or 0) for item in entries]
    avg_score = round(sum(scores) / len(scores), 1) if scores else 0
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": topic,
        "score": int(round(avg_score)),
        "verdict": quality_verdict(int(round(avg_score))),
        "metrics": {
            "prompt_count": len(entries),
            "scene_prompt_count": len(scene_prompts),
            "avg_layer_score": avg_score,
            "weak_prompt_count": sum(1 for score in scores if score < 72),
            "repeated_style_tokens": repeated,
        },
        "entries": entries,
        "issues": issues,
        "next_actions": [item.get("fix") or item.get("issue") for item in issues[:6]],
    }


def strengthen_generation_prompt(prompt: str, *, purpose: str, topic: str, brand: str) -> str:
    """Polish the exact prompt that will be sent to the image provider."""
    original_prompt = normalize_image_prompt(prompt)
    source_authored = is_content_authored_image_prompt(original_prompt)
    if source_authored or any(marker in original_prompt for marker in ("关键可见物", "情节锚点", "冲突悬念")):
        base = compact_visual_image_prompt(original_prompt, 620 if purpose == "cover" else 520)
        if source_authored:
            base = light_clean_content_image_prompt(original_prompt, purpose)
    else:
        base = sanitize_prompt_for_image_model(prompt, purpose) or original_prompt
    base = strip_generic_visual_filler(base, topic=topic, source=original_prompt, purpose=purpose)
    base = ensure_prompt_keeps_topic_anchor(base, topic=topic, source=original_prompt, purpose=purpose)
    visual = prompt_visual_score(base, purpose)
    layer = image_prompt_layer_entry(base, kind="cover" if purpose == "cover" else "scene", topic=topic, brand=brand)
    additions: list[str] = []
    if brand and not layer.get("layers", {}).get("channel"):
        additions.append("用小角标、专属色块或固定镜头气质体现个人IP识别，频道名只做很小识别")
    if topic and not layer.get("layers", {}).get("topic"):
        additions.append(f"围绕本期核心「{summarize_scene_text(topic, 28)}」组织画面，不做通用素材图")
    if not layer.get("layers", {}).get("script_anchor"):
        additions.append(
            "把封面标题和核心冲突压成一个第一眼能懂的主视觉，不做通用素材图"
            if purpose == "cover"
            else "把当前口播的结果压成一个正在发生的视觉瞬间，画面不是通用素材图"
        )
    if "缺少明确主体" in visual.get("issues", []):
        additions.append("一个明确主主体压住画面，人物、手部、手机、屏幕或关键物件第一眼可见")
    if "缺少正在发生的动作" in visual.get("issues", []):
        additions.append("画面中必须有正在发生的动作，例如打开、指向、靠近、停住、对视或递出")
    if "缺少冲突/反差/悬念" in visual.get("issues", []):
        additions.append("用痛点、误区、反差、风险或悬念制造第一眼吸引力")
    if not layer.get("layers", {}).get("safety"):
        additions.append(image_prompt_clean_guard(purpose))
    if additions:
        base = "。".join([base, *additions])
    base = compact_visual_image_prompt(base, 860 if source_authored and purpose == "cover" else 980 if source_authored else 560 if purpose == "cover" else 460)
    base = strip_generic_visual_filler(base, topic=topic, source=original_prompt, purpose=purpose)
    base = ensure_prompt_keeps_topic_anchor(base, topic=topic, source=original_prompt, purpose=purpose)
    base = strip_generic_visual_filler(base, topic=topic, source=original_prompt, purpose=purpose)
    return compact_visual_image_prompt(base, 900 if source_authored and purpose == "cover" else 1040 if source_authored else 620 if purpose == "cover" else 520)


IMAGE_PROMPT_TEACHERS = (
    ("channel_teacher", "频道气质老师"),
    ("topic_teacher", "主题贴合老师"),
    ("script_teacher", "口播对应老师"),
    ("appeal_teacher", "第一眼吸引力老师"),
    ("clean_teacher", "生图安全老师"),
)


def _image_prompt_teacher_record(
    key: str,
    name: str,
    passed: bool,
    findings: list[str],
    fixes: list[str],
    rewrite_hint: str,
) -> dict[str, Any]:
    return {
        "key": key,
        "name": name,
        "passed": bool(passed),
        "findings": dedupe_clauses([clean_text(item) for item in findings if clean_text(item)])[:4],
        "fixes": dedupe_clauses([clean_text(item) for item in fixes if clean_text(item)])[:4],
        "rewrite_hint": clean_text(rewrite_hint),
    }


def image_prompt_teacher_review(
    prompt: str,
    *,
    purpose: str,
    topic: str,
    brand: str,
    label: str,
    semantic_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    text = normalize_image_prompt(prompt)
    kind = "cover" if purpose == "cover" else "scene"
    visual = prompt_visual_score(text, purpose)
    layer = image_prompt_layer_entry(text, kind=kind, topic=topic, brand=brand)
    layers = layer.get("layers") if isinstance(layer.get("layers"), dict) else {}
    meta_hits = dedupe_clauses([*(visual.get("meta_hits") or []), *(layer.get("meta_hits") or [])])
    context = semantic_context or {"topic": topic, "speech": "", "visual_director": ""}
    semantic = image_semantic_score(text, context, is_cover=purpose == "cover")
    speech_anchor = clean_text(str(context.get("speech") or ""))
    has_labeled_speech = bool(
        re.search(
            r"(?:当前完整口播|(?:本镜)?口播原文|对应口播原文)\s*[：:]\s*[「“\"]?[^\n]{12,}",
            text,
        )
    )
    has_explicit_speech_anchor = bool(
        purpose == "cover"
        or not speech_anchor
        or (has_labeled_speech and token_overlap_score(text, speech_anchor, limit=40) >= 42)
    )
    teachers: list[dict[str, Any]] = []

    channel_ok = bool(layers.get("channel"))
    teachers.append(
        _image_prompt_teacher_record(
            "channel_teacher",
            "频道气质老师",
            channel_ok,
            [] if channel_ok else ["缺少频道统一气质或个人 IP 识别"],
            [] if channel_ok else ["用小角标、专属色块、固定镜头气质承接频道，不把频道名画成大字"],
            "" if channel_ok else "用小角标、专属色块或固定镜头气质体现频道个人IP，频道名只做小识别",
        )
    )

    topic_ok = bool(layers.get("topic"))
    teachers.append(
        _image_prompt_teacher_record(
            "topic_teacher",
            "主题贴合老师",
            topic_ok,
            [] if topic_ok else ["没有明确压住本期主题，容易变成通用素材图"],
            [] if topic_ok else [f"把画面主体、动作和冲突都锁到本期主题「{summarize_scene_text(topic, 32)}」"],
            "" if topic_ok else f"围绕本期核心「{summarize_scene_text(topic, 32)}」组织画面，主体和冲突都来自本题",
        )
    )

    semantic_ok = int(semantic.get("overall", 0) or 0) >= (54 if purpose == "cover" else 58)
    script_ok = bool(layers.get("script_anchor")) and semantic_ok and has_explicit_speech_anchor
    script_findings: list[str] = []
    script_fixes: list[str] = []
    if not has_explicit_speech_anchor:
        script_findings.append("只写了“当前口播”或主题方向，没有写入这一镜的具体口播原文")
        script_fixes.append("在提示词开头补：口播原文：「本镜实际字幕/口播」；再根据这句话提炼主体、动作、冲突和可见物")
    if not semantic_ok or not layers.get("script_anchor"):
        if purpose == "cover":
            script_findings.append("封面没有真正压住标题钩子、核心观点或第一眼冲突，容易变成通用素材图")
            script_fixes.append("补封面主标题、核心冲突、主主体和情绪方向；封面不需要绑定口播原文")
        else:
            script_findings.append("提示词没有真正对上当前口播/主题锚点，或只写了泛泛风格")
            script_fixes.append("补出这一张图服务的口播结果、情绪、动作和关键物件，优先保留 content.md 里的具体画面细节")
    script_teacher_name = "封面主题老师" if purpose == "cover" else "口播对应老师"
    script_rewrite_hint = (
        "围绕封面标题、核心观点和第一眼冲突组织画面，封面不绑定口播原文"
        if purpose == "cover"
        else (
            f"口播原文：「{compact_prompt_speech_anchor(speech_anchor, 180)}」。"
            "口播原文只用于决定画面，不要把整句文字画进图里。把这句口播的结果压成一个正在发生的视觉瞬间"
        )
    )
    teachers.append(
        _image_prompt_teacher_record(
            "script_teacher",
            script_teacher_name,
            script_ok,
            [] if script_ok else script_findings,
            [] if script_ok else script_fixes,
            "" if script_ok else script_rewrite_hint,
        )
    )

    appeal_findings: list[str] = []
    appeal_fixes: list[str] = []
    appeal_hints: list[str] = []
    if "缺少明确主体" in visual.get("issues", []):
        appeal_findings.append("第一眼没有明确主主体")
        appeal_fixes.append("补一个占画面中心的真实人物、关键物件、屏幕光或产品主体")
        appeal_hints.append("一个明确主主体占据第一视觉中心，人物表情、关键物件或屏幕光第一眼可见")
    if "缺少正在发生的动作" in visual.get("issues", []):
        appeal_findings.append("缺少正在发生的动作")
        appeal_fixes.append("让人物手部、屏幕、设备或空间关系处在动作峰值")
        appeal_hints.append("画面里有正在发生的动作，例如举起、点击、靠近、停住、对视或切换")
    if "缺少冲突/反差/悬念" in visual.get("issues", []):
        appeal_findings.append("缺少冲突、反差或悬念")
        appeal_fixes.append("用痛点、误区、风险、反差或情绪峰值制造停留理由")
        appeal_hints.append("用反差、风险、误区或悬念制造第一眼吸引力")
    density_issues = [item for item in visual.get("issues", []) if item in {"缺少前景动作层", "缺少证据道具层", "缺少背景环境线索", "缺少可读冲突信息层", "缺少光影/结构强化", "画面层次太素"}]
    if density_issues:
        appeal_findings.append(f"画面密度不足：{', '.join(density_issues[:3])}")
        appeal_fixes.append("把画面拆成前景动作、证据道具、背景环境、可读短字和光影结构，不做空背景单主体")
        appeal_hints.append("补前景动作层、证据道具层、背景环境线索、可读冲突短字和屏幕光/警示色结构")
    appeal_ok = not appeal_findings
    teachers.append(
        _image_prompt_teacher_record(
            "appeal_teacher",
            "第一眼吸引力老师",
            appeal_ok,
            appeal_findings,
            appeal_fixes,
            "。".join(appeal_hints),
        )
    )

    clean_findings: list[str] = []
    if meta_hits:
        clean_findings.append(f"含生产元信息：{', '.join(meta_hits[:4])}")
    if len(text) > (760 if purpose == "cover" else 860):
        clean_findings.append("提示词过长，图片模型容易抓错重点")
    if re.search(r"(画面[:：]\s*){2,}|画面里有[。；;，,]?|限制[:：]|画幅比例|栏目字样|生产说明|视频扣费", text):
        clean_findings.append("含会被画进图里的规则词或残留旧词")
    clean_ok = not clean_findings and bool(layers.get("safety"))
    teachers.append(
        _image_prompt_teacher_record(
            "clean_teacher",
            "生图安全老师",
            clean_ok,
            clean_findings,
            [] if clean_ok else ["删掉画幅、编号、限制、栏目、生产说明等规则词，只保留正向视觉描述"],
            image_prompt_clean_guard(purpose),
        )
    )

    score = min(int(visual.get("score", 0) or 0), int(layer.get("score", 0) or 0))
    hard_teacher_keys = {"topic_teacher", "script_teacher"}
    for teacher in teachers:
        teacher["blocking"] = bool(not teacher.get("passed") and teacher.get("key") in hard_teacher_keys)
    integrity_issues = generation_prompt_integrity_issues(text)
    semantic_hard_ok = bool(
        int(semantic.get("overall", 0) or 0) >= 68
        and int(semantic.get("text_safety", 0) or 0) >= 60
        and not semantic.get("foreign_callouts")
        and not semantic.get("foreign_numeric_facts")
    )
    blocking = bool(
        any(item.get("blocking") for item in teachers)
        or not semantic_hard_ok
        or integrity_issues
    )
    return {
        "label": label,
        "purpose": purpose,
        "score": score,
        "passed": not blocking,
        "blocking": blocking,
        "advisory_passed": score >= 82 and all(item.get("passed") for item in teachers),
        "integrity_issues": integrity_issues,
        "visual": visual,
        "layer": layer,
        "semantic": semantic,
        "teachers": teachers,
        "rewrite_hints": [
            item.get("rewrite_hint")
            for item in teachers
            if isinstance(item, dict) and clean_text(str(item.get("rewrite_hint") or ""))
        ],
    }


def image_teacher_review_rank(review: dict[str, Any]) -> tuple[int, int, int]:
    teachers = review.get("teachers") if isinstance(review.get("teachers"), list) else []
    blocking_count = sum(1 for item in teachers if isinstance(item, dict) and not item.get("passed"))
    return (1 if review.get("passed") else 0, -blocking_count, int(review.get("score", 0) or 0))


PROMPT_DETAIL_STOPWORDS = {
    "真实",
    "摄影",
    "质感",
    "主体",
    "清楚",
    "画面",
    "字幕",
    "空间",
    "频道",
    "气质",
    "短标签",
    "可视化",
    "主题",
    "情境",
    "当前",
    "口播",
    "动作",
    "冲突",
    "来自",
    "优先",
    "本期",
    "本镜",
    "场景",
    "人物",
    "环境",
    "线索",
    "一个",
    "两个",
    "少量",
    "正在发生",
    "电影级摄影质感",
}


def image_prompt_detail_tokens(text: str, limit: int = 40) -> list[str]:
    source = clean_text(text)
    if not source:
        return []
    focused_parts = []
    for marker in ("主画面", "正在发生", "画面短标签", "冲突悬念", "情节锚点"):
        value = extract_content_prompt_field(source, marker, limit=180)
        if value:
            focused_parts.append(value)
    focused = "。".join(focused_parts) or source
    tokens: list[str] = []
    tokens.extend(re.findall(r"[A-Za-z]+(?:App|APP)?|[0-9]+(?:\.[0-9]+)?(?:G|GB|M|MB|%|万|亿|元|小时|分钟|年|次)", focused, flags=re.IGNORECASE))
    tokens.extend(re.findall(r"[\u4e00-\u9fffA-Za-z0-9]{2,18}", focused))
    quoted = re.findall(r"[“\"「](.*?)[”\"」]", focused)
    tokens.extend(quoted)
    result: list[str] = []
    for token in tokens:
        item = clean_text(token).strip("，,。；;：:（）()、/ ")
        if not item:
            continue
        if item in PROMPT_DETAIL_STOPWORDS:
            continue
        if re.fullmatch(r"\d+|[一二三四五六七八九十]+个?", item):
            continue
        if len(item) < 2:
            continue
        if len(item) > 18:
            item = item[:18]
        if item not in result:
            result.append(item)
        if len(result) >= limit:
            break
    return result


def image_prompt_detail_preservation(candidate: str, reference: str) -> dict[str, Any]:
    reference_tokens = image_prompt_detail_tokens(reference, 32)
    if len(reference_tokens) < 4:
        return {"required": False, "score": 100, "missing": [], "tokens": reference_tokens}
    candidate_text = clean_text(candidate)
    matched = [token for token in reference_tokens if token and token in candidate_text]
    score = int(round(len(matched) / max(1, len(reference_tokens)) * 100))
    missing = [token for token in reference_tokens if token not in matched]
    return {
        "required": True,
        "score": score,
        "matched": matched,
        "missing": missing[:8],
        "tokens": reference_tokens,
    }


def teacher_rewrite_generation_prompt(
    prompt: str,
    *,
    purpose: str,
    topic: str,
    brand: str,
    label: str,
    max_rounds: int = 3,
    semantic_context: dict[str, Any] | None = None,
) -> tuple[str, dict[str, Any]]:
    versions: list[dict[str, Any]] = []
    current = strengthen_generation_prompt(prompt, purpose=purpose, topic=topic, brand=brand)
    current = ensure_prompt_contains_speech_anchor(
        current,
        clean_text(str((semantic_context or {}).get("speech") or "")),
        purpose=purpose,
    )
    best_prompt = current
    best_review = image_prompt_teacher_review(current, purpose=purpose, topic=topic, brand=brand, label=label, semantic_context=semantic_context)

    for round_index in range(1, max_rounds + 1):
        review = image_prompt_teacher_review(current, purpose=purpose, topic=topic, brand=brand, label=label, semantic_context=semantic_context)
        versions.append({"round": round_index, "prompt": current, "review": review})
        if image_teacher_review_rank(review) > image_teacher_review_rank(best_review):
            best_prompt = current
            best_review = review
        if review.get("passed"):
            break
        hints = [clean_text(str(item)) for item in review.get("rewrite_hints", []) if clean_text(str(item))]
        if not hints:
            break
        next_prompt = strengthen_generation_prompt(
            "。".join([current, *hints]),
            purpose=purpose,
            topic=topic,
            brand=brand,
        )
        next_prompt = ensure_prompt_contains_speech_anchor(
            next_prompt,
            clean_text(str((semantic_context or {}).get("speech") or "")),
            purpose=purpose,
        )
        if next_prompt == current:
            break
        current = next_prompt
    final_review = image_prompt_teacher_review(current, purpose=purpose, topic=topic, brand=brand, label=label, semantic_context=semantic_context)
    if image_teacher_review_rank(best_review) > image_teacher_review_rank(final_review):
        current = best_prompt
        final_review = best_review
    return current, {
        "provider": "local-image-teachers",
        "rounds": versions,
        "final_review": final_review,
        "passed": final_review.get("passed"),
    }


def compose_image_prompt_teacher_messages(
    project: dict[str, Any],
    template: dict[str, Any],
    purpose: str,
    entries: list[dict[str, Any]],
) -> list[dict[str, str]]:
    topic = clean_text(str(project.get("topic_name") or ""))
    brand = clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or project.get("template") or ""))
    content_excerpt = ""
    try:
        project_id = int(project.get("id", 0) or 0)
        if project_id:
            content_excerpt = summarize_scene_text(content_without_image_prompts(storage.get_content(project_id)), 5000)
    except (ValueError, TypeError, OSError):
        content_excerpt = ""
    compact_entries = [
        {
            "target": item.get("target"),
            "label": item.get("label"),
            "original_prompt": item.get("original_prompt"),
            "elastic_prompt": item.get("elastic_prompt"),
            "local_fixed_prompt": item.get("final_prompt"),
            "semantic_context": item.get("semantic_context"),
            "visual_decision": item.get("visual_decision"),
            "teacher_findings": [
                {
                    "teacher": teacher.get("name"),
                    "findings": teacher.get("findings", []),
                    "fixes": teacher.get("fixes", []),
                }
                for teacher in (item.get("teacher_review") or {}).get("teachers", [])
                if isinstance(teacher, dict) and not teacher.get("passed")
            ],
        }
        for item in entries
    ]
    system = (
        "你是短视频视觉导演。只输出 JSON，不要 markdown，也不要只点评。"
        "每个场景必须先提出 A、B 两个语义正确但视觉路线明显不同的候选概念，再选择更适合当前口播、且与整批已选场景不重复的一个。"
        "两个概念不能只是换机位或换颜色：可以分别采用真实证据现场、概念隐喻、编辑设计、数据关系、物件叙事等不同表达方式。"
        "final_prompt 必须对应 selected_concept，并且可以直接发给文生图模型。"
        "硬边界只有：服务本期主题和当前口播；人物、对象、数字与因果不能改错；不得借用其它镜头或其它项目的信息。"
        "人物、对象、动作、证据物件、图形关系、构图和材质由你按这段口播自由设计，不套固定信息牌或固定版式。"
        "final_prompt 必须要求模型一次完成画面与原生文字；标题、完整结论、事实数字、批注和必要来源与场景融为一体，文字只来自当前口播，不设统一字数上限，并禁止截断、错误文字、乱码、Logo和水印。"
        "先核对 semantic_context.audio_anchor 与 semantic_context.speech，再参考原提示词中的有效场景证据；原提示词的构图、色调、人物和道具都不是必须继承的事实。"
        "整批场景要主动变化视觉载体，避免连续使用同一个人物、桌面、手机、蓝色办公室或同一种左右对比构图。"
        "不得用‘人物正对镜头摊手或皱眉 + 大问号/红叉 + 产品陈列’代替具体内容；除非口播本身就在讲人物反应，否则优先呈现真实动作、测试过程、因果关系或结果证据。"
    )
    user = json.dumps(
        {
            "topic": topic,
            "channel": brand,
            "purpose": purpose,
            "content_md_excerpt": content_excerpt,
            "output_schema": {
                "prompts": [
                    {
                        "target": "s_01.png",
                        "concepts": [
                            {"id": "A", "visual_idea": "候选视觉概念", "prompt": "候选 A 生图描述"},
                            {"id": "B", "visual_idea": "明显不同的候选视觉概念", "prompt": "候选 B 生图描述"},
                        ],
                        "selected_concept": "A",
                        "selection_reason": "为什么更贴合口播且不与相邻镜头重复",
                        "final_prompt": "直接可用的生图提示词",
                        "teacher_notes": ["改了什么"],
                    }
                ]
            },
            "items": compact_entries,
        },
        ensure_ascii=False,
    )
    return [{"role": "system", "content": system}, {"role": "user", "content": user}]


def rewrite_image_prompts_with_ai_teachers(
    project: dict[str, Any],
    template: dict[str, Any],
    purpose: str,
    entries: list[dict[str, Any]],
) -> dict[str, dict[str, Any]]:
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if not api_key or OpenAI is None or not entries:
        return {}
    base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
    model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
    thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
    reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
    client = OpenAI(api_key=api_key, base_url=base_url, timeout=90.0)
    extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
    if thinking_type in {"enabled", "disabled"}:
        extra_body["thinking"] = {"type": thinking_type}
    response = client.chat.completions.create(
        model=model,
        messages=compose_image_prompt_teacher_messages(project, template, purpose, entries),
        temperature=0.35,
        max_tokens=7000,
        response_format={"type": "json_object"},
        extra_body=extra_body,
    )
    choice = response.choices[0] if getattr(response, "choices", None) else None
    raw = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
    project_id = int(project.get("id", 0) or 0)
    if project_id:
        with contextlib.suppress(Exception):
            storage.write_text(storage.project_file(project_id, f"reports/{purpose}_prompt_teacher_raw.json"), raw)
    payload = _safe_json_from_text(raw)
    if not isinstance(payload, dict):
        return {}
    raw_prompts: list[Any] = []
    for key in ("prompts", "scenes", "items"):
        if isinstance(payload.get(key), list):
            raw_prompts = payload.get(key)
            break
    expected_targets = [clean_text(str(entry.get("target") or "")) for entry in entries]
    result: dict[str, dict[str, Any]] = {}
    for item_index, item in enumerate(raw_prompts):
        if not isinstance(item, dict):
            continue
        target = clean_text(str(item.get("target") or item.get("filename") or ""))
        if not target and item_index < len(expected_targets):
            target = expected_targets[item_index]
        concepts: list[dict[str, str]] = []
        raw_concepts = item.get("concepts") if isinstance(item.get("concepts"), list) else []
        for index, concept in enumerate(raw_concepts[:3]):
            if not isinstance(concept, dict):
                continue
            idea = clean_text(str(concept.get("visual_idea") or concept.get("idea") or ""))
            concept_prompt = clean_text(str(concept.get("prompt") or ""))
            if not idea and not concept_prompt:
                continue
            concepts.append(
                {
                    "id": clean_text(str(concept.get("id") or chr(ord("A") + index))),
                    "visual_idea": idea,
                    "prompt": concept_prompt,
                }
            )
        selected_id = clean_text(str(item.get("selected_concept") or item.get("selected") or ""))
        selected_item = next(
            (concept for concept in concepts if clean_text(str(concept.get("id") or "")) == selected_id),
            concepts[0] if concepts else {},
        )
        prompt = clean_text(
            str(
                item.get("final_prompt")
                or item.get("prompt")
                or selected_item.get("prompt")
                or selected_item.get("visual_idea")
                or ""
            )
        )
        if not target or not prompt:
            continue
        result[target] = {
            "prompt": prompt,
            "concepts": concepts,
            "selected_concept": selected_id or clean_text(str(selected_item.get("id") or "")),
            "selection_reason": clean_text(str(item.get("selection_reason") or "")),
            "teacher_notes": _text_list(item.get("teacher_notes"), [], limit=4, item_limit=80),
            "provider": f"deepseek-image-prompt-teachers:{model}",
        }
    return result


def preflight_generation_prompt_batch(project_id: int, prompts: list[dict[str, Any]], *, purpose: str) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    content_text = storage.get_content(project_id)
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    topic = clean_text(str(project.get("topic_name") or ""))
    brand = clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or template_key))
    semantic_contexts = image_semantic_context_map(project_id, content_text, mode)
    visual_brief: dict[str, Any] = {}
    try:
        stored_brief = storage.read_json(visual_brief_path(project_id), {})
        if isinstance(stored_brief, dict) and visual_brief_is_current(stored_brief, project, content_text):
            visual_brief = stored_brief
        else:
            visual_brief = get_or_create_visual_brief(
                project,
                template,
                content_text,
                scene_count=len(prompts) if purpose == "scene" else 0,
            )
    except Exception:
        visual_brief = build_visual_brief(
            project,
            template,
            content_text,
            scene_count=len(prompts) if purpose == "scene" else 0,
        )
    entries: list[dict[str, Any]] = []
    issues: list[dict[str, Any]] = []
    changed_count = 0
    final_prompts: dict[str, str] = {}
    kind = "cover" if purpose == "cover" else "scene"

    def semantic_context_for_target(target: str) -> dict[str, Any]:
        target_text = clean_text(str(target or ""))
        candidates = [target_text]
        if purpose == "cover":
            if target_text and not target_text.startswith("covers/"):
                candidates.insert(0, f"covers/{target_text}")
        else:
            if target_text and not target_text.startswith("scenes/"):
                candidates.insert(0, f"scenes/{target_text}")
        for candidate in candidates:
            context = semantic_contexts.get(candidate)
            if isinstance(context, dict):
                return context
        return {"topic": topic, "speech": "", "visual_director": ""}

    for item in prompts:
        target = clean_text(str(item.get("target") or item.get("label") or ""))
        label = clean_text(str(item.get("label") or target or "图片"))
        original = normalize_image_prompt(repair_legacy_mojibake(item.get("prompt") or ""))
        before_visual = prompt_visual_score(original, purpose)
        before_layer = image_prompt_layer_entry(original, kind=kind, topic=topic, brand=brand)
        semantic_context = semantic_context_for_target(target)
        visual_decision: dict[str, Any] = {}
        seed_prompt = original
        try:
            elastic_prompt, visual_decision = elastic_visual_prompt_for_image(
                project,
                template,
                content_text,
                visual_brief,
                purpose=purpose,
                target=target,
                label=label,
                source_prompt=original,
                semantic_context=semantic_context,
            )
            seed_prompt = source_first_image_prompt(original, elastic_prompt, purpose)
        except Exception as exc:
            visual_decision = {"error": str(exc)}
        if purpose == "scene":
            scene_index = image_target_scene_index(target, label)
            visual_scenes = visual_brief.get("scenes") if isinstance(visual_brief.get("scenes"), list) else []
            visual_scene = visual_scenes[scene_index - 1] if 0 < scene_index <= len(visual_scenes) and isinstance(visual_scenes[scene_index - 1], dict) else {}
            speech_anchor = clean_text(str(semantic_context.get("speech") or ""))
            if speech_anchor or visual_scene:
                visual_type = infer_visual_type(original, speech_anchor)
                scene_prompt = scene_specific_image_prompt(
                    topic=topic,
                    speech_text=speech_anchor,
                    source_prompt=original,
                    visual_scene=visual_scene,
                    visual_world=clean_text(str(visual_brief.get("visual_world") or "")),
                    narrative=narrative_state_for_scene(scene_index or 1, max(len(visual_scenes), len(prompts), 1)),
                    visual_type=visual_type,
                    viewpoint=scene_viewpoint_hint(scene_index or 1, max(len(visual_scenes), len(prompts), 1), visual_type),
                    style_hint=content_scene_style_hint(classify_material_style(f"{original}\n{speech_anchor}", template, "scene"), template),
                )
                seed_prompt = source_first_image_prompt(original, scene_prompt, purpose)
        fixed_prompt, teacher_rewrite = teacher_rewrite_generation_prompt(
            seed_prompt,
            purpose=purpose,
            topic=topic,
            brand=brand,
            label=label,
            semantic_context=semantic_context,
        )
        fixed_prompt = ensure_prompt_contains_speech_anchor(
            fixed_prompt,
            clean_text(str(semantic_context.get("speech") or "")),
            purpose=purpose,
        )
        after_visual = prompt_visual_score(fixed_prompt, purpose)
        after_layer = image_prompt_layer_entry(fixed_prompt, kind=kind, topic=topic, brand=brand)
        after_semantic = image_semantic_score(fixed_prompt, semantic_context, is_cover=purpose == "cover")
        before_semantic = image_semantic_score(original, semantic_context, is_cover=purpose == "cover")
        score = min(
            int(after_visual.get("score", 0) or 0),
            int(after_layer.get("score", 0) or 0),
            int(after_semantic.get("overall", 0) or 0),
        )
        original_score = min(
            int(before_visual.get("score", 0) or 0),
            int(before_layer.get("score", 0) or 0),
            int(before_semantic.get("overall", 0) or 0),
        )
        negative_rewrite_reverted = bool(original and fixed_prompt != original and score < original_score)
        if negative_rewrite_reverted:
            fixed_prompt = original
            after_visual = before_visual
            after_layer = before_layer
            after_semantic = before_semantic
            score = original_score
        changed_count += int(fixed_prompt != original)
        entry = {
            "target": target,
            "label": label,
            "purpose": purpose,
            "changed": fixed_prompt != original,
            "original_prompt": original,
            "elastic_prompt": seed_prompt,
            "final_prompt": fixed_prompt,
            "score": score,
            "original_score": original_score,
            "negative_rewrite_reverted": negative_rewrite_reverted,
            "visual_decision": visual_decision,
            "semantic_context": semantic_context,
            "before": {"visual": before_visual, "layer": before_layer},
            "after": {"visual": after_visual, "layer": after_layer, "semantic": after_semantic, "rewrite": teacher_rewrite},
            "teacher_review": teacher_rewrite.get("final_review", {}),
            "teacher_fixed": True,
            "ai_teacher_used": False,
        }
        entries.append(entry)

    ai_teacher_error = ""
    ai_teacher_results: dict[str, dict[str, Any]] = {}
    ai_teacher_needed = any(
        int(entry.get("score", 0) or 0) < 72
        or (
            purpose == "scene"
            and not semantic_scene_brief_integrity(
                str(entry.get("original_prompt") or ""),
                str(entry.get("final_prompt") or ""),
            ).get("ok")
        )
        for entry in entries
    )
    ai_teacher_requested = (
        bool(clean_text(runtime_env().get("DEEPSEEK_API_KEY", "")))
        and bool(entries)
        and ai_teacher_needed
    )
    if ai_teacher_requested:
        try:
            ai_teacher_results = rewrite_image_prompts_with_ai_teachers(project, template, purpose, entries)
        except Exception as exc:
            ai_teacher_error = str(exc)
    if ai_teacher_requested and not ai_teacher_results and not ai_teacher_error:
        ai_teacher_error = "AI 视觉导演返回空结构，已明确回退到本地语义提示词。"

    if ai_teacher_results:
        used_selected_carriers: set[str] = set()
        for entry in entries:
            target = clean_text(str(entry.get("target") or ""))
            ai_item = ai_teacher_results.get(target)
            if not ai_item:
                continue
            visual_concepts = ai_item.get("concepts") if isinstance(ai_item.get("concepts"), list) else []
            selected_concept_id = clean_text(str(ai_item.get("selected_concept") or ""))
            selected_concept_item = next(
                (
                    concept
                    for concept in visual_concepts
                    if isinstance(concept, dict) and clean_text(str(concept.get("id") or "")) == selected_concept_id
                ),
                visual_concepts[0] if visual_concepts and isinstance(visual_concepts[0], dict) else {},
            )
            selected_visual_concept = clean_text(
                str(selected_concept_item.get("visual_idea") or selected_concept_item.get("prompt") or "")
            )
            active_topic_type = clean_text(str(visual_brief.get("topic_type") or "general_editorial"))
            entry["visual_concepts"] = visual_concepts
            entry["selected_concept_candidate"] = selected_concept_id
            entry["concept_selection_reason"] = clean_text(str(ai_item.get("selection_reason") or ""))
            local_prompt = clean_text(str(entry.get("final_prompt") or ""))
            local_review = entry.get("teacher_review") if isinstance(entry.get("teacher_review"), dict) else {}
            ai_prompt = clean_text(str(ai_item.get("prompt") or ""))
            if not ai_prompt:
                continue
            semantic_context = semantic_context_for_target(target)
            if purpose == "scene" and visual_concepts:
                selected_quality_issues = visual_concept_quality_issues(selected_visual_concept)
                if selected_quality_issues:
                    for concept in visual_concepts:
                        if not isinstance(concept, dict) or concept is selected_concept_item:
                            continue
                        alternative_text = clean_text(str(concept.get("visual_idea") or concept.get("prompt") or ""))
                        alternative_context = f"{alternative_text} {concept.get('prompt', '')}"
                        if (
                            visual_concept_quality_issues(alternative_text)
                            or visual_topic_conflicts(alternative_text, active_topic_type)
                            or foreign_scene_numeric_facts(alternative_context, semantic_context)
                        ):
                            continue
                        selected_concept_item = concept
                        selected_concept_id = clean_text(str(concept.get("id") or ""))
                        selected_visual_concept = alternative_text
                        ai_prompt = clean_text(str(concept.get("prompt") or ai_prompt))
                        selected_quality_issues = []
                        entry["selected_concept_candidate"] = selected_concept_id
                        entry["concept_selection_reason"] = "原候选含自我否定、截断或不可执行描述，自动切换到可直接成图的候选。"
                        break
                selected_topic_conflicts = visual_topic_conflict_hits(selected_visual_concept, active_topic_type)
                if selected_topic_conflicts:
                    for concept in visual_concepts:
                        if not isinstance(concept, dict) or concept is selected_concept_item:
                            continue
                        alternative_text = clean_text(str(concept.get("visual_idea") or concept.get("prompt") or ""))
                        if visual_topic_conflicts(alternative_text, active_topic_type) or visual_concept_quality_issues(alternative_text):
                            continue
                        selected_concept_item = concept
                        selected_concept_id = clean_text(str(concept.get("id") or ""))
                        selected_visual_concept = alternative_text
                        ai_prompt = clean_text(str(concept.get("prompt") or ai_prompt))
                        selected_topic_conflicts = []
                        entry["selected_concept_candidate"] = selected_concept_id
                        entry["concept_selection_reason"] = "原候选混入其它题材的专属物件，自动切换到本期语义一致的候选。"
                        break
                selected_foreign_numbers = foreign_scene_numeric_facts(
                    f"{selected_visual_concept} {selected_concept_item.get('prompt', '')}",
                    semantic_context,
                )
                if selected_foreign_numbers:
                    for concept in visual_concepts:
                        if not isinstance(concept, dict) or concept is selected_concept_item:
                            continue
                        alternative_text = clean_text(str(concept.get("visual_idea") or concept.get("prompt") or ""))
                        alternative_foreign = foreign_scene_numeric_facts(
                            f"{alternative_text} {concept.get('prompt', '')}",
                            semantic_context,
                        )
                        if alternative_foreign or visual_concept_quality_issues(alternative_text):
                            continue
                        selected_concept_item = concept
                        selected_concept_id = clean_text(str(concept.get("id") or ""))
                        selected_visual_concept = alternative_text
                        ai_prompt = clean_text(str(concept.get("prompt") or ai_prompt))
                        entry["selected_concept_candidate"] = selected_concept_id
                        entry["concept_selection_reason"] = (
                            "原候选含当前口播未出现的数字，自动切换到事实一致的另一视觉概念。"
                        )
                        break
                selected_carriers = visual_concept_carriers(
                    f"{selected_visual_concept} {selected_concept_item.get('prompt', '')}"
                )
                if used_selected_carriers.intersection(selected_carriers):
                    for concept in visual_concepts:
                        if not isinstance(concept, dict) or concept is selected_concept_item:
                            continue
                        alternative_text = clean_text(str(concept.get("visual_idea") or concept.get("prompt") or ""))
                        alternative_carriers = visual_concept_carriers(f"{alternative_text} {concept.get('prompt', '')}")
                        alternative_foreign = foreign_scene_numeric_facts(
                            f"{alternative_text} {concept.get('prompt', '')}",
                            semantic_context,
                        )
                        if (
                            alternative_foreign
                            or visual_concept_quality_issues(alternative_text)
                            or used_selected_carriers.intersection(alternative_carriers)
                        ):
                            continue
                        selected_concept_item = concept
                        selected_concept_id = clean_text(str(concept.get("id") or ""))
                        selected_visual_concept = alternative_text
                        selected_carriers = alternative_carriers
                        ai_prompt = clean_text(str(concept.get("prompt") or ai_prompt))
                        entry["selected_concept_candidate"] = selected_concept_id
                        entry["concept_selection_reason"] = (
                            "原候选与本批前面镜头重复使用同一主载体，自动切换到视觉路线不同的候选。"
                        )
                        break
            direct_scene_grounding: dict[str, Any] = {}
            direct_ai_scene = False
            if purpose == "scene":
                direct_scene_grounding = ai_teacher_scene_grounding_report(
                    ai_prompt,
                    concept=selected_visual_concept,
                    semantic_context=semantic_context,
                    active_topic_type=active_topic_type,
                )
                entry["ai_teacher_grounding"] = direct_scene_grounding
                if direct_scene_grounding.get("accepted"):
                    direct_ai_scene = True
                    # The AI director's concrete shot is the creative source of
                    # truth.  Wrap it only with the current scene facts; do not
                    # run it through the generic local rewrite templates again.
                    selected_visual_concept = normalize_image_prompt(ai_prompt)
                    ai_prompt = grounded_ai_teacher_scene_prompt(
                        ai_prompt,
                        topic=topic,
                        semantic_context=semantic_context,
                    )
                    direct_review = image_prompt_teacher_review(
                        ai_prompt,
                        purpose=purpose,
                        topic=topic,
                        brand=brand,
                        label=clean_text(str(entry.get("label") or target)),
                        semantic_context=semantic_context,
                    )
                    ai_review = {
                        "provider": "ai-director-grounded-scene",
                        "rounds": [],
                        "final_review": direct_review,
                        "passed": True,
                    }
            preserve_latin_prompt = purpose == "cover" and prompt_is_latin_dominant(ai_prompt)
            if direct_ai_scene:
                pass
            elif preserve_latin_prompt:
                ai_prompt = normalize_image_prompt(ai_prompt)
                ai_prompt = ensure_prompt_keeps_topic_anchor(
                    ai_prompt,
                    topic=topic,
                    source=clean_text(str(semantic_context.get("speech") or selected_visual_concept)),
                    purpose=purpose,
                )
                direct_review = image_prompt_teacher_review(
                    ai_prompt,
                    purpose=purpose,
                    topic=topic,
                    brand=brand,
                    label=clean_text(str(entry.get("label") or target)),
                    semantic_context=semantic_context,
                )
                ai_review = {
                    "provider": "local-image-teachers-preserve-latin",
                    "rounds": [],
                    "final_review": direct_review,
                    "passed": direct_review.get("passed"),
                }
            else:
                ai_prompt = sanitize_prompt_for_image_model(ai_prompt, purpose) or ai_prompt
                ai_prompt, ai_review = teacher_rewrite_generation_prompt(
                    ai_prompt,
                    purpose=purpose,
                    topic=topic,
                    brand=brand,
                    label=clean_text(str(entry.get("label") or target)),
                    max_rounds=2,
                    semantic_context=semantic_context,
                )
            if not direct_ai_scene:
                ai_prompt = ensure_prompt_contains_speech_anchor(
                    ai_prompt,
                    clean_text(str(semantic_context.get("speech") or "")),
                    purpose=purpose,
                )
            ai_final_review = ai_review.get("final_review") if isinstance(ai_review.get("final_review"), dict) else {}
            integrity_issues = generation_prompt_integrity_issues(ai_prompt)
            if integrity_issues:
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_integrity_issues"] = integrity_issues
                entry["ai_teacher_notes"] = [
                    f"AI 生图提示词不完整，已回退：{', '.join(integrity_issues)}。",
                    *list(ai_item.get("teacher_notes", []) or [])[:3],
                ]
                continue
            if re.search(r"视频扣费|栏目字样|生产说明", ai_prompt):
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_notes"] = [
                    "AI 老师二改含会被画进图里的空句或规则词，已回退到本地老师版本。",
                    *list(ai_item.get("teacher_notes", []) or [])[:3],
                ]
                continue
            detail_preservation = image_prompt_detail_preservation(ai_prompt, local_prompt)
            has_distinct_concepts = len(visual_concepts) >= 2 and bool(selected_visual_concept)
            if detail_preservation.get("required") and int(detail_preservation.get("score", 0) or 0) < 58 and not has_distinct_concepts:
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_detail_preservation"] = detail_preservation
                entry["ai_teacher_notes"] = [
                    f"AI 老师二改丢失成稿关键画面细节，保真度 {detail_preservation.get('score')} 分，已回退到本地老师版本。",
                    f"缺失：{', '.join(str(item) for item in detail_preservation.get('missing', [])[:5])}",
                    *list(ai_item.get("teacher_notes", []) or [])[:2],
                ]
                continue
            if (
                local_prompt
                and local_review
                and image_teacher_review_rank(local_review) >= image_teacher_review_rank(ai_final_review)
                and not has_distinct_concepts
            ):
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_notes"] = [
                    "AI 老师二改未通过本地老师复检，已回退到本地老师改写版本。",
                    *list(ai_item.get("teacher_notes", []) or [])[:3],
                ]
                continue
            after_visual = prompt_visual_score(ai_prompt, purpose)
            after_layer = image_prompt_layer_entry(ai_prompt, kind=kind, topic=topic, brand=brand)
            after_semantic = image_semantic_score(ai_prompt, semantic_context, is_cover=purpose == "cover")
            score = min(
                int(after_visual.get("score", 0) or 0),
                int(after_layer.get("score", 0) or 0),
                int(after_semantic.get("overall", 0) or 0),
            )
            if direct_ai_scene:
                score = max(score, min(92, max(72, int(direct_scene_grounding.get("score", 0) or 0) - 8)))
            local_score = int(entry.get("score", 0) or 0)
            foreign_numbers = foreign_scene_numeric_facts(
                f"{ai_prompt.replace(clean_text(str(semantic_context.get('topic') or '')), '')} {selected_visual_concept}",
                semantic_context,
            )
            semantic_blocked = (
                not bool(direct_scene_grounding.get("accepted"))
                if direct_ai_scene
                else (
                    bool(after_semantic.get("foreign_callouts"))
                    or bool(after_semantic.get("foreign_numeric_facts"))
                    or bool(foreign_numbers)
                    or int(after_semantic.get("topic", 0) or 0) < 30
                    or visual_topic_conflicts(selected_visual_concept, active_topic_type)
                    or bool(visual_concept_quality_issues(selected_visual_concept))
                )
            )
            if has_distinct_concepts and semantic_blocked:
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_notes"] = [
                    "AI 候选概念偏离本期主题或混入其它镜头信息，已回退。"
                    + (f" 跨镜数字：{', '.join(foreign_numbers)}。" if foreign_numbers else ""),
                    *list(ai_item.get("teacher_notes", []) or [])[:3],
                ]
                continue
            if local_prompt and score < local_score and not has_distinct_concepts:
                entry["ai_teacher_used"] = False
                entry["ai_teacher_rejected"] = True
                entry["ai_teacher_provider"] = ai_item.get("provider")
                entry["ai_teacher_notes"] = [
                    f"AI 老师二改综合分 {score} 低于当前版本 {local_score}，已回退，避免负优化。",
                    *list(ai_item.get("teacher_notes", []) or [])[:3],
                ]
                continue
            if ai_prompt and ai_prompt != entry.get("final_prompt"):
                changed_count += 1
            entry["final_prompt"] = ai_prompt
            entry["score"] = score
            entry["after"] = {"visual": after_visual, "layer": after_layer, "semantic": after_semantic, "rewrite": ai_review}
            entry["teacher_review"] = ai_review.get("final_review", {})
            entry["ai_teacher_used"] = True
            entry["ai_teacher_direct"] = direct_ai_scene
            entry["selected_visual_concept"] = selected_visual_concept
            entry["selected_concept"] = selected_concept_id or clean_text(str(selected_concept_item.get("id") or ""))
            used_selected_carriers.update(
                visual_concept_carriers(f"{selected_visual_concept} {selected_concept_item.get('prompt', '')}")
            )
            entry["ai_teacher_provider"] = ai_item.get("provider")
            entry["ai_teacher_notes"] = ai_item.get("teacher_notes", [])

    used_scene_callouts: Counter[str] = Counter()
    callout_plan: list[dict[str, Any]] = []
    for entry in entries:
        target = clean_text(str(entry.get("target") or ""))
        label = clean_text(str(entry.get("label") or target or "图片"))
        final_prompt = clean_text(str(entry.get("final_prompt") or ""))
        semantic_context = entry.get("semantic_context") if isinstance(entry.get("semantic_context"), dict) else {}
        if not entry.get("ai_teacher_direct"):
            final_prompt = ensure_prompt_contains_speech_anchor(
                final_prompt,
                clean_text(str(semantic_context.get("speech") or "")),
                purpose=purpose,
            )
        if purpose == "scene":
            previous_prompt = final_prompt
            scene_index = image_target_scene_index(target, label) or len(callout_plan) + 1
            # The complete current speech is the source of truth. The image AI
            # may derive as many text and visual information elements as the
            # scene needs, without being boxed into a short preselected list.
            selected_callouts: list[str] = []
            final_prompt = apply_unique_scene_callouts_to_prompt(final_prompt, selected_callouts)
            if final_prompt != previous_prompt:
                changed_count += 1
            density_prompt_before = final_prompt
            if entry.get("ai_teacher_direct"):
                density_report = scene_visual_density_report(final_prompt)
            else:
                final_prompt, density_report = enhance_scene_prompt_density(
                    final_prompt,
                    entry,
                    topic=topic,
                    callouts=selected_callouts,
                )
            if final_prompt != density_prompt_before:
                changed_count += 1
            selected_visual_concept = clean_text(str(entry.get("selected_visual_concept") or ""))
            if not selected_visual_concept:
                visual_decision = entry.get("visual_decision") if isinstance(entry.get("visual_decision"), dict) else {}
                fallback_parts = [
                    f"主体：{'、'.join(str(item) for item in visual_decision.get('subjects', [])[:3])}"
                    if isinstance(visual_decision.get("subjects"), list) and visual_decision.get("subjects")
                    else "",
                    f"动作：{clean_text(str(visual_decision.get('action') or ''))}" if visual_decision.get("action") else "",
                    f"冲突：{clean_text(str(visual_decision.get('tension') or ''))}" if visual_decision.get("tension") else "",
                    clean_text(str(visual_decision.get("world") or visual_decision.get("visual_world") or "")),
                ]
                selected_visual_concept = compact_visual_concept(
                    "；".join(item for item in fallback_parts if item),
                    280,
                )
                if selected_visual_concept:
                    entry["fallback_visual_concept"] = selected_visual_concept
            balanced_prompt = balanced_scene_generation_brief(
                final_prompt,
                topic=topic,
                speech=clean_text(str(semantic_context.get("speech") or "")),
                anchor=clean_text(str(semantic_context.get("audio_anchor") or "")),
                concept=selected_visual_concept,
                source_information=semantic_context.get("source_information") if isinstance(semantic_context.get("source_information"), dict) else None,
            )
            if balanced_prompt != final_prompt:
                changed_count += 1
                final_prompt = balanced_prompt
            repaired_prompt, repaired_foreign_numbers = repair_foreign_scene_numeric_facts(
                final_prompt,
                semantic_context,
            )
            if repaired_prompt != final_prompt:
                changed_count += 1
                final_prompt = repaired_prompt
                entry["foreign_numeric_repair"] = {
                    "applied": True,
                    "removed": repaired_foreign_numbers,
                }
            score_after_callouts, after_visual, after_layer, after_semantic = score_final_image_prompt(
                final_prompt,
                purpose=purpose,
                kind=kind,
                topic=topic,
                brand=brand,
                semantic_context=semantic_context,
            )
            previous_score = int(entry.get("score", 0) or 0)
            concept_semantic_pass = bool(entry.get("selected_visual_concept")) and int(after_semantic.get("overall", 0) or 0) >= 75
            entry["score"] = max(previous_score, score_after_callouts, 72 if concept_semantic_pass else 0)
            entry["concept_semantic_override"] = concept_semantic_pass and max(previous_score, score_after_callouts) < 62
            after_payload = entry.get("after") if isinstance(entry.get("after"), dict) else {}
            after_payload.update(
                {
                    "visual": after_visual,
                    "layer": after_layer,
                    "semantic": after_semantic,
                    "callout_allocation_score": score_after_callouts,
                    "visual_density": density_report,
                }
            )
            entry["after"] = after_payload
            entry["readable_callouts"] = selected_callouts
            entry["callout_uniqueness_applied"] = True
            entry["visual_density_applied"] = final_prompt != density_prompt_before
            callout_plan.append({"target": target, "label": label, "callouts": selected_callouts})
        final_prompt = normalize_image_prompt(repair_legacy_mojibake(final_prompt))
        if purpose == "scene":
            integrity = semantic_scene_brief_integrity(original, final_prompt)
            contract_preserved = scene_prompt_preserves_channel_contract(original, final_prompt)
            if not integrity.get("ok") or not contract_preserved:
                final_prompt = original
                entry["best_version_lock"] = {
                    "applied": True,
                    "reason": "candidate_lost_scene_contract",
                    "missing": list(integrity.get("missing", [])),
                }
            # The contract lock above may restore the original prompt and with it
            # foreign numbers from another scene. Sanitize once more after the
            # lock so a deterministic repair does not turn into an endless
            # preflight/retry loop.
            final_prompt, post_lock_removed = repair_foreign_scene_numeric_facts(
                final_prompt,
                semantic_context,
            )
            if post_lock_removed:
                changed_count += 1
                entry["post_lock_numeric_repair"] = {
                    "applied": True,
                    "removed": post_lock_removed,
                }
        entry["final_prompt"] = final_prompt
        final_prompts[target] = final_prompt
        score = int(entry.get("score", 0) or 0)
        if score < 62:
            issues.append(
                quality_issue(
                    "warn",
                    label,
                    f"老师团改写后，实际生图提示词复检仍低：{score} 分。",
                    "全自动模式会使用当前口播语义保底继续生成，并在成图后按真实图片质量决定是否单张重绘。",
                )
            )
        elif score < 72:
            issues.append(
                quality_issue(
                    "warn",
                    label,
                    f"老师团已改写，但提示词仍偏弱：{score} 分。",
                    "可以继续生成；如果画面仍不好，单张重绘时会继续套用老师团改写链路。",
                )
            )
    scores = [int(item.get("score", 0) or 0) for item in entries]
    if ai_teacher_requested and not ai_teacher_results:
        issues.append(
            quality_issue(
                "warn",
                "AI 视觉概念",
                ai_teacher_error,
                "可继续使用本地语义提示词；下次预检会重新请求 A/B 候选概念。",
            )
        )
    hard_blockers: list[dict[str, Any]] = []
    for entry in entries:
        target = clean_text(str(entry.get("target") or ""))
        label = clean_text(str(entry.get("label") or target or "图片"))
        final_prompt = clean_text(str(entry.get("final_prompt") or ""))
        after = entry.get("after") if isinstance(entry.get("after"), dict) else {}
        semantic = after.get("semantic") if isinstance(after.get("semantic"), dict) else {}
        semantic_context = entry.get("semantic_context") if isinstance(entry.get("semantic_context"), dict) else {}
        blockers: list[str] = []
        if not final_prompt:
            blockers.append("提示词为空")
        if semantic.get("foreign_callouts"):
            blockers.append(f"仍含跨镜信息：{', '.join(str(item) for item in semantic.get('foreign_callouts', [])[:4])}")
        remaining_foreign_numbers = foreign_scene_numeric_facts(final_prompt, semantic_context)
        if remaining_foreign_numbers:
            blockers.append(f"仍含未核实数字：{', '.join(remaining_foreign_numbers[:4])}")
        if purpose == "scene" and clean_text(str(semantic_context.get("speech") or "")):
            if int(semantic.get("speech", 0) or 0) < 20 and int(semantic.get("audio_anchor", 0) or 0) < 20:
                blockers.append("没有承接当前口播")
        if blockers:
            entry["hard_blockers"] = blockers
            hard_blockers.append({"target": target, "label": label, "reasons": blockers})
            issues.append(
                quality_issue(
                    "risk",
                    label,
                    "；".join(blockers),
                    "系统已完成一次语义修复，仍有事实污染；只重建这一张的语义提示词后再发送图片模型。",
                )
            )
    avg_score = round(sum(scores) / len(scores), 1) if scores else 0
    generation_safe = not hard_blockers and bool(final_prompts)
    quality_passed = bool(scores) and min(scores) >= 62
    passed = generation_safe
    report = {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "purpose": purpose,
        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
        "passed": passed,
        "generation_safe": generation_safe,
        "quality_passed": quality_passed,
        "hard_blockers": hard_blockers,
        "continue_policy": (
            "generate_then_audit"
            if generation_safe and not quality_passed
            else ("generate" if generation_safe else "repair_before_provider")
        ),
        "score": int(round(avg_score)),
        "changed_count": changed_count,
        "prompt_count": len(entries),
        "issues": issues,
        "entries": entries,
        "final_prompts": final_prompts,
        "callout_plan": callout_plan,
        "teacher_pipeline": {
            "local_teachers": [name for _key, name in IMAGE_PROMPT_TEACHERS],
            "ai_teacher_used": any(bool(item.get("ai_teacher_used")) for item in entries),
            "ai_teacher_requested": ai_teacher_requested,
            "ai_teacher_result_count": len(ai_teacher_results),
            "ai_teacher_error": ai_teacher_error,
            "policy": "AI 视觉导演先给出 A/B 候选概念并选择；失败时明确记录，再回退本地语义提示词。",
        },
    }
    if generation_safe and final_prompts:
        with contextlib.suppress(Exception):
            updated_manifest = update_visual_prompt_manifest_prompts(
                project_id,
                purpose,
                final_prompts,
                content_text,
                prompt_scores={
                    clean_text(str(item.get("target") or "")): int(item.get("score", 0) or 0)
                    for item in entries
                    if clean_text(str(item.get("target") or ""))
                },
                source="prompt-preflight",
            )
            manifest_update = updated_manifest.get("last_prompt_update") if isinstance(updated_manifest, dict) else {}
            report["best_version_lock"] = manifest_update if isinstance(manifest_update, dict) else {}
            preserved = set(report["best_version_lock"].get("preserved_targets", []) or [])
            if preserved:
                manifest_items = (
                    updated_manifest.get("scenes", [])
                    if purpose == "scene"
                    else list((updated_manifest.get("covers", {}) or {}).values())
                )
                manifest_by_target = {
                    clean_text(str(item.get("target") or "")): item
                    for item in manifest_items
                    if isinstance(item, dict)
                }
                for entry in entries:
                    target = clean_text(str(entry.get("target") or ""))
                    if target not in preserved or target not in manifest_by_target:
                        continue
                    kept = manifest_by_target[target]
                    entry["candidate_prompt"] = entry.get("final_prompt")
                    entry["candidate_score"] = entry.get("score")
                    entry["final_prompt"] = clean_text(str(kept.get("prompt") or ""))
                    entry["score"] = int(kept.get("quality_score", 0) or 0)
                    entry["best_version_preserved"] = True
                    final_prompts[target] = entry["final_prompt"]
                report["final_prompts"] = final_prompts
                report["score"] = int(round(sum(int(item.get("score", 0) or 0) for item in entries) / max(1, len(entries))))
    storage.save_report(project_id, f"{purpose}_prompt_preflight", report)
    return report


def rhythm_signal_for_line(line: str, index: int, total: int) -> str:
    text = clean_text(line)
    if content_lines_use_english([text]):
        lowered = text.lower()
        if index <= 2 and (
            bool(re.search(r"[0-9?!]", text))
            or any(token in lowered for token in ("but", "actually", "the catch", "cost", "risk", "mistake", "not the"))
        ):
            return "hook"
        if any(token in lowered for token in ("for example", "for instance", "consider ", "imagine ", "in one case")):
            return "case"
        if any(token in lowered for token in ("but", "however", "instead", "actually", "turns out", "the catch")):
            return "turn"
        if "?" in text or any(token in lowered for token in ("then", "now", "compare", "because", "what happens")):
            return "push"
        if index >= total - 2 and is_explicit_interaction_cta(text):
            return "interaction"
        return "explain"
    if index <= 2 and (
        any(token in text for token in HOOK_SIGNAL_TOKENS)
        or any(opening_semantic_hook_signals(text).values())
    ):
        return "hook"
    if any(token in text for token in ("比如", "例如", "拿", "有一次", "举个例子", "真实")):
        return "case"
    if any(token in text for token in ("但是", "可", "其实", "结果", "反而", "偏偏", "真正", "表面")):
        return "turn"
    if any(token in text for token in RETENTION_SIGNAL_TOKENS) or "？" in text or "?" in text:
        return "push"
    if index >= total - 2 and any(token in text for token in INTERACTION_SIGNAL_TOKENS):
        return "interaction"
    return "explain"


def script_rhythm_report(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    content_text = content if content is not None else storage.get_content(project_id)
    lines = content_body_lines(content_text, mode)
    dialogue_lines = [strip_dialogue_speaker(line) for line in parse_dialogue_lines(content_text, mode)] or lines
    engagement = content_engagement_report(content_text, mode)
    opening_novelty: dict[str, Any] = {}
    with contextlib.suppress(Exception):
        opening_novelty = opening_novelty_report(project_id, content_text)
    issues: list[dict[str, Any]] = []
    visual_notes: list[dict[str, Any]] = []

    if not lines:
        issues.append(quality_issue("risk", "节奏", "没有可分析的正文/口播内容。", "先生成或粘贴 content.md。"))

    signals = [rhythm_signal_for_line(line, idx, len(lines)) for idx, line in enumerate(lines)]
    english_mode = engagement.get("detected_language") == "en-US"
    push_indexes = [idx for idx, signal in enumerate(signals) if signal in {"hook", "case", "turn", "push", "interaction"}]
    max_plain_gap = 0
    previous = -1
    for idx in [*push_indexes, len(lines)]:
        max_plain_gap = max(max_plain_gap, idx - previous - 1)
        previous = idx
    if english_mode:
        long_lines = [
            line
            for line in dialogue_lines
            if len(re.findall(r"\b[A-Za-z0-9][A-Za-z0-9'-]*\b", clean_text(line))) > 24
        ]
        ultra_short_lines = [
            line
            for line in dialogue_lines
            if 0 < len(re.findall(r"\b[A-Za-z0-9][A-Za-z0-9'-]*\b", clean_text(line))) < 3
        ]
    else:
        long_lines = [line for line in dialogue_lines if len(clean_text(line)) > 46]
        ultra_short_lines = [line for line in dialogue_lines if 0 < len(clean_text(line)) < 8]
    scene_count = len(resolved_scene_prompt_plan(project, template, content_text))
    audio_duration = safe_probe_duration(storage.project_file(project_id, "audio/podcast.mp3"))
    avg_scene_hold = round(audio_duration / scene_count, 2) if audio_duration > 0 and scene_count else 0
    retention = retention_duration_profile(project, template)
    spoken_char_count, estimated_duration = estimate_spoken_duration_sec(content_text, mode)

    if float(engagement.get("opening_score", 0) or 0) < CONTENT_OPENING_MIN_SCORE:
        issues.append(quality_issue("warn", "前三秒", "开头钩子不足，第一屏缺少明确代价、反差或悬念。", "第一句改成结果先行/反常识/具体痛点，并控制在 10-24 字。"))
    bad_phrase_hits = script_bad_phrase_hits("\n".join(dialogue_lines) or content_text)
    if bad_phrase_hits:
        issues.append(
            quality_issue(
                "risk",
                "口播套话/播客腔",
                f"存在弱开头或播客式收尾：{', '.join(bad_phrase_hits[:6])}。",
                "节奏增强会先删除这些句式，再补一个具体评论区互动问题。",
            )
        )
    if max_plain_gap >= 5:
        issues.append(quality_issue("warn", "中段推进", f"最长连续 {max_plain_gap} 句都缺少追问、转折、案例或反差。", "每 2-4 句插入一次追问、误区纠正、具体案例或“表面/真正”转折。"))
    if float(engagement.get("retention_score", 0) or 0) < CONTENT_RETENTION_MIN_SCORE:
        issues.append(quality_issue("warn", "中段留存", "中段缺少按节奏分布的新数字、案例、后果或反转。", "每 20-30 秒补一个新的追看理由，不能连续解释超过 3 段。"))
    if dialogue_lines and len(long_lines) / max(1, len(dialogue_lines)) > 0.28:
        length_label = "24 个英文单词" if english_mode else "46 字"
        issues.append(
            quality_issue(
                "warn",
                "口播句长",
                f"长句偏多：{len(long_lines)}/{len(dialogue_lines)} 句超过 {length_label}。",
                "把长句拆成短句，给字幕和语音留停顿。",
            )
        )
    if len(ultra_short_lines) >= max(4, len(dialogue_lines) // 4):
        issues.append(quality_issue("info", "口播碎片", "过短句偏多，可能显得碎。", "把连续短句合并成“短句 + 解释”结构。"))
    if float(engagement.get("interaction_score", 0) or 0) < CONTENT_INTERACTION_MIN_SCORE:
        issues.append(quality_issue("warn", "结尾互动", "结尾没有形成单一、低门槛互动。", "只保留一个具体评论动作，不要同时堆点赞、收藏、关注和转发。"))
    if retention.get("enabled") and estimated_duration and estimated_duration < float(retention.get("minimum_sec") or 0):
        shortfall = float(retention.get("minimum_sec") or 0) - estimated_duration
        level = "risk" if estimated_duration < float(retention.get("minimum_sec") or 0) * 0.72 else "warn"
        issues.append(
            quality_issue(
                level,
                "内容深度",
                f"口播约 {estimated_duration:.0f} 秒，比当前频道的完整表达下限少约 {shortfall:.0f} 秒，容易只给结论没有内容。",
                f"补足至少 {retention.get('information_beats', 5)} 个不同信息节点；优先增加可核实证据、原因、现实影响、误区纠正和具体行动，不要重复改写同一句话。",
            )
        )
    hollow = hollow_script_report(content_text, mode)
    if hollow.get("hollow"):
        details = "、".join(str(item) for item in hollow.get("hits", [])[:5])
        issues.append(
            quality_issue(
                "risk",
                "空壳文案",
                f"台词正在讲写作方法而不是本期内容：{details or '缺少主题事实和具体案例'}。",
                "重新调用文案模型，围绕本期已核实资料写出具体对象、机制、证据、案例和现实影响；禁止使用通用占位稿。",
            )
        )
    if avg_scene_hold > 20:
        visual_notes.append(quality_issue("warn", "画面停留", f"按当前音频估算，每张场景图平均停留 {avg_scene_hold:.0f} 秒。当前采用关键节点配图，不计入文案节奏扣分。", "优先用剪辑运动、字幕和局部特写维持画面变化；只有信息节点不足时再增加图片。"))
    elif avg_scene_hold and avg_scene_hold < 8:
        visual_notes.append(quality_issue("info", "画面停留", f"每张场景图平均停留 {avg_scene_hold:.0f} 秒，切换可能过快。", "确认字幕能读完，必要时合并相近镜头。"))

    score = quality_score_from_issues(issues)
    beats = [
        {
            "index": idx + 1,
            "signal": signal,
            "text": summarize_scene_text(line, 70),
            "chars": len(clean_text(line)),
        }
        for idx, (line, signal) in enumerate(zip(lines, signals))
    ]
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": project.get("topic_name", ""),
        "score": score,
        "verdict": quality_verdict(score),
        "engagement": {
            "overall_score": engagement.get("overall_score"),
            "opening_score": engagement.get("opening_score"),
            "retention_score": engagement.get("retention_score"),
            "interaction_score": engagement.get("interaction_score"),
            "opening_novelty_score": opening_novelty.get("score", 100),
            "opening_family": opening_novelty.get("family", ""),
        },
        "opening_novelty": opening_novelty,
        "metrics": {
            "line_count": len(lines),
            "dialogue_count": len(dialogue_lines),
            "push_signal_count": len(push_indexes),
            "max_plain_gap": max_plain_gap,
            "long_line_count": len(long_lines),
            "ultra_short_line_count": len(ultra_short_lines),
            "scene_prompt_count": scene_count,
            "audio_duration_sec": audio_duration,
            "avg_scene_hold_sec": avg_scene_hold,
            "spoken_char_count": spoken_char_count,
            "estimated_spoken_duration_sec": estimated_duration,
            "retention_minimum_sec": retention.get("minimum_sec", 0),
            "retention_target_sec": retention.get("target_sec", 0),
            "retention_maximum_sec": retention.get("maximum_sec", 0),
            "retention_soft_maximum_sec": retention.get("soft_maximum_sec", 0),
            "information_beats": retention.get("information_beats", 0),
            "source_depth": retention.get("source_depth", "light"),
        },
        "beats": beats[:80],
        "issues": issues,
        "visual_notes": visual_notes,
        "next_actions": [item.get("fix") or item.get("issue") for item in issues[:6]],
    }


SCRIPT_SECTION_TITLES = ("对话脚本", "口播脚本", "视频脚本", "脚本")


def detect_script_section_title(content: str) -> str:
    for title in SCRIPT_SECTION_TITLES:
        if extract_section(content, title, level=2):
            return title
    return "口播脚本"


def split_spoken_text_for_rhythm(text: str, limit: int = 42) -> list[str]:
    cleaned = clean_text(text)
    if content_lines_use_english([cleaned]):
        return split_caption_sentence(cleaned, limit=max(24, limit))
    if len(cleaned) <= limit:
        return [cleaned] if cleaned else []
    parts = [part for part in re.split(r"(?<=[。！？!?；;])\s*", cleaned) if clean_text(part)]
    if len(parts) <= 1:
        parts = [part for part in re.split(r"[，,]\s*", cleaned) if clean_text(part)]

    result: list[str] = []
    current = ""
    for part in parts:
        part = clean_text(part)
        if not part:
            continue
        candidate = f"{current}{part}" if not current else f"{current}{part}"
        if current and len(candidate) > limit:
            result.append(current)
            current = part
        else:
            current = candidate
    if current:
        result.append(current)

    normalized: list[str] = []
    for item in result:
        if len(item) <= limit + 8:
            normalized.append(item)
            continue
        chunk = item
        while len(chunk) > limit + 8:
            cut = max(chunk.rfind("，", 0, limit), chunk.rfind(",", 0, limit), chunk.rfind("、", 0, limit))
            if cut < 14:
                cut = limit
            normalized.append(chunk[:cut].strip("，,、 "))
            chunk = chunk[cut:].strip("，,、 ")
        if chunk:
            normalized.append(chunk)
    return [item for item in normalized if item]


def rhythm_bridge_line(topic: str, index: int, output_language: str = "zh-CN") -> str:
    source = clean_text(topic)
    if clean_text(output_language).lower().startswith("en"):
        variants = [
            "But that still leaves one missing step.",
            "Now compare that claim with what actually happens.",
            "Here is the detail that changes the conclusion.",
        ]
    elif any(token in source for token in ("自动续费", "扣费", "订阅", "免密", "支付")):
        variants = [
            "先别急，关键不是你点没点取消，而是钱到底从哪里扣。",
            "很多人以为关掉 App 就结束了，其实真正的开关在支付渠道里。",
            "记住这个判断：看见便宜试用，先找自动续费这一行。",
        ]
    else:
        variants = [
            "先别急，真正容易忽略的点在后面。",
            "很多人以为到这一步就结束了，其实关键还没出现。",
            "这里换个角度看，问题就清楚了。",
        ]
    return variants[index % len(variants)]


def interaction_line_for_topic(topic: str, output_language: str = "zh-CN") -> str:
    source = clean_text(topic)
    if clean_text(output_language).lower().startswith("en"):
        topic_anchor = re.sub(r"[^0-9A-Za-z ]+", "", source).strip()
        if topic_anchor:
            return f"What is the one detail about {topic_anchor[:56].rstrip()} that would change your mind?"
        return "What is the one real detail that would change your mind?"
    if any(token in source for token in ("自动续费", "扣费", "订阅", "免密", "支付")):
        return "如果你也收到过扣费短信，评论区告诉我：你手机里关掉了几个自动扣费项目？"
    if any(token in source.lower() for token in ("智能家居", "智能设备", "matter", "homekit", "米家")):
        return "你家哪件智能设备已经吃灰或变砖？评论区只写设备名。"
    if any(token in source for token in ("骗局", "诈骗", "骗子", "上门", "冒充")):
        return "你遇到过哪一种骗局？评论区只写关键词，提醒更多人。"
    if any(token in source for token in ("AI", "人工智能", "大模型", "智能体")):
        return "AI 最先改变了你工作的哪一步？评论区只说一个真实变化。"
    topic_anchor = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", source)[:12]
    if topic_anchor:
        return f"说到{topic_anchor}，你踩过哪个坑？评论区只写一个经历。"
    return "你遇到过类似情况吗？评论区只写一个最真实的例子。"


def format_rhythm_dialogue_line(speaker: str, text: str) -> str:
    clean_speaker = clean_text(speaker) or "主播"
    clean_spoken = clean_text(text)
    return f"【{clean_speaker}】{clean_spoken}" if clean_spoken else ""


def is_explicit_interaction_cta(text: str) -> bool:
    spoken = clean_text(strip_spoken_line_for_tts(text))
    if not spoken:
        return False
    spoken_lower = spoken.lower()
    if content_lines_use_english([spoken]):
        return bool(
            re.search(r"\b(you|your)\b", spoken_lower)
            and (
                "?" in spoken
                or any(
                    token in spoken_lower
                    for token in ("comment", "tell me", "which one", "what would", "what is the one", "share ")
                )
            )
        )
    if any(token in spoken for token in ("评论区", "评论里", "留言区", "评论告诉")):
        return True
    if "留言" in spoken and any(token in spoken for token in ("你", "告诉", "写", "说", "聊")):
        return True
    return any(token in spoken for token in ("发出来", "晒出来", "告诉我")) and any(token in spoken for token in ("你", "大家", "我"))


def is_terminal_interaction_intent(text: str) -> bool:
    spoken = clean_text(strip_spoken_line_for_tts(text))
    if not spoken:
        return False
    if is_explicit_interaction_cta(spoken):
        return True
    if "？" not in spoken and "?" not in spoken:
        return False
    if content_lines_use_english([spoken]):
        return bool(re.search(r"\b(you|your)\b", spoken.lower()))
    audience_signal = any(token in spoken for token in ("你", "大家", "你家", "你手机", "你会"))
    experience_signal = any(
        token in spoken
        for token in ("踩过", "哪个坑", "遇到过", "碰到过", "中过", "最离谱", "什么广告", "什么经历", "你更")
    )
    return audience_signal and experience_signal


def terminal_interaction_quality(text: str) -> int:
    spoken = clean_text(strip_spoken_line_for_tts(text))
    score = 0
    if is_explicit_interaction_cta(spoken):
        score += 8
    if any(token in spoken for token in ("只写", "只说", "只留")):
        score += 5
    specific_signals = sum(token in spoken for token in ("最离谱", "最懂你", "你家", "你手机"))
    score += min(6, specific_signals * 3)
    if "还是" in spoken:
        score += 2
    if 12 <= len(spoken) <= 72:
        score += 1
    elif len(spoken) > 96:
        score -= 2
    if spoken.startswith("说到"):
        score -= 6
    return score


def duplicate_terminal_interaction_indexes(lines: list[str], tail_spoken_limit: int = 6) -> list[int]:
    spoken_lines: list[tuple[int, str]] = []
    for index, line in enumerate(lines):
        spoken = strip_spoken_line_for_tts(line)
        if spoken:
            spoken_lines.append((index, spoken))
    interaction_lines = [
        (index, spoken)
        for index, spoken in spoken_lines[-max(1, tail_spoken_limit) :]
        if is_terminal_interaction_intent(spoken)
    ]
    if len(interaction_lines) <= 1:
        return []
    keep_index, _keep_spoken = max(
        interaction_lines,
        key=lambda item: (terminal_interaction_quality(item[1]), -item[0]),
    )
    return [index for index, _spoken in interaction_lines if index != keep_index]


def dedupe_terminal_interaction_lines(lines: list[str]) -> tuple[list[str], int]:
    duplicate_indexes = set(duplicate_terminal_interaction_indexes(lines))
    if not duplicate_indexes:
        return lines, 0
    kept = [line for index, line in enumerate(lines) if index not in duplicate_indexes]
    for index in range(len(kept) - 1, max(-1, len(kept) - 7), -1):
        if not is_terminal_interaction_intent(kept[index]):
            continue
        if not is_explicit_interaction_cta(kept[index]):
            kept[index] = kept[index].rstrip() + "评论区只写一个经历。"
        break
    return kept, len(duplicate_indexes)


def semantic_duplicate_dialogue_pairs(lines: list[str], lookahead: int = 4) -> list[dict[str, Any]]:
    spoken: list[tuple[int, str, str]] = []
    for index, line in enumerate(lines):
        text = clean_text(strip_spoken_line_for_tts(line))
        normalized = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", text).lower()
        if len(normalized) >= 10:
            spoken.append((index, text, normalized))
    pairs: list[dict[str, Any]] = []
    for position, (left_index, left_text, left_norm) in enumerate(spoken):
        for right_index, right_text, right_norm in spoken[position + 1 : position + 1 + max(1, lookahead)]:
            matcher = difflib.SequenceMatcher(None, left_norm, right_norm)
            ratio = matcher.ratio()
            longest = matcher.find_longest_match(0, len(left_norm), 0, len(right_norm)).size
            containment = longest / max(1, min(len(left_norm), len(right_norm)))
            explicit_duplicate_cta = is_explicit_interaction_cta(left_text) and is_explicit_interaction_cta(right_text)
            if not explicit_duplicate_cta and ratio < 0.78 and not (longest >= 12 and containment >= 0.62):
                continue
            pairs.append(
                {
                    "left_index": left_index,
                    "right_index": right_index,
                    "left": left_text,
                    "right": right_text,
                    "similarity": round(max(ratio, containment), 3),
                    "interaction_duplicate": explicit_duplicate_cta,
                }
            )
    return pairs


def low_information_transition_family(text: str) -> str:
    source = clean_text(strip_spoken_line_for_tts(text))
    if not source or len(source) > 34 or re.search(r"\d", source):
        return ""
    transition_patterns = (
        r"(?:先别急|等等|别急).*(?:后面|往下|接着)",
        r"(?:更狠|真正关键|关键|重点).*(?:还在后面|还没出现|马上出现)",
        r"(?:你以为|很多人以为).*(?:结束|完了).*(?:其实|但|可)",
        r"(?:问题来了|接着看|往下看|继续看)",
    )
    return "suspense_bridge" if any(re.search(pattern, source) for pattern in transition_patterns) else ""


def dialogue_information_score(text: str) -> int:
    source = clean_text(strip_spoken_line_for_tts(text))
    score = min(40, len(source))
    score += len(re.findall(r"\d+(?:\.\d+)?", source)) * 8
    score += sum(3 for token in SCENE_MEANINGFUL_SPEECH_TOKENS if token in source)
    if low_information_transition_family(source):
        score -= 20
    return score


def dedupe_script_semantic_lines(lines: list[str]) -> tuple[list[str], dict[str, int]]:
    remove_indexes: set[int] = set()
    duplicate_count = 0
    transition_count = 0
    for pair in semantic_duplicate_dialogue_pairs(lines, lookahead=6):
        if pair.get("interaction_duplicate"):
            continue
        left_index = int(pair.get("left_index", -1))
        right_index = int(pair.get("right_index", -1))
        if left_index < 0 or right_index < 0 or left_index in remove_indexes or right_index in remove_indexes:
            continue
        left = clean_text(str(pair.get("left") or ""))
        right = clean_text(str(pair.get("right") or ""))
        left_norm = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", left).lower()
        right_norm = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", right).lower()
        containment = bool(left_norm and right_norm and (left_norm in right_norm or right_norm in left_norm))
        if float(pair.get("similarity", 0) or 0) < 0.88 and not containment:
            continue
        left_score = dialogue_information_score(left)
        right_score = dialogue_information_score(right)
        remove_indexes.add(left_index if right_score > left_score + 3 else right_index)
        duplicate_count += 1

    recent_transitions: list[tuple[int, str]] = []
    spoken_position = 0
    for index, line in enumerate(lines):
        if index in remove_indexes:
            continue
        spoken = clean_text(strip_spoken_line_for_tts(line))
        if not spoken:
            continue
        family = low_information_transition_family(spoken)
        if family:
            repeated = next(
                (
                    previous_index
                    for previous_index, previous_family in reversed(recent_transitions)
                    if previous_family == family and spoken_position - previous_index <= 6
                ),
                None,
            )
            if repeated is not None:
                remove_indexes.add(index)
                transition_count += 1
            else:
                recent_transitions.append((spoken_position, family))
        spoken_position += 1

    return (
        [line for index, line in enumerate(lines) if index not in remove_indexes],
        {"duplicate_count": duplicate_count, "transition_count": transition_count},
    )


def script_bad_phrase_hits(text: str) -> list[str]:
    source = clean_text(text)
    hits: list[str] = []
    for pattern in WEAK_SCRIPT_OPENING_PATTERNS:
        if re.search(pattern, source):
            hits.append("弱开头套话")
            break
    for token in (*WEAK_SCRIPT_OUTRO_TOKENS, *WEAK_SCRIPT_CTA_TOKENS):
        if token in source:
            hits.append(token)
    return dedupe_clauses(hits)


def strip_weak_opening_prefix(spoken: str) -> tuple[str, list[str]]:
    cleaned = clean_text(spoken)
    hits: list[str] = []
    changed = True
    while changed and cleaned:
        changed = False
        for pattern in WEAK_SCRIPT_OPENING_PATTERNS:
            updated = re.sub(rf"^\s*(?:{pattern})", "", cleaned, count=1).strip(" ，,。；;：:")
            if updated != cleaned:
                hits.append("弱开头套话")
                cleaned = updated
                changed = True
                break
    return cleaned, hits


def strip_weak_outro_tail(spoken: str) -> tuple[str, list[str]]:
    cleaned = clean_text(spoken)
    hits = [token for token in WEAK_SCRIPT_OUTRO_TOKENS if token in cleaned]
    if not hits:
        return cleaned, []
    cut_positions = [cleaned.find(token) for token in hits if cleaned.find(token) >= 0]
    keep = cleaned[: min(cut_positions)].strip(" ，,。；;：:")
    if len(keep) >= 14 and any(token in keep for token in INTERACTION_SIGNAL_TOKENS):
        return keep, hits
    return "", hits


def trim_to_single_interaction_action(spoken: str) -> tuple[str, bool]:
    """Keep the audience question and its first comment action, drop stacked follows/likes."""
    cleaned = clean_text(spoken)
    if not is_explicit_interaction_cta(cleaned):
        return cleaned, False
    positions = [
        cleaned.find(token)
        for token in ("评论区", "评论里", "留言区", "评论告诉", "留言")
        if cleaned.find(token) >= 0
    ]
    if not positions:
        return cleaned, False
    action_start = min(positions)
    boundary = re.search(r"[。！？!?]", cleaned[action_start:])
    if not boundary:
        return cleaned, False
    end = action_start + boundary.end()
    trimmed = cleaned[:end].strip()
    return trimmed, trimmed != cleaned


def visual_prefixed_script_body(line: str) -> str | None:
    stripped = str(line or "").strip()
    if stripped.startswith(("- ", "* ")):
        stripped = stripped[2:].strip()
    stripped = re.sub(r"\*\*(.*?)\*\*", r"\1", stripped).strip()
    match = SPEAKER_PREFIX_RE.match(stripped)
    if not match or not is_visual_marker_speaker(match.group(1)):
        return None
    return str(match.group(2) or "").strip()


def looks_like_visual_prompt_body(text: str) -> bool:
    raw = str(text or "").strip()
    source = clean_text(raw).strip("“”\"'‘’【】[] ")
    if not source or not re.search(r"[0-9A-Za-z\u4e00-\u9fff]", source):
        return True
    if len(source) <= 18 and raw.endswith(("”】", "\"】", "’】", "】")):
        return True
    if re.match(
        r"^(?:画面|镜头|场景|分镜|切到|切换到|回到开头|电脑屏幕|屏幕|主角|人物|表格|数据流向|示意图|"
        r"手机\s*[+＋]\s*电脑|左边|右边|中间|背景|画面上方|画面下方|底部文字|俯拍|特写)",
        source,
    ):
        return True
    visual_nouns = (
        "画面", "镜头", "屏幕", "界面", "鼠标", "手指特写", "图标", "弹窗", "字体", "箭头",
        "背景", "表格", "示意图", "双屏", "色块", "构图", "景别", "字幕区", "权限窗口",
    )
    visual_actions = (
        "出现", "显示", "浮现", "切换", "弹出", "划过", "点击", "标注", "列出", "连接", "伸出",
        "特写", "放大", "缩小", "虚化", "飘浮", "排布", "构成",
    )
    noun_hits = sum(token in source for token in visual_nouns)
    action_hits = sum(token in source for token in visual_actions)
    return noun_hits >= 2 or (noun_hits >= 1 and action_hits >= 1)


def repair_visual_prompt_contamination_text(content: str, mode: str) -> tuple[str, list[str]]:
    if mode == "article":
        return content, []
    title = detect_script_section_title(content)
    section = extract_section(content, title, level=2)
    if not section:
        return content, []

    nonempty_lines = [line for line in section.splitlines() if clean_text(line)]
    visual_marked = [line for line in nonempty_lines if visual_prefixed_script_body(line) is not None]
    mass_contamination = len(visual_marked) >= 3 and len(visual_marked) / max(1, len(nonempty_lines)) >= 0.45

    repaired: list[str] = []
    removed = 0
    recovered = 0
    trimmed = 0
    for raw in section.splitlines():
        body = visual_prefixed_script_body(raw)
        if body is None:
            original = raw.rstrip()
            stripped = original.strip()
            prefix = ""
            normalized = stripped
            if normalized.startswith(("- ", "* ")):
                prefix = normalized[:2]
                normalized = normalized[2:].strip()
            normalized = re.sub(r"\*\*(.*?)\*\*", r"\1", normalized).strip()
            parsed = parse_dialogue_speaker_line(normalized, max_speaker_len=18)
            if parsed:
                speaker, spoken = parsed
                cleaned_spoken = sanitize_spoken_body_for_tts(spoken)
                if not cleaned_spoken:
                    if looks_like_visual_generation_instruction(spoken) or looks_like_visual_prompt_body(spoken):
                        removed += 1
                        continue
                elif cleaned_spoken != clean_text(spoken):
                    repaired.append(f"{prefix}{format_rhythm_dialogue_line(speaker, cleaned_spoken)}")
                    trimmed += 1
                    continue
            elif looks_like_visual_generation_instruction(normalized):
                removed += 1
                continue
            repaired.append(original)
            continue
        removed += 1
        if not mass_contamination or looks_like_visual_prompt_body(body):
            continue
        spoken = re.sub(r"[”\"’']?[】\]]\s*$", "", body).strip()
        spoken = clean_text(spoken).strip()
        if not spoken:
            continue
        repaired.append(format_rhythm_dialogue_line("主播", spoken))
        recovered += 1

    compacted: list[str] = []
    for line in repaired:
        if not line.strip() and (not compacted or not compacted[-1].strip()):
            continue
        compacted.append(line)
    repaired_section = "\n".join(compacted).strip()
    if not removed and not recovered and not trimmed:
        return content, []
    if not repaired_section:
        return content, []
    hits = [f"移除口播区画面提示词{removed}行"]
    if recovered:
        hits.append(f"恢复误标口播{recovered}行")
    if trimmed:
        hits.append(f"剥离台词前置画面描述{trimmed}行")
    return replace_section(content, title, repaired_section, level=2), hits


def rewrite_script_section_bad_phrases(script: str, topic: str, mode: str) -> tuple[str, list[str]]:
    if mode == "article":
        return script, []
    output_language = "en-US" if content_lines_use_english([script]) else "zh-CN"
    output: list[str] = []
    hits: list[str] = []
    spoken_count = 0
    last_speaker = "主播"

    for raw in script.splitlines():
        original = raw.rstrip()
        stripped = original.strip()
        if not stripped:
            output.append(original)
            continue
        prefix = ""
        body = stripped
        if body.startswith(("- ", "* ")):
            prefix = body[:2]
            body = body[2:].strip()
        normalized = re.sub(r"\*\*(.*?)\*\*", r"\1", body).strip()
        if is_standalone_speaker_label(normalized):
            last_speaker = normalized.strip("【】[]：:")
            hits.append("移除空角色行")
            continue
        parsed = parse_dialogue_speaker_line(normalized, max_speaker_len=18)
        if not parsed:
            if any(token in normalized for token in WEAK_SCRIPT_OUTRO_TOKENS):
                hits.extend(token for token in WEAK_SCRIPT_OUTRO_TOKENS if token in normalized)
                continue
            cleaned = strip_spoken_line_for_tts(normalized)
            if cleaned:
                spoken_count += 1
                if spoken_count <= 3:
                    cleaned, opening_hits = strip_weak_opening_prefix(cleaned)
                    hits.extend(opening_hits)
                cleaned, outro_hits = strip_weak_outro_tail(cleaned)
                if outro_hits:
                    hits.extend(outro_hits)
                cleaned, interaction_trimmed = trim_to_single_interaction_action(cleaned)
                if interaction_trimmed:
                    hits.append("结尾只保留一个互动动作")
                if not cleaned:
                    continue
                if any(token in cleaned for token in WEAK_SCRIPT_CTA_TOKENS) and not any(token in cleaned for token in INTERACTION_SIGNAL_TOKENS):
                    hits.extend(token for token in WEAK_SCRIPT_CTA_TOKENS if token in cleaned)
                    continue
                output.append(f"{prefix}{cleaned}" if prefix else cleaned)
            else:
                output.append(original)
            continue

        speaker = clean_text(parsed[0]) or last_speaker
        spoken = strip_leading_stage_direction(clean_text(parsed[1]))
        last_speaker = speaker
        if not spoken:
            output.append(original)
            continue

        spoken_count += 1
        if spoken_count <= 3:
            spoken = clean_opening_spoken_line(spoken)
            spoken, opening_hits = strip_weak_opening_prefix(spoken)
            hits.extend(opening_hits)
        spoken, outro_hits = strip_weak_outro_tail(spoken)
        if outro_hits:
            hits.extend(outro_hits)
        spoken, interaction_trimmed = trim_to_single_interaction_action(spoken)
        if interaction_trimmed:
            hits.append("结尾只保留一个互动动作")
        if not spoken:
            continue
        if any(token in spoken for token in WEAK_SCRIPT_CTA_TOKENS) and not any(token in spoken for token in INTERACTION_SIGNAL_TOKENS):
            hits.extend(token for token in WEAK_SCRIPT_CTA_TOKENS if token in spoken)
            continue
        output.append(f"{prefix}{format_rhythm_dialogue_line(speaker, spoken)}" if prefix else format_rhythm_dialogue_line(speaker, spoken))

    output, semantic_dedupe = dedupe_script_semantic_lines(output)
    if semantic_dedupe.get("duplicate_count"):
        hits.append("合并重复口播")
    if semantic_dedupe.get("transition_count"):
        hits.append("移除重复转折")
    output, duplicate_interaction_count = dedupe_terminal_interaction_lines(output)
    if duplicate_interaction_count:
        hits.append("合并重复互动结尾")
    dialogue_parts: list[str] = []
    for line in output:
        normalized_line = line.strip().removeprefix("- ").removeprefix("* ").strip()
        parsed = parse_dialogue_speaker_line(normalized_line, max_speaker_len=18)
        if parsed:
            dialogue_parts.append(parsed[1])
            continue
        spoken = strip_spoken_line_for_tts(normalized_line)
        if spoken:
            dialogue_parts.append(spoken)
    tail = "\n".join(dialogue_parts)[-240:]
    if not any(is_explicit_interaction_cta(item) for item in dialogue_parts[-6:]) or any(token in tail for token in WEAK_SCRIPT_OUTRO_TOKENS):
        output.append(
            format_rhythm_dialogue_line(
                last_speaker,
                interaction_line_for_topic(topic, output_language),
            )
        )
        hits.append("补具体互动结尾")
        output, removed_after_append = dedupe_terminal_interaction_lines(output)
        if removed_after_append:
            hits.append("合并重复互动结尾")

    return "\n".join(output).strip(), dedupe_clauses(hits)


def repair_script_bad_phrases_text(content: str, topic: str, mode: str) -> tuple[str, list[str]]:
    if mode == "article":
        return content, []
    title = detect_script_section_title(content)
    section = extract_section(content, title, level=2)
    if not section:
        return content, []
    repaired_section, hits = rewrite_script_section_bad_phrases(section, topic, mode)
    if not hits or repaired_section == section:
        return content, hits
    return replace_section(content, title, repaired_section, level=2), hits


def opening_repair_candidates(hook: str) -> list[str]:
    source = clean_opening_spoken_line(hook)
    if not source:
        return []
    candidates: list[str] = []

    def add(value: str) -> None:
        candidate = clean_text(value).strip(" ，,；;：:—-。")
        if 8 <= len(candidate) <= 46 and candidate != source and candidate not in candidates:
            if candidate[-1:] not in "。！？!?":
                candidate += "。"
            candidates.append(candidate)

    add(re.sub(r"^(?:就这|就这点|就这么点)[？?!！]+\s*", "", source))
    add(re.sub(r"^(?:先)?别急(?:着)?[^，。！？!?]{0,30}[，,：:]\s*", "", source))
    add(re.sub(r"^(?:很多人|不少人|大多数人|多数人)[^，。！？!?]{0,34}[，,：:]\s*", "", source))

    sentence_parts = [clean_text(item) for item in re.split(r"(?<=[。！？!?])", source) if clean_text(item)]
    if len(sentence_parts) > 1 and len(sentence_parts[0].strip("。！？!?")) <= 8:
        add("".join(sentence_parts[1:2]))
    for sentence in sentence_parts:
        add(sentence)
        for clause in re.split(r"[，,；;—]", sentence):
            add(clause)
    if "——" in source:
        left, right = source.split("——", 1)
        add(left)
        add(right)
    return candidates


def replace_first_spoken_line(content: str, replacement: str, mode: str) -> str:
    title = "正文" if mode == "article" else detect_script_section_title(content)
    section = extract_section(content, title, level=2)
    if not section:
        return content
    output = section.splitlines()
    for index, raw in enumerate(output):
        stripped = raw.strip()
        if not stripped or stripped.startswith(("#", "[配图")):
            continue
        normalized = re.sub(r"^\s*(?:[-*]\s+)", "", stripped)
        normalized = re.sub(r"\*\*(.*?)\*\*", r"\1", normalized).strip()
        if is_stage_direction_line(normalized) or looks_like_visual_direction(normalized):
            continue
        parsed = parse_dialogue_speaker_line(normalized, max_speaker_len=18)
        indent = raw[: len(raw) - len(raw.lstrip())]
        bullet_match = re.match(r"^\s*([-*]\s+)", raw)
        bullet = bullet_match.group(1) if bullet_match else ""
        if parsed:
            output[index] = f"{indent}{bullet}{format_rhythm_dialogue_line(parsed[0], replacement)}"
            break
        spoken = clean_opening_spoken_line(normalized)
        if len(spoken) >= 6:
            output[index] = f"{indent}{bullet}{replacement}"
            break
    else:
        return content

    updated = replace_section(content, title, "\n".join(output).strip(), level=2)
    updated = re.sub(
        r"(?m)^(\s*-\s*钩子\s*[:：]\s*).*$",
        lambda match: f"{match.group(1)}{replacement}",
        updated,
        count=1,
    )
    highlights = extract_section(updated, "重点字幕", level=2)
    if highlights:
        highlight_lines = highlights.splitlines()
        for index, raw in enumerate(highlight_lines):
            match = re.match(r"^(\s*\d+[.)、]\s*)(.+?)\s*$", raw)
            if not match:
                continue
            highlight = clean_text(match.group(2))
            cleaned_highlight = re.sub(r"^(?:就这|就这点|就这么点)[？?!！]+\s*", "", highlight)
            if cleaned_highlight != highlight and clean_text(cleaned_highlight):
                highlight_lines[index] = f"{match.group(1)}{cleaned_highlight}"
            break
        updated = replace_section(updated, "重点字幕", "\n".join(highlight_lines).strip(), level=2)
    return updated


def repair_channel_opening_repetition(project_id: int, content: str) -> dict[str, Any]:
    before = opening_novelty_report(project_id, content)
    if not before.get("repetitive"):
        return {"changed": False, "content": content, "before": before, "after": before, "replacement": ""}

    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    history = channel_opening_history(project, template)
    plan = channel_opening_diversity_plan(project, template)
    current_hook = clean_text(str(before.get("hook") or ""))
    scored: list[tuple[float, str]] = []
    for candidate in opening_repair_candidates(current_hook):
        similarities = [
            opening_similarity(candidate, str(item.get("hook") or ""), clean_text(str(item.get("topic") or "")))
            for item in history
        ]
        maximum = max(similarities, default=0.0)
        surface = opening_surface_signature(candidate)
        repeated_surface = bool(surface and any(item.get("surface") == surface for item in history[:8]))
        candidate_family = opening_family(candidate)
        specificity = 0.0
        specificity += 0.8 if re.search(r"\d", candidate) else 0.0
        specificity += 0.6 if any(token in candidate for token in ("手机", "门锁", "广告", "屏幕", "火锅", "手表", "音箱", "App", "APP")) else 0.0
        specificity += 0.5 if any(token in candidate for token in ("弹", "按", "夹", "亮", "搜", "打开", "关", "买", "装", "测")) else 0.0
        preference = 0.7 if candidate_family in (plan.get("preferred_families") or []) else 0.0
        score = (1.0 - maximum) * 5.0 + specificity + preference - (2.0 if repeated_surface else 0.0)
        if maximum < 0.78 and not repeated_surface:
            scored.append((score, candidate))
    if not scored:
        return {"changed": False, "content": content, "before": before, "after": before, "replacement": ""}

    replacement = max(scored, key=lambda item: item[0])[1]
    repaired = replace_first_spoken_line(content, replacement, mode)
    after = opening_novelty_report(project_id, repaired)
    improved = repaired != content and (
        not after.get("repetitive")
        or int(after.get("score", 0) or 0) >= int(before.get("score", 0) or 0) + 12
    )
    if not improved:
        return {"changed": False, "content": content, "before": before, "after": before, "replacement": ""}
    return {
        "changed": True,
        "content": repaired,
        "before": before,
        "after": after,
        "replacement": replacement,
    }


def repair_stale_opening_highlight(content: str) -> tuple[str, list[str]]:
    highlights = extract_section(content, "重点字幕", level=2)
    if not highlights:
        return content, []
    lines = highlights.splitlines()
    for index, raw in enumerate(lines):
        match = re.match(r"^(\s*\d+[.)、]\s*)(.+?)\s*$", raw)
        if not match:
            continue
        original = clean_text(match.group(2))
        repaired = re.sub(r"^(?:就这|就这点|就这么点)[？?!！]+\s*", "", original)
        if repaired != original and clean_text(repaired):
            lines[index] = f"{match.group(1)}{repaired}"
            return replace_section(content, "重点字幕", "\n".join(lines).strip(), level=2), ["同步清理重点字幕旧开场"]
        break
    return content, []


def is_strong_numeric_fact(token: str) -> bool:
    normalized = normalized_numeric_fact(token)
    return bool(
        normalized
        and not normalized.startswith(("几", "数"))
        and re.search(
            r"(?:%|秒|分钟|小时|天|年|字|元|块|万|亿|次|倍|家|人|条|款|台|"
            r"mAh|Ah|mWh|Wh|kWh|mW|kW|W|mV|V|mA|A|GHz|MHz|kHz|Hz|GB|TB|MB|KB|"
            r"毫安时|毫安|安时|安|毫瓦时|瓦时|千瓦时|毫瓦|千瓦|瓦|毫伏|伏|摄氏度|℃|°C)$",
            normalized,
            flags=re.IGNORECASE,
        )
        and not re.fullmatch(r"(?:一|1)(?:人|条|款|台|次|家)", normalized)
    )


def numeric_fact_is_ordinal(line: str, token: str) -> bool:
    source = clean_text(line)
    raw = clean_text(token)
    if not source or not raw:
        return False
    return any(match.start() > 0 and source[match.start() - 1] == "第" for match in re.finditer(re.escape(raw), source))


def extract_contextual_numeric_claims(text: str) -> list[dict[str, str]]:
    source = clean_text(text)
    claims: list[dict[str, str]] = []
    pattern = re.compile(
        r"血压(?P<middle>[^，。！？!?\d]{0,10}?)(?P<first>\d{2,3})(?:(?P<separator>[、，,/和至到~～-]+)(?P<second>\d{2,3}))?(?:\+|以上)?"
    )
    for match in pattern.finditer(source):
        claims.append({"raw": match.group("first"), "normalized": f"血压{match.group('first')}"})
        if match.group("second"):
            claims.append({"raw": match.group("second"), "normalized": f"血压{match.group('second')}"})
    return claims


FACT_USAGE_META_LABELS = {
    "封面主标题",
    "封面副标题",
    "核心观点",
    "推荐发布标题",
    "钩子",
    "互动钩子",
    "免责声明",
}
FACT_AUTHORITY_SECTIONS = ("原始材料简述", "资料边界", "参考资料")
FACT_EXCLUDED_SECTIONS = {
    "图片提示词",
    "场景图提示词",
    "参考资料",
    "资料来源",
    "原始材料简述",
    "资料边界",
}


def strong_numeric_claims_in_line(line: str) -> list[dict[str, str]]:
    source = clean_text(line)
    claims: list[dict[str, str]] = []
    seen: set[str] = set()
    for token in extract_numeric_fact_tokens(source):
        normalized = normalized_numeric_fact(token)
        if (
            not normalized
            or normalized in seen
            or not is_strong_numeric_fact(token)
            or numeric_fact_is_ordinal(source, token)
        ):
            continue
        seen.add(normalized)
        claims.append({"raw": clean_text(token), "normalized": normalized, "kind": "numeric"})
    for claim in extract_contextual_numeric_claims(source):
        normalized = clean_text(str(claim.get("normalized") or ""))
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        claims.append(
            {
                "raw": clean_text(str(claim.get("raw") or "")),
                "normalized": normalized,
                "kind": "contextual_measurement",
            }
        )
    return claims


def numeric_fact_authority_records(
    project_id: int,
    content: str,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
) -> list[dict[str, str]]:
    source_brief = storage.get_brief(project_id) if brief is None and project_id else str(brief or "")
    source_references = storage.get_references(project_id) if references is None and project_id else (references or [])
    records: list[dict[str, str]] = []

    def append_record(kind: str, label: str, text: str) -> None:
        value = clean_text(text)
        if value:
            records.append({"kind": kind, "label": clean_text(label), "text": value})

    append_record("brief", "brief.md", source_brief)
    for index, item in enumerate(source_references, start=1):
        if not isinstance(item, dict):
            continue
        source_name = clean_text(str(item.get("source") or ""))
        source_url = clean_text(str(item.get("url") or ""))
        if source_name in {"历史稿", "历史内容"} or re.search(r"[/\\]data[/\\]projects[/\\]\d+[/\\]content\.md$", source_url, flags=re.IGNORECASE):
            continue
        label = clean_text(str(item.get("title") or "")) or f"参考资料 {index}"
        text = " ".join(
            clean_text(str(item.get(field) or ""))
            for field in ("title", "snippet", "source")
        )
        append_record("reference", label, text)
    for title in FACT_AUTHORITY_SECTIONS:
        append_record("content_source", f"content.md / {title}", extract_section(content, title, level=2))
    return records


def numeric_fact_source_map(records: Iterable[dict[str, str]]) -> dict[str, list[dict[str, str]]]:
    result: dict[str, list[dict[str, str]]] = {}
    for record in records:
        source = clean_text(str(record.get("text") or ""))
        source_ref = {
            "kind": clean_text(str(record.get("kind") or "source")),
            "label": clean_text(str(record.get("label") or "资料来源")),
        }
        for claim in strong_numeric_claims_in_line(source):
            fact = clean_text(str(claim.get("normalized") or ""))
            if not fact:
                continue
            entries = result.setdefault(fact, [])
            if source_ref not in entries:
                entries.append(source_ref)
    return result


def content_numeric_fact_usages(content: str, mode: str) -> list[dict[str, Any]]:
    usages: list[dict[str, Any]] = []
    section = ""
    section_indexes: dict[str, int] = {}
    seen: set[tuple[str, int, str]] = set()

    def append_line(section_name: str, line: str, *, label: str = "") -> None:
        candidate = clean_text(line)
        if not candidate:
            return
        next_index = section_indexes.get(section_name, 0) + 1
        section_indexes[section_name] = next_index
        for claim in strong_numeric_claims_in_line(candidate):
            fact = clean_text(str(claim.get("normalized") or ""))
            key = (section_name, next_index, fact)
            if not fact or key in seen:
                continue
            seen.add(key)
            usages.append(
                {
                    "section": section_name,
                    "line_index": next_index,
                    "label": clean_text(label),
                    "fact": fact,
                    "raw": clean_text(str(claim.get("raw") or "")),
                    "kind": clean_text(str(claim.get("kind") or "numeric")),
                    "line": candidate,
                }
            )

    for raw_line in str(content or "").splitlines():
        stripped = raw_line.strip()
        heading = re.match(r"^(#{1,6})[ \t]+(.+?)\s*$", stripped)
        if heading:
            level = len(heading.group(1))
            heading_text = clean_text(heading.group(2))
            if level == 1:
                section = "标题"
                append_line(section, heading_text)
            elif level == 2:
                section = heading_text
            continue
        if not stripped or section in FACT_EXCLUDED_SECTIONS:
            continue
        if section == "Meta":
            field_match = re.match(r"^[-*]\s*(?:\*\*)?\s*([^：:]+?)\s*(?:\*\*)?\s*[：:]\s*(.+?)\s*$", stripped)
            if not field_match:
                continue
            label = clean_text(field_match.group(1))
            if label not in FACT_USAGE_META_LABELS:
                continue
            append_line("Meta", stripped, label=label)
            continue
        if section == "口播脚本":
            spoken = clean_text(strip_spoken_line_for_tts(stripped))
            if spoken and not is_terminal_interaction_intent(spoken):
                append_line(section, spoken)
            continue
        if section == "重点字幕":
            append_line(section, stripped)
            continue
        if mode == "article":
            append_line(section or "正文", stripped)
    return usages


def build_episode_fact_registry(
    project_id: int,
    content: str,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    project = storage.get_project(project_id) if project_id else {}
    mode = clean_text(str(project.get("template_mode") or "video"))
    authority_records = numeric_fact_authority_records(
        project_id,
        content,
        brief=brief,
        references=references,
    )
    source_map = numeric_fact_source_map(authority_records)
    usages = content_numeric_fact_usages(content, mode)
    usage_map: dict[str, list[dict[str, Any]]] = {}
    for usage in usages:
        fact = clean_text(str(usage.get("fact") or ""))
        if fact:
            usage_map.setdefault(fact, []).append(usage)

    fact_order: list[str] = []
    for usage in usages:
        fact = clean_text(str(usage.get("fact") or ""))
        if fact and fact not in fact_order:
            fact_order.append(fact)

    facts: list[dict[str, Any]] = []
    for fact in fact_order:
        sources = source_map.get(fact, [])
        fact_usages = usage_map.get(fact, [])
        if fact_usages and sources:
            status = "verified"
        elif fact_usages:
            status = "unsupported"
        else:
            status = "source_only"
        facts.append(
            {
                "fact": fact,
                "status": status,
                "sources": sources,
                "usages": fact_usages,
            }
        )

    verified_facts = [item["fact"] for item in facts if item.get("status") == "verified"]
    unsupported_facts = [item for item in facts if item.get("status") == "unsupported"]
    authority_payload = [
        {
            "kind": record.get("kind", ""),
            "label": record.get("label", ""),
            "text": record.get("text", ""),
        }
        for record in authority_records
    ]
    authority_hash = hashlib.sha256(
        json.dumps(authority_payload, ensure_ascii=False, sort_keys=True).encode("utf-8", errors="ignore")
    ).hexdigest()[:16]
    fact_hash = hashlib.sha256(
        json.dumps(facts, ensure_ascii=False, sort_keys=True).encode("utf-8", errors="ignore")
    ).hexdigest()[:16]
    return {
        "version": FACT_REGISTRY_VERSION,
        "generated_at": storage.now_ts(),
        "content_hash": visual_brief_source_hash(content),
        "authority_hash": authority_hash,
        "fact_hash": fact_hash,
        "source_available": bool(authority_records),
        "verified_facts": verified_facts,
        "source_facts": sorted(source_map),
        "unsupported_facts": unsupported_facts,
        "facts": facts,
        "counts": {
            "verified": len(verified_facts),
            "unsupported": len(unsupported_facts),
            "source_only": sum(1 for item in facts if item.get("status") == "source_only"),
            "used": sum(1 for item in facts if item.get("usages")),
        },
    }


def save_episode_fact_registry(
    project_id: int,
    content: str | None = None,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
    registry: dict[str, Any] | None = None,
) -> dict[str, Any]:
    content_text = content if content is not None else storage.get_content(project_id)
    candidate = registry if isinstance(registry, dict) else build_episode_fact_registry(
        project_id,
        content_text,
        brief=brief,
        references=references,
    )
    path = storage.project_file(project_id, "fact_registry.json")
    existing = storage.read_json(path, {})
    identity_keys = ("version", "content_hash", "authority_hash", "fact_hash")
    if isinstance(existing, dict) and all(existing.get(key) == candidate.get(key) for key in identity_keys):
        return existing
    storage.write_json(path, candidate)
    return candidate


def numeric_source_consistency_report(
    project_id: int,
    content: str,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    registry = build_episode_fact_registry(
        project_id,
        content,
        brief=brief,
        references=references,
    )
    unsupported: list[dict[str, Any]] = []
    for fact_entry in registry.get("unsupported_facts", []):
        if not isinstance(fact_entry, dict):
            continue
        for usage in fact_entry.get("usages", []):
            if not isinstance(usage, dict):
                continue
            kind = clean_text(str(usage.get("kind") or "numeric"))
            unsupported.append(
                {
                    "section": clean_text(str(usage.get("section") or "文案")),
                    "line_index": int(usage.get("line_index") or 0),
                    "label": clean_text(str(usage.get("label") or "")),
                    "fact": clean_text(str(usage.get("fact") or fact_entry.get("fact") or "")),
                    "line": clean_text(str(usage.get("line") or "")),
                    "reason": (
                        "该精确医疗数值未在 brief、原始材料或参考资料中找到同值依据"
                        if kind == "contextual_measurement"
                        else "该精确数字未在 brief、原始材料或参考资料中找到同值依据"
                    ),
                    "kind": kind,
                }
            )
    return {
        "checked": True,
        "source_available": bool(registry.get("source_available")),
        "supported_facts": list(registry.get("source_facts") or []),
        "verified_facts": list(registry.get("verified_facts") or []),
        "unsupported_facts": unsupported,
        "passed": not unsupported,
        "fact_registry_hash": clean_text(str(registry.get("fact_hash") or "")),
    }


def soften_unsupported_numeric_claim_line(line: str, facts: Iterable[str]) -> tuple[str, list[str]]:
    original = clean_text(line)
    rewritten = original
    target_facts = {normalized_numeric_fact(item) for item in facts if clean_text(item)}
    if not target_facts:
        return original, []

    contextual_targets = [item for item in target_facts if item.startswith("血压")]
    if contextual_targets:
        rewritten = re.sub(
            r"血压[^，。！？!?\d]{0,10}?\d{2,3}(?:[、，,/和至到~～-]+\d{2,3})?(?:\+|以上)?",
            "血压突然飙高",
            rewritten,
        )

    rewritten = re.sub(
        r"[一二三四五六七八九十百千万两\d]+个人里(?:至少|大约|约)?[一二三四五六七八九十百千万两\d]+个(?:人)?中招",
        "不少人都会中招",
        rewritten,
    )
    rewritten = re.sub(
        r"[一二三四五六七八九十百千万两\d]+年[、至到和或~～-]+[一二三四五六七八九十百千万两\d]+年",
        "很长一段时间",
        rewritten,
    )

    hits: list[str] = [f"{item}改为定性表达" for item in contextual_targets if rewritten != original]
    for raw in extract_numeric_fact_tokens(original):
        normalized = normalized_numeric_fact(raw)
        if normalized not in target_facts or raw not in rewritten:
            continue
        before = rewritten
        escaped = re.escape(raw)

        # Rewrite the surrounding claim before falling back to a token replacement.
        # This keeps spoken Chinese natural (for example, "一千块买的" must become
        # "花大价钱买的", not the broken phrase "一笔买的").
        if re.search(r"(?:元|块|万|亿)$", normalized):
            rewritten = re.sub(rf"{escaped}\s*\d+\s*包邮", "低价包邮", rewritten)
            rewritten = re.sub(rf"{escaped}\s*包邮", "低价包邮", rewritten)
            rewritten = re.sub(rf"{escaped}\s*买", "花大价钱买", rewritten)
            rewritten = re.sub(rf"花(?:了)?\s*{escaped}", "花了不少钱", rewritten)
            rewritten = re.sub(rf"(?:亏|赔)(?:了)?\s*{escaped}", "亏了不少钱", rewritten)
        elif normalized.endswith("%"):
            rewritten = re.sub(
                rf"(?:电池)?健康度\s*(?:跌到|降到|只剩|还剩)\s*{escaped}",
                "电池健康度明显下降",
                rewritten,
            )
            rewritten = re.sub(
                rf"(?:才|只)\s*(?:进|涨|充)(?:了)?\s*{escaped}(?:\s*的电)?",
                "电量却只涨了一点",
                rewritten,
            )
            rewritten = re.sub(
                rf"(?:达到|高达|超过|只有|仅有|降到|跌到|还剩|只剩)\s*{escaped}",
                "出现明显变化",
                rewritten,
            )
        elif re.search(r"(?:秒|分钟|小时)$", normalized):
            rewritten = re.sub(rf"(?:只要|仅需|不到)\s*{escaped}", "很快", rewritten)
            rewritten = re.sub(rf"(?:等待?|等了?)\s*{escaped}", "等一小会儿", rewritten)

        rewritten = re.sub(
            rf"(?:偷偷|擅自)?停了{escaped}(?P<object>[^，。！？!?]{{1,10}}?药)",
            r"擅自停用\g<object>后",
            rewritten,
        )
        rewritten = re.sub(rf"出事前最后{escaped}", "出事前", rewritten)
        rewritten = re.sub(rf"{escaped}内", "短时间内", rewritten)
        if raw in rewritten:
            if re.search(r"(?:秒|分钟|小时)$", normalized):
                replacement = "短时间"
            elif re.search(r"(?:天|年)$", normalized):
                replacement = "一段时间"
            elif re.search(r"(?:元|块|万|亿)$", normalized):
                replacement = "不少钱"
            elif normalized.endswith("%"):
                replacement = "明显"
            elif normalized.endswith("倍"):
                replacement = "更大"
            elif normalized.endswith("次"):
                replacement = "多次"
            elif re.search(r"(?:家|人|条|款|台)$", normalized):
                replacement = "不少"
            else:
                replacement = "一些"
            rewritten = rewritten.replace(raw, replacement)
        if rewritten != before:
            hits.append(f"{normalized}改为定性表达")

    return rewritten, dedupe_clauses(hits)


def repair_project_unsupported_numeric_facts(project_id: int, content: str | None = None) -> dict[str, Any]:
    original_content = content if content is not None else storage.get_content(project_id)
    brief = storage.get_brief(project_id)
    references = storage.get_references(project_id)
    repaired_content, hits = soften_unsupported_numeric_facts_text(
        project_id,
        original_content,
        brief=brief,
        references=references,
    )
    changed = repaired_content != original_content
    validation = numeric_source_consistency_report(
        project_id,
        repaired_content,
        brief=brief,
        references=references,
    )
    result: dict[str, Any] = {
        "ok": not validation.get("unsupported_facts"),
        "changed": changed,
        "hits": hits,
        "content": repaired_content,
        "remaining": validation.get("unsupported_facts", []),
    }
    if changed:
        result.update(
            save_project_content_bundle(
                project_id,
                repaired_content,
                image_dirty_reason="content.md 已移除无来源精确数字，图片提示词已同步重建，图片需要重新确认",
                refresh_quality_report=False,
            )
        )
    return result


def soften_unsupported_numeric_facts_text(
    project_id: int,
    content: str,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
) -> tuple[str, list[str]]:
    report = numeric_source_consistency_report(
        project_id,
        content,
        brief=brief,
        references=references,
    )
    unsupported = report.get("unsupported_facts") if isinstance(report.get("unsupported_facts"), list) else []
    grouped: dict[tuple[str, int, str], list[str]] = {}
    for item in unsupported:
        if not isinstance(item, dict):
            continue
        line = clean_text(str(item.get("line") or ""))
        fact = clean_text(str(item.get("fact") or ""))
        if line and fact:
            key = (
                clean_text(str(item.get("section") or "文案")),
                int(item.get("line_index") or 0),
                line,
            )
            grouped.setdefault(key, []).append(fact)

    rewritten = str(content or "")
    hits: list[str] = []
    for (_section, _line_index, line), facts in grouped.items():
        repaired_line, line_hits = soften_unsupported_numeric_claim_line(line, facts)
        if repaired_line == line:
            continue
        rewritten = rewritten.replace(line, repaired_line, 1)
        hits.extend(line_hits)
    return rewritten, dedupe_clauses(hits)


def canonicalize_project_content(
    project_id: int,
    content: str,
    *,
    brief: str | None = None,
    references: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    topic = clean_text(str(project.get("topic_name") or first_heading(content) or ""))
    original = str(content or "")
    normalized = compact_content_meta(original)
    normalized, visual_prompt_hits = repair_visual_prompt_contamination_text(normalized, mode)
    normalized, bad_phrase_hits = repair_script_bad_phrases_text(normalized, topic, mode)
    normalized, highlight_hits = repair_stale_opening_highlight(normalized)
    opening_repair = repair_channel_opening_repetition(project_id, normalized)
    normalized = str(opening_repair.get("content") or normalized).rstrip() + "\n"
    # Unsupported facts must remain visible to the gate. Token-by-token replacements
    # such as "3倍" -> "更大" silently damage sentence grammar and spoken meaning.
    numeric_repair_hits: list[str] = []
    opening_report = opening_novelty_report(project_id, normalized)
    numeric_consistency = numeric_source_consistency_report(
        project_id,
        normalized,
        brief=brief,
        references=references,
    )
    fact_registry = build_episode_fact_registry(
        project_id,
        normalized,
        brief=brief,
        references=references,
    )
    actions = [*visual_prompt_hits, *bad_phrase_hits, *highlight_hits, *numeric_repair_hits]
    if opening_repair.get("changed"):
        actions.append("合并同频道重复开场")
    return {
        "content": normalized,
        "changed": normalized != original,
        "actions": dedupe_clauses(actions),
        "bad_phrase_repair": bad_phrase_hits,
        "opening_repair": {
            "changed": bool(opening_repair.get("changed")),
            "replacement": opening_repair.get("replacement", ""),
        },
        "opening_novelty": opening_report,
        "numeric_consistency": numeric_consistency,
        "fact_registry": fact_registry,
    }


def semantic_text_hash(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8", errors="ignore")).hexdigest()[:16]


def content_semantic_fingerprints(
    project: dict[str, Any],
    template: dict[str, Any],
    content: str,
) -> dict[str, Any]:
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    project_topic = clean_text(str(project.get("topic_name") or ""))
    document_topic = clean_text(str(first_heading(content) or project_topic))
    topic = document_topic or project_topic
    core_viewpoint = clean_text(extract_bullet_field(content, "核心观点"))
    counterpoint = clean_text(extract_bullet_field(content, "反常识点"))
    spoken_lines = [
        clean_text(strip_spoken_line_for_tts(item))
        for item in parse_dialogue_lines(content, mode)
        if clean_text(strip_spoken_line_for_tts(item))
    ]
    if mode == "article" and not spoken_lines:
        spoken_lines = [clean_text(item) for item in content_body_lines(content, mode) if clean_text(item)]
    opening = spoken_lines[0] if spoken_lines else ""
    terminal_indexes = {
        index
        for index in range(max(0, len(spoken_lines) - 6), len(spoken_lines))
        if is_terminal_interaction_intent(spoken_lines[index])
    }
    cta_lines = [spoken_lines[index] for index in sorted(terminal_indexes)]
    core_lines = [
        line
        for index, line in enumerate(spoken_lines)
        if index != 0 and index not in terminal_indexes
    ]
    cover_payload = {
        "topic": topic,
        "title": first_heading(content),
        "cover_title": extract_meta_field(content, "封面主标题") or extract_meta_field(content, "推荐发布标题"),
        "cover_subtitle": extract_meta_field(content, "封面副标题"),
        "core": core_viewpoint,
        "counterpoint": counterpoint,
    }
    bgm_payload = {
        "topic": topic,
        "core": core_viewpoint,
        "counterpoint": counterpoint,
        "template": clean_text(str(project.get("template") or template.get("key") or "")),
    }
    return {
        "mode": mode,
        "topic": topic,
        "project_topic": project_topic,
        "document_topic": document_topic,
        "core_viewpoint": core_viewpoint,
        "counterpoint": counterpoint,
        "spoken_lines": spoken_lines,
        "opening": opening,
        "cta_lines": cta_lines,
        "core_lines": core_lines,
        "speech_hash": semantic_text_hash(spoken_lines),
        "opening_hash": semantic_text_hash(opening),
        "cta_hash": semantic_text_hash(cta_lines),
        "core_hash": semantic_text_hash(core_lines),
        "topic_hash": semantic_text_hash(document_topic),
        "viewpoint_hash": semantic_text_hash({"core": core_viewpoint, "counterpoint": counterpoint}),
        "cover_hash": semantic_text_hash(cover_payload),
        "bgm_semantic_hash": semantic_text_hash(bgm_payload),
        "line_hashes": [semantic_text_hash(line) for line in spoken_lines],
    }


def changed_core_line_fragments(before_lines: list[str], after_lines: list[str]) -> list[str]:
    matcher = difflib.SequenceMatcher(None, before_lines, after_lines)
    fragments: list[str] = []
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            continue
        for value in [*before_lines[i1:i2], *after_lines[j1:j2]]:
            cleaned = clean_text(value)
            if cleaned and cleaned not in fragments:
                fragments.append(cleaned)
    return fragments


def semantic_scene_match_score(fragment: str, scene_text: str) -> float:
    left = clean_text(fragment)
    right = clean_text(scene_text)
    if not left or not right:
        return 0.0
    left_compact = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", left).lower()
    right_compact = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "", right).lower()
    if not left_compact or not right_compact:
        return 0.0
    matcher = difflib.SequenceMatcher(None, left_compact, right_compact)
    longest = matcher.find_longest_match(0, len(left_compact), 0, len(right_compact)).size
    containment = longest / max(1, min(len(left_compact), len(right_compact)))
    left_units = _alignment_ngrams(left_compact)
    right_units = _alignment_ngrams(right_compact)
    overlap = len(left_units.intersection(right_units)) / max(1, min(len(left_units), len(right_units)))
    left_numbers = set(re.findall(r"\d+(?:\.\d+)?", left_compact))
    right_numbers = set(re.findall(r"\d+(?:\.\d+)?", right_compact))
    number_bonus = 0.16 if left_numbers and left_numbers.intersection(right_numbers) else 0.0
    return min(1.0, max(matcher.ratio(), containment, overlap) + number_bonus)


def changed_core_scene_targets(
    project_id: int,
    before_lines: list[str],
    after_lines: list[str],
) -> dict[str, Any]:
    fragments = changed_core_line_fragments(before_lines, after_lines)
    plan = storage.read_json(storage.project_file(project_id, "audio/scene_plan.json"), {})
    scenes = plan.get("scenes") if isinstance(plan, dict) and isinstance(plan.get("scenes"), list) else []
    ranked: list[tuple[float, int]] = []
    for item in scenes:
        if not isinstance(item, dict):
            continue
        try:
            index = int(item.get("index", 0) or 0)
        except (TypeError, ValueError):
            continue
        if index <= 0:
            continue
        scene_text = " ".join(
            clean_text(str(item.get(field) or ""))
            for field in ("speech_text", "speech_summary", "audio_anchor", "text", "prompt", "image_prompt")
        )
        score = max((semantic_scene_match_score(fragment, scene_text) for fragment in fragments), default=0.0)
        ranked.append((score, index))

    changed_blocks = max(1, sum(1 for tag, *_rest in difflib.SequenceMatcher(None, before_lines, after_lines).get_opcodes() if tag != "equal"))
    target_count = min(2, changed_blocks)
    selected = [index for score, index in sorted(ranked, key=lambda item: (item[0], -item[1]), reverse=True) if score >= 0.12][:target_count]

    if not selected:
        scene_count = len(scenes)
        if scene_count <= 0:
            summary = storage.get_summary(project_id)
            scene_count = int(summary.get("scene_count", 0) or 0) if isinstance(summary, dict) else 0
        if scene_count > 0:
            matcher = difflib.SequenceMatcher(None, before_lines, after_lines)
            changed_positions = [j1 for tag, _i1, _i2, j1, _j2 in matcher.get_opcodes() if tag != "equal"]
            position = min(changed_positions, default=0)
            index = round(position * max(0, scene_count - 1) / max(1, len(after_lines) - 1)) + 1
            selected = [max(1, min(scene_count, index))]

    return {
        "targets": [f"s_{index:02d}.png" for index in sorted(set(selected))],
        "changed_lines": fragments,
        "matched_scores": [
            {"scene": f"s_{index:02d}.png", "score": round(score, 3)}
            for score, index in sorted(ranked, key=lambda item: item[0], reverse=True)[:4]
        ],
    }


def content_change_impact(project_id: int, before_content: str, after_content: str) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    before = content_semantic_fingerprints(project, template, before_content)
    after = content_semantic_fingerprints(project, template, after_content)
    topic_or_viewpoint_changed = (
        before["topic_hash"] != after["topic_hash"]
        or before["viewpoint_hash"] != after["viewpoint_hash"]
    )
    if str(before_content or "").strip() == str(after_content or "").strip():
        scope = "unchanged"
    elif before["speech_hash"] == after["speech_hash"]:
        if topic_or_viewpoint_changed:
            scope = "full_script"
        else:
            scope = "cover_only" if before["cover_hash"] != after["cover_hash"] else "metadata_or_format"
    elif topic_or_viewpoint_changed:
        scope = "full_script"
    elif before["core_hash"] == after["core_hash"] and before["opening_hash"] == after["opening_hash"]:
        scope = "cta_only"
    elif before["core_hash"] == after["core_hash"] and before["cta_hash"] == after["cta_hash"]:
        scope = "opening_only"
    elif before["core_hash"] == after["core_hash"]:
        scope = "opening_and_cta"
    else:
        matcher = difflib.SequenceMatcher(None, before["core_lines"], after["core_lines"])
        changed_core_lines = sum(
            max(i2 - i1, j2 - j1)
            for tag, i1, i2, j1, j2 in matcher.get_opcodes()
            if tag != "equal"
        )
        scope = "scene_local" if changed_core_lines <= 2 else "full_script"

    speech_changed = before["speech_hash"] != after["speech_hash"]
    cover_changed = before["cover_hash"] != after["cover_hash"]
    bgm_changed = before["bgm_semantic_hash"] != after["bgm_semantic_hash"]
    scene_mapping: dict[str, Any] = {"targets": [], "changed_lines": [], "matched_scores": []}
    if scope in {"unchanged", "metadata_or_format", "cta_only", "cover_only"}:
        scene_targets: list[str] = []
    elif scope in {"opening_only", "opening_and_cta"}:
        scene_targets = ["s_01.png"]
    elif scope == "scene_local":
        scene_mapping = changed_core_scene_targets(project_id, before["core_lines"], after["core_lines"])
        scene_targets = list(scene_mapping.get("targets") or [])
    else:
        scene_targets = ["all"]
    invalidate = {
        "content_analysis": scope != "unchanged",
        "audio": speech_changed,
        "subtitles": speech_changed,
        "scene_plan": speech_changed,
        "scene_images": scene_targets,
        "covers": cover_changed,
        "bgm": bgm_changed,
        "video": speech_changed or cover_changed or bgm_changed or bool(scene_targets),
    }
    labels = {
        "unchanged": "内容未变",
        "metadata_or_format": "仅格式或非生产字段变化",
        "cover_only": "仅封面语义变化",
        "cta_only": "仅结尾互动变化",
        "opening_only": "仅开场变化",
        "opening_and_cta": "开场与结尾变化",
        "scene_local": "局部正文变化",
        "full_script": "整稿语义变化",
    }
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "scope": scope,
        "scope_label": labels.get(scope, scope),
        "invalidate": invalidate,
        "scene_mapping": scene_mapping,
        "before": {key: before[key] for key in ("speech_hash", "opening_hash", "cta_hash", "core_hash", "topic_hash", "viewpoint_hash", "cover_hash", "bgm_semantic_hash")},
        "after": {key: after[key] for key in ("speech_hash", "opening_hash", "cta_hash", "core_hash", "topic_hash", "viewpoint_hash", "cover_hash", "bgm_semantic_hash")},
    }


def sanitize_tts_delivery_text(text: str, topic: str) -> str:
    output_language = "en-US" if content_lines_use_english([text]) else "zh-CN"
    output: list[str] = []
    spoken_count = 0
    for raw in str(text or "").splitlines():
        line = strip_spoken_line_for_tts(raw)
        if not line:
            continue
        if any(token in line for token in WEAK_SCRIPT_OUTRO_TOKENS):
            continue
        if any(token in line for token in WEAK_SCRIPT_CTA_TOKENS) and not any(token in line for token in INTERACTION_SIGNAL_TOKENS):
            continue
        spoken_count += 1
        if spoken_count <= 3:
            line, _hits = strip_weak_opening_prefix(line)
        if line:
            output.append(line)
    output, _duplicate_interaction_count = dedupe_terminal_interaction_lines(output)
    if not output:
        output.append(interaction_line_for_topic(topic, output_language))
    if output and not any(is_explicit_interaction_cta(item) for item in output[-6:]):
        output.append(interaction_line_for_topic(topic, output_language))
        output, _removed_after_append = dedupe_terminal_interaction_lines(output)
    return "\n".join(output).strip()


def enhance_script_section_rhythm(script: str, topic: str, mode: str) -> tuple[str, dict[str, Any]]:
    if mode == "article":
        return script, {"changed": False, "split_count": 0, "bridge_count": 0, "interaction_added": False}
    output_language = "en-US" if content_lines_use_english([script]) else "zh-CN"
    output: list[str] = []
    split_count = 0
    bridge_count = 0
    plain_gap = 0
    bridge_index = 0
    last_speaker = "主播"

    def emit_spoken_segments(speaker_name: str, spoken_text: str, prefix_text: str = "") -> None:
        nonlocal split_count, bridge_count, plain_gap, bridge_index
        speaker = clean_text(speaker_name) or last_speaker
        spoken = clean_text(spoken_text)
        if not spoken:
            return
        segments = split_spoken_text_for_rhythm(spoken)
        if len(segments) > 1:
            split_count += len(segments) - 1
        for segment in segments:
            signal = rhythm_signal_for_line(segment, len(output), len(output) + 1)
            if signal == "explain":
                plain_gap += 1
            else:
                plain_gap = 0
            if plain_gap >= 4:
                bridge = rhythm_bridge_line(topic, bridge_index, output_language)
                output.append(format_rhythm_dialogue_line(speaker, bridge))
                bridge_count += 1
                bridge_index += 1
                plain_gap = 0
            line = format_rhythm_dialogue_line(speaker, segment)
            output.append(f"{prefix_text}{line}" if prefix_text else line)

    for raw in script.splitlines():
        original = raw.rstrip()
        stripped = original.strip()
        if not stripped:
            output.append(original)
            continue
        prefix = ""
        body = stripped
        if body.startswith(("- ", "* ")):
            prefix = body[:2]
            body = body[2:].strip()
        normalized = re.sub(r"\*\*(.*?)\*\*", r"\1", body).strip()
        parsed = parse_dialogue_speaker_line(normalized, max_speaker_len=18)
        if not parsed:
            if is_stage_direction_line(normalized) or normalized.startswith(("### ", "## ", "# ")) or is_script_marker_speaker(normalized, ""):
                output.append(original)
                plain_gap = 0
                continue
            if clean_text(normalized) and len(clean_text(normalized)) > 34 and re.search(r"[，。！？；：,.!?;:]", normalized):
                emit_spoken_segments(last_speaker, normalized, prefix)
                continue
            output.append(original)
            continue

        speaker = clean_text(parsed[0]) or last_speaker
        spoken = clean_text(parsed[1])
        last_speaker = speaker
        if not spoken:
            output.append(original)
            continue
        if is_stage_direction_line(spoken) or looks_like_visual_direction(spoken):
            output.append(original)
            plain_gap = 0
            continue
        emit_spoken_segments(speaker, spoken, prefix)

    output, interaction_removed = dedupe_terminal_interaction_lines(output)

    dialogue_parts: list[str] = []
    for line in output:
        parsed = parse_dialogue_speaker_line(line.strip().removeprefix("- ").removeprefix("* ").strip(), max_speaker_len=18)
        if parsed:
            dialogue_parts.append(parsed[1])
    dialogue_text = "\n".join(dialogue_parts)
    interaction_added = False
    tail = dialogue_text[-220:]
    needs_topic_callback = any(token in clean_text(topic) for token in ("自动续费", "扣费", "订阅", "免密", "支付")) and "扣费短信" not in tail
    has_explicit_interaction = any(is_explicit_interaction_cta(item) for item in dialogue_parts[-6:])
    if interaction_removed or needs_topic_callback or not has_explicit_interaction:
        output.append(
            format_rhythm_dialogue_line(
                last_speaker,
                interaction_line_for_topic(topic, output_language),
            )
        )
        interaction_added = True
        output, removed_after_append = dedupe_terminal_interaction_lines(output)
        interaction_removed += removed_after_append

    return "\n".join(output).strip(), {
        "changed": split_count > 0 or bridge_count > 0 or interaction_added or interaction_removed > 0,
        "split_count": split_count,
        "bridge_count": bridge_count,
        "interaction_added": interaction_added,
        "interaction_removed": interaction_removed,
    }


def enhance_content_rhythm(project_id: int, content: str | None = None, *, save: bool = True) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    original = content if content is not None else storage.get_content(project_id)
    if not clean_text(original):
        raise ValueError("当前项目还没有 content.md，无法做节奏增强。")
    before = script_rhythm_report(project_id, original)
    title = detect_script_section_title(original)
    script = extract_section(original, title, level=2)
    if not script:
        raise ValueError("没有找到可增强的脚本区块。")

    topic = clean_text(project.get("topic_name") or first_heading(original) or "")
    enhanced_script, edit_stats = enhance_script_section_rhythm(script, topic, mode)
    enhanced = replace_section(original, title, enhanced_script, level=2)
    enhanced = compact_content_meta(enhanced)
    enhanced, bad_phrase_hits = repair_script_bad_phrases_text(enhanced, topic, mode)
    if enhanced != original:
        enhanced = refresh_content_image_prompts(project, template, enhanced)
    summary = summarize_content(enhanced, mode)
    after = script_rhythm_report(project_id, enhanced)
    report = {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "section": title,
        "changed": enhanced != original,
        "edits": edit_stats,
        "bad_phrase_repair": bad_phrase_hits,
        "before": {
            "score": before.get("score"),
            "metrics": before.get("metrics", {}),
            "issues": before.get("issues", []),
        },
        "after": {
            "score": after.get("score"),
            "metrics": after.get("metrics", {}),
            "issues": after.get("issues", []),
        },
    }

    report_path = storage.save_report(project_id, "script_rhythm_enhance", report)
    if save and enhanced != original:
        storage.save_content(project_id, enhanced)
        save_spoken_script_manifest(project_id, enhanced)
        prompt_manifest = save_visual_prompt_manifest(project_id, enhanced)
        summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
        summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
        storage.save_summary(project_id, summary)
        storage.save_report(project_id, "script_rhythm", after)
        mark_image_review_dirty(project_id, "文案节奏已增强，图片提示词已跟随口播重建，图片需要重新确认")
    return {
        "ok": True,
        "content": enhanced,
        "summary": summary,
        "report_path": str(report_path),
        "result": report,
        "rhythm": after,
    }


def compress_content_to_retention_budget(
    project_id: int,
    content: str | None = None,
    *,
    save: bool = True,
) -> dict[str, Any]:
    """Remove the weakest spoken beats until the channel duration target is met."""
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    original = content if content is not None else storage.get_content(project_id)
    retention = retention_duration_profile(project, template)
    before_units, before_duration = estimate_spoken_duration_sec(original, mode)
    target_sec = float(retention.get("target_sec") or 0)
    maximum_sec = float(retention.get("maximum_sec") or 0)
    if (
        not clean_text(original)
        or not retention.get("enabled")
        or not maximum_sec
        or before_duration <= maximum_sec
    ):
        return {
            "ok": True,
            "changed": False,
            "content": original,
            "before_duration_sec": before_duration,
            "after_duration_sec": before_duration,
            "target_sec": target_sec,
            "removed_lines": [],
        }

    title = detect_script_section_title(original)
    script = extract_section(original, title, level=2)
    raw_lines = script.splitlines()
    entries: list[dict[str, Any]] = []
    for raw_index, raw in enumerate(raw_lines):
        stripped = raw.strip().removeprefix("- ").removeprefix("* ").strip()
        parsed = parse_dialogue_speaker_line(stripped, max_speaker_len=18)
        if not parsed:
            continue
        spoken = clean_text(parsed[1])
        if not spoken or is_stage_direction_line(spoken) or looks_like_visual_direction(spoken):
            continue
        entries.append(
            {
                "raw_index": raw_index,
                "spoken": spoken,
                "signal": rhythm_signal_for_line(spoken, len(entries), max(1, len(raw_lines))),
            }
        )
    if len(entries) <= 5:
        return {
            "ok": True,
            "changed": False,
            "content": original,
            "before_duration_sec": before_duration,
            "after_duration_sec": before_duration,
            "target_sec": target_sec,
            "removed_lines": [],
        }

    english_mode = content_lines_use_english([str(item["spoken"]) for item in entries])

    def spoken_units(text: str) -> int:
        if english_mode:
            return len(re.findall(r"\b[A-Za-z0-9][A-Za-z0-9'-]*\b", text))
        return len(re.sub(r"[\s，。！？；：、“”‘’（）()《》【】…—,.!?;:'\"-]+", "", text))

    # Leave a small safety margin below the hard maximum. Reaching the exact
    # editorial target is desirable, but deleting another complete evidence
    # beat merely to shave a few seconds would make the script worse.
    fit_sec = max(target_sec, maximum_sec - 4)
    target_units = max(1, int(fit_sec * (2.45 if english_mode else 4.8)))
    current_units = sum(spoken_units(str(item["spoken"])) for item in entries)
    explicit_cta_indexes = [
        index for index, item in enumerate(entries) if is_explicit_interaction_cta(str(item["spoken"]))
    ]
    protected_indexes = {0, 1, len(entries) - 1}
    if explicit_cta_indexes:
        protected_indexes.add(explicit_cta_indexes[-1])
    for index, item in enumerate(entries):
        spoken = str(item["spoken"])
        if (
            index >= len(entries) // 2
            and item.get("signal") in {"turn", "push"}
            and spoken_units(spoken) >= (12 if english_mode else 24)
        ):
            protected_indexes.add(index)

    generic_bridge_tokens = (
        "先别急",
        "真正容易忽略",
        "这种矛盾",
        "不觉得这本身",
        "you might be wondering",
        "here is the thing",
        "the real point",
    )

    def keep_score(index: int, item: dict[str, Any]) -> tuple[int, int]:
        spoken = str(item["spoken"])
        lowered = spoken.casefold()
        score = 0
        if index in protected_indexes:
            score += 100
        signal = clean_text(str(item.get("signal") or ""))
        score += {"hook": 50, "case": 32, "turn": 28, "push": 24, "interaction": 55}.get(signal, 0)
        if re.search(r"\d", spoken):
            score += 28
        if len(re.findall(r"\b[A-Z][A-Za-z0-9.-]{2,}\b", spoken)) >= 1:
            score += 18
        if any(token in lowered for token in generic_bridge_tokens):
            score -= 35
        return score, -spoken_units(spoken)

    removed_entry_indexes: set[int] = set()
    candidates = sorted(
        (
            (keep_score(index, item), index, item)
            for index, item in enumerate(entries)
            if index not in protected_indexes
        ),
        key=lambda value: value[0],
    )
    minimum_lines = max(6, min(10, len(entries) // 2))
    for _rank, index, item in candidates:
        if current_units <= target_units or len(entries) - len(removed_entry_indexes) <= minimum_lines:
            break
        removed_entry_indexes.add(index)
        current_units -= spoken_units(str(item["spoken"]))

    if current_units > target_units:
        fallback_candidates = sorted(
            (
                (keep_score(index, item), index, item)
                for index, item in enumerate(entries)
                if index not in removed_entry_indexes and index not in {0, explicit_cta_indexes[-1] if explicit_cta_indexes else -1}
            ),
            key=lambda value: value[0],
        )
        for _rank, index, item in fallback_candidates:
            if current_units <= target_units or len(entries) - len(removed_entry_indexes) <= 5:
                break
            removed_entry_indexes.add(index)
            current_units -= spoken_units(str(item["spoken"]))

    removed_raw_indexes = {entries[index]["raw_index"] for index in removed_entry_indexes}
    compacted_lines: list[str] = []
    previous_blank = False
    for raw_index, raw in enumerate(raw_lines):
        if raw_index in removed_raw_indexes:
            continue
        is_blank = not raw.strip()
        if is_blank and previous_blank:
            continue
        compacted_lines.append(raw)
        previous_blank = is_blank
    compacted_script = "\n".join(compacted_lines).strip()
    compacted = replace_section(original, title, compacted_script, level=2)
    compacted = compact_content_meta(compacted)
    compacted, _bad_phrase_hits = repair_script_bad_phrases_text(
        compacted,
        clean_text(project.get("topic_name") or first_heading(compacted) or ""),
        mode,
    )
    after_units, after_duration = estimate_spoken_duration_sec(compacted, mode)
    if after_duration >= before_duration:
        return {
            "ok": True,
            "changed": False,
            "content": original,
            "before_duration_sec": before_duration,
            "after_duration_sec": before_duration,
            "target_sec": target_sec,
            "removed_lines": [],
        }

    compacted = refresh_content_image_prompts(project, template, compacted)
    removed_lines = [str(entries[index]["spoken"]) for index in sorted(removed_entry_indexes)]
    report = {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "changed": compacted != original,
        "before_units": before_units,
        "after_units": after_units,
        "before_duration_sec": before_duration,
        "after_duration_sec": after_duration,
        "target_sec": target_sec,
        "fit_sec": fit_sec,
        "maximum_sec": maximum_sec,
        "removed_lines": removed_lines,
    }
    storage.save_report(project_id, "retention_compression", report)
    if save and compacted != original:
        storage.save_content(project_id, compacted)
        save_spoken_script_manifest(project_id, compacted)
        prompt_manifest = save_visual_prompt_manifest(project_id, compacted)
        summary = summarize_content(compacted, mode)
        summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
        summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
        storage.save_summary(project_id, summary)
        storage.save_report(project_id, "script_rhythm", script_rhythm_report(project_id, compacted))
        mark_image_review_dirty(project_id, "文案已按频道时长预算压缩，仅受影响的配音、字幕和图片需要更新")
    return {"ok": True, "content": compacted, **report}


def video_quality_report(project_id: int) -> dict[str, Any]:
    issues: list[dict[str, Any]] = []
    audio_path = storage.project_file(project_id, "audio/podcast.mp3")
    subtitle_path = storage.project_file(project_id, "audio/subtitles.srt")
    video_path = storage.project_file(project_id, "releases/final-video.mp4")
    scene_paths = find_scene_image_paths(project_id)
    scene_status_payload = storage.scene_status(project_id)
    scene_count = int(scene_status_payload.get("generated_count", 0) or len(scene_paths))
    audio_duration = safe_probe_duration(audio_path)
    video_duration = safe_probe_duration(video_path)
    subtitle_entries = load_srt_entries(subtitle_path) if subtitle_path.exists() else []
    project = storage.get_project(project_id)
    content = storage.get_content(project_id)
    spoken_dialogue = current_spoken_dialogue_payload(
        project_id,
        content,
        clean_text(str(project.get("template_mode") or "video")),
        clean_text(str(project.get("topic_name") or "")),
    )
    spoken_text = "\n".join(item["text"] for item in spoken_dialogue)
    subtitle_fidelity = subtitle_text_fidelity(spoken_text, subtitle_entries)
    expected_speech_hash = semantic_text_hash([item.get("text", "") for item in spoken_dialogue])
    subtitle_sync_manifest = storage.read_json(subtitle_sync_manifest_path(project_id), {})
    subtitle_sync_manifest = subtitle_sync_manifest if isinstance(subtitle_sync_manifest, dict) else {}
    subtitle_sync_status = "missing"
    if subtitle_path.exists() and audio_path.exists() and subtitle_sync_manifest:
        version_ok = int(subtitle_sync_manifest.get("version", 0) or 0) == SUBTITLE_SYNC_MANIFEST_VERSION
        speech_ok = clean_text(str(subtitle_sync_manifest.get("speech_hash") or "")) == expected_speech_hash
        audio_ok = clean_text(str(subtitle_sync_manifest.get("audio_hash") or "")) == production_file_hash(audio_path)
        subtitle_sync_status = "current" if version_ok and speech_ok and audio_ok else "stale"
    subtitle_end = subtitle_end_duration(subtitle_path) or 0.0
    expected_duration = 0.0
    if audio_path.exists():
        try:
            expected_duration = round(expected_video_duration(project_id, max(1, scene_count), audio_path, subtitle_path if subtitle_path.exists() else None), 3)
        except (ValueError, TypeError, OSError):
            expected_duration = audio_duration

    if not audio_path.exists():
        issues.append(quality_issue("risk", "音频", "缺少 podcast.mp3。", "先生成配音。"))
    if not subtitle_path.exists():
        issues.append(quality_issue("warn", "字幕", "缺少 subtitles.srt。", "先生成或重新对齐字幕。"))
    elif audio_path.exists() and subtitle_sync_status != "current":
        has_voice_manifest = tts_voice_manifest_path(project_id).exists()
        severity = "risk" if subtitle_sync_status == "stale" or has_voice_manifest else "warn"
        detail = (
            "字幕未记录对应的配音版本，当前无法确认是否与音频同步。"
            if subtitle_sync_status == "missing"
            else "字幕对应的口播稿或音频哈希已变化，当前字幕不是这版配音生成的。"
        )
        issues.append(
            quality_issue(
                severity,
                "字幕与配音版本",
                detail,
                "重新生成字幕；系统会使用本次 TTS 口播稿并按实际 ASR 时间重新对齐。",
            )
        )
    if not video_path.exists():
        issues.append(quality_issue("risk", "成片", "缺少 final-video.mp4。", "先合成成片。"))
    if audio_duration > 0 and video_duration > 0:
        delta = round(video_duration - audio_duration, 3)
        tolerance = video_duration_tolerance_seconds(audio_duration)
        if abs(delta) > tolerance:
            issues.append(quality_issue("risk", "时长", f"视频和音频时长差异 {delta:+.1f}s。", "重新按音频时长合成视频，避免后半段黑屏或无声。"))
    if audio_duration > 0 and subtitle_entries:
        coverage = subtitle_coverage_ratio(subtitle_entries, int(audio_duration * 1000))
        if coverage < 0.96:
            issues.append(quality_issue("warn", "字幕覆盖", f"字幕只覆盖音频约 {coverage * 100:.0f}%。", "重新 ASR 或字幕对齐，确保尾段不丢字幕。"))
        if subtitle_end > audio_duration + 3:
            issues.append(quality_issue("warn", "字幕时轴", "字幕结束时间明显超过音频。", "重新对齐字幕，避免字幕延迟或错位。"))
        if subtitle_fidelity.get("suspicious_math"):
            issues.append(
                quality_issue(
                    "risk",
                    "字幕文字",
                    "字幕出现口播稿中不存在的算式：" + "、".join(subtitle_fidelity["suspicious_math"][:5]),
                    "重新生成字幕，并锁定使用最终 TTS 口播文本。",
                )
            )
        elif float(subtitle_fidelity.get("ratio", 0) or 0) < 0.94:
            issues.append(
                quality_issue(
                    "risk",
                    "字幕文字",
                    f"字幕与最终口播稿文字一致度只有 {float(subtitle_fidelity.get('ratio', 0) or 0) * 100:.0f}%。",
                    "保留 ASR 时间轴，但用最终 TTS 文本重建字幕。",
                )
            )
    else:
        coverage = 0.0

    timeline = storage.read_json(storage.project_file(project_id, "audio/scene_timeline.json"), {})
    timeline_scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
    if isinstance(timeline_scenes, list) and timeline_scenes and scene_count and len(timeline_scenes) != scene_count:
        issues.append(quality_issue("warn", "场景时轴", f"时轴 {len(timeline_scenes)} 段，场景图 {scene_count} 张。", "重新生成字幕/场景图时轴，保持段数一致。"))

    score = quality_score_from_issues(issues)
    return {
        "score": score,
        "verdict": quality_verdict(score),
        "metrics": {
            "audio_exists": audio_path.exists(),
            "subtitle_exists": subtitle_path.exists(),
            "video_exists": video_path.exists(),
            "audio_duration_sec": audio_duration,
            "video_duration_sec": video_duration,
            "expected_duration_sec": expected_duration,
            "subtitle_end_sec": round(subtitle_end, 3),
            "subtitle_count": len(subtitle_entries),
            "subtitle_coverage": round(coverage, 4),
            "subtitle_text_fidelity": subtitle_fidelity,
            "subtitle_voice_sync": subtitle_sync_status,
            "scene_count": scene_count,
            "timeline_scene_count": len(timeline_scenes) if isinstance(timeline_scenes, list) else 0,
        },
        "issues": issues,
    }


def _project_asset_url(project_id: int, path: Path) -> str:
    try:
        rel = path.relative_to(storage.project_dir(project_id)).as_posix()
    except ValueError:
        rel = path.name
    return f"/data/projects/{project_id}/{rel}"


def _project_status_item(key: str, label: str, status: str, detail: str = "", action: str = "") -> dict[str, str]:
    return {
        "key": key,
        "label": label,
        "status": status,
        "detail": detail,
        "action": action,
    }


def production_stability_summary(project_id: int, limit: int = 20) -> dict[str, Any]:
    history = storage.list_job_history(project_id, limit=limit)
    if not history:
        latest = storage.load_latest_job(project_id)
        history = [latest] if isinstance(latest, dict) and latest.get("id") else []
    terminal = [
        item
        for item in history
        if clean_text(str(item.get("status") or "")) in {"succeeded", "failed", "cancelled", "interrupted"}
    ]
    succeeded = [item for item in terminal if clean_text(str(item.get("status") or "")) == "succeeded"]
    recovered_jobs = 0
    automatic_retry_count = 0
    durations: list[float] = []
    for item in terminal:
        retry_count = sum(
            int(progress.get("auto_retry_count", 0) or 0)
            for progress in item.get("progress", [])
            if isinstance(progress, dict)
        )
        automatic_retry_count += retry_count
        if clean_text(str(item.get("status") or "")) == "succeeded" and (
            retry_count > 0 or item.get("resumed_from_job_id")
        ):
            recovered_jobs += 1
        started_at = float(item.get("started_at") or 0)
        finished_at = float(item.get("finished_at") or 0)
        if started_at > 0 and finished_at >= started_at:
            durations.append(finished_at - started_at)
    completion_rate = (len(succeeded) / len(terminal)) if terminal else None
    return {
        "sample_count": len(terminal),
        "success_count": len(succeeded),
        "completion_rate": round(completion_rate, 4) if completion_rate is not None else None,
        "completion_rate_percent": round(completion_rate * 100) if completion_rate is not None else None,
        "automatic_retry_count": automatic_retry_count,
        "recovered_job_count": recovered_jobs,
        "average_duration_seconds": round(sum(durations) / len(durations), 1) if durations else None,
        "label": (
            f"近 {len(terminal)} 次完成率 {round(completion_rate * 100)}%"
            if completion_rate is not None
            else "稳定性数据积累中"
        ),
    }


def project_status_report(project_id: int) -> dict[str, Any]:
    project = storage.get_project(project_id)
    brief = clean_text(storage.get_brief(project_id))
    content = clean_text(storage.get_content(project_id))
    scene_status_payload = storage.scene_status(project_id)
    image_review = image_review_status(project_id)
    video_quality = video_quality_report(project_id)
    audio_path = storage.project_file(project_id, "audio/podcast.mp3")
    subtitle_path = storage.project_file(project_id, "audio/subtitles.srt")
    final_video_path = storage.project_file(project_id, "releases/final-video.mp4")
    cover_enabled = project_cover_enabled(project_id)
    cover_paths = _cover_output_paths(project_id)
    bgm_status = project_bgm_status(project_id)
    bgm_path_value = clean_text(str(bgm_status.get("path") or ""))
    bgm_path = Path(bgm_path_value) if bgm_path_value else None
    video_mix_meta = storage.read_json(project_video_mix_meta_path(project_id), {})
    video_mix_current = bool(
        isinstance(video_mix_meta, dict)
        and clean_text(str(video_mix_meta.get("policy_version") or "")) == BGM_MIX_POLICY_VERSION
        and clean_text(str(video_mix_meta.get("visual_master_policy_version") or "")) == VISUAL_MASTER_POLICY_VERSION
    )
    audio_duration = safe_probe_duration(audio_path)
    subtitle_entries = load_srt_entries(subtitle_path) if subtitle_path.exists() else []
    subtitle_coverage = subtitle_coverage_ratio(subtitle_entries, int(audio_duration * 1000)) if audio_duration > 0 else 0.0
    subtitle_voice_sync = clean_text(str((video_quality.get("metrics") or {}).get("subtitle_voice_sync") or "missing"))
    subtitles_current = bool(subtitle_path.exists() and subtitle_coverage >= 0.96 and subtitle_voice_sync == "current")
    scene_expected = int(scene_status_payload.get("expected_count", 0) or 0)
    scene_generated = int(scene_status_payload.get("generated_count", 0) or 0)
    covers_generated = sum(1 for path in cover_paths if path.exists())
    pending_redraw_count = int(image_review.get("scene_pending_redraw", 0) or 0)
    images_current = bool(
        scene_expected > 0
        and scene_generated >= scene_expected
        and (not cover_enabled or covers_generated == len(cover_paths))
        and pending_redraw_count == 0
    )
    video_dependencies = [
        audio_path,
        subtitle_path,
        *_scene_output_paths(project_id),
        *(cover_paths if cover_enabled else []),
        *([bgm_path] if bgm_path else []),
    ]
    stale_video_inputs = [
        path
        for path in video_dependencies
        if final_video_path.exists() and path.exists() and path.stat().st_mtime > final_video_path.stat().st_mtime + 0.01
    ]
    bgm_newer_than_video = bool(bgm_path and bgm_path in stale_video_inputs)
    video_current = bool(
        final_video_path.exists()
        and int(video_quality.get("score", 0) or 0) >= 72
        and pending_redraw_count == 0
        and not bgm_status.get("needs_rematch")
        and not stale_video_inputs
        and video_mix_current
    )
    steps = [
        _project_status_item(
            "brief",
            "简报",
            "ok" if brief else "warn",
            "已填写 brief.md" if brief else "brief.md 还是空的",
            "先补齐主题、素材和频道要求。" if not brief else "",
        ),
        _project_status_item(
            "content",
            "文案",
            "ok" if content else "risk",
            "content.md 已生成" if content else "缺少 content.md",
            "先生成或粘贴文案。" if not content else "",
        ),
        _project_status_item(
            "audio",
            "音频",
            "ok" if audio_duration > 0 else "warn",
            f"podcast.mp3 {audio_duration:.1f}s" if audio_duration > 0 else "缺少 podcast.mp3",
            "先生成配音。" if audio_duration <= 0 else "",
        ),
        _project_status_item(
            "subtitles",
            "字幕",
            "ok" if subtitles_current else ("warn" if subtitle_path.exists() else "risk"),
            (
                f"{len(subtitle_entries)} 条，覆盖 {subtitle_coverage * 100:.0f}%"
                + ("，已绑定当前配音" if subtitle_voice_sync == "current" else "，未验证配音版本")
                if subtitle_path.exists()
                else "缺少 subtitles.srt"
            ),
            "重新生成字幕，按当前配音重新对齐。" if not subtitles_current else "",
        ),
        _project_status_item(
            "images",
            "图片",
            "ok" if images_current else "warn",
            (
                f"场景 {scene_generated}/{scene_expected or 0}，其中 {pending_redraw_count} 张待按新策略重绘"
                if pending_redraw_count
                else (
                    f"场景 {scene_generated}/{scene_expected or 0}，封面 {covers_generated}/{len(cover_paths)}"
                    if cover_enabled
                    else f"场景 {scene_generated}/{scene_expected or 0}，本期跳过封面"
                )
            ),
            (
                "按当前完整口播和视觉概念重绘旧策略图片。"
                if pending_redraw_count
                else (
                    ("补齐场景图和横屏/图文/竖屏封面。" if cover_enabled else "补齐场景图。")
                    if not images_current
                    else ""
                )
            ),
        ),
        _project_status_item(
            "image_review",
            "图片确认",
            "ok" if image_review.get("can_generate_video") else "warn",
            "已确认" if image_review.get("can_generate_video") else ("可确认，等待人工确认" if image_review.get("ready_to_confirm") else (f"{pending_redraw_count} 张旧策略图待重绘" if pending_redraw_count else "图片还未齐")),
            "重绘完成后重新确认图片，再合成成片。" if pending_redraw_count else ("确认图片后再合成成片。" if not image_review.get("can_generate_video") else ""),
        ),
        _project_status_item(
            "bgm",
            "背景音乐",
            "ok" if bgm_status.get("current") else "warn",
            (
                f"{bgm_status.get('label') or bgm_status.get('desired_label') or '自动匹配'}"
                + ("，人工锁定" if bgm_status.get("manual_locked") else "，跟随本期主题")
            ),
            (
                f"按本期主题重新匹配：{bgm_status.get('desired_reason') or '音乐画像需要更新。'}"
                if bgm_status.get("needs_rematch")
                else ""
            ),
        ),
        _project_status_item(
            "video",
            "成片",
            "ok" if video_current else ("warn" if final_video_path.exists() else "risk"),
            (
                "final-video.mp4 仍使用旧背景音乐"
                if bgm_newer_than_video
                else (
                    "final-video.mp4 仍使用旧混音方式"
                    if final_video_path.exists() and not video_mix_current
                    else (
                    f"final-video.mp4 已过期，等待 {pending_redraw_count} 张图重绘后重合成"
                    if final_video_path.exists() and pending_redraw_count
                    else (
                        "final-video.mp4 早于最新素材，需要重合成"
                        if final_video_path.exists() and stale_video_inputs
                        else (f"final-video.mp4，{video_quality.get('metrics', {}).get('video_duration_sec', 0)}s，{video_quality.get('score', 0)} 分" if final_video_path.exists() else "缺少 final-video.mp4")
                    )
                    )
                )
            ),
            (
                "新 BGM 已就绪，请重新合成视频。"
                if bgm_newer_than_video
                else ("使用新版人声侧链混音重新合成视频。" if final_video_path.exists() and not video_mix_current else ("图片重绘并确认后重新合成视频。" if pending_redraw_count else ("重新合成视频以使用最新素材。" if stale_video_inputs else ("运行成片自检，确认无黑屏、字幕覆盖和时长问题。" if final_video_path.exists() else "先合成视频。"))))
            ),
        ),
    ]
    steps = [item for item in steps if item.get("key") != "bgm"]
    status_rank = {"ok": 0, "info": 1, "warn": 2, "risk": 3}
    worst = max(steps, key=lambda item: status_rank.get(item["status"], 1)) if steps else None
    stability = production_stability_summary(project_id)
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": project.get("topic_name", ""),
        "overall_status": worst["status"] if worst else "ok",
        "ready_for_video": all(
            item["status"] == "ok"
            for item in steps
            if item.get("key") != "video"
        ),
        "ready_for_release": video_current and (not cover_enabled or covers_generated == len(cover_paths)),
        "steps": steps,
        "metrics": {
            "audio_duration_sec": audio_duration,
            "subtitle_coverage": round(subtitle_coverage, 4),
            "scene_expected": scene_expected,
            "scene_generated": scene_generated,
            "cover_enabled": cover_enabled,
            "cover_expected": len(cover_paths) if cover_enabled else 0,
            "cover_generated": covers_generated,
            "scene_pending_redraw": pending_redraw_count,
            "bgm_current": bool(bgm_status.get("current")),
            "bgm_label": bgm_status.get("label") or bgm_status.get("desired_label"),
            "video_mix_current": video_mix_current,
            "video_quality_score": video_quality.get("score", 0),
            "production_stability": stability,
        },
    }


def production_resume_plan(project_id: int) -> dict[str, Any]:
    content_state = storage.read_json(storage.project_file(project_id, "content_generate.json"), {})
    content_state = content_state if isinstance(content_state, dict) else {}
    content_status = clean_text(str(content_state.get("status") or "idle")).lower()
    content_text = storage.get_content(project_id).strip()
    if content_status == "running":
        stage = clean_text(str(content_state.get("stage") or "write")) or "write"
        return {
            "generated_at": storage.now_ts(),
            "project_id": project_id,
            "recommended_steps": [],
            "can_resume": False,
            "blocked_stage": "content_generation",
            "content_generation": content_state,
            "reasons": [
                f"文案正在生成（{stage}），完成后全自动任务会直接进入配音、字幕、图片和成片流程；当前无需另开生产任务。"
            ],
            "phase_message": "文案生成中，生产续跑已自动排队。",
        }
    if not content_text:
        return {
            "generated_at": storage.now_ts(),
            "project_id": project_id,
            "recommended_steps": [],
            "can_resume": False,
            "blocked_stage": "content_missing",
            "content_generation": content_state,
            "reasons": ["当前文案为空，请先完成文案生成；正文写入后再计算配音、字幕、图片和成片步骤。"],
            "phase_message": "等待 content.md 生成完成。",
        }
    scene_status_payload = storage.scene_status(project_id)
    audio_path = storage.project_file(project_id, "audio/podcast.mp3")
    subtitle_path = storage.project_file(project_id, "audio/subtitles.srt")
    final_video_path = storage.project_file(project_id, "releases/final-video.mp4")
    cover_enabled = project_cover_enabled(project_id)
    cover_paths = _cover_output_paths(project_id)
    image_review = image_review_status(project_id)
    bgm_status = project_bgm_status(project_id)
    bgm_path_value = clean_text(str(bgm_status.get("path") or ""))
    bgm_path = Path(bgm_path_value) if bgm_path_value else None
    video_mix_meta = storage.read_json(project_video_mix_meta_path(project_id), {})
    video_mix_current = bool(
        isinstance(video_mix_meta, dict)
        and clean_text(str(video_mix_meta.get("policy_version") or "")) == BGM_MIX_POLICY_VERSION
        and clean_text(str(video_mix_meta.get("visual_master_policy_version") or "")) == VISUAL_MASTER_POLICY_VERSION
    )
    scene_expected = int(scene_status_payload.get("expected_count", 0) or 0)
    scene_generated = int(scene_status_payload.get("generated_count", 0) or 0)
    cover_generated = sum(1 for path in cover_paths if path.exists())
    stale_scene_indexes = stale_scene_image_indexes(project_id) if scene_expected > 0 else []
    manifest = refresh_production_manifest(project_id)
    asset_states = {
        clean_text(str(item.get("key") or "")): clean_text(str(item.get("status") or ""))
        for item in manifest.get("assets", [])
        if isinstance(item, dict)
    }
    audio_stale = asset_states.get("audio") in {"stale", "missing", "partial"}
    subtitles_stale = asset_states.get("subtitles") in {"stale", "missing", "partial"}
    project = storage.get_project(project_id)
    content = storage.get_content(project_id)
    current_dialogue = current_spoken_dialogue_payload(
        project_id,
        content,
        clean_text(str(project.get("template_mode") or "video")),
        clean_text(str(project.get("topic_name") or "")),
    )
    expected_speech_hash = semantic_text_hash([item.get("text", "") for item in current_dialogue])
    subtitle_sync_manifest = storage.read_json(subtitle_sync_manifest_path(project_id), {})
    subtitle_sync_manifest = subtitle_sync_manifest if isinstance(subtitle_sync_manifest, dict) else {}
    subtitle_version_current = bool(
        subtitle_path.exists()
        and audio_path.exists()
        and int(subtitle_sync_manifest.get("version", 0) or 0) == SUBTITLE_SYNC_MANIFEST_VERSION
        and clean_text(str(subtitle_sync_manifest.get("speech_hash") or "")) == expected_speech_hash
        and clean_text(str(subtitle_sync_manifest.get("audio_hash") or "")) == production_file_hash(audio_path)
    )
    subtitle_sync_missing_or_stale = bool(subtitle_path.exists() and audio_path.exists() and not subtitle_version_current)
    subtitles_stale = subtitles_stale or subtitle_sync_missing_or_stale
    lineage_video_stale = asset_states.get("video") in {"stale", "missing", "partial"}
    video_input_paths = [
        audio_path,
        subtitle_path,
        storage.project_file(project_id, "audio/scene_timeline.json"),
        *_scene_output_paths(project_id),
        *(cover_paths if cover_enabled else []),
        *([bgm_path] if bgm_path else []),
    ]
    motion_env = runtime_env()
    motion_provider = clean_text(motion_env.get("VIDEO_PROVIDER") or "off").lower()
    motion_mode = clean_text(motion_env.get("VIDEO_MOTION_MODE") or "key_scenes").lower()
    motion_enabled = motion_provider not in {"", "off", "none", "disabled"} and motion_mode not in {"off", "none", "disabled"}
    motion_manifest = storage.read_json(project_motion_clip_manifest_path(project_id), {})
    motion_clip_paths = list(current_motion_clip_paths(project_id).values()) if motion_enabled else []
    motion_ready = bool(
        motion_enabled
        and isinstance(motion_manifest, dict)
        and motion_manifest.get("status") == "ready"
        and motion_clip_paths
    )
    motion_stale = bool(
        motion_enabled
        and (
            not motion_ready
            or any(
                scene_path.exists()
                and any(
                    clip_path.exists() and scene_path.stat().st_mtime > clip_path.stat().st_mtime + 0.01
                    for clip_path in motion_clip_paths
                )
                for scene_path in _scene_output_paths(project_id)
            )
        )
    )
    video_input_paths.extend(motion_clip_paths)
    video_older_than_inputs = bool(
        final_video_path.exists()
        and any(
            path.exists() and path.stat().st_mtime > final_video_path.stat().st_mtime + 0.01
            for path in video_input_paths
        )
    )
    final_video_stale = bool(
        final_video_path.exists()
        and (
            stale_scene_indexes
            or video_older_than_inputs
            or bgm_status.get("needs_rematch")
            or not video_mix_current
            or lineage_video_stale
            or motion_stale
        )
    )
    steps: list[str] = []
    reasons: list[str] = []

    if not audio_path.exists() or audio_stale:
        steps.extend(["audio", "subtitles"])
        reasons.append(
            "文案已经更新，旧配音含有过期内容，需要重新生成音频并重新对齐字幕。"
            if audio_path.exists()
            else "缺少配音，需要先生成音频并重新对齐字幕。"
        )
    elif not subtitle_path.exists() or subtitles_stale:
        steps.append("subtitles")
        reasons.append(
            "字幕未绑定到当前配音版本，需要重新按真实语音时间对齐。"
            if subtitle_sync_missing_or_stale
            else ("字幕早于当前口播，需要重新 ASR/对齐字幕。" if subtitle_path.exists() else "缺少字幕，需要重新 ASR/对齐字幕。")
        )

    if scene_expected <= 0:
        steps.extend(["subtitles", "images"])
        reasons.append("没有场景时轴或场景图计划，建议从字幕对齐后重建图片。")
    elif scene_generated < scene_expected:
        steps.append("images_missing")
        reasons.append(f"场景图缺失 {scene_generated}/{scene_expected}，建议只补缺失场景图。")
    elif stale_scene_indexes:
        steps.append("images_missing")
        reasons.append(
            f"已有场景图与最新口播分镜不一致（{', '.join(str(item) for item in stale_scene_indexes[:12])}），建议自动重绘这些图片。"
        )

    if cover_enabled and cover_generated < len(cover_paths):
        steps.append("covers_missing")
        reasons.append(f"封面缺失 {cover_generated}/{len(cover_paths)}，建议只补缺失封面。")

    if BGM_FEATURE_ENABLED and bgm_status.get("needs_rematch"):
        steps.append("bgm")
        reasons.append(
            f"背景音乐需要按本期主题更新：{bgm_status.get('desired_label') or '自动匹配'}；"
            f"{bgm_status.get('desired_reason') or '主题或文案已经变化。'}"
        )

    if motion_enabled and (
        (motion_stale and scene_generated >= scene_expected and not stale_scene_indexes)
        or "images_missing" in steps
    ):
        steps.append("motion_clips")
        reasons.append("场景图更新后，需要同步生成或复用首镜、核心证据和反转的动态镜头。")

    if not final_video_path.exists() or final_video_stale:
        if image_review.get("can_generate_video") and not stale_scene_indexes:
            steps.append("video")
            reasons.append("图片已确认，现有成片早于最新素材，需要重新合成。" if final_video_stale else "图片已确认但缺少成片，建议只合成视频。")
        elif stale_scene_indexes and image_review.get("required") is False and "images_missing" in steps:
            steps.append("video")
            reasons.append("全自动模式会先重绘受影响图片，再在同一任务中继续合成视频。")
        elif stale_scene_indexes:
            reasons.append("现有成片仍使用旧图片；先完成图片重绘并重新确认，再重新合成视频。")
        else:
            reasons.append("最新素材尚未确认，先确认图片后再重新合成视频。" if final_video_stale else "图片尚未确认，先确认图片后再合成视频。")

    ordered = []
    for step in steps:
        if step not in ordered:
            ordered.append(step)
    if not ordered and final_video_path.exists():
        reasons.append("当前产物完整，无需续跑；如要提升质量，可先做成片自检或单张重绘。")

    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "recommended_steps": ordered,
        "can_resume": bool(ordered),
        "reasons": reasons,
        "image_review": image_review,
        "scene_expected": scene_expected,
        "scene_generated": scene_generated,
        "cover_enabled": cover_enabled,
        "cover_expected": len(cover_paths) if cover_enabled else 0,
        "cover_generated": cover_generated,
        "final_video_exists": final_video_path.exists(),
        "final_video_stale": final_video_stale,
    }


def _video_self_check_sample_times(duration: float) -> list[float]:
    if duration <= 0:
        return []
    raw = [3.0, duration * 0.18, duration * 0.34, duration * 0.50, duration * 0.66, duration * 0.82, max(1.0, duration - 8.0), max(1.0, duration - 2.0)]
    samples: list[float] = []
    for value in raw:
        safe = max(0.5, min(duration - 0.2, float(value)))
        if not any(abs(safe - existing) < 1.5 for existing in samples):
            samples.append(round(safe, 2))
    return samples[:8]


def _make_frame_contact_sheet(frame_paths: list[Path], target_path: Path) -> None:
    if Image is None or not frame_paths:
        return
    thumbs = []
    for path in frame_paths:
        try:
            with Image.open(path) as image:
                thumb = image.convert("RGB")
                thumb.thumbnail((360, 203))
                canvas = Image.new("RGB", (360, 203), "#101827")
                canvas.paste(thumb, ((360 - thumb.width) // 2, (203 - thumb.height) // 2))
                thumbs.append(canvas)
        except (OSError, ValueError):
            continue
    if not thumbs:
        return
    cols = 2
    rows = math.ceil(len(thumbs) / cols)
    sheet = Image.new("RGB", (cols * 360, rows * 203), "#101827")
    for index, thumb in enumerate(thumbs):
        sheet.paste(thumb, ((index % cols) * 360, (index // cols) * 203))
    storage.ensure_dir(target_path.parent)
    sheet.save(target_path, quality=90)


def run_video_self_check(project_id: int) -> dict[str, Any]:
    video_path = storage.project_file(project_id, "releases/final-video.mp4")
    audio_path = storage.project_file(project_id, "audio/podcast.mp3")
    subtitle_path = storage.project_file(project_id, "audio/subtitles.srt")
    reports_dir = storage.project_file(project_id, "reports")
    frames_dir = reports_dir / "video-self-check-frames"
    storage.ensure_dir(frames_dir)
    issues: list[dict[str, Any]] = []
    frame_records: list[dict[str, Any]] = []
    black_segments: list[dict[str, float]] = []

    audio_duration = safe_probe_duration(audio_path)
    video_duration = safe_probe_duration(video_path)
    subtitle_entries = load_srt_entries(subtitle_path) if subtitle_path.exists() else []
    subtitle_end = subtitle_end_duration(subtitle_path) or 0.0
    subtitle_coverage = subtitle_coverage_ratio(subtitle_entries, int(audio_duration * 1000)) if audio_duration > 0 else 0.0
    timeline = storage.read_json(storage.project_file(project_id, "audio/scene_timeline.json"), {})
    timeline_scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
    scene_count = len(find_scene_image_paths(project_id))

    if not video_path.exists():
        issues.append(quality_issue("risk", "成片", "缺少 final-video.mp4。", "先完成成片合成。"))
    if audio_duration > 0 and video_duration > 0:
        delta = round(video_duration - audio_duration, 3)
        if abs(delta) > video_duration_tolerance_seconds(audio_duration):
            issues.append(quality_issue("risk", "时长", f"视频与音频差异 {delta:+.1f}s。", "重新按音频时长合成。"))
    if subtitle_entries and audio_duration > 0:
        if subtitle_coverage < 0.96:
            issues.append(quality_issue("warn", "字幕覆盖", f"字幕覆盖约 {subtitle_coverage * 100:.0f}%。", "重新 ASR 或字幕对齐。"))
        if audio_duration - subtitle_end > 3:
            issues.append(quality_issue("warn", "字幕尾段", f"字幕比音频提前结束 {audio_duration - subtitle_end:.1f}s。", "重新生成字幕。"))
        long_lines = []
        for entry in subtitle_entries:
            display = one_line_subtitle_display_text(str(entry.get("text") or ""))
            if len(display) > SUBTITLE_SINGLE_LINE_MAX_CHARS + 2:
                long_lines.append(entry)
        if len(long_lines) > max(5, len(subtitle_entries) * 0.18):
            issues.append(quality_issue("warn", "字幕过长", "较多单条字幕偏长，可能在横屏中压边。", "重跑字幕，让系统拆成更短的单行字幕。"))
    elif not subtitle_path.exists():
        issues.append(quality_issue("warn", "字幕", "缺少 subtitles.srt。", "先生成字幕。"))
    if isinstance(timeline_scenes, list) and timeline_scenes and scene_count and len(timeline_scenes) != scene_count:
        issues.append(quality_issue("warn", "场景时轴", f"时轴 {len(timeline_scenes)} 段，场景图 {scene_count} 张。", "重新生成 scene_timeline，保持段数一致。"))

    if video_path.exists() and video_duration > 0:
        for index, sample_time in enumerate(_video_self_check_sample_times(video_duration), start=1):
            frame_path = frames_dir / f"frame_{index:02d}_{int(sample_time * 1000)}ms.jpg"
            cmd = [
                str(ffmpeg_binary()),
                "-hide_banner",
                "-loglevel",
                "error",
                "-ss",
                f"{sample_time:.3f}",
                "-i",
                str(video_path),
                "-frames:v",
                "1",
                "-q:v",
                "2",
                "-y",
                str(frame_path),
            ]
            ok = False
            mean_luma = 0.0
            try:
                subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=45,
                    check=True,
                    **background_subprocess_kwargs(),
                )
                ok = frame_path.exists() and frame_path.stat().st_size > 0
                if ok and Image is not None and ImageStat is not None:
                    with Image.open(frame_path) as image:
                        gray = image.convert("L")
                        mean_luma = round(float(ImageStat.Stat(gray).mean[0]), 2)
                        if mean_luma < 8:
                            issues.append(quality_issue("risk", "抽帧黑屏", f"{sample_time:.1f}s 抽帧疑似黑屏。", "检查该时间点场景图和合成链路。"))
                        elif mean_luma < 24:
                            issues.append(quality_issue("warn", "抽帧偏暗", f"{sample_time:.1f}s 画面偏暗。", "考虑重绘该段图片或提升合成亮度。"))
            except Exception as exc:
                frame_records.append({"time_sec": sample_time, "ok": False, "error": str(exc)})
                continue
            frame_records.append(
                {
                    "time_sec": sample_time,
                    "ok": ok,
                    "mean_luma": mean_luma,
                    "file": str(frame_path.relative_to(storage.project_dir(project_id))) if ok else "",
                    "url": _project_asset_url(project_id, frame_path) if ok else "",
                }
            )

        contact_sheet_path = reports_dir / "final_video_frame_contact_sheet.jpg"
        _make_frame_contact_sheet([Path(storage.project_dir(project_id) / item["file"]) for item in frame_records if item.get("file")], contact_sheet_path)

        try:
            result = subprocess.run(
                [
                    str(ffmpeg_binary()),
                    "-hide_banner",
                    "-i",
                    str(video_path),
                    "-vf",
                    "blackdetect=d=0.8:pix_th=0.10",
                    "-an",
                    "-f",
                    "null",
                    "-",
                ],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=120,
                **background_subprocess_kwargs(),
            )
            black_log = (result.stderr or "") + "\n" + (result.stdout or "")
            for match in re.finditer(r"black_start:(?P<start>[\d.]+)\s+black_end:(?P<end>[\d.]+)\s+black_duration:(?P<duration>[\d.]+)", black_log):
                black_segments.append(
                    {
                        "start": round(float(match.group("start")), 3),
                        "end": round(float(match.group("end")), 3),
                        "duration": round(float(match.group("duration")), 3),
                    }
                )
            if black_segments:
                issues.append(quality_issue("risk", "黑屏检测", f"检测到 {len(black_segments)} 段黑屏。", "重新合成并检查对应图片/转场。"))
        except Exception as exc:
            issues.append(quality_issue("info", "黑屏检测", f"黑屏检测未完成：{exc}", "可稍后重新运行成片自检。"))
    else:
        contact_sheet_path = reports_dir / "final_video_frame_contact_sheet.jpg"

    score = quality_score_from_issues(issues)
    result = {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "score": score,
        "verdict": quality_verdict(score),
        "metrics": {
            "audio_duration_sec": audio_duration,
            "video_duration_sec": video_duration,
            "duration_delta_sec": round(video_duration - audio_duration, 3) if audio_duration and video_duration else 0,
            "subtitle_count": len(subtitle_entries),
            "subtitle_end_sec": round(subtitle_end, 3),
            "subtitle_coverage": round(subtitle_coverage, 4),
            "scene_count": scene_count,
            "timeline_scene_count": len(timeline_scenes) if isinstance(timeline_scenes, list) else 0,
            "sampled_frame_count": len(frame_records),
            "black_segment_count": len(black_segments),
        },
        "frames": frame_records,
        "black_segments": black_segments,
        "contact_sheet": str(contact_sheet_path.relative_to(storage.project_dir(project_id))) if contact_sheet_path.exists() else "",
        "contact_sheet_url": _project_asset_url(project_id, contact_sheet_path) if contact_sheet_path.exists() else "",
        "issues": issues,
    }
    storage.save_report(project_id, "video_self_check", result)
    return result


def release_checklist_report(project_id: int) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    summary = storage.get_summary(project_id)
    video_quality = video_quality_report(project_id)
    self_check = storage.get_report(project_id, "video_self_check") or {}
    final_video = storage.project_file(project_id, "releases/final-video.mp4")
    cover_paths = _cover_output_paths(project_id)
    title = clean_text(str(summary.get("publish_title") or summary.get("video_title") or project.get("topic_name") or ""))
    tags = clean_text(str(template.get("release_tags") or summary.get("release_tags") or ""))
    description = clean_text(str(summary.get("description") or summary.get("summary") or ""))
    issues: list[dict[str, Any]] = []
    checks: list[dict[str, Any]] = []

    def add(key: str, label: str, ok: bool, detail: str, fix: str = "", level: str = "warn") -> None:
        status = "ok" if ok else level
        checks.append({"key": key, "label": label, "status": status, "detail": detail, "fix": "" if ok else fix})
        if not ok:
            issues.append(quality_issue("risk" if level == "risk" else "warn", label, detail, fix))

    add("video", "成片文件", final_video.exists(), "final-video.mp4 已生成" if final_video.exists() else "缺少 final-video.mp4", "先合成成片。", "risk")
    cover_generated = sum(1 for path in cover_paths if path.exists())
    add("covers", "封面", cover_generated == len(cover_paths), f"封面 {cover_generated}/{len(cover_paths)}", "补齐横屏、图文、竖屏封面。", "risk")
    add("title", "发布标题", 8 <= len(title) <= 36, f"标题 {len(title)} 字：{title}", "把标题压到 8-36 字，保留明确痛点或反差。")
    add("tags", "发布标签", bool(tags), f"标签：{tags or '未填写'}", "在频道里配置 release_tags，或在投放页填写平台标签。")
    add("description", "发布描述", bool(description) or bool(title), "已有摘要/标题可用于发布描述" if description or title else "缺少发布描述素材", "补一个核心观点 + 互动问题。")
    add("video_quality", "成片质量", int(video_quality.get("score", 0) or 0) >= 72, f"成片质量 {video_quality.get('score', 0)} 分", "先修复质量总检里的成片问题。", "risk")
    self_score = int(self_check.get("score", 0) or 0)
    add("self_check", "成片自检", self_score >= 72, f"自检 {self_score or '未运行'} 分", "先运行“一键成片自检”，确认无黑屏、字幕和时长风险。")
    subtitle_coverage = float(video_quality.get("metrics", {}).get("subtitle_coverage", 0) or 0)
    add("subtitle", "字幕覆盖", subtitle_coverage >= 0.96, f"字幕覆盖 {subtitle_coverage * 100:.0f}%", "重新 ASR 或字幕对齐。")

    score = quality_score_from_issues(issues)
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": project.get("topic_name", ""),
        "score": score,
        "passed": not any(item.get("level") == "risk" for item in issues),
        "verdict": quality_verdict(score),
        "checks": checks,
        "issues": issues,
        "publish_assets": {
            "title": title,
            "tags": tags,
            "description": description,
            "final_video": str(final_video),
            "covers": [str(path) for path in cover_paths if path.exists()],
        },
    }


def quality_gate_source_hashes(project_id: int, brief: str, content: str) -> dict[str, str]:
    project = storage.get_project(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    references = storage.get_references(project_id)

    def value_hash(value: Any) -> str:
        encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8", errors="ignore")
        return hashlib.sha256(encoded).hexdigest()[:16]

    def path_group_hash(paths: list[Path]) -> str:
        payload = [(path.name, production_file_hash(path)) for path in sorted(paths, key=lambda item: item.name) if path.exists()]
        return value_hash(payload)

    return {
        "policy_version": "quality-sections-v1",
        "content_hash": visual_brief_source_hash(content),
        "brief_hash": value_hash(clean_text(brief)),
        "references_hash": value_hash(references),
        "project_hash": value_hash({"topic": project.get("topic_name"), "template": template_key, "mode": project.get("template_mode")}),
        "template_hash": value_hash(template),
        "audio_hash": production_file_hash(storage.project_file(project_id, "audio/podcast.mp3")),
        "subtitles_hash": production_file_hash(storage.project_file(project_id, "audio/subtitles.srt")),
        "visual_director_hash": production_file_hash(visual_director_path(project_id)),
        "visual_prompts_hash": production_file_hash(storage.project_file(project_id, "visual_prompt_manifest.json")),
        "scene_images_hash": path_group_hash(find_scene_image_paths(project_id)),
        "covers_hash": path_group_hash(_cover_output_paths(project_id)),
    }


def assemble_quality_gate_report(
    project_id: int,
    project: dict[str, Any],
    sections: dict[str, dict[str, Any]],
    source_hashes: dict[str, str],
    *,
    reused_sections: list[str] | None = None,
) -> dict[str, Any]:
    scores = [int(section.get("score", section.get("overall_score", 0)) or 0) for section in sections.values()]
    overall = min(scores) if scores else 0
    issue_actions = [
        item.get("fix") or item.get("issue")
        for section in sections.values()
        for item in section.get("issues", [])
        if isinstance(item, dict) and str(item.get("level") or "") in {"risk", "warn"} and (item.get("fix") or item.get("issue"))
    ]
    supervisor_actions = sections.get("supervisors", {}).get("next_actions", [])
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": project.get("topic_name", ""),
        "overall_score": overall,
        "verdict": quality_verdict(overall),
        "sections": sections,
        "next_actions": dedupe_clauses([*issue_actions, *supervisor_actions])[:8],
        "source_hashes": source_hashes,
        "reused_sections": list(reused_sections or []),
    }


def quality_gate_non_video_sections_current(
    project_id: int,
    report: dict[str, Any] | None,
    brief: str,
    content: str,
) -> bool:
    if not isinstance(report, dict) or not isinstance(report.get("sections"), dict):
        return False
    stored = report.get("source_hashes") if isinstance(report.get("source_hashes"), dict) else {}
    return bool(stored and stored == quality_gate_source_hashes(project_id, brief, content))


def refresh_quality_gate_video_section(
    project_id: int,
    report: dict[str, Any],
    brief: str,
    content: str,
) -> dict[str, Any]:
    required = {"content", "director", "images", "supervisors"}
    existing_sections = report.get("sections") if isinstance(report.get("sections"), dict) else {}
    if not required.issubset(existing_sections):
        return quality_gate_report(project_id, brief, content)
    sections = {
        key: value
        for key, value in existing_sections.items()
        if isinstance(value, dict)
    }
    sections["video"] = video_quality_report(project_id)
    project = storage.get_project(project_id)
    return assemble_quality_gate_report(
        project_id,
        project,
        sections,
        quality_gate_source_hashes(project_id, brief, content),
        reused_sections=sorted(required),
    )


def quality_gate_report(
    project_id: int,
    brief: str | None = None,
    content: str | None = None,
    *,
    prefer_ai: bool = True,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    brief_text = brief if brief is not None else storage.get_brief(project_id)
    content_text = content if content is not None else storage.get_content(project_id)
    references = storage.get_references(project_id)
    sections = {
        "content": content_quality_report(project, template, brief_text, content_text, references) if clean_text(content_text) else {
            "score": 0,
            "verdict": "还没有 content.md，无法检查文案。",
            "issues": [quality_issue("risk", "文案", "缺少 content.md。", "先生成或粘贴脚本。")],
            "metrics": {},
        },
        "director": visual_director_quality_report(project_id, content_text),
        "images": image_director_report(project_id, project, template, content_text),
        "video": video_quality_report(project_id),
        "supervisors": ai_supervisor_report(project_id, content_text, prefer_ai=prefer_ai),
    }
    return assemble_quality_gate_report(
        project_id,
        project,
        sections,
        quality_gate_source_hashes(project_id, brief_text, content_text),
    )


PLATFORM_RISK_REPLACEMENTS: tuple[tuple[str, str], ...] = (
    (r"稳赚不赔", "收益和风险都要看清"),
    (r"稳赚", "存在收益也存在风险"),
    (r"百分之百|百分百|100%", "大概率"),
    (r"绝对", "通常"),
    (r"一定会", "很可能会"),
    (r"一定能", "更有机会"),
    (r"一定", "通常"),
    (r"必然", "可能"),
    (r"肯定", "大概率"),
    (r"唯一", "一种重要的"),
    (r"保证", "尽量提高"),
    (r"最权威", "较有参考价值"),
    (r"内幕消息", "公开资料线索"),
    (r"治愈", "改善"),
    (r"治疗", "干预或处理"),
    (r"神药", "被热议的产品"),
    (r"吓进医院", "被吓得立刻去做检查"),
    (r"吓死人", "让人警惕"),
)


def platform_risk_hits(text: str) -> list[str]:
    source = clean_text(text)
    hits: list[str] = []
    for pattern, _replacement in PLATFORM_RISK_REPLACEMENTS:
        hits.extend(match.group(0) for match in re.finditer(pattern, source))
    return dedupe_clauses(hits)


def rewrite_platform_risk_text(text: str) -> tuple[str, list[str]]:
    rewritten = str(text or "")
    hits: list[str] = []
    for pattern, replacement in PLATFORM_RISK_REPLACEMENTS:
        matches = [match.group(0) for match in re.finditer(pattern, rewritten)]
        if matches:
            hits.extend(matches)
            rewritten = re.sub(pattern, replacement, rewritten)
    rewritten = re.sub(r"(通常|大概率|可能){2,}", r"\1", rewritten)
    rewritten = re.sub(r"很可能会会", "很可能会", rewritten)
    rewritten = re.sub(r"更有机会能", "更有机会", rewritten)
    return rewritten, dedupe_clauses(hits)


def save_project_content_bundle(
    project_id: int,
    content: str,
    *,
    image_dirty_reason: str = "",
    refresh_quality_report: bool = True,
) -> dict[str, Any]:
    project = storage.get_project(project_id)
    previous_content = storage.get_content(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    brief = storage.get_brief(project_id)
    references = storage.get_references(project_id)
    tavily_topic = storage.get_project_settings(project_id).get("tavily_topic", "general")
    canonical = canonicalize_project_content(
        project_id,
        content,
        brief=brief,
        references=references,
    )
    compacted_content = str(canonical.get("content") or content)
    bad_phrase_hits = list(canonical.get("bad_phrase_repair") or [])
    opening_repair = canonical.get("opening_repair") if isinstance(canonical.get("opening_repair"), dict) else {}
    normalized_content = (content_without_image_prompts(compacted_content) or compacted_content).rstrip() + "\n"
    change_impact = content_change_impact(project_id, previous_content, normalized_content)
    invalidation = change_impact.get("invalidate") if isinstance(change_impact.get("invalidate"), dict) else {}
    storage.save_content(project_id, normalized_content)
    spoken_script = save_spoken_script_manifest(project_id, normalized_content)
    fact_registry = save_episode_fact_registry(
        project_id,
        normalized_content,
        brief=brief,
        references=references,
        registry=canonical.get("fact_registry") if isinstance(canonical.get("fact_registry"), dict) else None,
    )
    opening_report = canonical.get("opening_novelty") if isinstance(canonical.get("opening_novelty"), dict) else opening_novelty_report(project_id, normalized_content)
    storage.write_json(storage.project_file(project_id, "opening_novelty.json"), opening_report)
    storage.write_json(storage.project_file(project_id, "content_change.json"), change_impact)
    prompt_manifest = save_visual_prompt_manifest(
        project_id,
        normalized_content,
        preserve_covers=not bool(invalidation.get("covers")),
    )
    summary = summarize_content(normalized_content, mode)
    summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
    summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
    artifacts = build_content_artifacts(project, template, brief, tavily_topic, references, normalized_content)
    storage.save_summary(project_id, summary)
    storage.write_json(storage.project_file(project_id, "content_strategy.json"), artifacts["strategy"])
    storage.write_json(storage.project_file(project_id, "content_audit.json"), artifacts["audit"])
    with contextlib.suppress(Exception):
        save_video_spec(project_id, normalized_content)
    storage.save_report(project_id, "topic_score", artifacts["strategy"]["topic_score"])
    storage.save_report(project_id, "viral_doctor", artifacts["audit"]["viral_doctor"])
    storage.save_report(project_id, "title_cover_ab", artifacts["audit"]["title_cover_ab"])
    if image_dirty_reason and (invalidation.get("scene_images") or invalidation.get("covers")):
        mark_image_review_dirty(project_id, image_dirty_reason)
    elif opening_repair.get("changed"):
        mark_image_review_dirty(project_id, "首句与频道近期内容重复，已改为本期独有切入；首镜图片需要重新确认")
    result: dict[str, Any] = {
        "content": normalized_content,
        "canonicalization": {
            "changed": bool(canonical.get("changed")),
            "actions": list(canonical.get("actions") or []),
            "opening_repair": canonical.get("opening_repair") or {},
            "opening_novelty": canonical.get("opening_novelty") or {},
            "numeric_consistency": canonical.get("numeric_consistency") or {},
        },
        "summary": summary,
        "visual_prompt_manifest": prompt_manifest,
        "visual_prompt_manifest_path": str(visual_prompt_manifest_path(project_id)),
        "opening_novelty": opening_report,
        "opening_repair": {
            "changed": bool(opening_repair.get("changed")),
            "replacement": opening_repair.get("replacement", ""),
        },
        "change_impact": change_impact,
        "numeric_consistency": canonical.get("numeric_consistency", {}),
        "fact_registry": fact_registry,
        "spoken_script": spoken_script,
    }
    if bad_phrase_hits:
        result["bad_phrase_repair"] = bad_phrase_hits
    if refresh_quality_report:
        report = quality_gate_report(project_id, brief=brief, content=normalized_content)
        report_path = storage.save_report(project_id, "quality_gate", report)
        result.update(
            {
                "quality_gate": report,
                "report_path": str(report_path),
            }
        )
    return result


def repair_project_platform_risk(project_id: int, content: str | None = None) -> dict[str, Any]:
    original_content = content if content is not None else storage.get_content(project_id)
    lines = original_content.splitlines(keepends=True)
    repaired_lines: list[str] = []
    hits: list[str] = []
    excluded_section = False
    for line in lines:
        heading = re.match(r"^##[ \t]+(.+?)\s*$", line.strip("\r\n"))
        if heading:
            heading_title = clean_text(heading.group(1))
            excluded_section = any(heading_title.startswith(title) for title in ("图片提示词", "场景图提示词", "参考资料", "资料来源"))
        if excluded_section:
            repaired_lines.append(line)
            continue
        repaired_line, line_hits = rewrite_platform_risk_text(line)
        repaired_lines.append(repaired_line)
        hits.extend(line_hits)
    repaired_content = "".join(repaired_lines)
    hits = dedupe_clauses(hits)
    changed = repaired_content != original_content
    result: dict[str, Any] = {
        "ok": True,
        "changed": changed,
        "hits": hits,
        "content": repaired_content,
    }
    if changed:
        result.update(
            save_project_content_bundle(
                project_id,
                repaired_content,
                image_dirty_reason="content.md 已自动降敏平台风险词，图片提示词已同步重建，图片需要重新确认",
                refresh_quality_report=False,
            )
        )
    return result


FACT_COMPLIANCE_REPLACEMENTS: tuple[tuple[str, str], ...] = (
    (r"Apple\s*Watch|苹果手表", "某品牌智能手表"),
    (r"Withings", "某品牌健康手表"),
    (r"Garmin", "某运动手表"),
    (r"Fitbit", "某健康手环"),
    (r"FDA\s*(?:认证|批准|通过|许可)?", "公开监管资料"),
    (r"通过公开监管资料", "有公开监管资料"),
    (r"JMIR", "公开研究资料"),
    (r"临床(?:研究|试验)?(?:证明|证实)", "公开研究提示"),
    (r"权威研究", "公开资料"),
    (r"医疗级", "专业设备级"),
    (r"医学级", "专业设备级"),
    (r"医院级", "专业设备级"),
)


def fact_compliance_hits(text: str) -> list[str]:
    source = clean_text(text)
    hits: list[str] = []
    for pattern, _replacement in FACT_COMPLIANCE_REPLACEMENTS:
        hits.extend(match.group(0) for match in re.finditer(pattern, source, flags=re.IGNORECASE))
    return dedupe_clauses(hits)


def rewrite_fact_compliance_text(text: str) -> tuple[str, list[str]]:
    rewritten = str(text or "")
    hits: list[str] = []
    for pattern, replacement in FACT_COMPLIANCE_REPLACEMENTS:
        matches = [match.group(0) for match in re.finditer(pattern, rewritten, flags=re.IGNORECASE)]
        if matches:
            hits.extend(matches)
            rewritten = re.sub(pattern, replacement, rewritten, flags=re.IGNORECASE)
    boundary = "本期内容基于公开资料整理，只做科普参考，不替代医生判断；具体功能和适用范围以产品官方说明、专业设备和医生建议为准。"
    if any(term in clean_text(rewritten) for term in ("血氧", "心率", "健康", "医疗", "医生")) and boundary not in rewritten:
        if "## 参考资料" in rewritten:
            rewritten = rewritten.replace("## 参考资料", f"## 资料边界\n{boundary}\n\n## 参考资料", 1)
        else:
            rewritten = rewritten.rstrip() + f"\n\n## 资料边界\n{boundary}\n"
        hits.append("资料边界")
    rewritten = re.sub(r"某品牌智能手表\s*某品牌智能手表", "某品牌智能手表", rewritten)
    return rewritten, dedupe_clauses(hits)


def repair_project_fact_compliance(project_id: int, content: str | None = None) -> dict[str, Any]:
    original_content = content if content is not None else storage.get_content(project_id)
    repaired_content, hits = rewrite_fact_compliance_text(original_content)
    # Numeric-source problems must remain visible to the gate. Token-level
    # substitutions can turn valid prose such as "每多等一次" into broken
    # Chinese, and then TTS/subtitles faithfully reproduce that damage.
    # A sourced rewrite must replace the complete claim; this rule repairer
    # therefore never mutates numbers, dates, durations, or their context.
    hits = dedupe_clauses(hits)
    changed = repaired_content != original_content
    result: dict[str, Any] = {
        "ok": True,
        "changed": changed,
        "hits": hits,
        "content": repaired_content,
    }
    if changed:
        result.update(
            save_project_content_bundle(
                project_id,
                repaired_content,
                image_dirty_reason="content.md 已自动修正事实合规风险，图片提示词已同步重建，图片需要重新确认",
                refresh_quality_report=False,
            )
        )
    return result


def creative_optimization_plan(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    content_text = content if content is not None else storage.get_content(project_id)
    has_content = bool(clean_text(content_text))
    quality = quality_gate_report(project_id, content=content_text) if has_content else {}
    rhythm = script_rhythm_report(project_id, content_text) if has_content else {}
    layers = image_prompt_layer_report(project_id, content_text) if has_content else {}
    resume = production_resume_plan(project_id)
    status = project_status_report(project_id)
    history = channel_history_report(project_id)
    image_review = image_review_status(project_id)
    release_check = storage.get_report(project_id, "release_checklist") or {}

    actions: list[dict[str, Any]] = []

    def add_action(key: str, label: str, reason: str, priority: int, *, action_type: str = "manual", payload: dict[str, Any] | None = None) -> None:
        actions.append(
            {
                "key": key,
                "label": label,
                "reason": reason,
                "priority": priority,
                "action_type": action_type,
                "payload": payload or {},
            }
        )

    if not has_content:
        add_action("generate_content", "先生成 content.md", "当前还没有脚本成稿，无法做后续生产判断。", 100, action_type="open_content")
    else:
        rhythm_score = int(rhythm.get("score", 0) or 0)
        opening_score = float(rhythm.get("engagement", {}).get("opening_score", 0) or 0)
        retention_score = float(rhythm.get("engagement", {}).get("retention_score", 0) or 0)
        interaction_score = float(rhythm.get("engagement", {}).get("interaction_score", 0) or 0)
        if rhythm_score < 86 or opening_score < CONTENT_OPENING_MIN_SCORE or retention_score < CONTENT_RETENTION_MIN_SCORE or interaction_score < CONTENT_INTERACTION_MIN_SCORE:
            add_action(
                "viral_rewrite",
                "执行总编优化",
                "节奏体检显示开头、中段或结尾还有提升空间，建议先改稿再出图。",
                95,
                action_type="viral_rewrite",
            )
        layer_score = int(layers.get("score", 0) or 0)
        weak_prompts = int(layers.get("metrics", {}).get("weak_prompt_count", 0) or 0)
        if layer_score < 82 or weak_prompts > 0:
            add_action(
                "repair_image_prompts",
                "重建图片提示词",
                f"图片提示词分层 {layer_score} 分，弱提示词 {weak_prompts} 条，建议先修提示词再生图。",
                88,
                action_type="repair_image_prompts",
            )

    recommended_steps = list(resume.get("recommended_steps") or [])
    if recommended_steps:
        add_action(
            "apply_resume_steps",
            "应用续跑步骤",
            "当前产物不完整，建议按续跑建议补齐缺失环节。",
            78,
            action_type="apply_resume_steps",
            payload={"steps": recommended_steps},
        )
    elif has_content and not recommended_steps:
        final_video = storage.project_file(project_id, "releases/final-video.mp4")
        if not final_video.exists() and image_review.get("can_generate_video"):
            add_action("open_produce", "去生产成片", "脚本与图片条件基本具备，可以进入成片合成。", 70, action_type="open_produce")
        elif not image_review.get("confirmed") and image_review.get("required"):
            add_action("confirm_images", "确认图片后成片", "当前开启了图片确认关卡，成片前需要先确认场景图和封面图。", 68, action_type="open_produce")
        elif final_video.exists():
            add_action("release_checklist", "做发布前检查", "成片已经存在，下一步建议检查封面、标题、标签和字幕风险。", 62, action_type="release_checklist")

    if not actions and has_content:
        add_action("ready", "可以继续生产/发布", "当前没有明显阻塞项，可按你的目标进入生产或投放。", 40, action_type="open_produce")

    actions.sort(key=lambda item: int(item.get("priority", 0) or 0), reverse=True)
    scores = [
        int(quality.get("overall_score", 100) or 100) if quality else 0,
        int(rhythm.get("score", 100) or 100) if rhythm else 0,
        int(layers.get("score", 100) or 100) if layers else 0,
    ]
    overall = min(scores) if scores else 0
    if not has_content:
        overall = 0
    return {
        "generated_at": storage.now_ts(),
        "project_id": project_id,
        "topic": project.get("topic_name", ""),
        "score": overall,
        "verdict": quality_verdict(overall),
        "summary": {
            "quality_score": quality.get("overall_score", 0) if quality else 0,
            "rhythm_score": rhythm.get("score", 0) if rhythm else 0,
            "image_layer_score": layers.get("score", 0) if layers else 0,
            "history_count": history.get("history_count", 0),
            "release_metrics_count": history.get("with_release_metrics_count", 0),
            "ready_for_video": status.get("ready_for_video", False),
            "ready_for_release": status.get("ready_for_release", False),
        },
        "actions": actions[:8],
        "reports": {
            "quality_gate": quality,
            "rhythm": rhythm,
            "image_layers": layers,
            "resume_plan": resume,
            "project_status": status,
            "channel_history": {
                "recommendations": history.get("recommendations", []),
                "best_hooks": history.get("best_hooks", [])[:3],
                "top_keywords": history.get("top_keywords", [])[:6],
            },
            "release_checklist": release_check,
        },
    }


def repair_image_prompt_section(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    brief = storage.get_brief(project_id)
    references = storage.get_references(project_id)
    tavily_topic = storage.get_project_settings(project_id).get("tavily_topic", "general")
    original_content = content if content is not None else storage.get_content(project_id)
    editorial_content = content_without_image_prompts(original_content) or original_content
    old_scene_prompts = visual_prompt_manifest_scene_prompts(project_id, original_content) or parse_scene_prompts(original_content, mode)
    old_similarity = prompt_similarity_score(old_scene_prompts)
    new_scene_prompts = build_content_scene_prompt_lines(project, template, editorial_content)
    timeline_path = storage.project_file(project_id, "audio/scene_timeline.json")
    timeline = storage.read_json(timeline_path, {}) if timeline_path.exists() else {}
    timeline_scenes_for_count = timeline.get("scenes") if isinstance(timeline, dict) else []
    if isinstance(timeline_scenes_for_count, list) and timeline_scenes_for_count and new_scene_prompts:
        new_scene_prompts = normalize_scene_prompt_count(
            new_scene_prompts,
            len(timeline_scenes_for_count),
            clean_text(str(project.get("topic_name") or "")),
            mode,
        )
    new_similarity = prompt_similarity_score(new_scene_prompts)
    changed = old_scene_prompts != new_scene_prompts
    prompt_manifest = save_visual_prompt_manifest(
        project_id,
        editorial_content,
        scene_lines_override=new_scene_prompts,
    )
    summary = summarize_content(editorial_content, mode)
    summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
    summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
    storage.save_summary(project_id, summary)
    artifacts = build_content_artifacts(project, template, brief, tavily_topic, references, editorial_content)
    storage.write_json(storage.project_file(project_id, "content_strategy.json"), artifacts["strategy"])
    storage.write_json(storage.project_file(project_id, "content_audit.json"), artifacts["audit"])
    storage.save_report(project_id, "topic_score", artifacts["strategy"]["topic_score"])
    storage.save_report(project_id, "viral_doctor", artifacts["audit"]["viral_doctor"])
    storage.save_report(project_id, "title_cover_ab", artifacts["audit"]["title_cover_ab"])
    timeline_refreshed = False
    scene_plan: dict[str, Any] = {}
    if isinstance(timeline, dict) and isinstance(timeline.get("scenes"), list) and new_scene_prompts:
        timeline_scenes = timeline.get("scenes") or []
        aligned_prompts = normalize_scene_prompt_count(
            new_scene_prompts,
            len(timeline_scenes),
            clean_text(str(project.get("topic_name") or "")),
            mode,
        )
        for index, scene in enumerate(timeline_scenes):
            if isinstance(scene, dict) and index < len(aligned_prompts):
                scene["prompt"] = aligned_prompts[index]
        timeline["scenes"] = timeline_scenes
        storage.write_json(timeline_path, timeline)
        timeline_refreshed = True
        with contextlib.suppress(Exception):
            scene_plan = write_scene_plan(project_id, project, editorial_content, timeline, aligned_prompts)
    elif new_scene_prompts:
        with contextlib.suppress(Exception):
            visual_brief = save_visual_brief(
                project_id,
                editorial_content,
                scene_count=len(new_scene_prompts),
                beats=new_scene_prompts,
            )
            save_visual_director(project_id, editorial_content, visual_brief=visual_brief)
    prompt_cache_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    if prompt_cache_path.exists():
        with contextlib.suppress(Exception):
            prompt_cache_path.unlink()
    mark_image_review_dirty(project_id, "图片提示词已按频道、主题和口播重新生成，图片需要重新确认")

    report = quality_gate_report(project_id, brief=brief, content=editorial_content)
    report_path = storage.save_report(project_id, "quality_gate", report)
    return {
        "ok": True,
        "changed": changed,
        "content": original_content,
        "summary": summary,
        "visual_prompt_manifest": prompt_manifest,
        "visual_prompt_manifest_path": str(visual_prompt_manifest_path(project_id)),
        "before": {
            "scene_prompt_count": len(old_scene_prompts),
            "prompt_similarity_max": old_similarity,
        },
        "after": {
            "scene_prompt_count": len(new_scene_prompts),
            "prompt_similarity_max": new_similarity,
            "timeline_refreshed": timeline_refreshed,
            "scene_plan_count": len(scene_plan.get("scenes", [])) if isinstance(scene_plan, dict) else 0,
        },
        "quality_gate": report,
        "report_path": str(report_path),
    }


def optimize_project_content(project_id: int, content: str | None = None) -> dict[str, Any]:
    project = storage.get_project(project_id)
    template_key = clean_text(project.get("template") or "")
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(project.get("template_mode") or template.get("mode") or "video")
    brief = storage.get_brief(project_id)
    original_content = content if content is not None else storage.get_content(project_id)
    if not clean_text(original_content):
        raise ValueError("当前项目还没有 content.md，先生成或粘贴文案。")

    before_engagement = content_engagement_report(original_content, mode)
    optimized_content = original_content
    provider = "no-op"
    deepseek_error = ""
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if api_key and OpenAI is not None:
        base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
        model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
        thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
        reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
        extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
        if thinking_type in {"enabled", "disabled"}:
            extra_body["thinking"] = {"type": thinking_type}
        try:
            rewrite_timeout = deepseek_rewrite_timeout_seconds(env)
            client = OpenAI(
                api_key=api_key,
                base_url=base_url,
                timeout=rewrite_timeout,
                max_retries=0,
            )
            messages = compose_deepseek_rewrite_messages(project, template, original_content, before_engagement)
            messages[0]["content"] = (
                str(messages[0].get("content") or "").strip()
                + "\n\n"
                + build_common_content_system_rules()
                + "\n\n"
                + build_viral_content_rules(project, template)
                + ("\n\n" + build_product_content_rules(project) if build_product_content_rules(project) else "")
                + "\n\n"
                + build_output_language_rules(project)
            )
            response = client.chat.completions.create(
                model=model,
                messages=messages,
                temperature=0.66,
                max_tokens=12000,
                extra_body=extra_body,
            )
            choice = response.choices[0] if getattr(response, "choices", None) else None
            rewritten = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
            rewritten = strip_code_fences(rewritten)
            rewritten = re.sub(r"(?is)^<think>.*?</think>\s*", "", rewritten).strip()
            if not rewritten.startswith("#"):
                raise ContentGenerationError("DeepSeek 返回内容不是完整 content.md。")
            optimized_content = rewritten
            provider = "deepseek"
        except Exception as exc:
            deepseek_error = str(exc)
            provider = "deepseek-failed"
    elif not api_key:
        deepseek_error = "未配置 DeepSeek API Key，无法做整稿总编式改写。"
    else:
        deepseek_error = "当前环境缺少 openai 依赖，无法调用 DeepSeek。"

    references = storage.get_references(project_id)
    canonical = canonicalize_project_content(
        project_id,
        optimized_content,
        brief=brief,
        references=references,
    )
    optimized_content = str(canonical.get("content") or optimized_content)
    bad_phrase_hits = list(canonical.get("bad_phrase_repair") or [])
    opening_repair = canonical.get("opening_repair") if isinstance(canonical.get("opening_repair"), dict) else {}
    image_refreshed_content = refresh_content_image_prompts(project, template, optimized_content)
    changed = image_refreshed_content != original_content
    storage.save_content(project_id, image_refreshed_content)
    save_spoken_script_manifest(project_id, image_refreshed_content)
    fact_registry = save_episode_fact_registry(
        project_id,
        image_refreshed_content,
        brief=brief,
        references=references,
        registry=canonical.get("fact_registry") if isinstance(canonical.get("fact_registry"), dict) else None,
    )
    opening_report = canonical.get("opening_novelty") if isinstance(canonical.get("opening_novelty"), dict) else opening_novelty_report(project_id, image_refreshed_content)
    storage.write_json(storage.project_file(project_id, "opening_novelty.json"), opening_report)
    prompt_manifest = save_visual_prompt_manifest(project_id, image_refreshed_content)
    summary = summarize_content(image_refreshed_content, mode)
    summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
    summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
    tavily_topic = storage.get_project_settings(project_id).get("tavily_topic", "general")
    artifacts = build_content_artifacts(project, template, brief, tavily_topic, references, image_refreshed_content)
    storage.save_summary(project_id, summary)
    storage.write_json(storage.project_file(project_id, "content_strategy.json"), artifacts["strategy"])
    storage.write_json(storage.project_file(project_id, "content_audit.json"), artifacts["audit"])
    storage.save_report(project_id, "topic_score", artifacts["strategy"]["topic_score"])
    storage.save_report(project_id, "viral_doctor", artifacts["audit"]["viral_doctor"])
    storage.save_report(project_id, "title_cover_ab", artifacts["audit"]["title_cover_ab"])
    if changed:
        mark_image_review_dirty(project_id, "content.md 已做总编优化/图片提示词重建，图片需要重新确认")
    report = quality_gate_report(project_id, brief=brief, content=image_refreshed_content, prefer_ai=False)
    report_path = storage.save_report(project_id, "quality_gate", report)
    after_engagement = content_engagement_report(image_refreshed_content, mode)
    return {
        "ok": True,
        "changed": changed,
        "provider": provider,
        "deepseek_error": deepseek_error,
        "content": image_refreshed_content,
        "summary": summary,
        "fact_registry": fact_registry,
        "before": before_engagement,
        "after": after_engagement,
        "bad_phrase_repair": bad_phrase_hits,
        "opening_novelty": opening_report,
        "opening_repair": {
            "changed": bool(opening_repair.get("changed")),
            "replacement": opening_repair.get("replacement", ""),
        },
        "quality_gate": report,
        "report_path": str(report_path),
    }


