def production_stage_gate_keys_for_step(step: str) -> list[str]:
    step = clean_text(step)
    if step == "audio":
        return ["content_gate"]
    if step in {"images", "images_missing", "images_sample", "covers", "covers_missing"}:
        return ["content_gate", "visual_prompt_gate"]
    if step == "video":
        return ["pre_video_gate"]
    return []


def production_stage_gate_auto_fix_mode(explicit_gate_mode: str, gate_key: str) -> bool:
    """Return whether a gate may mutate assets during this job step.

    An explicitly requested gate repair is allowed to optimize assets.  The
    pre-video gate attached implicitly to the video step is deliberately
    check-only: once composition starts it must consume the selected assets,
    not reopen an image provider behind the user's back.
    """
    mode = clean_text(explicit_gate_mode)
    if mode == "check":
        return False
    if mode == "fix":
        return True
    return clean_text(gate_key) != "pre_video_gate"


def quality_sample_scene_index(project_id: int, scene_count: int) -> int:
    if scene_count <= 0:
        return 0
    plan = storage.read_json(storage.project_file(project_id, "audio/scene_plan.json"), {})
    scenes = plan.get("scenes") if isinstance(plan, dict) and isinstance(plan.get("scenes"), list) else []
    candidates: list[tuple[float, int]] = []
    for item in scenes:
        if not isinstance(item, dict):
            continue
        try:
            index = int(item.get("index", 0) or 0)
        except (TypeError, ValueError):
            continue
        if index < 1 or index > scene_count:
            continue
        importance = float(item.get("importance_score", 0) or 0)
        alignment = float(item.get("alignment_score", 0) or 0)
        hook_bonus = 12.0 if index == 1 else 0.0
        candidates.append((importance * 2.0 + alignment * 0.15 + hook_bonus, index))
    if not candidates:
        return 1
    return max(candidates, key=lambda item: (item[0], -item[1]))[1]


def key_image_candidate_score(project_id: int, path: Path, prompt: str, scene_index: int = 0) -> dict[str, Any]:
    metrics = image_asset_metrics(path, project_id)
    context_map = image_semantic_context_map(project_id)
    semantic_context = context_map.get(f"scenes/s_{scene_index:02d}.png", {}) if scene_index > 0 else {}
    appeal = image_appeal_score(metrics, prompt, is_cover=False, semantic_context=semantic_context)
    audit = read_image_audit(path)
    severity = clean_text(str(audit.get("severity") or "ok"))
    penalty = 35 if severity == "hard" else (12 if severity == "soft" else 0)
    ocr = audit.get("ocr") if isinstance(audit.get("ocr"), dict) else {}
    fact_coverage = int(ocr.get("fact_coverage_score", 0) or 0)
    semantic = appeal.get("semantic") if isinstance(appeal.get("semantic"), dict) else {}
    speech_fit = int(max(semantic.get("speech", 0) or 0, semantic.get("audio_anchor", 0) or 0))
    information_score = int(
        clamp_number(
            float(metrics.get("contrast", 0) or 0) * 1.2
            + float(metrics.get("edge_score", 0) or 0) * 3.0
            + fact_coverage * 0.25,
            0,
            100,
        )
    )
    opening_contract = opening_visual_contract(project_id) if int(scene_index or 0) == 1 else {}
    opening_alignment = opening_visual_alignment_score(prompt, audit, opening_contract) if opening_contract else {}
    if opening_contract:
        score = max(
            0,
            int(
                round(
                    int(appeal.get("score", 0) or 0) * 0.38
                    + speech_fit * 0.23
                    + information_score * 0.17
                    + int(opening_alignment.get("score", 0) or 0) * 0.22
                    - penalty
                )
            ),
        )
    else:
        score = max(
            0,
            int(
                round(
                    int(appeal.get("score", 0) or 0) * 0.48
                    + speech_fit * 0.3
                    + information_score * 0.22
                    - penalty
                )
            ),
        )
    return {
        "path": path.as_posix(),
        "score": score,
        "judge": (
            "title-opening-first-frame-contract + speech-fit + information-density + first-frame-appeal"
            if opening_contract
            else "speech-fit + information-density + first-frame-appeal"
        ),
        "dimensions": {
            "speech_fit": speech_fit,
            "information_density": information_score,
            "appeal": int(appeal.get("score", 0) or 0),
            "fact_coverage": fact_coverage,
            "opening_contract": int(opening_alignment.get("score", 0) or 0),
            "title_alignment": int(opening_alignment.get("title_alignment", 0) or 0),
            "opening_line_alignment": int(opening_alignment.get("opening_line_alignment", 0) or 0),
        },
        "appeal": appeal,
        "audit": audit,
        "prompt": prompt,
        "opening_contract": opening_contract,
    }


def opening_visual_contract(project_id: int) -> dict[str, Any]:
    """Bind the title, first spoken line and first frame to one semantic promise."""

    project = storage.get_project(project_id)
    content = storage.get_content(project_id)
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    mode = clean_text(str(project.get("template_mode") or template.get("mode") or "video"))
    spoken_content = content_without_image_prompts(content) or content
    summary = summarize_content(spoken_content, mode)
    title = clean_text(
        str(
            summary.get("publish_title")
            or summary.get("video_title")
            or first_heading(spoken_content)
            or project.get("topic_name")
            or ""
        )
    )
    cover_title = clean_text(str(summary.get("cover_title") or title))
    opening_line = extract_opening_hook(spoken_content, mode)
    context_map = image_semantic_context_map(project_id, spoken_content, mode)
    first_context = context_map.get("scenes/s_01.png", {})
    first_speech = clean_scene_spoken_text(
        str(first_context.get("audio_anchor") or first_context.get("speech") or opening_line)
    )
    semantic_source = clean_text("\n".join([title, cover_title, opening_line, first_speech]))
    return {
        "title": title,
        "cover_title": cover_title,
        "opening_line": opening_line,
        "first_scene_speech": first_speech,
        "semantic_terms": semantic_tokens(semantic_source, limit=24),
        "promise_hash": semantic_text_hash(semantic_source),
    }


def opening_visual_alignment_score(
    prompt: str,
    audit: dict[str, Any],
    contract: dict[str, Any],
) -> dict[str, int]:
    ocr = audit.get("ocr") if isinstance(audit.get("ocr"), dict) else {}
    evidence = clean_text("\n".join([prompt, str(ocr.get("text") or "")]))
    title = clean_text(str(contract.get("title") or contract.get("cover_title") or ""))
    opening_line = clean_text(str(contract.get("opening_line") or ""))
    first_scene_speech = clean_text(str(contract.get("first_scene_speech") or opening_line))
    title_alignment = token_overlap_score(evidence, title, limit=24)
    opening_line_alignment = token_overlap_score(evidence, opening_line, limit=32)
    speech_alignment = token_overlap_score(evidence, first_scene_speech, limit=40)
    score = int(round(title_alignment * 0.34 + opening_line_alignment * 0.33 + speech_alignment * 0.33))
    return {
        "score": score,
        "title_alignment": title_alignment,
        "opening_line_alignment": opening_line_alignment,
        "first_scene_speech_alignment": speech_alignment,
    }


def _key_visual_concept_text(concept: dict[str, Any]) -> str:
    return clean_text(
        "\n".join(
            str(concept.get(key) or "")
            for key in (
                "name",
                "visual_thesis",
                "subject",
                "conflict",
                "composition",
                "information_strategy",
                "why_click",
            )
        )
    )


def _fallback_key_visual_concepts(
    project_id: int,
    purpose: str,
    base_prompt: str,
    contract: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Build three semantic concepts without locking the episode to one visual template."""

    if not isinstance(contract, dict) or not contract:
        try:
            contract = opening_visual_contract(project_id)
        except (ValueError, KeyError):
            contract = {}
    title = clean_text(str(contract.get("cover_title") or contract.get("title") or "本期主题"))
    opening = clean_text(str(contract.get("opening_line") or contract.get("first_scene_speech") or "当前开场"))
    anchor_tokens = semantic_tokens("\n".join([title, opening, base_prompt]), limit=12)
    anchor = "、".join(anchor_tokens[:5]) or title
    strategies = [
        {
            "name": "动作触发的真相瞬间",
            "visual_thesis": f"把“{opening}”变成正在发生且后果立刻可见的一瞬间",
            "subject": f"围绕 {anchor} 选择一个真实主体与一只正在操作的手",
            "conflict": "一个看似普通的动作，马上触发与预期相反的可见结果",
            "composition": "近景或中近景，动作在前景、结果在中景，观众沿动作方向读图",
            "information_strategy": "证据直接长在物件和动作里，数字只在确有必要时成为一个主信息",
            "why_click": "第一眼先看到动作，第二眼发现结果不对劲，形成追问",
        },
        {
            "name": "证据同框对撞",
            "visual_thesis": f"用同一真实空间里的两份相反证据兑现“{title}”",
            "subject": f"从 {anchor} 中选择两个存在因果关系的实体证据",
            "conflict": "承诺与实际结果在同一画面中互相否定，而不是做装饰性拼贴",
            "composition": "主体占画面大部分，用距离、朝向和光线形成左右或前后对撞",
            "information_strategy": "让数字、账单、状态灯、痕迹或实物规模承担信息，不堆长段说明",
            "why_click": "观众无需读完整文字也能看出前后矛盾",
        },
        {
            "name": "后果被发现的瞬间",
            "visual_thesis": f"从“{opening}”之后最刺痛的实际后果反推本期悬念",
            "subject": f"以 {anchor} 的真实使用者、关键物件和结果痕迹构成现场",
            "conflict": "人物刚发现损失、异常或误判，表情与现场证据互相呼应",
            "composition": "后果证据清晰在前，人物反应在侧后方，避免正面摆拍和摊手",
            "information_strategy": "只把决定理解的事实做成视觉重点，其它内容交给字幕",
            "why_click": "先让观众感到代价，再产生‘为什么会这样’的观看动力",
        },
        {
            "name": "选择前一秒",
            "visual_thesis": f"把“{title}”压缩成一个马上就会选错的现实抉择",
            "subject": f"围绕 {anchor} 选择一只停在关键选择前的手和两个真实去向",
            "conflict": "两个选择看似接近，实际后果完全不同",
            "composition": "俯拍或过肩近景，手部和两个选项形成三角关系，人物仅作为情绪背景",
            "information_strategy": "用状态、材质、价格或结果差异表达，不使用统一模板信息板",
            "why_click": "观众会下意识代入并猜自己会选哪一个",
        },
        {
            "name": "规模反差实体化",
            "visual_thesis": f"把“{opening}”里最反常的数字或规模变成可比较的实体证据",
            "subject": f"从 {anchor} 中选择一个可计数、可堆叠或可测量的核心物件",
            "conflict": "宣传中的轻描淡写与现场真实规模形成强烈反差",
            "composition": "一个尺度参照物靠近镜头，真实数量或时间痕迹延伸到背景",
            "information_strategy": "核心数字和实体规模互相证明，避免数字墙和无关装饰",
            "why_click": "视觉规模先制造冲击，随后数字完成事实确认",
        },
        {
            "name": "被忽略的关键证据",
            "visual_thesis": f"把决定“{title}”真假的小证据放到第一视觉层级",
            "subject": f"从 {anchor} 中寻找一个观众平时容易忽略但能定性的细节",
            "conflict": "大多数人盯着表面，真正答案藏在近处的物理痕迹或状态变化里",
            "composition": "微距证据为主，人物或完整场景虚化在后，使用光线和视线引导而非红圈箭头",
            "information_strategy": "证据本身可读，必要时只保留一个与证据直接相连的短结论",
            "why_click": "观众会因‘原来关键在这里’而停留",
        },
    ]
    seed = int(hashlib.sha256(f"{title}|{opening}|{purpose}|{base_prompt[:800]}".encode("utf-8")).hexdigest()[:8], 16)
    start = seed % len(strategies)
    step = 5 if seed % 2 else 1
    picked = [strategies[(start + step * offset) % len(strategies)] for offset in range(3)]
    return [
        {
            **item,
            "id": chr(ord("A") + index),
            "ai_score": 72 - index,
            "source": "semantic-fallback",
        }
        for index, item in enumerate(picked)
    ]


def _score_key_visual_concepts(
    concepts: list[dict[str, Any]],
    contract: dict[str, Any],
) -> list[dict[str, Any]]:
    title = clean_text(str(contract.get("cover_title") or contract.get("title") or ""))
    opening = clean_text(str(contract.get("opening_line") or contract.get("first_scene_speech") or ""))
    cliché_terms = ("赛博", "全息", "机器人", "人物摊手", "悬浮UI", "巨大红叉", "霓虹科技", "无关装饰")
    action_terms = ("按", "拿", "撕", "拆", "拨", "选", "发现", "触发", "打开", "关闭", "对比", "测量", "指向")
    conflict_terms = ("冲突", "反差", "相反", "异常", "后果", "损失", "误判", "选择", "证据", "真相", "悬念")
    scored: list[dict[str, Any]] = []
    concept_bodies = [_key_visual_concept_text(item) for item in concepts]
    for index, concept in enumerate(concepts):
        body = concept_bodies[index]
        title_fit = token_overlap_score(body, title, limit=24) if title else 70
        opening_fit = token_overlap_score(body, opening, limit=32) if opening else 70
        complete_fields = sum(
            1
            for key in ("visual_thesis", "subject", "conflict", "composition", "information_strategy", "why_click")
            if clean_text(str(concept.get(key) or ""))
        )
        structure = int(round(complete_fields / 6 * 100))
        action = min(100, 45 + sum(12 for term in action_terms if term in body))
        conflict = min(100, 40 + sum(11 for term in conflict_terms if term in body))
        try:
            ai_score = int(clamp_number(float(concept.get("ai_score", 72) or 72), 0, 100))
        except (TypeError, ValueError):
            ai_score = 72
        similarities = [
            difflib.SequenceMatcher(None, body, other).ratio()
            for other_index, other in enumerate(concept_bodies)
            if other_index != index and other
        ]
        max_similarity = max(similarities, default=0.0)
        diversity = int(round(clamp_number((1.0 - max(0.0, max_similarity - 0.20)) * 100, 0, 100)))
        cliché_hits = [term for term in cliché_terms if term in body]
        score = int(
            round(
                title_fit * 0.16
                + opening_fit * 0.18
                + structure * 0.14
                + action * 0.13
                + conflict * 0.13
                + diversity * 0.14
                + ai_score * 0.12
                - len(cliché_hits) * 7
            )
        )
        scored.append(
            {
                **concept,
                "score": int(clamp_number(score, 0, 100)),
                "dimensions": {
                    "title_fit": title_fit,
                    "opening_fit": opening_fit,
                    "structure": structure,
                    "action": action,
                    "conflict": conflict,
                    "diversity": diversity,
                    "ai_score": ai_score,
                },
                "max_similarity": round(max_similarity, 3),
                "cliche_hits": cliché_hits,
            }
        )
    return sorted(scored, key=lambda item: (int(item.get("score", 0) or 0), -len(str(item.get("visual_thesis") or ""))), reverse=True)


def _normalize_key_visual_concepts(
    raw_concepts: Any,
    fallback: list[dict[str, Any]],
    contract: dict[str, Any],
    provider: str,
) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    if isinstance(raw_concepts, list):
        for index, item in enumerate(raw_concepts[:3]):
            if not isinstance(item, dict):
                continue
            try:
                declared_score = int(clamp_number(float(item.get("score", item.get("ai_score", 72)) or 72), 0, 100))
            except (TypeError, ValueError):
                declared_score = 72
            concept = {
                "id": chr(ord("A") + len(normalized)),
                "name": clean_text(str(item.get("name") or item.get("concept_name") or f"构思 {index + 1}")),
                "visual_thesis": clean_text(str(item.get("visual_thesis") or item.get("idea") or "")),
                "subject": clean_text(str(item.get("subject") or "")),
                "conflict": clean_text(str(item.get("conflict") or "")),
                "composition": clean_text(str(item.get("composition") or "")),
                "information_strategy": clean_text(str(item.get("information_strategy") or item.get("information") or "")),
                "why_click": clean_text(str(item.get("why_click") or item.get("reason") or "")),
                "prompt": clean_text(str(item.get("prompt") or "")),
                "ai_score": declared_score,
                "source": provider,
            }
            if len(_key_visual_concept_text(concept)) >= 30:
                normalized.append(concept)
    for fallback_item in fallback:
        if len(normalized) >= 3:
            break
        candidate = {**fallback_item, "id": chr(ord("A") + len(normalized))}
        body = _key_visual_concept_text(candidate)
        if any(difflib.SequenceMatcher(None, body, _key_visual_concept_text(item)).ratio() > 0.82 for item in normalized):
            continue
        normalized.append(candidate)
    normalized = normalized[:3]
    for index, item in enumerate(normalized):
        item["id"] = chr(ord("A") + index)
    return _score_key_visual_concepts(normalized, contract)


def generate_key_visual_concepts(project_id: int, purpose: str, base_prompt: str) -> dict[str, Any]:
    """Create three text concepts and select only the best two for rendering."""

    purpose_key = "cover" if clean_text(purpose).lower().startswith("cover") else "opening"
    try:
        project = storage.get_project(project_id)
    except (ValueError, KeyError):
        project = {"id": project_id, "template": "", "topic_name": ""}
    template_key = clean_text(str(project.get("template") or ""))
    template = storage.get_template(template_key) if template_key else {}
    try:
        contract = opening_visual_contract(project_id)
    except (ValueError, KeyError):
        prompt_anchor = clean_text(base_prompt)[:180]
        contract = {
            "title": clean_text(str(project.get("topic_name") or prompt_anchor)),
            "cover_title": clean_text(str(project.get("topic_name") or prompt_anchor)),
            "opening_line": prompt_anchor,
            "first_scene_speech": prompt_anchor,
        }
    fallback = _fallback_key_visual_concepts(project_id, purpose_key, base_prompt, contract)
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    provider = "semantic-fallback"
    ai_error = ""
    raw_concepts: Any = []
    if api_key and OpenAI is not None:
        base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
        model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
        thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
        reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
        previous = storage.get_report(project_id, "key_visual_concepts") or {}
        previous_plan = (previous.get("plans") or {}).get(purpose_key, {}) if isinstance(previous, dict) else {}
        previous_names = [
            clean_text(str(item.get("name") or ""))
            for item in (previous_plan.get("concepts") or [])
            if isinstance(item, dict)
        ]
        language_rule = build_output_language_rules(project)
        user_prompt = f"""
你是短视频的首帧与封面创意导演。先做文字构思竞争，再由系统只生成前两名。
{language_rule}

本次位置：{"主横屏封面" if purpose_key == "cover" else "首镜前三秒"}
标题：{contract.get("cover_title") or contract.get("title") or ""}
开场首句：{contract.get("opening_line") or ""}
首镜口播：{contract.get("first_scene_speech") or ""}
频道：{template.get("brand_name") or template.get("name") or template_key}

当前基础成图要求：
{base_prompt[:9000]}

上一轮构思名：{json.dumps(previous_names, ensure_ascii=False)}

请返回严格 JSON：
{{
  "concepts": [
    {{
      "name": "构思名",
      "visual_thesis": "这一张用什么可见事实兑现标题和首句",
      "subject": "具体主体与关键物件",
      "conflict": "正在发生的动作、矛盾或悬念",
      "composition": "镜头距离、空间关系、视线顺序",
      "information_strategy": "哪些信息由实物、数字、状态或短标题表达",
      "why_click": "为什么缩略图第一眼会停留",
      "prompt": "在基础要求上追加的本构思专属成图指令",
      "score": 0
    }}
  ]
}}

硬要求：
1. 恰好 3 个构思，且主体、动作、构图、信息组织至少各有三项明显区别。
2. 每个构思必须从本期标题、开场和基础要求里取材，不借用其它镜头或历史项目。
3. 避开人物摊手、机器人、全息脑图、巨大红叉、赛博蓝光、统一黑条和无意义物件堆叠。
4. score 按标题兑现、首句悬念、事实准确、视觉冲突、缩略图可读性综合给 0-100 分。
5. prompt 只描述本构思的独有设计，不复述整份基础要求。
""".strip()
        extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
        if thinking_type in {"enabled", "disabled"}:
            extra_body["thinking"] = {"type": thinking_type}
        try:
            client = OpenAI(api_key=api_key, base_url=base_url, timeout=90.0, max_retries=0)
            response = client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": "你只输出严格 JSON，不输出 Markdown。"},
                    {"role": "user", "content": user_prompt},
                ],
                temperature=0.78,
                max_tokens=4200,
                response_format={"type": "json_object"},
                extra_body=extra_body,
            )
            choice = response.choices[0] if getattr(response, "choices", None) else None
            raw = message_content_to_text(choice.message.content if choice and getattr(choice, "message", None) else "")
            payload = _safe_json_from_text(raw)
            raw_concepts = payload.get("concepts") if isinstance(payload, dict) else []
            provider = f"deepseek-creative-director:{model}"
        except Exception as exc:
            ai_error = str(exc)
            raw_concepts = []
    concepts = _normalize_key_visual_concepts(raw_concepts, fallback, contract, provider)
    selected = concepts[:2]
    report = {
        "policy_version": KEY_VISUAL_CONCEPT_POLICY_VERSION,
        "purpose": purpose_key,
        "provider": provider if raw_concepts else "semantic-fallback",
        "ai_error": ai_error,
        "generated_at": storage.now_ts(),
        "contract": contract,
        "concept_count": len(concepts),
        "render_count": len(selected),
        "concepts": concepts,
        "selected_concepts": selected,
        "selected_ids": [str(item.get("id") or "") for item in selected],
        "selection_rule": "AI creative score + title/opening fit + diversity guard; render top two only",
    }
    root_report = storage.get_report(project_id, "key_visual_concepts") or {}
    plans = root_report.get("plans") if isinstance(root_report.get("plans"), dict) else {}
    plans[purpose_key] = report
    root_report.update(
        {
            "policy_version": KEY_VISUAL_CONCEPT_POLICY_VERSION,
            "updated_at": storage.now_ts(),
            "plans": plans,
        }
    )
    storage.save_report(project_id, "key_visual_concepts", root_report)
    return report


