def cover_candidate_status(project_id: int) -> dict[str, Any]:
    report = storage.get_report(project_id, "cover_candidates")
    competition = report.get("competition") if isinstance(report, dict) else {}
    if not isinstance(competition, dict) or not competition:
        return {"pending": False}
    candidate_path = storage.project_file(project_id, "covers/candidates/cover_landscape_b.png")
    if not candidate_path.exists() or candidate_path.stat().st_size < 4096:
        return {"pending": False}
    prompt_path = candidate_path.with_suffix(".md")
    audit_path = candidate_path.with_suffix(".audit.json")
    prompt = storage.read_text(prompt_path) if prompt_path.exists() else ""
    audit = storage.read_json(audit_path, {}) if audit_path.exists() else {}
    candidates = competition.get("candidates") if isinstance(competition.get("candidates"), list) else []
    report_candidate = next((item for item in candidates if isinstance(item, dict)), {})
    return {
        "pending": clean_text(str(competition.get("selection_mode") or "")) in {
            "pending",
            "generating",
            "ai_recommended_pending_human",
        },
        "target": "cover_landscape.png",
        "role": "cover_hook_competition",
        "selection_mode": clean_text(str(competition.get("selection_mode") or "")),
        "selected_variant": clean_text(str(competition.get("selected_variant") or "")),
        "ai_recommended_variant": clean_text(str(competition.get("ai_recommended_variant") or "")),
        "current_score": int((competition.get("current") or {}).get("score", 0))
        if isinstance(competition.get("current"), dict)
        else 0,
        "current": competition.get("current") if isinstance(competition.get("current"), dict) else {},
        "concept_count": int(competition.get("concept_count", 0) or 0),
        "generated_count": int(competition.get("generated_count", 0) or 0),
        "concept_provider": clean_text(str(competition.get("concept_provider") or "")),
        "concept_pool": competition.get("concept_pool") if isinstance(competition.get("concept_pool"), list) else [],
        "selected_concepts": competition.get("selected_concepts") if isinstance(competition.get("selected_concepts"), list) else [],
        "opening_contract": competition.get("opening_contract")
        if isinstance(competition.get("opening_contract"), dict)
        else {},
        "candidate": {
            "variant": "B",
            "filename": candidate_path.name,
            "url": f"/data/projects/{project_id}/covers/candidates/{candidate_path.name}",
            "relative_path": f"covers/candidates/{candidate_path.name}",
            "absolute_path": str(candidate_path.resolve()),
            "size": candidate_path.stat().st_size,
            "modified_at": candidate_path.stat().st_mtime,
            "prompt": prompt,
            "prompt_preview": storage.prompt_preview_text(prompt),
            "prompt_url": f"/data/projects/{project_id}/covers/candidates/{prompt_path.name}" if prompt_path.exists() else "",
            "audit": audit if isinstance(audit, dict) else {},
            "score": int(report_candidate.get("score", 0) or 0),
            "local_score": int(report_candidate.get("local_score", report_candidate.get("score", 0)) or 0),
            "judge_mode": clean_text(str(report_candidate.get("judge_mode") or "")),
            "vision_judge": report_candidate.get("vision_judge") if isinstance(report_candidate.get("vision_judge"), dict) else {},
            "concept": report_candidate.get("concept") if isinstance(report_candidate.get("concept"), dict) else {},
            "is_ai_recommended": clean_text(str(competition.get("ai_recommended_variant") or "")).upper() == "B",
        },
    }


def promote_generated_image_candidate(source: Path, target: Path) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)
    for suffix in (".md", ".audit.json", ".typography.json"):
        source_sidecar = source.with_suffix(suffix)
        if source_sidecar.exists():
            shutil.copy2(source_sidecar, target.with_suffix(suffix))
    source_cover = cover_typography_source_path(source)
    if source_cover.exists():
        shutil.copy2(source_cover, cover_typography_source_path(target))
    scene_source = scene_information_source_path(source)
    if scene_source.exists():
        shutil.copy2(scene_source, scene_information_source_path(target))
    scene_overlay = scene_information_overlay_path(source)
    if scene_overlay.exists():
        shutil.copy2(scene_overlay, scene_information_overlay_path(target))


def cleanup_scene_image_candidates(
    project_id: int,
    scene_index: int,
    *,
    keep_variants: Iterable[str] = (),
) -> list[str]:
    """Remove superseded candidate assets for one scene.

    Candidate images are a review buffer, not a permanent archive.  Keeping this
    cleanup scene-scoped prevents a repair from growing C/D/E variants forever.
    """

    normalized_index = max(0, int(scene_index or 0))
    if normalized_index <= 0:
        return []
    keep = {clean_text(str(item)).lower() for item in keep_variants if clean_text(str(item))}
    candidate_dir = storage.project_file(project_id, "scenes/candidates")
    if not candidate_dir.exists():
        return []
    prefix = f"s_{normalized_index:02d}_"
    removed: list[str] = []
    for path in list(candidate_dir.iterdir()):
        if not path.is_file():
            continue
        comparable = path.name[1:] if path.name.startswith(".") else path.name
        if not comparable.lower().startswith(prefix):
            continue
        variant_match = re.match(rf"^{re.escape(prefix)}([a-z])", comparable, flags=re.IGNORECASE)
        if not variant_match or variant_match.group(1).lower() in keep:
            continue
        path.unlink(missing_ok=True)
        removed.append(path.name)
    return removed


def discard_scene_image_candidates(
    project_id: int,
    scene_index: int,
    *,
    reason: str = "official_regenerated",
) -> list[str]:
    """Clear one scene's temporary alternatives after a new official image exists."""

    normalized_index = max(0, int(scene_index or 0))
    if normalized_index <= 0:
        return []
    removed = cleanup_scene_image_candidates(project_id, normalized_index)
    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        return removed
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    remaining = [
        item
        for item in competitions
        if not (isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == normalized_index)
    ]
    if len(remaining) == len(competitions) and not removed:
        return removed
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    history.append(
        {
            "scene_index": normalized_index,
            "target": f"s_{normalized_index:02d}.png",
            "selection_mode": clean_text(reason) or "official_regenerated",
            "selected_at": storage.now_ts(),
            "removed_files": removed,
        }
    )
    report.update(
        {
            "updated_at": storage.now_ts(),
            "policy": "single official image by default; one optional review candidate per scene",
            "competitions": remaining,
            "selection_history": history[-60:],
        }
    )
    storage.save_report(project_id, "key_image_candidates", report)
    return removed


def _save_scene_repair_candidate(
    project_id: int,
    scene_index: int,
    candidate_path: Path,
    prompt: str,
    *,
    recovered: bool = False,
) -> dict[str, Any]:
    variant_match = re.fullmatch(rf"s_{int(scene_index):02d}_([a-z])", candidate_path.stem, flags=re.IGNORECASE)
    variant = variant_match.group(1).upper() if variant_match else "R"
    if recovered:
        audit = read_image_audit(candidate_path)
        candidate = {
            "path": candidate_path.as_posix(),
            "score": 0,
            "judge": "recovered-after-interruption",
            "dimensions": {},
            "audit": audit,
            "prompt": prompt,
        }
    else:
        candidate = apply_actual_image_judge(
            key_image_candidate_score(project_id, candidate_path, prompt, int(scene_index)),
            (
                vision_key_image_judge(project_id, candidate_path, prompt, "opening")
                if int(scene_index) == 1
                else {"available": False, "provider": "local-visual-audit"}
            ),
        )
    candidate["variant"] = variant
    official_path = storage.project_file(project_id, f"scenes/s_{int(scene_index):02d}.png")
    current: dict[str, Any] = {}
    if official_path.exists() and official_path.stat().st_size >= 4096:
        official_prompt = read_generated_prompt(official_path, prompt)
        current = apply_actual_image_judge(
            key_image_candidate_score(project_id, official_path, official_prompt, int(scene_index)),
            (
                vision_key_image_judge(project_id, official_path, official_prompt, "opening")
                if int(scene_index) == 1 and not recovered
                else {"available": False, "provider": "local-visual-audit"}
            ),
        )
        current["variant"] = "CURRENT"
    candidate_score = int(candidate.get("score", 0) or 0)
    current_score = int(current.get("score", -1) or -1) if current else -1
    candidate_has_visual_review = bool(
        isinstance(candidate.get("vision_judge"), dict)
        and candidate["vision_judge"].get("available")
    )
    current_has_visual_review = bool(
        isinstance(current.get("vision_judge"), dict)
        and current["vision_judge"].get("available")
    )
    recommended = (
        variant
        if (
            recovered
            or not current
            or (
                candidate_has_visual_review
                and current_has_visual_review
                and candidate_score >= current_score + 2
            )
        )
        else "CURRENT"
    )

    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        report = {}
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    competitions = [
        item
        for item in competitions
        if not (isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == int(scene_index))
    ]
    competitions.append(
        {
            "scene_index": int(scene_index),
            "target": f"s_{int(scene_index):02d}.png",
            "role": "repair_candidate",
            "selected_variant": recommended,
            "selected_score": max(current_score, candidate_score),
            "ai_recommended_variant": recommended,
            "selection_mode": "recovered_pending_human" if recovered else "ai_recommended_pending_human",
            "manual_confirmation_required": True,
            "visual_review_available": candidate_has_visual_review and current_has_visual_review,
            "candidate_limit": 1,
            "current": current,
            "candidates": [candidate],
        }
    )
    report.update(
        {
            "generated_at": report.get("generated_at") or storage.now_ts(),
            "updated_at": storage.now_ts(),
            "policy": "one pending repair candidate per scene; adopted candidates are removed",
            "competitions": sorted(competitions, key=lambda item: int(item.get("scene_index", 0) or 0)),
        }
    )
    storage.save_report(project_id, "key_image_candidates", report)
    mark_image_review_dirty(project_id, f"场景 {int(scene_index)} 有 1 张待审替换图，请先采用或重绘")
    return candidate


def mark_scene_image_manual_acceptance(project_id: int, filename: str) -> None:
    records_path = storage.project_file(project_id, "scenes/scene_prompts.json")
    records = storage.read_json(records_path, [])
    if not isinstance(records, list):
        return
    changed = False
    for record in records:
        if not isinstance(record, dict) or clean_text(str(record.get("filename") or "")) != filename:
            continue
        record["manual_image_accepted"] = True
        record["manual_image_accepted_at"] = storage.now_ts()
        changed = True
        break
    if changed:
        storage.write_json(records_path, records)


def prune_finished_scene_candidates(project_id: int) -> list[dict[str, Any]]:
    """Delete candidates that have already been manually or automatically adopted."""

    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        return []
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    remaining: list[dict[str, Any]] = []
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    pruned: list[dict[str, Any]] = []
    for item in competitions:
        if not isinstance(item, dict):
            continue
        mode = clean_text(str(item.get("selection_mode") or ""))
        scene_index = int(item.get("scene_index", 0) or 0)
        target = clean_text(str(item.get("target") or f"s_{scene_index:02d}.png"))
        official = storage.project_file(project_id, f"scenes/{target}") if scene_index > 0 else None
        if mode in {"manual", "ai_auto"} and official and official.exists():
            if mode == "manual":
                mark_scene_image_manual_acceptance(project_id, target)
            removed = cleanup_scene_image_candidates(project_id, scene_index)
            record = {
                "scene_index": scene_index,
                "target": target,
                "variant": item.get("selected_variant"),
                "selection_mode": mode,
                "selected_at": item.get("manual_selected_at") or item.get("selected_at") or storage.now_ts(),
                "removed_files": removed,
            }
            history.append(record)
            pruned.append(record)
        else:
            remaining.append(item)
    if pruned:
        report["competitions"] = remaining
        report["selection_history"] = history[-60:]
        report["updated_at"] = storage.now_ts()
        report["policy"] = "one pending repair candidate per scene; adopted candidates are removed"
        storage.save_report(project_id, "key_image_candidates", report)
    return pruned


def recover_orphaned_scene_candidates(project_id: int, *, minimum_age_seconds: float = 2.0) -> list[dict[str, Any]]:
    candidate_dir = storage.project_file(project_id, "scenes/candidates")
    candidate_dir.mkdir(parents=True, exist_ok=True)
    scene_dir = storage.project_file(project_id, "scenes")
    now = time.time()
    newest_by_target: dict[str, Path] = {}
    pattern = re.compile(r"^\.s_(\d+)_([a-z])\.gen-\d+\.png$", flags=re.IGNORECASE)
    for path in candidate_dir.glob(".s_*.gen-*.png"):
        match = pattern.fullmatch(path.name)
        if not match or not path.is_file() or _is_active_generated_tmp(path):
            continue
        stat = path.stat()
        if stat.st_size < 4096 or now - stat.st_mtime < minimum_age_seconds:
            continue
        target_name = f"s_{int(match.group(1)):02d}_{match.group(2).lower()}.png"
        current = newest_by_target.get(target_name)
        if current is None or stat.st_mtime > current.stat().st_mtime:
            newest_by_target[target_name] = path

    recovered: list[dict[str, Any]] = []
    for target_name, tmp_path in sorted(newest_by_target.items()):
        if Image is not None:
            try:
                with Image.open(tmp_path) as image:
                    image.verify()
            except (OSError, SyntaxError):
                continue
        target = candidate_dir / target_name
        _replace_generated_image(tmp_path, target)
        prompt = read_generated_prompt(target, "")
        audit = read_image_audit(target)
        if not audit:
            audit = {
                "ok": False,
                "severity": "pending",
                "reasons": ["interrupted_before_audit"],
                "warnings": ["图片已下载完成，但任务在 OCR/质量审计前中断。"],
                "purpose": "scene",
                "size_hint": SCENE_IMAGE_SIZE,
                "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
                "prompt": prompt,
                "recovered_at": storage.now_ts(),
            }
            storage.write_json(target.with_suffix(".audit.json"), audit)
        recovered.append(
            {
                "filename": target.name,
                "path": str(target),
                "size": target.stat().st_size,
                "audit_status": "ready" if audit.get("severity") != "pending" else "pending",
            }
        )

    root_pattern = re.compile(r"^\.s_(\d+)\.(?:gen|regen)-\d+\.png$", flags=re.IGNORECASE)
    newest_root_by_index: dict[int, Path] = {}
    if scene_dir.exists():
        for path in [*scene_dir.glob(".s_*.gen-*.png"), *scene_dir.glob(".s_*.regen-*.png")]:
            match = root_pattern.fullmatch(path.name)
            if not match or not path.is_file() or _is_active_generated_tmp(path):
                continue
            stat = path.stat()
            if stat.st_size < 4096 or now - stat.st_mtime < minimum_age_seconds:
                continue
            index = int(match.group(1))
            current = newest_root_by_index.get(index)
            if current is None or stat.st_mtime > current.stat().st_mtime:
                newest_root_by_index[index] = path

    for scene_index, tmp_path in sorted(newest_root_by_index.items()):
        if Image is not None:
            try:
                with Image.open(tmp_path) as image:
                    image.verify()
            except Exception:
                continue
        cleanup_scene_image_candidates(project_id, scene_index)
        target = candidate_dir / f"s_{scene_index:02d}_r.png"
        _replace_generated_image(tmp_path, target)
        prompt = read_generated_prompt(target, "")
        audit = read_image_audit(target)
        if not audit:
            audit = {
                "ok": False,
                "severity": "pending",
                "reasons": ["interrupted_before_audit"],
                "warnings": ["图片已下载完成，但任务在 OCR/质量审计前中断。"],
                "purpose": "scene",
                "size_hint": SCENE_IMAGE_SIZE,
                "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
                "prompt": prompt,
                "recovered_at": storage.now_ts(),
            }
            storage.write_json(target.with_suffix(".audit.json"), audit)
        _save_scene_repair_candidate(project_id, scene_index, target, prompt, recovered=True)
        recovered.append(
            {
                "filename": target.name,
                "path": str(target),
                "size": target.stat().st_size,
                "audit_status": "pending",
                "recovered_from": tmp_path.name,
            }
        )
    return recovered


def _promote_scene_image_candidate(
    project_id: int,
    scene_index: int,
    variant: str,
    *,
    selection_mode: str,
    manual_accepted: bool,
) -> dict[str, Any]:
    try:
        normalized_index = int(scene_index)
    except (TypeError, ValueError) as exc:
        raise ValueError("候选图的场景编号无效。") from exc
    normalized_variant = clean_text(variant).upper()
    if normalized_index <= 0 or not re.fullmatch(r"[A-Z]", normalized_variant):
        raise ValueError("候选图编号无效，请重新刷新场景图。")

    candidate_dir = storage.project_file(project_id, "scenes/candidates")
    candidate_path = candidate_dir / f"s_{normalized_index:02d}_{normalized_variant.lower()}.png"
    if not candidate_path.exists() or candidate_path.stat().st_size < 4096:
        raise ValueError(f"候选 {normalized_variant} 尚未生成完成，暂时不能采用。")

    target_name = f"s_{normalized_index:02d}.png"
    target_path = storage.project_file(project_id, f"scenes/{target_name}")
    prompt = read_generated_prompt(candidate_path, "")
    audit = read_image_audit(candidate_path)
    if not audit or audit.get("severity") == "pending":
        audit = audit_generated_image(candidate_path, SCENE_IMAGE_SIZE, "scene", prompt)
        audit["attempt"] = int(audit.get("attempt", 1) or 1)
        audit["prompt"] = prompt
        storage.write_json(candidate_path.with_suffix(".audit.json"), audit)

    promote_generated_image_candidate(candidate_path, target_path)
    _update_scene_prompt_record(
        project_id,
        target_name,
        prompt,
        prompt,
        audit,
        manual_accepted=manual_accepted,
    )

    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        report = {}
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    competition = next(
        (
            item
            for item in competitions
            if isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == normalized_index
        ),
        None,
    )
    if competition is None:
        competition = {
            "scene_index": normalized_index,
            "target": target_name,
            "role": "key_scene",
            "candidates": [],
        }
        competitions.append(competition)
    report_candidates = competition.get("candidates") if isinstance(competition.get("candidates"), list) else []
    selected_report = next(
        (
            item
            for item in report_candidates
            if isinstance(item, dict) and clean_text(str(item.get("variant") or "")).upper() == normalized_variant
        ),
        {},
    )
    selected_at = storage.now_ts()
    removed_candidates = cleanup_scene_image_candidates(project_id, normalized_index)
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    history.append(
        {
            "scene_index": normalized_index,
            "target": target_name,
            "variant": normalized_variant,
            "score": int(selected_report.get("score", 0) or 0),
            "concept": selected_report.get("concept") if isinstance(selected_report.get("concept"), dict) else {},
            "ai_recommended_variant": competition.get("ai_recommended_variant") or competition.get("selected_variant"),
            "selection_mode": selection_mode,
            "selected_at": selected_at,
            "removed_files": removed_candidates,
        }
    )
    competitions = [
        item
        for item in competitions
        if not (isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == normalized_index)
    ]
    report.update(
        {
            "generated_at": report.get("generated_at") or storage.now_ts(),
            "updated_at": selected_at,
            "policy": "one pending repair candidate per scene; adopted candidates are removed",
            "competitions": sorted(competitions, key=lambda item: int(item.get("scene_index", 0) or 0)),
            "selection_history": history[-60:],
        }
    )
    storage.save_report(project_id, "key_image_candidates", report)
    actor = "人工" if selection_mode == "manual" else "AI 自动"
    review = mark_image_review_dirty(
        project_id,
        f"场景 {normalized_index} 已由{actor}采用候选 {normalized_variant}，等待图片总确认",
    )
    manifest: dict[str, Any] | None = None
    with contextlib.suppress(Exception):
        manifest = record_production_step(project_id, "images_sample")
    return {
        "ok": True,
        "scene_index": normalized_index,
        "variant": normalized_variant,
        "target": target_name,
        "path": str(target_path),
        "audit": audit,
        "review": review,
        "manifest": manifest,
        "scene_status": storage.scene_status(project_id),
    }


def select_scene_image_candidate(project_id: int, scene_index: int, variant: str) -> dict[str, Any]:
    return _promote_scene_image_candidate(
        project_id,
        scene_index,
        variant,
        selection_mode="manual",
        manual_accepted=True,
    )


def _resolve_current_scene_candidate_automatically(project_id: int, scene_index: int) -> dict[str, Any]:
    target_name = f"s_{int(scene_index):02d}.png"
    target_path = storage.project_file(project_id, f"scenes/{target_name}")
    if not target_path.exists() or target_path.stat().st_size < 4096:
        raise ValueError("当前正式图尚未完整保存。")
    removed = cleanup_scene_image_candidates(project_id, scene_index)
    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        report = {}
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    competition = next(
        (
            item
            for item in competitions
            if isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == int(scene_index)
        ),
        {},
    )
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    history.append(
        {
            "scene_index": int(scene_index),
            "target": target_name,
            "variant": "CURRENT",
            "ai_recommended_variant": "CURRENT",
            "selection_mode": "ai_auto_current",
            "selected_at": storage.now_ts(),
            "selected_score": int(competition.get("selected_score", 0) or 0),
            "concept": (
                (competition.get("current") or {}).get("concept")
                if isinstance(competition.get("current"), dict)
                and isinstance((competition.get("current") or {}).get("concept"), dict)
                else {}
            ),
            "removed_files": removed,
        }
    )
    report.update(
        {
            "updated_at": storage.now_ts(),
            "competitions": [
                item
                for item in competitions
                if not (isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == int(scene_index))
            ],
            "selection_history": history[-60:],
        }
    )
    storage.save_report(project_id, "key_image_candidates", report)
    return {
        "ok": True,
        "scene_index": int(scene_index),
        "variant": "CURRENT",
        "target": target_name,
        "path": str(target_path),
    }


def resolve_scene_candidates_automatically(project_id: int) -> dict[str, Any]:
    """Promote one AI-recommended candidate per pending scene.

    Switching to automatic review must change the official files consumed by
    video composition. Merely hiding the manual gate would leave stale images
    in place and make the mode switch misleading.
    """

    report = storage.get_report(project_id, "key_image_candidates")
    competitions = report.get("competitions") if isinstance(report, dict) else []
    if not isinstance(competitions, list):
        competitions = []

    resolved: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for competition in list(competitions):
        if not isinstance(competition, dict):
            continue
        scene_index = int(competition.get("scene_index", 0) or 0)
        if scene_index <= 0:
            continue
        recommended = clean_text(str(competition.get("ai_recommended_variant") or "")).upper()
        if recommended == "CURRENT":
            try:
                resolved.append(_resolve_current_scene_candidate_automatically(project_id, scene_index))
            except ValueError as exc:
                skipped.append({"scene_index": scene_index, "variant": "CURRENT", "reason": str(exc)})
            continue
        candidates = competition.get("candidates") if isinstance(competition.get("candidates"), list) else []
        ranked_candidates = sorted(
            (item for item in candidates if isinstance(item, dict)),
            key=lambda item: int(item.get("score", 0) or 0),
            reverse=True,
        )
        preferred_variants = [
            competition.get("ai_recommended_variant"),
            competition.get("selected_variant"),
            *(item.get("variant") for item in ranked_candidates),
        ]
        normalized_variants = list(
            dict.fromkeys(
                clean_text(str(item or "")).upper()
                for item in preferred_variants
                if re.fullmatch(r"[A-Z]", clean_text(str(item or "")).upper())
            )
        )
        candidate_dir = storage.project_file(project_id, "scenes/candidates")
        variant = next(
            (
                item
                for item in normalized_variants
                if (candidate_dir / f"s_{scene_index:02d}_{item.lower()}.png").exists()
                and (candidate_dir / f"s_{scene_index:02d}_{item.lower()}.png").stat().st_size >= 4096
            ),
            "",
        )
        if not variant:
            skipped.append({"scene_index": scene_index, "reason": "没有可采用的候选编号"})
            continue
        try:
            resolved.append(
                _promote_scene_image_candidate(
                    project_id,
                    scene_index,
                    variant,
                    selection_mode="ai_auto",
                    manual_accepted=False,
                )
            )
        except ValueError as exc:
            skipped.append({"scene_index": scene_index, "variant": variant, "reason": str(exc)})

    return {
        "resolved": [
            {"scene_index": item["scene_index"], "variant": item["variant"], "target": item["target"]}
            for item in resolved
        ],
        "skipped": skipped,
        "resolved_count": len(resolved),
        "skipped_count": len(skipped),
    }


def _finalize_cover_competition(
    project_id: int,
    variant: str,
    *,
    selection_mode: str,
) -> dict[str, Any]:
    normalized = clean_text(str(variant or "CURRENT")).upper()
    target_path = storage.project_file(project_id, "covers/cover_landscape.png")
    if normalized == "B":
        source_path = storage.project_file(project_id, "covers/candidates/cover_landscape_b.png")
        if not source_path.exists() or source_path.stat().st_size < 4096:
            raise ValueError("封面候选 B 尚未完整保存。")
        promote_generated_image_candidate(source_path, target_path)
    elif normalized != "CURRENT":
        raise ValueError("封面候选编号无效。")
    if not target_path.exists() or target_path.stat().st_size < 4096:
        raise ValueError("当前横屏封面尚未完整保存。")

    removed = cleanup_cover_candidates(project_id)
    report = storage.get_report(project_id, "cover_candidates")
    if not isinstance(report, dict):
        report = {}
    competition = report.get("competition") if isinstance(report.get("competition"), dict) else {}
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    selected_visual = competition.get("current") if normalized == "CURRENT" else next(
        (
            item
            for item in (competition.get("candidates") or [])
            if isinstance(item, dict) and clean_text(str(item.get("variant") or "")).upper() == normalized
        ),
        {},
    )
    history.append(
        {
            "target": "cover_landscape.png",
            "variant": normalized,
            "ai_recommended_variant": competition.get("ai_recommended_variant"),
            "selection_mode": clean_text(selection_mode),
            "score": int(selected_visual.get("score", 0) or 0) if isinstance(selected_visual, dict) else 0,
            "concept": (
                selected_visual.get("concept")
                if isinstance(selected_visual, dict) and isinstance(selected_visual.get("concept"), dict)
                else {}
            ),
            "selected_at": storage.now_ts(),
            "removed_files": removed,
        }
    )
    report.update(
        {
            "updated_at": storage.now_ts(),
            "competition": {},
            "selection_history": history[-40:],
        }
    )
    storage.save_report(project_id, "cover_candidates", report)
    review = mark_image_review_dirty(
        project_id,
        f"横屏封面已采用方案 {'A' if normalized == 'CURRENT' else normalized}，等待整组图片确认",
    )
    return {
        "ok": True,
        "target": "cover_landscape.png",
        "variant": normalized,
        "path": str(target_path),
        "review": review,
    }


def select_cover_candidate(project_id: int, variant: str) -> dict[str, Any]:
    return _finalize_cover_competition(project_id, variant, selection_mode="manual")


def keep_current_cover(project_id: int) -> dict[str, Any]:
    return _finalize_cover_competition(project_id, "CURRENT", selection_mode="manual_keep_current")


def resolve_cover_candidates_automatically(project_id: int) -> dict[str, Any]:
    status = cover_candidate_status(project_id)
    if not status.get("pending"):
        return {"resolved_count": 0, "resolved": []}
    recommended = clean_text(str(status.get("ai_recommended_variant") or "CURRENT")).upper()
    if recommended not in {"B", "CURRENT"}:
        recommended = "CURRENT"
    result = _finalize_cover_competition(project_id, recommended, selection_mode="ai_auto")
    return {"resolved_count": 1, "resolved": [{"target": result["target"], "variant": result["variant"]}]}


def keep_current_scene_image(project_id: int, scene_index: int) -> dict[str, Any]:
    try:
        normalized_index = int(scene_index)
    except (TypeError, ValueError) as exc:
        raise ValueError("场景编号无效。") from exc
    if normalized_index <= 0:
        raise ValueError("场景编号无效。")

    target_name = f"s_{normalized_index:02d}.png"
    target_path = storage.project_file(project_id, f"scenes/{target_name}")
    if not target_path.exists() or target_path.stat().st_size < 4096:
        raise ValueError("当前旧图不存在，不能选择保留。")

    prompt = read_generated_prompt(target_path, "")
    audit = read_image_audit(target_path)
    _update_scene_prompt_record(
        project_id,
        target_name,
        prompt,
        prompt,
        audit,
        manual_accepted=True,
    )
    removed_candidates = cleanup_scene_image_candidates(project_id, normalized_index)

    report = storage.get_report(project_id, "key_image_candidates")
    if not isinstance(report, dict):
        report = {}
    competitions = report.get("competitions") if isinstance(report.get("competitions"), list) else []
    competition = next(
        (
            item
            for item in competitions
            if isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == normalized_index
        ),
        {},
    )
    history = report.get("selection_history") if isinstance(report.get("selection_history"), list) else []
    history.append(
        {
            "scene_index": normalized_index,
            "target": target_name,
            "variant": "CURRENT",
            "ai_recommended_variant": competition.get("ai_recommended_variant"),
            "selection_mode": "keep_current",
            "selected_at": storage.now_ts(),
            "removed_files": removed_candidates,
        }
    )
    report.update(
        {
            "generated_at": report.get("generated_at") or storage.now_ts(),
            "updated_at": storage.now_ts(),
            "policy": "one pending repair candidate per scene; adopted candidates are removed",
            "competitions": [
                item
                for item in competitions
                if not (isinstance(item, dict) and int(item.get("scene_index", 0) or 0) == normalized_index)
            ],
            "selection_history": history[-60:],
        }
    )
    storage.save_report(project_id, "key_image_candidates", report)
    review = mark_image_review_dirty(
        project_id,
        f"场景 {normalized_index} 已人工保留当前旧图，等待图片总确认",
    )
    manifest: dict[str, Any] | None = None
    with contextlib.suppress(Exception):
        manifest = record_production_step(project_id, "images_sample")
    return {
        "ok": True,
        "scene_index": normalized_index,
        "variant": "CURRENT",
        "target": target_name,
        "path": str(target_path),
        "review": review,
        "manifest": manifest,
        "scene_status": storage.scene_status(project_id),
    }


def _stage_gate_teacher(supervisors: dict[str, Any], key: str) -> dict[str, Any]:
    teachers = supervisors.get("teachers") if isinstance(supervisors.get("teachers"), list) else []
    for item in teachers:
        if isinstance(item, dict) and item.get("key") == key:
            return item
    return {}


def _stage_gate_teacher_issue(teacher: dict[str, Any]) -> dict[str, Any] | None:
    score = int(teacher.get("score", 0) or 0)
    if score >= 72 and not teacher.get("blocking"):
        return None
    teacher_key = clean_text(str(teacher.get("key") or ""))
    hard_blocking_teacher = bool(teacher.get("blocking")) and teacher_key in {
        "fact_teacher",
        "visual_teacher",
    }
    name = clean_text(str(teacher.get("name") or teacher.get("key") or "AI 老师"))
    suggestions = teacher.get("suggestions") if isinstance(teacher.get("suggestions"), list) else []
    findings = teacher.get("findings") if isinstance(teacher.get("findings"), list) else []
    return quality_issue(
        "risk" if hard_blocking_teacher else "warn",
        name,
        f"{name}评分 {score}，认为当前环节还不够稳。",
        clean_text("；".join(str(item) for item in suggestions[:2]) or "；".join(str(item) for item in findings[:2])),
    )


def _stage_gate_score(values: Iterable[Any], default: int = 0) -> int:
    scores: list[int] = []
    for value in values:
        try:
            score = int(float(value or 0))
        except (ValueError, TypeError):
            continue
        if score > 0:
            scores.append(score)
    return min(scores) if scores else default


def stage_gate_source_fingerprint(project_id: int, key: str) -> str:
    content = storage.get_content(project_id)
    if key == "content_gate":
        payload = {
            "rule_version": STAGE_GATE_RULE_VERSIONS[key],
            "content": visual_brief_source_hash(content),
            "brief": semantic_text_hash(storage.get_brief(project_id)),
            "references": semantic_text_hash(storage.get_references(project_id)),
        }
        return semantic_text_hash(payload)
    if key == "visual_prompt_gate":
        manifest = storage.read_json(visual_prompt_manifest_path(project_id), {})
        project = storage.get_project(project_id)
        payload = {
            "rule_version": STAGE_GATE_RULE_VERSIONS[key],
            "content": visual_prompt_manifest_identity(project, content).get("content_hash"),
            "policy": IMAGE_PROMPT_POLICY_VERSION,
            "manifest": semantic_text_hash(manifest),
        }
        return semantic_text_hash(payload)
    if key == "pre_video_gate":
        snapshots = production_artifact_snapshots(project_id)
        hashes = production_source_hashes(project_id, snapshots)

        def file_stamp(path: Path) -> dict[str, Any]:
            if not path.exists():
                return {"exists": False}
            stat = path.stat()
            return {"exists": True, "size": stat.st_size, "mtime_ns": stat.st_mtime_ns}

        payload = {
            "rule_version": STAGE_GATE_RULE_VERSIONS[key],
            "audio": hashes.get("audio_hash"),
            "subtitles": hashes.get("subtitles_hash"),
            "scene_plan": hashes.get("scene_plan_hash"),
            "scene_images": hashes.get("scene_images_hash"),
            "covers": hashes.get("covers_hash"),
            "bgm": hashes.get("bgm_hash"),
            "image_review": file_stamp(_image_review_path(project_id)),
            "scene_records": file_stamp(storage.project_file(project_id, "scenes/scene_prompts.json")),
            "prompt_policy": IMAGE_PROMPT_POLICY_VERSION,
            "mix_policy": BGM_MIX_POLICY_VERSION,
        }
        return semantic_text_hash(payload)
    return semantic_text_hash(
        {
            "key": key,
            "rule_version": STAGE_GATE_RULE_VERSIONS.get(key, "1"),
            "content": visual_brief_source_hash(content),
        }
    )


def _stage_gate_eval_payload(
    project_id: int,
    key: str,
    score: int,
    passed: bool,
    issues: list[dict[str, Any]],
    details: dict[str, Any],
) -> dict[str, Any]:
    definition = STAGE_GATE_DEFS.get(key, {"label": key, "desc": ""})
    return {
        "key": key,
        "label": definition.get("label", key),
        "desc": definition.get("desc", ""),
        "score": int(clamp_number(score, 0, 100)),
        "passed": bool(passed),
        "status": "passed" if passed else "needs_fix",
        "issues": issues[:8],
        "details": details,
        "checked_at": storage.now_ts(),
        "project_id": project_id,
        "source_fingerprint": stage_gate_source_fingerprint(project_id, key),
    }


def evaluate_production_stage_gate(
    project_id: int,
    key: str,
    content: str | None = None,
    *,
    prefer_ai: bool = False,
) -> dict[str, Any]:
    content_text = content if content is not None else storage.get_content(project_id)
    if key == "content_gate":
        project = storage.get_project(project_id)
        template_key = clean_text(project.get("template") or "")
        template = storage.get_template(template_key) if template_key else {}
        brief = storage.get_brief(project_id)
        references = storage.get_references(project_id)
        editorial_content = content_for_editorial_quality(content_text) or content_text
        supervisors = ai_supervisor_report(project_id, editorial_content, prefer_ai=prefer_ai)
        rhythm = script_rhythm_report(project_id, content_text)
        content_report = content_quality_report(
            project,
            template,
            brief,
            editorial_content,
            references,
            source_content=content_text,
        )
        teacher_keys = ["topic_teacher", "script_teacher", "fact_teacher"]
        teachers = [_stage_gate_teacher(supervisors, item) for item in teacher_keys]
        teacher_scores = [int(item.get("score", 0) or 0) for item in teachers if item]
        issues: list[dict[str, Any]] = []
        supervisor_error = clean_text(str(supervisors.get("ai_error") or ""))
        if supervisor_error:
            issues.append(
                quality_issue(
                    "warn",
                    "AI 老师团",
                    f"{user_facing_error(supervisor_error)} 本轮评分已使用本地规则完成。",
                    "检查 DeepSeek 余额或密钥；本地检查通过时仍可继续生产。",
                )
            )
        for teacher in teachers:
            issue = _stage_gate_teacher_issue(teacher)
            if issue:
                issues.append(issue)
        rhythm_issues = rhythm.get("issues") if isinstance(rhythm.get("issues"), list) else []
        content_issues = content_report.get("issues") if isinstance(content_report.get("issues"), list) else []
        editorial_issues = [
            item
            for item in content_issues
            if isinstance(item, dict)
            and not any(token in clean_text(str(item.get("where") or "")) for token in ("场景图", "图片", "封面", "视觉"))
        ]
        for item in [*rhythm_issues, *editorial_issues]:
            if isinstance(item, dict) and item.get("level") in {"risk", "warn"}:
                issues.append(item)
        editorial_quality_score = quality_score_from_issues(editorial_issues)
        score = _stage_gate_score(
            [rhythm.get("score"), editorial_quality_score, *teacher_scores],
            default=int(supervisors.get("overall_score", supervisors.get("score", 0)) or 0),
        )
        engagement = content_report.get("engagement") if isinstance(content_report.get("engagement"), dict) else {}
        engagement_passed = (
            float(engagement.get("overall_score", 0) or 0) >= CONTENT_OVERALL_MIN_SCORE
            and float(engagement.get("opening_score", 0) or 0) >= CONTENT_OPENING_MIN_SCORE
            and float(engagement.get("retention_score", 0) or 0) >= CONTENT_RETENTION_MIN_SCORE
            and float(engagement.get("interaction_score", 0) or 0) >= CONTENT_INTERACTION_MIN_SCORE
        )
        passed = score >= CONTENT_GATE_MIN_SCORE and engagement_passed and not any(item.get("level") == "risk" for item in issues)
        return _stage_gate_eval_payload(
            project_id,
            key,
            score,
            passed,
            issues,
            {
                "supervisors": {
                    "provider": supervisors.get("provider"),
                    "ai_model": supervisors.get("ai_model"),
                    "teachers": teachers,
                    "ai_error": supervisors.get("ai_error", ""),
                },
                "rhythm_score": rhythm.get("score", 0),
                "content_score": editorial_quality_score,
                "engagement": engagement,
                "required": {
                    "gate_score": CONTENT_GATE_MIN_SCORE,
                    "overall": CONTENT_OVERALL_MIN_SCORE,
                    "opening": CONTENT_OPENING_MIN_SCORE,
                    "retention": CONTENT_RETENTION_MIN_SCORE,
                    "interaction": CONTENT_INTERACTION_MIN_SCORE,
                },
            },
        )

    if key == "visual_prompt_gate":
        reuse_report = storage.get_report(project_id, "image_reuse")
        review = image_review_status(project_id)
        content_path = storage.project_file(project_id, "content.md")
        content_mtime = content_path.stat().st_mtime if content_path.exists() else 0.0
        reuse_saved_at = 0.0
        if isinstance(reuse_report, dict):
            try:
                reuse_saved_at = float(reuse_report.get("saved_at") or 0)
            except (ValueError, TypeError):
                reuse_saved_at = 0.0
        reuse_is_current = bool(reuse_saved_at and (not content_mtime or reuse_saved_at + 0.5 >= content_mtime))
        if (
            isinstance(reuse_report, dict)
            and reuse_report.get("skip_prompt_preflight")
            and reuse_report.get("reuse_confirmed")
            and review.get("can_generate_video")
            and reuse_is_current
        ):
            payload = _stage_gate_eval_payload(
                project_id,
                key,
                100,
                True,
                [],
                {
                    "skipped_reason": "已选择复用旧图，本轮不会调用图片接口，因此不再对生图提示词打分。",
                    "image_reuse": reuse_report,
                    "image_review": review,
                },
            )
            payload["status"] = "skipped_reuse"
            payload["verdict"] = "复用旧图，跳过提示词评分"
            return payload

        supervisors = ai_supervisor_report(project_id, content_text, prefer_ai=prefer_ai)
        visual_teacher = _stage_gate_teacher(supervisors, "visual_teacher")
        layers = image_prompt_layer_report(project_id, content_text)
        director = visual_director_quality_report(project_id, content_text)
        metrics = layers.get("metrics", {}) if isinstance(layers.get("metrics"), dict) else {}
        issues: list[dict[str, Any]] = []
        supervisor_error = clean_text(str(supervisors.get("ai_error") or ""))
        if supervisor_error:
            issues.append(
                quality_issue(
                    "warn",
                    "AI 视觉老师",
                    f"{user_facing_error(supervisor_error)} 本轮提示词评分已使用本地视觉规则完成。",
                    "检查 DeepSeek 余额或密钥；本地检查通过时仍可继续生成图片。",
                )
            )
        weak_count = int(metrics.get("weak_prompt_count", 0) or 0)
        repeated = metrics.get("repeated_style_tokens", [])
        layer_score = int(layers.get("score", 0) or 0)
        director_score = int(director.get("score", 0) or 0)
        teacher_score = int(visual_teacher.get("score", 0) or 0) if visual_teacher else 0
        teacher_text = clean_text(
            "；".join(
                str(item)
                for item in [
                    *(visual_teacher.get("findings") if isinstance(visual_teacher.get("findings"), list) else []),
                    *(visual_teacher.get("suggestions") if isinstance(visual_teacher.get("suggestions"), list) else []),
                ]
            )
        )
        local_prompt_evidence_ok = layer_score >= 78 and weak_count == 0 and int(metrics.get("prompt_count", 0) or 0) > 0
        teacher_hallucinated_missing_prompts = bool(
            local_prompt_evidence_ok
            and any(
                token in teacher_text
                for token in (
                    "没有图片提示词",
                    "未提供任何图片提示词",
                    "未包含任何图片提示词",
                    "没有识别到图片提示词",
                    "缺乏具体视觉提示词",
                    "无法评估是否对齐",
                )
            )
        )
        teacher_issue = _stage_gate_teacher_issue(visual_teacher)
        if teacher_issue and not teacher_hallucinated_missing_prompts:
            issues.append(teacher_issue)
        for source in (layers, director):
            for item in source.get("issues", []) if isinstance(source.get("issues", []), list) else []:
                if isinstance(item, dict) and item.get("level") in {"risk", "warn"}:
                    issues.append(item)
        score_inputs = [layer_score, director_score]
        if visual_teacher and not teacher_hallucinated_missing_prompts:
            score_inputs.append(teacher_score)
        score = _stage_gate_score(
            score_inputs,
            default=layer_score,
        )
        # A channel-level art direction is expected to repeat across an episode.
        # Repetition is advisory only; scene subjects/actions carry the variety.
        passed = score >= 78 and weak_count == 0 and not any(item.get("level") == "risk" for item in issues)
        return _stage_gate_eval_payload(
            project_id,
            key,
            score,
            passed,
            issues,
            {
                "supervisors": {
                    "provider": supervisors.get("provider"),
                    "ai_model": supervisors.get("ai_model"),
                    "teachers": [visual_teacher] if visual_teacher else [],
                    "ai_error": supervisors.get("ai_error", ""),
                },
                "image_layer_score": layer_score,
                "director_score": director_score,
                "weak_prompt_count": weak_count,
                "repeated_style_tokens": repeated,
                "ai_visual_teacher_ignored": teacher_hallucinated_missing_prompts,
            },
        )

    if key == "pre_video_gate":
        project = storage.get_project(project_id)
        template_key = clean_text(project.get("template") or "")
        template = storage.get_template(template_key) if template_key else {}
        preflight = video_preflight_report(project_id)
        review = image_review_status(project_id)
        image_report = image_director_report(project_id, project, template, content_text)
        blockers = preflight.get("blockers") if isinstance(preflight.get("blockers"), list) else []
        warnings = preflight.get("warnings") if isinstance(preflight.get("warnings"), list) else []
        issues = [item for item in [*blockers, *warnings] if isinstance(item, dict)]
        image_issues = image_report.get("issues") if isinstance(image_report.get("issues"), list) else []
        ignored_image_issues = image_report.get("ignored_issues") if isinstance(image_report.get("ignored_issues"), list) else []
        image_override = image_report.get("image_quality_override") if isinstance(image_report.get("image_quality_override"), dict) else image_quality_override_status(project_id)
        for item in image_issues:
            if isinstance(item, dict) and item.get("level") in {"risk", "warn"}:
                issues.append(item)
        if not review.get("can_generate_video"):
            issues.append(
                quality_issue(
                    "risk",
                    "图片确认",
                    "当前场景图/封面图还没有确认通过。",
                    "先检查图片效果，满意后点击确认当前图片。",
                )
            )
        warning_penalty_count = pre_video_warning_penalty_count(warnings)
        preflight_score = int(
            clamp_number(
                100
                - len(blockers) * 30
                - warning_penalty_count * 8
                - (0 if review.get("can_generate_video") else 20),
                0,
                100,
            )
        )
        raw_image_score = int(image_report.get("score", 0) or 0)
        image_hard_risk = any(
            pre_video_image_issue_is_hard(item)
            for item in image_issues
            if isinstance(item, dict)
        )
        image_score = max(raw_image_score, 72) if image_override.get("active") and ignored_image_issues and not image_hard_risk else raw_image_score
        asset_ready = bool(preflight.get("passed")) and bool(review.get("can_generate_video")) and not blockers
        soft_image_only = asset_ready and not image_hard_risk and bool(image_issues)
        effective_image_score = max(image_score, 72) if soft_image_only else image_score
        score = _stage_gate_score([preflight_score, effective_image_score], default=preflight_score)
        passed = (
            bool(preflight.get("passed"))
            and bool(review.get("can_generate_video"))
            and effective_image_score >= 72
            and not image_hard_risk
        )
        payload = _stage_gate_eval_payload(
            project_id,
            key,
            score,
            passed,
            issues,
            {
                "preflight": preflight,
                "image_review": review,
                "image_score": effective_image_score,
                "raw_image_score": raw_image_score,
                "image_metrics": image_report.get("metrics", {}),
                "image_quality_override": image_override,
                "ignored_image_soft_issue_count": len(ignored_image_issues),
                "soft_image_only": soft_image_only,
                "warning_penalty_count": warning_penalty_count,
            },
        )
        if passed and soft_image_only and raw_image_score < 72:
            payload["status"] = "accepted_with_warnings"
            payload["verdict"] = "资产齐全，图片弱项作为提醒通过，允许进入成片合成"
        return payload

    raise ValueError(f"未知生产前闸门：{key}")


def _stage_gates_report_base(project_id: int) -> dict[str, Any]:
    raw = storage.get_report(project_id, "stage_gates")
    if not isinstance(raw, dict):
        raw = {}
    gates = raw.get("gates") if isinstance(raw.get("gates"), dict) else {}
    return {
        "generated_at": raw.get("generated_at") or storage.now_ts(),
        "project_id": project_id,
        "topic": storage.get_project(project_id).get("topic_name", ""),
        "definitions": STAGE_GATE_DEFS,
        "gates": gates,
        "history": raw.get("history") if isinstance(raw.get("history"), list) else [],
    }


def save_stage_gate_result(project_id: int, result: dict[str, Any]) -> dict[str, Any]:
    report = _stage_gates_report_base(project_id)
    gates = report["gates"]
    gates[str(result.get("key") or "")] = result
    history = report["history"]
    history.append(
        {
            "key": result.get("key"),
            "label": result.get("label"),
            "status": result.get("status"),
            "score": result.get("score"),
            "checked_at": result.get("checked_at") or storage.now_ts(),
            "actions": result.get("actions", []),
        }
    )
    report["history"] = history[-30:]
    report["generated_at"] = storage.now_ts()
    storage.save_report(project_id, "stage_gates", report)
    return report


def production_stage_gates_dashboard(project_id: int) -> dict[str, Any]:
    report = _stage_gates_report_base(project_id)
    ordered = []
    for key, definition in STAGE_GATE_DEFS.items():
        current = report["gates"].get(key)
        if not isinstance(current, dict):
            current = {
                "key": key,
                "label": definition.get("label", key),
                "desc": definition.get("desc", ""),
                "status": "pending",
                "score": 0,
                "passed": False,
                "issues": [],
                "details": {},
            }
        elif clean_text(str(current.get("status") or "")) != "pending":
            stored_fingerprint = clean_text(str(current.get("source_fingerprint") or ""))
            expected_fingerprint = stage_gate_source_fingerprint(project_id, key)
            if not stored_fingerprint or stored_fingerprint != expected_fingerprint:
                changed_label = "输入资产" if key == "pre_video_gate" else "文案或提示词"
                current = {
                    **current,
                    "passed": False,
                    "status": "stale",
                    "stale": True,
                    "verdict": f"{changed_label}已更新，上一轮评分已失效，等待重新检查。",
                    "issues": [
                        quality_issue(
                            "info",
                            f"{changed_label}更新",
                            f"{changed_label}已在上次闸门检查后变化。",
                            "重新运行检查，页面不会再把旧分数当作当前结果；如果输入没有变化，系统会直接复用已通过结果。",
                        )
                    ],
                }
        ordered.append(current)
    report["ordered_gates"] = ordered
    return report


def cached_stage_gate_result(project_id: int, key: str) -> dict[str, Any] | None:
    report = _stage_gates_report_base(project_id)
    current = report.get("gates", {}).get(key) if isinstance(report.get("gates"), dict) else None
    if not isinstance(current, dict):
        return None
    if clean_text(str(current.get("status") or "")) in {"", "pending", "stale", "running", "fixing"}:
        return None
    stored = clean_text(str(current.get("source_fingerprint") or ""))
    if not stored or stored != stage_gate_source_fingerprint(project_id, key):
        return None
    return {**current, "cache_hit": True, "reused_at": storage.now_ts()}


def evaluate_all_production_stage_gates(project_id: int, *, force: bool = False) -> dict[str, Any]:
    evaluated: list[str] = []
    reused: list[str] = []
    for key in STAGE_GATE_DEFS:
        cached = None if force else cached_stage_gate_result(project_id, key)
        if cached is not None:
            reused.append(key)
            continue
        result = evaluate_production_stage_gate(project_id, key)
        save_stage_gate_result(project_id, result)
        evaluated.append(key)
    dashboard = production_stage_gates_dashboard(project_id)
    dashboard["cache"] = {
        "evaluated": evaluated,
        "reused": reused,
        "hit_count": len(reused),
        "miss_count": len(evaluated),
    }
    return dashboard


def stage_gate_has_hard_risk(result: dict[str, Any]) -> bool:
    issues = result.get("issues") if isinstance(result.get("issues"), list) else []
    return any(isinstance(item, dict) and item.get("level") == "risk" for item in issues)


PRE_VIDEO_NON_BLOCKING_IMAGE_TERMS = (
    "旧提示词策略",
    "贴合偏弱",
    "吸引力不足",
)


def pre_video_warning_penalty_count(warnings: list[dict[str, Any]]) -> int:
    regular_count = 0
    has_legacy_policy_warning = False
    for item in warnings:
        if not isinstance(item, dict):
            continue
        text = clean_text(
            " ".join(str(item.get(key) or "") for key in ("where", "issue", "fix"))
        )
        if "旧提示词策略" in text:
            has_legacy_policy_warning = True
        else:
            regular_count += 1
    return regular_count + int(has_legacy_policy_warning)


def pre_video_image_issue_is_hard(issue: dict[str, Any]) -> bool:
    if clean_text(str(issue.get("level") or "")) != "risk":
        return False
    text = clean_text(
        " ".join(str(issue.get(key) or "") for key in ("where", "issue", "fix"))
    )
    if any(term in text for term in PRE_VIDEO_NON_BLOCKING_IMAGE_TERMS):
        return False
    return not is_ignorable_image_quality_issue(issue)


def stage_gate_can_continue_with_warnings(key: str, result: dict[str, Any]) -> bool:
    score = int(result.get("score", 0) or 0)
    if stage_gate_has_hard_risk(result):
        return False
    if key == "content_gate":
        # Subjective teacher/retention scores remain visible as warnings, but
        # must not deadlock a fully automatic run after the repair pass.
        return score >= 55
    if key == "visual_prompt_gate":
        details = result.get("details") if isinstance(result.get("details"), dict) else {}
        weak_count = int(details.get("weak_prompt_count", 0) or 0)
        return score >= 70 and weak_count <= 1
    return False


CONTENT_REWRITEABLE_GATE_TOKENS = (
    "开头",
    "钩子",
    "中段",
    "留存",
    "节奏",
    "互动",
    "重复",
    "套话",
    "表达",
    "长句",
    "脚本",
)


def content_gate_has_rewriteable_issues(result: dict[str, Any]) -> bool:
    issues = result.get("issues") if isinstance(result.get("issues"), list) else []
    for item in issues:
        if not isinstance(item, dict):
            continue
        source = clean_text(f"{item.get('where', '')} {item.get('issue', '')}")
        if any(token in source for token in CONTENT_REWRITEABLE_GATE_TOKENS):
            return True
    return False


def accept_stage_gate_with_warnings(result: dict[str, Any]) -> dict[str, Any]:
    accepted = dict(result)
    accepted["passed"] = True
    accepted["status"] = "accepted_with_warnings"
    accepted["verdict"] = "带提醒通过，继续下一步"
    accepted["accepted_with_warnings"] = True
    return accepted


def pre_video_gate_repair_targets(result: dict[str, Any]) -> list[tuple[str, str]]:
    targets: list[tuple[str, str]] = []
    seen: set[str] = set()
    issues = result.get("issues") if isinstance(result.get("issues"), list) else []
    repair_signals = (
        "贴合偏弱",
        "吸引力不足",
        "图片自检硬失败",
        "跨题材",
        "旧项目词",
        "旧提示词策略",
        "提示词污染",
    )
    for item in issues:
        if not isinstance(item, dict):
            continue
        where = clean_text(str(item.get("where") or "")).replace("\\", "/")
        issue_text = clean_text(str(item.get("issue") or ""))
        if not any(signal in issue_text for signal in repair_signals):
            continue
        scene_match = re.fullmatch(r"scenes/(s_\d+\.(?:png|jpg|jpeg|webp))", where, flags=re.IGNORECASE)
        cover_match = re.fullmatch(r"covers/(cover_(?:landscape|story|portrait)\.(?:png|jpg|jpeg|webp))", where, flags=re.IGNORECASE)
        if scene_match:
            key = f"scene:{scene_match.group(1).lower()}"
            if key not in seen:
                targets.append(("scene", scene_match.group(1)))
                seen.add(key)
        elif cover_match:
            key = f"cover:{cover_match.group(1).lower()}"
            if key not in seen:
                targets.append(("cover", cover_match.group(1)))
                seen.add(key)
    return targets


def pre_video_target_has_only_legacy_policy_issue(
    result: dict[str, Any],
    kind: str,
    target: str,
) -> bool:
    expected_where = f"scenes/{target}" if kind == "scene" else f"covers/{target}"
    matching: list[str] = []
    issues = result.get("issues") if isinstance(result.get("issues"), list) else []
    for item in issues:
        if not isinstance(item, dict):
            continue
        where = clean_text(str(item.get("where") or "")).replace("\\", "/")
        if where.lower() != expected_where.lower():
            continue
        matching.append(clean_text(str(item.get("issue") or "")))
    return bool(matching) and all("旧提示词策略" in issue for issue in matching)


def stage_gate_repair_steps(key: str, result: dict[str, Any]) -> list[str]:
    if key != "pre_video_gate":
        return []
    requested: set[str] = set()
    issues = result.get("issues") if isinstance(result.get("issues"), list) else []
    for item in issues:
        if not isinstance(item, dict):
            continue
        where = clean_text(str(item.get("where") or ""))
        issue = clean_text(str(item.get("issue") or ""))
        text = f"{where} {issue}".lower()
        if any(token in text for token in ("podcast.mp3", "音频版本", "缺少音频", "配音过期", "音频早于")):
            requested.update({"audio", "subtitles"})
        elif any(token in text for token in ("subtitles.srt", "字幕版本", "字幕覆盖", "字幕过期", "缺少字幕", "字幕早于")):
            requested.add("subtitles")
        # A scene path only identifies where an issue occurred; it does not
        # mean the file is missing.  Soft quality scores and prompt-policy
        # versions are handled on the image page and must never reopen the
        # image provider from inside video composition.
        if any(token in text for token in ("缺少场景图", "场景图缺失", "场景图不完整", "找不到场景图")):
            requested.add("images_missing")
        if any(token in text for token in ("缺少封面", "封面缺失", "封面图缺失", "封面不完整")):
            requested.add("covers_missing")
        if any(token in text for token in ("bgm", "背景音乐", "音乐版本", "重新匹配")):
            requested.add("bgm")
    if "audio" in requested:
        requested.add("subtitles")
    order = ("audio", "subtitles", "images_missing", "covers_missing", "bgm")
    return [item for item in order if item in requested]


def project_image_repair_prompt(project_id: int, kind: str, target: str) -> str:
    if kind == "scene":
        filename = normalize_scene_image_filename(target)
        report = storage.get_report(project_id, "scene_prompt_preflight")
        final_prompts = report.get("final_prompts") if isinstance(report, dict) and isinstance(report.get("final_prompts"), dict) else {}
        prompt = clean_text(str(final_prompts.get(filename) or ""))
        if prompt:
            return prompt
        records = storage.read_json(storage.project_file(project_id, "scenes/scene_prompts.json"), [])
        if isinstance(records, list):
            for record in records:
                if isinstance(record, dict) and clean_text(str(record.get("filename") or "")) == filename:
                    prompt = clean_text(str(record.get("prompt") or record.get("source_prompt") or ""))
                    if prompt:
                        return prompt
        project = storage.get_project(project_id)
        content = storage.get_content(project_id)
        prompts = current_scene_prompts(
            project_id,
            content,
            clean_text(str(project.get("template_mode") or "video")),
            clean_text(str(project.get("topic_name") or "")),
            prefer_timeline=True,
        )
        index = image_target_scene_index(filename)
        return prompts[index - 1] if 0 < index <= len(prompts) else ""

    cover = normalize_cover_target(target)
    output_path = storage.project_file(project_id, f"covers/{cover['filename']}")
    prompt_path = output_path.with_suffix(".md")
    if prompt_path.exists():
        prompt = clean_text(storage.read_text(prompt_path))
        if prompt:
            return prompt
    report = storage.get_report(project_id, "cover_prompt_preflight")
    final_prompts = report.get("final_prompts") if isinstance(report, dict) and isinstance(report.get("final_prompts"), dict) else {}
    return clean_text(str(final_prompts.get(str(cover["filename"])) or ""))


def emit_stage_gate_progress(
    callback: Callable[[dict[str, Any]], None] | None,
    phase: str,
    message: str,
    **details: Any,
) -> None:
    if callback is None:
        return
    payload = {
        "phase": clean_text(phase),
        "message": clean_text(message),
        "updated_at": storage.now_ts(),
        **details,
    }
    try:
        callback(payload)
    except Exception:
        pass


def run_production_stage_gate(
    project_id: int,
    key: str,
    *,
    auto_fix: bool = True,
    progress_callback: Callable[[dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    before = cached_stage_gate_result(project_id, key)
    if before is not None:
        emit_stage_gate_progress(
            progress_callback,
            "cache_hit",
            f"输入未变化，已复用上次 {int(before.get('score', 0) or 0)} 分检查结果",
            score=int(before.get("score", 0) or 0),
            cache_hit=True,
        )
    else:
        emit_stage_gate_progress(progress_callback, "checking", "正在读取最新内容、规则和已有质量报告")
        before = evaluate_production_stage_gate(project_id, key)
    before_issues = before.get("issues") if isinstance(before.get("issues"), list) else []
    emit_stage_gate_progress(
        progress_callback,
        "checked",
        f"初检完成：{int(before.get('score', 0) or 0)} 分，发现 {len(before_issues)} 项待处理",
        score=int(before.get("score", 0) or 0),
        issue_count=len(before_issues),
    )
    result = {
        **before,
        "status": "passed" if before.get("passed") else ("fixing" if auto_fix else "failed"),
        "before": before,
        "after": before,
        "actions": [],
        "content_changed": False,
    }
    if before.get("passed"):
        emit_stage_gate_progress(progress_callback, "complete", "当前闸门已经通过，无需修改", score=int(before.get("score", 0) or 0))
        save_stage_gate_result(project_id, result)
        return result

    if not auto_fix:
        emit_stage_gate_progress(progress_callback, "complete", "检查完成，等待处理未通过项", score=int(before.get("score", 0) or 0))
        save_stage_gate_result(project_id, result)
        return result

    try:
        if key == "content_gate":
            emit_stage_gate_progress(progress_callback, "rule_repair", "正在修复平台风险与事实一致性")
            risk_fix = repair_project_platform_risk(project_id)
            if risk_fix.get("changed"):
                hits = ", ".join(str(item) for item in risk_fix.get("hits", [])[:8])
                result["actions"].append(f"平台风险自动降敏：{hits}")
                result["content_changed"] = True
            fact_fix = repair_project_fact_compliance(project_id)
            if fact_fix.get("changed"):
                hits = ", ".join(str(item) for item in fact_fix.get("hits", [])[:8])
                result["actions"].append(f"事实合规自动修正：{hits}")
                result["content_changed"] = True
            numeric_fix = repair_project_unsupported_numeric_facts(project_id)
            if numeric_fix.get("changed"):
                hits = ", ".join(str(item) for item in numeric_fix.get("hits", [])[:8])
                result["actions"].append(f"无来源精确数字改为定性表达：{hits}")
                result["content_changed"] = True
            after = evaluate_production_stage_gate(project_id, key)
            result["after"] = after
            if after.get("passed"):
                result["actions"].append("平台/事实合规复检通过")
            elif content_gate_has_rewriteable_issues(after):
                if risk_fix.get("changed") or fact_fix.get("changed"):
                    result["actions"].append("平台/事实合规复检仍未完全通过，继续自动总编优化")
                result["actions"].append("节奏增强并同步重建图片提示词")
                emit_stage_gate_progress(progress_callback, "rhythm_rewrite", "规则修复后仍未通过，正在增强开头、节奏和信息密度")
                enhanced = enhance_content_rhythm(project_id, save=True)
                result["content_changed"] = result["content_changed"] or bool(enhanced.get("content"))
                risk_fix = repair_project_platform_risk(project_id)
                if risk_fix.get("changed"):
                    hits = ", ".join(str(item) for item in risk_fix.get("hits", [])[:8])
                    result["actions"].append(f"节奏增强后再次降敏：{hits}")
                    result["content_changed"] = True
                fact_fix = repair_project_fact_compliance(project_id)
                if fact_fix.get("changed"):
                    hits = ", ".join(str(item) for item in fact_fix.get("hits", [])[:8])
                    result["actions"].append(f"节奏增强后事实合规修正：{hits}")
                    result["content_changed"] = True
                numeric_fix = repair_project_unsupported_numeric_facts(project_id)
                if numeric_fix.get("changed"):
                    hits = ", ".join(str(item) for item in numeric_fix.get("hits", [])[:8])
                    result["actions"].append(f"节奏增强后移除无来源精确数字：{hits}")
                    result["content_changed"] = True
                after = evaluate_production_stage_gate(project_id, key)
                result["after"] = after
                if (
                    not after.get("passed")
                    and content_gate_has_rewriteable_issues(after)
                    and clean_text(runtime_env().get("DEEPSEEK_API_KEY", ""))
                ):
                    emit_stage_gate_progress(
                        progress_callback,
                        "ai_rewrite",
                        f"正在调用一次 AI 总编改稿；最长等待 {deepseek_rewrite_timeout_seconds(runtime_env())} 秒，超时会保留本地优化结果",
                    )
                    optimized = optimize_project_content(project_id)
                    if optimized.get("provider") == "deepseek":
                        result["actions"].append("DeepSeek 总编改稿并复检")
                    else:
                        ai_error = user_facing_error(str(optimized.get("deepseek_error") or "AI 总编调用失败"))
                        result["actions"].append(f"DeepSeek 总编未执行：{ai_error}")
                        emit_stage_gate_progress(progress_callback, "ai_unavailable", ai_error)
                    result["content_changed"] = result["content_changed"] or bool(optimized.get("changed"))
                    risk_fix = repair_project_platform_risk(project_id)
                    if risk_fix.get("changed"):
                        hits = ", ".join(str(item) for item in risk_fix.get("hits", [])[:8])
                        result["actions"].append(f"总编改稿后再次降敏：{hits}")
                        result["content_changed"] = True
                    fact_fix = repair_project_fact_compliance(project_id)
                    if fact_fix.get("changed"):
                        hits = ", ".join(str(item) for item in fact_fix.get("hits", [])[:8])
                        result["actions"].append(f"总编改稿后事实合规修正：{hits}")
                        result["content_changed"] = True
                    numeric_fix = repair_project_unsupported_numeric_facts(project_id)
                    if numeric_fix.get("changed"):
                        hits = ", ".join(str(item) for item in numeric_fix.get("hits", [])[:8])
                        result["actions"].append(f"总编改稿后移除无来源精确数字：{hits}")
                        result["content_changed"] = True
                    after = evaluate_production_stage_gate(project_id, key)
                    result["after"] = after
                if not after.get("passed") and content_gate_has_rewriteable_issues(after):
                    result["actions"].append("二次节奏校准并复检")
                    emit_stage_gate_progress(progress_callback, "second_rewrite", "首次改稿仍未通过，正在进行第二轮节奏校准")
                    enhanced_again = enhance_content_rhythm(project_id, save=True)
                    result["content_changed"] = result["content_changed"] or bool(enhanced_again.get("content"))
                    risk_fix = repair_project_platform_risk(project_id)
                    if risk_fix.get("changed"):
                        hits = ", ".join(str(item) for item in risk_fix.get("hits", [])[:8])
                        result["actions"].append(f"二次校准后再次降敏：{hits}")
                        result["content_changed"] = True
                    fact_fix = repair_project_fact_compliance(project_id)
                    if fact_fix.get("changed"):
                        hits = ", ".join(str(item) for item in fact_fix.get("hits", [])[:8])
                        result["actions"].append(f"二次校准后事实合规修正：{hits}")
                        result["content_changed"] = True
                    numeric_fix = repair_project_unsupported_numeric_facts(project_id)
                    if numeric_fix.get("changed"):
                        hits = ", ".join(str(item) for item in numeric_fix.get("hits", [])[:8])
                        result["actions"].append(f"二次校准后移除无来源精确数字：{hits}")
                        result["content_changed"] = True
                    after = evaluate_production_stage_gate(project_id, key)
                    result["after"] = after
                elif not after.get("passed"):
                    result["actions"].append("剩余阻断项需要补充来源或人工确认，已跳过无关的 AI 改稿")
                    emit_stage_gate_progress(
                        progress_callback,
                        "needs_attention",
                        "自动修复已结束；剩余问题不能靠改写解决，请按阻断项补充依据",
                    )
                duration_fix = compress_content_to_retention_budget(project_id, save=True)
                if duration_fix.get("changed"):
                    before_duration = float(duration_fix.get("before_duration_sec") or 0)
                    after_duration = float(duration_fix.get("after_duration_sec") or 0)
                    result["actions"].append(
                        f"按频道时长预算压缩口播：约 {before_duration:.0f} 秒 -> {after_duration:.0f} 秒"
                    )
                    result["content_changed"] = True
                    emit_stage_gate_progress(
                        progress_callback,
                        "duration_fit",
                        f"口播已压到频道目标时长：约 {after_duration:.0f} 秒，正在复检",
                    )
                    after = evaluate_production_stage_gate(project_id, key)
                    result["after"] = after
            else:
                result["actions"].append("剩余阻断项需要补充来源或人工确认，已跳过无关的节奏与 AI 改稿")
                emit_stage_gate_progress(
                    progress_callback,
                    "needs_attention",
                    "自动修复已结束；剩余问题不能靠改写解决，请按阻断项补充依据",
                )
        elif key == "visual_prompt_gate":
            result["actions"].append("重建场景图/封面提示词")
            emit_stage_gate_progress(progress_callback, "prompt_rebuild", "正在根据主题和逐段口播重建图片提示词")
            repaired = repair_image_prompt_section(project_id)
            result["content_changed"] = bool(repaired.get("content"))
            after = evaluate_production_stage_gate(project_id, key)
            result["after"] = after
        elif key == "pre_video_gate":
            working_report = before

            def has_rhythm_blocker(report: dict[str, Any]) -> bool:
                return any(
                    clean_text(str(item.get("where") or "")) == "文案节奏"
                    or "节奏体检" in clean_text(str(item.get("issue") or ""))
                    for item in report.get("issues", [])
                    if isinstance(item, dict)
                )

            if has_rhythm_blocker(working_report):
                emit_stage_gate_progress(
                    progress_callback,
                    "rhythm_rewrite",
                    "成片前发现文案节奏阻断，正在修复开头、长句、中段推进和重复结尾",
                )
                result["actions"].append("成片前节奏增强并合并重复互动结尾")
                enhanced = enhance_content_rhythm(project_id, save=True)
                enhance_result = enhanced.get("result") if isinstance(enhanced.get("result"), dict) else {}
                rhythm_changed = bool(enhance_result.get("changed"))
                result["content_changed"] = result["content_changed"] or rhythm_changed
                working_report = evaluate_production_stage_gate(project_id, key)
                result["after"] = working_report
                if not has_rhythm_blocker(working_report):
                    result["actions"].append("文案节奏阻断已修复")
                elif clean_text(runtime_env().get("DEEPSEEK_API_KEY", "")):
                    emit_stage_gate_progress(
                        progress_callback,
                        "ai_rewrite",
                        f"规则增强后仍未达标，正在调用一次 AI 总编改稿；最长等待 {deepseek_rewrite_timeout_seconds(runtime_env())} 秒",
                    )
                    optimized = optimize_project_content(project_id)
                    if optimized.get("provider") == "deepseek":
                        result["actions"].append("DeepSeek 总编重写开头与中段留存并复检")
                    else:
                        ai_error = user_facing_error(str(optimized.get("deepseek_error") or "AI 总编调用失败"))
                        result["actions"].append(f"DeepSeek 总编未执行：{ai_error}")
                        emit_stage_gate_progress(progress_callback, "ai_unavailable", ai_error)
                    result["content_changed"] = result["content_changed"] or bool(optimized.get("changed"))
                    repair_project_platform_risk(project_id)
                    repair_project_fact_compliance(project_id)
                    working_report = evaluate_production_stage_gate(project_id, key)
                    result["after"] = working_report

            targets = pre_video_gate_repair_targets(working_report)
            if targets:
                emit_stage_gate_progress(
                    progress_callback,
                    "image_prepare",
                    f"已定位 {len(targets)} 张待优化图片，正在准备当前口播提示词",
                    current=0,
                    total=len(targets),
                )
                if any(image_kind == "scene" for image_kind, _target in targets):
                    project = storage.get_project(project_id)
                    content = storage.get_content(project_id)
                    prompts = current_scene_prompts(
                        project_id,
                        content,
                        clean_text(str(project.get("template_mode") or "video")),
                        clean_text(str(project.get("topic_name") or "")),
                        prefer_timeline=True,
                    )
                    preflight_generation_prompt_batch(
                        project_id,
                        [
                            {"target": f"s_{index:02d}.png", "label": f"场景 {index}", "prompt": prompt}
                            for index, prompt in enumerate(prompts, start=1)
                        ],
                        purpose="scene",
                    )
                    result["actions"].append("已先按当前完整口播刷新场景提示词，旧规则和旧镜头词不再复用")
                review_state = image_review_status(project_id)
                manual_image_review = bool(review_state.get("required", True))
                pending_candidate_indexes = {
                    int(item or 0) for item in review_state.get("scene_candidate_pending_indexes", []) if int(item or 0) > 0
                }
                manual_candidates_created = 0
                waiting_for_human = False
                result["actions"].append(
                    f"检测到 {len(targets)} 张低贴合/低吸引力图片，"
                    f"开始逐张 {'生成待审替换图' if manual_image_review else 'AI 比较后自动替换'}"
                )
                for target_index, (image_kind, target) in enumerate(targets, start=1):
                    scene_index = image_target_scene_index(target, target) if image_kind == "scene" else 0
                    if scene_index in pending_candidate_indexes:
                        waiting_for_human = True
                        result["actions"].append(f"{target} 已有 1 张待审替换图，本轮不重复生成")
                        continue
                    if (
                        image_kind == "scene"
                        and scene_index > 0
                        and not manual_image_review
                        and pre_video_target_has_only_legacy_policy_issue(working_report, image_kind, target)
                    ):
                        official_path = storage.project_file(project_id, f"scenes/s_{scene_index:02d}.png")
                        audit = read_image_audit(official_path) if official_path.exists() else {}
                        if official_path.exists() and clean_text(str(audit.get("severity") or "ok")) != "hard":
                            keep_current_scene_image(project_id, scene_index)
                            result["actions"].append(
                                f"{target} 仅为提示词策略版本差异，现有图片自检合格；全自动模式已保留旧图，不额外生图"
                            )
                            continue
                    emit_stage_gate_progress(
                        progress_callback,
                        "image_redraw",
                        f"正在处理 {target_index}/{len(targets)}：{target}",
                        current=target_index,
                        total=len(targets),
                        target=target,
                    )
                    prompt = project_image_repair_prompt(project_id, image_kind, target)
                    if not prompt:
                        result["actions"].append(f"{target} 缺少可用提示词，已跳过")
                        continue
                    prompt = compact_visual_image_prompt(
                        "。".join(
                            [
                                prompt,
                                "自动优化要求：上一版图片被判定与主题或当前口播贴合偏弱，必须更换构图，直接呈现当前完整口播里的核心对象、动作、数字、对比和结论",
                                "画面文字和信息关系由 AI 根据当前口播自由生成，数量、字数和形式不限制，但不得借用其它镜头内容，也不得使用统一黑条或固定模板贴纸",
                            ]
                        ),
                        1100,
                    )
                    if image_kind == "scene" and scene_index > 0:
                        candidate_dir = storage.project_file(project_id, "scenes/candidates")
                        candidate_dir.mkdir(parents=True, exist_ok=True)
                        cleanup_scene_image_candidates(project_id, scene_index)
                        candidate_path = candidate_dir / f"s_{scene_index:02d}_r.png"
                        project = storage.get_project(project_id)
                        template_key = clean_text(str(project.get("template") or ""))
                        template = storage.get_template(template_key) if template_key else {}
                        env = runtime_env()
                        generate_configured_image_safely(
                            prompt,
                            candidate_path,
                            SCENE_IMAGE_SIZE,
                            "scene",
                            env,
                            None,
                            template,
                        )
                        final_prompt = read_generated_prompt(candidate_path, prompt)
                        if manual_image_review:
                            _save_scene_repair_candidate(
                                project_id,
                                scene_index,
                                candidate_path,
                                final_prompt,
                            )
                            manual_candidates_created += 1
                            waiting_for_human = True
                            result["actions"].append(f"{target} 已生成 1 张待审替换图，正式图暂不覆盖")
                        else:
                            official_path = storage.project_file(project_id, f"scenes/s_{scene_index:02d}.png")
                            candidate_score = key_image_candidate_score(
                                project_id,
                                candidate_path,
                                final_prompt,
                                scene_index,
                            )
                            official_score: dict[str, Any] = {"score": -1}
                            if official_path.exists():
                                with contextlib.suppress(Exception):
                                    official_score = key_image_candidate_score(
                                        project_id,
                                        official_path,
                                        read_generated_prompt(official_path, prompt),
                                        scene_index,
                                    )
                            if int(candidate_score.get("score", 0) or 0) >= int(official_score.get("score", -1) or -1):
                                promote_generated_image_candidate(candidate_path, official_path)
                                audit = read_image_audit(candidate_path)
                                _update_scene_prompt_record(project_id, official_path.name, prompt, final_prompt, audit)
                                result["actions"].append(
                                    f"{target} 新图 {candidate_score.get('score', 0)} 分，"
                                    f"高于原图 {official_score.get('score', 0)} 分，已自动替换"
                                )
                            else:
                                result["actions"].append(
                                    f"{target} 原图 {official_score.get('score', 0)} 分更高，已保留正式图"
                                )
                            cleanup_scene_image_candidates(project_id, scene_index)
                    else:
                        redraw = regenerate_project_image(project_id, image_kind, target, prompt)
                        if redraw.get("needs_handoff"):
                            result["actions"].append(f"{target} 已创建 ChatGPT 接力任务，等待图片保存")
                        else:
                            result["actions"].append(f"{target} 已按当前主题和完整口播完成 AI 重绘")
                    emit_stage_gate_progress(
                        progress_callback,
                        "image_redraw",
                        f"已完成 {target_index}/{len(targets)}：{target}",
                        current=target_index,
                        total=len(targets),
                        target=target,
                    )
                result["waiting_for_human"] = waiting_for_human
                result["manual_candidates_created"] = manual_candidates_created
                if waiting_for_human:
                    emit_stage_gate_progress(
                        progress_callback,
                        "waiting_human",
                        f"已生成 {manual_candidates_created} 张待审替换图，请在场景图候选区采用；不会继续批量追加",
                        current=manual_candidates_created,
                        total=manual_candidates_created,
                    )
                else:
                    emit_stage_gate_progress(progress_callback, "rechecking", "图片处理完成，正在重新检查贴合度、OCR 和资产状态")
                result["after"] = evaluate_production_stage_gate(project_id, key)
            else:
                if not working_report.get("passed"):
                    result["actions"].append("未发现可自动重绘的具体图片；保留音频、字幕、缺图或人工确认阻断项")
                    emit_stage_gate_progress(progress_callback, "complete", "未发现可自动重绘的具体图片，已保留其它阻断项")
                result["after"] = working_report
        else:
            result["actions"].append("未知闸门，无自动修复动作")
    except Exception as exc:
        emit_stage_gate_progress(progress_callback, "failed", f"自动优化失败：{user_facing_error(exc)}")
        result["actions"].append(f"自动修复失败：{exc}")
        result["status"] = "failed"
        result["error"] = str(exc)
        save_stage_gate_result(project_id, result)
        return result

    after = result.get("after") if isinstance(result.get("after"), dict) else before
    if not result.get("waiting_for_human") and not after.get("passed") and stage_gate_can_continue_with_warnings(key, after):
        result["actions"].append("仅剩轻微提醒，已带提醒通过并自动进入下一步")
        after = accept_stage_gate_with_warnings(after)
        result["after"] = after
    result["score"] = after.get("score", before.get("score", 0))
    result["passed"] = bool(after.get("passed"))
    result["issues"] = after.get("issues", before.get("issues", []))
    result["details"] = after.get("details", before.get("details", {}))
    result["status"] = "waiting_human" if result.get("waiting_for_human") else (after.get("status") if result["passed"] else "failed")
    if result["status"] not in {"passed", "accepted_with_warnings", "failed", "waiting_human"}:
        result["status"] = "passed" if result["passed"] else "failed"
    result["accepted_with_warnings"] = bool(after.get("accepted_with_warnings"))
    result["checked_at"] = storage.now_ts()
    result["source_fingerprint"] = clean_text(str(after.get("source_fingerprint") or stage_gate_source_fingerprint(project_id, key)))
    emit_stage_gate_progress(
        progress_callback,
        "waiting_human" if result.get("waiting_for_human") else ("complete" if result.get("passed") else "needs_attention"),
        (
            "待审替换图已显示，请采用后再复检"
            if result.get("waiting_for_human")
            else f"复检完成：{int(result.get('score', 0) or 0)} 分，{'已通过' if result.get('passed') else '仍有未通过项'}"
        ),
        score=int(result.get("score", 0) or 0),
        issue_count=len(result.get("issues", [])) if isinstance(result.get("issues"), list) else 0,
    )
    save_stage_gate_result(project_id, result)
    return result


def run_production_stage_gate_closed_loop(
    project_id: int,
    key: str,
    *,
    max_rounds: int = 3,
    auto_fix: bool = True,
    progress_callback: Callable[[dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    rounds: list[dict[str, Any]] = []
    max_rounds = max(1, min(5, int(max_rounds or 3)))
    last_result: dict[str, Any] = {}
    previous_signature = ""

    for round_index in range(1, max_rounds + 1):
        emit_stage_gate_progress(
            progress_callback,
            "round_start",
            f"开始第 {round_index}/{max_rounds} 轮{'自动优化与复检' if auto_fix else '检查'}",
            round=round_index,
            max_rounds=max_rounds,
        )
        result = run_production_stage_gate(
            project_id,
            key,
            auto_fix=auto_fix,
            progress_callback=progress_callback,
        )
        last_result = result
        signature = json.dumps(
            {
                "passed": bool(result.get("passed")),
                "score": int(result.get("score", 0) or 0),
                "status": result.get("status"),
                "issues": [
                    {
                        "level": item.get("level"),
                        "where": item.get("where"),
                        "issue": item.get("issue"),
                    }
                    for item in result.get("issues", [])[:8]
                    if isinstance(item, dict)
                ],
                "actions": result.get("actions", [])[:8] if isinstance(result.get("actions"), list) else [],
            },
            ensure_ascii=False,
            sort_keys=True,
        )
        rounds.append(
            {
                "round": round_index,
                "score": int(result.get("score", 0) or 0),
                "passed": bool(result.get("passed")),
                "status": result.get("status"),
                "actions": result.get("actions", []) if isinstance(result.get("actions"), list) else [],
                "issue_count": len(result.get("issues", [])) if isinstance(result.get("issues"), list) else 0,
            }
        )
        emit_stage_gate_progress(
            progress_callback,
            "round_complete",
            f"第 {round_index} 轮完成：{int(result.get('score', 0) or 0)} 分，{'已通过' if result.get('passed') else '仍需处理'}",
            round=round_index,
            max_rounds=max_rounds,
            score=int(result.get("score", 0) or 0),
            issue_count=len(result.get("issues", [])) if isinstance(result.get("issues"), list) else 0,
        )
        if result.get("passed") or result.get("waiting_for_human"):
            break
        if not auto_fix or signature == previous_signature:
            break
        previous_signature = signature

    if not last_result:
        last_result = evaluate_production_stage_gate(project_id, key)
    merged_actions: list[str] = []
    for item in rounds:
        for action in item.get("actions", []) if isinstance(item.get("actions"), list) else []:
            action_text = clean_text(str(action))
            if action_text and action_text not in merged_actions:
                merged_actions.append(action_text)
    last_result = dict(last_result)
    last_result["rounds"] = rounds
    last_result["closed_loop_rounds"] = len(rounds)
    last_result["closed_loop_max_rounds"] = max_rounds
    last_result["closed_loop_exhausted"] = bool(rounds and not last_result.get("passed") and len(rounds) >= max_rounds)
    if merged_actions:
        last_result["actions"] = merged_actions
    emit_stage_gate_progress(
        progress_callback,
        "finished",
        (
            f"闸门任务结束：共运行 {len(rounds)} 轮，等待人工采用候选图"
            if last_result.get("waiting_for_human")
            else f"闸门任务结束：共运行 {len(rounds)} 轮，{'已通过' if last_result.get('passed') else '仍有未通过项'}"
        ),
        rounds=len(rounds),
        score=int(last_result.get("score", 0) or 0),
        passed=bool(last_result.get("passed")),
    )
    save_stage_gate_result(project_id, last_result)
    return last_result


def coerce_non_negative_int(value: Any) -> int:
    try:
        if value is None or value == "":
            return 0
        return max(0, int(float(value)))
    except (ValueError, TypeError):
        return 0


def coerce_non_negative_float(value: Any) -> float:
    try:
        if value is None or value == "":
            return 0.0
        return max(0.0, float(value))
    except (ValueError, TypeError):
        return 0.0


def normalize_release_metrics(raw: dict[str, Any] | None) -> dict[str, Any]:
    raw = raw if isinstance(raw, dict) else {}

    def normalized_rate(key: str) -> float:
        value = coerce_non_negative_float(raw.get(key))
        if value <= 1 and value > 0:
            value *= 100
        return round(clamp_number(value, 0, 100), 2)

    metrics = {
        "impressions": coerce_non_negative_int(raw.get("impressions")),
        "click_through_rate": normalized_rate("click_through_rate"),
        "views": coerce_non_negative_int(raw.get("views")),
        "likes": coerce_non_negative_int(raw.get("likes")),
        "comments": coerce_non_negative_int(raw.get("comments")),
        "shares": coerce_non_negative_int(raw.get("shares")),
        "favorites": coerce_non_negative_int(raw.get("favorites")),
        "follows": coerce_non_negative_int(raw.get("follows")),
        "two_second_retention_rate": normalized_rate("two_second_retention_rate"),
        "five_second_retention_rate": normalized_rate("five_second_retention_rate"),
        "average_watch_seconds": round(coerce_non_negative_float(raw.get("average_watch_seconds")), 2),
        "completion_rate": normalized_rate("completion_rate"),
        "notes": clean_text(str(raw.get("notes") or "")),
        "source": clean_text(str(raw.get("source") or "")),
        "synced_at": coerce_non_negative_float(raw.get("synced_at")),
        "updated_at": storage.now_ts(),
    }
    if not metrics["click_through_rate"] and metrics["impressions"] and metrics["views"]:
        metrics["click_through_rate"] = round(
            clamp_number(metrics["views"] / metrics["impressions"] * 100, 0, 100),
            2,
        )
    return metrics


def release_estimated_duration_seconds(metrics: dict[str, Any]) -> float:
    average_watch = float(metrics.get("average_watch_seconds", 0) or 0)
    completion_rate = float(metrics.get("completion_rate", 0) or 0)
    if average_watch <= 0 or completion_rate <= 0:
        return 0.0
    estimate = average_watch / completion_rate * 100
    if estimate < 10 or estimate > 3600:
        return 0.0
    return round(estimate, 1)


def release_performance_signal(item: dict[str, Any]) -> dict[str, Any]:
    metrics = item.get("metrics") if isinstance(item.get("metrics"), dict) else {}
    metrics = normalize_release_metrics(metrics)
    views = metrics["views"]
    engagement = metrics["likes"] + metrics["comments"] + metrics["shares"] + metrics["favorites"]
    engagement_rate = round(engagement / views * 100, 2) if views else 0.0
    share_save_rate = round((metrics["shares"] + metrics["favorites"]) / views * 100, 2) if views else 0.0
    follow_rate = round(metrics["follows"] / views * 100, 2) if views else 0.0
    estimated_duration_seconds = release_estimated_duration_seconds(metrics)
    raw_score = (
        views
        + metrics["likes"] * 20
        + metrics["comments"] * 55
        + metrics["shares"] * 80
        + metrics["favorites"] * 30
        + metrics["follows"] * 100
        + metrics["completion_rate"] * 120
    )
    score_parts: list[tuple[float, float]] = []
    if views:
        score_parts.append((min(100.0, math.log10(views + 1) / 5 * 100), 8.0))
        score_parts.append((min(100.0, engagement_rate / 8 * 100), 17.0))
        score_parts.append((min(100.0, share_save_rate / 5 * 100), 10.0))
        if metrics["follows"]:
            score_parts.append((min(100.0, follow_rate / 2 * 100), 5.0))
    if metrics["two_second_retention_rate"]:
        score_parts.append((metrics["two_second_retention_rate"], 22.0))
    if metrics["five_second_retention_rate"]:
        score_parts.append((metrics["five_second_retention_rate"], 18.0))
    if metrics["completion_rate"]:
        score_parts.append((metrics["completion_rate"], 25.0))
    total_weight = sum(weight for _, weight in score_parts)
    quality_score = round(sum(value * weight for value, weight in score_parts) / total_weight, 1) if total_weight else 0.0

    if not score_parts:
        growth_stage = "待回填"
    elif metrics["two_second_retention_rate"] and metrics["two_second_retention_rate"] < 55:
        growth_stage = "开场流失"
    elif metrics["five_second_retention_rate"] and metrics["five_second_retention_rate"] < 38:
        growth_stage = "前段承接弱"
    elif metrics["completion_rate"] and metrics["completion_rate"] < 22:
        growth_stage = "中后段流失"
    elif views and engagement_rate < 2:
        growth_stage = "互动偏弱"
    else:
        growth_stage = "表现健康"
    return {
        "release_id": item.get("id"),
        "platform": item.get("platform", ""),
        "url": item.get("url", ""),
        "title": item.get("title", ""),
        "note": item.get("note", ""),
        "metrics": metrics,
        "engagement": engagement,
        "engagement_rate": engagement_rate,
        "share_save_rate": share_save_rate,
        "follow_rate": follow_rate,
        "estimated_duration_seconds": estimated_duration_seconds,
        "growth_stage": growth_stage,
        "performance_score": quality_score,
        "raw_performance_score": int(round(raw_score)),
        "has_metrics": any(
            metrics.get(key, 0)
            for key in (
                "impressions",
                "click_through_rate",
                "views",
                "likes",
                "comments",
                "shares",
                "favorites",
                "follows",
                "two_second_retention_rate",
                "five_second_retention_rate",
                "average_watch_seconds",
                "completion_rate",
            )
        ),
    }


def channel_growth_experiment(performance_signals: list[dict[str, Any]]) -> dict[str, Any]:
    signals = [item for item in performance_signals if isinstance(item, dict) and item.get("has_metrics")]

    def median_value(values: list[float]) -> float:
        ordered = sorted(float(value) for value in values if float(value) > 0)
        if not ordered:
            return 0.0
        middle = len(ordered) // 2
        if len(ordered) % 2:
            return round(ordered[middle], 1)
        return round((ordered[middle - 1] + ordered[middle]) / 2, 1)

    impressions = [float((item.get("metrics") or {}).get("impressions", 0) or 0) for item in signals]
    click_rates = [float((item.get("metrics") or {}).get("click_through_rate", 0) or 0) for item in signals]
    completions = [float((item.get("metrics") or {}).get("completion_rate", 0) or 0) for item in signals]
    durations = [float(item.get("estimated_duration_seconds", 0) or 0) for item in signals]
    result = {
        "sample_count": len(signals),
        "average_impressions": round(sum(value for value in impressions if value > 0) / max(1, sum(1 for value in impressions if value > 0)), 1),
        "average_click_through_rate": round(sum(value for value in click_rates if value > 0) / max(1, sum(1 for value in click_rates if value > 0)), 2),
        "median_estimated_duration_seconds": median_value(durations),
        "median_completion_rate": median_value(completions),
        "kind": "observe",
        "label": "继续观察",
        "duration_target": "",
        "prompt": "",
        "recommendation": "样本仍在积累，下一期继续回填展现、点击率、平均观看和完播率后再做针对性实验。",
    }
    if len(signals) < 2 or len([value for value in durations if value > 0]) < 2:
        return result
    if result["median_estimated_duration_seconds"] >= 180 and 0 < result["median_completion_rate"] < 25:
        result.update(
            {
                "kind": "short_episode_recovery",
                "label": "短时长恢复实验",
                "duration_target": "60-100 秒",
                "prompt": (
                    f"真实投放数据显示：最近 {len(signals)} 条有效样本的中位推算片长约 "
                    f"{int(result['median_estimated_duration_seconds'])} 秒，完播中位 {result['median_completion_rate']}%。"
                    "下一期进入短时长恢复实验：只讲一个可验证结论，Meta 时长写 60-100 秒；"
                    "若主题复杂，拆成连续短片，不把多段解释硬塞进一条。前 2 秒兑现标题，8 秒内给第一个证据或动作。"
                ),
                "recommendation": (
                    f"频道出现“长片低完播”信号：中位推算片长约 {int(result['median_estimated_duration_seconds'])} 秒，"
                    f"完播中位 {result['median_completion_rate']}%。接下来 3 期先验证 60-100 秒单结论短片，再用真实数据决定是否保留。"
                ),
            }
        )
    return result


def update_release_metrics(project_id: int, release_id: int, raw_metrics: dict[str, Any]) -> dict[str, Any]:
    links = storage.get_release_links(project_id)
    for item in links:
        if int(item.get("id", 0) or 0) == int(release_id):
            item["metrics"] = normalize_release_metrics(raw_metrics)
            storage.save_release_links(project_id, links)
            return item
    raise ValueError("release not found")


def _history_keyword_tokens(text: str) -> list[str]:
    stopwords = {
        "这个",
        "一个",
        "为什么",
        "怎么",
        "不是",
        "可以",
        "没有",
        "视频",
        "内容",
        "主题",
        "标题",
        "发布",
        "时候",
        "我们",
        "他们",
        "你们",
        "自己",
    }
    tokens = re.findall(r"[\u4e00-\u9fff]{2,8}|[A-Za-z0-9][A-Za-z0-9_\-]{1,20}", clean_text(text))
    return [token for token in tokens if token not in stopwords and len(token) >= 2]


def _first_content_hook(content: str, mode: str) -> str:
    return extract_opening_hook(content, mode)[:90]


def channel_terminal_cta(content: str, mode: str) -> str:
    lines = [clean_text(strip_spoken_line_for_tts(item)) for item in parse_dialogue_lines(content, mode)]
    candidates = [item for item in lines[-8:] if item and is_terminal_interaction_intent(item)]
    return max(candidates, key=terminal_interaction_quality, default="")


def channel_cta_signature(text: str) -> str:
    source = clean_text(text)
    if not source:
        return ""
    if re.search(r"(?:扣|打|回)[一二两123]", source) or ("1" in source and "2" in source):
        return "binary_code_comment"
    if any(token in source for token in ("只写一个经历", "写一个经历", "说说经历", "遇到过")):
        return "single_experience_comment"
    if any(token in source for token in ("哪种", "哪个", "哪一个", "最离谱", "最烦")):
        return "choice_comment"
    if any(token in source for token in ("同意", "支持", "觉得", "怎么看", "站哪边")):
        return "stance_comment"
    if any(token in source for token in ("收藏", "转发", "关注", "点赞")):
        return "engagement_command"
    return "open_question_comment"


def channel_case_structure_signature(content: str, mode: str) -> str:
    spoken = "\n".join(
        clean_text(strip_spoken_line_for_tts(item))
        for item in parse_dialogue_lines(content, mode)
        if clean_text(strip_spoken_line_for_tts(item))
    )
    if not spoken:
        return ""
    signals: list[str] = []
    if re.search(r"(?:我(?:买|用|试|遇到|发现|亲测)|亲身|实测|朋友|同事|家里人)", spoken):
        signals.append("personal_case")
    if len([item for item in extract_numeric_fact_tokens(spoken) if is_strong_numeric_fact(item)]) >= 2:
        signals.append("data_evidence")
    if any(token in spoken for token in ("对比", "相比", "一边", "另一边", "同样", "前后", "反而")):
        signals.append("comparison")
    if len(re.findall(r"(?:第一|第二|第三|先.{0,8}再|打开.{0,12}设置|关闭.{0,12}开关)", spoken)) >= 2:
        signals.append("step_solution")
    if any(token in spoken for token in ("原理", "机制", "真正原因", "因为", "所以", "背后")):
        signals.append("mechanism_explain")
    if any(token in spoken for token in ("结果", "代价", "后果", "失效", "泄露", "损失", "坑")):
        signals.append("consequence_reveal")
    return "+".join(signals[:3]) or "scene_explain"


def channel_character_pose_signature(text: str) -> str:
    source = clean_text(text)
    pose_patterns = (
        ("shrug_or_spread_hands", ("摊手", "耸肩", "双手摊开")),
        ("pointing_at_screen", ("手指指向", "指着", "点击屏幕", "手指停在")),
        ("looking_down_at_phone", ("低头看手机", "盯着手机", "手持手机", "手机贴近")),
        ("desk_computer_gaze", ("坐在电脑前", "盯着电脑", "电脑屏幕", "笔记本电脑")),
        ("holding_evidence", ("举着", "拿着", "手持", "托着", "捏着")),
        ("face_reaction", ("震惊", "皱眉", "错愕", "表情", "人物反应")),
    )
    for signature, tokens in pose_patterns:
        if any(token in source for token in tokens):
            return signature
    return "object_led" if source else ""


def channel_cover_composition_signature(text: str) -> str:
    source = clean_text(text)
    composition_patterns = (
        ("split_comparison", ("左右对比", "左右分割", "一边", "另一边", "前后对比", "双栏")),
        ("subject_one_side_title_space", ("主体压住一侧", "另一侧", "留标题", "标题安全区")),
        ("large_number_center", ("大号数字", "数据光牌", "数字牌", "趋势箭头")),
        ("person_phone_closeup", ("人物", "手机", "近景", "特写")),
        ("object_evidence_closeup", ("关键物件", "证据", "手部操作", "物件特写")),
        ("interface_scene", ("界面", "屏幕", "通知", "弹窗", "面板")),
    )
    for signature, tokens in composition_patterns:
        if sum(1 for token in tokens if token in source) >= min(2, len(tokens)):
            return signature
    return "topic_scene" if source else ""


