def sync_project_content_artifacts(
    project_id: int,
    expected_content_hash: str,
    progress_callback: Callable[[str, str], None] | None = None,
) -> dict[str, Any]:
    def progress(phase: str, message: str) -> None:
        if progress_callback:
            progress_callback(phase, message)

    project = storage.get_project(project_id)
    template = storage.get_template(project["template"])
    content = storage.get_content(project_id)
    current_hash = visual_brief_source_hash(content)
    if expected_content_hash and current_hash != expected_content_hash:
        return {"superseded": True, "content_hash": current_hash}

    progress("summary", "正在更新摘要与场景数量")
    summary = summarize_content(content, project.get("template_mode", "video"))
    brief = storage.get_brief(project_id)
    references = storage.get_references(project_id)
    fact_registry = save_episode_fact_registry(
        project_id,
        content,
        brief=brief,
        references=references,
    )
    tavily_topic = storage.get_project_settings(project_id).get("tavily_topic", "general")

    progress("audit", "正在重算选题、文案与语义质量报告")
    artifacts = build_content_artifacts(project, template, brief, tavily_topic, references, content)
    if visual_brief_source_hash(storage.get_content(project_id)) != current_hash:
        return {"superseded": True, "content_hash": visual_brief_source_hash(storage.get_content(project_id))}

    storage.save_summary(project_id, summary)
    storage.write_json(storage.project_file(project_id, "content_strategy.json"), artifacts["strategy"])
    storage.write_json(storage.project_file(project_id, "content_audit.json"), artifacts["audit"])
    storage.save_report(project_id, "topic_score", artifacts["strategy"]["topic_score"])
    storage.save_report(project_id, "viral_doctor", artifacts["audit"]["viral_doctor"])
    storage.save_report(project_id, "title_cover_ab", artifacts["audit"]["title_cover_ab"])

    change_report = storage.read_json(storage.project_file(project_id, "content_change.json"), {})
    invalidation = change_report.get("invalidate") if isinstance(change_report, dict) and isinstance(change_report.get("invalidate"), dict) else {}
    visual_changed = bool(invalidation.get("scene_images") or invalidation.get("covers"))
    progress(
        "visual",
        "正在后台更新视觉简报、编导规格和生图提示词"
        if visual_changed
        else "图片与封面语义未变化，正在复用现有视觉清单",
    )
    with contextlib.suppress(Exception):
        if visual_changed:
            save_visual_brief(project_id, content)
        prompt_manifest = save_visual_prompt_manifest(
            project_id,
            content,
            force=visual_changed,
            preserve_covers=not bool(invalidation.get("covers")),
        )
        summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
        summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
        storage.save_summary(project_id, summary)
    with contextlib.suppress(Exception):
        save_video_spec(project_id, content)
    with contextlib.suppress(Exception):
        expected = int(storage.scene_status(project_id).get("expected_count", 0) or 0)
        if expected > 0:
            storage.cleanup_extra_scene_outputs(project_id, expected)
    manifest = record_production_step(project_id, "content_sync")
    progress("complete", "内容分析已更新，旧资产状态已重新标记")
    return {
        "superseded": False,
        "content_hash": current_hash,
        "summary": summary,
        "audit_score": artifacts["audit"].get("score", 0),
        "fact_registry": fact_registry,
        "manifest": manifest,
    }


class ContentRuntime:
    def __init__(self) -> None:
        self.tasks: dict[int, dict[str, Any]] = {}

    def status(self, project_id: int) -> dict[str, Any] | None:
        item = self.tasks.get(project_id)
        if item:
            return item["state"]
        path = storage.project_file(project_id, "content_generate.json")
        if path.exists():
            return storage.read_json(path, None)
        return None

    async def start(self, project: dict[str, Any], template: dict[str, Any], brief: str, tavily_topic: str) -> dict[str, Any]:
        project_id = project["id"]
        await self.cancel(project_id, silent=True)
        state = {
            "status": "running",
            "started_at": storage.now_ts(),
            "stage": "think",
            "stage_started_at": storage.now_ts(),
            "stages": [],
            "cancel_requested": False,
            "provider": "",
            "reference_count": 0,
        }
        self.tasks[project_id] = {"state": state}
        storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
        task = asyncio.create_task(self._run(project, template, brief, tavily_topic))
        self.tasks[project_id]["task"] = task
        return state

    async def cancel(self, project_id: int, silent: bool = False) -> dict[str, Any]:
        item = self.tasks.get(project_id)
        if not item:
            return {"already_done": True}
        item["state"]["cancel_requested"] = True
        task = item.get("task")
        if task:
            task.cancel()
            with contextlib.suppress(asyncio.CancelledError):
                await task
        if not silent:
            state = item["state"]
            state["status"] = "cancelled"
            state["finished_at"] = storage.now_ts()
            storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
        self.tasks.pop(project_id, None)
        meta = storage.get_project(project_id)
        meta["content_generating"] = False
        storage.write_project_meta(project_id, meta)
        return {"already_done": False}

    def _push_stage(self, project_id: int, stage: str) -> None:
        state = self.tasks[project_id]["state"]
        state["stage"] = stage
        state["stage_started_at"] = storage.now_ts()
        state["stages"].append({"stage": stage, "started_at": storage.now_ts()})
        storage.write_json(storage.project_file(project_id, "content_generate.json"), state)

    async def _run(self, project: dict[str, Any], template: dict[str, Any], brief: str, tavily_topic: str) -> None:
        project_id = project["id"]
        state = self.tasks[project_id]["state"]
        meta = storage.get_project(project_id)
        meta["content_generating"] = True
        storage.write_project_meta(project_id, meta)
        try:
            self._push_stage(project_id, "think")
            preliminary_strategy = content_strategy_report(project, template, brief, tavily_topic, [])
            storage.write_json(storage.project_file(project_id, "content_strategy.json"), preliminary_strategy)
            await asyncio.sleep(0.15)

            self._push_stage(project_id, "search")
            references: list[dict[str, Any]] = []
            provider = ""
            original_error = ""
            deepseek_error = ""
            context: dict[str, Any] = {}
            deepseek_enabled = bool(clean_text(runtime_env().get("DEEPSEEK_API_KEY", "")))
            state["generator_priority"] = "deepseek-template-first" if deepseek_enabled else "local-fallback"

            if deepseek_enabled:
                context = await asyncio.to_thread(build_reference_context, project, template, brief, tavily_topic)
                references = context.get("references", [])
                if not isinstance(references, list):
                    references = []
                state["reference_count"] = len(references)
                storage.write_json(storage.project_file(project_id, "content_generate.json"), state)

                self._push_stage(project_id, "write")
                try:
                    content = await asyncio.to_thread(render_deepseek_content, project, template, brief, tavily_topic, context)
                    provider = "deepseek"
                except Exception as exc:
                    deepseek_error = str(exc)
                    state["deepseek_error"] = deepseek_error
                    storage.write_json(storage.project_file(project_id, "content_generate.json"), state)

                    self._push_stage(project_id, "original_fallback")
                    try:
                        original_result = await asyncio.to_thread(render_original_content, project, template, brief, tavily_topic)
                        references = original_result.get("references", [])
                        if not isinstance(references, list):
                            references = []
                        state["reference_count"] = len(references)
                        state["original_stages"] = original_result.get("stages", [])
                        storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
                        content = str(original_result["content"])
                        provider = str(original_result.get("provider") or "deepseek-via-original")
                    except Exception as original_exc:
                        original_error = str(original_exc)
                        state["original_error"] = original_error
                        storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
                        raise ContentGenerationError(
                            "文案模型调用失败，已保留原有文案并停止生产。"
                            f" DeepSeek：{user_facing_error(deepseek_error, 260)}；"
                            f"备用链路：{user_facing_error(original_error, 260)}"
                        )
            else:
                state["fallback_reason"] = "DeepSeek API Key 未配置，已阻止使用通用空壳兜底稿。"
                storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
                raise ContentGenerationError(
                    "DeepSeek API Key 未配置，文案未生成；系统不会再用与主题无关的通用稿代替。"
                )

            canonical = canonicalize_project_content(
                project_id,
                content,
                brief=brief,
                references=references,
            )
            content = str(canonical.get("content") or content)
            hollow = hollow_script_report(content, clean_text(template.get("mode") or "video"))
            if hollow.get("hollow"):
                raise ContentGenerationError(
                    "文案只有写作方法和通用转折，缺少本期事实、案例与结论，已阻止进入配音和生图。"
                )
            numeric_consistency = canonical.get("numeric_consistency") if isinstance(canonical.get("numeric_consistency"), dict) else {}
            unsupported_facts = numeric_consistency.get("unsupported_facts") if isinstance(numeric_consistency, dict) else []
            if isinstance(unsupported_facts, list) and unsupported_facts:
                facts = dedupe_clauses(
                    clean_text(str(item.get("fact") or ""))
                    for item in unsupported_facts
                    if isinstance(item, dict)
                )
                raise ContentGenerationError(
                    "文案包含参考资料无法证明的精确数字，已阻止保存："
                    + "、".join(facts[:6])
                )
            bad_phrase_hits = list(canonical.get("bad_phrase_repair") or [])
            opening_repair = canonical.get("opening_repair") if isinstance(canonical.get("opening_repair"), dict) else {}
            content = refresh_content_image_prompts(project, template, content)
            summary = summarize_content(content, template.get("mode", "video"))
            artifacts = build_content_artifacts(project, template, brief, tavily_topic, references, content)
            storage.save_content(project_id, content)
            save_spoken_script_manifest(project_id, content)
            opening_report = canonical.get("opening_novelty") if isinstance(canonical.get("opening_novelty"), dict) else opening_novelty_report(project_id, content)
            storage.write_json(storage.project_file(project_id, "opening_novelty.json"), opening_report)
            storage.save_references(project_id, references)
            save_episode_fact_registry(
                project_id,
                content,
                brief=brief,
                references=references,
                registry=canonical.get("fact_registry") if isinstance(canonical.get("fact_registry"), dict) else None,
            )
            storage.save_summary(project_id, summary)
            self._push_stage(project_id, "visual")
            with contextlib.suppress(Exception):
                save_visual_brief(project_id, content)
                prompt_manifest = save_visual_prompt_manifest(project_id, content)
                summary["scene_count"] = int(prompt_manifest.get("scene_count") or 0)
                summary["scene_count_script"] = int(prompt_manifest.get("scene_count") or 0)
                storage.save_summary(project_id, summary)
            storage.write_json(storage.project_file(project_id, "content_strategy.json"), artifacts["strategy"])
            storage.write_json(storage.project_file(project_id, "content_audit.json"), artifacts["audit"])
            with contextlib.suppress(Exception):
                save_video_spec(project_id, content)
            storage.save_report(project_id, "topic_score", artifacts["strategy"]["topic_score"])
            storage.save_report(project_id, "viral_doctor", artifacts["audit"]["viral_doctor"])
            storage.save_report(project_id, "title_cover_ab", artifacts["audit"]["title_cover_ab"])
            mark_image_review_dirty(project_id, "content.md 已更新，图片需要重新确认")
            with contextlib.suppress(Exception):
                record_production_step(project_id, "content_sync")
            state["provider"] = provider
            state["content_audit_score"] = artifacts["audit"]["score"]
            state["content_audit_verdict"] = artifacts["audit"]["verdict"]
            if bad_phrase_hits:
                state["bad_phrase_repair"] = bad_phrase_hits
            state["opening_novelty"] = {
                "score": opening_report.get("score", 0),
                "family": opening_report.get("family", ""),
                "repetitive": opening_report.get("repetitive", False),
            }
            if opening_repair.get("changed"):
                state["opening_repair"] = {"replacement": opening_repair.get("replacement", "")}
            if deepseek_error:
                state["fallback_reason"] = deepseek_error
            if original_error:
                state["original_fallback_reason"] = original_error
            state["status"] = "succeeded"
            state["finished_at"] = storage.now_ts()
            storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
        except asyncio.CancelledError:
            state["status"] = "cancelled"
            state["finished_at"] = storage.now_ts()
            storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
            raise
        except Exception as exc:
            state["status"] = "failed"
            state["finished_at"] = storage.now_ts()
            state["error"] = str(exc)
            storage.write_json(storage.project_file(project_id, "content_generate.json"), state)
        finally:
            meta = storage.get_project(project_id)
            meta["content_generating"] = False
            storage.write_project_meta(project_id, meta)
            self.tasks.pop(project_id, None)


class ContentSyncRuntime:
    def __init__(self) -> None:
        self.tasks: dict[int, dict[str, Any]] = {}

    def _path(self, project_id: int) -> Path:
        return storage.project_file(project_id, "content_sync.json")

    def status(self, project_id: int) -> dict[str, Any] | None:
        item = self.tasks.get(project_id)
        if item:
            return dict(item["state"])
        state = storage.read_json(self._path(project_id), None)
        if isinstance(state, dict) and state.get("running"):
            state = {
                **state,
                "status": "interrupted",
                "running": False,
                "finished_at": state.get("finished_at") or storage.now_ts(),
                "message": "上一次内容同步在服务重启时中断；再次保存会自动重建。",
            }
            storage.write_json(self._path(project_id), state)
        return state if isinstance(state, dict) else None

    async def start(self, project_id: int) -> dict[str, Any]:
        requested_hash = visual_brief_source_hash(storage.get_content(project_id))
        existing = self.tasks.get(project_id)
        if existing:
            state = existing["state"]
            state["requested_content_hash"] = requested_hash
            state["message"] = "已收到更新版本，当前轮结束后会自动同步最新内容。"
            state["updated_at"] = storage.now_ts()
            storage.write_json(self._path(project_id), state)
            return dict(state)

        state = {
            "status": "queued",
            "running": True,
            "phase": "saved",
            "message": "内容已保存，后台同步任务已受理。",
            "requested_content_hash": requested_hash,
            "active_content_hash": "",
            "started_at": storage.now_ts(),
            "updated_at": storage.now_ts(),
            "finished_at": None,
        }
        storage.write_json(self._path(project_id), state)
        task = asyncio.create_task(self._run(project_id, state))
        self.tasks[project_id] = {"state": state, "task": task}
        return dict(state)

    async def _run(self, project_id: int, state: dict[str, Any]) -> None:
        try:
            while True:
                active_hash = clean_text(str(state.get("requested_content_hash") or ""))
                state.update(
                    {
                        "status": "running",
                        "running": True,
                        "active_content_hash": active_hash,
                        "phase": "prepare",
                        "message": "正在读取当前内容和已有资产。",
                        "updated_at": storage.now_ts(),
                    }
                )
                storage.write_json(self._path(project_id), state)

                def update_progress(phase: str, message: str) -> None:
                    state["phase"] = phase
                    state["message"] = message
                    state["updated_at"] = storage.now_ts()
                    storage.write_json(self._path(project_id), state)

                result = await asyncio.to_thread(
                    sync_project_content_artifacts,
                    project_id,
                    active_hash,
                    update_progress,
                )
                newest_hash = clean_text(str(state.get("requested_content_hash") or ""))
                if result.get("superseded") or newest_hash != active_hash:
                    state["message"] = "检测到更新版本，正在切换到最新内容。"
                    state["updated_at"] = storage.now_ts()
                    storage.write_json(self._path(project_id), state)
                    continue
                state.update(
                    {
                        "status": "succeeded",
                        "running": False,
                        "phase": "complete",
                        "message": "内容分析和资产版本状态已更新。",
                        "result": result,
                        "finished_at": storage.now_ts(),
                        "updated_at": storage.now_ts(),
                    }
                )
                storage.write_json(self._path(project_id), state)
                break
        except Exception as exc:
            state.update(
                {
                    "status": "failed",
                    "running": False,
                    "phase": "failed",
                    "message": f"内容同步失败：{user_facing_error(exc)}",
                    "error": user_facing_error(exc),
                    "finished_at": storage.now_ts(),
                    "updated_at": storage.now_ts(),
                }
            )
            storage.write_json(self._path(project_id), state)
        finally:
            self.tasks.pop(project_id, None)


def job_runtime_health(job: dict[str, Any], now: float | None = None) -> dict[str, Any]:
    current = float(now if now is not None else storage.now_ts())
    running = bool(job.get("running")) and clean_text(str(job.get("status") or "")) == "running"
    heartbeat_at = float(job.get("heartbeat_at") or job.get("updated_at") or job.get("started_at") or 0)
    last_progress_at = float(job.get("last_progress_at") or job.get("updated_at") or job.get("started_at") or 0)
    heartbeat_age = max(0, int(current - heartbeat_at)) if heartbeat_at > 0 else 0
    progress_age = max(0, int(current - last_progress_at)) if last_progress_at > 0 else 0
    if not running:
        state = "terminal"
        label = "任务已结束"
    elif heartbeat_at <= 0 or heartbeat_age > 15:
        state = "stalled"
        label = "后台心跳中断，任务可能已卡住"
    elif progress_age > 45:
        state = "waiting_external"
        label = "后台在线，正在等待外部服务返回"
    else:
        state = "active"
        label = "后台运行正常"
    return {
        "state": state,
        "label": label,
        "worker_alive": bool(running and state != "stalled"),
        "heartbeat_age_seconds": heartbeat_age,
        "progress_age_seconds": progress_age,
    }


PRODUCTION_STEP_AUTO_RETRY_LIMIT = 2
PRODUCTION_STEP_AUTO_RETRY_DELAYS = (3, 8)
PRODUCTION_STEP_KEYS = {
    "audio",
    "subtitles",
    "images",
    "images_missing",
    "images_sample",
    "covers",
    "covers_missing",
    "motion_clips",
    "bgm",
    "article",
    "video",
    "content_sync",
}


def production_error_recovery_policy(error: BaseException | str) -> dict[str, Any]:
    """Classify a production error without hiding the original failure.

    External image, speech and browser services occasionally return a broken
    response even though the project inputs are valid.  Those failures should
    be retried inside the same job so a full-auto run does not stop for a click.
    Configuration, login, balance and deterministic quality-gate failures stay
    visible because repeating them would only waste time and quota.
    """
    raw = clean_text(str(error or ""))
    lowered = raw.casefold()
    hard_stop_markers = (
        "余额不足",
        "insufficient balance",
        "未配置",
        "缺少 api",
        "api key",
        "需要重新登录",
        "请登录",
        "login required",
        "输入框不可编辑",
        "未通过，已停止进入下一步",
        "unknown production gate",
        "未知生产闸门",
        "用户已请求停止",
        "已取消",
    )
    transient_markers = (
        "timeout",
        "timed out",
        "超时",
        "temporarily",
        "temporary",
        "稍后重试",
        "rate limit",
        "error code: 429",
        "connection closed",
        "connection reset",
        "connection aborted",
        "err_connection_closed",
        "err_connection_reset",
        "target page, context or browser has been closed",
        "未收到任何音频数据",
        "没有收到音频",
        "empty response",
        "remote protocol error",
        "server disconnected",
        "winerror 2",
        "winerror 5",
        "winerror 32",
        "文件被 windows 暂时占用",
        "系统找不到指定的文件",
        "network",
        "网络",
    )
    blocked = any(marker in lowered for marker in hard_stop_markers)
    retryable = bool(raw and not blocked and any(marker in lowered for marker in transient_markers))
    if retryable:
        category = "external_transient"
        label = "外部服务短暂波动"
        action = "系统将保留已完成素材并自动重试当前步骤"
    elif blocked:
        category = "configuration_or_quality"
        label = "需要处理明确阻断项"
        action = "按页面给出的唯一修复动作处理后继续"
    else:
        category = "unknown"
        label = "生产步骤返回异常"
        action = "系统已保留完成素材，可按资产续跑计划继续"
    return {
        "retryable": retryable,
        "category": category,
        "label": label,
        "action": action,
        "max_retries": PRODUCTION_STEP_AUTO_RETRY_LIMIT if retryable else 0,
    }


def remaining_job_steps(job: dict[str, Any]) -> list[str]:
    steps = [clean_text(str(step)) for step in job.get("steps", []) if clean_text(str(step))]
    if not steps:
        return []
    current_step = clean_text(str(job.get("current_step") or ""))
    if current_step in steps:
        return steps[steps.index(current_step) :]
    completed = {
        clean_text(str(item.get("key") or ""))
        for item in job.get("progress", [])
        if isinstance(item, dict)
        and clean_text(str(item.get("status") or "")) in {"success", "passed", "accepted_with_warnings"}
    }
    pending = [step for step in steps if step not in completed]
    return pending or steps


def normalize_production_steps(steps: Iterable[str]) -> list[str]:
    normalized: list[str] = []
    unknown: list[str] = []
    for value in steps:
        step = clean_text(str(value or ""))
        if not step:
            continue
        if step == "bgm" and not BGM_FEATURE_ENABLED:
            continue
        gate_match = re.fullmatch(r"gate-(?:check|fix):([a-z_]+)", step) or re.fullmatch(r"gate:([a-z_]+)", step)
        valid_gate = bool(gate_match and gate_match.group(1) in STAGE_GATE_DEFS)
        if step not in PRODUCTION_STEP_KEYS and not valid_gate:
            unknown.append(step)
            continue
        if step not in normalized:
            normalized.append(step)
    if unknown:
        raise RuntimeError(f"生产步骤不存在：{', '.join(unknown)}")
    if not normalized:
        raise RuntimeError("背景音乐功能已移除，请选择其它生产步骤。")
    return normalized


class JobRuntime:
    _shared_tasks: dict[str, dict[str, Any]] = {}

    def __init__(self) -> None:
        # API 手动生产、自动挖题生产和重启续跑会创建不同的 JobRuntime 实例。
        # 活跃任务必须共用同一注册表，否则另一个实例查询 latest() 时会把
        # 仍在运行的任务误判成“服务重启后中断”。
        self.tasks = self._shared_tasks

    def latest(self, project_id: int, *, force_recover_orphan: bool = False) -> dict[str, Any] | None:
        job = storage.load_latest_job(project_id)
        changed = False
        if job:
            cleaned_log = sanitize_user_log_text(str(job.get("log", "") or ""))
            if cleaned_log != str(job.get("log", "") or ""):
                job["log"] = cleaned_log
                changed = True
            if clean_text(str(job.get("status") or "")) == "failed" and not clean_text(str(job.get("error") or "")):
                recovered_error = job_error_from_log(cleaned_log)
                if recovered_error:
                    job["error"] = recovered_error
                    changed = True
        heartbeat_at = float(
            job.get("heartbeat_at") or job.get("updated_at") or job.get("started_at") or 0
        ) if job else 0.0
        heartbeat_age = max(0.0, storage.now_ts() - heartbeat_at) if heartbeat_at > 0 else float("inf")
        orphan_confirmed = bool(
            job
            and job.get("running")
            and job.get("id") not in self.tasks
            and (force_recover_orphan or heartbeat_age > 30.0)
        )
        if orphan_confirmed:
            recovered = dict(job)
            recovered["running"] = False
            recovered["finished_at"] = recovered.get("finished_at") or storage.now_ts()
            if recovered.get("status") == "running":
                recovered["status"] = "interrupted"
            log_text = str(recovered.get("log", "") or "").rstrip()
            suffix = "[job] 上一次任务已中断，未完成步骤已经停止，请重新运行。"
            recovered["log"] = f"{log_text}\n{suffix}".strip() if log_text else suffix
            recovered["updated_at"] = recovered["finished_at"]
            recovered["heartbeat_at"] = recovered["finished_at"]
            recovered["phase_message"] = "任务已中断，没有继续运行。"
            recovered["error"] = clean_text(str(recovered.get("error") or "")) or "服务重启时任务仍在运行，请继续未完成任务。"
            job = recovered
            changed = True
        if job and clean_text(str(job.get("status") or "")) in {"succeeded", "failed", "cancelled", "interrupted"}:
            terminal_status = clean_text(str(job.get("status") or ""))
            progress = job.get("progress") if isinstance(job.get("progress"), list) else []
            normalized_progress: list[dict[str, Any]] = []
            progress_changed = False
            for raw_item in progress:
                if not isinstance(raw_item, dict):
                    continue
                item = dict(raw_item)
                item_status = clean_text(str(item.get("status") or ""))
                if item_status in {"queued", "running"}:
                    item["status"] = "success" if terminal_status == "succeeded" else terminal_status
                    item["phase"] = terminal_status
                    item["finished_at"] = job.get("finished_at") or storage.now_ts()
                    if terminal_status == "interrupted":
                        item["message"] = "任务已中断，当前步骤已经停止，可重新运行。"
                    elif terminal_status == "failed":
                        failure_reason = clean_text(str(job.get("error") or ""))
                        item["message"] = f"失败原因：{failure_reason}" if failure_reason else "任务执行失败，当前步骤已经停止，请查看日志后重试。"
                    elif terminal_status == "cancelled":
                        item["message"] = "任务已取消，当前步骤已经停止。"
                    progress_changed = True
                elif terminal_status == "failed" and item_status == "failed":
                    failure_reason = clean_text(str(job.get("error") or ""))
                    old_message = clean_text(str(item.get("message") or ""))
                    if failure_reason and (not old_message or "请查看日志" in old_message):
                        item["message"] = f"失败原因：{failure_reason}"
                        progress_changed = True
                normalized_progress.append(item)
            if progress_changed:
                job = {**job, "progress": normalized_progress}
                changed = True
        if job and changed:
            storage.save_latest_job(project_id, job)
        if job:
            job = {**job, "runtime_health": job_runtime_health(job)}
        return job

    async def start(
        self,
        project: dict[str, Any],
        steps: list[str],
        allow_incomplete_video: bool = False,
        *,
        auto_recover: bool = True,
        origin: str = "manual",
    ) -> dict[str, Any]:
        project_id = project["id"]
        steps = normalize_production_steps(steps)
        latest = self.latest(project_id)
        if latest and latest.get("running"):
            raise RuntimeError("当前项目已有任务正在运行。")
        job_id = f"job-{project_id}-{storage.now_ms()}"
        started_at = storage.now_ts()
        snapshot = {
            "id": job_id,
            "project_id": project_id,
            "steps": steps,
            "status": "running",
            "running": True,
            "started_at": started_at,
            "finished_at": None,
            "return_code": None,
            "allow_incomplete_video": allow_incomplete_video,
            "auto_recover": bool(auto_recover),
            "auto_retry_limit": PRODUCTION_STEP_AUTO_RETRY_LIMIT if auto_recover else 0,
            "origin": clean_text(origin) or "manual",
            "log": "",
            "progress": [],
            "updated_at": started_at,
            "heartbeat_at": started_at,
            "last_progress_at": started_at,
            "phase_message": "任务已创建，正在准备第一个步骤。",
        }
        try:
            snapshot["architecture"] = capsule_architecture.initialize_run(
                project_id,
                job_id,
                steps,
            )
        except Exception as exc:
            snapshot["architecture"] = {
                "version": capsule_architecture.ARCHITECTURE_VERSION,
                "run_id": job_id,
                "error": user_facing_error(exc),
            }
        storage.save_latest_job(project_id, snapshot)
        task = asyncio.create_task(self._run(project, steps, job_id, allow_incomplete_video))
        self.tasks[job_id] = {"task": task, "project_id": project_id}
        return {**snapshot, "runtime_health": job_runtime_health(snapshot, started_at)}

    async def cancel(self, job_id: str) -> dict[str, Any]:
        item = self.tasks.get(job_id)
        if not item:
            return {"already_done": True}
        task = item["task"]
        task.cancel()
        abort_result = await asyncio.to_thread(
            abort_active_chatgpt_image_generations,
            runtime_env(),
            timeout_seconds=12.0,
        )
        with contextlib.suppress(asyncio.CancelledError):
            await task
        return {"already_done": False, "chatgpt_abort": abort_result}

    async def resume_on_startup(self) -> list[dict[str, Any]]:
        """Resume manual full-auto jobs left running by a service restart."""
        resumed: list[dict[str, Any]] = []
        for project in storage.list_projects():
            project_id = int(project.get("id", 0) or 0)
            if project_id <= 0:
                continue
            stored = storage.load_latest_job(project_id) or {}
            recoverable_restart = bool(
                stored.get("resume_pending")
                and clean_text(str(stored.get("interruption_reason") or "")) == "service_restart"
            )
            if not recoverable_restart and (
                not stored.get("running") or clean_text(str(stored.get("status") or "")) != "running"
            ):
                continue
            # Auto-topic batches own their child recovery loop. New child jobs
            # carry this origin so the two supervisors never race each other.
            origin = clean_text(str(stored.get("origin") or ""))
            if origin and origin != "manual":
                continue
            if not bool(stored.get("auto_recover", False)):
                continue
            recovered = (
                self.latest(project_id, force_recover_orphan=True) or stored
                if stored.get("running")
                else stored
            )
            restart_count = int(recovered.get("restart_resume_count", 0) or 0)
            if restart_count >= 2:
                continue
            steps = remaining_job_steps(recovered)
            if not steps:
                plan = production_resume_plan(project_id)
                steps = [clean_text(str(item)) for item in plan.get("recommended_steps", []) if clean_text(str(item))]
            if not steps:
                continue
            snapshot = await self.start(
                storage.get_project(project_id),
                steps,
                bool(recovered.get("allow_incomplete_video", False)),
                auto_recover=True,
                origin="manual",
            )
            latest = storage.load_latest_job(project_id) or snapshot
            latest["restart_resume_count"] = restart_count + 1
            latest["resumed_from_job_id"] = recovered.get("id")
            latest["resume_pending"] = False
            latest["phase_message"] = "服务已恢复，正在自动续跑中断前的生产步骤。"
            latest["log"] = "[recovery] 服务重启后已自动续跑，已完成素材继续保留。"
            storage.save_latest_job(project_id, latest)
            resumed.append(latest)
        return resumed

    async def _run(self, project: dict[str, Any], steps: list[str], job_id: str, allow_incomplete_video: bool) -> None:
        project_id = project["id"]
        log_lines: list[str] = []
        progress: list[dict[str, Any]] = []
        snapshot = storage.load_latest_job(project_id) or {}
        try:
            architecture = snapshot.get("architecture") if isinstance(snapshot.get("architecture"), dict) else {}
            if architecture.get("plan"):
                log_lines.append(
                    "[architecture] 已载入生产合同、分镜连续性合同与运行目录："
                    f"{architecture.get('plan')}"
                )
            summary = storage.get_summary(project_id)
            content = storage.get_content(project_id)
            canonical = canonicalize_project_content(project_id, content)
            canonical_content = str(canonical.get("content") or content)
            if canonical_content != content:
                impact = content_change_impact(project_id, content, canonical_content)
                storage.save_content(project_id, canonical_content)
                save_spoken_script_manifest(project_id, canonical_content)
                storage.write_json(storage.project_file(project_id, "content_change.json"), impact)
                storage.write_json(
                    storage.project_file(project_id, "opening_novelty.json"),
                    canonical.get("opening_novelty") or {},
                )
                content = canonical_content
                summary = summarize_content(content, project.get("template_mode", "video"))
                storage.save_summary(project_id, summary)
                invalidation = impact.get("invalidate") if isinstance(impact.get("invalidate"), dict) else {}
                with contextlib.suppress(Exception):
                    save_visual_prompt_manifest(
                        project_id,
                        content,
                        preserve_covers=not bool(invalidation.get("covers")),
                    )
                if invalidation.get("scene_images") or invalidation.get("covers"):
                    mark_image_review_dirty(project_id, f"{impact.get('scope_label') or '文案已标准化'}，仅受影响图片需要重新确认")
                actions = "、".join(str(item) for item in canonical.get("actions", [])[:6])
                log_lines.append(f"[content] 生产前已统一标准化文案{f'：{actions}' if actions else ''}")
            save_episode_fact_registry(
                project_id,
                content,
                registry=canonical.get("fact_registry") if isinstance(canonical.get("fact_registry"), dict) else None,
            )
            title = summary.get("publish_title") or summary.get("video_title") or project["topic_name"]
            mode = project.get("template_mode", "video")
            scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"])
            completed_gates: set[str] = set()
            try:
                intelligence = await asyncio.to_thread(
                    sync_production_intelligence,
                    project_id,
                    "production_start",
                )
                routes = intelligence.get("research", {}).get("routes", [])
                log_lines.append(
                    "[production] 已载入频道配方、研究路由和证据图谱"
                    f"（研究源 {len(routes) if isinstance(routes, list) else 0} 个）"
                )
            except Exception as exc:
                log_lines.append(f"[production] 生产智能初始化提醒：{user_facing_error(exc)}")

            for step in steps:
                if step in {"covers", "covers_missing"} and not project_cover_enabled(project_id):
                    progress.append(
                        {
                            "key": step,
                            "status": "success",
                            "phase": "skipped",
                            "message": "本期已选择跳过封面，自动继续下一步。",
                            "started_at": storage.now_ts(),
                            "finished_at": storage.now_ts(),
                        }
                    )
                    log_lines.append("[covers] 本期封面为可选项，已按项目设置跳过，继续下一步")
                    with contextlib.suppress(Exception):
                        capsule_architecture.record_step(project_id, job_id, step, "skipped", "本期封面已关闭")
                    self._flush(project_id, snapshot, log_lines, progress, step)
                    continue
                with contextlib.suppress(Exception):
                    capsule_architecture.record_step(project_id, job_id, step, "running", "生产步骤已开始")
                gate_changed_content = False
                explicit_gate_match = re.fullmatch(r"gate-(check|fix):([a-z_]+)", clean_text(step))
                legacy_gate_match = re.fullmatch(r"gate:([a-z_]+)", clean_text(step))
                explicit_gate_mode = explicit_gate_match.group(1) if explicit_gate_match else ("fix" if legacy_gate_match else "")
                explicit_gate_key = explicit_gate_match.group(2) if explicit_gate_match else (legacy_gate_match.group(1) if legacy_gate_match else "")
                gate_keys = [explicit_gate_key] if explicit_gate_key else production_stage_gate_keys_for_step(step)
                for gate_key in gate_keys:
                    if gate_key not in STAGE_GATE_DEFS:
                        raise RuntimeError(f"未知生产闸门：{gate_key}")
                    if gate_key in completed_gates:
                        continue
                    gate_def = STAGE_GATE_DEFS.get(gate_key, {"label": gate_key})
                    gate_label = clean_text(str(gate_def.get("label") or gate_key))
                    cached_dashboard = production_stage_gates_dashboard(project_id)
                    cached_gate = next(
                        (
                            item
                            for item in cached_dashboard.get("ordered_gates", [])
                            if isinstance(item, dict) and item.get("key") == gate_key
                        ),
                        None,
                    )
                    if cached_gate and cached_gate.get("passed") and not cached_gate.get("stale") and not explicit_gate_key:
                        cached_score = int(cached_gate.get("score", 0) or 0)
                        cached_status = clean_text(str(cached_gate.get("status") or "passed"))
                        progress.append(
                            {
                                "key": f"gate:{gate_key}",
                                "label": gate_label,
                                "status": cached_status,
                                "score": cached_score,
                                "reused": True,
                                "started_at": storage.now_ts(),
                                "finished_at": storage.now_ts(),
                            }
                        )
                        log_lines.append(f"[gate] {gate_label}：输入未变化，复用上次通过结果 {cached_score} 分，直接进入下一步")
                        completed_gates.add(gate_key)
                        self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                        continue
                    gate_auto_fix = production_stage_gate_auto_fix_mode(explicit_gate_mode, gate_key)
                    progress.append(
                        {
                            "key": f"gate:{gate_key}",
                            "label": gate_label,
                            "status": "running",
                            "phase": "queued",
                            "message": "任务已启动，正在读取最新内容",
                            "started_at": storage.now_ts(),
                        }
                    )
                    log_lines.append(f"[gate] {gate_label}：{'自动优化任务' if gate_auto_fix else '检查任务'}已启动")
                    self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                    gate_live_status: dict[str, Any] = {}

                    def update_gate_live_status(payload: dict[str, Any]) -> None:
                        if isinstance(payload, dict):
                            gate_live_status.update(payload)

                    gate_task = asyncio.create_task(
                        asyncio.to_thread(
                            run_production_stage_gate_closed_loop,
                            project_id,
                            gate_key,
                            max_rounds=(1 if gate_key == "content_gate" else 2) if gate_auto_fix else 1,
                            auto_fix=gate_auto_fix,
                            progress_callback=update_gate_live_status,
                        )
                    )
                    gate_started_monotonic = time.monotonic()
                    last_heartbeat_log = 0
                    while True:
                        try:
                            gate_result = await asyncio.wait_for(asyncio.shield(gate_task), timeout=2.0)
                            break
                        except asyncio.TimeoutError:
                            gate_waited_seconds = max(1, int(time.monotonic() - gate_started_monotonic))
                            progress[-1]["elapsed_seconds"] = gate_waited_seconds
                            for field in ("phase", "message", "updated_at", "round", "max_rounds", "current", "total", "target", "score", "issue_count"):
                                if field in gate_live_status:
                                    progress[-1][field] = gate_live_status[field]
                            if gate_waited_seconds - last_heartbeat_log >= 10:
                                heartbeat_message = clean_text(str(progress[-1].get("message") or "任务仍在处理"))
                                log_lines.append(f"[gate] {gate_label}：{heartbeat_message}（已运行 {gate_waited_seconds} 秒）")
                                last_heartbeat_log = gate_waited_seconds
                            self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                    progress[-1]["elapsed_seconds"] = max(0, int(time.monotonic() - gate_started_monotonic))
                    for field in ("phase", "message", "updated_at", "round", "max_rounds", "current", "total", "target", "score", "issue_count"):
                        if field in gate_live_status:
                            progress[-1][field] = gate_live_status[field]
                    repair_steps = stage_gate_repair_steps(gate_key, gate_result) if gate_auto_fix and not gate_result.get("passed") else []
                    if repair_steps:
                        repair_actions = list(gate_result.get("actions") or [])
                        original_before = gate_result.get("before") if isinstance(gate_result.get("before"), dict) else gate_result

                        def update_gate_asset_repair(payload: dict[str, Any]) -> None:
                            if not isinstance(payload, dict):
                                return
                            progress[-1].update(payload)
                            progress[-1]["updated_at"] = storage.now_ts()
                            self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")

                        for repair_step in repair_steps:
                            step_labels = {
                                "audio": "重新生成配音",
                                "subtitles": "重新对齐字幕",
                                "images_missing": "成片前补齐真实缺失的场景图",
                                "covers_missing": "成片前补齐真实缺失的封面",
                                "bgm": "按当前主题重新匹配 BGM",
                            }
                            repair_label = step_labels.get(repair_step, repair_step)
                            progress[-1].update({"phase": f"repair_{repair_step}", "message": repair_label})
                            log_lines.append(f"[gate] {gate_label}：阻断项已映射到修复器 -> {repair_label}")
                            self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                            content = storage.get_content(project_id)
                            scene_lines = await self._handle_step(
                                project_id,
                                project,
                                title,
                                repair_step,
                                content,
                                scene_lines,
                                log_lines,
                                job_id,
                                progress_callback=update_gate_asset_repair,
                            )
                            await asyncio.to_thread(record_production_step, project_id, repair_step)
                            repair_actions.append(repair_label)
                        progress[-1].update({"phase": "rechecking", "message": "对应修复器已执行，正在复检成片资产"})
                        self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                        refreshed_gate = await asyncio.to_thread(
                            run_production_stage_gate_closed_loop,
                            project_id,
                            gate_key,
                            max_rounds=1,
                            auto_fix=False,
                        )
                        refreshed_gate["before"] = original_before
                        refreshed_gate["actions"] = repair_actions
                        refreshed_gate["asset_repair_steps"] = repair_steps
                        gate_result = refreshed_gate
                    before_score = gate_result.get("before", {}).get("score", gate_result.get("score", 0))
                    after_score = gate_result.get("after", {}).get("score", gate_result.get("score", 0))
                    rounds = gate_result.get("rounds") if isinstance(gate_result.get("rounds"), list) else []
                    if rounds:
                        for round_item in rounds:
                            if not isinstance(round_item, dict):
                                continue
                            log_lines.append(
                                f"[gate] {gate_label}：第 {round_item.get('round')} 轮复评 "
                                f"{round_item.get('score', 0)} 分，状态 {round_item.get('status')}"
                            )
                    actions = gate_result.get("actions") if isinstance(gate_result.get("actions"), list) else []
                    if actions:
                        log_lines.append(f"[gate] {gate_label}：自动处理 -> {'；'.join(str(item) for item in actions)}")
                    if gate_result.get("passed"):
                        if gate_result.get("accepted_with_warnings"):
                            log_lines.append(f"[gate] {gate_label}：带提醒通过（{before_score} -> {after_score} 分），自动进入下一步")
                        else:
                            log_lines.append(f"[gate] {gate_label}：通过（{before_score} -> {after_score} 分）")
                        progress[-1]["status"] = "success"
                        progress[-1]["score"] = after_score
                        if gate_result.get("accepted_with_warnings"):
                            progress[-1]["status"] = "accepted_with_warnings"
                        progress[-1]["finished_at"] = storage.now_ts()
                        completed_gates.add(gate_key)
                        if gate_result.get("content_changed"):
                            gate_changed_content = True
                            content = storage.get_content(project_id)
                            summary = storage.get_summary(project_id)
                            title = summary.get("publish_title") or summary.get("video_title") or project["topic_name"]
                            scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"])
                    else:
                        progress[-1]["status"] = "failed"
                        progress[-1]["score"] = after_score
                        progress[-1]["finished_at"] = storage.now_ts()
                        for issue in gate_result.get("issues", [])[:4] if isinstance(gate_result.get("issues"), list) else []:
                            if isinstance(issue, dict):
                                level = "阻止" if issue.get("level") == "risk" else "提醒"
                                log_lines.append(f"[gate] {level}：{issue.get('where', '')} - {issue.get('issue', '')}；建议：{issue.get('fix', '')}")
                        self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")
                        if explicit_gate_mode == "check":
                            completed_gates.add(gate_key)
                            continue
                        raise RuntimeError(f"{gate_label}未通过，已停止进入下一步。")
                    self._flush(project_id, snapshot, log_lines, progress, f"gate:{gate_key}")

                if explicit_gate_key:
                    continue

                effective_step = step
                if gate_changed_content and step == "images_missing":
                    effective_step = "images"
                    log_lines.append("[gate] 图片提示词已更新，补图步骤升级为重新校准场景图")
                if gate_changed_content and step == "covers_missing":
                    effective_step = "covers"
                    log_lines.append("[gate] 封面提示词已更新，补封面步骤升级为重新生成封面")

                progress.append(
                    {
                        "key": step,
                        "status": "running",
                        "phase": "queued",
                        "message": "任务已受理，正在准备当前步骤。",
                        "started_at": storage.now_ts(),
                        "updated_at": storage.now_ts(),
                    }
                )
                self._flush(project_id, snapshot, log_lines, progress, step)

                def update_step_live_status(payload: dict[str, Any]) -> None:
                    if not isinstance(payload, dict) or not progress:
                        return
                    live_payload = dict(payload)
                    if "elapsed_seconds" in live_payload:
                        live_payload["phase_elapsed_seconds"] = live_payload.pop("elapsed_seconds")
                    progress[-1].update(live_payload)
                    step_started_at = float(progress[-1].get("started_at", storage.now_ts()) or storage.now_ts())
                    progress[-1]["elapsed_seconds"] = max(0, int(storage.now_ts() - step_started_at))
                    progress[-1]["updated_at"] = storage.now_ts()
                    self._flush(project_id, snapshot, log_lines, progress, step)

                retry_count = 0
                retry_limit = int(snapshot.get("auto_retry_limit", 0) or 0)
                while True:
                    step_task = asyncio.create_task(
                        self._handle_step(
                            project_id,
                            project,
                            title,
                            effective_step,
                            content,
                            scene_lines,
                            log_lines,
                            job_id,
                            progress_callback=update_step_live_status,
                        )
                    )
                    try:
                        while True:
                            try:
                                scene_lines = await asyncio.wait_for(asyncio.shield(step_task), timeout=2.0)
                                break
                            except asyncio.TimeoutError:
                                now = storage.now_ts()
                                started = float(progress[-1].get("started_at") or now)
                                progress[-1]["elapsed_seconds"] = max(0, int(now - started))
                                progress[-1]["heartbeat_at"] = now
                                current = storage.load_latest_job(project_id)
                                if current and current.get("id") != snapshot.get("id"):
                                    continue
                                snapshot["status"] = "running"
                                snapshot["running"] = True
                                snapshot["current_step"] = step
                                snapshot["progress"] = progress
                                snapshot["log"] = "\n".join(log_lines)
                                snapshot["updated_at"] = now
                                snapshot["heartbeat_at"] = now
                                storage.save_latest_job(project_id, snapshot)
                        break
                    except asyncio.CancelledError:
                        step_task.cancel()
                        with contextlib.suppress(asyncio.CancelledError):
                            await step_task
                        raise
                    except Exception as step_exc:
                        policy = production_error_recovery_policy(step_exc)
                        if not policy.get("retryable") or retry_count >= retry_limit:
                            raise
                        retry_count += 1
                        delay_index = min(retry_count - 1, len(PRODUCTION_STEP_AUTO_RETRY_DELAYS) - 1)
                        delay_seconds = PRODUCTION_STEP_AUTO_RETRY_DELAYS[delay_index]
                        progress[-1].update(
                            {
                                "status": "running",
                                "phase": "auto_retry",
                                "message": f"{policy.get('label')}，{delay_seconds} 秒后自动重试（{retry_count}/{retry_limit}）",
                                "auto_retry_count": retry_count,
                                "auto_retry_limit": retry_limit,
                                "last_error": user_facing_error(step_exc),
                                "updated_at": storage.now_ts(),
                            }
                        )
                        log_lines.append(
                            f"[recovery] {step}：{policy.get('label')}，已保留当前素材；"
                            f"{delay_seconds} 秒后自动重试（{retry_count}/{retry_limit}）"
                        )
                        self._flush(project_id, snapshot, log_lines, progress, step)
                        for _second in range(delay_seconds):
                            await asyncio.sleep(1)
                            self._flush(project_id, snapshot, log_lines, progress, step)
                if retry_count:
                    progress[-1]["auto_retry_count"] = retry_count
                    log_lines.append(f"[recovery] {step}：自动重试成功，继续后续生产步骤")
                try:
                    manifest = await asyncio.to_thread(record_production_step, project_id, effective_step)
                    summary_state = manifest.get("summary") if isinstance(manifest.get("summary"), dict) else {}
                    log_lines.append(
                        "[manifest] 资产版本已更新："
                        f"当前 {summary_state.get('current', 0)}/{summary_state.get('total', 0)}，"
                        f"旧版 {summary_state.get('stale', 0)}，缺失 {summary_state.get('missing', 0)}"
                    )
                except Exception as exc:
                    log_lines.append(f"[manifest] 资产版本暂未更新：{user_facing_error(exc)}")
                try:
                    await asyncio.to_thread(
                        sync_production_intelligence,
                        project_id,
                        effective_step,
                    )
                    log_lines.append("[production] 频道配方与证据图谱已同步")
                except Exception as exc:
                    log_lines.append(f"[production] 创作资料同步提醒：{user_facing_error(exc)}")
                progress[-1]["status"] = "success"
                progress[-1]["phase"] = "complete"
                if step == "video":
                    progress[-1]["message"] = "画面母版、音频混合与成片总检已完成。"
                elif step == "bgm":
                    progress[-1]["message"] = "主题 BGM 已匹配完成。"
                if effective_step != step:
                    progress[-1]["effective_step"] = effective_step
                progress[-1]["finished_at"] = storage.now_ts()
                with contextlib.suppress(Exception):
                    capsule_architecture.record_step(
                        project_id,
                        job_id,
                        step,
                        "success",
                        clean_text(str(progress[-1].get("message") or "步骤已完成")),
                    )
                self._flush(project_id, snapshot, log_lines, progress, step)

            try:
                final_intelligence = await asyncio.to_thread(
                    sync_production_intelligence,
                    project_id,
                    "complete",
                    rebuild_dataset=True,
                )
                checkpoint = final_intelligence.get("checkpoint") if isinstance(final_intelligence.get("checkpoint"), dict) else {}
                log_lines.append(
                    "[production] 频道配方、证据图谱与训练样本已随本轮生产自动更新"
                    f"（检查点 {round(float(checkpoint.get('completion_ratio', 0) or 0) * 100)}%）"
                )
            except Exception as exc:
                log_lines.append(f"[production] 收尾同步提醒：{user_facing_error(exc)}")
            snapshot["status"] = "succeeded"
            snapshot["running"] = False
            snapshot["return_code"] = 0
            snapshot["finished_at"] = storage.now_ts()
            snapshot["updated_at"] = snapshot["finished_at"]
            snapshot["heartbeat_at"] = snapshot["finished_at"]
            snapshot["last_progress_at"] = snapshot["finished_at"]
            snapshot["phase_message"] = "全部生产步骤已完成。"
            snapshot["log"] = "\n".join(log_lines)
            snapshot["progress"] = progress
            with contextlib.suppress(Exception):
                capsule_architecture.finalize_run(project_id, job_id, "succeeded")
            storage.save_latest_job(project_id, snapshot)
        except asyncio.CancelledError:
            snapshot["status"] = "cancelled"
            snapshot["running"] = False
            snapshot["return_code"] = -1
            snapshot["finished_at"] = storage.now_ts()
            snapshot["updated_at"] = snapshot["finished_at"]
            snapshot["heartbeat_at"] = snapshot["finished_at"]
            snapshot["last_progress_at"] = snapshot["finished_at"]
            snapshot["phase_message"] = "任务已取消，没有继续运行。"
            log_lines.append("[job] 用户已请求停止，当前任务已取消。")
            snapshot["log"] = "\n".join(log_lines)
            snapshot["progress"] = progress
            with contextlib.suppress(Exception):
                capsule_architecture.finalize_run(project_id, job_id, "cancelled", "用户停止任务")
            storage.save_latest_job(project_id, snapshot)
            raise
        except Exception as exc:
            error_message = user_facing_error(exc)
            recovery = production_error_recovery_policy(exc)
            snapshot["status"] = "failed"
            snapshot["running"] = False
            snapshot["return_code"] = 1
            snapshot["error"] = error_message
            snapshot["finished_at"] = storage.now_ts()
            snapshot["updated_at"] = snapshot["finished_at"]
            snapshot["heartbeat_at"] = snapshot["finished_at"]
            snapshot["last_progress_at"] = snapshot["finished_at"]
            snapshot["phase_message"] = f"任务失败：{error_message}"
            snapshot["recovery"] = {
                **recovery,
                "recommended_steps": remaining_job_steps({**snapshot, "steps": steps, "progress": progress}),
                "automatic_retries_exhausted": bool(recovery.get("retryable")),
            }
            for item in reversed(progress):
                if clean_text(str(item.get("status") or "")) in {"queued", "running"}:
                    item["status"] = "failed"
                    item["phase"] = "failed"
                    item["message"] = f"失败原因：{error_message}"
                    item["finished_at"] = snapshot["finished_at"]
                    break
            log_lines.append(f"[job] 任务失败：{error_message}")
            snapshot["log"] = "\n".join(log_lines)
            snapshot["progress"] = progress
            with contextlib.suppress(Exception):
                current_step = clean_text(str(snapshot.get("current_step") or ""))
                if current_step:
                    capsule_architecture.record_step(project_id, job_id, current_step, "failed", error_message)
                capsule_architecture.finalize_run(project_id, job_id, "failed", error_message)
            storage.save_latest_job(project_id, snapshot)
        finally:
            self.tasks.pop(job_id, None)

    def _flush(
        self,
        project_id: int,
        snapshot: dict[str, Any],
        log_lines: list[str],
        progress: list[dict[str, Any]],
        current_step: str,
    ) -> None:
        current = storage.load_latest_job(project_id)
        if current and current.get("id") != snapshot.get("id"):
            return
        # A worker delegated through ``asyncio.to_thread`` may finish a late
        # progress callback after the asyncio job has already been cancelled.
        # Never let that stale callback turn a terminal job back into
        # ``running``; this was the source of the apparent infinite generation
        # and repeated auto-resume loop.
        if current and current.get("id") == snapshot.get("id"):
            current_status = clean_text(str(current.get("status") or ""))
            if current_status in {"cancelled", "failed", "succeeded", "interrupted"} or (
                current.get("finished_at") is not None and not bool(current.get("running"))
            ):
                return
        snapshot["status"] = "running"
        snapshot["running"] = True
        snapshot["current_step"] = current_step
        snapshot["log"] = "\n".join(log_lines)
        snapshot["progress"] = progress
        now = storage.now_ts()
        snapshot["updated_at"] = now
        snapshot["heartbeat_at"] = now
        if progress:
            snapshot["phase_message"] = clean_text(str(progress[-1].get("message") or "")) or "当前步骤仍在处理。"
            progress_at = float(
                progress[-1].get("updated_at")
                or progress[-1].get("finished_at")
                or progress[-1].get("started_at")
                or now
            )
            snapshot["last_progress_at"] = max(float(snapshot.get("last_progress_at") or 0), progress_at)
        storage.save_latest_job(project_id, snapshot)

    async def _handle_real_step(
        self,
        project_id: int,
        project: dict[str, Any],
        title: str,
        step: str,
        content: str,
        scene_lines: list[str],
        log_lines: list[str],
        job_id: str,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
    ) -> tuple[bool, list[str]]:
        mode = project.get("template_mode", "video")
        template_key = clean_text(project.get("template", ""))
        template = storage.get_template(template_key) if template_key else {"name": "", "brand_name": ""}
        dialogue_lines = parse_dialogue_lines(content, mode)
        image_progress_current = 0
        image_progress_total = 0
        motion_progress_current = 0
        motion_progress_total = 0

        def add(line: str) -> None:
            nonlocal image_progress_current, image_progress_total, motion_progress_current, motion_progress_total
            log_lines.append(line)
            snapshot = storage.load_latest_job(project_id) or {}
            if snapshot.get("id") != job_id:
                return
            snapshot["log"] = "\n".join(log_lines)
            now = storage.now_ts()
            snapshot["updated_at"] = now
            snapshot["heartbeat_at"] = now
            snapshot["phase_message"] = clean_text(re.sub(r"^\[[^\]]+\]\s*", "", line))
            storage.save_latest_job(project_id, snapshot)
            if progress_callback and line.startswith("[images]"):
                message = clean_text(re.sub(r"^\[images\]\s*", "", line))
                payload: dict[str, Any] = {"phase": "image_generation", "message": message}
                started_match = re.search(r"开始\s+(\d+)\s*/\s*(\d+)", message)
                saved_match = re.search(r"进度\s+(\d+)\s*/\s*(\d+)", message)
                progress_match = saved_match or started_match
                if progress_match:
                    image_progress_current = max(0, int(progress_match.group(1)))
                    image_progress_total = max(image_progress_current, int(progress_match.group(2)))
                if image_progress_total > 0:
                    completed = image_progress_current if saved_match else max(0, image_progress_current - 1)
                    payload.update(
                        {
                            "current": image_progress_current,
                            "total": image_progress_total,
                            "percent": round(completed * 100 / image_progress_total, 1),
                        }
                    )
                if "提示词已发送" in line:
                    payload["phase"] = "chatgpt_submitted"
                elif "正在生成图片" in line or "尚未返回图片" in line or "可输入状态但尚未检测到图片" in line:
                    payload["phase"] = "chatgpt_wait"
                elif "已保存" in line or "进度 " in line:
                    payload["phase"] = "image_saved"
                if payload["phase"] in {"chatgpt_submitted", "chatgpt_wait"} and image_progress_total > 0:
                    payload["message"] = f"第 {image_progress_current}/{image_progress_total} 张：{message}"
                with contextlib.suppress(Exception):
                    progress_callback(payload)
            elif progress_callback and line.startswith("[motion_clips]"):
                message = clean_text(re.sub(r"^\[motion_clips\]\s*", "", line))
                payload = {
                    "phase": "motion_generation",
                    "status": "running",
                    "message": message,
                }
                started_match = re.search(r"开始\s+(\d+)\s*/\s*(\d+)", message)
                if started_match:
                    motion_progress_current = max(1, int(started_match.group(1)))
                    motion_progress_total = max(motion_progress_current, int(started_match.group(2)))
                wait_match = re.search(r"场景\s*(\d+).*?已等待\s*(\d+)\s*秒", message)
                if wait_match:
                    payload["phase"] = "motion_wait_external"
                    payload["external_wait_seconds"] = int(wait_match.group(2))
                if "完成场景" in message or "复用 " in message:
                    payload["phase"] = "motion_clip_ready"
                if motion_progress_total > 0:
                    payload.update(
                        {
                            "current": motion_progress_current,
                            "total": motion_progress_total,
                            "percent": round(
                                max(0, motion_progress_current - (0 if payload["phase"] == "motion_clip_ready" else 1))
                                * 100
                                / motion_progress_total,
                                1,
                            ),
                        }
                    )
                    payload["message"] = f"第 {motion_progress_current}/{motion_progress_total} 段：{message}"
                with contextlib.suppress(Exception):
                    progress_callback(payload)

        if step == "audio":
            env = runtime_env()
            output_path = storage.project_file(project_id, "audio/podcast.mp3")
            tts_dialogue = current_spoken_dialogue_payload(project_id, content, mode, project["topic_name"])
            tts_text = "\n".join(item["text"] for item in tts_dialogue)
            configured_voice_mode = clean_text(str(template.get("voice_mode") or ""))
            voice_mode = resolve_tts_voice_mode(configured_voice_mode, tts_dialogue)
            speaker_count = len(
                {
                    clean_text(str(item.get("speaker") or "")).casefold()
                    for item in tts_dialogue
                    if clean_text(str(item.get("speaker") or ""))
                }
            )
            tts_dialogue = normalize_tts_dialogue_for_voice_mode(tts_dialogue, voice_mode)
            speaker_balance = dialogue_voice_balance_report(tts_dialogue)
            if voice_mode == "dual" and not speaker_balance["balanced"]:
                raise RuntimeError("双人配音台词分配不均衡，已停止生成，避免再次出现单句副声。")
            speaker_1 = clean_text(str(template.get("tts_speaker_1") or env.get("VOLC_TTS_SPEAKER_1") or ""))
            speaker_2 = clean_text(str(template.get("tts_speaker_2") or env.get("VOLC_TTS_SPEAKER_2") or ""))
            random_value = template.get("tts_random_order", env.get("VOLC_TTS_RANDOM_ORDER", "false"))
            random_order = random_value is True or clean_text(str(random_value)).casefold() in {"1", "true", "yes", "on"}
            try:
                speech_rate = float(template.get("tts_speech_rate") or env.get("VOLC_TTS_SPEECH_RATE") or 1.0)
            except (TypeError, ValueError):
                speech_rate = 1.0
            if voice_mode == "single":
                # The original podcast endpoint always accepts two speaker slots.
                # Fill both with the selected narrator so neither its defaults nor
                # an unlabelled script line can introduce another voice.
                speaker_2 = speaker_1
                random_order = False
            elif not speaker_1 or not speaker_2 or speaker_1 == speaker_2:
                raise RuntimeError("双人讲述需要配置两个不同音色，请先在声音设置中选择两个声音。")
            add(
                f"[audio] 配音模式：{voice_mode}（稿件角色 {speaker_count} 个，"
                f"频道配置 {configured_voice_mode or 'auto'}）"
            )
            if voice_mode == "dual":
                add(
                    "[audio] 双人台词已均衡："
                    + "，".join(
                        f"{item['speaker']} {item['utterance_count']} 句/{item['character_ratio']:.0%}"
                        for item in speaker_balance["distribution"]
                    )
                )
            voice_summary = tts_voice_label(speaker_1) or "全局默认音色"
            if voice_mode == "dual":
                voice_summary += f" + {tts_voice_label(speaker_2) or '全局默认音色 2'}"
            add(f"[audio] 本期音色：{voice_summary}；语速 {speech_rate:.2f}x")
            add("[audio] 正在调用豆包播客生成真实音频 podcast.mp3")
            if not env.get("VOLC_TTS_APP_KEY") or not env.get("VOLC_TTS_ACCESS_KEY"):
                raise RuntimeError("VOLC_TTS_APP_KEY / VOLC_TTS_ACCESS_KEY 未配置，无法生成真实配音。")
            add("[audio] 已切换为逐句直读模式，禁止豆包自动改写开场和结尾")
            result = await asyncio.to_thread(
                run_original_bridge,
                "tts",
                {
                    "text": tts_text,
                    "output_path": str(output_path),
                    "dialogue_lines": tts_dialogue,
                    "overrides": {
                        "action": 3,
                        "voice_mode": voice_mode,
                        "speaker_1": speaker_1 or None,
                        "speaker_2": speaker_2 or None,
                        "random_order": random_order,
                        "speech_rate": max(0.8, min(speech_rate, 1.2)),
                    },
                },
                env,
                configured_timeout_seconds(env, "TTS_TIMEOUT_SECONDS", 1200, 300, 3600),
            )
            effective_speakers = [
                clean_text(str(item))
                for item in result.get("effective_speakers", [])
                if clean_text(str(item))
            ]
            if not effective_speakers:
                effective_speakers = [speaker_1] if voice_mode == "single" else [speaker_1, speaker_2]
            if voice_mode == "single" and set(effective_speakers) != {speaker_1}:
                output_path.unlink(missing_ok=True)
                raise RuntimeError("单人配音检测到第二音色，已丢弃本次音频，请重试。")
            single_round_enforced = bool(result.get("single_round_enforced", False))
            if voice_mode == "single" and not single_round_enforced:
                output_path.unlink(missing_ok=True)
                raise RuntimeError("单人配音没有锁定为连续单音色请求，已丢弃本次音频，请重试。")
            if voice_mode == "single":
                add(
                    "[audio] 单人稿已压缩为最少接口安全分段，"
                    "所有分段与两个音色槽位均锁定同一男声"
                )
            else:
                add("[audio] 正在整理豆包逐句 MP3 分段并抑制齿音，不会直接拼接音频字节")
            audio_processing = await asyncio.to_thread(normalize_tts_audio_asset, output_path, tts_dialogue)
            add(
                "[audio] 音频分段整理完成："
                f"{audio_processing.get('round_count', 1)} 段 -> 1 条规范音轨，"
                f"MP3 头 {audio_processing.get('id3_headers_before', 0)} -> "
                f"{audio_processing.get('id3_headers_after', 0)}"
            )
            inserted_pause = float(audio_processing.get("inserted_pause_seconds", 0) or 0)
            if inserted_pause > 0:
                add(
                    f"[audio] 已按标点和角色补足自然句间停顿，共 {inserted_pause:.1f} 秒，"
                    "避免相邻句首尾相撞"
                )
            storage.write_json(
                tts_voice_manifest_path(project_id),
                {
                    "version": TTS_VOICE_MANIFEST_VERSION,
                    "generated_at": storage.now_ts(),
                    "voice_mode": voice_mode,
                    "configured_voice_mode": configured_voice_mode or "auto",
                    "selected_voice": speaker_1,
                    "selected_voice_label": tts_voice_label(speaker_1),
                    "selected_voice_2": speaker_2 if voice_mode == "dual" else "",
                    "selected_voice_2_label": tts_voice_label(speaker_2) if voice_mode == "dual" else "",
                    "effective_speakers": effective_speakers,
                    "random_order": random_order,
                    "single_voice_enforced": voice_mode == "single",
                    "single_round_enforced": single_round_enforced,
                    "single_timbre_enforced": bool(result.get("single_timbre_enforced", False)),
                    "request_utterance_count": int(result.get("request_utterance_count", 0) or 0),
                    "dual_voice_enforced": voice_mode == "dual" and speaker_balance["balanced"],
                    "speaker_balance": speaker_balance,
                    "speech_rate": round(max(0.8, min(speech_rate, 1.2)), 2),
                    "utterance_count": len(tts_dialogue),
                    "dialogue_speakers": sorted(
                        {
                            clean_text(str(item.get("speaker") or ""))
                            for item in tts_dialogue
                            if clean_text(str(item.get("speaker") or ""))
                        }
                    ),
                    "speech_hash": semantic_text_hash([item.get("text", "") for item in tts_dialogue]),
                    "audio_processing": audio_processing,
                },
            )
            storage.write_text(
                storage.project_file(project_id, "audio/podcast.txt"),
                (tts_text or clean_text(content) or project["topic_name"]).strip() + "\n",
            )
            # The old SRT was timed against a different waveform. Remove it
            # only after the new audio is safely written so a later failed ASR
            # run can never leak mismatched subtitles into the video step.
            removed_subtitle_artifacts = invalidate_audio_dependent_subtitle_artifacts(project_id)
            if removed_subtitle_artifacts:
                add("[audio] 新配音已落盘，已使旧字幕/时轴失效，下一步将按本次音频重新对齐")
            size_mb = output_path.stat().st_size / 1048576.0
            add(f"[audio] 豆包播客音频已生成 -> podcast.mp3 ({size_mb:.1f} MB)")
            return True, scene_lines

        if step == "subtitles":
            env = runtime_env()
            audio_path = storage.project_file(project_id, "audio/podcast.mp3")
            srt_path = storage.project_file(project_id, "audio/subtitles.srt")
            timeline_path = storage.project_file(project_id, "audio/scene_timeline.json")
            if not audio_path.exists():
                raise RuntimeError("podcast.mp3 不存在，请先完成配音步骤。")
            scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"], prefer_timeline=False)
            dialogue_payload = current_spoken_dialogue_payload(project_id, content, mode, project["topic_name"])
            dialogue_texts = [item["text"] for item in dialogue_payload] or scene_lines
            add("[subtitles] 正在调用火山 ASR 生成真实字幕")
            if not env.get("VOLC_ASR_APP_KEY") and env.get("VOLC_TTS_APP_KEY"):
                add("[subtitles] 当前未单独填写 ASR 密钥，先回退复用 TTS 密钥识别")
            result = await asyncio.to_thread(
                run_original_bridge,
                "asr",
                {
                    "audio_path": str(audio_path),
                    "srt_output": str(srt_path),
                    "dialogue_lines": dialogue_texts,
                },
                env,
                configured_timeout_seconds(env, "ASR_TIMEOUT_SECONDS", 900, 300, 3600),
            )
            utterances = result.get("utterances", []) if isinstance(result.get("utterances", []), list) else []
            if not utterances:
                utterances = load_srt_entries(srt_path)
            if not utterances:
                raise RuntimeError("原版 ASR 没有返回可用字幕。")
            asr_utterances = normalize_asr_subtitle_entries(utterances)
            audio_duration_ms = max(1000, round(probe_audio_duration(audio_path) * 1000))
            coverage = subtitle_coverage_ratio(asr_utterances, audio_duration_ms)
            utterances = build_source_locked_subtitles(dialogue_texts, asr_utterances, audio_duration_ms)
            if not utterances:
                raise RuntimeError("无法根据最终口播稿建立字幕时间轴。")
            scene_count_info = resolve_project_scene_count(project, content, mode, candidate_count=len(scene_lines), audio_ms=audio_duration_ms)
            desired_scene_count = int(scene_count_info.get("final", len(scene_lines)) or len(scene_lines) or 1)
            if scene_count_info.get("mode") != "fixed":
                semantic_count_info = suggest_semantic_key_image_count(utterances, desired_scene_count, audio_duration_ms)
                desired_scene_count = int(semantic_count_info.get("final", desired_scene_count) or desired_scene_count)
                scene_count_info["semantic_selection"] = semantic_count_info
                add(
                    "[scene_timeline] 关键画面筛选："
                    f"时间建议 {semantic_count_info.get('requested')} 张，语义节点 {semantic_count_info.get('semantic_count')} 个，最终 {desired_scene_count} 张"
                )
            latest_job = storage.load_latest_job(project_id) or {}
            existing_scene_count = int(storage.scene_status(project_id).get("generated_count", 0) or 0)
            desired_scene_count, preserved_scene_count = stable_scene_count_for_job(
                desired_scene_count,
                existing_scene_count,
                latest_job.get("steps") if isinstance(latest_job.get("steps"), list) else [],
                fixed_mode=scene_count_info.get("mode") == "fixed",
            )
            if preserved_scene_count:
                scene_count_info["preserved_existing_assets"] = True
                add(
                    f"[scene_timeline] 本次未请求重绘场景图，沿用现有 {existing_scene_count} 张，只按新配音重排时长"
                )
            scene_lines = normalize_scene_prompt_count(scene_lines, desired_scene_count, project["topic_name"], mode)
            add(f"[subtitles] ASR 时间覆盖 {coverage * 100:.0f}%，字幕文字已锁定为最终 TTS 口播稿")
            # The legacy bridge output was immediately overwritten by the
            # canonical source-locked timeline below. Avoid a second external
            # wait and make the subtitle job deterministic and resumable.
            timeline = build_scene_timeline_for_scene_count(utterances, scene_lines, desired_scene_count, audio_duration_ms)
            storage.write_text(
                timeline_path,
                json.dumps(timeline, ensure_ascii=False, indent=2),
            )
            add("[scene_timeline] 已按有效口播锚点直接重排切镜；跳过冗余旧版接口等待")
            timeline_scenes = timeline.get("scenes") if isinstance(timeline, dict) else []
            if not isinstance(timeline_scenes, list) or len(timeline_scenes) != desired_scene_count:
                reason = "固定张数" if scene_count_info.get("mode") == "fixed" else "自动张数"
                add(f"[scene_timeline] {reason}要求 {desired_scene_count} 张，正在重切时轴")
                timeline = build_scene_timeline_for_scene_count(utterances, scene_lines, desired_scene_count, audio_duration_ms)
                storage.write_text(
                    timeline_path,
                    json.dumps(timeline, ensure_ascii=False, indent=2),
                )
            if utterances:
                storage.write_text(storage.project_file(project_id, "audio/subtitles.txt"), utterances_to_plain_text(utterances) + "\n")
            aligned_lines = [clean_text(str(item.get("prompt", ""))) for item in timeline.get("scenes", []) if isinstance(item, dict)]
            image_scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"], prefer_timeline=False)
            if not image_scene_lines:
                image_scene_lines = scene_lines
            image_scene_lines = normalize_scene_prompt_count(image_scene_lines, desired_scene_count, project["topic_name"], mode)
            scene_range = timeline.get("scene_count_range") or {}
            add(
                f"[scene_timeline] 使用对齐后的场景图列表：候选 {len(scene_lines)} 张 -> 最终 {len(aligned_lines)} 张"
            )
            if aligned_lines and image_scene_lines:
                add("[scene_timeline] 时轴只负责切段，生图提示词已切回 content.md 原文链路，避免原版时轴压缩提示词")
            if scene_range:
                add(
                    f"[scene_timeline] 音频时长命中的建议区间：{scene_range.get('min', len(aligned_lines))}-{scene_range.get('max', len(aligned_lines))} 张"
                )
            scene_count_source = "fixed_setting" if scene_count_info.get("mode") == "fixed" else "audio_timeline"
            scene_count_label = "固定张数" if scene_count_source == "fixed_setting" else "真实音频时轴"
            add(f"[scene_timeline] 本次张数锁定：{len(aligned_lines)} 张（{scene_count_label}，音频 {audio_duration_ms / 1000:.1f}s）")
            scene_plan = write_scene_plan(project_id, project, content, timeline, image_scene_lines or scene_lines)
            write_srt_entries(srt_path, merge_subtitle_display_entries(utterances))
            sync_project_subtitle_files(project_id)
            storage.write_json(
                subtitle_sync_manifest_path(project_id),
                {
                    "version": SUBTITLE_SYNC_MANIFEST_VERSION,
                    "generated_at": storage.now_ts(),
                    "timing_source": "asr_text_aligned",
                    "speech_hash": semantic_text_hash(dialogue_texts),
                    "audio_hash": production_file_hash(audio_path),
                    "utterance_count": len(dialogue_texts),
                    "subtitle_entry_count": len(utterances),
                },
            )
            add(f"[scene_timeline] 写出 audio/scene_timeline.json，共 {len(aligned_lines)} 段")
            add(f"[scene_plan] 写出 audio/scene_plan.json，共 {scene_plan.get('scene_count', len(aligned_lines))} 镜")
            summary = storage.get_summary(project_id)
            if summary:
                original_scene_count = int(summary.get("scene_count", 0) or 0)
                summary["scene_count_script"] = int(summary.get("scene_count_script", original_scene_count) or original_scene_count)
                summary["scene_count"] = len(aligned_lines)
                summary["scene_count_aligned"] = len(aligned_lines)
                summary["scene_count_source"] = scene_count_source
                summary["scene_count_audio_ms"] = audio_duration_ms
            storage.save_summary(project_id, summary)
            add(f"[subtitles] 已生成真实字幕 -> subtitles.srt（{len(utterances)} 条）")
            return True, image_scene_lines or scene_lines

        if step in {"images", "images_missing", "images_sample"}:
            env = runtime_env()
            provider = resolve_image_provider_queue(env)[0]
            provider_desc = describe_image_provider_queue(env)
            if not scene_lines:
                scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"])
            # Keep image generation aligned with the latest audio pacing rule.
            # A stale ten/fifteen-scene plan should not survive into a new run.
            audio_path = storage.project_file(project_id, "audio/podcast.mp3")
            if mode != "article" and audio_path.exists():
                audio_ms = max(1000, round(safe_probe_duration(audio_path) * 1000))
                count_info = resolve_project_scene_count(
                    project,
                    content,
                    mode,
                    candidate_count=len(scene_lines),
                    audio_ms=audio_ms,
                )
                desired_count = int(count_info.get("final", len(scene_lines)) or len(scene_lines) or 1)
                if count_info.get("mode") != "fixed" and desired_count != len(scene_lines):
                    repaired = await asyncio.to_thread(repair_scene_timeline, project_id)
                    scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"], prefer_timeline=True)
                    add(
                        f"[scene_timeline] 按最新音频重点规则重建：{len(scene_lines)} 张（目标 {desired_count} 张，纯过渡句不单独配图）"
                    )
            removed_extras = storage.cleanup_extra_scene_outputs(project_id, len(scene_lines))
            missing_only = step == "images_missing"
            sample_only = step == "images_sample"
            sample_index = quality_sample_scene_index(project_id, len(scene_lines)) if sample_only else 0
            missing_indexes: set[int] = set()
            existing_records = storage.read_json(storage.project_file(project_id, "scenes/scene_prompts.json"), [])
            if not isinstance(existing_records, list):
                existing_records = []
            prompt_context = project_image_context_hashes(project_id, content)
            if missing_only:
                change_report = storage.read_json(storage.project_file(project_id, "content_change.json"), {})
                change_scope = clean_text(str(change_report.get("scope") or "")) if isinstance(change_report, dict) else ""
                change_invalidation = change_report.get("invalidate") if isinstance(change_report, dict) and isinstance(change_report.get("invalidate"), dict) else {}
                localized_change_indexes = {
                    image_target_scene_index(str(item))
                    for item in (change_invalidation.get("scene_images") or [])
                    if re.fullmatch(r"s_\d+\.png", clean_text(str(item)), flags=re.IGNORECASE)
                }
                localized_change_indexes.discard(0)
                localized_change_indexes = {
                    index for index in localized_change_indexes if 1 <= index <= len(scene_lines)
                }
                try:
                    change_generated_at = float(change_report.get("generated_at", 0) or 0)
                except (TypeError, ValueError):
                    change_generated_at = 0.0
                already_refreshed_indexes = {
                    index
                    for index in localized_change_indexes
                    if change_generated_at > 0
                    and storage.project_file(project_id, f"scenes/s_{index:02d}.png").exists()
                    and storage.project_file(project_id, f"scenes/s_{index:02d}.png").stat().st_mtime
                    >= change_generated_at
                }
                if already_refreshed_indexes:
                    localized_change_indexes.difference_update(already_refreshed_indexes)
                    add(
                        "[images] 局部失效标记已消费："
                        + "、".join(f"s_{item:02d}" for item in sorted(already_refreshed_indexes))
                        + " 的正式图晚于文案变更记录，本轮不再重复生成"
                    )
                if change_scope in {"opening_only", "opening_and_cta", "scene_local"} and localized_change_indexes:
                    missing_indexes.update(localized_change_indexes)
                    add(
                        "[images] 语义增量模式：文案只影响 "
                        + "、".join(f"s_{item:02d}" for item in sorted(localized_change_indexes))
                        + "，其它已有图片保持不动"
                    )
                scene_status_payload = storage.scene_status(project_id)
                for item in scene_status_payload.get("missing_items", []):
                    if isinstance(item, dict):
                        try:
                            missing_indexes.add(int(item.get("index", 0) or 0))
                        except (ValueError, TypeError):
                            continue
                stale_indexes = {
                    index
                    for index in stale_scene_image_indexes(project_id)
                    if 1 <= index <= len(scene_lines)
                }
                preserved_stale_indexes = stale_indexes.difference(localized_change_indexes)
                if preserved_stale_indexes:
                    add(
                        "[images] 补缺失模式：以下已有正式图仅提示词版本过期，本轮保留不覆盖 "
                        + "、".join(f"s_{item:02d}" for item in sorted(preserved_stale_indexes))
                    )
                if missing_indexes:
                    add(
                        "[images] 增量补图模式：只处理 "
                        + "、".join(f"s_{item:02d}" for item in sorted(missing_indexes))
                        + "；其它正式图不会因旧评分或软提醒被覆盖"
                    )
                if not missing_indexes:
                    if removed_extras:
                        add(f"[images] 已清理 {removed_extras} 个超出当前场景数量的旧文件/记录")
                    add("[images] 没有缺失或语义过期的场景图，跳过补图。")
                    return True, scene_lines
            scene_records = list(existing_records) if (missing_only or sample_only) else []
            scene_jobs: list[tuple[int, str]] = []
            reused_records: list[dict[str, Any]] = []
            for idx, prompt in enumerate(scene_lines, start=1):
                if sample_only and idx != sample_index:
                    continue
                if missing_only and idx not in missing_indexes:
                    continue
                reused_record = (
                    None
                    if (missing_only or sample_only)
                    else reusable_scene_image_record(
                        project_id,
                        idx,
                        prompt,
                        existing_records,
                        content_hash=prompt_context.get("content_hash", ""),
                        topic_hash=prompt_context.get("topic_hash", ""),
                    )
                )
                if reused_record:
                    reused_records.append(reused_record)
                    scene_records.append(reused_record)
                    continue
                scene_jobs.append((idx, prompt))
            opening_concept_plan: dict[str, Any] = {}
            opening_concept_base_prompt = ""
            opening_concepts: list[dict[str, Any]] = []
            opening_job = (
                next(((idx, prompt) for idx, prompt in scene_jobs if idx == 1), None)
                if not missing_only and not sample_only
                else None
            )
            if opening_job:
                opening_concept_base_prompt = opening_job[1]
                add("[images] 首镜创意导演：先生成 3 个文字构思，按标题、首句、冲突和差异度选前 2 名成图")
                opening_concept_plan = await asyncio.to_thread(
                    generate_key_visual_concepts,
                    project_id,
                    "opening",
                    opening_concept_base_prompt,
                )
                opening_concepts = (
                    opening_concept_plan.get("selected_concepts")
                    if isinstance(opening_concept_plan.get("selected_concepts"), list)
                    else []
                )
                if opening_concepts:
                    scene_jobs = [
                        (
                            idx,
                            key_visual_concept_prompt(prompt, opening_concepts[0], "opening")
                            if idx == 1
                            else prompt,
                        )
                        for idx, prompt in scene_jobs
                    ]
                    score_text = "、".join(
                        f"{item.get('name') or item.get('id')} {int(item.get('score', 0) or 0)}分"
                        for item in opening_concept_plan.get("concepts", [])[:3]
                        if isinstance(item, dict)
                    )
                    add(f"[images] 首镜构思初选完成：{score_text}；只生成前 2 名")
            if not scene_jobs and not reused_records:
                add("[images] 缺失编号没有可用提示词，请先重建图片提示词或重新生成字幕时间轴。")
                return True, scene_lines
            if removed_extras:
                add(f"[images] 已清理 {removed_extras} 个超出当前场景数量的旧文件/记录")
            if reused_records:
                add(f"[images] 已复用上一轮旧图 {len(reused_records)} 张：{', '.join(str(item.get('filename')) for item in reused_records[:12])}")
            if scene_jobs:
                add("[gate] 生图前提示词闸门：正在检查本次实际发送给图片模型的场景图提示词")
                prompt_preflight = preflight_generation_prompt_batch(
                    project_id,
                    [
                        {"target": f"s_{idx:02d}.png", "label": f"场景 {idx}", "prompt": prompt}
                        for idx, prompt in scene_jobs
                    ],
                    purpose="scene",
                )
                if prompt_preflight.get("changed_count"):
                    add(f"[gate] 生图前提示词闸门：已自动改写 {prompt_preflight.get('changed_count')} 条实际生图提示词")
                for item in prompt_preflight.get("issues", [])[:4] if isinstance(prompt_preflight.get("issues"), list) else []:
                    if isinstance(item, dict):
                        level = "阻止" if item.get("level") == "risk" else "提醒"
                        add(f"[gate] {level}：{item.get('where', '')} - {item.get('issue', '')}；建议：{item.get('fix', '')}")
                if not prompt_preflight.get("generation_safe", prompt_preflight.get("passed")):
                    raise RuntimeError("生图前提示词闸门未通过，已停止调用图片接口。")
                final_prompt_map = prompt_preflight.get("final_prompts") if isinstance(prompt_preflight.get("final_prompts"), dict) else {}
                protected_scene_jobs: list[tuple[int, str]] = []
                for idx, prompt in scene_jobs:
                    original_prompt = normalize_image_prompt(repair_legacy_mojibake(prompt))
                    candidate_prompt = normalize_image_prompt(
                        repair_legacy_mojibake(final_prompt_map.get(f"s_{idx:02d}.png") or original_prompt)
                    )
                    integrity = semantic_scene_brief_integrity(original_prompt, candidate_prompt)
                    protected_scene_jobs.append(
                        (
                            idx,
                            candidate_prompt
                            if integrity.get("ok")
                            and scene_prompt_preserves_channel_contract(original_prompt, candidate_prompt)
                            else original_prompt,
                        )
                    )
                scene_jobs = protected_scene_jobs
                scene_callout_map = {
                    image_target_scene_index(str(item.get("target") or ""), str(item.get("label") or "")): clean_scene_callout_item(
                        str((item.get("callouts") or [""])[0])
                    )
                    for item in prompt_preflight.get("callout_plan", [])
                    if isinstance(item, dict) and isinstance(item.get("callouts"), list) and item.get("callouts")
                }
                if prompt_preflight.get("quality_passed", True):
                    add(f"[gate] 生图前提示词闸门通过：{prompt_preflight.get('score', 0)} 分，开始调用图片模型")
                else:
                    add(
                        f"[gate] 提示词质量提醒：{prompt_preflight.get('score', 0)} 分；"
                        "事实与当前口播一致，已采用语义保底继续生图，成图后再做真实图片审计"
                    )
            else:
                scene_callout_map = {}
            if scene_jobs:
                add(f"[images] 正在调用 {provider['label']} 生成 {len(scene_jobs)} 张场景图")
                add(f"[images] {provider_desc}")
                add("[images] 关键位竞争策略：普通镜头 1 张；首镜先做 3 个文字构思，只生成前 2 名，再看真实成图保留 1 张")
                if provider["key"] in {"apiyi", "third_party"}:
                    add("[images] OpenAI 兼容文生图单张通常需要几十秒；已切换为稳态串行生成，逐张完成后再进入下一张")
                if provider["key"] == "chatgpt_web_handoff":
                    add("[images] ChatGPT 网页接力：只打开 chatgpt.com，不会唤起桌面软件")
                if provider["key"] == "chatgpt_desktop_handoff":
                    add("[images] ChatGPT Classic 手动接力：提示词已复制，需手动粘贴发送并把生成图片保存到目标路径")
                if provider["key"] == "chatgpt_handoff":
                    add("[images] ChatGPT 旧版接力配置：会按旧设置逐张等待图片保存完成")
                if provider["key"] == "chatgpt_web_auto":
                    add("[images] ChatGPT 网页自动化：会自动发送提示词、等待图片并保存到项目目录；首次使用需要在弹出浏览器中登录")
                if provider["key"] == "imageai_playground":
                    add("[images] GPT Image Playground 网页模式：会打开 imageai.centos.hk，自动注入第三方 API 配置、提交提示词并保存图片")
            if missing_only:
                add(f"[images] 续跑模式：只更新编号 {', '.join(f's_{idx:02d}' for idx in sorted(missing_indexes))}，保留其它已有图片")
            elif sample_only:
                add(f"[images] 质量样片模式：选中重要度最高的 s_{sample_index:02d}，只生成这一张，确认方向后再批量出图")
            elif scene_jobs:
                add("[images] 智能复用模式：旧图相似则保留，缺失或不匹配的编号才生成新图")
            else:
                add("[images] 智能复用模式：本轮场景图全部复用上一轮旧图")
            for idx, prompt in scene_jobs:
                filename = f"s_{idx:02d}.png"
                output_path = storage.project_file(project_id, f"scenes/{filename}")
                add(f"[images] 开始 {idx}/{len(scene_lines)} -> {filename}")
                await asyncio.to_thread(
                    generate_configured_image_safely,
                    prompt,
                    output_path,
                    SCENE_IMAGE_SIZE,
                    "scene",
                    env,
                    add,
                    template,
                )
                discard_scene_image_candidates(project_id, idx, reason="batch_official_regenerated")
                final_prompt = read_generated_prompt(output_path, prompt)
                audit = read_image_audit(output_path)
                information_anchor = clean_scene_callout_item(str(scene_callout_map.get(idx) or scene_information_anchor_from_prompt(prompt)))
                if audit.get("attempt", 1) > 1:
                    add(f"[images] {filename} 自检后重绘 {audit.get('attempt')} 次")
                if audit.get("severity") == "soft" and audit.get("reasons"):
                    add(f"[images] {filename} 自检提示：{', '.join(str(item) for item in audit.get('reasons', []))}")
                scene_record = {
                    "filename": filename,
                    "label": f"场景 {idx}",
                    "prompt": final_prompt,
                    "source_prompt": normalize_image_prompt(prompt),
                    "audit": {
                        "ok": audit.get("ok", True),
                        "severity": audit.get("severity", "ok"),
                        "attempt": audit.get("attempt", 1),
                        "reasons": audit.get("reasons", []),
                        "warnings": audit.get("warnings", []),
                        "ocr": audit.get("ocr", {}),
                        "neighbor_similarity": audit.get("neighbor_similarity", {}),
                    },
                    "content_hash": prompt_context.get("content_hash", ""),
                    "topic_hash": prompt_context.get("topic_hash", ""),
                    "channel_id": prompt_context.get("channel_id", ""),
                    "episode_id": prompt_context.get("episode_id", ""),
                    "manifest_version": prompt_context.get("manifest_version", ""),
                    "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
                    "information_anchor": information_anchor,
                    "information_design": "ai_native" if information_anchor else "none",
                    "visual_concept": opening_concepts[0] if idx == 1 and opening_concepts else {},
                    "updated_at": storage.now_ts(),
                }
                if missing_only or sample_only:
                    scene_records = [
                        item
                        for item in scene_records
                        if not (isinstance(item, dict) and item.get("filename") == filename)
                    ]
                scene_records.append(scene_record)
                scene_records.sort(key=scene_record_index)
                storage.write_json(storage.project_file(project_id, "scenes/scene_prompts.json"), scene_records)
                if idx == 1 and not missing_only and not sample_only:
                    candidate_path = storage.project_file(project_id, "scenes/candidates/s_01_b.png")
                    try:
                        second_concept = opening_concepts[1] if len(opening_concepts) > 1 else None
                        candidate_prompt = build_opening_scene_candidate_prompt(
                            project_id,
                            opening_concept_base_prompt or prompt,
                            concept=second_concept,
                        )
                        candidate_preflight = preflight_generation_prompt_batch(
                            project_id,
                            [
                                {
                                    "target": "s_01_b.png",
                                    "label": "首镜候选 B",
                                    "prompt": candidate_prompt,
                                }
                            ],
                            purpose="scene",
                        )
                        if not candidate_preflight.get("passed"):
                            raise RuntimeError("首镜候选提示词自检未通过")
                        candidate_prompt_map = (
                            candidate_preflight.get("final_prompts")
                            if isinstance(candidate_preflight.get("final_prompts"), dict)
                            else {}
                        )
                        candidate_prompt = clean_text(
                            str(candidate_prompt_map.get("s_01_b.png") or candidate_prompt)
                        )
                        add("[images] 首镜关键位：3 个构思已完成文字筛选，正在生成排名第 2 的方案；普通镜头不追加图片")
                        await asyncio.to_thread(
                            generate_configured_image_safely,
                            candidate_prompt,
                            candidate_path,
                            SCENE_IMAGE_SIZE,
                            "scene",
                            env,
                            add,
                            template,
                        )
                        candidate_final_prompt = read_generated_prompt(candidate_path, candidate_prompt)
                        competition = await asyncio.to_thread(
                            save_opening_scene_competition,
                            project_id,
                            output_path,
                            candidate_path,
                            final_prompt,
                            candidate_final_prompt,
                            opening_concept_plan,
                        )
                        recommendation = clean_text(str(competition.get("ai_recommended_variant") or "CURRENT"))
                        current_score = int(
                            ((competition.get("current") or {}).get("score", 0))
                            if isinstance(competition.get("current"), dict)
                            else 0
                        )
                        candidate_score = int(
                            ((competition.get("candidates") or [{}])[0].get("score", 0))
                            if isinstance(competition.get("candidates"), list) and competition.get("candidates")
                            else 0
                        )
                        add(
                            f"[images] 首镜真实成图复评：方案 A {current_score} 分，方案 B {candidate_score} 分，推荐 {recommendation}"
                        )
                        if image_review_status(project_id).get("required") is False:
                            automatic = resolve_scene_candidates_automatically(project_id)
                            if automatic.get("resolved_count"):
                                adopted = automatic.get("resolved", [{}])[0]
                                add(f"[images] 全自动模式已采用首镜方案 {adopted.get('variant', recommendation)}")
                                refreshed_records = storage.read_json(
                                    storage.project_file(project_id, "scenes/scene_prompts.json"),
                                    scene_records,
                                )
                                if isinstance(refreshed_records, list):
                                    scene_records = refreshed_records
                    except Exception as exc:
                        _cleanup_generated_tmp(candidate_path)
                        cleanup_scene_image_candidates(project_id, 1)
                        add(f"[images] 首镜第 2 构思未完成，保留已通过自检的正式图 A：{exc}")
                add(f"[images] 进度 {idx}/{len(scene_lines)} -> {filename}")
            scene_records.sort(key=scene_record_index)
            storage.write_json(storage.project_file(project_id, "scenes/scene_prompts.json"), scene_records)
            if not missing_only and not sample_only:
                removed = storage.cleanup_extra_scene_outputs(project_id, len(scene_lines))
                if removed:
                    add(f"[images] 已清理 {removed} 个超出当前场景数量的旧文件")
            if scene_jobs:
                mark_image_review_dirty(
                    project_id,
                    "质量样片已生成，请先确认方向再批量出图" if sample_only else "场景图已更新，等待人工确认",
                )
            elif reused_records:
                mark_image_review_dirty(project_id, "场景图已复用上一轮旧图，等待人工确认")
            if sample_only:
                add(f"[images] 质量样片 s_{sample_index:02d} 已生成，批量任务尚未开始")
            else:
                add("[images] 场景图已处理完成" if not missing_only else "[images] 增量场景图已补齐")
            return True, scene_lines

        if step in {"covers", "covers_missing"}:
            env = runtime_env()
            provider = resolve_image_provider_queue(env)[0]
            provider_desc = describe_image_provider_queue(env)
            landscape_prompt = (
                visual_prompt_manifest_cover_prompt(project_id, "landscape", content)
                or video_spec_cover_prompt(project_id, "landscape")
                or build_content_cover_prompt(project, template, content, "landscape")
                or parse_cover_prompt_from_content(content, "landscape")
            )
            story_prompt = (
                visual_prompt_manifest_cover_prompt(project_id, "story", content)
                or video_spec_cover_prompt(project_id, "story")
                or build_content_cover_prompt(project, template, content, "story")
                or parse_cover_prompt_from_content(content, "story")
            )
            portrait_prompt = (
                visual_prompt_manifest_cover_prompt(project_id, "portrait", content)
                or video_spec_cover_prompt(project_id, "portrait")
                or build_content_cover_prompt(project, template, content, "portrait")
                or parse_cover_prompt_from_content(content, "portrait")
            )
            missing_only = step == "covers_missing"
            add(f"[covers] 正在调用 {provider['label']} 生成封面图")
            cover_jobs = [
                ("横屏封面", landscape_prompt, storage.project_file(project_id, "covers/cover_landscape.png"), COVER_LANDSCAPE_SIZE),
                ("图文封面", story_prompt, storage.project_file(project_id, "covers/cover_story.png"), COVER_STORY_SIZE),
                ("竖屏封面", portrait_prompt, storage.project_file(project_id, "covers/cover_portrait.png"), COVER_PORTRAIT_SIZE),
            ]
            cover_summary = summarize_content(content_without_image_prompts(content) or content, mode)
            required_cover_title = clean_text(
                str(cover_summary.get("cover_title") or first_heading(content) or project.get("topic_name") or title)
            )
            required_cover_subtitle = clean_text(
                str(cover_summary.get("cover_subtitle") or extract_bullet_field(content, "封面副标题") or "")
            )
            cover_jobs = [
                (
                    label,
                    ensure_cover_text_directives(
                        prompt,
                        required_cover_title,
                        required_cover_subtitle,
                        project_output_language(project),
                    ),
                    output_path,
                    output_size,
                )
                for label, prompt, output_path, output_size in cover_jobs
            ]
            cover_prompt_by_name = {output_path.name: prompt for _label, prompt, output_path, _size in cover_jobs}
            cover_variant_targets = [
                ("图文封面", storage.project_file(project_id, "covers/cover_story.png"), COVER_STORY_SIZE),
                ("竖屏封面", storage.project_file(project_id, "covers/cover_portrait.png"), COVER_PORTRAIT_SIZE),
            ]

            def derive_cover_variants(master_path: Path, *, missing_only_local: bool = False) -> int:
                derived = 0
                if not master_path.exists() or master_path.stat().st_size < 4096:
                    return 0
                for variant_label, variant_path, variant_size in cover_variant_targets:
                    if missing_only_local and variant_path.exists() and variant_path.stat().st_size >= 4096:
                        continue
                    variant_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(master_path, variant_path)
                    normalize_generated_image_size(variant_path, variant_size, log=add, label=variant_label)
                    variant_prompt = clean_text(
                        str(cover_prompt_by_name.get(variant_path.name) or cover_prompt_by_name.get("cover_landscape.png") or "")
                    )
                    storage.write_text(variant_path.with_suffix(".md"), variant_prompt + "\n")
                    variant_audit = audit_generated_image(variant_path, variant_size, "cover", variant_prompt)
                    variant_audit["derived_from"] = "cover_landscape.png"
                    variant_audit["generation_mode"] = "local_cover_adaptation"
                    storage.write_json(variant_path.with_suffix(".audit.json"), variant_audit)
                    derived += 1
                    add(f"[covers] {variant_label}已由主封面本地适配，不追加图片模型调用")
                return derived

            cover_concept_plan: dict[str, Any] = {}
            cover_concept_base_prompt = ""
            cover_concepts: list[dict[str, Any]] = []
            if missing_only:
                master_path = storage.project_file(project_id, "covers/cover_landscape.png")
                if master_path.exists() and master_path.stat().st_size >= 4096:
                    derived_count = derive_cover_variants(master_path, missing_only_local=True)
                    add(f"[covers] 主封面已经存在，本地补齐 {derived_count} 个发布比例，不追加生图")
                    return True, scene_lines
                cover_jobs = [item for item in cover_jobs if item[2].name == "cover_landscape.png"]
                add("[covers] 主封面缺失：只调用一次图片模型，其余比例随后本地适配")
            else:
                cover_jobs = [item for item in cover_jobs if item[2].name == "cover_landscape.png"]
                add("[covers] 单封面模式：AI 只生成一张主封面，图文与竖屏比例由本地自动适配")
            landscape_job = next((item for item in cover_jobs if item[2].name == "cover_landscape.png"), None)
            if landscape_job:
                cover_concept_base_prompt = landscape_job[1]
                add("[covers] 封面创意导演：先比较 3 个文字构思，只采用得分最高的一种生成正式封面")
                cover_concept_plan = await asyncio.to_thread(
                    generate_key_visual_concepts,
                    project_id,
                    "cover",
                    cover_concept_base_prompt,
                )
                cover_concepts = (
                    cover_concept_plan.get("selected_concepts")
                    if isinstance(cover_concept_plan.get("selected_concepts"), list)
                    else []
                )
                if cover_concepts:
                    cover_jobs = [
                        (
                            label,
                            ensure_cover_text_directives(
                                key_visual_concept_prompt(prompt, cover_concepts[0], "cover"),
                                required_cover_title,
                                required_cover_subtitle,
                                project_output_language(project),
                            )
                            if output_path.name == "cover_landscape.png"
                            else prompt,
                            output_path,
                            output_size,
                        )
                        for label, prompt, output_path, output_size in cover_jobs
                    ]
                    score_text = "、".join(
                        f"{item.get('name') or item.get('id')} {int(item.get('score', 0) or 0)}分"
                        for item in cover_concept_plan.get("concepts", [])[:3]
                        if isinstance(item, dict)
                    )
                    add(f"[covers] 封面构思初选完成：{score_text}；默认只生成第 1 名")
            if cover_jobs:
                add("[gate] 封面生图前提示词闸门：正在检查本次实际发送给图片模型的封面提示词")
                prompt_preflight = preflight_generation_prompt_batch(
                    project_id,
                    [
                        {"target": output_path.name, "label": label, "prompt": prompt}
                        for label, prompt, output_path, _output_size in cover_jobs
                    ],
                    purpose="cover",
                )
                if prompt_preflight.get("changed_count"):
                    add(f"[gate] 封面生图前提示词闸门：已自动改写 {prompt_preflight.get('changed_count')} 条实际封面提示词")
                for item in prompt_preflight.get("issues", [])[:4] if isinstance(prompt_preflight.get("issues"), list) else []:
                    if isinstance(item, dict):
                        level = "阻止" if item.get("level") == "risk" else "提醒"
                        add(f"[gate] {level}：{item.get('where', '')} - {item.get('issue', '')}；建议：{item.get('fix', '')}")
                if not prompt_preflight.get("generation_safe", prompt_preflight.get("passed")):
                    raise RuntimeError("封面生图前提示词闸门未通过，已停止调用图片接口。")
                final_prompt_map = prompt_preflight.get("final_prompts") if isinstance(prompt_preflight.get("final_prompts"), dict) else {}
                cover_jobs = [
                    (
                        label,
                        ensure_cover_text_directives(
                            clean_text(str(final_prompt_map.get(output_path.name) or prompt)),
                            required_cover_title,
                            required_cover_subtitle,
                            project_output_language(project),
                        ),
                        output_path,
                        output_size,
                    )
                    for label, prompt, output_path, output_size in cover_jobs
                ]
                add(f"[gate] 封面生图前提示词闸门通过：{prompt_preflight.get('score', 0)} 分，开始调用图片模型")
            add(f"[covers] {provider_desc}")
            if provider["key"] in {"apiyi", "third_party"}:
                add("[covers] OpenAI 兼容文生图封面已切换为串行生成")
            if provider["key"] == "chatgpt_web_handoff":
                add("[covers] ChatGPT 网页接力：只打开 chatgpt.com，不会唤起桌面软件")
            if provider["key"] == "chatgpt_desktop_handoff":
                add("[covers] ChatGPT Classic 手动接力：提示词已复制，需手动粘贴发送并把封面保存到目标路径")
            if provider["key"] == "chatgpt_handoff":
                add("[covers] ChatGPT 旧版接力配置：会按旧设置等待封面文件保存完成")
            if provider["key"] == "chatgpt_web_auto":
                add("[covers] ChatGPT 网页自动化：会自动发送提示词、等待图片并保存到项目目录；首次使用需要在弹出浏览器中登录")
            if provider["key"] == "imageai_playground":
                add("[covers] GPT Image Playground 网页模式：会打开 imageai.centos.hk，自动提交封面提示词并保存图片")
            for label, prompt, output_path, output_size in cover_jobs:
                add(f"[covers] 开始生成 {label}")
                await asyncio.to_thread(generate_configured_image_safely, prompt, output_path, output_size, "cover", env, add, template)
                cover_candidate_auto_enabled = bool(
                    storage.get_project_settings(project_id).get("cover_candidate_auto_enabled", False)
                )
                if output_path.name == "cover_landscape.png" and cover_candidate_auto_enabled:
                    discard_cover_competition(project_id, reason="primary_cover_regenerated")
                audit = read_image_audit(output_path)
                if audit.get("attempt", 1) > 1:
                    add(f"[covers] {label} 自检后重绘 {audit.get('attempt')} 次")
                if audit.get("severity") == "soft" and audit.get("reasons"):
                    add(f"[covers] {label} 自检提示：{', '.join(str(item) for item in audit.get('reasons', []))}")
                add(f"[covers] 已完成 {label}")
                if output_path.name == "cover_landscape.png" and cover_candidate_auto_enabled:
                    candidate_path = storage.project_file(project_id, "covers/candidates/cover_landscape_b.png")
                    try:
                        second_concept = cover_concepts[1] if len(cover_concepts) > 1 else None
                        candidate_prompt = build_cover_candidate_prompt(
                            project_id,
                            cover_concept_base_prompt or prompt,
                            concept=second_concept,
                        )
                        candidate_preflight = preflight_generation_prompt_batch(
                            project_id,
                            [
                                {
                                    "target": "cover_landscape_b.png",
                                    "label": "横屏封面候选 B",
                                    "prompt": candidate_prompt,
                                }
                            ],
                            purpose="cover",
                        )
                        if not candidate_preflight.get("passed"):
                            raise RuntimeError("封面候选提示词自检未通过")
                        candidate_prompt_map = (
                            candidate_preflight.get("final_prompts")
                            if isinstance(candidate_preflight.get("final_prompts"), dict)
                            else {}
                        )
                        candidate_prompt = ensure_cover_text_directives(
                            clean_text(str(candidate_prompt_map.get("cover_landscape_b.png") or candidate_prompt)),
                            required_cover_title,
                            required_cover_subtitle,
                            project_output_language(project),
                        )
                        add("[covers] 封面关键位：3 个构思已完成文字筛选，正在生成排名第 2 的方案；其它比例不追加候选")
                        await asyncio.to_thread(
                            generate_configured_image_safely,
                            candidate_prompt,
                            candidate_path,
                            output_size,
                            "cover",
                            env,
                            add,
                            template,
                        )
                        candidate_final_prompt = read_generated_prompt(candidate_path, candidate_prompt)
                        competition = await asyncio.to_thread(
                            save_cover_competition,
                            project_id,
                            output_path,
                            candidate_path,
                            read_generated_prompt(output_path, prompt),
                            candidate_final_prompt,
                            cover_concept_plan,
                        )
                        recommendation = clean_text(str(competition.get("ai_recommended_variant") or "CURRENT"))
                        current_score = int(
                            ((competition.get("current") or {}).get("score", 0))
                            if isinstance(competition.get("current"), dict)
                            else 0
                        )
                        candidate_score = int(
                            ((competition.get("candidates") or [{}])[0].get("score", 0))
                            if isinstance(competition.get("candidates"), list) and competition.get("candidates")
                            else 0
                        )
                        add(
                            f"[covers] 封面真实成图复评：方案 A {current_score} 分，方案 B {candidate_score} 分，推荐 {recommendation}"
                        )
                        if image_review_status(project_id).get("required") is False:
                            automatic = resolve_cover_candidates_automatically(project_id)
                            if automatic.get("resolved_count"):
                                adopted = automatic.get("resolved", [{}])[0]
                                add(f"[covers] 全自动模式已采用封面方案 {adopted.get('variant', recommendation)}")
                    except Exception as exc:
                        _cleanup_generated_tmp(candidate_path)
                        discard_cover_competition(project_id, reason="cover_competition_unavailable")
                        add(f"[covers] 封面第 2 构思未完成，保留已通过自检的正式封面 A：{exc}")
            master_path = storage.project_file(project_id, "covers/cover_landscape.png")
            derive_cover_variants(master_path)
            mark_image_review_dirty(project_id, "主封面已重新生成，其余比例已本地适配，等待人工确认")
            add("[covers] 主封面已生成，图文与竖屏比例已本地适配")
            return True, scene_lines

        if step == "motion_clips":
            add("[motion_clips] 正在按 Capsule 生产合同筛选首镜、核心证据和反转镜头")
            try:
                result = await asyncio.to_thread(generate_project_motion_clips, project_id, log=add)
            except Exception as exc:
                error_message = user_facing_error(exc)
                checkpoint = storage.read_json(project_motion_clip_manifest_path(project_id), {})
                preserved_clips = checkpoint.get("clips", []) if isinstance(checkpoint, dict) else []
                preserved_clips = preserved_clips if isinstance(preserved_clips, list) else []
                result = {
                    "version": MOTION_CLIP_MANIFEST_VERSION,
                    # Dynamic clips are an enhancement. If at least one clip is
                    # complete, publish that checkpoint as usable and let the
                    # editor fill remaining scenes with stable image motion.
                    # This prevents the auto-production supervisor from
                    # repeatedly retrying the failed second clip.
                    "status": "ready" if preserved_clips else "fallback",
                    "partial": bool(preserved_clips),
                    "provider": clean_text(runtime_env().get("VIDEO_PROVIDER") or "auto"),
                    "reason": error_message,
                    "clips": preserved_clips,
                    "generated_count": len(preserved_clips),
                    "updated_at": storage.now_ts(),
                }
                storage.write_json(project_motion_clip_manifest_path(project_id), result)
                if preserved_clips:
                    add(
                        f"[motion_clips] 已保留前面完成的 {len(preserved_clips)} 段；"
                        "下次从缺失片段继续，已完成片段不会重做"
                    )
                add(
                    "[motion_clips] 外部视频增强本轮未返回有效片段，已自动切换为场景原图轻运动；"
                    "动态镜头保留为下次可重试增强项，本轮继续进入成片"
                )
            status = clean_text(result.get("status"))
            if status in {"disabled", "skipped", "fallback"}:
                add(f"[motion_clips] {result.get('reason') or '动态镜头已关闭'}，成片继续使用场景原图轻运动")
            else:
                add(
                    "[motion_clips] 动态镜头已就绪："
                    f"新生成 {int(result.get('generated_count', 0) or 0)} 段，"
                    f"复用 {int(result.get('reused_count', 0) or 0)} 段"
                )
            project_visual_master_path(project_id).unlink(missing_ok=True)
            project_visual_master_meta_path(project_id).unlink(missing_ok=True)
            return True, scene_lines

        if step == "bgm":
            audio_path = storage.project_file(project_id, "audio/podcast.mp3")
            audio_duration = safe_probe_duration(audio_path) if audio_path.exists() else 0.0
            before = project_bgm_status(project_id)
            emit_ffmpeg_progress(
                progress_callback,
                {
                    "phase": "bgm_analyze",
                    "message": "正在分析本期主题、口播情绪和频道气质",
                    "percent": 8.0,
                    "eta_seconds": None,
                },
            )
            add(
                "[bgm] 已启动按主题匹配："
                f"目标 {before.get('desired_label') or before.get('label') or '自动判断'}"
                f"；{before.get('desired_reason') or before.get('reason') or '正在分析本期口播'}"
            )
            emit_ffmpeg_progress(
                progress_callback,
                {
                    "phase": "bgm_generate",
                    "message": "主题方向已确定，正在检索或生成可用音乐",
                    "percent": 35.0,
                    "eta_seconds": None,
                },
            )
            result = await asyncio.to_thread(
                ensure_project_bgm,
                project_id,
                template_key,
                audio_duration=audio_duration,
                force_rematch=True,
                status_callback=add,
            )
            selector = result.get("selector") if isinstance(result.get("selector"), dict) else {}
            bpm = result.get("bpm") or selector.get("bpm", [])
            bpm_text = f" · BPM {bpm[0]}-{bpm[-1]}" if isinstance(bpm, list) and bpm else ""
            audit = result.get("audio_vocal_audit") if isinstance(result.get("audio_vocal_audit"), dict) else {}
            track = result.get("track") if isinstance(result.get("track"), dict) else {}
            rejected_count = int(track.get("rejected_candidate_count", 0) or 0)
            if audit.get("status") == "passed":
                add(f"[bgm] 实际音频人声检测通过{f'，此前已淘汰 {rejected_count} 首候选' if rejected_count else ''}")
            elif audit.get("status") in {"inconclusive", "unavailable"}:
                add(f"[bgm] 提醒：{audit.get('reason') or '实际音频人声检测未完成'}")
            add(
                "[bgm] 主题音乐已就绪："
                f"{result.get('label') or result.get('mood') or result.get('source')}"
                f"{bpm_text} · {result.get('reason') or result.get('source')}"
            )
            emit_ffmpeg_progress(
                progress_callback,
                {
                    "phase": "bgm_complete",
                    "message": "主题 BGM 已匹配完成",
                    "percent": 100.0,
                    "eta_seconds": 0,
                },
            )
            return True, scene_lines

        if step == "video":
            preflight = video_preflight_report(project_id)
            if not preflight.get("passed"):
                for item in preflight.get("blockers", []):
                    if isinstance(item, dict):
                        add(f"[preflight] 阻止：{item.get('where', '')} - {item.get('issue', '')}；建议：{item.get('fix', '')}")
                raise RuntimeError("成片前总检未通过，请先修复阻止项。")
            for item in preflight.get("warnings", []):
                if isinstance(item, dict):
                    add(f"[preflight] 提醒：{item.get('where', '')} - {item.get('issue', '')}")
            add("[preflight] 成片前总检通过")
            audio_path = storage.project_file(project_id, "audio/podcast.mp3")
            subtitle_path = storage.project_file(project_id, "audio/subtitles.srt")
            scene_paths = find_scene_image_paths(project_id)
            output_path = storage.project_file(project_id, "releases/final-video.mp4")
            director = storage.read_json(visual_director_path(project_id), {})
            edit_direction = director.get("edit_direction") if isinstance(director.get("edit_direction"), dict) else {}
            sound_direction = director.get("sound_direction") if isinstance(director.get("sound_direction"), dict) else {}
            if edit_direction or sound_direction:
                pace = clean_text(str(edit_direction.get("overall_pace") or "默认硬切节奏"))
                policy = clean_text(str(edit_direction.get("transition_policy") or "无转场"))
                add(f"[director] 成片节奏：{pace}；转场策略：{policy}")
            if BGM_FEATURE_ENABLED:
                project_info = storage.get_project(project_id)
                template_key = clean_text(str(project_info.get("template") or ""))
                bgm_state = ensure_project_bgm(project_id, template_key, audio_duration=safe_probe_duration(audio_path))
                if bgm_state.get("path"):
                    track = bgm_state.get("track") if isinstance(bgm_state.get("track"), dict) else {}
                    track_name = clean_text(str(track.get("name") or ""))
                    track_license = clean_text(str(track.get("license") or ""))
                    bgm_label = clean_text(str(bgm_state.get("label") or ""))
                    bgm_volume = director_bgm_volume(project_id, runtime_env())
                    add(
                        "[bgm] 已准备背景音乐："
                        f"{bgm_state.get('source')}"
                        f"{' · ' + bgm_label if bgm_label else ''}"
                        f"{' · ' + track_name if track_name else ''}"
                        f"{' · ' + track_license if track_license else ''}"
                        f" · 混音音量 {bgm_volume:.2f}"
                    )
            add("[video] 已启用逐节拍推拉与平移；信息层和字幕保持稳定")
            result_path = await asyncio.to_thread(
                compose_final_video,
                project_id,
                title,
                scene_paths,
                audio_path,
                subtitle_path if subtitle_path.exists() else None,
                output_path,
                progress_callback,
            )
            size_mb = result_path.stat().st_size / 1048576.0 if result_path.exists() else 0.0
            add(f"[video] 已生成 final-video.mp4 ({size_mb:.1f} MB)")
            try:
                brief_text = storage.get_brief(project_id)
                cached_quality = storage.get_report(project_id, "quality_gate")
                mix_meta = storage.read_json(project_video_mix_meta_path(project_id), {})
                reuse_quality_sections = bool(
                    isinstance(mix_meta, dict)
                    and mix_meta.get("visual_master_cache_hit")
                    and quality_gate_non_video_sections_current(
                        project_id,
                        cached_quality,
                        brief_text,
                        content,
                    )
                )
                emit_ffmpeg_progress(
                    progress_callback,
                    {
                        "phase": "quality_check",
                        "message": (
                            "画面质量报告仍为当前版本，正在复核新视频的时长、字幕覆盖和媒体完整性"
                            if reuse_quality_sections
                            else "视频已生成，正在检查文案、图片、时长、字幕覆盖和画面完整性"
                        ),
                        "percent": 97.0,
                        "eta_seconds": None,
                    },
                )
                if reuse_quality_sections and isinstance(cached_quality, dict):
                    report = await asyncio.to_thread(
                        refresh_quality_gate_video_section,
                        project_id,
                        cached_quality,
                        brief_text,
                        content,
                    )
                    add("[quality] 画面母版未变化，已复用文案、编导、图片和 AI 总编检查，仅复核最终媒体")
                else:
                    report = await asyncio.to_thread(quality_gate_report, project_id, brief_text, content)
                storage.save_report(project_id, "quality_gate", report)
                add(f"[quality] 质量总检完成：{report.get('overall_score', 0)} 分，{report.get('verdict', '')}")
                emit_ffmpeg_progress(
                    progress_callback,
                    {
                        "phase": "complete",
                        "message": "成片与质量总检已完成",
                        "percent": 100.0,
                        "eta_seconds": 0,
                    },
                )
            except Exception as exc:
                add(f"[quality] 质量总检暂未完成：{exc}")
            return True, scene_lines
            template_key = clean_text(project.get("template", ""))
            template = storage.get_template(template_key) if template_key else {"name": "", "brand_name": ""}
            add("[video] 优先调用原版 composer 合成最终 mp4")
            try:
                result_path = await asyncio.to_thread(
                    compose_original_video,
                    project_id,
                    project,
                    template,
                    content,
                    scene_paths,
                    audio_path,
                    subtitle_path if subtitle_path.exists() else None,
                    output_path,
                )
                add("[video] 已切回原版成片链路")
            except Exception as exc:
                add(f"[video] 原版 composer 调用失败，回退本地 ffmpeg：{exc}")
                result_path = await asyncio.to_thread(
                    compose_final_video,
                    project_id,
                    title,
                    scene_paths,
                    audio_path,
                    subtitle_path if subtitle_path.exists() else None,
                    output_path,
                )
            size_mb = result_path.stat().st_size / 1048576.0 if result_path.exists() else 0.0
            add(f"[video] 已生成 final-video.mp4 ({size_mb:.1f} MB)")
            return True, scene_lines

        return False, scene_lines

    async def _handle_step(
        self,
        project_id: int,
        project: dict[str, Any],
        title: str,
        step: str,
        content: str,
        scene_lines: list[str],
        log_lines: list[str],
        job_id: str,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
    ) -> list[str]:
        handled, next_scene_lines = await self._handle_real_step(
            project_id,
            project,
            title,
            step,
            content,
            scene_lines,
            log_lines,
            job_id,
            progress_callback,
        )
        if handled:
            return next_scene_lines

        mode = project.get("template_mode", "video")
        dialogue_lines = parse_dialogue_lines(content, mode)
        highlights = parse_highlights(content)

        def add(line: str) -> None:
            log_lines.append(line)
            snapshot = storage.load_latest_job(project_id) or {}
            snapshot["log"] = "\n".join(log_lines)
            storage.save_latest_job(project_id, snapshot)

        if step == "audio":
            add("[audio] 正在生成本地演示口播音频 podcast.wav")
            tts_dialogue = current_spoken_dialogue_payload(project_id, content, mode, project["topic_name"])
            spoken_lines = [item["text"] for item in tts_dialogue]
            duration = max(2.2, min(12.0, len(spoken_lines) * 0.65 or len(scene_lines) * 0.8 or 2.2))
            await asyncio.sleep(0.4)
            write_wave_file(storage.project_file(project_id, "audio/podcast.wav"), duration=duration, freq=440.0)
            storage.write_text(
                storage.project_file(project_id, "audio/podcast.txt"),
                ("\n".join(spoken_lines) or "\n".join(scene_lines) or clean_text(content) or project["topic_name"]) + "\n",
            )
            add("[audio] 口播音频与稿本文本已写出")
            return scene_lines

        if step == "subtitles":
            add("[subtitles] 正在对齐字幕")
            await asyncio.sleep(0.35)
            scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"], prefer_timeline=False)
            scene_count_info = resolve_project_scene_count(project, content, mode, candidate_count=len(scene_lines), audio_ms=len(dialogue_lines) * 4000)
            desired_scene_count = int(scene_count_info.get("final", len(scene_lines)) or len(scene_lines) or 1)
            scene_lines = normalize_scene_prompt_count(scene_lines, desired_scene_count, project["topic_name"], mode)
            spoken = dialogue_lines or scene_lines
            fake_utterances = []
            for idx, line in enumerate(spoken[: max(1, desired_scene_count)], start=1):
                fake_utterances.append(
                    {
                        "start_ms": (idx - 1) * 4000,
                        "end_ms": idx * 4000,
                        "text": clean_text(line),
                    }
                )
            preview_audio_ms = max(1000, len(fake_utterances) * 4000)
            timeline = build_scene_timeline_for_scene_count(fake_utterances, scene_lines, desired_scene_count, preview_audio_ms)
            write_srt_entries(storage.project_file(project_id, "audio/subtitles.srt"), fake_utterances)
            sync_project_subtitle_files(project_id)
            storage.write_text(
                storage.project_file(project_id, "audio/scene_timeline.json"),
                json.dumps(timeline, ensure_ascii=False, indent=2),
            )
            aligned_lines = [clean_text(str(item.get("prompt", ""))) for item in timeline.get("scenes", []) if isinstance(item, dict)]
            summary = storage.get_summary(project_id)
            if summary:
                original_scene_count = int(summary.get("scene_count", 0) or 0)
                summary["scene_count_script"] = int(summary.get("scene_count_script", original_scene_count) or original_scene_count)
                summary["scene_count"] = len(aligned_lines)
                summary["scene_count_aligned"] = len(aligned_lines)
                summary["scene_count_source"] = "fixed_setting" if scene_count_info.get("mode") == "fixed" else "preview_timeline"
                summary["scene_count_audio_ms"] = preview_audio_ms
                storage.save_summary(project_id, summary)
            add(
                f"[scene_timeline] 使用对齐后的场景图列表：候选 {len(scene_lines)} 张 -> 最终 {len(aligned_lines)} 张"
            )
            scene_count_label = "固定张数" if scene_count_info.get("mode") == "fixed" else "预演时轴"
            add(f"[scene_timeline] 本次张数锁定：{len(aligned_lines)} 张（{scene_count_label}，音频 {preview_audio_ms / 1000:.1f}s）")
            scene_plan = write_scene_plan(project_id, project, content, timeline, aligned_lines or scene_lines)
            add(f"[scene_timeline] 写出 audio/scene_timeline.json，共 {len(aligned_lines)} 段")
            add(f"[scene_plan] 写出 audio/scene_plan.json，共 {scene_plan.get('scene_count', len(aligned_lines))} 镜")
            add("[subtitles] subtitles.srt 与 scene_timeline.json 已生成")
            return aligned_lines or scene_lines

        if step == "images":
            if not scene_lines:
                scene_lines = current_scene_prompts(project_id, content, mode, project["topic_name"])
            add(f"[images] 开始生成 {len(scene_lines)} 张场景图")
            scene_records = []
            existing_records = storage.read_json(storage.project_file(project_id, "scenes/scene_prompts.json"), [])
            if not isinstance(existing_records, list):
                existing_records = []
            prompt_context = project_image_context_hashes(project_id, content)
            removed = storage.cleanup_extra_scene_outputs(project_id, len(scene_lines))
            if removed:
                add(f"[images] 已清理 {removed} 个超出当前场景数量的旧文件")
            for idx, prompt in enumerate(scene_lines, start=1):
                reused_record = reusable_scene_image_record(
                    project_id,
                    idx,
                    prompt,
                    existing_records,
                    content_hash=prompt_context.get("content_hash", ""),
                    topic_hash=prompt_context.get("topic_hash", ""),
                )
                if reused_record:
                    scene_records.append(reused_record)
                    add(f"[images] 复用上一轮旧图 {idx}/{len(scene_lines)} -> {reused_record.get('filename')}")
                    continue
                filename = f"s_{idx:02d}.svg"
                label = highlights[idx - 1] if idx - 1 < len(highlights) else f"场景 {idx}"
                write_svg_card(
                    storage.project_file(project_id, f"scenes/{filename}"),
                    label,
                    prompt,
                    "#2563eb" if idx % 2 else "#7c3aed",
                    (1280, 720),
                )
                scene_records.append(
                    {
                        "filename": filename,
                        "label": label,
                        "prompt": prompt,
                        "source_prompt": normalize_image_prompt(prompt),
                        "content_hash": prompt_context.get("content_hash", ""),
                        "topic_hash": prompt_context.get("topic_hash", ""),
                        "channel_id": prompt_context.get("channel_id", ""),
                        "episode_id": prompt_context.get("episode_id", ""),
                        "manifest_version": prompt_context.get("manifest_version", ""),
                        "prompt_policy_version": IMAGE_PROMPT_POLICY_VERSION,
                        "updated_at": storage.now_ts(),
                    }
                )
                add(f"[images] 进度 {idx}/{len(scene_lines)} -> {filename}")
                await asyncio.sleep(0.18)
            scene_records.sort(key=scene_record_index)
            storage.write_text(
                storage.project_file(project_id, "scenes/scene_prompts.json"),
                json.dumps(scene_records, ensure_ascii=False, indent=2),
            )
            add("[images] 场景图已处理完成")
            return scene_lines

        if step == "covers":
            summary = storage.get_summary(project_id)
            cover_title = summary.get("cover_title") or title
            cover_subtitle = summary.get("cover_subtitle") or fallback_cover_subtitle(title)
            add("[covers] 生成横屏和竖屏发布封面")
            await asyncio.sleep(0.35)
            write_svg_card(
                storage.project_file(project_id, "covers/cover_landscape.svg"),
                cover_title,
                cover_subtitle or "横屏封面",
                "#f97316",
                (1280, 720),
            )
            write_svg_card(
                storage.project_file(project_id, "covers/cover_portrait.svg"),
                cover_title,
                cover_subtitle or "竖屏封面",
                "#db2777",
                (900, 1200),
            )
            write_svg_card(
                storage.project_file(project_id, "covers/cover_story.svg"),
                cover_title,
                cover_subtitle or "横图封面",
                "#059669",
                (1200, 900),
            )
            add("[covers] 封面图已生成")
            return

        if step == "article":
            add("[article] 正在生成图文发布稿")
            await asyncio.sleep(0.25)
            lines = parse_dialogue_lines(content, "article") or scene_lines
            article_body = "# 图文发布稿\n\n" + "\n".join(f"- 第 {idx + 1} 段：{line}" for idx, line in enumerate(lines))
            storage.write_text(storage.project_file(project_id, "article/publish-pack.md"), article_body + "\n")
            add("[article] 图文包 markdown 已写出")
            return

        if step == "video":
            add("[video] 正在拼装本地预演成片")
            await asyncio.sleep(0.45)
            scene_records = storage.read_json(storage.project_file(project_id, "scenes/scene_prompts.json"), [])
            scenes = []
            for idx, prompt in enumerate(scene_lines, start=1):
                filename = f"s_{idx:02d}.svg"
                path = storage.project_file(project_id, f"scenes/{filename}")
                if not path.exists():
                    continue
                record = next((item for item in scene_records if item.get("filename") == filename), {})
                scenes.append(
                    {
                        "filename": filename,
                        "label": record.get("label") or f"场景 {idx}",
                        "prompt": record.get("prompt") or prompt,
                    }
                )
            write_preview_html(project_id, title, scenes)
            storage.write_text(
                storage.project_file(project_id, "releases/final-video.txt"),
                "这是当前本地版本的成片占位文件。正式 ffmpeg / 外部模型链路后续可继续替换成真实 mp4。\n",
            )
            add("[video] 已生成 final-preview.html 与 final-video.txt")
            return scene_lines

        add(f"[{step}] 未识别的步骤，已跳过")
        return scene_lines


