def _safe_json_from_text(text: str) -> dict[str, Any]:
    cleaned = strip_code_fences(text)
    try:
        payload = json.loads(cleaned)
        return payload if isinstance(payload, dict) else {}
    except json.JSONDecodeError:
        pass
    match = re.search(r"(?s)\{.*\}", cleaned or "")
    if not match:
        return {}
    try:
        payload = json.loads(match.group(0))
    except json.JSONDecodeError:
        return {}
    return payload if isinstance(payload, dict) else {}


def _recover_truncated_json_list(text: str, key: str) -> list[dict[str, Any]]:
    """Recover complete objects when a model response stops inside a JSON array."""
    cleaned = strip_code_fences(text)
    match = re.search(rf'"{re.escape(key)}"\s*:\s*\[', cleaned)
    if not match:
        return []
    cursor = match.end()
    decoder = json.JSONDecoder()
    recovered: list[dict[str, Any]] = []
    while cursor < len(cleaned):
        while cursor < len(cleaned) and cleaned[cursor] in " \t\r\n,":
            cursor += 1
        if cursor >= len(cleaned) or cleaned[cursor] == "]":
            break
        try:
            value, consumed = decoder.raw_decode(cleaned[cursor:])
        except json.JSONDecodeError:
            break
        if isinstance(value, dict):
            recovered.append(value)
        cursor += consumed
    return recovered


def _expand_topic_direction_candidates(
    *,
    direction: str,
    brand: str,
    references: list[dict[str, Any]],
    existing_topics: list[str],
    desired_count: int,
) -> list[dict[str, Any]]:
    """Expand a broad direction such as “汽车” into actual candidate topics."""
    direction = clean_text(direction)
    raw: list[dict[str, Any]] = []
    for item in references:
        title = clean_text(str(item.get("title") or ""))
        if not title:
            continue
        title = re.split(r"\s+[-|｜]\s+", title, maxsplit=1)[0]
        if re.search(r"[\u4e00-\u9fff]", direction) and len(re.findall(r"[\u4e00-\u9fff]", title)) < 3:
            continue
        raw.append(
            {
                "title": title[:80],
                "brief": clean_text(str(item.get("snippet") or ""))[:220],
                "why": f"来自近期公开信息，并围绕“{direction}”形成可继续核实的具体切口。",
                "search_query": title,
                "target_duration": "按信息量自适应",
                "score": 3.8,
                "source": "prompt_news",
            }
        )
        if len(raw) >= desired_count:
            break
    if raw:
        return _normalize_topic_candidates(raw, existing_topics)[:desired_count]
    angle_templates = [
        ("最近真正改变普通人的，不是参数，而是这项变化", "从近期变化切入，解释它会影响谁、影响什么以及判断方法。"),
        ("看似升级，为什么有人用完反而更麻烦？", "选择一个真实使用场景，拆解宣传卖点与实际体验之间的差距。"),
        ("最容易被忽略的成本，藏在购买之后", "围绕后续费用、使用门槛或维护成本形成消费决策内容。"),
        ("同样的预算，差别到底出现在哪一步？", "用两个可核实方案做条件一致的对比，突出真正决定结果的变量。"),
        ("这项新规或新技术，先影响的可能不是厂商", "把行业变化翻译成普通用户能感知的具体后果。"),
        ("发布会上讲得很热，实际值得关注的只有这件事", "从最新产品或事件中筛出一个具有证据和评论空间的核心变化。"),
        ("现在入手还是再等等？先看这三个信号", "围绕价格、成熟度和使用场景给出可执行的判断框架。"),
        ("大家都盯着功能，真正的门槛却在另一边", "用反常识角度寻找供应链、服务、隐私或落地条件。"),
    ]
    for suffix, brief in angle_templates:
        raw.append(
            {
                "title": f"{direction}：{suffix}"[:80],
                "brief": brief,
                "why": f"将“{direction}”作为选题范围，而不是直接把关键词当作成片标题。",
                "search_query": " ".join(part for part in (brand, direction, suffix) if part),
                "target_duration": "按信息量自适应",
                "score": 3.4,
                "source": "prompt_expansion",
            }
        )
        if len(raw) >= desired_count * 2:
            break
    normalized = _normalize_topic_candidates(raw, existing_topics)
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in normalized:
        key = re.sub(r"\W+", "", clean_text(str(item.get("title") or "")).lower())
        if not key or key in seen:
            continue
        seen.add(key)
        deduped.append(item)
        if len(deduped) >= desired_count:
            break
    return deduped


def _channel_topic_keywords(template: dict[str, Any]) -> list[str]:
    source = "\n".join(
        [
            str(template.get("key") or ""),
            str(template.get("name") or ""),
            str(template.get("brand_name") or ""),
            str(template.get("target_audience") or ""),
            str(template.get("channel_voice") or ""),
            str(template.get("interaction_goal") or ""),
            str(template.get("topic_mining_hint") or ""),
            str(template.get("release_tags") or ""),
            str(template.get("prompt") or "")[:1400],
        ]
    )
    domain_vocabulary = (
        "人工智能", "AI", "大模型", "机器人", "科技", "手机", "芯片", "智能设备", "互联网",
        "效率工具", "消费电子", "智能汽车", "软件", "应用", "隐私", "网络安全",
        "健康", "医疗", "血压", "血糖", "养老", "老人", "中老年", "营养", "睡眠",
        "财经", "消费", "商品", "测评", "家电", "汽车", "职场", "教育", "家庭",
        "诈骗", "安全", "社会", "民生", "法律", "体育", "旅行", "美食",
    )
    domain_terms = [term for term in domain_vocabulary if term.lower() in source.lower()]
    tokens = list(extract_tokens(source))
    ignored = {
        "content", "markdown", "prompt", "video", "brief", "meta", "16", "9", "3", "4", "cover", "default",
        "不要", "禁止", "优先", "人物", "摄影", "数字", "自然", "画面", "内容", "频道", "短视频",
        "标题", "封面", "风格", "生成", "必须", "可以", "使用", "真实", "信息",
    }
    ranked = sorted(
        (token for token in tokens if token not in ignored and len(token) >= 2),
        key=lambda item: (-source.count(item), item),
    )
    return dedupe_clauses([*domain_terms, *ranked])[:10]


def _topic_duplicate_penalty(title: str, existing_topics: list[str]) -> float:
    tokens = extract_tokens(title)
    if not tokens:
        return 0.0
    return max((overlap_score(tokens, item) for item in existing_topics), default=0.0)


def _normalize_topic_candidates(raw_candidates: Any, existing_topics: list[str]) -> list[dict[str, Any]]:
    if not isinstance(raw_candidates, list):
        return []
    candidates: list[dict[str, Any]] = []
    for item in raw_candidates:
        if not isinstance(item, dict):
            continue
        title = clean_text(str(item.get("title") or item.get("topic") or ""))
        if not title:
            continue
        try:
            score = float(item.get("score") or 4.0)
        except (ValueError, TypeError):
            score = 4.0
        duplicate_penalty = _topic_duplicate_penalty(title, existing_topics)
        candidates.append(
            {
                "title": title[:80],
                "brief": clean_text(str(item.get("brief") or item.get("angle") or item.get("summary") or "")),
                "why": clean_text(str(item.get("why") or item.get("reason") or item.get("value") or "")),
                "search_query": clean_text(str(item.get("search_query") or item.get("query") or title)),
                "target_duration": clean_text(str(item.get("target_duration") or item.get("duration") or "按信息量自适应")),
                "score": max(0.0, min(5.0, score)),
                "duplicate_penalty": round(duplicate_penalty, 3),
                "rank_score": round(max(0.0, score - duplicate_penalty * 2.2), 3),
                "source": clean_text(str(item.get("source") or "deepseek")),
            }
        )
    candidates.sort(key=lambda item: item.get("rank_score", 0), reverse=True)
    return candidates


def apply_current_news_candidate_scores(
    candidates: list[dict[str, Any]],
    references: list[dict[str, Any]],
    channel_terms: list[str] | None = None,
) -> list[dict[str, Any]]:
    def topical_text(value: str) -> str:
        cleaned = clean_text(value)
        cleaned = re.sub(r"(?<!\d)20\d{2}(?!\d)", " ", cleaned)
        cleaned = re.sub(r"\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b", " ", cleaned, flags=re.IGNORECASE)
        cleaned = re.sub(r"\d{1,2}\s*(?:月|日|号|时|点|分)", " ", cleaned)
        cleaned = re.sub(r"\b(?:latest|today|yesterday|live|news|update)\b", " ", cleaned, flags=re.IGNORECASE)
        return clean_text(cleaned)

    scored: list[dict[str, Any]] = []
    for candidate in candidates:
        if _topic_reference_block_reason(
            {
                "title": candidate.get("title", ""),
                "snippet": candidate.get("brief", ""),
                "url": candidate.get("url", ""),
            },
            channel_terms or [],
        ):
            continue
        subject = topical_text(f"{candidate.get('title', '')} {candidate.get('brief', '')}")
        matches: list[tuple[int, dict[str, Any]]] = []
        for reference in references:
            if _topic_reference_block_reason(reference, channel_terms or []):
                continue
            reference_text = topical_text(f"{reference.get('title', '')} {reference.get('snippet', '')}")
            support_score = source_information_match_score(reference_text, subject)
            if support_score >= 24:
                matches.append((support_score, reference))
        matches.sort(key=lambda pair: (-pair[0], int((pair[1].get("freshness") or {}).get("age_days") or 9999)))
        evidence_count = len(matches)
        source_domains = set()
        for _, item in matches:
            url = clean_text(str(item.get("url") or ""))
            domain = urllib.parse.urlparse(url).netloc.lower() if url else ""
            publisher = clean_text(str(item.get("source") or ""))
            identity = publisher.lower() if domain == "news.google.com" and publisher else domain
            if identity:
                source_domains.add(identity)
        source_domains.discard("")
        ages = [
            int(item.get("age_days") if item.get("age_days") is not None else (item.get("freshness") or {}).get("age_days"))
            for _, item in matches
            if item.get("age_days") is not None or (item.get("freshness") or {}).get("age_days") is not None
        ]
        latest_age_days = min(ages) if ages else None
        original_score = float(candidate.get("score") or 0.0)
        freshness_adjustment = (
            0.55
            if latest_age_days is not None and latest_age_days <= 7
            else (0.1 if latest_age_days is not None and latest_age_days <= CURRENT_NEWS_MAX_AGE_DAYS else -0.8)
        )
        evidence_adjustment = 0.45 if len(source_domains) >= 2 else (-0.35 if evidence_count == 1 else -1.5)
        adjusted_score = min(original_score, 3.0) if evidence_count < 2 else original_score
        duplicate_penalty = float(candidate.get("duplicate_penalty") or 0.0)
        specificity = _topic_specificity_score(str(candidate.get("title") or ""), str(candidate.get("brief") or ""))
        visual_potential = _topic_visual_score(str(candidate.get("title") or ""), str(candidate.get("brief") or ""))
        rank_score = round(
            max(
                0.0,
                min(
                    5.0,
                    adjusted_score
                    - duplicate_penalty * 2.2
                    + freshness_adjustment
                    + evidence_adjustment
                    + (specificity - 0.5) * 0.6
                    + (visual_potential - 0.5) * 0.35,
                ),
            ),
            3,
        )
        issues: list[str] = []
        if len(source_domains) < 2:
            issues.append("独立来源不足")
        if latest_age_days is None:
            issues.append("发布日期待确认")
        elif latest_age_days > 7:
            issues.append("不是近7天事件")
        if duplicate_penalty >= 0.55:
            issues.append("接近历史选题")
        if specificity < 0.5:
            issues.append("题目仍偏宽泛")
        if visual_potential < 0.5:
            issues.append("画面抓手偏弱")
        readiness = "strong" if not issues and rank_score >= 3.8 else ("review" if evidence_count >= 1 else "weak")
        entry = dict(candidate)
        entry.update(
            {
                "score": round(max(0.0, adjusted_score), 3),
                "news_evidence_count": evidence_count,
                "independent_source_count": len(source_domains),
                "latest_age_days": latest_age_days,
                "readiness": readiness,
                "readiness_label": {"strong": "可直接生产", "review": "建议复核", "weak": "证据不足"}[readiness],
                "quality_issues": issues,
                "quality_dimensions": {
                    "specificity": specificity,
                    "visual_potential": visual_potential,
                    "novelty": round(max(0.0, 1.0 - duplicate_penalty), 3),
                },
                "news_evidence": [
                    {
                        "title": clean_text(str(item.get("title") or "")),
                        "url": clean_text(str(item.get("url") or "")),
                        "published_date": clean_text(str(item.get("published_date") or "")),
                        "freshness_status": clean_text(str(item.get("freshness_status") or "")),
                        "support_score": score,
                    }
                    for score, item in matches[:3]
                ],
                "rank_score": rank_score,
            }
        )
        scored.append(entry)
    scored.sort(
        key=lambda item: (
            {"strong": 0, "review": 1, "weak": 2}.get(str(item.get("readiness") or "weak"), 2),
            -int(item.get("news_evidence_count") or 0),
            -float(item.get("rank_score") or 0.0),
        )
    )
    return scored


_REAL_ESTATE_CHANNEL_TERMS = (
    "房地产", "房产", "楼市", "买房", "卖房", "楼盘", "住宅", "置业", "租房", "二手房", "新房",
)

_REAL_ESTATE_LISTING_MARKERS = (
    "售楼处", "售楼部", "楼盘详情", "户型图", "容积率", "置业顾问", "预约看房", "看房热线",
    "售楼电话", "营销中心", "在售房源", "开盘时间", "交房时间", "楼栋信息", "楼盘地址",
    "参考均价", "最新价格", "样板间", "房源信息", "物业费", "开发商",
)

_REAL_ESTATE_SOFT_MARKERS = (
    "楼盘", "房源", "户型", "小区", "住宅", "均价", "开盘", "交房", "看房", "买房", "售楼",
)


def _looks_like_seo_content_farm(text: str) -> bool:
    """Detect stitched download/SEO pages rather than judging only by freshness."""
    lowered = clean_text(text).lower()
    if not lowered:
        return False
    download_markers = (
        "官网下载", "最新版下载", "安卓版下载", "app下载", "软件下载", "安装教程", "功能指南",
        "下载链接", "下载地址", "破解版", "官网最新版", "网站安卓版", "苹果支持文档",
    )
    marker_hits = sum(1 for marker in download_markers if marker.lower() in lowered)
    repeated_promotional_terms = sum(lowered.count(marker) for marker in ("官网", "下载", "最新版", "安装"))
    topic_families = (
        ("赛事预测", "体育竞猜", "比分", "球队", "博彩"),
        ("ai营销", "product hunt", "提示词", "自动化营销"),
        ("游戏", "棋牌", "电竞", "手游"),
        ("安卓版", "app下载", "软件下载", "安装教程", "功能指南"),
        ("妇联", "娱乐圈", "明星", "直播间"),
    )
    family_hits = sum(1 for family in topic_families if any(marker in lowered for marker in family))
    suspicious_prefix = bool(re.search(r"(?:^|\s)[a-z0-9]{1,5}\.[\u4e00-\u9fff]", lowered))
    navigation_markers = (
        "首页", "要闻", "直播间", "法律帮助", "健康生活", "婚姻与家庭", "图秀", "视频",
        "数据平台", "微博", "qzone", "微信", "扫一扫", "文章正文",
    )
    navigation_density = sum(1 for marker in navigation_markers if marker in lowered)
    suspicious_domain = bool(
        re.search(r"\b[a-z0-9-]{2,}\.(?:cc|vip|top|xyz|win|bet|fun)\b", lowered, flags=re.IGNORECASE)
    )
    gambling_markers = (
        "vip网页版登录", "体育预测", "赛事预测", "体育竞猜", "博彩", "赔率", "投注", "投注平台",
        "娱乐城", "娱乐平台", "真人娱乐", "百家乐", "棋牌平台", "体育网", "预测崛起", "尊龙", "凯发",
    )
    gambling_hits = sum(1 for marker in gambling_markers if marker in lowered)
    disguised_gambling_brand = bool(
        re.search(r"(?:开.?云|尊龙|凯发|皇冠).{0,16}(?:登录|官网|平台|娱乐)", lowered)
    )
    synthetic_cta = (
        ("## 行动号召" in text or "行动号召" in lowered)
        and sum(
            1
            for marker in ("立即登录", "github搜索", "下载最新源码", "体验demo", "访问官网", "加入我们的社区")
            if marker in lowered
        )
        >= 2
    )
    return bool(
        marker_hits >= 2
        or repeated_promotional_terms >= 5
        or (family_hits >= 3 and (marker_hits >= 1 or repeated_promotional_terms >= 2))
        or (suspicious_prefix and family_hits >= 2 and repeated_promotional_terms >= 2)
        or navigation_density >= 7
        or (navigation_density >= 4 and (suspicious_domain or gambling_hits >= 1))
        or (suspicious_domain and gambling_hits >= 1)
        or gambling_hits >= 3
        or disguised_gambling_brand
        or (synthetic_cta and gambling_hits >= 1)
    )


def _topic_reference_block_reason(
    item: dict[str, Any],
    channel_terms: list[str],
) -> str:
    """Return a hard-rejection reason for vertical landing pages outside the channel scope."""
    channel_text = clean_text(" ".join(channel_terms)).lower()
    if any(term.lower() in channel_text for term in _REAL_ESTATE_CHANNEL_TERMS):
        return ""

    text = clean_text(
        f"{item.get('title', '')} {item.get('snippet', '')} {item.get('source', '')} {item.get('url', '')}"
    ).lower()
    if not text:
        return ""
    if _looks_like_seo_content_farm(text):
        return "SEO拼接页或软件下载站，不是可核验的新闻来源"
    hard_hits = [term for term in _REAL_ESTATE_LISTING_MARKERS if term.lower() in text]
    soft_hits = [term for term in _REAL_ESTATE_SOFT_MARKERS if term.lower() in text]
    landing_page_signals = sum(
        1
        for marker in ("欢迎您", "官方首页", "详情", "咨询", "订阅", "价格", "地址", "电话")
        if marker.lower() in text
    )
    if hard_hits or (len(set(soft_hits)) >= 3 and landing_page_signals >= 1):
        return "房地产楼盘营销页与当前频道无关"
    return ""


def filter_current_news_references_for_channel(
    references: list[dict[str, Any]],
    channel_terms: list[str],
) -> list[dict[str, Any]]:
    target = clean_text(" ".join(channel_terms))
    if not target:
        return references
    ranked: list[tuple[int, dict[str, Any]]] = []
    for item in references:
        block_reason = _topic_reference_block_reason(item, channel_terms)
        if block_reason:
            continue
        source = clean_text(f"{item.get('title', '')} {item.get('snippet', '')}")
        direct_hits: list[str] = []
        for raw_term in channel_terms:
            term = clean_text(raw_term)
            if len(term) < 2:
                continue
            if re.fullmatch(r"[A-Za-z0-9.+#-]+", term):
                matched = bool(re.search(rf"(?<![A-Za-z0-9]){re.escape(term)}(?![A-Za-z0-9])", source, flags=re.IGNORECASE))
            else:
                matched = term.lower() in source.lower()
            if matched:
                direct_hits.append(term)
        score = max(
            source_information_match_score(source, target),
            min(100, len(direct_hits) * 24),
        )
        if score >= 18:
            ranked.append((score, {**item, "channel_term_hits": direct_hits[:6]}))
    ranked.sort(
        key=lambda pair: (
            -pair[0],
            int(pair[1].get("age_days")) if pair[1].get("age_days") is not None else 99999,
        )
    )
    return [{**item, "channel_relevance_score": score} for score, item in ranked]


def _clean_selected_topic_queue(raw_topics: Any) -> list[dict[str, Any]]:
    if not isinstance(raw_topics, list):
        return []
    queue: list[dict[str, Any]] = []
    for item in raw_topics:
        if not isinstance(item, dict):
            continue
        title = clean_text(str(item.get("title") or item.get("topic") or ""))
        if not title:
            continue
        try:
            score = float(item.get("score") or 4.0)
        except (ValueError, TypeError):
            score = 4.0
        queue.append(
            {
                "title": title[:80],
                "brief": clean_text(str(item.get("brief") or item.get("angle") or item.get("summary") or "")),
                "why": clean_text(str(item.get("why") or item.get("reason") or item.get("value") or "")),
                "search_query": clean_text(str(item.get("search_query") or item.get("query") or title)),
                "target_duration": clean_text(str(item.get("target_duration") or item.get("duration") or "按信息量自适应")),
                "score": max(0.0, min(5.0, score)),
                "rank_score": max(0.0, min(5.0, score)),
                "source": clean_text(str(item.get("source") or "selected")),
            }
        )
    return queue[:5]


def _fallback_topic_candidates(template: dict[str, Any], existing_topics: list[str]) -> list[dict[str, Any]]:
    brand = clean_text(str(template.get("brand_name") or template.get("name") or template.get("key") or "本频道"))
    prompt_blob = clean_text(str(template.get("prompt") or ""))
    keywords = _channel_topic_keywords(template)
    base = keywords[0] if keywords else brand
    seeds = [
        {
            "title": f"{base}里最容易被忽略的一个坑",
            "brief": "从用户最容易误判的细节切入，做成能直接提醒观众的短视频选题。",
            "why": "有痛点、有提醒价值，也适合做封面钩子。",
        },
        {
            "title": f"{brand}今天最值得讲的一件小事",
            "brief": "围绕频道人设，把近期可讨论的小切口讲成一条完整因果线。",
            "why": "适合保持频道连续更新，不依赖宏大题目。",
        },
        {
            "title": f"很多人以为懂了{base}，其实第一步就错了",
            "brief": "用反常识开头，先拆误区，再给具体判断方法。",
            "why": "标题冲突感强，利于短视频开场留人。",
        },
    ]
    if any(word in prompt_blob for word in ["爸妈", "老人", "中老年", "养老", "客服", "诈骗"]):
        seeds = [
            {
                "title": "爸妈接到“客服扣费电话”，先别急着操作",
                "brief": "围绕老人接到扣费、会员、屏幕共享等电话时的真实反应，拆出正确处理顺序。",
                "why": "强现实痛点，家庭场景明确，容易引发转发。",
            },
            {
                "title": "免费服务突然要你转账，最该先核实什么",
                "brief": "用一个生活化案例，把诈骗话术拆成几个可判断信号。",
                "why": "能给观众可执行的判断方法，适合做系列。",
            },
            {
                "title": "验证码不是数字，是钱袋子的钥匙",
                "brief": "把常见验证码骗局讲成一个有画面感的安全提醒。",
                "why": "比泛泛提醒更形象，封面钩子也更直接。",
            },
        ]
    elif any(word in prompt_blob for word in ["科技", "AI", "华为", "手机", "智能"]):
        seeds = [
            {
                "title": "新功能看着很炫，真正改变体验的是哪一步",
                "brief": "围绕科技产品的新功能，从用户实际场景拆出真正价值。",
                "why": "能避开参数堆砌，讲成用户能听懂的场景。",
            },
            {
                "title": "大家都在问值不值，其实该先看这三个场景",
                "brief": "用三个生活场景判断一个智能产品到底适不适合普通人。",
                "why": "具备消费决策价值，评论区容易讨论。",
            },
            {
                "title": "别只看发布会，真正的差别藏在日常使用里",
                "brief": "把发布会卖点翻译成普通用户的一天，判断是不是噱头。",
                "why": "符合科技频道连续产出的稳定结构。",
            },
        ]
    return _normalize_topic_candidates([{**item, "score": 4.0, "source": "fallback"} for item in seeds], existing_topics)


def _topic_mining_focuses(template: dict[str, Any], user_prompt: str, search_scope: str) -> list[str]:
    """Build a few focused searches instead of one query containing the whole channel profile."""
    requested = clean_text(user_prompt)
    scope = clean_text(search_scope)
    if requested:
        compact = re.sub(
            r"(?:最近|近)\s*(?:一|1|7)\s*(?:周|天)|普通人(?:能)?直接感知的|优先|重点|请关注|关注|相关的|方面的",
            " ",
            requested,
        )
        clauses = [clean_text(item) for item in re.split(r"[，,；;。\n]+", compact) if clean_text(item)]
        base = clauses[0] if clauses else requested
        base = re.sub(r"(?:最新|近期|新)?(?:变化|进展|动态|消息)$", "", base).strip() or base
        modifiers = [
            token for token in ("价格", "费用", "功能", "使用成本", "隐私", "政策", "体验", "安全", "效率")
            if token in requested
        ]
        parts = [clean_text(f"{base} {modifier}") for modifier in modifiers[:3]] or [base[:32]]
    else:
        hint = clean_text(str(template.get("topic_mining_hint") or ""))
        parts = [clean_text(item) for item in re.split(r"[、，,；;|/\n]+", hint) if clean_text(item)]
        if not parts:
            parts = _channel_topic_keywords(template)[:6]
    if scope and scope.lower() not in {"general", "auto", "news"}:
        parts.insert(0, clean_text(f"{requested} {scope}" if requested else scope))
    return dedupe_clauses(parts)[:4]


def _mine_topic_reference_pool(
    template: dict[str, Any],
    user_prompt: str,
    search_scope: str,
    today_label: str,
) -> tuple[list[dict[str, Any]], list[str]]:
    focuses = _topic_mining_focuses(template, user_prompt, search_scope)
    queries = [f"{today_label} {focus} 最新进展 发布 更新 影响" for focus in focuses]
    if not queries:
        queries = [f"{today_label} {template.get('name') or template.get('key') or ''} 最新进展"]
    with ThreadPoolExecutor(max_workers=min(4, len(queries))) as executor:
        batches = list(executor.map(lambda item: search_current_news(item, 6), queries))
    references = dedupe_references([item for batch in batches for item in batch])
    channel_terms = dedupe_clauses([*focuses, *_channel_topic_keywords(template)[:5]])
    filtered = filter_current_news_references_for_channel(references, channel_terms)
    # Channel filtering is a hard boundary. Falling back to the unfiltered search
    # pool turns fresh landing pages from unrelated verticals into topic candidates.
    result = filtered if channel_terms else references
    if clean_text(user_prompt):
        # An explicit mining direction is stricter than the channel's broad topic
        # vocabulary. A page that merely says "AI" must not pass a request for
        # "汽车", "手机" or another concrete direction.
        requested_focuses = [clean_text(item) for item in focuses if clean_text(item)]
        direction_matched: list[dict[str, Any]] = []
        for item in result:
            source_text = clean_text(f"{item.get('title', '')} {item.get('snippet', '')}")
            matched = any(
                focus.lower() in source_text.lower()
                or source_information_match_score(source_text, focus) >= 28
                for focus in requested_focuses
            )
            if matched:
                direction_matched.append(item)
        result = direction_matched
        intent_terms = [
            term for term in ("价格", "费用", "功能", "使用成本", "成本", "隐私", "政策", "体验", "安全", "效率")
            if term in clean_text(user_prompt)
        ]
        if intent_terms:
            result = [
                item for item in result
                if any(term in clean_text(f"{item.get('title', '')} {item.get('snippet', '')}") for term in intent_terms)
            ]
    return result[:18], queries


def _topic_specificity_score(title: str, brief: str) -> float:
    source = clean_text(f"{title} {brief}")
    concrete_markers = (
        "发布", "上线", "更新", "降价", "涨价", "召回", "处罚", "测试", "实测", "关闭", "开放",
        "调整", "增长", "下降", "宣布", "报告", "调查", "版本", "功能", "政策", "费用", "价格",
    )
    score = 0.25
    if re.search(r"\d", source):
        score += 0.25
    if re.search(r"[A-Za-z][A-Za-z0-9.+-]{1,}", source):
        score += 0.2
    if any(marker in source for marker in concrete_markers):
        score += 0.3
    return round(min(1.0, score), 3)


def _topic_visual_score(title: str, brief: str) -> float:
    source = clean_text(f"{title} {brief}")
    markers = (
        "手机", "电脑", "汽车", "芯片", "屏幕", "设备", "账单", "价格", "按钮", "页面", "门店",
        "工厂", "办公室", "实验", "测试", "对比", "前后", "用户", "产品", "数据", "报告",
    )
    return round(min(1.0, 0.25 + sum(0.13 for marker in markers if marker in source)), 3)


def _select_diverse_topic_candidates(candidates: list[dict[str, Any]], desired_count: int) -> list[dict[str, Any]]:
    selected: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    for candidate in candidates:
        title = clean_text(str(candidate.get("title") or ""))
        similarity = max(
            (overlap_score(extract_tokens(title), clean_text(str(item.get("title") or ""))) for item in selected),
            default=0.0,
        )
        if similarity >= 0.62:
            deferred.append({**candidate, "candidate_similarity": round(similarity, 3)})
            continue
        selected.append(candidate)
        if len(selected) >= desired_count:
            return selected
    for candidate in deferred:
        selected.append(candidate)
        if len(selected) >= desired_count:
            break
    return selected


def mine_channel_topic(
    template: dict[str, Any],
    tavily_topic: str = "general",
    user_prompt: str = "",
    desired_count: int = 6,
) -> dict[str, Any]:
    template_key = clean_text(str(template.get("key") or ""))
    existing_projects = storage.projects_for_template(template_key) if template_key else []
    existing_topics = [clean_text(str(item.get("topic_name") or "")) for item in existing_projects[:30]]
    keywords = _channel_topic_keywords(template)
    brand = clean_text(str(template.get("brand_name") or template.get("name") or template_key or "本频道"))
    user_prompt = clean_text(user_prompt)
    desired_count = max(1, min(int(desired_count or 6), 12))
    prompt_hint = user_prompt[:240]
    channel_profile = channel_profile_text(template)
    expects_chinese = len(re.findall(r"[\u4e00-\u9fff]", f"{brand} {channel_profile}")) >= 5
    learning = channel_learning_prompt_block({"id": 0, "template": template_key}, template)
    today_label = datetime.now().astimezone().strftime("%Y年%m月%d日")
    search_scope = "" if clean_text(tavily_topic).lower() in {"", "general", "auto"} else clean_text(tavily_topic)
    references, seed_queries = _mine_topic_reference_pool(template, prompt_hint, search_scope, today_label)
    candidate_channel_terms = dedupe_clauses(
        [brand, prompt_hint, search_scope, *keywords[:8], clean_text(str(template.get("topic_mining_hint") or ""))]
    )
    query = seed_queries[0] if seed_queries else " ".join([today_label, prompt_hint, search_scope, "最新进展"]).strip()
    if not references and not prompt_hint:
        references = dedupe_references(
            [item for seed_query in seed_queries[:2] for item in search_duckduckgo(seed_query, 6)]
        )[:12]

    candidates: list[dict[str, Any]] = []
    env = runtime_env()
    api_key = clean_text(env.get("DEEPSEEK_API_KEY", ""))
    if api_key and OpenAI is not None:
        base_url = clean_text(env.get("DEEPSEEK_BASE_URL", "")) or "https://api.deepseek.com"
        model = clean_text(env.get("DEEPSEEK_MODEL", "")) or "deepseek-v4-flash"
        thinking_type = clean_text(env.get("DEEPSEEK_THINKING_TYPE", "")) or "enabled"
        reasoning_effort = clean_text(env.get("DEEPSEEK_REASONING_EFFORT", "")) or "high"
        refs_block = format_reference_block("可参考的公开资料：", references[:8])
        user_prompt_block = f"\n用户额外提示词（必须优先满足）：\n{prompt_hint}\n" if prompt_hint else "\n用户额外提示词：无\n"
        prompt = f"""
你是一个短视频频道的自动选题导演，请严格根据当前频道 prompt.md 挖掘本频道可连续生产的视频主题。

要求：
1. 选题必须服从频道人设、语气、受众、封面风格和内容结构，不能生成通用科普腔。
2. 选题要避开历史主题，优先挑有现实痛点、画面感、传播钩子、可查资料支撑的题。
3. 返回严格 JSON，不要 Markdown，不要解释。
4. 严格给 {desired_count} 个候选，每个候选包含 title、brief、why、search_query、target_duration、score。
5. 用户输入的是“挖题范围/方向”，不是要求把输入原样当标题。每个候选都要在该范围内形成不同的具体事件、冲突、对象或决策角度。
6. title 不超过 32 个字，brief 不超过 90 个字，why 不超过 55 个字，search_query 不超过 45 个字，避免输出被截断。
7. 今天是 {today_label}。候选必须优先来自近7天资料，近7天不足时才允许使用近30天资料。
8. 必须区分“网页发布日期”和“事件发生时间”。近期文章回顾多年前事件不是最新新闻，避免包装成刚发生。
9. 每个候选至少要能被下方两条近期资料共同支撑；只有一条来源、发布日期未知或没有新进展的题，score 不得超过 3 分。
10. title 和 brief 要明确写出本次新进展，不要只讲一个长期存在的旧问题。
11. 同一事件、同一公司或同一结论最多占 2 个候选；候选之间要覆盖产品、政策、技术、用户成本、使用体验或行业变化中的至少 4 类，禁止把一条新闻改写成多个相似标题。

频道信息：
- key: {template_key}
- name: {template.get("name") or ""}
- brand_name: {brand}
- mode: {template.get("mode") or "video"}
- release_tags: {template.get("release_tags") or ""}
- cover_style: {template.get("cover_style") or ""}
- target_audience: {template.get("target_audience") or ""}
- channel_voice: {template.get("channel_voice") or ""}
- visual_strategy: {template.get("visual_strategy") or ""}
- forbidden_rules: {template.get("forbidden_rules") or ""}
- interaction_goal: {template.get("interaction_goal") or ""}
- topic_mining_hint: {template.get("topic_mining_hint") or ""}

频道中枢：
{channel_profile or "未填写结构化频道中枢，以 prompt.md 为准。"}

{learning}

频道 prompt.md：
{str(template.get("prompt") or "")[:5000]}

历史主题：
{json.dumps(existing_topics[:30], ensure_ascii=False)}

{user_prompt_block}

{refs_block}

请返回：
{{
  "candidates": [
    {{
      "title": "短而有钩子的主题名",
      "brief": "本期切入角度和素材组织方式",
      "why": "为什么适合这个频道",
      "search_query": "后续查资料用的搜索词",
      "target_duration": "按信息量自适应",
      "score": 4.5
    }}
  ]
}}
""".strip()
        extra_body: dict[str, Any] = {"reasoning_effort": reasoning_effort}
        if thinking_type in {"enabled", "disabled"}:
            extra_body["thinking"] = {"type": thinking_type}
        try:
            client = OpenAI(api_key=api_key, base_url=base_url, timeout=90.0)
            response = client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": "你只输出严格 JSON。"},
                    {"role": "user", "content": prompt},
                ],
                temperature=0.85,
                max_tokens=max(5200, desired_count * 850),
                extra_body=extra_body,
            )
            raw = message_content_to_text(response.choices[0].message.content if response.choices else "")
            payload = _safe_json_from_text(raw)
            if not isinstance(payload.get("candidates"), list):
                recovered = _recover_truncated_json_list(raw, "candidates")
                if recovered:
                    payload = {"candidates": recovered}
            candidates = _normalize_topic_candidates(payload.get("candidates"), existing_topics)
        except (ValueError, KeyError, TypeError):
            candidates = []

    if expects_chinese:
        candidates = [
            item for item in candidates
            if len(re.findall(r"[\u4e00-\u9fff]", clean_text(str(item.get("title") or "")))) >= 3
        ]

    if candidates and references:
        candidates = apply_current_news_candidate_scores(candidates, references, candidate_channel_terms)
        if not prompt_hint and not any(int(item.get("news_evidence_count") or 0) >= 1 for item in candidates):
            candidates = []

    if not candidates and not prompt_hint and references:
        candidates = _normalize_topic_candidates(
            [
                {
                    "title": re.split(r"\s+[-|｜]\s+", clean_text(str(item.get("title") or "")), maxsplit=1)[0][:80],
                    "brief": clean_text(str(item.get("snippet") or "")),
                    "why": "来自近7天或近30天的公开报道，具备明确发布日期，可继续交叉核实。",
                    "search_query": clean_text(str(item.get("title") or query)),
                    "target_duration": "按信息量自适应",
                    "score": 4.0,
                    "source": "current_news",
                }
                for item in references[:6]
                if clean_text(str(item.get("title") or ""))
                and (not expects_chinese or len(re.findall(r"[\u4e00-\u9fff]", str(item.get("title") or ""))) >= 3)
            ],
            existing_topics,
        )
        candidates = apply_current_news_candidate_scores(candidates, references, candidate_channel_terms)

    if prompt_hint and references and len(candidates) < desired_count:
        expanded = _expand_topic_direction_candidates(
            direction=prompt_hint,
            brand=brand,
            references=references,
            existing_topics=existing_topics,
            desired_count=desired_count,
        )
        existing_titles = {
            re.sub(r"\W+", "", clean_text(str(item.get("title") or "")).lower())
            for item in candidates
        }
        for item in expanded:
            key = re.sub(r"\W+", "", clean_text(str(item.get("title") or "")).lower())
            if key and key not in existing_titles:
                candidates.append(item)
                existing_titles.add(key)
            if len(candidates) >= desired_count:
                break

    if candidates and references:
        candidates = apply_current_news_candidate_scores(candidates, references, candidate_channel_terms)
    candidates = _select_diverse_topic_candidates(candidates, desired_count)

    if not candidates and not prompt_hint:
        candidates = _fallback_topic_candidates(template, existing_topics)

    if not candidates and not prompt_hint:
        title = f"{brand}自动选题 {int(storage.now_ts())}"
        candidates = _normalize_topic_candidates([{"title": title, "score": 3.5, "source": "fallback"}], existing_topics)

    picked = candidates[0] if candidates else {}
    search_query = clean_text(str(picked.get("search_query") or picked.get("title") or query))
    topic_refs = (search_current_news(f"{today_label} {search_query}", 8) if picked else []) or references
    if picked and not topic_refs:
        topic_refs = search_duckduckgo(f"{today_label} 最新 {search_query}", 6)
    return {
        "picked": picked,
        "candidates": candidates,
        "references": topic_refs,
        "seed_query": query,
        "seed_queries": seed_queries,
        "searched_query": search_query,
        "existing_topics": existing_topics[:30],
        "keywords": keywords,
        "user_prompt": user_prompt,
        "current_news_mode": True,
        "freshness_policy_version": NEWS_FRESHNESS_POLICY_VERSION,
        "freshness_window": "7d_then_30d",
        "quality_summary": {
            "requested_count": desired_count,
            "returned_count": len(candidates),
            "strong_count": sum(1 for item in candidates if item.get("readiness") == "strong"),
            "review_count": sum(1 for item in candidates if item.get("readiness") == "review"),
            "reference_count": len(references),
            "message": (
                "本轮近期资料不足，请缩小方向或稍后重试。"
                if not candidates
                else ("候选数量少于目标，只保留有近期依据的选题。" if len(candidates) < desired_count else "已完成近期事件筛选。")
            ),
        },
        "provider": (
            "deepseek"
            if any(item.get("source") == "deepseek" for item in candidates)
            else (candidates[0].get("source", "fallback") if candidates else "research")
        ),
    }


def selected_topic_payload(
    selected_topic: dict[str, Any],
    template: dict[str, Any],
    tavily_topic: str = "general",
    user_prompt: str = "",
    queued_topics: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    template_key = clean_text(str(template.get("key") or ""))
    existing_projects = storage.projects_for_template(template_key) if template_key else []
    existing_topics = [clean_text(str(item.get("topic_name") or "")) for item in existing_projects[:30]]
    normalized = _clean_selected_topic_queue([selected_topic])
    picked = normalized[0] if normalized else {
        "title": clean_text(str(selected_topic.get("title") or selected_topic.get("topic") or f"{template_key} 自动主题")),
        "brief": clean_text(str(selected_topic.get("brief") or "")),
        "why": clean_text(str(selected_topic.get("why") or "")),
        "search_query": clean_text(str(selected_topic.get("search_query") or selected_topic.get("title") or template_key)),
        "target_duration": clean_text(str(selected_topic.get("target_duration") or "按信息量自适应")),
        "score": 4.0,
        "rank_score": 4.0,
        "source": "selected",
    }
    all_candidates = _clean_selected_topic_queue(queued_topics or [selected_topic])
    search_query = clean_text(str(picked.get("search_query") or picked.get("title") or template_key))
    today_label = datetime.now().astimezone().strftime("%Y年%m月%d日")
    references = search_current_news(f"{today_label} {search_query}", 8)
    if not references:
        references = search_duckduckgo(f"{today_label} 最新 {search_query}", 6)
    return {
        "picked": picked,
        "candidates": [picked],
        "queued_topics": all_candidates or [picked],
        "references": references,
        "seed_query": search_query,
        "searched_query": search_query,
        "existing_topics": existing_topics[:30],
        "keywords": _channel_topic_keywords(template),
        "user_prompt": clean_text(user_prompt),
        "current_news_mode": True,
        "freshness_policy_version": NEWS_FRESHNESS_POLICY_VERSION,
        "freshness_window": "7d_then_30d",
        "provider": picked.get("source") or "selected",
        "selected_by_user": True,
        "locked_topic_title": clean_text(str(picked.get("title") or "")),
    }


def auto_topic_reference_line(item: dict[str, Any]) -> str:
    freshness = item.get("freshness") if isinstance(item.get("freshness"), dict) else reference_freshness(item)
    published_date = clean_text(str(freshness.get("published_date") or item.get("published_date") or "未知日期"))
    status = clean_text(str(freshness.get("status") or item.get("freshness_status") or "unknown"))
    return (
        f"- [{published_date} / {status}] {item.get('title') or '资料'}："
        f"{item.get('snippet') or ''} {item.get('url') or ''}"
    ).strip()


