def selected_topic_alignment_score(topic_title: str, content: str) -> float:
    tokens = extract_tokens(topic_title)
    if not tokens:
        return 1.0
    source = content_without_image_prompts(content or "")[:7000]
    return round(overlap_score(tokens, source), 3)


def production_job_failure_reason(job: dict[str, Any]) -> str:
    """Expose the child job's actionable blocker instead of stale asset steps."""
    error = clean_text(str(job.get("error") or job.get("phase_message") or "生产任务未完成"))
    blocker = ""
    for line in reversed(str(job.get("log") or "").splitlines()):
        cleaned = clean_text(line)
        if "[gate] 阻止：" in cleaned:
            blocker = cleaned.split("[gate] 阻止：", 1)[-1].strip()
            break
    if blocker and blocker not in error:
        return f"{error} 具体阻断：{blocker}"
    return error


class AutoVideoRuntime:
    def __init__(self) -> None:
        self.task: asyncio.Task[None] | None = None
        self.state: dict[str, Any] | None = None

    def latest(self) -> dict[str, Any] | None:
        payload = self.state or storage.read_json(AUTO_VIDEO_STATE_FILE, None)
        if not isinstance(payload, dict):
            return None
        payload = self._reconcile_project_job(payload)
        if payload.get("running") and (not self.task or self.task.done()):
            if payload.get("child_job_running"):
                self.state = payload
                return payload
            if (
                payload.get("auto_confirm_images")
                and payload.get("project_id")
                and clean_text(str(payload.get("stage") or "")) == "produce"
            ):
                pending = dict(payload)
                pending["recovery_pending"] = True
                pending["phase_message"] = "检测到服务重启，正在自动恢复未完成生产步骤。"
                self.state = pending
                self._save()
                return pending
            recovered = dict(payload)
            recovered["running"] = False
            recovered["finished_at"] = recovered.get("finished_at") or storage.now_ts()
            recovered["status"] = "interrupted" if recovered.get("status") == "running" else recovered.get("status", "interrupted")
            log_text = str(recovered.get("log") or "").rstrip()
            suffix = "[auto] 上一次自动成片任务在服务重启前中断，请重新开始。"
            recovered["log"] = f"{log_text}\n{suffix}".strip() if log_text else suffix
            self.state = recovered
            self._save()
            return recovered
        return payload

    def _reconcile_project_job(self, payload: dict[str, Any]) -> dict[str, Any]:
        project_id = int(payload.get("project_id") or 0)
        if not project_id or not payload.get("auto_confirm_images"):
            return payload
        job = storage.load_latest_job(project_id) or {}
        if not isinstance(job, dict) or not job:
            return payload
        reconciled = dict(payload)
        changed = False
        if reconciled.pop("child_job_running", None) is not None:
            changed = True
        if job.get("running") and clean_text(str(job.get("status") or "")) == "running":
            if not reconciled.get("running") or clean_text(str(reconciled.get("status") or "")) != "running":
                reconciled["running"] = True
                reconciled["status"] = "running"
                reconciled["finished_at"] = None
                reconciled["error"] = ""
                reconciled["stage"] = "produce"
                changed = True
            reconciled["child_job_id"] = clean_text(str(job.get("id") or ""))
            reconciled["child_job_running"] = True
            reconciled["phase_message"] = clean_text(
                str(job.get("phase_message") or "全自动生产任务仍在后台运行。")
            )
            reconciled["runtime_health"] = job_runtime_health(job)
            changed = True
        elif clean_text(str(job.get("status") or "")) == "succeeded":
            final_video_path = storage.project_file(project_id, "releases/final-video.mp4")
            queue_index = int(reconciled.get("queue_index") or 0)
            queue_total = max(1, int(reconciled.get("queue_total") or reconciled.get("count") or 1))
            if final_video_path.exists() and queue_index >= queue_total:
                reconciled["running"] = False
                reconciled["status"] = "succeeded"
                reconciled["finished_at"] = reconciled.get("finished_at") or storage.now_ts()
                reconciled["error"] = ""
                reconciled["phase_message"] = "自动挖题成片已完成。"
                reconciled["result"] = self._project_result(project_id, job)
                changed = True
        elif clean_text(str(job.get("status") or "")) in {"failed", "cancelled", "interrupted"}:
            # Do not leave a stale "active" heartbeat on an auto task after its child job
            # has already reached a terminal state. The UI otherwise looks permanently stuck.
            child_status = clean_text(str(job.get("status") or "failed"))
            reconciled["running"] = False
            reconciled["status"] = child_status
            reconciled["finished_at"] = reconciled.get("finished_at") or job.get("finished_at") or storage.now_ts()
            reconciled["child_job_id"] = clean_text(str(job.get("id") or ""))
            reconciled["child_job_running"] = False
            reconciled["error"] = production_job_failure_reason(job) if child_status == "failed" else clean_text(str(job.get("error") or ""))
            reconciled["phase_message"] = clean_text(
                str(job.get("phase_message") or reconciled.get("error") or "生产任务已结束。")
            )
            reconciled["runtime_health"] = job_runtime_health(job)
            changed = True
        if changed:
            self.state = reconciled
            self._save()
        return reconciled

    def _project_result(self, project_id: int, job: dict[str, Any]) -> dict[str, Any]:
        project = storage.get_project(project_id)
        files = {item["relative_path"]: item for item in storage.list_project_files(project_id)}
        return {
            "project_id": project_id,
            "topic": clean_text(str(project.get("topic_name") or (self.state.get("topic") if self.state else ""))),
            "project_root": str(storage.project_dir(project_id)),
            "final_video": files.get("releases/final-video.mp4"),
            "latest_job": job,
        }

    async def resume_on_startup(self) -> dict[str, Any] | None:
        payload = self.state or storage.read_json(AUTO_VIDEO_STATE_FILE, None)
        if not isinstance(payload, dict):
            return None
        self.state = payload
        payload = self._reconcile_project_job(payload)
        project_id = int(payload.get("project_id") or 0)
        stage = clean_text(str(payload.get("stage") or ""))
        status = clean_text(str(payload.get("status") or ""))
        full_auto = bool(payload.get("auto_confirm_images"))
        if (
            not full_auto
            or not project_id
            or stage != "produce"
            # A failed run is terminal. Restarting the service must not silently
            # launch the same deterministic failing step again; users can still
            # explicitly continue after the blocker has been repaired.
            or status in {"succeeded", "cancelled", "failed"}
            or (self.task and not self.task.done())
        ):
            return payload
        restart_attempts = int(payload.get("restart_resume_attempts") or 0)
        if status == "failed" and restart_attempts >= 3:
            return payload
        self.state["status"] = "running"
        self.state["running"] = True
        self.state["finished_at"] = None
        self.state["error"] = ""
        self.state["recovery_pending"] = False
        self.state["restart_resume_attempts"] = restart_attempts + 1
        self.state["phase_message"] = "服务已恢复，正在自动续跑未完成生产步骤。"
        self._log("[auto] 检测到上次全自动任务未完成，正在按资产状态自动续跑")
        self.task = asyncio.create_task(self._resume_production_after_restart())
        self._save()
        return self.state

    async def _resume_production_after_restart(self) -> None:
        assert self.state is not None
        project_id = int(self.state.get("project_id") or 0)
        try:
            if not project_id:
                raise RuntimeError("全自动续跑缺少项目编号。")
            save_image_review_status(project_id, required=False, confirmed=False)
            runtime = JobRuntime()
            runtime.latest(project_id, force_recover_orphan=True)
            completed_job: dict[str, Any] = storage.load_latest_job(project_id) or {}
            final_video_path = storage.project_file(project_id, "releases/final-video.mp4")
            recovery_signatures: set[str] = set()
            last_failure = ""
            for round_index in range(1, 4):
                if clean_text(str(completed_job.get("status") or "")) == "succeeded" and final_video_path.exists():
                    break
                plan = production_resume_plan(project_id)
                resume_steps = [clean_text(str(item)) for item in plan.get("recommended_steps", []) if clean_text(str(item))]
                if not resume_steps:
                    if final_video_path.exists():
                        break
                    resume_steps = ["video"]
                signature = "|".join(resume_steps)
                if signature in recovery_signatures and round_index >= 3:
                    detail = last_failure or "生产任务没有给出可执行的失败原因。"
                    raise RuntimeError(f"{detail} 自动修复未能推进，请先处理上述真实阻断项。")
                recovery_signatures.add(signature)
                self.state["auto_repair_round"] = round_index
                self.state["phase_message"] = f"第 {round_index} 轮自动修复：{'、'.join(resume_steps)}"
                self._log(f"[auto] 第 {round_index} 轮自动续跑：{' -> '.join(resume_steps)}")
                snapshot = await runtime.start(
                    storage.get_project(project_id),
                    resume_steps,
                    allow_incomplete_video=False,
                    auto_recover=True,
                    origin="auto_video",
                )
                self.state["child_job_id"] = snapshot.get("id")
                self._save()
                job_task = runtime.tasks.get(str(snapshot.get("id") or ""), {}).get("task")
                if job_task:
                    await job_task
                completed_job = storage.load_latest_job(project_id) or {}
                if clean_text(str(completed_job.get("status") or "")) == "succeeded" and final_video_path.exists():
                    break
                failure = production_job_failure_reason(completed_job)
                last_failure = failure
                self._log(f"[auto] 本轮未完成，系统将重新计算续跑步骤：{failure}")
            else:
                raise RuntimeError("全自动生产连续修复 3 轮后仍未生成成片。")

            if not final_video_path.exists():
                raise RuntimeError("生产步骤已结束，但没有生成 final-video.mp4。")
            self.state["result"] = self._project_result(project_id, completed_job)
            queue_index = int(self.state.get("queue_index") or 0)
            queue_total = max(1, int(self.state.get("queue_total") or self.state.get("count") or 1))
            if queue_index < queue_total:
                await self._run(
                    clean_text(str(self.state.get("template_key") or "")),
                    queue_total,
                    clean_text(str(self.state.get("tavily_topic") or "general")) or "general",
                    clean_text(str(self.state.get("mining_prompt") or "")),
                    list(self.state.get("steps") or []),
                    True,
                    list(self.state.get("queued_topics") or []),
                    start_index=queue_index + 1,
                )
                return
            self.state["status"] = "succeeded"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self.state["phase_message"] = "自动挖题成片已完成。"
            self._log("[auto] 服务重启后的自动续跑已完成")
            self._save()
        except asyncio.CancelledError:
            self.state["status"] = "cancelled"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self._log("[auto] 用户已取消自动续跑任务")
            self._save()
            raise
        except Exception as exc:
            self.state["status"] = "failed"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self.state["error"] = user_facing_error(exc)
            self.state["phase_message"] = f"全自动续跑失败：{user_facing_error(exc)}"
            self._log(f"[auto] 自动续跑失败：{user_facing_error(exc)}")
            self._save()

    async def start(
        self,
        template_key: str,
        *,
        count: int = 1,
        tavily_topic: str = "general",
        mining_prompt: str = "",
        steps: list[str] | None = None,
        auto_confirm_images: bool = True,
        selected_topics: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        if self.task and not self.task.done():
            raise RuntimeError("已有自动挖题成片任务正在运行，请等待完成或先取消。")
        template = storage.get_template(template_key)
        selected_queue = _clean_selected_topic_queue(selected_topics or [])
        safe_count = len(selected_queue) if selected_queue else max(1, min(int(count or 1), 5))
        mining_prompt = clean_text(mining_prompt)
        resolved_steps = steps or (
            ["images", "covers", "article"]
            if template.get("mode") == "article"
            else ["audio", "subtitles", "images", "covers", "video"]
        )
        state = _auto_video_state_seed(template_key, safe_count, tavily_topic or "general", resolved_steps, mining_prompt)
        state["auto_confirm_images"] = bool(auto_confirm_images)
        state["queued_topics"] = selected_queue
        state["queue_total"] = safe_count
        self.state = state
        self._save()
        self.task = asyncio.create_task(
            self._run(
                template_key,
                safe_count,
                tavily_topic or "general",
                mining_prompt,
                resolved_steps,
                bool(auto_confirm_images),
                selected_queue,
            )
        )
        return state

    async def cancel(self) -> dict[str, Any]:
        if not self.task or self.task.done():
            return {"already_done": True}
        self.task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await self.task
        return {"already_done": False}

    def _save(self) -> None:
        if not self.state:
            return
        storage.write_json(AUTO_VIDEO_STATE_FILE, self.state)
        project_id = self.state.get("project_id")
        if project_id:
            storage.write_json(storage.project_file(int(project_id), "auto_video.json"), self.state)

    def _log(self, line: str) -> None:
        if not self.state:
            return
        log = str(self.state.get("log") or "").rstrip()
        self.state["log"] = f"{log}\n{line}".strip() if log else line
        self._save()

    def _stage(self, stage: str) -> None:
        if not self.state:
            return
        self.state["stage"] = stage
        self.state["stage_started_at"] = storage.now_ts()
        self._save()

    async def _run(
        self,
        template_key: str,
        count: int,
        tavily_topic: str,
        mining_prompt: str,
        steps: list[str],
        auto_confirm_images: bool,
        selected_topics: list[dict[str, Any]] | None = None,
        start_index: int = 1,
    ) -> None:
        assert self.state is not None
        selected_queue = _clean_selected_topic_queue(selected_topics or [])
        try:
            for index in range(max(1, int(start_index or 1)), count + 1):
                template = storage.get_template(template_key)
                self._stage("mine_topic")
                self.state["queue_index"] = index
                self.state["queue_total"] = count
                self._save()
                self._log(f"[auto] {index}/{count} 正在为频道「{template_key}」准备主题")
                if mining_prompt:
                    self._log(f"[auto] 本次选题提示词：{mining_prompt}")
                if index <= len(selected_queue):
                    selected_topic = selected_queue[index - 1]
                    topic_payload = await asyncio.to_thread(
                        selected_topic_payload,
                        selected_topic,
                        template,
                        tavily_topic,
                        mining_prompt,
                        selected_queue,
                    )
                    self._log(f"[auto] 使用已确认候选：{selected_topic.get('title') or ''}")
                else:
                    topic_payload = await asyncio.to_thread(mine_channel_topic, template, tavily_topic, mining_prompt)
                picked = topic_payload.get("picked") if isinstance(topic_payload.get("picked"), dict) else {}
                topic_title = clean_text(str(picked.get("title") or ""))
                if not topic_title:
                    summary = topic_payload.get("quality_summary") if isinstance(topic_payload.get("quality_summary"), dict) else {}
                    raise RuntimeError(clean_text(str(summary.get("message") or "本轮没有找到有近期依据的候选主题。")))
                self.state["topic"] = topic_title
                self.state["topic_candidates"] = topic_payload.get("candidates", [])[:6]
                self._log(f"[auto] 已选题：{topic_title}")

                self._stage("create_project")
                project = storage.create_project(topic_title, template_key)
                project_id = int(project["id"])
                self.state["project_id"] = project_id
                self.state["created_projects"].append({"id": project_id, "topic_name": topic_title})
                self._save()

                brief = render_auto_topic_brief_v2(topic_payload, template, tavily_topic)
                storage.save_project_settings(
                    project_id,
                    {
                        "tavily_topic": tavily_topic,
                        "auto_topic_prompt": mining_prompt,
                        "current_news_mode": bool(topic_payload.get("current_news_mode", True)),
                        "news_freshness_policy_version": NEWS_FRESHNESS_POLICY_VERSION,
                        "news_freshness_window": clean_text(str(topic_payload.get("freshness_window") or "7d_then_30d")),
                    },
                )
                storage.save_brief(project_id, brief)
                storage.write_json(
                    storage.project_file(project_id, "auto_topic.json"),
                    {
                        "topic": topic_title,
                        "user_prompt": mining_prompt,
                        "payload": topic_payload,
                        "brief_path": str(storage.project_file(project_id, "brief.md")),
                        "created_at": storage.now_ts(),
                    },
                )
                self._log(f"[auto] 已创建项目 #{project_id} 并写入 brief.md")

                self._stage("content")
                self._log("[auto] 正在调用现有 content 生成链路")
                content_runtime = ContentRuntime()
                await content_runtime.start(project, template, brief, tavily_topic)
                content_task = content_runtime.tasks.get(project_id, {}).get("task")
                if content_task:
                    await content_task
                content_state = storage.read_json(storage.project_file(project_id, "content_generate.json"), {})
                if content_state.get("status") != "succeeded":
                    raise RuntimeError(str(content_state.get("error") or content_state.get("fallback_reason") or "content.md 生成失败"))
                self._log(f"[auto] content.md 已生成，文本模型：{content_state.get('provider') or content_state.get('generator_priority') or 'unknown'}")
                if topic_payload.get("selected_by_user"):
                    generated_content = storage.get_content(project_id)
                    alignment = selected_topic_alignment_score(topic_title, generated_content)
                    self._log(f"[auto] 勾选主题贴合度：{alignment:.2f}，锁定主题「{topic_title}」")
                    if alignment < 0.24:
                        raise RuntimeError(
                            f"content.md 明显偏离你勾选的主题「{topic_title}」（贴合度 {alignment:.2f}），已停止后续生产，避免生成错误主题的视频。"
                        )

                if auto_confirm_images:
                    save_image_review_status(project_id, required=False, confirmed=False)
                    self._log("[auto] 全自动模式已关闭图片人工确认门槛")

                self._stage("produce")
                self._log(f"[auto] 开始生产流水线：{' -> '.join(steps)}")
                job_runtime = JobRuntime()
                production_steps = normalize_production_steps(steps)
                production_signatures: set[str] = set()
                job: dict[str, Any] = {}
                last_failure = ""
                for production_round in range(1, 4):
                    signature = "|".join(production_steps)
                    if signature in production_signatures and production_round >= 3:
                        detail = last_failure or "生产任务没有给出可执行的失败原因。"
                        raise RuntimeError(f"{detail} 自动修复未能推进，请先处理上述真实阻断项。")
                    production_signatures.add(signature)
                    self.state["auto_repair_round"] = production_round
                    self.state["phase_message"] = (
                        f"正在生产：{'、'.join(production_steps)}"
                        if production_round == 1
                        else f"第 {production_round} 轮自动补齐：{'、'.join(production_steps)}"
                    )
                    self._save()
                    job_snapshot = await job_runtime.start(
                        storage.get_project(project_id),
                        production_steps,
                        allow_incomplete_video=False,
                        auto_recover=True,
                        origin="auto_video",
                    )
                    self.state["child_job_id"] = job_snapshot.get("id")
                    self._save()
                    job_task = job_runtime.tasks.get(job_snapshot["id"], {}).get("task")
                    if job_task:
                        await job_task
                    job = storage.load_latest_job(project_id) or {}
                    final_video_path = storage.project_file(project_id, "releases/final-video.mp4")
                    if job.get("status") == "succeeded" and (
                        final_video_path.exists() or "video" not in steps
                    ):
                        break
                    last_failure = production_job_failure_reason(job)
                    plan = production_resume_plan(project_id)
                    production_steps = [
                        clean_text(str(item))
                        for item in plan.get("recommended_steps", [])
                        if clean_text(str(item))
                    ]
                    if not production_steps:
                        log_tail = "\n".join(str(job.get("log") or "").splitlines()[-8:])
                        raise RuntimeError(f"生产流水线失败：{log_tail or job.get('status') or 'unknown'}")
                    self._log(
                        f"[auto] 第 {production_round} 轮未完成，已按最新资产重新计算："
                        f"{' -> '.join(production_steps)}；真实原因：{last_failure}"
                    )
                else:
                    raise RuntimeError("全自动生产连续补齐 3 轮后仍未完成。")

                self.state["result"] = self._project_result(project_id, job)
                self._log("[auto] 自动挖题成片完成")

            self.state["status"] = "succeeded"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self._save()
        except asyncio.CancelledError:
            self.state["status"] = "cancelled"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self._log("[auto] 用户已取消自动挖题成片任务")
            self._save()
            raise
        except Exception as exc:
            self.state["status"] = "failed"
            self.state["running"] = False
            self.state["finished_at"] = storage.now_ts()
            self.state["error"] = user_facing_error(exc)
            self._log(f"[auto] 任务失败：{user_facing_error(exc)}")
            self._save()
